CREATE OR REPLACE FUNCTION public.activate_tenant(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    UPDATE tenants
    SET status = 'active',
        suspended_at = NULL,
        suspended_reason = NULL
    WHERE id = p_tenant_id;
    
    -- تسجيل الحدث
    INSERT INTO saas_events (tenant_id, event_type, event_data, actor_type)
    VALUES (p_tenant_id, 'tenant_activated', '{}', 'admin');
    
    RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: activate_white_label(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.activate_white_label(p_agent_id uuid, p_payment_id uuid, p_approved_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_agent RECORD;
    v_payment RECORD;
    v_config_id UUID;
BEGIN
    -- الحصول على الوكيل
    SELECT * INTO v_agent FROM agents WHERE id = p_agent_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'الوكيل غير موجود');
    END IF;
    
    -- الحصول على الدفعة
    SELECT * INTO v_payment FROM white_label_payments WHERE id = p_payment_id AND agent_id = p_agent_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'الدفعة غير موجودة');
    END IF;
    
    IF v_payment.status != 'completed' THEN
        RETURN jsonb_build_object('success', false, 'error', 'الدفعة غير مكتملة');
    END IF;
    
    -- تحديث الوكيل
    UPDATE agents
    SET has_white_label = true,
        white_label_status = 'active',
        white_label_payment_amount = v_payment.amount,
        white_label_payment_date = v_payment.paid_at,
        white_label_payment_reference = v_payment.payment_reference,
        white_label_commission_percent = 50,  -- 50% للوكلاء بـ White Label
        white_label_activated_at = NOW(),
        white_label_expires_at = v_payment.valid_to,
        white_label_approved_at = NOW(),
        white_label_approved_by = p_approved_by,
        commission_percent = 50,  -- تحديث نسبة العمولة الأساسية
        recurring_commission_percent = 50  -- تحديث نسبة العمولة المتكررة
    WHERE id = p_agent_id;
    
    -- إنشاء إعدادات White Label افتراضية
    INSERT INTO white_label_configs (agent_id, brand_name, is_active)
    VALUES (p_agent_id, v_agent.name, true)
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_config_id;
    
    -- تسجيل الحدث
    INSERT INTO agent_events (agent_id, event_type, event_data)
    VALUES (p_agent_id, 'white_label_activated', jsonb_build_object(
        'payment_id', p_payment_id,
        'amount', v_payment.amount,
        'approved_by', p_approved_by
    ));
    
    RETURN jsonb_build_object(
        'success', true,
        'agent_id', p_agent_id,
        'config_id', v_config_id,
        'message', 'تم تفعيل White Label بنجاح'
    );
END;
$$;


--
-- Name: add_bank_account(uuid, character varying, character varying, character varying, character varying, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.add_bank_account(p_company_id uuid, p_bank_name_ar character varying, p_bank_name_en character varying, p_currency character varying DEFAULT 'UAH'::character varying, p_account_number character varying DEFAULT NULL::character varying, p_fop_group character varying DEFAULT NULL::character varying, p_annual_limit numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_bank_group_id UUID;
    v_next_code VARCHAR(10);
    v_new_account_id UUID;
    v_account_type_id UUID;
BEGIN
    -- Get tenant_id
    SELECT tenant_id INTO v_tenant_id 
    FROM companies 
    WHERE id = p_company_id;
    
    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION 'Company not found';
    END IF;
    
    -- Get bank group account (112)
    SELECT id INTO v_bank_group_id
    FROM chart_of_accounts
    WHERE company_id = p_company_id 
      AND account_code = '112'
      AND is_group = true;
    
    IF v_bank_group_id IS NULL THEN
        RAISE EXCEPTION 'Bank group account (112) not found. Please create unified chart first.';
    END IF;
    
    -- Get account type ID
    SELECT id INTO v_account_type_id
    FROM account_types
    WHERE code = 'CURRENT_ASSET';
    
    -- Generate next code (1121, 1122, ...)
    SELECT COALESCE(
        '112' || (MAX(SUBSTRING(account_code FROM 4)::INTEGER) + 1)::TEXT,
        '1121'
    ) INTO v_next_code
    FROM chart_of_accounts
    WHERE company_id = p_company_id 
      AND account_code LIKE '112%'
      AND LENGTH(account_code) = 4;
    
    -- Create new bank account
    INSERT INTO chart_of_accounts (
        tenant_id, company_id, account_code,
        name_ar, name_en,
        account_type_id, parent_id,
        is_group, is_detail, is_bank_account,
        currency, external_code, is_system
    ) VALUES (
        v_tenant_id, p_company_id, v_next_code,
        p_bank_name_ar, p_bank_name_en,
        v_account_type_id, v_bank_group_id,
        false, true, true,
        p_currency, p_account_number, false
    )
    RETURNING id INTO v_new_account_id;
    
    -- Add FOP limit if specified
    IF p_fop_group IS NOT NULL AND p_annual_limit IS NOT NULL THEN
        INSERT INTO bank_account_limits (
            tenant_id, company_id, account_id,
            fop_group, annual_limit,
            last_reset_date
        ) VALUES (
            v_tenant_id, p_company_id, v_new_account_id,
            p_fop_group, p_annual_limit,
            DATE_TRUNC('year', CURRENT_DATE)::DATE
        );
    END IF;
    
    RAISE NOTICE 'Bank account created: % (%) with code %', p_bank_name_ar, p_currency, v_next_code;
    
    RETURN v_new_account_id;
END;
$$;


--
-- Name: add_module_to_plan(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.add_module_to_plan(p_plan_id uuid, p_module_id uuid, p_is_core boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_module_exists BOOLEAN;
BEGIN
    -- التحقق من وجود الموديول
    SELECT EXISTS (
        SELECT 1 FROM system_modules WHERE id = p_module_id
    ) INTO v_module_exists;
    
    IF NOT v_module_exists THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'module_not_found',
            'message', 'الموديول غير موجود'
        );
    END IF;
    
    -- إضافة الموديول
    INSERT INTO plan_modules (plan_id, module_id, is_enabled, is_core)
    VALUES (p_plan_id, p_module_id, true, p_is_core)
    ON CONFLICT (plan_id, module_id) DO UPDATE SET
        is_enabled = true,
        is_core = EXCLUDED.is_core,
        updated_at = NOW();
    
    RETURN jsonb_build_object(
        'success', true,
        'message', 'تمت إضافة الموديول بنجاح'
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'exception',
            'message', SQLERRM
        );
END;
$$;


--
-- Name: add_pending_leave_on_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.add_pending_leave_on_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF NEW.status = 'pending' THEN
        UPDATE leave_balances
        SET pending_days = pending_days + NEW.total_days
        WHERE employee_id = NEW.employee_id
        AND leave_type_id = NEW.leave_type_id
        AND year = EXTRACT(YEAR FROM NEW.start_date);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: add_product_image(uuid, uuid, text, boolean, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.add_product_image(p_tenant_id uuid, p_product_id uuid, p_image_url text, p_is_primary boolean DEFAULT false, p_alt_text text DEFAULT NULL::text, p_display_order integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_images JSONB;
    v_new_image JSONB;
    v_updated_images JSONB;
    v_max_order INT;
BEGIN
    -- 1. الحصول على الصور الحالية
    SELECT COALESCE(images, '[]'::jsonb)
    INTO v_current_images
    FROM products
    WHERE id = p_product_id AND tenant_id = p_tenant_id;
    
    -- 2. تحديد display_order إذا لم يُحدد
    IF p_display_order IS NULL THEN
        SELECT COALESCE(MAX((img->>'display_order')::int), 0) + 1
        INTO v_max_order
        FROM jsonb_array_elements(v_current_images) AS img;
        
        p_display_order := v_max_order;
    END IF;
    
    -- 3. إنشاء كائن الصورة الجديدة
    v_new_image := jsonb_build_object(
        'url', p_image_url,
        'is_primary', p_is_primary,
        'alt_text', COALESCE(p_alt_text, ''),
        'display_order', p_display_order,
        'uploaded_at', NOW()
    );
    
    -- 4. إذا كانت primary، اجعل الصور الأخرى غير primary
    IF p_is_primary THEN
        v_updated_images := (
            SELECT jsonb_agg(
                jsonb_set(img, '{is_primary}', 'false'::jsonb)
            )
            FROM jsonb_array_elements(v_current_images) AS img
        );
        v_current_images := COALESCE(v_updated_images, '[]'::jsonb);
    END IF;
    
    -- 5. إضافة الصورة الجديدة
    v_updated_images := v_current_images || v_new_image;
    
    -- 6. تحديث المنتج
    UPDATE products
    SET images = v_updated_images,
        updated_at = NOW()
    WHERE id = p_product_id AND tenant_id = p_tenant_id;
    
    RETURN v_new_image;
END;
$$;


--
-- Name: add_product_review(uuid, uuid, uuid, uuid, integer, character varying, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.add_product_review(p_tenant_id uuid, p_company_id uuid, p_product_id uuid, p_customer_id uuid, p_rating integer, p_title character varying, p_review_text text, p_order_id uuid DEFAULT NULL::uuid, p_images jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_review_id UUID;
    v_is_verified BOOLEAN := false;
    v_result JSONB;
BEGIN
    -- التحقق من صحة التقييم
    IF p_rating < 1 OR p_rating > 5 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'التقييم يجب أن يكون من 1 إلى 5'
        );
    END IF;
    
    -- التحقق من شراء المنتج
    IF p_order_id IS NOT NULL THEN
        IF EXISTS (
            SELECT 1 FROM order_items oi
            INNER JOIN orders o ON o.id = oi.order_id
            WHERE oi.order_id = p_order_id
              AND oi.product_id = p_product_id
              AND o.customer_id = p_customer_id
              AND o.status IN ('delivered', 'confirmed')
        ) THEN
            v_is_verified := true;
        END IF;
    END IF;
    
    -- إضافة التقييم
    INSERT INTO product_reviews (
        tenant_id, company_id, product_id, customer_id, order_id,
        rating, title, review_text, images,
        is_verified_purchase, status
    )
    VALUES (
        p_tenant_id, p_company_id, p_product_id, p_customer_id, p_order_id,
        p_rating, p_title, p_review_text, p_images,
        v_is_verified, 'pending'
    )
    RETURNING id INTO v_review_id;
    
    -- إرجاع النتيجة
    v_result := jsonb_build_object(
        'success', true,
        'review_id', v_review_id,
        'is_verified_purchase', v_is_verified,
        'status', 'pending',
        'message', 'تم إرسال التقييم بنجاح. سيتم مراجعته قريباً'
    );
    
    RETURN v_result;
END;
$$;


--
-- Name: add_seller_response(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.add_seller_response(p_tenant_id uuid, p_review_id uuid, p_response text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    UPDATE product_reviews
    SET seller_response = p_response,
        seller_response_at = NOW(),
        updated_at = NOW()
    WHERE id = p_review_id
      AND tenant_id = p_tenant_id
      AND status = 'approved';
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'التقييم غير موجود أو غير موافق عليه');
    END IF;
    
    RETURN jsonb_build_object('success', true, 'message', 'تم إضافة الرد');
END;
$$;


--
-- Name: add_to_cart(uuid, uuid, uuid, numeric, uuid, character varying, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.add_to_cart(p_tenant_id uuid, p_company_id uuid, p_product_id uuid, p_quantity numeric DEFAULT 1, p_customer_id uuid DEFAULT NULL::uuid, p_session_id character varying DEFAULT NULL::character varying, p_product_variant_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_cart_id UUID;
    v_item_id UUID;
    v_unit_price DECIMAL;
    v_original_price DECIMAL;
    v_discount_percent DECIMAL;
    v_product_name VARCHAR;
    v_available_qty DECIMAL;
BEGIN
    -- ═══════════════════════════════════════════════════════════════
    -- 1. الحصول على أو إنشاء السلة
    -- ═══════════════════════════════════════════════════════════════
    v_cart_id := get_or_create_cart(p_tenant_id, p_company_id, p_customer_id, p_session_id);
    
    -- ═══════════════════════════════════════════════════════════════
    -- 2. حساب السعر (حسب العميل)
    -- ═══════════════════════════════════════════════════════════════
    SELECT 
        customer_price,
        base_price,
        discount_percent,
        name_ar
    INTO 
        v_unit_price,
        v_original_price,
        v_discount_percent,
        v_product_name
    FROM get_products_for_store(
        p_tenant_id,
        p_customer_id,
        NULL, NULL, NULL, NULL, NULL,
        'created_at', 'DESC',
        999, 0
    )
    WHERE product_id = p_product_id
    LIMIT 1;
    
    IF v_unit_price IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'product_not_found',
            'message', 'المنتج غير متاح'
        );
    END IF;
    
    -- ═══════════════════════════════════════════════════════════════
    -- 3. التحقق من التوفر
    -- ═══════════════════════════════════════════════════════════════
    SELECT available_quantity INTO v_available_qty
    FROM get_products_for_store(
        p_tenant_id, p_customer_id, NULL, NULL, NULL, NULL, NULL,
        'created_at', 'DESC', 1, 0
    )
    WHERE product_id = p_product_id;
    
    IF v_available_qty < p_quantity THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'insufficient_stock',
            'message', 'الكمية المتاحة: ' || v_available_qty,
            'available_quantity', v_available_qty
        );
    END IF;
    
    -- ═══════════════════════════════════════════════════════════════
    -- 4. إضافة أو تحديث العنصر
    -- ═══════════════════════════════════════════════════════════════
    INSERT INTO shopping_cart_items (
        cart_id,
        product_id,
        product_variant_id,
        quantity,
        unit_price,
        original_price,
        discount_percent,
        notes
    )
    VALUES (
        v_cart_id,
        p_product_id,
        p_product_variant_id,
        p_quantity,
        v_unit_price,
        v_original_price,
        v_discount_percent,
        p_notes
    )
    ON CONFLICT (cart_id, product_id) 
    DO UPDATE SET
        quantity = shopping_cart_items.quantity + EXCLUDED.quantity,
        updated_at = NOW()
    RETURNING id INTO v_item_id;
    
    -- ═══════════════════════════════════════════════════════════════
    -- 5. تحديث مجاميع السلة
    -- ═══════════════════════════════════════════════════════════════
    PERFORM update_cart_totals(v_cart_id);
    
    -- ═══════════════════════════════════════════════════════════════
    -- 6. إرجاع النتيجة
    -- ═══════════════════════════════════════════════════════════════
    RETURN jsonb_build_object(
        'success', true,
        'cart_id', v_cart_id,
        'item_id', v_item_id,
        'product_name', v_product_name,
        'quantity', p_quantity,
        'unit_price', v_unit_price,
        'message', 'تمت الإضافة للسلة'
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'add_failed',
            'message', SQLERRM
        );
END;
$$;


--
-- Name: add_user_by_super_admin(character varying, character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.add_user_by_super_admin(p_user_email character varying, p_user_name character varying, p_role_code character varying, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_role_id UUID;
    v_result JSONB;
BEGIN
    -- التحقق من أن المستخدم الحالي Super Admin
    IF NOT is_super_admin(auth.uid()) THEN
        SELECT jsonb_build_object(
            'success', false,
            'error', 'غير مصرح - يجب أن تكون Super Admin'
        ) INTO v_result;
        RETURN v_result;
    END IF;
    
    -- البحث عن المستخدم في Auth
    SELECT id INTO v_user_id
    FROM auth.users
    WHERE email = p_user_email
    LIMIT 1;
    
    IF v_user_id IS NULL THEN
        SELECT jsonb_build_object(
            'success', false,
            'error', 'المستخدم غير موجود في Auth. يرجى إنشاء المستخدم أولاً'
        ) INTO v_result;
        RETURN v_result;
    END IF;
    
    -- الحصول على Role
    SELECT id INTO v_role_id
    FROM roles
    WHERE code = p_role_code
    LIMIT 1;
    
    IF v_role_id IS NULL THEN
        SELECT jsonb_build_object(
            'success', false,
            'error', 'Role غير موجود: ' || p_role_code
        ) INTO v_result;
        RETURN v_result;
    END IF;
    
    -- ربط المستخدم بالـ Role
    INSERT INTO user_roles (user_id, role_id, tenant_id, is_active)
    VALUES (v_user_id, v_role_id, p_tenant_id, true)
    ON CONFLICT (user_id, role_id) 
    DO UPDATE SET is_active = true, tenant_id = p_tenant_id;
    
    -- إرجاع النتيجة
    SELECT jsonb_build_object(
        'success', true,
        'user_id', v_user_id,
        'email', p_user_email,
        'role', p_role_code,
        'message', 'تم إضافة المستخدم بنجاح'
    ) INTO v_result;
    
    RETURN v_result;
END;
$$;


--
-- Name: add_white_label_domain(uuid, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.add_white_label_domain(p_agent_id uuid, p_domain character varying, p_domain_type character varying DEFAULT 'subdomain'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_agent RECORD;
    v_domain_id UUID;
    v_verification_token VARCHAR(100);
BEGIN
    -- التحقق من الوكيل
    SELECT * INTO v_agent FROM agents WHERE id = p_agent_id AND has_white_label = true AND white_label_status = 'active';
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'الوكيل غير مفعل لـ White Label');
    END IF;
    
    -- التحقق من عدم وجود الدومين
    IF EXISTS (SELECT 1 FROM white_label_domains WHERE domain = p_domain) THEN
        RETURN jsonb_build_object('success', false, 'error', 'الدومين مسجل مسبقاً');
    END IF;
    
    -- توليد token للتحقق
    v_verification_token := 'WL-' || UPPER(SUBSTRING(MD5(RANDOM()::TEXT || NOW()::TEXT), 1, 32));
    
    -- إضافة الدومين
    INSERT INTO white_label_domains (agent_id, domain, domain_type, verification_token, status)
    VALUES (p_agent_id, p_domain, p_domain_type, v_verification_token, 'pending')
    RETURNING id INTO v_domain_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'domain_id', v_domain_id,
        'verification_token', v_verification_token,
        'message', 'تم إضافة الدومين بنجاح - يرجى تكوين DNS'
    );
END;
$$;


--
-- Name: advance_transaction_stage(text, uuid, text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.advance_transaction_stage(p_type text, p_transaction_id uuid, p_new_stage text, p_user_id uuid, p_user_name text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_cancellation_reason text DEFAULT NULL::text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
    v_current_stage TEXT;
    v_company_id UUID;
    v_tenant_id UUID;
    v_generated_no TEXT;
    v_number_field TEXT;
    v_date_field TEXT;
    v_user_field TEXT;
    v_user_name_field TEXT;
    v_at_field TEXT;
    v_sql TEXT;
BEGIN
    -- 1. قفل السجل وقراءة المرحلة الحالية
    IF p_type = 'purchase' THEN
        SELECT stage, company_id, tenant_id
        INTO v_current_stage, v_company_id, v_tenant_id
        FROM purchase_transactions
        WHERE id = p_transaction_id
        FOR UPDATE;
    ELSE
        SELECT stage, company_id, tenant_id
        INTO v_current_stage, v_company_id, v_tenant_id
        FROM sales_transactions
        WHERE id = p_transaction_id
        FOR UPDATE;
    END IF;

    IF v_current_stage IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'المعاملة غير موجودة');
    END IF;

    -- 2. التحقق من صلاحية التحويل
    IF NOT is_valid_stage_transition(p_type, v_current_stage, p_new_stage) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', format('تحويل غير مسموح: %s → %s', v_current_stage, p_new_stage)
        );
    END IF;

    -- 3. تحديد حقول المستخدم لهذه المرحلة
    v_user_field := CASE p_new_stage
        WHEN 'quotation' THEN 'quoted_by'
        WHEN 'reservation' THEN 'reserved_by'
        WHEN 'order' THEN 'ordered_by'
        WHEN 'approved' THEN 'approved_by'
        WHEN 'receipt' THEN 'received_by'
        WHEN 'delivery' THEN 'delivered_by'
        WHEN 'invoice' THEN 'invoiced_by'
        WHEN 'posted' THEN 'posted_by'
        WHEN 'cancelled' THEN 'cancelled_by'
        ELSE NULL
    END;

    v_user_name_field := CASE WHEN v_user_field IS NOT NULL THEN v_user_field || '_name' ELSE NULL END;

    v_at_field := CASE p_new_stage
        WHEN 'quotation' THEN 'quoted_at'
        WHEN 'reservation' THEN 'reserved_at'
        WHEN 'order' THEN 'ordered_at'
        WHEN 'approved' THEN 'approved_at'
        WHEN 'receipt' THEN 'received_at'
        WHEN 'delivery' THEN 'delivered_at'
        WHEN 'invoice' THEN 'invoiced_at'
        WHEN 'posted' THEN 'posted_at'
        WHEN 'cancelled' THEN 'cancelled_at'
        ELSE NULL
    END;

    -- 4. توليد رقم
    IF p_new_stage IN ('quotation', 'reservation', 'order', 'receipt', 'delivery', 'invoice') THEN
        v_generated_no := generate_stage_number(v_tenant_id, v_company_id, p_type, p_new_stage);
        v_number_field := p_new_stage || '_no';
        v_date_field := p_new_stage || '_date';
    END IF;

    -- 5. تحديث السجل
    IF p_type = 'purchase' THEN
        v_sql := 'UPDATE purchase_transactions SET stage = $1, updated_at = NOW(), updated_by = $2';
    ELSE
        v_sql := 'UPDATE sales_transactions SET stage = $1, updated_at = NOW(), updated_by = $2';
    END IF;

    IF v_number_field IS NOT NULL AND v_generated_no IS NOT NULL THEN
        v_sql := v_sql || format(', %I = %L', v_number_field, v_generated_no);
        v_sql := v_sql || format(', %I = CURRENT_DATE', v_date_field);
    END IF;

    IF v_user_field IS NOT NULL THEN
        v_sql := v_sql || format(', %I = %L', v_user_field, p_user_id);
        IF p_user_name IS NOT NULL AND v_user_name_field IS NOT NULL THEN
            v_sql := v_sql || format(', %I = %L', v_user_name_field, p_user_name);
        END IF;
        IF v_at_field IS NOT NULL THEN
            v_sql := v_sql || format(', %I = NOW()', v_at_field);
        END IF;
    END IF;

    IF p_new_stage = 'posted' THEN
        v_sql := v_sql || ', is_posted = true';
    END IF;

    IF p_new_stage = 'cancelled' AND p_cancellation_reason IS NOT NULL THEN
        v_sql := v_sql || format(', cancellation_reason = %L', p_cancellation_reason);
    END IF;

    IF p_new_stage = 'approved' AND p_notes IS NOT NULL THEN
        v_sql := v_sql || format(', approval_notes = %L', p_notes);
    END IF;

    v_sql := v_sql || ' WHERE id = $3';

    EXECUTE v_sql USING p_new_stage, p_user_id, p_transaction_id;

    -- 6. تسجيل في سجل المراحل
    INSERT INTO transaction_stage_log (
        transaction_type, transaction_id,
        from_stage, to_stage,
        generated_number, notes,
        performed_by, performed_by_name, ip_address, user_agent
    ) VALUES (
        p_type, p_transaction_id,
        v_current_stage, p_new_stage,
        v_generated_no, COALESCE(p_notes, p_cancellation_reason),
        p_user_id, p_user_name, p_ip_address, p_user_agent
    );

    -- 7. النتيجة
    RETURN jsonb_build_object(
        'success', true,
        'from_stage', v_current_stage,
        'to_stage', p_new_stage,
        'generated_number', v_generated_no,
        'performed_by', p_user_id,
        'performed_by_name', p_user_name
    );
END;
$_$;


--
-- Name: allocate_container_costs(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.allocate_container_costs(p_container_id uuid, p_allocation_method character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_container RECORD;
    v_item RECORD;
    v_total_goods_value NUMERIC := 0;
    v_total_expenses NUMERIC := 0;
    v_total_quantity NUMERIC := 0;
    v_allocation_method VARCHAR;
    v_ratio NUMERIC;
    v_allocated_cost NUMERIC;
    v_final_unit_cost NUMERIC;
    v_items_updated INTEGER := 0;
    v_result JSONB;
BEGIN
    -- جلب بيانات الكونتينر
    SELECT c.*, comp.tenant_id 
    INTO v_container
    FROM containers c
    JOIN companies comp ON c.company_id = comp.id
    WHERE c.id = p_container_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Container not found',
            'error_ar', 'الكونتينر غير موجود'
        );
    END IF;
    
    -- التحقق من أن التكاليف غير مثبتة
    IF v_container.is_cost_finalized = true THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Container costs already finalized',
            'error_ar', 'تكاليف الكونتينر مثبتة بالفعل'
        );
    END IF;
    
    -- تحديد طريقة التوزيع
    v_allocation_method := COALESCE(p_allocation_method, v_container.cost_allocation_method, 'by_value');
    
    -- حساب إجمالي قيمة البضاعة
    SELECT COALESCE(SUM(unit_cost * expected_quantity), 0)
    INTO v_total_goods_value
    FROM container_items
    WHERE container_id = p_container_id;
    
    -- حساب إجمالي المصاريف
    SELECT COALESCE(SUM(COALESCE(actual_amount, expected_amount, amount, 0)), 0)
    INTO v_total_expenses
    FROM container_expenses
    WHERE container_id = p_container_id;
    
    -- حساب إجمالي الكمية (لطريقة by_quantity)
    SELECT COALESCE(SUM(expected_quantity), 0)
    INTO v_total_quantity
    FROM container_items
    WHERE container_id = p_container_id;
    
    -- توزيع المصاريف على البنود
    FOR v_item IN 
        SELECT * FROM container_items WHERE container_id = p_container_id
    LOOP
        -- حساب النسبة حسب طريقة التوزيع
        CASE v_allocation_method
            WHEN 'by_value' THEN
                IF v_total_goods_value > 0 THEN
                    v_ratio := (v_item.unit_cost * v_item.expected_quantity) / v_total_goods_value;
                ELSE
                    v_ratio := 1.0 / NULLIF((SELECT COUNT(*) FROM container_items WHERE container_id = p_container_id), 0);
                END IF;
                
            WHEN 'by_quantity' THEN
                IF v_total_quantity > 0 THEN
                    v_ratio := v_item.expected_quantity / v_total_quantity;
                ELSE
                    v_ratio := 1.0 / NULLIF((SELECT COUNT(*) FROM container_items WHERE container_id = p_container_id), 0);
                END IF;
                
            WHEN 'by_weight' THEN
                -- توزيع حسب الوزن
                SELECT COALESCE(SUM(weight_kg), SUM(expected_quantity)) INTO v_total_quantity
                FROM container_items WHERE container_id = p_container_id;
                
                IF v_total_quantity > 0 THEN
                    v_ratio := COALESCE(v_item.weight_kg, v_item.expected_quantity) / v_total_quantity;
                ELSE
                    v_ratio := 1.0 / NULLIF((SELECT COUNT(*) FROM container_items WHERE container_id = p_container_id), 0);
                END IF;
                
            ELSE -- manual or unknown
                v_ratio := 0; -- keep existing values
        END CASE;
        
        -- حساب التكلفة الموزعة
        v_allocated_cost := v_total_expenses * COALESCE(v_ratio, 0);
        
        -- حساب تكلفة الوحدة النهائية
        IF v_item.expected_quantity > 0 THEN
            v_final_unit_cost := (v_item.unit_cost * v_item.expected_quantity + v_allocated_cost) / v_item.expected_quantity;
        ELSE
            v_final_unit_cost := v_item.unit_cost;
        END IF;
        
        -- تحديث البند
        IF v_allocation_method != 'manual' THEN
            UPDATE container_items
            SET 
                allocated_costs = v_allocated_cost,
                cost_per_unit_allocated = CASE WHEN expected_quantity > 0 THEN v_allocated_cost / expected_quantity ELSE 0 END,
                provisional_unit_cost = v_item.unit_cost,
                final_unit_cost = v_final_unit_cost,
                total_provisional_cost = v_item.unit_cost * expected_quantity,
                total_final_cost = v_final_unit_cost * expected_quantity,
                updated_at = NOW()
            WHERE id = v_item.id;
            
            v_items_updated := v_items_updated + 1;
        END IF;
    END LOOP;
    
    -- تحديث الكونتينر
    UPDATE containers
    SET 
        provisional_goods_cost = v_total_goods_value,
        total_expected_costs = (SELECT COALESCE(SUM(expected_amount), 0) FROM container_expenses WHERE container_id = p_container_id),
        total_actual_costs = v_total_expenses,
        total_landed_cost = v_total_goods_value + v_total_expenses,
        cost_allocation_method = v_allocation_method,
        updated_at = NOW()
    WHERE id = p_container_id;
    
    -- إرجاع النتيجة
    RETURN jsonb_build_object(
        'success', true,
        'container_id', p_container_id,
        'allocation_method', v_allocation_method,
        'total_goods_value', v_total_goods_value,
        'total_expenses', v_total_expenses,
        'total_landed_cost', v_total_goods_value + v_total_expenses,
        'items_updated', v_items_updated
    );
    
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM,
        'error_code', SQLSTATE
    );
END;
$$;


--
-- Name: apply_audit_trigger(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.apply_audit_trigger(p_table_name text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_trigger_name TEXT;
BEGIN
    v_trigger_name := 'trg_audit_' || p_table_name;
    
    -- حذف Trigger القديم
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON %I', v_trigger_name, p_table_name);
    
    -- إنشاء Trigger جديد
    EXECUTE format('
        CREATE TRIGGER %I
        AFTER INSERT OR UPDATE OR DELETE ON %I
        FOR EACH ROW
        EXECUTE FUNCTION auto_audit_log()
    ', v_trigger_name, p_table_name);
    
    RAISE NOTICE '✅ تم تطبيق Audit Trigger على %', p_table_name;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE '⚠️ فشل تطبيق Audit على %: %', p_table_name, SQLERRM;
END;
$$;


--
-- Name: apply_auto_company_trigger(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.apply_auto_company_trigger(p_table_name text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    EXECUTE format('DROP TRIGGER IF EXISTS trg_auto_company_%I ON public.%I', p_table_name, p_table_name);
    
    EXECUTE format('
        CREATE TRIGGER trg_auto_company_%I
            BEFORE INSERT ON public.%I
            FOR EACH ROW
            EXECUTE FUNCTION public.auto_set_company_id()
    ', p_table_name, p_table_name);
END;
$$;


--
-- Name: apply_auto_tenant_trigger(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.apply_auto_tenant_trigger(p_table_name text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- حذف التريغر القديم إن وجد
    EXECUTE format('DROP TRIGGER IF EXISTS trg_auto_tenant_%I ON public.%I', p_table_name, p_table_name);
    
    -- إنشاء التريغر الجديد
    EXECUTE format('
        CREATE TRIGGER trg_auto_tenant_%I
            BEFORE INSERT ON public.%I
            FOR EACH ROW
            EXECUTE FUNCTION public.auto_set_tenant_id()
    ', p_table_name, p_table_name);
END;
$$;


--
-- Name: apply_brand_isolation_trigger(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.apply_brand_isolation_trigger(p_table_name text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    EXECUTE format('DROP TRIGGER IF EXISTS trg_brand_isolation_%I ON public.%I', p_table_name, p_table_name);
    
    EXECUTE format('
        CREATE TRIGGER trg_brand_isolation_%I
            BEFORE INSERT OR UPDATE ON public.%I
            FOR EACH ROW
            EXECUTE FUNCTION public.enforce_brand_isolation()
    ', p_table_name, p_table_name);
END;
$$;


--
-- Name: apply_chart_template_to_company(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.apply_chart_template_to_company(p_company_id uuid, p_template_code text DEFAULT 'extended'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  -- 🔁 توحيد: دائماً الشجرة الموسّعة. p_template_code يُتجاهَل ويبقى للتوافق الخلفي.
  -- ✅ التحقق من وجود شجرة مسبقاً ⇒ لا تكرار عند إعادة التسجيل (idempotency)
  IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id LIMIT 1) THEN
    PERFORM create_extended_chart(p_company_id);
  END IF;

  -- 🆕 ضمان تحسينات الإنترنت/المشتريات بالطريق (idempotent — يخدم الشجرات القديمة أيضاً)
  PERFORM ensure_extended_chart_improvements(p_company_id);

  -- 🔗 ربط الحسابات الافتراضية
  BEGIN
    PERFORM auto_set_default_accounts(p_company_id);
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'auto_set_default_accounts warning for %: %', p_company_id, SQLERRM;
  END;

  -- 📅 إنشاء السنة المالية وفتراتها
  PERFORM ensure_company_fiscal_year(p_company_id);
END;
$$;


--
-- Name: apply_chart_template_to_company(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.apply_chart_template_to_company(p_company_id uuid, p_template_code character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF p_template_code IN ('extended', 'EXTENDED') THEN
        PERFORM create_extended_chart(p_company_id);
        RAISE NOTICE 'V6 — تم تطبيق الشجرة الموسعة V5.2 على الشركة %', p_company_id;
    ELSE
        PERFORM create_simple_chart(p_company_id);
        RAISE NOTICE 'V6 — تم تطبيق الشجرة القياسية V5.1 على الشركة %', p_company_id;
    END IF;
END;
$$;


--
-- Name: FUNCTION apply_chart_template_to_company(p_company_id uuid, p_template_code character varying); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_chart_template_to_company(p_company_id uuid, p_template_code character varying) IS 'V6: يستدعي create_simple_chart V5.1 أو create_extended_chart V5.2';


--
-- Name: apply_comprehensive_rls(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.apply_comprehensive_rls(p_table_name text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_table_exists BOOLEAN;
    v_tenant_id_exists BOOLEAN;
    v_policy_name TEXT;
BEGIN
    -- التحقق من وجود الجدول
    SELECT EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = p_table_name
    ) INTO v_table_exists;
    
    IF NOT v_table_exists THEN
        RAISE NOTICE '⚠️ الجدول % غير موجود - سيتم تخطيه', p_table_name;
        RETURN;
    END IF;
    
    -- التحقق من وجود عمود tenant_id
    SELECT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' 
          AND table_name = p_table_name 
          AND column_name = 'tenant_id'
    ) INTO v_tenant_id_exists;
    
    IF NOT v_tenant_id_exists THEN
        RAISE NOTICE '⚠️ الجدول % لا يحتوي على عمود tenant_id - سيتم تخطيه', p_table_name;
        RETURN;
    END IF;
    
    v_policy_name := p_table_name || '_tenant_isolation';
    
    -- تفعيل RLS
    
    -- حذف جميع Policies القديمة
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_policy_name || '_select', p_table_name);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_policy_name || '_insert', p_table_name);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_policy_name || '_update', p_table_name);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_policy_name || '_delete', p_table_name);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_policy_name, p_table_name);
    
    -- إنشاء Policies جديدة (مع التحقق من Super Admin مباشرة)
    EXECUTE format('
        CREATE POLICY %I ON %I
        FOR SELECT
        USING (
            tenant_id = get_current_tenant_id() 
            OR COALESCE(
                (auth.jwt() -> ''user_metadata'' ->> ''is_super_admin'')::BOOLEAN,
                (auth.jwt() -> ''app_metadata'' ->> ''is_super_admin'')::BOOLEAN,
                false
            )
        )
    ', v_policy_name || '_select', p_table_name);
    
    EXECUTE format('
        CREATE POLICY %I ON %I
        FOR INSERT
        WITH CHECK (
            tenant_id = get_current_tenant_id() 
            OR COALESCE(
                (auth.jwt() -> ''user_metadata'' ->> ''is_super_admin'')::BOOLEAN,
                (auth.jwt() -> ''app_metadata'' ->> ''is_super_admin'')::BOOLEAN,
                false
            )
        )
    ', v_policy_name || '_insert', p_table_name);
    
    EXECUTE format('
        CREATE POLICY %I ON %I
        FOR UPDATE
        USING (
            tenant_id = get_current_tenant_id() 
            OR COALESCE(
                (auth.jwt() -> ''user_metadata'' ->> ''is_super_admin'')::BOOLEAN,
                (auth.jwt() -> ''app_metadata'' ->> ''is_super_admin'')::BOOLEAN,
                false
            )
        )
        WITH CHECK (
            tenant_id = get_current_tenant_id() 
            OR COALESCE(
                (auth.jwt() -> ''user_metadata'' ->> ''is_super_admin'')::BOOLEAN,
                (auth.jwt() -> ''app_metadata'' ->> ''is_super_admin'')::BOOLEAN,
                false
            )
        )
    ', v_policy_name || '_update', p_table_name);
    
    EXECUTE format('
        CREATE POLICY %I ON %I
        FOR DELETE
        USING (
            tenant_id = get_current_tenant_id() 
            OR COALESCE(
                (auth.jwt() -> ''user_metadata'' ->> ''is_super_admin'')::BOOLEAN,
                (auth.jwt() -> ''app_metadata'' ->> ''is_super_admin'')::BOOLEAN,
                false
            )
        )
    ', v_policy_name || '_delete', p_table_name);
    
    RAISE NOTICE '✅ تم تطبيق RLS على %', p_table_name;
END;
$$;


--
-- Name: apply_rls_to_table(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.apply_rls_to_table(p_table_name text, p_policy_name text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_policy_name TEXT;
    v_table_exists BOOLEAN;
    v_tenant_id_exists BOOLEAN;
BEGIN
    -- التحقق من وجود الجدول
    SELECT EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = p_table_name
    ) INTO v_table_exists;
    
    IF NOT v_table_exists THEN
        RAISE NOTICE '⚠️ الجدول % غير موجود - سيتم تخطيه', p_table_name;
        RETURN;
    END IF;
    
    -- التحقق من وجود عمود tenant_id
    SELECT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' 
          AND table_name = p_table_name 
          AND column_name = 'tenant_id'
    ) INTO v_tenant_id_exists;
    
    IF NOT v_tenant_id_exists THEN
        RAISE NOTICE '⚠️ الجدول % لا يحتوي على عمود tenant_id - سيتم تخطيه', p_table_name;
        RETURN;
    END IF;
    
    -- استخدام اسم الـ policy المحدد أو الافتراضي
    v_policy_name := COALESCE(p_policy_name, p_table_name || '_tenant_isolation');
    
    -- تفعيل RLS
    
    -- حذف الـ policy القديم إن وجد
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', v_policy_name, p_table_name);
    
    -- إنشاء الـ policy الجديد
    EXECUTE format('CREATE POLICY %I ON %I FOR ALL USING (tenant_id = get_current_tenant_id() OR is_super_admin()) WITH CHECK (tenant_id = get_current_tenant_id() OR is_super_admin())', 
        v_policy_name, p_table_name);
    
    RAISE NOTICE '✅ تم تطبيق RLS على %', p_table_name;
END;
$$;


--
-- Name: approve_delivery_note(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.approve_delivery_note(p_note_id uuid, p_approved_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_note RECORD;
BEGIN
    SELECT * INTO v_note FROM delivery_notes WHERE id = p_note_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Delivery note not found');
    END IF;
    
    IF v_note.status != 'pending_approval' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Note is not pending approval');
    END IF;
    
    UPDATE delivery_notes
    SET 
        status = 'approved',
        approved_by = p_approved_by,
        approved_at = NOW()
    WHERE id = p_note_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'note_id', p_note_id,
        'status', 'approved'
    );
END;
$$;


--
-- Name: approve_listing_request(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.approve_listing_request(p_request_id uuid, p_overrides jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_req marketplace_listing_requests%ROWTYPE;
    v_link marketplace_supplier_links%ROWTYPE;
    v_product_id UUID;
    v_title JSONB;
    v_price DECIMAL(12,2);
    v_slug TEXT;
BEGIN
    SELECT * INTO v_req FROM marketplace_listing_requests WHERE id = p_request_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'listing request not found';
    END IF;

    -- تحقق الصلاحية: المستدعي من tenant مالك السوق (أو أدمن منصة)
    IF NOT (is_platform_admin() OR v_req.tenant_id = get_user_tenant_id()) THEN
        RAISE EXCEPTION 'not authorized to approve this request';
    END IF;

    IF v_req.status NOT IN ('pending', 'changes_requested', 'suspended') THEN
        RAISE EXCEPTION 'request is not in a reviewable state (%)', v_req.status;
    END IF;

    SELECT * INTO v_link FROM marketplace_supplier_links WHERE id = v_req.link_id;

    -- دمج تعديلات الأدمن
    v_title := COALESCE(
        p_overrides->'marketing_title',
        v_req.admin_overrides->'marketing_title',
        jsonb_build_object(
            'ar', v_req.proposed->>'name_ar',
            'en', v_req.proposed->>'name_en'
        )
    );
    v_price := COALESCE(
        (p_overrides->>'base_price')::DECIMAL,
        (v_req.admin_overrides->>'base_price')::DECIMAL,
        (v_req.proposed->>'supplier_price')::DECIMAL
    );
    v_slug := COALESCE(
        p_overrides->>'seo_slug',
        v_req.admin_overrides->>'seo_slug',
        lower(regexp_replace(COALESCE(v_req.proposed->>'code', v_req.material_id::text), '[^a-zA-Z0-9]+', '-', 'g'))
    );

    -- إنشاء/تحديث المنتج المنشور
    INSERT INTO ecommerce_products (
        store_id, tenant_id, material_id,
        supplier_link_id, supplier_tenant_id,
        marketing_title, seo_slug,
        base_price, supplier_cost_price,
        gallery_images, is_published, stock_status
    ) VALUES (
        v_req.store_id, v_req.tenant_id, v_req.material_id,
        v_req.link_id, v_req.supplier_tenant_id,
        v_title, v_slug,
        v_price, (v_req.proposed->>'supplier_price')::DECIMAL,
        CASE WHEN v_req.proposed->>'image_url' IS NOT NULL
             THEN jsonb_build_array(v_req.proposed->>'image_url')
             ELSE '[]'::jsonb END,
        true, 'in_stock'
    )
    ON CONFLICT (store_id, material_id) DO UPDATE SET
        marketing_title = EXCLUDED.marketing_title,
        base_price = EXCLUDED.base_price,
        supplier_cost_price = EXCLUDED.supplier_cost_price,
        supplier_link_id = EXCLUDED.supplier_link_id,
        supplier_tenant_id = EXCLUDED.supplier_tenant_id,
        is_published = true
    RETURNING id INTO v_product_id;

    -- ربط التصنيف إن حدده الأدمن
    IF COALESCE(p_overrides->>'category_id', v_req.admin_overrides->>'category_id') IS NOT NULL THEN
        INSERT INTO ecommerce_product_categories (product_id, category_id)
        VALUES (
            v_product_id,
            COALESCE(p_overrides->>'category_id', v_req.admin_overrides->>'category_id')::UUID
        )
        ON CONFLICT DO NOTHING;
    END IF;

    -- تحديث الطلب
    UPDATE marketplace_listing_requests
    SET status = 'approved',
        admin_overrides = COALESCE(admin_overrides, '{}'::jsonb) || COALESCE(p_overrides, '{}'::jsonb),
        ecommerce_product_id = v_product_id,
        reviewed_by = auth.uid(),
        reviewed_at = now(),
        review_note = COALESCE(p_overrides->>'note', review_note)
    WHERE id = p_request_id;

    -- تحديث إحصائيات المورد (قد يحوّله approved → active)
    PERFORM update_supplier_link_stats(v_req.link_id);

    RETURN v_product_id;
END;
$$;


--
-- Name: approve_recurring_entry(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.approve_recurring_entry(p_history_id uuid, p_user_id uuid, p_execute_now boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_history RECORD;
    v_result JSONB;
BEGIN
    -- جلب السجل
    SELECT * INTO v_history FROM recurring_entry_history WHERE id = p_history_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Record not found');
    END IF;

    -- التحقق من الحالة
    IF v_history.approval_status != 'pending' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Already processed');
    END IF;

    -- تحديث الموافقة
    UPDATE recurring_entry_history
    SET
        approval_status = 'approved',
        approved_by = p_user_id,
        approved_at = NOW()
    WHERE id = p_history_id;

    -- تنفيذ القيد إذا طُلب — مع force_post = true
    -- لأن الموافقة اليدوية = تفويض = ترحيل تلقائي
    IF p_execute_now THEN
        v_result := execute_recurring_entry(p_history_id, p_user_id, true);
        RETURN v_result;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Approved successfully',
        'executed', false
    );
END;
$$;


--
-- Name: approve_review(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.approve_review(p_tenant_id uuid, p_review_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_product_id UUID;
    v_result JSONB;
BEGIN
    -- تحديث حالة التقييم
    UPDATE product_reviews
    SET status = 'approved',
        approved_at = NOW(),
        updated_at = NOW()
    WHERE id = p_review_id
      AND tenant_id = p_tenant_id
    RETURNING product_id INTO v_product_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'التقييم غير موجود');
    END IF;
    
    -- تحديث إحصائيات المنتج
    PERFORM update_product_review_stats(p_tenant_id, v_product_id);
    
    RETURN jsonb_build_object('success', true, 'message', 'تمت الموافقة على التقييم');
END;
$$;


--
-- Name: ar_normalize(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.ar_normalize(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT lower(
        regexp_replace(
            regexp_replace(
                translate(
                    coalesce(t, ''),
                    'أإآاىئؤةًٌٍَُِّْـ',   -- hamza/alef variants, alef-maqsura, ta-marbuta, tashkeel, tatweel
                    'ااااييوه'              -- → ا ا ا ا ي ي و ه ; remainder (tashkeel+tatweel) stripped below
                ),
                '[ًٌٍَُِّْـ]', '', 'g'      -- strip any leftover tashkeel/tatweel
            ),
            '\s+', ' ', 'g'                -- collapse whitespace
        )
    );
$$;


--
-- Name: assert_can_access_company(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.assert_can_access_company(target_company_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
      DECLARE
          v_user_company_id uuid;
          v_is_admin boolean;
          v_jwt_role text;
      BEGIN
          -- 1. Service role bypass (cron jobs, server-side)
          BEGIN
              v_jwt_role := current_setting('request.jwt.claims', true)::json->>'role';
              IF v_jwt_role = 'service_role' THEN
                  RETURN;
              END IF;
          EXCEPTION WHEN OTHERS THEN
              -- No JWT context (direct psql) = superuser = allow
              RETURN;
          END;

          -- 2. Platform admin bypass
          v_is_admin := is_platform_admin();
          IF v_is_admin THEN
              RETURN;
          END IF;

          -- 3. NULL target = skip (trigger context where company_id comes from NEW row)
          IF target_company_id IS NULL THEN
              RETURN;
          END IF;

          -- 4. Company check
          v_user_company_id := get_user_company_id();
          IF v_user_company_id IS NULL THEN
              RAISE EXCEPTION 'Access Denied: No company context for current user';
          END IF;

          IF target_company_id != v_user_company_id THEN
              RAISE EXCEPTION 'Access Denied: Cross-company operation blocked [target=%, user=%]',
                  target_company_id, v_user_company_id;
          END IF;
      END;
      $$;


--
-- Name: assign_available_tenant(character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.assign_available_tenant(p_user_email character varying, p_user_name character varying) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_tenant_code VARCHAR(50);
BEGIN
    -- البحث عن tenant متاح
    SELECT id, code INTO v_tenant_id, v_tenant_code
    FROM tenants
    WHERE status = 'available'
    ORDER BY created_at ASC
    LIMIT 1
    FOR UPDATE SKIP LOCKED;  -- تجنب التعارض
    
    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION 'لا يوجد Tenants متاحة حالياً';
    END IF;
    
    -- تحديث بيانات Tenant
    UPDATE tenants
    SET 
        name = p_user_name,
        owner_email = p_user_email,
        status = 'active',
        updated_at = NOW()
    WHERE id = v_tenant_id;
    
    RAISE NOTICE '✅ تم ربط المشترك بـ Tenant: %', v_tenant_code;
    
    RETURN v_tenant_id;
END;
$$;


--
-- Name: assign_ecommerce_display_no(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.assign_ecommerce_display_no() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.display_no IS NULL OR NEW.display_no = '' THEN
    NEW.display_no := 'TX-' || nextval('ecommerce_product_display_seq');
  END IF;
  RETURN NEW;
END $$;


