      "ar":{"s":"🔗 رابط الدخول","t":"تسجيل الدخول","i":"اضغط للدخول إلى حسابك في {{brand}} بأمان.","b":"🔗 تسجيل الدخول"},
      "en":{"s":"🔗 Your sign-in link","t":"Sign in","i":"Click to securely sign in to your {{brand}} account.","b":"🔗 Sign in"},
      "ru":{"s":"🔗 Ссылка для входа","t":"Вход","i":"Нажмите, чтобы войти в аккаунт {{brand}}.","b":"🔗 Войти"},
      "uk":{"s":"🔗 Посилання для входу","t":"Вхід","i":"Натисніть, щоб увійти в акаунт {{brand}}.","b":"🔗 Увійти"},
      "tr":{"s":"🔗 Giriş bağlantınız","t":"Giriş yap","i":"{{brand}} hesabınıza giriş için tıklayın.","b":"🔗 Giriş yap"}},
    "email_change":{"icon":"✉️",
      "ar":{"s":"✉️ تأكيد البريد الجديد","t":"تأكيد البريد الجديد","i":"لتأكيد تغيير بريدك في {{brand}}، اضغط أدناه.","b":"✉️ تأكيد"},
      "en":{"s":"✉️ Confirm new email","t":"Confirm new email","i":"To confirm your email change on {{brand}}, click below.","b":"✉️ Confirm"},
      "ru":{"s":"✉️ Подтвердите почту","t":"Новая почта","i":"Подтвердите смену почты в {{brand}}.","b":"✉️ Подтвердить"},
      "uk":{"s":"✉️ Підтвердьте пошту","t":"Нова пошта","i":"Підтвердьте зміну пошти в {{brand}}.","b":"✉️ Підтвердити"},
      "tr":{"s":"✉️ E-postayı onayla","t":"Yeni e-posta","i":"{{brand}} e-posta değişikliğini onaylayın.","b":"✉️ Onayla"}},
    "invite":{"icon":"📩",
      "ar":{"s":"📩 دعوة","t":"تمت دعوتك","i":"تمت دعوتك للانضمام إلى {{brand}}.","b":"📩 قبول الدعوة"},
      "en":{"s":"📩 You are invited","t":"You are invited","i":"You have been invited to join {{brand}}.","b":"📩 Accept"},
      "ru":{"s":"📩 Приглашение","t":"Вас пригласили","i":"Вас пригласили в {{brand}}.","b":"📩 Принять"},
      "uk":{"s":"📩 Запрошення","t":"Вас запросили","i":"Вас запросили до {{brand}}.","b":"📩 Прийняти"},
      "tr":{"s":"📩 Davet","t":"Davet edildiniz","i":"{{brand}} platformuna davet edildiniz.","b":"📩 Kabul et"}},
    "reauth":{"icon":"🛡️",
      "ar":{"s":"🛡️ تأكيد الهوية","t":"تأكيد هويتك","i":"لإتمام العملية في {{brand}}، أكّد هويتك.","b":"🛡️ تأكيد"},
      "en":{"s":"🛡️ Confirm identity","t":"Confirm identity","i":"To complete this action on {{brand}}, confirm below.","b":"🛡️ Confirm"},
      "ru":{"s":"🛡️ Подтвердите личность","t":"Подтверждение","i":"Подтвердите личность в {{brand}}.","b":"🛡️ Подтвердить"},
      "uk":{"s":"🛡️ Підтвердьте особу","t":"Підтвердження","i":"Підтвердьте особу в {{brand}}.","b":"🛡️ Підтвердити"},
      "tr":{"s":"🛡️ Kimliğinizi doğrulayın","t":"Kimlik doğrulama","i":"{{brand}} işlemini tamamlamak için doğrulayın.","b":"🛡️ Doğrula"}}
  }'::jsonb;
  v_strings jsonb;
BEGIN
  IF v_lang NOT IN ('ar','en','ru','uk','tr') THEN v_lang := 'uk'; END IF;
  v_dir := CASE WHEN v_lang='ar' THEN 'rtl' ELSE 'ltr' END;
  IF v_platform = 'tkanex' OR COALESCE(event->'email_data'->>'redirect_to','') ILIKE '%tkanex%' THEN
    v_brand:='Tkanex'; v_wordmark:='TKANEX'; v_header_bg:='#1a1a2e'; v_header_fg:='#ffffff';
    v_btn_bg:='#c8a45a'; v_btn_fg:='#1a1a2e'; v_link:='#c8a45a'; v_site:='tkanex.com';
    v_tagline:='B2B FABRIC MARKETPLACE'; v_footer:='Tkanex — Одеса, Україна · tkanex.com'; v_support:='+380674841211';
  ELSE
    v_brand:='TexaCore'; v_wordmark:='TexaCore'; v_header_bg:='#047857'; v_header_fg:='#ffffff';
    v_btn_bg:='#047857'; v_btn_fg:='#ffffff'; v_link:='#047857'; v_site:='texacore.ai';
    v_tagline:='ENTERPRISE RESOURCE PLANNING'; v_footer:='TexaCore ERP · texacore.ai'; v_support:=NULL;
  END IF;
  v_url := v_base || '/auth/v1/verify?token=' || (event->'email_data'->>'token_hash')
           || '&type=' || v_action || '&redirect_to=' || COALESCE(event->'email_data'->>'redirect_to', v_base);
  v_kind := CASE WHEN v_action='signup' THEN 'activate' WHEN v_action='invite' THEN 'invite'
              WHEN v_action='recovery' THEN 'reset' WHEN v_action LIKE 'email_change%' THEN 'email_change'
              WHEN v_action='magiclink' THEN 'signin' WHEN v_action='reauthentication' THEN 'reauth' ELSE 'activate' END;
  v_icon := v_i18n->v_kind->>'icon';
  v_strings := v_i18n->v_kind->v_lang;
  v_subject := v_brand || ' — ' || (v_strings->>'s');
  v_title := v_strings->>'t';
  v_intro := replace(v_strings->>'i', '{{brand}}', v_brand);
  v_btn := v_strings->>'b';
  v_note := CASE v_lang
    WHEN 'ar' THEN 'إن لم تطلب هذا، تجاهل الرسالة. لا تشارك الرابط.'
    WHEN 'ru' THEN 'Если вы это не запрашивали, проигнорируйте письмо.'
    WHEN 'uk' THEN 'Якщо ви цього не запитували, проігноруйте лист.'
    WHEN 'tr' THEN 'Bu işlemi siz talep etmediyseniz, yok sayın.'
    ELSE 'If you did not request this, ignore this email.' END;
  v_html := '<!DOCTYPE html><html dir="'||v_dir||'" lang="'||v_lang||'"><body style="margin:0;background:#f3f4f6;font-family:Segoe UI,Arial,sans-serif;">'
    || '<table width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:40px 20px;"><tr><td align="center">'
    || '<table width="600" cellpadding="0" cellspacing="0" style="background:#fff;border-radius:16px;overflow:hidden;">'
    || '<tr><td style="background:'||v_header_bg||';padding:34px;text-align:center;"><div style="font-size:30px;font-weight:900;color:'||v_header_fg||';">'||v_wordmark||'</div><div style="font-size:11px;color:rgba(255,255,255,.7);letter-spacing:2px;">'||v_tagline||'</div></td></tr>'
    || '<tr><td style="text-align:center;padding:30px 40px 4px;font-size:56px;">'||v_icon||'</td></tr>'
    || '<tr><td style="text-align:center;padding:0 40px;"><h1 style="margin:0;font-size:24px;color:#1f2937;">'||v_title||'</h1></td></tr>'
    || '<tr><td style="padding:12px 40px;text-align:center;"><p style="margin:0;font-size:16px;color:#4b5563;line-height:1.8;">'||v_intro||'</p></td></tr>'
    || '<tr><td style="padding:20px 40px;text-align:center;"><a href="'||v_url||'" style="display:inline-block;background:'||v_btn_bg||';color:'||v_btn_fg||';text-decoration:none;padding:16px 50px;border-radius:14px;font-size:17px;font-weight:800;">'||v_btn||'</a></td></tr>'
    || '<tr><td style="padding:0 40px 16px;text-align:center;"><a href="'||v_url||'" style="font-size:11px;color:'||v_link||';word-break:break-all;">'||v_url||'</a></td></tr>'
    || '<tr><td style="padding:16px 40px;text-align:center;border-top:1px solid #e5e7eb;"><p style="margin:0;font-size:12px;color:#9ca3af;">🔒 '||v_note||'</p></td></tr>'
    || CASE WHEN v_support IS NOT NULL THEN '<tr><td style="padding:0 40px 8px;text-align:center;font-size:12px;color:#9ca3af;">📞 '||v_support||'</td></tr>' ELSE '' END
    || '<tr><td style="background:#f9fafb;padding:18px 40px;text-align:center;border-top:1px solid #e5e7eb;font-size:12px;color:#9ca3af;">'||v_footer||'</td></tr>'
    || '</table></td></tr></table></body></html>';
  PERFORM net.http_post(
    url := v_base || '/functions/v1/send-email',
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_anon,'apikey',v_anon),
    body := jsonb_build_object('to', v_email, 'subject', v_subject, 'html', v_html),
    timeout_milliseconds := 20000
  );
  RETURN '{}'::jsonb;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'auth_email_hook error: %', SQLERRM;
  RETURN '{}'::jsonb;
END;
$$;


--
-- Name: auto_audit_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.auto_audit_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_action VARCHAR(50);
    v_old_values JSONB;
    v_new_values JSONB;
    v_entity_name VARCHAR(255);
BEGIN
    -- تحديد نوع العملية
    IF TG_OP = 'INSERT' THEN
        v_action := 'create';
        v_new_values := to_jsonb(NEW);
        v_entity_name := COALESCE(
            v_new_values ->> 'name',
            v_new_values ->> 'name_ar',
            v_new_values ->> 'code',
            v_new_values ->> 'id'
        );
    ELSIF TG_OP = 'UPDATE' THEN
        v_action := 'update';
        v_old_values := to_jsonb(OLD);
        v_new_values := to_jsonb(NEW);
        v_entity_name := COALESCE(
            v_new_values ->> 'name',
            v_new_values ->> 'name_ar',
            v_new_values ->> 'code',
            v_new_values ->> 'id'
        );
    ELSIF TG_OP = 'DELETE' THEN
        v_action := 'delete';
        v_old_values := to_jsonb(OLD);
        v_entity_name := COALESCE(
            v_old_values ->> 'name',
            v_old_values ->> 'name_ar',
            v_old_values ->> 'code',
            v_old_values ->> 'id'
        );
    END IF;
    
    -- تسجيل
    PERFORM log_audit(
        v_action,
        TG_TABLE_NAME::VARCHAR(100),
        COALESCE(NEW.id, OLD.id),
        v_entity_name,
        v_old_values,
        v_new_values
    );
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: auto_calculate_invoice_commission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.auto_calculate_invoice_commission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_commission RECORD;
    v_period_start DATE;
    v_period_end DATE;
BEGIN
    -- فقط عند ترحيل الفاتورة
    IF NEW.status = 'posted' AND (OLD.status IS NULL OR OLD.status != 'posted') THEN
        -- تحديد فترة العمولة (الشهر الحالي)
        v_period_start := DATE_TRUNC('month', NEW.invoice_date)::DATE;
        v_period_end := (DATE_TRUNC('month', NEW.invoice_date) + INTERVAL '1 month' - INTERVAL '1 day')::DATE;
        
        -- حساب وإنشاء العمولات
        FOR v_commission IN 
            SELECT * FROM calculate_sales_commission(NEW.id, NEW.salesperson_id)
        LOOP
            INSERT INTO employee_commissions (
                tenant_id, company_id,
                employee_id, plan_id,
                period_start, period_end,
                source_type, source_id, source_number,
                base_amount, rate_applied, commission_amount,
                tier_number, net_amount,
                status
            )
            VALUES (
                NEW.tenant_id, NEW.company_id,
                v_commission.employee_id, v_commission.plan_id,
                v_period_start, v_period_end,
                'sales_invoice', NEW.id, NEW.invoice_number,
                v_commission.base_amount, v_commission.rate_applied, v_commission.commission_amount,
                v_commission.tier_applied, v_commission.commission_amount,
                'calculated'
            );
        END LOOP;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION auto_calculate_invoice_commission(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_calculate_invoice_commission() IS 'حساب العمولة تلقائياً عند ترحيل الفاتورة';


--
-- Name: auto_cancel_expired_bookings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.auto_cancel_expired_bookings() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  expired_order RECORD;
  cancelled_count INT := 0;
BEGIN
  -- البحث عن الطلبات المنتهية المهلة
  FOR expired_order IN
    SELECT 
      o.id,
      o.order_number,
      o.tenant_id,
      o.customer_name,
      o.customer_phone,
      o.booking_expires_at,
      o.status
    FROM ecommerce_orders o
    WHERE o.booking_expires_at IS NOT NULL
      AND o.booking_expires_at < NOW()
      AND o.status IN ('pending', 'awaiting_payment')
  LOOP
    -- 1. تحويل حالة الطلب إلى cancelled
    UPDATE ecommerce_orders 
    SET 
      status = 'cancelled',
      cancel_reason = 'booking_expired',
      cancelled_at = NOW(),
      updated_at = NOW()
    WHERE id = expired_order.id;

    -- 2. تسجيل في سجل الحالات
    INSERT INTO ecommerce_order_status_history (
      order_id, tenant_id, old_status, new_status, 
      changed_by_name, notes, event_type
    ) VALUES (
      expired_order.id,
      expired_order.tenant_id,
      expired_order.status,
      'cancelled',
      'النظام (إلغاء تلقائي)',
      'تم إلغاء الطلب تلقائياً بسبب انتهاء مهلة الحجز (' 
        || expired_order.booking_expires_at::TEXT || ')',
      'auto_cancelled'
    );

    -- 3. تحرير مخزون المورد (reservations)
    UPDATE ecommerce_stock_reservations
    SET 
      status = 'released',
      released_at = NOW()
    WHERE order_id = expired_order.id
      AND status = 'reserved';

    -- 4. تحديث حالة المورد
    UPDATE ecommerce_order_suppliers
    SET 
      status = 'cancelled',
      updated_at = NOW()
    WHERE order_id = expired_order.id
      AND status IN ('pending', 'confirmed');

    -- 5. تسجيل إشعار في سجل الإشعارات
    INSERT INTO ecommerce_notification_logs (
      tenant_id, order_id, order_number,
      stage_code, channel, recipient_type,
      message_body, status, sent_at
    ) VALUES (
      expired_order.tenant_id,
      expired_order.id,
      expired_order.order_number,
      'cancelled',
      'in_app',
      'admin',
      'تم إلغاء الطلب #' || expired_order.order_number 
        || ' تلقائياً بسبب انتهاء مهلة الحجز. تم تحرير مخزون المورد.',
      'sent',
      NOW()
    );

    -- 6. إشعار المورد (إن وجد)
    INSERT INTO ecommerce_notification_logs (
      tenant_id, order_id, order_number,
      stage_code, channel, recipient_type,
      message_body, status, sent_at
    )
    SELECT 
      expired_order.tenant_id,
      expired_order.id,
      expired_order.order_number,
      'cancelled',
      'in_app',
      'supplier',
      'تم إلغاء الطلب #' || expired_order.order_number 
        || ' وتحرير بضائعك بسبب عدم سداد العميل خلال المهلة المحددة.',
      'sent',
      NOW()
    FROM ecommerce_order_suppliers os
    WHERE os.order_id = expired_order.id
      AND os.supplier_id IS NOT NULL
    LIMIT 1; -- تسجيل إشعار واحد فقط

    cancelled_count := cancelled_count + 1;
    
    RAISE NOTICE 'Auto-cancelled order % (%) — booking expired at %',
      expired_order.order_number, expired_order.id, expired_order.booking_expires_at;
  END LOOP;

  IF cancelled_count > 0 THEN
    RAISE NOTICE 'pg_cron: Auto-cancelled % expired bookings at %', cancelled_count, NOW();
  END IF;
END;
$$;


--
-- Name: auto_create_agent_sub_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.auto_create_agent_sub_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_parent_id UUID;
    v_type_id UUID;
    v_tenant_id UUID;
    v_seq INT;
    v_new_code TEXT;
    v_new_id UUID;
BEGIN
    -- البحث عن الحساب الأب (134 = حسابات الوكلاء الجارية)
    SELECT id, account_type_id INTO v_parent_id, v_type_id
    FROM chart_of_accounts
    WHERE company_id = NEW.company_id
      AND account_code IN ('134', '1340', '1341')
      AND (is_group = true OR is_detail = false)
    ORDER BY
        CASE account_code
            WHEN '134' THEN 1
            WHEN '1340' THEN 2
            ELSE 3
        END
    LIMIT 1;

    IF v_parent_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT tenant_id INTO v_tenant_id
    FROM chart_of_accounts WHERE id = v_parent_id;

    -- تسلسل الرقم
    SELECT COUNT(*) + 1 INTO v_seq
    FROM chart_of_accounts
    WHERE parent_id = v_parent_id AND is_party_account = true;

    v_new_code := (SELECT account_code FROM chart_of_accounts WHERE id = v_parent_id)
                  || '-' || LPAD(v_seq::TEXT, 3, '0');

    -- إنشاء الحساب الفرعي
    INSERT INTO chart_of_accounts (
        id, account_code, name_ar, name_en,
        parent_id, company_id, tenant_id, account_type_id,
        is_group, is_detail, is_system, is_party_account,
        party_id, party_type, current_balance, currency
    ) VALUES (
        gen_random_uuid(), v_new_code,
        NEW.name_ar, NEW.name_en,
        v_parent_id, NEW.company_id, v_tenant_id, v_type_id,
        false, true, false, true,
        NEW.id, 'agent', 0,
        COALESCE((SELECT default_currency FROM companies WHERE id = NEW.company_id), 'USD')
    )
    RETURNING id INTO v_new_id;

    -- ربط الحساب بالوكيل
    NEW.payable_account_id := v_new_id;
    RETURN NEW;
END;
$$;


--
-- Name: auto_create_customer_sub_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.auto_create_customer_sub_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_parent_id UUID;
    v_type_id UUID;
    v_tenant_id UUID;
    v_seq INT;
    v_new_code TEXT;
    v_new_id UUID;
    v_parent_code TEXT;
BEGIN
    -- ═══ تحديد الحساب الأب حسب نوع العميل ═══
    IF NEW.customer_type = 'exchange' THEN
        -- زبائن الصرافة → تحت 133
        SELECT id, account_type_id, account_code
        INTO v_parent_id, v_type_id, v_parent_code
        FROM chart_of_accounts
        WHERE company_id = NEW.company_id
          AND account_code = '133'
          AND (is_group = true OR is_detail = false)
        LIMIT 1;
    ELSE
        -- عملاء عاديون → تحت 1131 أو 113 أو 1130
        SELECT id, account_type_id, account_code
        INTO v_parent_id, v_type_id, v_parent_code
        FROM chart_of_accounts
        WHERE company_id = NEW.company_id
          AND account_code IN ('1131', '113', '1130', '1310', '1311')
          AND (is_group = true OR is_detail = false)
        ORDER BY CASE account_code WHEN '1131' THEN 1 WHEN '113' THEN 2 ELSE 3 END
        LIMIT 1;
    END IF;

    IF v_parent_id IS NULL THEN RETURN NEW; END IF;

    SELECT tenant_id INTO v_tenant_id FROM chart_of_accounts WHERE id = v_parent_id;

    SELECT COUNT(*) + 1 INTO v_seq
    FROM chart_of_accounts WHERE parent_id = v_parent_id AND is_party_account = true;

    v_new_code := v_parent_code || '-' || LPAD(v_seq::TEXT, 3, '0');

    INSERT INTO chart_of_accounts (
        id, account_code, name_ar, name_en,
        parent_id, company_id, tenant_id, account_type_id,
        is_group, is_detail, is_system, is_party_account,
        party_id, party_type, current_balance,
        currency
    ) VALUES (
        gen_random_uuid(), v_new_code, NEW.name_ar, NEW.name_en,
        v_parent_id, NEW.company_id, v_tenant_id, v_type_id,
        false, true, false, true, NEW.id, 'customer', 0,
        COALESCE(NEW.currency, 'USD')
    ) RETURNING id INTO v_new_id;

    NEW.receivable_account_id := v_new_id;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION auto_create_customer_sub_account(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_create_customer_sub_account() IS 'V7.1 — حساب فرعي للعميل: exchange→133, عادي→1131/113';


--
-- Name: auto_create_employee_sub_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.auto_create_employee_sub_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_parent_id UUID;
    v_type_id UUID;
    v_tenant_id UUID;
    v_seq INT;
    v_new_code TEXT;
    v_new_id UUID;
    v_emp_name_ar TEXT;
    v_emp_name_en TEXT;
BEGIN
    -- البحث عن حساب الرواتب المستحقة
    SELECT id, account_type_id INTO v_parent_id, v_type_id
    FROM chart_of_accounts
    WHERE company_id = NEW.company_id
      AND account_code IN ('213', '2120', '2130', '214')
      AND (is_group = true OR is_detail = false)
    ORDER BY CASE account_code WHEN '213' THEN 1 WHEN '2120' THEN 2 WHEN '214' THEN 3 ELSE 4 END
    LIMIT 1;

    IF v_parent_id IS NULL THEN 
        RAISE NOTICE '⚠️ حساب الرواتب (213) غير موجود — تخطي';
        RETURN NEW; 
    END IF;

    SELECT tenant_id INTO v_tenant_id FROM chart_of_accounts WHERE id = v_parent_id;

    -- حساب التسلسل (تجاهل الحساب الملخص)
    SELECT COUNT(*) + 1 INTO v_seq
    FROM chart_of_accounts 
    WHERE parent_id = v_parent_id 
      AND is_party_account = true;

    v_new_code := (SELECT account_code FROM chart_of_accounts WHERE id = v_parent_id)
                  || '-' || LPAD(v_seq::TEXT, 3, '0');

    v_emp_name_ar := TRIM(NEW.first_name_ar || ' ' || COALESCE(NEW.last_name_ar, ''));
    v_emp_name_en := TRIM(COALESCE(NEW.first_name_en, '') || ' ' || COALESCE(NEW.last_name_en, ''));

    INSERT INTO chart_of_accounts (
        id, account_code, name_ar, name_en,
        parent_id, company_id, tenant_id, account_type_id,
        is_group, is_detail, is_system, is_party_account,
        party_id, party_type, current_balance
    ) VALUES (
        gen_random_uuid(), v_new_code, v_emp_name_ar, v_emp_name_en,
        v_parent_id, NEW.company_id, v_tenant_id, v_type_id,
        false, true, false, true, NEW.id, 'employee', 0
    ) RETURNING id INTO v_new_id;

    NEW.payable_account_id := v_new_id;

    RAISE NOTICE '✅ حساب فرعي للموظف: % (كود: %)', v_emp_name_ar, v_new_code;
    RETURN NEW;
END;
$$;


