--
-- Name: auto_create_invoice_due_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.auto_create_invoice_due_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF NEW.due_date IS NOT NULL AND NEW.stage = 'confirmed' THEN
    INSERT INTO crm_tasks (
      tenant_id, company_id, title, description,
      task_category, priority, status, due_date,
      related_entity_type, related_entity_id,
      color, created_by
    ) VALUES (
      NEW.tenant_id,
      NEW.company_id,
      'متابعة تحصيل فاتورة ' || NEW.id::text,
      'متابعة تحصيل فاتورة بقيمة ' || COALESCE(NEW.total_amount::text, '0'),
      'invoice_due',
      CASE WHEN NEW.due_date < NOW() + INTERVAL '3 days' THEN 'high' ELSE 'medium' END,
      'pending',
      NEW.due_date,
      'sales_transaction',
      NEW.id,
      '#ef4444',
      NEW.created_by
    ) ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_create_partner_sub_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.auto_create_partner_sub_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_parent_id UUID;
    v_type_id UUID;
    v_tenant_id UUID;
    v_seq INT;
    v_new_code TEXT;
    v_new_id UUID;
BEGIN
    -- البحث عن الحساب الأب (135 = حسابات الشركاء الجارية)
    SELECT id, account_type_id INTO v_parent_id, v_type_id
    FROM chart_of_accounts
    WHERE company_id = NEW.company_id
      AND account_code IN ('135', '1350', '1351')
      AND (is_group = true OR is_detail = false)
    ORDER BY
        CASE account_code
            WHEN '135' THEN 1
            WHEN '1350' THEN 2
            ELSE 3
        END
    LIMIT 1;

    IF v_parent_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT tenant_id INTO v_tenant_id
    FROM chart_of_accounts WHERE id = v_parent_id;

    -- تسلسل الرقم
    SELECT COUNT(*) + 1 INTO v_seq
    FROM chart_of_accounts
    WHERE parent_id = v_parent_id AND is_party_account = true;

    v_new_code := (SELECT account_code FROM chart_of_accounts WHERE id = v_parent_id)
                  || '-' || LPAD(v_seq::TEXT, 3, '0');

    -- إنشاء الحساب الفرعي
    INSERT INTO chart_of_accounts (
        id, account_code, name_ar, name_en,
        parent_id, company_id, tenant_id, account_type_id,
        is_group, is_detail, is_system, is_party_account,
        party_id, party_type, current_balance, currency
    ) VALUES (
        gen_random_uuid(), v_new_code,
        NEW.name_ar, NEW.name_en,
        v_parent_id, NEW.company_id, v_tenant_id, v_type_id,
        false, true, false, true,
        NEW.id, 'partner', 0,
        COALESCE((SELECT default_currency FROM companies WHERE id = NEW.company_id), 'USD')
    )
    RETURNING id INTO v_new_id;

    -- ربط الحساب بالشريك
    NEW.payable_account_id := v_new_id;
    RETURN NEW;
END;
$$;


--
-- Name: auto_create_supplier_sub_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.auto_create_supplier_sub_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_parent_id UUID;
    v_type_id UUID;
    v_tenant_id UUID;
    v_seq INT;
    v_new_code TEXT;
    v_new_id UUID;
BEGIN
    SELECT id, account_type_id INTO v_parent_id, v_type_id
    FROM chart_of_accounts
    WHERE company_id = NEW.company_id
      AND account_code IN ('2111', '211', '2110')
      AND (is_group = true OR is_detail = false)
    ORDER BY CASE account_code WHEN '2111' THEN 1 WHEN '211' THEN 2 ELSE 3 END
    LIMIT 1;

    IF v_parent_id IS NULL THEN RETURN NEW; END IF;

    SELECT tenant_id INTO v_tenant_id FROM chart_of_accounts WHERE id = v_parent_id;

    SELECT COUNT(*) + 1 INTO v_seq
    FROM chart_of_accounts WHERE parent_id = v_parent_id AND is_party_account = true;

    v_new_code := (SELECT account_code FROM chart_of_accounts WHERE id = v_parent_id)
                  || '-' || LPAD(v_seq::TEXT, 3, '0');

    INSERT INTO chart_of_accounts (
        id, account_code, name_ar, name_en,
        parent_id, company_id, tenant_id, account_type_id,
        is_group, is_detail, is_system, is_party_account,
        party_id, party_type, current_balance
    ) VALUES (
        gen_random_uuid(), v_new_code, NEW.name_ar, NEW.name_en,
        v_parent_id, NEW.company_id, v_tenant_id, v_type_id,
        false, true, false, true, NEW.id, 'supplier', 0
    ) RETURNING id INTO v_new_id;

    NEW.payable_account_id := v_new_id;
    RETURN NEW;
END;
$$;


