--
-- Name: auto_setup_chart_templates_for_new_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.auto_setup_chart_templates_for_new_tenant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- تجهيز القوالب للتينانت الجديد
    BEGIN
        PERFORM setup_chart_templates_for_tenant(NEW.id);
        RAISE NOTICE '✅ تم تجهيز القوالب المحاسبية للتينانت الجديد: %', NEW.id;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING '⚠️  فشل تجهيز القوالب للتينانت %: %', NEW.id, SQLERRM;
    END;
    
    RETURN NEW;
END;
$$;


