--
-- Name: can_delegate_to_role(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.can_delegate_to_role(p_user_id uuid, p_target_role_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_can_delegate BOOLEAN := false;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM user_roles ur
        JOIN role_delegations rd ON ur.role_id = rd.delegator_role_id
        JOIN roles target_role ON rd.delegatee_role_id = target_role.id
        WHERE ur.user_id = p_user_id
          AND ur.is_active = true
          AND rd.can_manage_users = true
          AND target_role.id = p_target_role_id
    ) INTO v_can_delegate;
    
    RETURN v_can_delegate;
END;
$$;


--
-- Name: can_edit_journal_entry(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.can_edit_journal_entry(p_entry_id uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_entry RECORD;
    v_period RECORD;
    v_fiscal_year RECORD;
    v_settings JSONB;
    v_mode VARCHAR;
BEGIN
    SELECT * INTO v_entry FROM journal_entries WHERE id = p_entry_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('can_edit', false, 'reason', 'entry_not_found', 'message', 'القيد غير موجود');
    END IF;
    
    SELECT COALESCE(accounting_settings, '{}'::jsonb) INTO v_settings FROM companies WHERE id = v_entry.company_id;
    v_mode := COALESCE(v_settings->>'fiscal_year_mode', 'independent');
    
    SELECT * INTO v_period FROM accounting_periods WHERE id = v_entry.period_id;
    SELECT * INTO v_fiscal_year FROM fiscal_years WHERE id = v_entry.fiscal_year_id;
    
    IF NOT v_entry.is_posted THEN
        RETURN jsonb_build_object('can_edit', true, 'mode', 'direct', 'message', 'القيد مسودة');
    END IF;
    
    IF (v_fiscal_year IS NULL OR v_fiscal_year.status = 'open') AND 
       (v_period IS NULL OR v_period.status = 'open') THEN
        RETURN jsonb_build_object('can_edit', true, 'mode', 'unpost_edit_repost', 'auto_unpost', true);
    END IF;
    
    IF v_fiscal_year IS NOT NULL AND v_fiscal_year.status = 'closed' AND v_mode = 'independent' THEN
        RETURN jsonb_build_object(
            'can_edit', COALESCE((v_settings->'closed_year_settings'->>'allow_edit_closed_year')::boolean, true),
            'mode', 'independent_closed_year',
            'require_reason', true
        );
    END IF;
    
    IF v_fiscal_year IS NOT NULL AND v_fiscal_year.status = 'closed' AND v_mode = 'linked' THEN
        RETURN jsonb_build_object('can_edit', false, 'mode', 'linked_closed_year');
    END IF;
    
    RETURN jsonb_build_object('can_edit', true, 'mode', 'default');
END;
$$;


--
-- Name: can_enable_mfa(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.can_enable_mfa(p_user_id uuid) RETURNS TABLE(can_enable boolean, reason_ar text, reason_en text, missing_fields text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_email TEXT;
    v_phone TEXT;
    v_full_name TEXT;
    v_system_enabled BOOLEAN;
    v_require_profile BOOLEAN;
    v_missing TEXT[] := ARRAY[]::TEXT[];
BEGIN
    -- التحقق من إعدادات النظام
    SELECT is_enabled, require_complete_profile 
    INTO v_system_enabled, v_require_profile
    FROM mfa_system_settings LIMIT 1;
    
    -- إذا الخدمة معطلة على مستوى النظام
    IF NOT COALESCE(v_system_enabled, false) THEN
        RETURN QUERY SELECT 
            false,
            'خدمة التحقق بخطوتين معطلة حالياً'::TEXT,
            'Two-factor authentication is currently disabled'::TEXT,
            ARRAY[]::TEXT[];
        RETURN;
    END IF;
    
    -- الحصول على بيانات المستخدم
    SELECT 
        COALESCE(up.email, au.email),
        up.phone,
        up.full_name
    INTO v_email, v_phone, v_full_name
    FROM user_profiles up
    LEFT JOIN auth.users au ON au.id = up.id
    WHERE up.id = p_user_id;
    
    -- التحقق من اكتمال البيانات إذا مطلوب
    IF v_require_profile THEN
        IF v_email IS NULL OR v_email = '' THEN
            v_missing := array_append(v_missing, 'email');
        END IF;
        
        IF v_full_name IS NULL OR v_full_name = '' THEN
            v_missing := array_append(v_missing, 'full_name');
        END IF;
    END IF;
    
    -- إذا هناك حقول ناقصة
    IF array_length(v_missing, 1) > 0 THEN
        RETURN QUERY SELECT 
            false,
            'يرجى إكمال بياناتك الشخصية أولاً'::TEXT,
            'Please complete your profile first'::TEXT,
            v_missing;
        RETURN;
    END IF;
    
    -- المستخدم مؤهل
    RETURN QUERY SELECT 
        true,
        'يمكنك تفعيل التحقق بخطوتين'::TEXT,
        'You can enable two-factor authentication'::TEXT,
        ARRAY[]::TEXT[];
END;
$$;


--
-- Name: can_user_see_module(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.can_user_see_module(p_user_id uuid, p_module_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1
        FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE ur.user_id = p_user_id
          AND ur.is_active = true
          AND p_module_code = ANY(r.visible_modules)
    );
END;
$$;


--
-- Name: cancel_ecom_order_cascade(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.cancel_ecom_order_cascade(p_order_id uuid, p_reason text DEFAULT 'cancelled'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order RECORD;
  v_released int := 0;
  v_po_cancelled int := 0;
  v_inv_voided int := 0;
  v_posted_kept int := 0;
  v_received numeric := 0;
  v_refund_pending numeric := 0;
  v_warnings text[] := ARRAY[]::text[];
BEGIN
  SELECT id, tenant_id, status, sales_order_id, sales_invoice_id,
         total_amount, paid_amount, cod_received, cod_received_amount,
         refund_amount, refund_status
    INTO v_order
  FROM ecommerce_orders WHERE id = p_order_id;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_not_found');
  END IF;

  -- 🔒 حارس العزل: المستدعي من نفس tenant الطلب (أو super admin)
  IF is_super_admin() IS NOT TRUE
     AND v_order.tenant_id IS DISTINCT FROM get_current_tenant_id() THEN
    RETURN jsonb_build_object('success', false, 'error', 'forbidden_cross_tenant');
  END IF;

  -- ① تحرير حجوزات المخزون غير المخصومة
  UPDATE ecommerce_stock_reservations
  SET status = 'released', released_at = now()
  WHERE order_id = p_order_id
    AND status NOT IN ('released', 'deducted');
  GET DIAGNOSTICS v_released = ROW_COUNT;

  -- ② إلغاء صفوف الموردين
  UPDATE ecommerce_order_suppliers
  SET status = 'cancelled', updated_at = now()
  WHERE order_id = p_order_id
    AND COALESCE(status, '') NOT IN ('cancelled', 'fulfilled');

  -- ③ إلغاء أوامر الشراء المرتبطة (إن لم تُستلم بضاعتها)
  UPDATE purchase_orders po
  SET status = 'cancelled', updated_at = now()
  WHERE po.id IN (
      SELECT DISTINCT eos.purchase_order_id
      FROM ecommerce_order_suppliers eos
      WHERE eos.order_id = p_order_id AND eos.purchase_order_id IS NOT NULL
    )
    AND COALESCE(po.status, '') NOT IN ('cancelled', 'received', 'completed', 'closed');
  GET DIAGNOSTICS v_po_cancelled = ROW_COUNT;

  -- ④ فاتورة/أمر المبيعات: إبطال إن لم يُرحَّل، وإلا إبقاء + تنبيه
  IF v_order.sales_invoice_id IS NOT NULL THEN
    PERFORM 1 FROM sales_transactions
      WHERE id = v_order.sales_invoice_id
        AND stage IN ('delivered', 'posted', 'completed');
    IF FOUND THEN
      v_posted_kept := 1;
      v_warnings := array_append(v_warnings,
        'الفاتورة مُرحَّلة محاسبياً — يلزم مرتجع/إشعار دائن يدوي لعكس القيد');
      UPDATE sales_transactions
      SET notes = COALESCE(notes, '') || E'\n⚠️ أُلغي الطلب الإلكتروني المصدر — يلزم مرتجع لعكس القيد.',
          updated_at = now()
      WHERE id = v_order.sales_invoice_id;
    ELSE
      UPDATE sales_transactions
      SET is_active = false, stage = 'cancelled', updated_at = now()
      WHERE id = v_order.sales_invoice_id;
      v_inv_voided := 1;
    END IF;
  END IF;

  -- أمر المبيعات (إن وُجد منفصلاً)
  IF v_order.sales_order_id IS NOT NULL THEN
    UPDATE sales_orders
    SET status = 'cancelled', updated_at = now()
    WHERE id = v_order.sales_order_id
      AND COALESCE(status, '') NOT IN ('cancelled', 'delivered', 'completed');
  END IF;

  -- ⑤ المبلغ المقبوض → استرداد معلّق + تنبيه (بلا قيد تلقائي)
  v_received := GREATEST(
    COALESCE(v_order.paid_amount, 0),
    CASE WHEN v_order.cod_received THEN COALESCE(v_order.cod_received_amount, 0) ELSE 0 END
  );
  IF v_received > 0
     AND COALESCE(v_order.refund_amount, 0) = 0
     AND COALESCE(v_order.refund_status, '') <> 'completed' THEN
    UPDATE ecommerce_orders
    SET refund_amount = v_received,
        refund_status = 'pending',
        updated_at = now()
    WHERE id = p_order_id;
    v_refund_pending := v_received;
    v_warnings := array_append(v_warnings,
      format('استُلم %s من العميل — سُجّل استرداد معلّق؛ يلزم إشعار دائن/إعادة دفع يدوي', v_received));
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'reservations_released', v_released,
    'purchase_orders_cancelled', v_po_cancelled,
    'invoice_voided', v_inv_voided,
    'invoice_posted_kept', v_posted_kept,
    'refund_pending', v_refund_pending,
    'warnings', to_jsonb(v_warnings)
  );
END;
$$;


