--
-- Name: check_row_access(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.check_row_access(p_tenant_id uuid, p_company_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_user_tenant_id UUID;
BEGIN
    -- Platform Owner يرى كل شيء
    IF is_platform_owner(p_user_id) THEN
        RETURN true;
    END IF;
    
    -- ═══ الخطوة 1: التحقق من البراند ═══
    -- التحقق من أن التينانت ينتمي لنفس البراند
    IF NOT is_same_brand(p_tenant_id, p_user_id) THEN
        RETURN false;
    END IF;
    
    -- ═══ الخطوة 2: التحقق من التينانت ═══
    -- Partner/Reseller: يرى تينانتاته فقط
    IF is_partner_or_reseller(p_user_id) THEN
        IF p_tenant_id = ANY(get_partner_tenant_ids(p_user_id)) THEN
            -- إذا لم يتم تحديد company_id، التحقق من tenant فقط
            IF p_company_id IS NULL THEN
                RETURN true;
            END IF;
            -- التحقق من صلاحية الوصول للشركة
            RETURN can_access_company(p_company_id, p_user_id);
        END IF;
        RETURN false;
    END IF;
    
    -- الحصول على tenant_id للمستخدم
    v_user_tenant_id := get_user_tenant_id(p_user_id);
    
    -- التحقق من الانتماء لنفس التينانت
    IF v_user_tenant_id IS NULL OR v_user_tenant_id != p_tenant_id THEN
        RETURN false;
    END IF;
    
    -- ═══ الخطوة 3: التحقق من الشركة ═══
    -- إذا لم يتم تحديد company_id، التحقق من tenant فقط
    IF p_company_id IS NULL THEN
        RETURN true;
    END IF;
    
    -- التحقق من صلاحية الوصول للشركة
    RETURN can_access_company(p_company_id, p_user_id);
EXCEPTION WHEN OTHERS THEN
    RETURN false;
END;
$$;


--
-- Name: check_special_permission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.check_special_permission(p_user_id uuid, p_perm_name text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_has_permission BOOLEAN := false;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE ur.user_id = p_user_id
          AND ur.is_active = true
          AND (ur.expires_at IS NULL OR ur.expires_at > NOW())
          AND (
              -- super_admin / tenant_owner / company_owner always have all permissions
              r.code IN ('super_admin', 'tenant_owner', 'company_owner')
              -- Or the role explicitly has this special permission
              OR (r.special_permissions IS NOT NULL 
                  AND (r.special_permissions ->> p_perm_name)::boolean = true)
          )
    ) INTO v_has_permission;
    
    RETURN v_has_permission;
END;
$$;


--
-- Name: check_subscription_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.check_subscription_access(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
    v_subscription RECORD;
    v_days_remaining INT;
    v_access_level TEXT;
    v_result JSONB;
BEGIN
    v_tenant_id := COALESCE(p_tenant_id, get_current_tenant_id());
    
    IF v_tenant_id IS NULL THEN
        RETURN jsonb_build_object(
            'access_level', 'denied',
            'reason', 'no_tenant'
        );
    END IF;
    
    -- الحصول على الاشتراك
    SELECT * INTO v_subscription
    FROM subscriptions
    WHERE tenant_id = v_tenant_id
    ORDER BY created_at DESC
    LIMIT 1;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'access_level', 'denied',
            'reason', 'no_subscription'
        );
    END IF;
    
    -- التحقق من القفل
    IF v_subscription.locked_at IS NOT NULL THEN
        RETURN jsonb_build_object(
            'access_level', 'locked',
            'reason', v_subscription.lock_reason,
            'locked_at', v_subscription.locked_at
        );
    END IF;
    
    -- حساب الأيام المتبقية
    v_days_remaining := GREATEST(0, 
        (v_subscription.current_period_end::date - CURRENT_DATE)
    );
    
    -- تحديد مستوى الوصول
    IF v_days_remaining <= 0 THEN
        v_access_level := 'expired';
    ELSIF v_days_remaining <= 3 THEN
        v_access_level := 'critical_warning';
    ELSIF v_days_remaining <= 7 THEN
        v_access_level := 'warning';
    ELSE
        v_access_level := 'full';
    END IF;
    
    RETURN jsonb_build_object(
        'access_level', v_access_level,
        'status', v_subscription.status,
        'days_remaining', v_days_remaining,
        'period_end', v_subscription.current_period_end,
        'plan_id', v_subscription.plan_id
    );
END;
$$;


--
-- Name: check_trusted_device(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.check_trusted_device(p_token text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_found boolean;
BEGIN
    -- تنظيف المنتهية
    DELETE FROM trusted_devices WHERE trusted_until < NOW();
    
    -- تحقق + تحديث آخر استخدام
    UPDATE trusted_devices
    SET last_used_at = NOW(),
        last_ip = (SELECT ip::text FROM auth.sessions WHERE user_id = auth.uid() ORDER BY updated_at DESC LIMIT 1)
    WHERE device_token = p_token 
    AND user_id = auth.uid()
    AND trusted_until > NOW()
    RETURNING true INTO v_found;
    
    RETURN COALESCE(v_found, false);
END;
$$;


--
-- Name: check_user_module_permission(uuid, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.check_user_module_permission(p_user_id uuid, p_module_code character varying, p_permission_type character varying DEFAULT 'view'::character varying) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_has_permission BOOLEAN;
    v_tenant_id UUID;
    v_company_id UUID;
    v_is_admin BOOLEAN;
BEGIN
    -- الحصول على معلومات المستخدم
    SELECT tenant_id, company_id, is_admin
    INTO v_tenant_id, v_company_id, v_is_admin
    FROM user_profiles
    WHERE id = p_user_id;
    
    -- إذا كان admin، لديه كل الصلاحيات
    IF v_is_admin THEN
        RETURN true;
    END IF;
    
    -- التحقق من الصلاحية المحددة
    SELECT 
        CASE p_permission_type
            WHEN 'view' THEN can_view
            WHEN 'create' THEN can_create
            WHEN 'edit' THEN can_edit
            WHEN 'delete' THEN can_delete
            WHEN 'export' THEN can_export
            WHEN 'import' THEN can_import
            WHEN 'approve' THEN can_approve
            WHEN 'manage_settings' THEN can_manage_settings
            ELSE false
        END
    INTO v_has_permission
    FROM user_module_permissions
    WHERE user_id = p_user_id
      AND tenant_id = v_tenant_id
      AND company_id = v_company_id
      AND module_code = p_module_code
      AND is_active = true
      AND (expires_at IS NULL OR expires_at > NOW());
    
    RETURN COALESCE(v_has_permission, false);
END;
$$;


--
-- Name: check_user_permission(uuid, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.check_user_permission(p_user_id uuid, p_module character varying, p_permission character varying) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_has_permission BOOLEAN := false;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE ur.user_id = p_user_id
          AND ur.is_active = true
          AND (ur.expires_at IS NULL OR ur.expires_at > NOW())
          AND (
              r.permissions->>'all' = 'true'
              OR p_permission = ANY(SELECT jsonb_array_elements_text(r.permissions->p_module))
          )
    ) INTO v_has_permission;
    
    RETURN v_has_permission;
END;
$$;


--
-- Name: check_user_resource_access(uuid, character varying, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.check_user_resource_access(p_user_id uuid, p_resource_type character varying, p_resource_id uuid, p_permission character varying DEFAULT 'read'::character varying) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_has_access BOOLEAN := false;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM user_resource_access ura
        WHERE ura.user_id = p_user_id
          AND ura.resource_type = p_resource_type
          AND ura.resource_id = p_resource_id
          AND (ura.expires_at IS NULL OR ura.expires_at > NOW())
          AND (ura.permissions->>p_permission)::boolean = true
    ) INTO v_has_access;
    
    RETURN v_has_access;
END;
$$;


--
-- Name: check_visibility(uuid, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.check_visibility(p_user_id uuid, p_rule_type character varying, p_target_type character varying, p_target_name character varying) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_is_visible BOOLEAN := true;
    v_user_roles UUID[];
BEGIN
    -- Get user's role IDs
    SELECT ARRAY_AGG(role_id) INTO v_user_roles
    FROM user_roles
    WHERE user_id = p_user_id AND is_active = true;
    
    -- Check if any visibility rule applies
    SELECT NOT EXISTS (
        SELECT 1
        FROM visibility_rules vr
        WHERE vr.rule_type = p_rule_type
          AND vr.target_type = p_target_type
          AND vr.target_name = p_target_name
          AND vr.is_active = true
          AND NOT (vr.visible_to_roles && v_user_roles)
    ) INTO v_is_visible;
    
    RETURN v_is_visible;
END;
$$;


--
-- Name: check_white_label_validity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.check_white_label_validity(p_agent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_agent RECORD;
BEGIN
    SELECT * INTO v_agent FROM agents WHERE id = p_agent_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('valid', false, 'reason', 'الوكيل غير موجود');
    END IF;
    
    IF NOT v_agent.has_white_label THEN
        RETURN jsonb_build_object('valid', false, 'reason', 'الوكيل غير مفعل لـ White Label');
    END IF;
    
    IF v_agent.white_label_status != 'active' THEN
        RETURN jsonb_build_object('valid', false, 'reason', 'White Label غير نشط', 'status', v_agent.white_label_status);
    END IF;
    
    IF v_agent.white_label_expires_at IS NOT NULL AND v_agent.white_label_expires_at < NOW() THEN
        -- تحديث الحالة تلقائياً
        UPDATE agents SET white_label_status = 'expired' WHERE id = p_agent_id;
        RETURN jsonb_build_object('valid', false, 'reason', 'White Label منتهي الصلاحية');
    END IF;
    
    RETURN jsonb_build_object(
        'valid', true,
        'expires_at', v_agent.white_label_expires_at,
        'commission_percent', v_agent.white_label_commission_percent
    );
END;
$$;


--
-- Name: cleanup_container_transit_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.cleanup_container_transit_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_has_entries BOOLEAN;
BEGIN
    -- Skip if no container_account_id
    IF OLD.container_account_id IS NULL THEN
        RETURN OLD;
    END IF;

    -- Check if the account has any journal entry lines
    SELECT EXISTS(
        SELECT 1 FROM journal_entry_lines 
        WHERE account_id = OLD.container_account_id
        LIMIT 1
    ) INTO v_has_entries;

    IF v_has_entries THEN
        -- Account has transactions → deactivate only (preserve audit trail)
        UPDATE chart_of_accounts 
        SET is_active = false
        WHERE id = OLD.container_account_id;
    ELSE
        -- No transactions → safe to delete the account
        -- Clear references in container_expenses first
        UPDATE container_expenses SET container_account_id = NULL 
        WHERE container_account_id = OLD.container_account_id;
        
        DELETE FROM chart_of_accounts 
        WHERE id = OLD.container_account_id;
    END IF;

    RETURN OLD;
END;
$$;


--
-- Name: cleanup_expired_guest_checkouts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.cleanup_expired_guest_checkouts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_deleted_count INT;
BEGIN
    -- حذف guest_checkouts المنتهية والتي لم يتم استخدامها
    DELETE FROM guest_checkouts
    WHERE expires_at < NOW()
      AND status = 'pending'
      AND NOT EXISTS (
          SELECT 1 FROM orders 
          WHERE orders.guest_checkout_id = guest_checkouts.id
      );
    
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    
    RETURN v_deleted_count;
END;
$$;


--
-- Name: cleanup_expired_otps(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.cleanup_expired_otps() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    DELETE FROM mfa_pending_otps WHERE expires_at < NOW();
END;
$$;


--
-- Name: cleanup_expired_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.cleanup_expired_sessions() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    DELETE FROM active_sessions 
    WHERE last_active_at < NOW() - INTERVAL '24 hours';
    
    UPDATE user_profiles 
    SET is_online = FALSE 
    WHERE is_online = TRUE 
    AND last_active_at < NOW() - INTERVAL '5 minutes';
END;
$$;


--
-- Name: cleanup_old_login_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.cleanup_old_login_history() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    DELETE FROM login_history 
    WHERE login_at < NOW() - INTERVAL '90 days';
END;
$$;


--
-- Name: cleanup_sales_invoice_journal_entries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.cleanup_sales_invoice_journal_entries() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- حذف قيد المبيعات الرئيسي
    IF OLD.journal_entry_id IS NOT NULL THEN
        DELETE FROM journal_entry_lines WHERE entry_id = OLD.journal_entry_id;
        DELETE FROM journal_entries WHERE id = OLD.journal_entry_id;
    END IF;
    
    -- حذف قيد COGS المنفصل
    IF OLD.cogs_journal_entry_id IS NOT NULL THEN
        DELETE FROM journal_entry_lines WHERE entry_id = OLD.cogs_journal_entry_id;
        DELETE FROM journal_entries WHERE id = OLD.cogs_journal_entry_id;
    END IF;
    
    -- حذف أي قيود إضافية مرتبطة بنفس الفاتورة عبر reference_id
    DELETE FROM journal_entry_lines
    WHERE entry_id IN (
        SELECT id FROM journal_entries 
        WHERE reference_id = OLD.id 
          AND reference_type IN ('sales_invoice', 'sales_cogs')
    );
    
    DELETE FROM journal_entries
    WHERE reference_id = OLD.id
      AND reference_type IN ('sales_invoice', 'sales_cogs');
    
    RETURN OLD;
END;
$$;


--
-- Name: cleanup_stale_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.cleanup_stale_sessions() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE deleted_count INT;
BEGIN
  DELETE FROM public.active_sessions
  WHERE last_heartbeat < NOW() - INTERVAL '2 minutes';
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


--
-- Name: clear_cart(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.clear_cart(p_tenant_id uuid, p_customer_id uuid DEFAULT NULL::uuid, p_session_id character varying DEFAULT NULL::character varying) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_cart_id UUID;
BEGIN
    -- الحصول على السلة
    IF p_customer_id IS NOT NULL THEN
        SELECT id INTO v_cart_id
        FROM shopping_carts
        WHERE tenant_id = p_tenant_id
          AND customer_id = p_customer_id
          AND status = 'active'
        LIMIT 1;
    ELSIF p_session_id IS NOT NULL THEN
        SELECT id INTO v_cart_id
        FROM shopping_carts
        WHERE tenant_id = p_tenant_id
          AND session_id = p_session_id
          AND status = 'active'
        LIMIT 1;
    END IF;
    
    IF v_cart_id IS NULL THEN
        RETURN false;
    END IF;
    
    -- حذف جميع العناصر
    DELETE FROM shopping_cart_items WHERE cart_id = v_cart_id;
    
    -- تحديث المجاميع
    PERFORM update_cart_totals(v_cart_id);
    
    RETURN TRUE;
END;
$$;


--
-- Name: complete_stock_count(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.complete_stock_count(p_stock_count_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_count_record stock_counts%ROWTYPE;
    v_total_items INT := 0;
    v_counted_items INT := 0;
    v_match_count INT := 0;
    v_variance_count INT := 0;
BEGIN
    -- Get stock count
    SELECT * INTO v_count_record
    FROM stock_counts
    WHERE id = p_stock_count_id;
    
    IF v_count_record IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Stock count not found');
    END IF;
    
    IF v_count_record.status = 'completed' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Stock count already completed');
    END IF;
    
    -- Calculate stats
    SELECT 
        COUNT(*),
        COUNT(*) FILTER (WHERE is_counted = true),
        COUNT(*) FILTER (WHERE is_counted = true AND variance = 0),
        COUNT(*) FILTER (WHERE is_counted = true AND variance != 0)
    INTO v_total_items, v_counted_items, v_match_count, v_variance_count
    FROM stock_count_items
    WHERE stock_count_id = p_stock_count_id;
    
    -- Update stock count
    UPDATE stock_counts SET
        status = 'completed',
        completed_date = CURRENT_DATE,
        completed_by = p_user_id,
        total_items = v_total_items,
        counted_items = v_counted_items,
        match_count = v_match_count,
        variance_count = v_variance_count,
        updated_at = NOW()
    WHERE id = p_stock_count_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'message', 'Stock count completed',
        'stats', jsonb_build_object(
            'total_items', v_total_items,
            'counted_items', v_counted_items,
            'match_count', v_match_count,
            'variance_count', v_variance_count
        )
    );
END;
$$;


--
-- Name: confirm_delivery(uuid, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.confirm_delivery(p_note_id uuid, p_receiver_name character varying DEFAULT NULL::character varying, p_signature text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    UPDATE delivery_notes
    SET 
        status = 'delivered',
        delivered_at = NOW(),
        receiver_name = COALESCE(p_receiver_name, receiver_name),
        receiver_signature = COALESCE(p_signature, receiver_signature)
    WHERE id = p_note_id;
    
    UPDATE delivery_note_items
    SET quantity_delivered = quantity_to_deliver
    WHERE delivery_note_id = p_note_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'note_id', p_note_id,
        'status', 'delivered'
    );
END;
$$;


--
-- Name: confirm_email_verification(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.confirm_email_verification(p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_email text;
BEGIN
  UPDATE public.user_profiles
    SET email_verified = true, email_verify_token = NULL, email_verify_expires = NULL
    WHERE email_verify_token = p_token AND COALESCE(email_verify_expires, now()) > now()
    RETURNING email INTO v_email;
  IF v_email IS NULL THEN
    -- إمّا رمز مستخدَم/منتهٍ، أو مؤكّد أصلاً
    RETURN jsonb_build_object('success', false, 'error', 'invalid_or_expired');
  END IF;
  RETURN jsonb_build_object('success', true, 'email', v_email);
END;
$$;


--
-- Name: confirm_pending_payment(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.confirm_pending_payment(p_id uuid, p_amount numeric DEFAULT NULL::numeric, p_sales_transaction_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_company uuid; v_tenant uuid; v_atype text; v_adata jsonb; v_user uuid := auth.uid();
    v_party uuid; v_party_name text; v_amount numeric; v_fund uuid; v_num text; v_doc uuid; v_inv uuid;
BEGIN
    SELECT company_id, tenant_id, action_type, action_data
      INTO v_company, v_tenant, v_atype, v_adata
      FROM pending_actions WHERE id=p_id AND status='pending';
    IF v_company IS NULL THEN RETURN jsonb_build_object('ok',false,'message','المسودة غير موجودة أو مؤكَّدة'); END IF;
    PERFORM assert_can_access_company(v_company);
    v_amount := COALESCE(p_amount, NULLIF(v_adata->>'amount','')::numeric);
    IF v_amount IS NULL OR v_amount <= 0 THEN RETURN jsonb_build_object('ok',false,'message','مبلغ غير صالح'); END IF;
    v_inv := COALESCE(p_sales_transaction_id, NULLIF(COALESCE(v_adata->>'sales_transaction_id', v_adata->>'invoice_id'),'')::uuid);
    v_fund := resolve_payment_fund(v_adata, v_company, v_user);
    IF v_fund IS NULL THEN RETURN jsonb_build_object('ok',false,'message','لا صندوق متاح — حدّد الصندوق قبل التأكيد'); END IF;

    IF v_atype = 'payment_received' THEN
        v_party_name := COALESCE(v_adata->>'from_name', v_adata->>'from_customer', v_adata->>'customer_name');
        v_party := NULLIF(v_adata->>'customer_id','')::uuid;
        IF v_party IS NULL AND v_party_name IS NOT NULL THEN
            SELECT id INTO v_party FROM customers WHERE company_id=v_company
              AND (name_ar ILIKE '%'||v_party_name||'%' OR name_en ILIKE '%'||v_party_name||'%' OR company_name ILIKE '%'||v_party_name||'%') LIMIT 1;
        END IF;
        IF v_party IS NULL THEN RETURN jsonb_build_object('ok',false,'message','تعذّر مطابقة العميل: '||COALESCE(v_party_name,'؟')); END IF;
        v_num := 'RCV-TG-'||to_char(now(),'YYMMDDHH24MISS');
        INSERT INTO payment_receipts(company_id,tenant_id,receipt_number,receipt_date,customer_id,customer_name,amount,payment_method,status,treasury_account_id,sales_transaction_id,created_by,notes)
          VALUES(v_company,v_tenant,v_num,CURRENT_DATE,v_party,v_party_name,v_amount,'cash','confirmed',v_fund,v_inv,v_user,'من مسودة تلغرام') RETURNING id INTO v_doc;
            PERFORM relink_telegram_doc(p_id, 'payment_receipt', v_doc);

    ELSIF v_atype = 'payment_made' THEN
        v_party_name := COALESCE(v_adata->>'to_name', v_adata->>'supplier_name');
        v_party := NULLIF(v_adata->>'supplier_id','')::uuid;
        IF v_party IS NULL AND v_party_name IS NOT NULL THEN
            SELECT id INTO v_party FROM suppliers WHERE company_id=v_company
              AND (name_ar ILIKE '%'||v_party_name||'%' OR name_en ILIKE '%'||v_party_name||'%' OR company_name ILIKE '%'||v_party_name||'%') LIMIT 1;
        END IF;
        IF v_party IS NULL THEN RETURN jsonb_build_object('ok',false,'message','تعذّر مطابقة المورد: '||COALESCE(v_party_name,'؟')); END IF;
        v_num := 'PAY-TG-'||to_char(now(),'YYMMDDHH24MISS');
        INSERT INTO payment_vouchers(company_id,tenant_id,voucher_number,voucher_date,supplier_id,supplier_name,amount,payment_method,status,treasury_account_id,created_by,notes)
          VALUES(v_company,v_tenant,v_num,CURRENT_DATE,v_party,v_party_name,v_amount,'cash','confirmed',v_fund,v_user,'من مسودة تلغرام') RETURNING id INTO v_doc;
            PERFORM relink_telegram_doc(p_id, 'payment_voucher', v_doc);
    ELSE
        RETURN jsonb_build_object('ok',false,'message','نوع غير مدعوم');
    END IF;

    UPDATE pending_actions SET status='confirmed', confirmed_at=now(), confirmed_via='web', confirmed_by=v_user WHERE id=p_id;
    RETURN jsonb_build_object('ok',true,'message','تم إنشاء وترحيل السند بمبلغ '||v_amount,'document_id',v_doc);
END $$;


--
-- Name: convert_contact_to_customer(uuid, character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.convert_contact_to_customer(p_contact_id uuid, p_customer_code character varying DEFAULT NULL::character varying, p_customer_type character varying DEFAULT 'individual'::character varying, p_receivable_account_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_contact RECORD;
    v_customer_id UUID;
    v_user_tenant UUID;
    v_code VARCHAR;
BEGIN
    v_user_tenant := get_user_tenant_id();
    
    IF v_user_tenant IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'User has no tenant');
    END IF;
    
    -- جلب بيانات جهة الاتصال
    SELECT * INTO v_contact FROM contacts
    WHERE id = p_contact_id AND tenant_id = v_user_tenant;
    
    IF v_contact.id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Contact not found');
    END IF;
    
    IF v_contact.converted_customer_id IS NOT NULL THEN
        RETURN json_build_object('success', false, 'message', 'Already converted', 
                                 'customer_id', v_contact.converted_customer_id);
    END IF;
    
    -- إنشاء كود تلقائي إن لم يُحدد
    v_code := COALESCE(p_customer_code, 'CUST-' || LPAD(
        (SELECT COALESCE(MAX(CAST(REPLACE(code, 'CUST-', '') AS INT)), 0) + 1 
         FROM customers WHERE tenant_id = v_user_tenant)::TEXT, 5, '0'
    ));
    
    -- إنشاء العميل (نقل الأسماء بنفس النمط)
    INSERT INTO customers (
        tenant_id, company_id, code, customer_type,
        name_ar, name_en, company_name,
        email, phone, mobile, whatsapp,
        country, city, address,
        telegram_username, telegram_chat_id,
        receivable_account_id,
        status, created_by, notes
    ) VALUES (
        v_user_tenant, v_contact.company_id, v_code, p_customer_type,
        COALESCE(v_contact.name_ar, COALESCE(v_contact.first_name, '') || ' ' || COALESCE(v_contact.last_name, '')),
        COALESCE(v_contact.name_en, v_contact.display_name, COALESCE(v_contact.first_name, '') || ' ' || COALESCE(v_contact.last_name, '')),
        v_contact.organization,
        v_contact.email, v_contact.phone, v_contact.mobile, v_contact.whatsapp,
        v_contact.country, v_contact.city, v_contact.address,
        v_contact.telegram_username, v_contact.telegram_chat_id,
        p_receivable_account_id,
        'active', auth.uid(), v_contact.notes
    )
    RETURNING id INTO v_customer_id;
    
    -- تحديث جهة الاتصال
    UPDATE contacts SET
        converted_customer_id = v_customer_id,
        converted_at = NOW(),
        converted_by = auth.uid(),
        lifecycle_stage = 'converted',
        status = 'converted'
    WHERE id = p_contact_id;
    
    -- إضافة تفاعل التحويل
    INSERT INTO contact_interactions (
        tenant_id, contact_id, interaction_type, subject, content, performed_by
    ) VALUES (
        v_user_tenant, p_contact_id, 'status_change', 
        'Converted to Customer',
        'Contact converted to customer with code: ' || v_code,
        auth.uid()
    );
    
    -- ربط المكالمات القديمة بالعميل الجديد
    UPDATE call_logs SET customer_id = v_customer_id
    WHERE contact_id = p_contact_id AND customer_id IS NULL;
    
    RETURN json_build_object(
        'success', true,
        'customer_id', v_customer_id,
        'customer_code', v_code,
        'message', 'Contact converted to customer successfully'
    );
END;
$$;


--
-- Name: convert_currency(numeric, character varying, character varying, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.convert_currency(p_amount numeric, p_from_currency character varying, p_to_currency character varying, p_company_id uuid, p_date timestamp with time zone DEFAULT now()) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_rate DECIMAL(18, 8);
    v_result DECIMAL(15, 2);
BEGIN
    -- Same currency
    IF p_from_currency = p_to_currency THEN
        RETURN p_amount;
    END IF;
    
    -- Get exchange rate (use mid_rate)
    SELECT mid_rate INTO v_rate
    FROM exchange_rates
    WHERE company_id = p_company_id
      AND from_currency = p_from_currency
      AND to_currency = p_to_currency
      AND effective_from <= p_date
      AND (effective_to IS NULL OR effective_to >= p_date)
      AND is_active = true
    ORDER BY effective_from DESC
    LIMIT 1;
    
    IF v_rate IS NULL THEN
        RAISE EXCEPTION 'No exchange rate found for % to % on %', 
            p_from_currency, p_to_currency, p_date;
    END IF;
    
    v_result := ROUND(p_amount * v_rate, 2);
    
    RETURN v_result;
END;
$$;


--
-- Name: convert_guest_order_to_customer(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.convert_guest_order_to_customer(p_tenant_id uuid, p_guest_checkout_id uuid, p_customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_orders_updated INT;
    v_result JSONB;
    v_uid  uuid := auth.uid();
    v_role text := auth.role();
    v_caller_email text;
    v_guest_email text;
BEGIN
    IF NOT (v_role = 'service_role' OR v_role IS NULL) THEN
        -- (أ) ملكية مُتحقَّقة لحساب العميل الهدف — لا نثق بصفّ ecommerce_customers قابل
        --     للإدراج الذاتي. customers.auth_user_id فريد ويُضبط فقط عبر دالة الربط
        --     المحروسة؛ user_profiles.customer_id يُضبط فقط عبر دوال محروسة.
        IF v_uid IS NULL OR NOT (
              EXISTS (SELECT 1 FROM customers c WHERE c.id = p_customer_id AND c.auth_user_id = v_uid)
              OR get_customer_id_from_auth(v_uid) = p_customer_id
           ) THEN
            RAISE EXCEPTION 'convert_guest_order_to_customer: not your customer account';
        END IF;
        -- (ب) إثبات ملكية الطلب الزائر ببريد المُتصل المُؤكَّد في auth.users (لا
        --     customers.email غير الفريد/القابل للكتابة من المهاجم).
        SELECT email INTO v_guest_email  FROM guest_checkouts WHERE id = p_guest_checkout_id AND tenant_id = p_tenant_id;
        SELECT email INTO v_caller_email FROM auth.users      WHERE id = v_uid AND email_confirmed_at IS NOT NULL;
        IF v_caller_email IS NULL OR v_guest_email IS NULL OR lower(v_caller_email) <> lower(v_guest_email) THEN
            RAISE EXCEPTION 'convert_guest_order_to_customer: guest order not owned by caller';
        END IF;
    END IF;

    UPDATE orders
       SET customer_id = p_customer_id, guest_checkout_id = NULL, updated_at = NOW()
     WHERE tenant_id = p_tenant_id AND guest_checkout_id = p_guest_checkout_id AND customer_id IS NULL;
    GET DIAGNOSTICS v_orders_updated = ROW_COUNT;

    UPDATE guest_checkouts
       SET status = 'converted_to_customer', converted_to_customer_id = p_customer_id, converted_at = NOW()
     WHERE id = p_guest_checkout_id AND tenant_id = p_tenant_id;

    v_result := jsonb_build_object('success', true, 'orders_converted', v_orders_updated,
                                   'customer_id', p_customer_id, 'message', 'تم تحويل الطلبات إلى العميل المسجل');
    RETURN v_result;
END;
$$;


--
-- Name: convert_material_quantity(uuid, numeric, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.convert_material_quantity(p_material_id uuid, p_quantity numeric, p_from_unit_id uuid, p_to_unit_id uuid) RETURNS TABLE(converted_quantity numeric, conversion_factor numeric, total_weight numeric, total_volume numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_factor NUMERIC;
    v_weight NUMERIC;
    v_volume NUMERIC;
BEGIN
    -- إذا كانت نفس الوحدة: لا تحويل
    IF p_from_unit_id = p_to_unit_id THEN
        RETURN QUERY SELECT p_quantity, 1.0::NUMERIC, NULL::NUMERIC, NULL::NUMERIC;
        RETURN;
    END IF;
    
    -- البحث عن التحويل المباشر (from → to)
    SELECT muc.conversion_factor, muc.weight_per_unit, muc.volume_cbm
    INTO v_factor, v_weight, v_volume
    FROM public.material_unit_conversions muc
    WHERE muc.material_id = p_material_id
    AND muc.from_unit_id = p_from_unit_id
    AND muc.to_unit_id = p_to_unit_id
    AND muc.is_active = true
    LIMIT 1;
    
    IF v_factor IS NOT NULL THEN
        RETURN QUERY SELECT 
            (p_quantity * v_factor)::NUMERIC,
            v_factor,
            CASE WHEN v_weight IS NOT NULL THEN (p_quantity * v_weight)::NUMERIC ELSE NULL END,
            CASE WHEN v_volume IS NOT NULL THEN (p_quantity * v_volume)::NUMERIC ELSE NULL END;
        RETURN;
    END IF;
    
    -- البحث عن التحويل العكسي (to → from) وقلب المعامل
    SELECT muc.conversion_factor, muc.weight_per_unit, muc.volume_cbm
    INTO v_factor, v_weight, v_volume
    FROM public.material_unit_conversions muc
    WHERE muc.material_id = p_material_id
    AND muc.from_unit_id = p_to_unit_id
    AND muc.to_unit_id = p_from_unit_id
    AND muc.is_active = true
    LIMIT 1;
    
    IF v_factor IS NOT NULL AND v_factor > 0 THEN
        RETURN QUERY SELECT 
            (p_quantity / v_factor)::NUMERIC,
            (1.0 / v_factor)::NUMERIC,
            NULL::NUMERIC,
            NULL::NUMERIC;
        RETURN;
    END IF;
    
    -- لم يُعثر على تحويل: إرجاع NULL
    RETURN QUERY SELECT NULL::NUMERIC, NULL::NUMERIC, NULL::NUMERIC, NULL::NUMERIC;
END;
$$;


--
-- Name: convert_quotation_to_order(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.convert_quotation_to_order(p_quotation_id uuid, p_doc_cycle character varying DEFAULT 'purchase'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_quote       RECORD;
    v_order_id    UUID;
    v_order_number VARCHAR(50);
    v_items_copied INT := 0;
BEGIN
    IF p_doc_cycle = 'purchase' THEN
        -- ════════════════════════════════════════════════════════
        -- دورة المشتريات: عرض سعر مشتريات → أمر شراء
        -- ════════════════════════════════════════════════════════
        SELECT * INTO v_quote FROM purchase_quotations WHERE id = p_quotation_id;
        
        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false, 'error', 'عرض السعر غير موجود');
        END IF;
        
        IF v_quote.status = 'converted' THEN
            RETURN jsonb_build_object('success', false, 'error', 'عرض السعر محوّل مسبقاً');
        END IF;
        
        v_order_number := 'PO-' || TO_CHAR(NOW(), 'YYYYMMDD-HH24MISS');
        
        -- إنشاء أمر الشراء (tenant_id + company_id يأتيان من عرض السعر)
        INSERT INTO purchase_orders (
            tenant_id, company_id, branch_id,
            order_number, order_date,
            supplier_id, supplier_name,
            quotation_id,
            status, currency, exchange_rate,
            total_amount, notes,
            created_by
        ) VALUES (
            v_quote.tenant_id, v_quote.company_id, v_quote.branch_id,
            v_order_number, CURRENT_DATE,
            v_quote.supplier_id, v_quote.supplier_name,
            p_quotation_id,
            'draft', COALESCE(v_quote.currency, 'SAR'), COALESCE(v_quote.exchange_rate, 1),
            COALESCE(v_quote.total_amount, 0),
            'تحويل من عرض سعر ' || COALESCE(v_quote.quotation_number, ''),
            auth.uid()
        ) RETURNING id INTO v_order_id;
        
        -- نسخ البنود (بدون company_id لأنها غير موجودة في purchase_order_items)
        INSERT INTO purchase_order_items (
            tenant_id, order_id,
            product_id, material_id, variant_id,
            description, quantity, unit_price, discount_amount,
            tax_rate, tax_amount, subtotal, total
        )
        SELECT 
            tenant_id, v_order_id,
            product_id, material_id, variant_id,
            description, quantity, unit_price, discount_amount,
            tax_rate, tax_amount, subtotal, total
        FROM purchase_quotation_items
        WHERE quotation_id = p_quotation_id;
        
        GET DIAGNOSTICS v_items_copied = ROW_COUNT;
        
        -- تحديث حالة عرض السعر
        UPDATE purchase_quotations SET status = 'converted', updated_at = NOW() WHERE id = p_quotation_id;
        
    ELSIF p_doc_cycle = 'sales' THEN
        -- ════════════════════════════════════════════════════════
        -- دورة المبيعات: عرض سعر مبيعات → أمر بيع
        -- ════════════════════════════════════════════════════════
        SELECT * INTO v_quote FROM quotations WHERE id = p_quotation_id;
        
        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false, 'error', 'عرض السعر غير موجود');
        END IF;
        
        IF v_quote.status = 'converted' THEN
            RETURN jsonb_build_object('success', false, 'error', 'عرض السعر محوّل مسبقاً');
        END IF;
        
        v_order_number := 'SO-' || TO_CHAR(NOW(), 'YYYYMMDD-HH24MISS');
        
        INSERT INTO sales_orders (
            tenant_id, company_id, branch_id,
            order_number, order_date,
            customer_id, customer_name,
            quotation_id,
            status, currency,
            total_amount, notes,
            created_by
        ) VALUES (
            v_quote.tenant_id, v_quote.company_id, v_quote.branch_id,
            v_order_number, CURRENT_DATE,
            v_quote.customer_id, v_quote.customer_name,
            p_quotation_id,
            'draft', COALESCE(v_quote.currency, 'SAR'),
            COALESCE(v_quote.total_amount, 0),
            'تحويل من عرض سعر ' || COALESCE(v_quote.quotation_number, ''),
            auth.uid()
        ) RETURNING id INTO v_order_id;
        
        -- نسخ البنود (sales_order_items فيها company_id)
        INSERT INTO sales_order_items (
            tenant_id, company_id, order_id,
            product_id, variant_id, material_id,
            description, quantity, unit_price,
            discount_percent, discount_amount,
            tax_percent, tax_amount, subtotal, total
        )
        SELECT 
            tenant_id, company_id, v_order_id,
            product_id, variant_id, material_id,
            description, quantity, unit_price,
            discount_percent, discount_amount,
            tax_percent, tax_amount, subtotal, total
        FROM quotation_items
        WHERE quotation_id = p_quotation_id;
        
        GET DIAGNOSTICS v_items_copied = ROW_COUNT;
        
        UPDATE quotations SET status = 'converted', updated_at = NOW() WHERE id = p_quotation_id;
        
    ELSE
        RETURN jsonb_build_object('success', false, 'error', 'doc_cycle يجب أن يكون purchase أو sales');
    END IF;
    
    RETURN jsonb_build_object(
        'success', true,
        'order_id', v_order_id,
        'order_number', v_order_number,
        'items_copied', v_items_copied,
        'cycle', p_doc_cycle,
        'message', 'تم تحويل عرض السعر إلى أمر بنجاح'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'detail', SQLSTATE);
END;
$$;


