--
-- Name: create_customer_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_customer_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_parent_id UUID;
    v_account_type_id UUID;
    v_new_code VARCHAR(50);
    v_new_account_id UUID;
    v_full_code VARCHAR(200);
BEGIN
    -- الحصول على حساب العملاء الأب (1130)
    SELECT id INTO v_parent_id 
    FROM chart_of_accounts 
    WHERE company_id = NEW.company_id 
      AND account_code = '1130';
    
    IF v_parent_id IS NULL THEN
        -- لا توجد شجرة حسابات، تخطي
        RAISE NOTICE 'لا توجد شجرة حسابات للشركة، تخطي إنشاء حساب العميل';
        RETURN NEW;
    END IF;
    
    -- الحصول على نوع الحساب
    SELECT id INTO v_account_type_id FROM account_types WHERE code = 'CURRENT_ASSET';
    
    -- توليد رقم الحساب الجديد
    v_new_code := generate_next_account_code(NEW.tenant_id, NEW.company_id, '1130');
    v_full_code := '1000.1100.1130.' || v_new_code;
    
    -- إنشاء الحساب الفرعي للعميل
    INSERT INTO chart_of_accounts (
        tenant_id, company_id, account_code, 
        name_ar, name_en, 
        account_type_id, parent_id, 
        is_group, is_detail, level, full_code, 
        currency, is_active, is_receivable
    )
    VALUES (
        NEW.tenant_id, NEW.company_id, v_new_code,
        NEW.name_ar, COALESCE(NEW.name_en, NEW.name_ar),
        v_account_type_id, v_parent_id,
        false, true, 4, v_full_code,
        COALESCE(NEW.currency, 'SAR'), true, true
    )
    RETURNING id INTO v_new_account_id;
    
    -- تحديث العميل بربط الحساب
    NEW.receivable_account_id := v_new_account_id;
    
    RAISE NOTICE 'تم إنشاء حساب للعميل: % - رقم الحساب: %', NEW.name_ar, v_new_code;
    
    RETURN NEW;
END;
$$;


--
-- Name: create_default_company_for_tenant(uuid, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_default_company_for_tenant(p_tenant_id uuid, p_company_name character varying, p_business_type character varying DEFAULT 'general'::character varying, p_company_type character varying DEFAULT 'production'::character varying, p_currency character varying DEFAULT 'SAR'::character varying, p_country_code character varying DEFAULT 'SA'::character varying) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_company_id UUID;
    v_company_code VARCHAR(50);
    v_count INT;
    v_full_name VARCHAR(255);
BEGIN
    SELECT COUNT(*) INTO v_count FROM companies WHERE tenant_id = p_tenant_id;
    v_company_code := 'COMP-' || LPAD((v_count + 1)::TEXT, 3, '0');

    WHILE EXISTS (SELECT 1 FROM companies WHERE code = v_company_code AND tenant_id = p_tenant_id) LOOP
        v_company_code := 'COMP-' || LPAD(FLOOR(RANDOM() * 999999)::TEXT, 6, '0');
    END LOOP;

    v_full_name := CASE p_company_type
        WHEN 'training' THEN p_company_name || ' (تدريبية)'
        WHEN 'test' THEN p_company_name || ' (تجريبية)'
        ELSE p_company_name
    END;

    INSERT INTO companies (
        tenant_id, code, name, name_en, business_type, company_type,
        default_currency, country_code, fiscal_year_start_month,
        tax_system, vat_rate, inventory_valuation_method
    )
    VALUES (
        p_tenant_id, v_company_code, v_full_name, p_company_name,
        p_business_type, p_company_type, COALESCE(p_currency, 'SAR'), p_country_code, 1,
        CASE WHEN p_country_code IN ('SA', 'AE', 'BH', 'KW', 'OM', 'QA') THEN 'vat_gcc'
             WHEN p_country_code IN ('EG', 'JO', 'LB') THEN 'vat_standard'
             ELSE 'none' END,
        CASE WHEN p_country_code IN ('SA', 'AE', 'BH', 'OM', 'QA') THEN 15.00
             WHEN p_country_code = 'EG' THEN 14.00
             WHEN p_country_code = 'JO' THEN 16.00
             ELSE 0.00 END,
        'weighted_average'
    )
    RETURNING id INTO v_company_id;

    -- ✅ إنشاء إعدادات المحاسبة تلقائياً للشركة الجديدة
    INSERT INTO company_accounting_settings (company_id, base_currency, supported_currencies)
    VALUES (v_company_id, COALESCE(p_currency, 'SAR'), ARRAY[COALESCE(p_currency, 'SAR')]::text[])
    ON CONFLICT (company_id) DO NOTHING;

    RETURN v_company_id;
END;
$$;


