--
-- Name: create_monthly_targets(uuid, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_monthly_targets(p_company_id uuid, p_year integer, p_month integer, p_copy_from_previous boolean DEFAULT true) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_assignment RECORD;
    v_prev_target RECORD;
    v_created INT := 0;
    v_tenant_id UUID;
BEGIN
    -- الحصول على tenant_id
    SELECT tenant_id INTO v_tenant_id FROM companies WHERE id = p_company_id;
    
    -- لكل موظف لديه تعيين نشط
    FOR v_assignment IN 
        SELECT DISTINCT ea.employee_id, ea.tenant_id, ea.target_amount
        FROM employee_incentive_assignments ea
        WHERE ea.company_id = p_company_id
          AND ea.is_active = true
          AND MAKE_DATE(p_year, p_month, 1) BETWEEN ea.start_date AND COALESCE(ea.end_date, '9999-12-31')
    LOOP
        -- التحقق من عدم وجود هدف مسبق
        IF NOT EXISTS (
            SELECT 1 FROM employee_targets
            WHERE employee_id = v_assignment.employee_id
              AND period_year = p_year
              AND period_month = p_month
              AND target_type = 'sales_amount'
        ) THEN
            -- محاولة نسخ من الشهر السابق
            IF p_copy_from_previous THEN
                SELECT * INTO v_prev_target
                FROM employee_targets
                WHERE employee_id = v_assignment.employee_id
                  AND target_type = 'sales_amount'
                  AND (
                      (period_year = p_year AND period_month = p_month - 1)
                      OR (p_month = 1 AND period_year = p_year - 1 AND period_month = 12)
                  )
                LIMIT 1;
            END IF;
            
            -- إنشاء الهدف
            INSERT INTO employee_targets (
                tenant_id, company_id, employee_id,
                target_type, period_type, period_year, period_month,
                target_amount,
                bonus_on_achievement, bonus_on_exceed,
                status
            )
            VALUES (
                v_tenant_id, p_company_id, v_assignment.employee_id,
                'sales_amount', 'monthly', p_year, p_month,
                COALESCE(v_prev_target.target_amount, v_assignment.target_amount, 0),
                COALESCE(v_prev_target.bonus_on_achievement, 0),
                COALESCE(v_prev_target.bonus_on_exceed, 0),
                'active'
            );
            
            v_created := v_created + 1;
        END IF;
    END LOOP;
    
    RETURN v_created;
END;
$$;


--
-- Name: FUNCTION create_monthly_targets(p_company_id uuid, p_year integer, p_month integer, p_copy_from_previous boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_monthly_targets(p_company_id uuid, p_year integer, p_month integer, p_copy_from_previous boolean) IS 'إنشاء أهداف شهرية للموظفين';


--
-- Name: create_new_tenant(character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_new_tenant(p_tenant_code character varying, p_tenant_name character varying, p_email character varying, p_phone character varying DEFAULT NULL::character varying, p_country_code character varying DEFAULT 'SA'::character varying, p_default_language character varying DEFAULT 'ar'::character varying, p_business_type character varying DEFAULT 'general'::character varying) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
BEGIN
    INSERT INTO tenants (
        code, name, email, phone, status, default_language
    )
    VALUES (
        p_tenant_code, p_tenant_name, p_email, p_phone, 'active', p_default_language
    )
    RETURNING id INTO v_tenant_id;
    
    RETURN v_tenant_id;
END;
$$;


--
-- Name: create_new_tenant(character varying, character varying, character varying, character varying, character varying, character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_new_tenant(p_tenant_code character varying, p_tenant_name character varying, p_email character varying, p_phone character varying DEFAULT NULL::character varying, p_country_code character varying DEFAULT 'SA'::character varying, p_default_language character varying DEFAULT 'ar'::character varying, p_business_type character varying DEFAULT 'general'::character varying, p_product_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_resolved_product_id UUID;
BEGIN
    -- Resolve product_id: passed > from plan lookup > default texacore
    v_resolved_product_id := COALESCE(
        p_product_id,
        (SELECT id FROM saas_products WHERE code = 'texacore' AND is_active = true LIMIT 1)
    );

    INSERT INTO tenants (
        code, name, email, phone, status, default_language, product_id
    )
    VALUES (
        p_tenant_code, p_tenant_name, p_email, p_phone, 'active', p_default_language, v_resolved_product_id
    )
    RETURNING id INTO v_tenant_id;
    
    RETURN v_tenant_id;
END;
$$;


--
-- Name: create_order_from_cart(uuid, uuid, uuid, uuid, uuid, character varying, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_order_from_cart(p_tenant_id uuid, p_company_id uuid, p_cart_id uuid, p_customer_id uuid DEFAULT NULL::uuid, p_guest_checkout_id uuid DEFAULT NULL::uuid, p_payment_method character varying DEFAULT 'cash_on_delivery'::character varying, p_shipping_method character varying DEFAULT 'standard'::character varying, p_customer_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_order_id UUID;
    v_order_number VARCHAR;
    v_cart RECORD;
    v_item RECORD;
    v_result JSONB;
BEGIN
    -- التحقق من وجود السلة
    SELECT * INTO v_cart
    FROM shopping_carts
    WHERE id = p_cart_id
      AND tenant_id = p_tenant_id
      AND status = 'active';
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'السلة غير موجودة أو غير نشطة'
        );
    END IF;
    
    -- التحقق من وجود عناصر في السلة
    IF v_cart.items_count = 0 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'السلة فارغة'
        );
    END IF;
    
    -- توليد رقم الطلب
    v_order_number := generate_order_number(p_tenant_id, p_company_id);
    
    -- إنشاء الطلب
    INSERT INTO orders (
        tenant_id, company_id, order_number,
        customer_id, guest_checkout_id, cart_id,
        subtotal, discount_amount, tax_amount, total_amount,
        currency, payment_method, shipping_method, customer_notes,
        status, payment_status
    )
    VALUES (
        p_tenant_id, p_company_id, v_order_number,
        p_customer_id, p_guest_checkout_id, p_cart_id,
        v_cart.subtotal, v_cart.discount_amount, v_cart.tax_amount, v_cart.total_amount,
        v_cart.currency, p_payment_method, p_shipping_method, p_customer_notes,
        'pending', 'pending'
    )
    RETURNING id INTO v_order_id;
    
    -- نسخ عناصر السلة إلى الطلب
    INSERT INTO order_items (
        tenant_id, company_id, order_id, product_id,
        product_name, product_sku, product_image_url,
        quantity, unit_price, discount_amount, tax_amount, total_price
    )
    SELECT
        p_tenant_id, p_company_id, v_order_id, sci.product_id,
        COALESCE(p.name_ar, p.name_en, 'Unknown') as product_name,
        p.sku,
        (p.images->0->>'url')::TEXT as product_image_url,
        sci.quantity,
        sci.unit_price,
        0, -- discount per item
        0, -- tax per item
        sci.total_price
    FROM shopping_cart_items sci
    LEFT JOIN products p ON p.id = sci.product_id
    WHERE sci.cart_id = p_cart_id;
    
    -- تحديث حالة السلة
    UPDATE shopping_carts
    SET status = 'completed',
        updated_at = NOW()
    WHERE id = p_cart_id;
    
    -- إرجاع النتيجة
    v_result := jsonb_build_object(
        'success', true,
        'order_id', v_order_id,
        'order_number', v_order_number,
        'total_amount', v_cart.total_amount,
        'currency', v_cart.currency,
        'message', 'تم إنشاء الطلب بنجاح'
    );
    
    RETURN v_result;
END;
$$;


--
-- Name: create_payment_receipt_journal_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_payment_receipt_journal_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_entry_id UUID;
    v_cust UUID;
    v_cash UUID;
    v_fy UUID;
BEGIN
    IF NEW.status != 'confirmed' THEN RETURN NEW; END IF;
    IF NEW.journal_entry_id IS NOT NULL THEN RETURN NEW; END IF;

    -- حساب العميل (الذمم المدينة)
    v_cust := (SELECT receivable_account_id FROM customers WHERE id = NEW.customer_id);
    IF v_cust IS NULL THEN
        SELECT id INTO v_cust FROM chart_of_accounts
        WHERE company_id = NEW.company_id AND is_party_account = true AND party_type = 'customer' AND party_id = NEW.customer_id LIMIT 1;
    END IF;
    IF v_cust IS NULL THEN
        SELECT id INTO v_cust FROM chart_of_accounts
        WHERE company_id = NEW.company_id AND account_code IN ('1131','1130','113') AND COALESCE(is_group,false)=false
        ORDER BY CASE account_code WHEN '1131' THEN 0 WHEN '1130' THEN 1 ELSE 2 END LIMIT 1;
    END IF;
    IF v_cust IS NULL THEN
        SELECT id INTO v_cust FROM chart_of_accounts
        WHERE company_id = NEW.company_id AND is_receivable = true AND COALESCE(is_group,false)=false ORDER BY account_code LIMIT 1;
    END IF;

    -- حساب النقد/البنك (دوري)
    IF NEW.treasury_account_id IS NOT NULL THEN
        v_cash := NEW.treasury_account_id;
    ELSIF NEW.payment_method IN ('cash','نقدي','نقداً') THEN
        SELECT id INTO v_cash FROM chart_of_accounts WHERE company_id=NEW.company_id AND is_cash_account=true AND COALESCE(is_group,false)=false ORDER BY account_code LIMIT 1;
    ELSE
        SELECT id INTO v_cash FROM chart_of_accounts WHERE company_id=NEW.company_id AND is_bank_account=true AND COALESCE(is_group,false)=false ORDER BY account_code LIMIT 1;
    END IF;
    IF v_cash IS NULL THEN
        SELECT id INTO v_cash FROM chart_of_accounts WHERE company_id=NEW.company_id AND (is_cash_account=true OR is_bank_account=true) AND COALESCE(is_group,false)=false ORDER BY account_code LIMIT 1;
    END IF;

    IF v_cust IS NULL OR v_cash IS NULL THEN
        RAISE EXCEPTION 'سند القبض %: تعذّر إيجاد حساب % ', NEW.receipt_number,
            CASE WHEN v_cust IS NULL THEN 'العميل/الذمم المدينة' ELSE 'النقد/البنك' END;
    END IF;

    SELECT id INTO v_fy FROM fiscal_years WHERE company_id=NEW.company_id AND is_current=true LIMIT 1;

    INSERT INTO journal_entries (
        tenant_id, company_id, branch_id, entry_number, entry_date, fiscal_year_id, entry_type,
        reference_type, reference_id, reference_number, description, currency, exchange_rate,
        total_debit, total_credit, status, is_posted, created_by, created_at
    ) VALUES (
        NEW.tenant_id, NEW.company_id, NEW.branch_id, 'JE-PR-'||NEW.receipt_number, NEW.receipt_date, v_fy, 'payment_receipt',
        'payment_receipt', NEW.id, NEW.receipt_number,
        'سند قبض رقم '||NEW.receipt_number||' - '||COALESCE(NEW.customer_name,''), NEW.currency, NEW.exchange_rate,
        NEW.amount, NEW.amount, 'draft', false, NEW.created_by, NOW()
    ) RETURNING id INTO v_entry_id;

    INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, debit, credit, debit_fc, credit_fc, currency, exchange_rate, description, reference_type, reference_id)
    VALUES (NEW.tenant_id, v_entry_id, 1, v_cash, NEW.amount, 0, NEW.amount, 0, NEW.currency, NEW.exchange_rate, 'تحصيل نقدي - سند '||NEW.receipt_number, 'payment_receipt', NEW.id);

    INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, debit, credit, debit_fc, credit_fc, currency, exchange_rate, description, party_type, party_id, reference_type, reference_id)
    VALUES (NEW.tenant_id, v_entry_id, 2, v_cust, 0, NEW.amount, 0, NEW.amount, NEW.currency, NEW.exchange_rate, 'تسديد ذمة العميل - سند '||NEW.receipt_number, 'customer', NEW.customer_id, 'payment_receipt', NEW.id);

    PERFORM post_journal_entry(v_entry_id, NEW.created_by);
    NEW.journal_entry_id := v_entry_id;
    RETURN NEW;
END;
$$;


--
-- Name: create_payment_voucher_journal_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_payment_voucher_journal_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_entry_id UUID;
    v_supp UUID;
    v_cash UUID;
    v_fy UUID;
BEGIN
    IF NEW.status != 'confirmed' THEN RETURN NEW; END IF;
    IF NEW.journal_entry_id IS NOT NULL THEN RETURN NEW; END IF;

    -- حساب المورد (الذمم الدائنة)
    v_supp := (SELECT payable_account_id FROM suppliers WHERE id = NEW.supplier_id);
    IF v_supp IS NULL THEN
        SELECT id INTO v_supp FROM chart_of_accounts
        WHERE company_id = NEW.company_id AND is_party_account = true AND party_type = 'supplier' AND party_id = NEW.supplier_id LIMIT 1;
    END IF;
    IF v_supp IS NULL THEN
        SELECT id INTO v_supp FROM chart_of_accounts
        WHERE company_id = NEW.company_id AND is_payable = true AND COALESCE(is_group,false)=false ORDER BY account_code LIMIT 1;
    END IF;
    IF v_supp IS NULL THEN
        SELECT id INTO v_supp FROM chart_of_accounts
        WHERE company_id = NEW.company_id AND account_code IN ('2112','2110','2100','2000') AND COALESCE(is_group,false)=false ORDER BY account_code LIMIT 1;
    END IF;

    -- النقد/البنك (دوري) — payment_vouchers بلا treasury_account_id
    IF NEW.payment_method IN ('cash','نقدي','نقداً') THEN
        SELECT id INTO v_cash FROM chart_of_accounts WHERE company_id=NEW.company_id AND is_cash_account=true AND COALESCE(is_group,false)=false ORDER BY account_code LIMIT 1;
    ELSE
        SELECT id INTO v_cash FROM chart_of_accounts WHERE company_id=NEW.company_id AND is_bank_account=true AND COALESCE(is_group,false)=false ORDER BY account_code LIMIT 1;
    END IF;
    IF v_cash IS NULL THEN
        SELECT id INTO v_cash FROM chart_of_accounts WHERE company_id=NEW.company_id AND (is_cash_account=true OR is_bank_account=true) AND COALESCE(is_group,false)=false ORDER BY account_code LIMIT 1;
    END IF;

    IF v_supp IS NULL OR v_cash IS NULL THEN
        RAISE EXCEPTION 'سند الصرف %: تعذّر إيجاد حساب %', NEW.voucher_number,
            CASE WHEN v_supp IS NULL THEN 'المورد/الذمم الدائنة' ELSE 'النقد/البنك' END;
    END IF;

    SELECT id INTO v_fy FROM fiscal_years WHERE company_id=NEW.company_id AND is_current=true LIMIT 1;

    INSERT INTO journal_entries (
        tenant_id, company_id, branch_id, entry_number, entry_date, fiscal_year_id, entry_type,
        reference_type, reference_id, reference_number, description, currency, exchange_rate,
        total_debit, total_credit, status, is_posted, created_by, created_at
    ) VALUES (
        NEW.tenant_id, NEW.company_id, NEW.branch_id, 'JE-PV-'||NEW.voucher_number, NEW.voucher_date, v_fy, 'payment_voucher',
        'payment_voucher', NEW.id, NEW.voucher_number,
        'سند صرف رقم '||NEW.voucher_number||' - '||COALESCE(NEW.supplier_name,''), NEW.currency, NEW.exchange_rate,
        NEW.amount, NEW.amount, 'draft', false, NEW.created_by, NOW()
    ) RETURNING id INTO v_entry_id;

    INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, debit, credit, debit_fc, credit_fc, currency, exchange_rate, description, party_type, party_id, reference_type, reference_id)
    VALUES (NEW.tenant_id, v_entry_id, 1, v_supp, NEW.amount, 0, NEW.amount, 0, NEW.currency, NEW.exchange_rate, 'سداد للمورد - سند '||NEW.voucher_number, 'supplier', NEW.supplier_id, 'payment_voucher', NEW.id);

    INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, debit, credit, debit_fc, credit_fc, currency, exchange_rate, description, reference_type, reference_id)
    VALUES (NEW.tenant_id, v_entry_id, 2, v_cash, 0, NEW.amount, 0, NEW.amount, NEW.currency, NEW.exchange_rate, 'صرف نقدي - سند '||NEW.voucher_number, 'payment_voucher', NEW.id);

    PERFORM post_journal_entry(v_entry_id, NEW.created_by);
    NEW.journal_entry_id := v_entry_id;
    RETURN NEW;
END;
$$;


--
-- Name: create_promotional_discount(character varying, character varying, character varying, integer, timestamp with time zone, timestamp with time zone, jsonb, character varying, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_promotional_discount(p_code character varying, p_name_ar character varying, p_name_en character varying, p_discount_percentage integer, p_valid_from timestamp with time zone, p_valid_to timestamp with time zone, p_applicable_plans jsonb DEFAULT '[]'::jsonb, p_applies_to character varying DEFAULT 'both'::character varying, p_auto_apply boolean DEFAULT true, p_priority integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_discount_id UUID;
BEGIN
    -- التحقق من الكود
    IF EXISTS (SELECT 1 FROM promotional_discounts WHERE code = p_code) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'code_exists',
            'message', 'كود الخصم موجود مسبقاً'
        );
    END IF;
    
    -- إنشاء الخصم
    INSERT INTO promotional_discounts (
        code, name_ar, name_en,
        discount_percentage,
        valid_from, valid_to,
        applicable_plans, applies_to,
        is_active, auto_apply, priority
    ) VALUES (
        p_code, p_name_ar, p_name_en,
        p_discount_percentage,
        p_valid_from, p_valid_to,
        p_applicable_plans, p_applies_to,
        true, p_auto_apply, p_priority
    )
    RETURNING id INTO v_discount_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'discount_id', v_discount_id,
        'code', p_code,
        'message', 'تم إنشاء الخصم بنجاح'
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'exception',
            'message', SQLERRM
        );
END;
$$;


--
-- Name: create_purchase_journal_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_purchase_journal_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_entry_id UUID;
    v_entry_number VARCHAR(50);
    v_payable_account_id UUID;
    v_expense_account_id UUID;
    v_item RECORD;
BEGIN
    -- Only process when status changes to 'posted'
    IF NEW.status != 'posted' OR NEW.is_posted != true THEN
        RETURN NEW;
    END IF;

    -- Don't reprocess if already posted
    IF OLD.status = 'posted' AND OLD.is_posted = true THEN
        RETURN NEW;
    END IF;

    -- Get supplier's payable account
    SELECT payable_account_id INTO v_payable_account_id
    FROM suppliers
    WHERE id = NEW.supplier_id;

    -- Get default expense account (you may want to get this from company settings)
    SELECT id INTO v_expense_account_id
    FROM accounts
    WHERE company_id = NEW.company_id
      AND account_type = 'expense'
      AND is_active = true
    LIMIT 1;

    -- Create journal entry
    v_entry_number := 'PI-' || NEW.invoice_number;

    INSERT INTO journal_entries (
        tenant_id, company_id, branch_id,
        entry_number, entry_date,
        description, entry_type, status,
        reference_type, reference_id,
        created_by
    )
    VALUES (
        NEW.tenant_id, NEW.company_id, NEW.branch_id,
        v_entry_number, NEW.invoice_date,
        'قيد فاتورة مشتريات ' || NEW.invoice_number,
        'PURCHASE_INVOICE', 'POSTED',
        'purchase_invoice', NEW.id,
        NEW.created_by
    )
    RETURNING id INTO v_entry_id;

    -- Debit: Expense Account
    INSERT INTO journal_entry_lines (
        tenant_id, entry_id, account_id,
        description, debit, credit
    )
    VALUES (
        NEW.tenant_id, v_entry_id, v_expense_account_id,
        'مشتريات - ' || COALESCE(NEW.supplier_name, ''),
        NEW.total_amount, 0
    );

    -- Credit: Accounts Payable
    INSERT INTO journal_entry_lines (
        tenant_id, entry_id, account_id,
        description, debit, credit
    )
    VALUES (
        NEW.tenant_id, v_entry_id, v_payable_account_id,
        'دائنون - ' || COALESCE(NEW.supplier_name, ''),
        0, NEW.total_amount
    );

    -- Link journal entry to invoice
    UPDATE purchase_invoices
    SET journal_entry_id = v_entry_id
    WHERE id = NEW.id;

    RETURN NEW;
END;
$$;


--
-- Name: create_recurring_template(uuid, uuid, character varying, character varying, character varying, date, numeric, uuid, uuid, integer, character varying, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_recurring_template(p_tenant_id uuid, p_company_id uuid, p_template_code character varying, p_template_name character varying, p_frequency character varying, p_start_date date, p_total_amount numeric, p_debit_account_id uuid, p_credit_account_id uuid, p_day_of_month integer DEFAULT NULL::integer, p_category character varying DEFAULT 'other'::character varying, p_description text DEFAULT NULL::text, p_auto_post boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_template_id UUID;
BEGIN
    -- إنشاء القالب
    INSERT INTO recurring_entry_templates (
        tenant_id, company_id,
        template_code, template_name, description,
        frequency, day_of_month,
        start_date, next_execution_date,
        total_amount,
        category,
        auto_post, is_active
    )
    VALUES (
        p_tenant_id, p_company_id,
        p_template_code, p_template_name, p_description,
        p_frequency, p_day_of_month,
        p_start_date, p_start_date,
        p_total_amount,
        p_category,
        p_auto_post, true
    )
    RETURNING id INTO v_template_id;
    
    -- إضافة بند المدين
    INSERT INTO recurring_entry_lines (
        tenant_id, template_id, line_number,
        account_id, debit, credit,
        description
    )
    VALUES (
        p_tenant_id, v_template_id, 1,
        p_debit_account_id, p_total_amount, 0,
        p_template_name || ' - مدين'
    );
    
    -- إضافة بند الدائن
    INSERT INTO recurring_entry_lines (
        tenant_id, template_id, line_number,
        account_id, debit, credit,
        description
    )
    VALUES (
        p_tenant_id, v_template_id, 2,
        p_credit_account_id, 0, p_total_amount,
        p_template_name || ' - دائن'
    );
    
    RAISE NOTICE 'تم إنشاء قالب القيد المتكرر: %', p_template_name;
    
    RETURN v_template_id;
END;
$$;


--
-- Name: FUNCTION create_recurring_template(p_tenant_id uuid, p_company_id uuid, p_template_code character varying, p_template_name character varying, p_frequency character varying, p_start_date date, p_total_amount numeric, p_debit_account_id uuid, p_credit_account_id uuid, p_day_of_month integer, p_category character varying, p_description text, p_auto_post boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_recurring_template(p_tenant_id uuid, p_company_id uuid, p_template_code character varying, p_template_name character varying, p_frequency character varying, p_start_date date, p_total_amount numeric, p_debit_account_id uuid, p_credit_account_id uuid, p_day_of_month integer, p_category character varying, p_description text, p_auto_post boolean) IS 'إنشاء قالب قيد متكرر بسيط (مدين/دائن)';


--
-- Name: create_sales_draft_from_analysis(uuid, uuid, text, text, numeric, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_sales_draft_from_analysis(p_company uuid, p_customer_id uuid, p_customer_name text, p_currency text, p_total numeric, p_items jsonb, p_pa_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_tenant uuid; v_txn uuid; v_item jsonb; v_n int := 0; v_desc text;
BEGIN
    SELECT tenant_id INTO v_tenant FROM companies WHERE id = p_company;
    IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'message', 'شركة غير صالحة'); END IF;
    IF auth.uid() IS NOT NULL THEN PERFORM assert_can_access_company(p_company); END IF;

    INSERT INTO sales_transactions(company_id, tenant_id, stage, customer_id, customer_name, currency, total_amount, source_type)
      VALUES(p_company, v_tenant, 'draft', p_customer_id, NULLIF(p_customer_name,''),
             COALESCE(NULLIF(p_currency,''), 'USD'), COALESCE(p_total, 0), 'telegram_invoice')
      RETURNING id INTO v_txn;

    FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb)) LOOP
        v_n := v_n + 1;
        v_desc := trim(both ' ' FROM
            COALESCE(v_item->>'name','') ||
            CASE WHEN COALESCE(v_item->>'color','') <> '' THEN ' - ' || (v_item->>'color') ELSE '' END ||
            CASE WHEN COALESCE(v_item->>'roll_number','') <> '' THEN ' [' || (v_item->>'roll_number') || ']' ELSE '' END);
        INSERT INTO sales_transaction_items(transaction_id, line_number, quantity, unit_price, description)
          VALUES(v_txn, v_n,
                 COALESCE(NULLIF(v_item->>'quantity','')::numeric, 0),
                 COALESCE(NULLIF(v_item->>'unit_price','')::numeric, 0),
                 NULLIF(v_desc, ''));
    END LOOP;

    IF p_pa_id IS NOT NULL THEN PERFORM relink_telegram_doc(p_pa_id, 'sales_transaction', v_txn); END IF;
    RETURN jsonb_build_object('ok', true, 'transaction_id', v_txn, 'items', v_n);
END $$;


--
-- Name: create_sales_invoice_journal_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_sales_invoice_journal_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_entry_id UUID;
    v_entry_number VARCHAR(50);
    v_customer_account_id UUID;
    v_sales_account_id UUID;
    v_vat_account_id UUID;
    v_fiscal_year_id UUID;
BEGIN
    -- فقط عند تأكيد الفاتورة (posted)
    IF NEW.status != 'posted' OR NEW.is_posted = false THEN
        RETURN NEW;
    END IF;
    
    -- تخطي إذا كان القيد موجود مسبقاً
    IF NEW.journal_entry_id IS NOT NULL THEN
        RETURN NEW;
    END IF;
    
    -- الحصول على حساب العميل
    v_customer_account_id := (
        SELECT receivable_account_id 
        FROM customers 
        WHERE id = NEW.customer_id
    );
    
    IF v_customer_account_id IS NULL THEN
        -- استخدام حساب العملاء العام
        v_customer_account_id := get_account_by_code(NEW.company_id, '1130');
    END IF;
    
    -- الحصول على حساب المبيعات
    v_sales_account_id := get_account_by_code(NEW.company_id, '4100');
    IF v_sales_account_id IS NULL THEN
        RAISE EXCEPTION 'حساب المبيعات (4100) غير موجود';
    END IF;
    
    -- الحصول على حساب ضريبة القيمة المضافة
    v_vat_account_id := get_account_by_code(NEW.company_id, '2130');
    
    -- الحصول على السنة المالية الحالية
    SELECT id INTO v_fiscal_year_id
    FROM fiscal_years
    WHERE company_id = NEW.company_id
      AND is_current = true
    LIMIT 1;
    
    -- توليد رقم القيد
    v_entry_number := 'JE-SI-' || NEW.invoice_number;
    
    -- إنشاء القيد اليومي
    INSERT INTO journal_entries (
        tenant_id, company_id, branch_id,
        entry_number, entry_date,
        fiscal_year_id,
        entry_type,
        reference_type, reference_id, reference_number,
        description,
        currency, exchange_rate,
        total_debit, total_credit,
        status, is_posted, posted_at,
        created_by, created_at
    )
    VALUES (
        NEW.tenant_id, NEW.company_id, NEW.branch_id,
        v_entry_number, NEW.invoice_date,
        v_fiscal_year_id,
        'sales_invoice',
        'sales_invoice', NEW.id, NEW.invoice_number,
        'قيد فاتورة مبيعات رقم ' || NEW.invoice_number,
        NEW.currency, NEW.exchange_rate,
        NEW.total_amount, NEW.total_amount,
        'posted', true, NOW(),
        NEW.created_by, NOW()
    )
    RETURNING id INTO v_entry_id;
    
    -- إضافة بنود القيد
    -- 1. مدين: حساب العميل
    INSERT INTO journal_entry_lines (
        tenant_id, entry_id, line_number,
        account_id, debit, credit,
        currency, exchange_rate,
        description,
        party_type, party_id,
        reference_type, reference_id
    )
    VALUES (
        NEW.tenant_id, v_entry_id, 1,
        v_customer_account_id, NEW.total_amount, 0,
        NEW.currency, NEW.exchange_rate,
        CASE WHEN NEW.notes IS NOT NULL AND NEW.notes != '' THEN 'ذمة العميل - فاتورة ' || NEW.invoice_number || ' - ' || NEW.notes ELSE 'ذمة العميل - فاتورة ' || NEW.invoice_number END,
        'customer', NEW.customer_id,
        'sales_invoice', NEW.id
    );
    
    -- 2. دائن: حساب المبيعات (المبلغ قبل الضريبة)
    INSERT INTO journal_entry_lines (
        tenant_id, entry_id, line_number,
        account_id, debit, credit,
        currency, exchange_rate,
        description,
        reference_type, reference_id
    )
    VALUES (
        NEW.tenant_id, v_entry_id, 2,
        v_sales_account_id, 0, NEW.taxable_amount,
        NEW.currency, NEW.exchange_rate,
        CASE WHEN NEW.notes IS NOT NULL AND NEW.notes != '' THEN 'إيراد مبيعات - فاتورة ' || NEW.invoice_number || ' - ' || NEW.notes ELSE 'إيراد مبيعات - فاتورة ' || NEW.invoice_number END,
        'sales_invoice', NEW.id
    );
    
    -- 3. دائن: حساب ضريبة القيمة المضافة (إذا وجدت)
    IF NEW.tax_amount > 0 AND v_vat_account_id IS NOT NULL THEN
        INSERT INTO journal_entry_lines (
            tenant_id, entry_id, line_number,
            account_id, debit, credit,
            currency, exchange_rate,
            description,
            reference_type, reference_id
        )
        VALUES (
            NEW.tenant_id, v_entry_id, 3,
            v_vat_account_id, 0, NEW.tax_amount,
            NEW.currency, NEW.exchange_rate,
            'ضريبة القيمة المضافة - فاتورة ' || NEW.invoice_number,
            'sales_invoice', NEW.id
        );
    END IF;
    
    -- تحديث الفاتورة بربط القيد
    NEW.journal_entry_id := v_entry_id;
    NEW.posted_at := NOW();
    
    -- تحديث رصيد العميل
    UPDATE customers
    SET balance = balance + NEW.total_amount,
        total_sales = total_sales + NEW.total_amount
    WHERE id = NEW.customer_id;
    
    RAISE NOTICE 'تم إنشاء قيد فاتورة المبيعات: % - المبلغ: %', v_entry_number, NEW.total_amount;
    
    RETURN NEW;
END;
$$;


--
-- Name: create_sales_return_from_ecom(uuid, jsonb, text, numeric, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_sales_return_from_ecom(p_order_id uuid, p_items jsonb, p_reason text, p_shipping_deduction numeric DEFAULT 0, p_refund_method text DEFAULT 'credit'::text, p_auto_post boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order RECORD;
  v_inv RECORD;
  v_return_id uuid;
  v_return_no text;
  v_total numeric := 0;
  v_item jsonb;
  v_post jsonb;
  v_refund numeric;
  v_qty numeric;
  v_max numeric;
BEGIN
  SELECT id, tenant_id, company_id, customer_name, erp_customer_id, status,
         sales_invoice_id, currency, sales_return_id
    INTO v_order
  FROM ecommerce_orders WHERE id = p_order_id;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_not_found');
  END IF;

  -- 🔒 حارس العزل: المستدعي من نفس tenant الطلب (أو super admin)
  IF is_super_admin() IS NOT TRUE
     AND v_order.tenant_id IS DISTINCT FROM get_current_tenant_id() THEN
    RETURN jsonb_build_object('success', false, 'error', 'forbidden_cross_tenant');
  END IF;

  -- 🛡️ منع التكرار: مرتجع واحد لكل طلب
  IF v_order.sales_return_id IS NOT NULL OR v_order.status = 'returned' THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_returned',
      'sales_return_id', v_order.sales_return_id);
  END IF;

  SELECT id, warehouse_id, customer_id, company_id
    INTO v_inv
  FROM sales_transactions WHERE id = v_order.sales_invoice_id;

  v_return_no := 'SR-EC-' || to_char(now(), 'YYMMDD') || '-' || substr(p_order_id::text, 1, 4);
  IF EXISTS (SELECT 1 FROM sales_returns WHERE return_number = v_return_no) THEN
    v_return_no := v_return_no || '-' || substr(md5(p_order_id::text || clock_timestamp()::text), 1, 4);
  END IF;

  INSERT INTO sales_returns (
    tenant_id, company_id, return_number, return_date,
    invoice_id, customer_id, warehouse_id, reason,
    total_amount, currency, status,
    source_type, source_id
  ) VALUES (
    v_order.tenant_id, COALESCE(v_inv.company_id, v_order.company_id),
    v_return_no, current_date,
    NULL,
    COALESCE(v_inv.customer_id, v_order.erp_customer_id),
    v_inv.warehouse_id, p_reason,
    0, COALESCE(v_order.currency, 'UAH'), 'draft',
    'ecommerce', p_order_id
  ) RETURNING id INTO v_return_id;

  -- البنود — مع حدّ الكمية بالمسلَّمة
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    -- أقصى كمية مسموح إرجاعها لهذا الصنف: المسلَّم إن وُجد (>0)، وإلا المطلوب
    -- (يطابق منطق الواجهة: fulfilled_quantity || quantity)
    SELECT COALESCE(MAX(CASE WHEN COALESCE(fulfilled_quantity, 0) > 0
                             THEN fulfilled_quantity ELSE COALESCE(quantity, 0) END), 0) INTO v_max
    FROM ecommerce_order_items
    WHERE order_id = p_order_id
      AND (
        (NULLIF(v_item->>'material_id','') IS NOT NULL AND material_id = (v_item->>'material_id')::uuid)
        OR (NULLIF(v_item->>'product_id','') IS NOT NULL AND product_id = (v_item->>'product_id')::uuid)
      );

    v_qty := LEAST(COALESCE((v_item->>'quantity')::numeric, 0), v_max);
    IF v_qty <= 0 THEN
      CONTINUE;  -- لا صنف مطابق أو كمية صفر → تخطٍّ
    END IF;

    v_total := v_total + (v_qty * COALESCE((v_item->>'unit_price')::numeric, 0));
    INSERT INTO sales_return_items (
      tenant_id, company_id, return_id,
      material_id, product_id,
      quantity_returned, unit_price,
      total, warehouse_id, reason, condition
    ) VALUES (
      v_order.tenant_id, COALESCE(v_inv.company_id, v_order.company_id), v_return_id,
      NULLIF(v_item->>'material_id','')::uuid, NULLIF(v_item->>'product_id','')::uuid,
      v_qty, COALESCE((v_item->>'unit_price')::numeric, 0),
      v_qty * COALESCE((v_item->>'unit_price')::numeric, 0),
      v_inv.warehouse_id, COALESCE(v_item->>'reason', p_reason), COALESCE(v_item->>'condition', 'good')
    );
  END LOOP;

  -- لا بنود صالحة → ألغِ المرتجع الفارغ وأبلغ
  IF v_total = 0 THEN
    DELETE FROM sales_returns WHERE id = v_return_id;
    RETURN jsonb_build_object('success', false, 'error', 'no_valid_items');
  END IF;

  UPDATE sales_returns SET total_amount = v_total WHERE id = v_return_id;

  v_refund := GREATEST(v_total - COALESCE(p_shipping_deduction, 0), 0);

  IF p_auto_post THEN
    v_post := post_sales_return(v_return_id, v_inv.warehouse_id);
  END IF;

  UPDATE ecommerce_orders SET
    status = 'returned',
    sales_return_id = v_return_id,
    return_reason = p_reason,
    returned_at = now(),
    refund_amount = v_refund,
    refund_method = p_refund_method,
    refund_status = CASE WHEN p_refund_method = 'credit' THEN 'completed' ELSE 'pending' END,
    shipping_deduction = COALESCE(p_shipping_deduction, 0),
    updated_at = now()
  WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'return_id', v_return_id,
    'return_number', v_return_no,
    'total', v_total,
    'shipping_deduction', COALESCE(p_shipping_deduction, 0),
    'refund_amount', v_refund,
    'refund_method', p_refund_method,
    'posted', p_auto_post,
    'post_result', v_post
  );
END;
$$;


--
-- Name: create_shipment_document(uuid, character varying, uuid, character varying, character varying, character varying, character varying, character varying, character varying, text, character varying, character varying, character varying, character varying, character varying, character varying, numeric, integer, numeric, numeric, text, numeric, numeric, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_shipment_document(p_company_id uuid, p_source_table character varying, p_source_id uuid, p_carrier_code character varying, p_recipient_name character varying, p_recipient_phone character varying, p_recipient_city character varying DEFAULT NULL::character varying, p_recipient_city_ref character varying DEFAULT NULL::character varying, p_recipient_address_ref character varying DEFAULT NULL::character varying, p_recipient_address_street text DEFAULT NULL::text, p_recipient_building character varying DEFAULT NULL::character varying, p_recipient_flat character varying DEFAULT NULL::character varying, p_service_type character varying DEFAULT 'WarehouseWarehouse'::character varying, p_cargo_type character varying DEFAULT 'Parcel'::character varying, p_payer_type character varying DEFAULT 'Sender'::character varying, p_payment_method character varying DEFAULT 'NonCash'::character varying, p_weight numeric DEFAULT 1.0, p_seats_amount integer DEFAULT 1, p_declared_value numeric DEFAULT 0, p_cod_amount numeric DEFAULT 0, p_description text DEFAULT NULL::text, p_length numeric DEFAULT NULL::numeric, p_width numeric DEFAULT NULL::numeric, p_height numeric DEFAULT NULL::numeric, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
    v_carrier RECORD;
    v_doc_id UUID;
    v_np_request JSONB;
BEGIN
    -- Get tenant_id from company
    SELECT tenant_id INTO v_tenant_id FROM companies WHERE id = p_company_id;
    IF v_tenant_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Company not found');
    END IF;
    
    -- Get carrier config
    SELECT * INTO v_carrier 
    FROM shipping_carriers 
    WHERE company_id = p_company_id 
      AND carrier_code = p_carrier_code 
      AND is_active = true
    LIMIT 1;
    
    IF v_carrier.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Carrier not configured: ' || p_carrier_code);
    END IF;
    
    -- Create shipment document record
    INSERT INTO shipment_documents (
        tenant_id, company_id, carrier_id,
        source_table, source_id, carrier_code,
        status,
        -- Sender (from carrier config)
        sender_ref, sender_city_ref, sender_address_ref,
        sender_contact_ref, sender_phone,
        -- Recipient
        recipient_city_name, recipient_city_ref,
        recipient_address_ref, recipient_address_street,
        recipient_building, recipient_flat,
        recipient_contact_name, recipient_phone,
        -- Details
        service_type, cargo_type, payer_type, payment_method,
        weight, seats_amount,
        length, width, height,
        declared_value, cod_amount,
        description,
        created_by
    ) VALUES (
        v_tenant_id, p_company_id, v_carrier.id,
        p_source_table, p_source_id, p_carrier_code,
        'pending',
        -- Sender
        v_carrier.np_sender_ref, v_carrier.np_sender_city_ref, v_carrier.np_sender_address_ref,
        v_carrier.np_sender_contact_ref, v_carrier.np_sender_phone,
        -- Recipient
        p_recipient_city, p_recipient_city_ref,
        p_recipient_address_ref, p_recipient_address_street,
        p_recipient_building, p_recipient_flat,
        p_recipient_name, p_recipient_phone,
        -- Details
        p_service_type, p_cargo_type, p_payer_type, p_payment_method,
        p_weight, p_seats_amount,
        p_length, p_width, p_height,
        p_declared_value, p_cod_amount,
        p_description,
        p_created_by
    )
    RETURNING id INTO v_doc_id;
    
    -- Build Nova Poshta API request (for n8n to send)
    IF p_carrier_code = 'nova_poshta' THEN
        v_np_request := jsonb_build_object(
            'apiKey', '__API_KEY__',  -- n8n يستبدله بمفتاح API المشفر
            'modelName', 'InternetDocument',
            'calledMethod', 'save',
            'methodProperties', jsonb_build_object(
                'PayerType', p_payer_type,
                'PaymentMethod', p_payment_method,
                'DateTime', to_char(NOW(), 'DD.MM.YYYY'),
                'CargoType', p_cargo_type,
                'Weight', p_weight::text,
                'SeatsAmount', p_seats_amount::text,
                'ServiceType', p_service_type,
                'Description', COALESCE(p_description, 'Shipment from TexaCore'),
                'Cost', p_declared_value::text,
                -- Sender
                'Sender', v_carrier.np_sender_ref,
                'CitySender', v_carrier.np_sender_city_ref,
                'SenderAddress', v_carrier.np_sender_address_ref,
                'ContactSender', v_carrier.np_sender_contact_ref,
                'SendersPhone', v_carrier.np_sender_phone,
                -- Recipient (dynamic)
                'RecipientCityName', COALESCE(p_recipient_city, ''),
                'RecipientAddressName', COALESCE(p_recipient_address_ref, ''),
                'RecipientName', p_recipient_name,
                'RecipientsPhone', p_recipient_phone,
                -- Volume
                'VolumeGeneral', CASE 
                    WHEN p_length IS NOT NULL AND p_width IS NOT NULL AND p_height IS NOT NULL 
                    THEN ((p_length * p_width * p_height) / 1000000)::text
                    ELSE '0.001'
                END
            )
        );
        
        -- Add BackwardDeliveryData if COD
        IF p_cod_amount > 0 THEN
            v_np_request := jsonb_set(
                v_np_request,
                '{methodProperties,BackwardDeliveryData}',
                jsonb_build_array(
                    jsonb_build_object(
                        'PayerType', 'Recipient',
                        'CargoType', 'Money',
                        'RedeliveryString', p_cod_amount::text
                    )
                )
            );
        END IF;
        
        -- Add dimensions if provided
        IF p_length IS NOT NULL THEN
            v_np_request := jsonb_set(
                v_np_request,
                '{methodProperties,OptionsSeat}',
                jsonb_build_array(
                    jsonb_build_object(
                        'volumetricLength', p_length::text,
                        'volumetricWidth', p_width::text,
                        'volumetricHeight', p_height::text,
                        'weight', p_weight::text
                    )
                )
            );
        END IF;
        
        -- Save the request template
        UPDATE shipment_documents SET api_request = v_np_request WHERE id = v_doc_id;
    END IF;
    
    -- Return everything n8n needs
    RETURN jsonb_build_object(
        'success', true,
        'shipment_document_id', v_doc_id,
        'carrier_code', p_carrier_code,
        'carrier_id', v_carrier.id,
        'api_endpoint', COALESCE(v_carrier.api_endpoint, 'https://api.novaposhta.ua/v2.0/json/'),
        'n8n_webhook', v_carrier.n8n_create_shipment_webhook,
        'np_api_request', v_np_request,
        'tracking_url_template', v_carrier.tracking_url_template
    );
END;
$$;


--
-- Name: FUNCTION create_shipment_document(p_company_id uuid, p_source_table character varying, p_source_id uuid, p_carrier_code character varying, p_recipient_name character varying, p_recipient_phone character varying, p_recipient_city character varying, p_recipient_city_ref character varying, p_recipient_address_ref character varying, p_recipient_address_street text, p_recipient_building character varying, p_recipient_flat character varying, p_service_type character varying, p_cargo_type character varying, p_payer_type character varying, p_payment_method character varying, p_weight numeric, p_seats_amount integer, p_declared_value numeric, p_cod_amount numeric, p_description text, p_length numeric, p_width numeric, p_height numeric, p_created_by uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_shipment_document(p_company_id uuid, p_source_table character varying, p_source_id uuid, p_carrier_code character varying, p_recipient_name character varying, p_recipient_phone character varying, p_recipient_city character varying, p_recipient_city_ref character varying, p_recipient_address_ref character varying, p_recipient_address_street text, p_recipient_building character varying, p_recipient_flat character varying, p_service_type character varying, p_cargo_type character varying, p_payer_type character varying, p_payment_method character varying, p_weight numeric, p_seats_amount integer, p_declared_value numeric, p_cod_amount numeric, p_description text, p_length numeric, p_width numeric, p_height numeric, p_created_by uuid) IS 'إنشاء بوليصة شحن جديدة — تجهز الطلب لإرساله عبر n8n إلى Nova Poshta API';


--
-- Name: create_simple_chart(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_simple_chart(p_company_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
    v_base_currency VARCHAR(10);
    v_intl_currency VARCHAR(10);
    v_asset_type UUID; v_current_asset_type UUID; v_fixed_asset_type UUID;
    v_liability_type UUID; v_current_liability_type UUID; v_long_liability_type UUID;
    v_equity_type UUID; v_revenue_type UUID; v_expense_type UUID; v_cogs_type UUID;
    v_assets_id UUID; v_current_assets_id UUID;
    v_cash_grp UUID; v_banks_grp UUID; v_inv_grp UUID;
    v_fixed_assets_id UUID;
    v_exchange_assets_id UUID;
    v_liabilities_id UUID; v_current_liab_id UUID; v_long_liab_id UUID;
    v_exchange_liab_id UUID;
    v_equity_id UUID;
    v_revenue_id UUID; v_rev_ops_id UUID; v_rev_other_id UUID; v_rev_exchange_id UUID;
    v_expenses_id UUID; v_cogs_grp UUID; v_purchases_grp UUID;
    v_opex_grp UUID; v_exchange_exp_id UUID;
    v_freight_grp UUID; v_misc_grp UUID;
BEGIN
    SELECT tenant_id INTO v_tenant_id FROM companies WHERE id = p_company_id;
    IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'Company not found: %', p_company_id; END IF;
    IF EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id LIMIT 1) THEN RETURN; END IF;

    -- V6: العملة الديناميكية
    SELECT COALESCE(cas.base_currency, c.default_currency, 'USD'),
           COALESCE(cas.default_international_purchase_currency, 'USD')
    INTO v_base_currency, v_intl_currency
    FROM companies c LEFT JOIN company_accounting_settings cas ON cas.company_id = c.id
    WHERE c.id = p_company_id;
    IF v_base_currency IS NULL THEN v_base_currency := 'USD'; END IF;
    IF v_intl_currency IS NULL THEN v_intl_currency := 'USD'; END IF;
    IF v_base_currency = v_intl_currency THEN v_intl_currency := v_base_currency; END IF;

    -- Account types
    SELECT id INTO v_asset_type FROM account_types WHERE code = 'ASSET';
    SELECT id INTO v_current_asset_type FROM account_types WHERE code = 'CURRENT_ASSET';
    SELECT id INTO v_fixed_asset_type FROM account_types WHERE code = 'FIXED_ASSET';
    SELECT id INTO v_liability_type FROM account_types WHERE code = 'LIABILITY';
    SELECT id INTO v_current_liability_type FROM account_types WHERE code = 'CURRENT_LIABILITY';
    SELECT id INTO v_long_liability_type FROM account_types WHERE code IN ('LONG_TERM_LIABILITY','NON_CURRENT_LIABILITY','LIABILITY');
    IF v_long_liability_type IS NULL THEN v_long_liability_type := v_liability_type; END IF;
    SELECT id INTO v_equity_type FROM account_types WHERE code = 'EQUITY';
    SELECT id INTO v_revenue_type FROM account_types WHERE code = 'REVENUE';
    SELECT id INTO v_expense_type FROM account_types WHERE code = 'EXPENSE';
    SELECT id INTO v_cogs_type FROM account_types WHERE code = 'COGS';
    IF v_cogs_type IS NULL THEN v_cogs_type := v_expense_type; END IF;

    -- ═══ 1️⃣ الأصول ═══
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES (v_tenant_id, p_company_id, '1', 'الأصول', 'Assets', v_asset_type, NULL, false, true, v_base_currency) RETURNING id INTO v_assets_id;

    -- 11 الأصول المتداولة
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES (v_tenant_id, p_company_id, '11', 'الأصول المتداولة', 'Current Assets', v_current_asset_type, v_assets_id, false, true, v_base_currency) RETURNING id INTO v_current_assets_id;

    -- 111 الصندوق
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES (v_tenant_id, p_company_id, '111', 'الصندوق', 'Cash', v_current_asset_type, v_current_assets_id, false, true, v_base_currency) RETURNING id INTO v_cash_grp;
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, is_cash_account, currency)
    VALUES
        (v_tenant_id, p_company_id, '1111', 'صندوق - عملة محلية', 'Cash - Local Currency', v_current_asset_type, v_cash_grp, true, true, true, v_base_currency),
        (v_tenant_id, p_company_id, '1112', 'صندوق - عملة أساسية', 'Cash - Base Currency', v_current_asset_type, v_cash_grp, true, true, true, v_intl_currency);

    -- 112 البنوك
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES (v_tenant_id, p_company_id, '112', 'البنوك', 'Banks', v_current_asset_type, v_current_assets_id, false, true, v_base_currency) RETURNING id INTO v_banks_grp;
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, is_bank_account, currency)
    VALUES
        (v_tenant_id, p_company_id, '1121', 'بنك - عملة محلية', 'Bank - Local Currency', v_current_asset_type, v_banks_grp, true, true, true, v_base_currency),
        (v_tenant_id, p_company_id, '1122', 'بنك - عملة أساسية', 'Bank - Base Currency', v_current_asset_type, v_banks_grp, true, true, true, v_intl_currency);

    -- 113 العملاء
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, is_receivable, currency)
    VALUES (v_tenant_id, p_company_id, '113', 'العملاء', 'Accounts Receivable', v_current_asset_type, v_current_assets_id, false, true, true, v_base_currency);

    -- 114 المخزون
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES (v_tenant_id, p_company_id, '114', 'المخزون', 'Inventory', v_current_asset_type, v_current_assets_id, false, true, v_base_currency) RETURNING id INTO v_inv_grp;
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES
        (v_tenant_id, p_company_id, '1141', 'بضاعة جاهزة', 'Finished Goods', v_current_asset_type, v_inv_grp, true, true, v_base_currency),
        (v_tenant_id, p_company_id, '1142', 'مواد خام', 'Raw Materials', v_current_asset_type, v_inv_grp, true, true, v_base_currency);

    -- باقي الأصول المتداولة
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES
        (v_tenant_id, p_company_id, '116', 'مصاريف مقدمة', 'Prepaid Expenses', v_current_asset_type, v_current_assets_id, true, true, v_base_currency),
        (v_tenant_id, p_company_id, '117', 'ض.ق.م - مدخلات', 'VAT Input', v_current_asset_type, v_current_assets_id, true, true, v_base_currency),
        (v_tenant_id, p_company_id, '118', 'دفعات مقدمة للموردين', 'Supplier Deposits', v_current_asset_type, v_current_assets_id, true, true, v_base_currency);

    -- 12 الأصول الثابتة
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES (v_tenant_id, p_company_id, '12', 'الأصول الثابتة', 'Fixed Assets', v_fixed_asset_type, v_assets_id, false, true, v_base_currency) RETURNING id INTO v_fixed_assets_id;
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES
        (v_tenant_id, p_company_id, '121', 'أصول ثابتة', 'Fixed Assets', v_fixed_asset_type, v_fixed_assets_id, true, true, v_base_currency),
        (v_tenant_id, p_company_id, '129', 'مجمع الإهلاك', 'Accumulated Depreciation', v_fixed_asset_type, v_fixed_assets_id, true, true, v_base_currency);

    -- 🆕 13 ذمم الصرافة والحوالات
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES (v_tenant_id, p_company_id, '13', 'ذمم الصرافة والحوالات', 'Exchange & Remittance Receivables', v_current_asset_type, v_assets_id, false, true, v_base_currency) RETURNING id INTO v_exchange_assets_id;
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES
        (v_tenant_id, p_company_id, '131', 'ذمم حوالات صادرة', 'Outgoing Remittance Receivables', v_current_asset_type, v_exchange_assets_id, true, true, v_base_currency),
        (v_tenant_id, p_company_id, '132', 'ذمم حوالات واردة', 'Incoming Remittance Receivables', v_current_asset_type, v_exchange_assets_id, true, true, v_base_currency),
        (v_tenant_id, p_company_id, '133', 'ذمم رصائد الصرافة', 'Exchange Balance Receivables', v_current_asset_type, v_exchange_assets_id, true, true, v_base_currency);
    -- 134, 135 = مجموعات trigger للوكلاء/الشركاء (تُنشأ عند تفعيل الموديول)

    -- ═══ 2️⃣ الخصوم ═══
    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES (v_tenant_id, p_company_id, '2', 'الخصوم', 'Liabilities', v_liability_type, NULL, false, true, v_base_currency) RETURNING id INTO v_liabilities_id;

    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
    VALUES (v_tenant_id, p_company_id, '21', 'الخصوم المتداولة', 'Current Liabilities', v_current_liability_type, v_liabilities_id, false, true, v_base_currency) RETURNING id INTO v_current_liab_id;

    INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, is_payable, currency)
    VALUES (v_tenant_id, p_company_id, '211', 'الموردون', 'Accounts Payable', v_current_liability_type, v_current_liab_id, false, true, true, v_base_currency);

