--
-- Name: create_subscription_plan(character varying, character varying, character varying, text, integer, integer, integer, integer, integer, integer, jsonb, jsonb, numeric, numeric, character varying, integer, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_subscription_plan(p_code character varying, p_name_ar character varying, p_name_en character varying, p_description text, p_max_users integer DEFAULT 5, p_max_companies integer DEFAULT 1, p_max_branches integer DEFAULT 2, p_max_warehouses integer DEFAULT 2, p_max_products integer DEFAULT 1000, p_storage_gb integer DEFAULT 5, p_included_modules jsonb DEFAULT '[]'::jsonb, p_features jsonb DEFAULT '{}'::jsonb, p_price_monthly numeric DEFAULT 0, p_price_yearly numeric DEFAULT 0, p_currency character varying DEFAULT 'SAR'::character varying, p_trial_days integer DEFAULT 14, p_is_popular boolean DEFAULT false, p_display_order integer DEFAULT 999) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_product_id UUID;
    v_plan_id UUID;
BEGIN
    -- الحصول على product_id
    SELECT id INTO v_product_id FROM saas_products WHERE code = 'erp-saas' LIMIT 1;
    
    IF v_product_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'product_not_found',
            'message', 'المنتج الرئيسي غير موجود'
        );
    END IF;
    
    -- التحقق من عدم وجود الكود مسبقاً
    IF EXISTS (SELECT 1 FROM subscription_plans WHERE product_id = v_product_id AND code = p_code) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'code_exists',
            'message', 'كود الباقة موجود مسبقاً'
        );
    END IF;
    
    -- إنشاء الباقة
    INSERT INTO subscription_plans (
        product_id,
        code,
        name_ar,
        name_en,
        description,
        max_users,
        max_companies,
        max_branches,
        max_warehouses,
        max_products,
        storage_gb,
        included_modules,
        features,
        price_monthly,
        price_yearly,
        currency,
        trial_days,
        is_popular,
        display_order,
        is_active
    ) VALUES (
        v_product_id,
        p_code,
        p_name_ar,
        p_name_en,
        p_description,
        p_max_users,
        p_max_companies,
        p_max_branches,
        p_max_warehouses,
        p_max_products,
        p_storage_gb,
        p_included_modules,
        p_features,
        p_price_monthly,
        p_price_yearly,
        p_currency,
        p_trial_days,
        p_is_popular,
        p_display_order,
        true
    )
    RETURNING id INTO v_plan_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'plan_id', v_plan_id,
        'code', p_code,
        'message', 'تم إنشاء الباقة بنجاح'
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'exception',
            'message', SQLERRM
        );
END;
$$;


--
-- Name: create_summary_accounts_for_company(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_summary_accounts_for_company(p_company_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_base_currency VARCHAR(10);
    v_parent_id UUID;
    v_type_id UUID;
BEGIN
    SELECT tenant_id INTO v_tenant_id FROM companies WHERE id = p_company_id;
    SELECT COALESCE(default_currency, 'USD') INTO v_base_currency FROM companies WHERE id = p_company_id;

    -- ═══ 1. SUM العملاء — تحت 1131 (ذمم الجملة) أو 113 (ذمم العملاء) ═══
    SELECT id, account_type_id INTO v_parent_id, v_type_id
    FROM chart_of_accounts
    WHERE company_id = p_company_id
      AND account_code IN ('1131', '113', '1130')
      AND (is_group = true OR is_detail = false)
    ORDER BY CASE account_code WHEN '1131' THEN 1 WHEN '113' THEN 2 ELSE 3 END
    LIMIT 1;

    IF v_parent_id IS NOT NULL THEN
        INSERT INTO chart_of_accounts (
            tenant_id, company_id, account_code, name_ar, name_en,
            account_type_id, parent_id,
            is_group, is_detail, is_system, is_active,
            is_summary_account, summary_party_type,
            current_balance, currency
        ) VALUES (
            v_tenant_id, p_company_id,
            (SELECT account_code FROM chart_of_accounts WHERE id = v_parent_id) || '-SUM',
            'إجمالي ذمم العملاء', 'Total Customer Receivables',
            v_type_id, v_parent_id,
            false, true, true, true,
            true, 'customer',
            0, v_base_currency
        ) ON CONFLICT (tenant_id, company_id, account_code) DO NOTHING;
    END IF;

    -- ═══ 2. SUM الموردين — تحت 2111 أو 211 ═══
    SELECT id, account_type_id INTO v_parent_id, v_type_id
    FROM chart_of_accounts
    WHERE company_id = p_company_id
      AND account_code IN ('2111', '211', '2110')
      AND (is_group = true OR is_detail = false)
    ORDER BY CASE account_code WHEN '2111' THEN 1 WHEN '211' THEN 2 ELSE 3 END
    LIMIT 1;

    IF v_parent_id IS NOT NULL THEN
        INSERT INTO chart_of_accounts (
            tenant_id, company_id, account_code, name_ar, name_en,
            account_type_id, parent_id,
            is_group, is_detail, is_system, is_active,
            is_summary_account, summary_party_type,
            current_balance, currency
        ) VALUES (
            v_tenant_id, p_company_id,
            (SELECT account_code FROM chart_of_accounts WHERE id = v_parent_id) || '-SUM',
            'إجمالي ذمم الموردين', 'Total Supplier Payables',
            v_type_id, v_parent_id,
            false, true, true, true,
            true, 'supplier',
            0, v_base_currency
        ) ON CONFLICT (tenant_id, company_id, account_code) DO NOTHING;
    END IF;

    -- ═══ 3. SUM الموظفين — تحت 213 ═══
    SELECT id, account_type_id INTO v_parent_id, v_type_id
    FROM chart_of_accounts
    WHERE company_id = p_company_id
      AND account_code IN ('213', '2120', '2130')
      AND (is_group = true OR is_detail = false)
    ORDER BY CASE account_code WHEN '213' THEN 1 WHEN '2120' THEN 2 ELSE 3 END
    LIMIT 1;

    IF v_parent_id IS NOT NULL THEN
        INSERT INTO chart_of_accounts (
            tenant_id, company_id, account_code, name_ar, name_en,
            account_type_id, parent_id,
            is_group, is_detail, is_system, is_active,
            is_summary_account, summary_party_type,
            current_balance, currency
        ) VALUES (
            v_tenant_id, p_company_id,
            (SELECT account_code FROM chart_of_accounts WHERE id = v_parent_id) || '-SUM',
            'مستحقات الموظفين', 'Employee Payables',
            v_type_id, v_parent_id,
            false, true, true, true,
            true, 'employee',
            0, v_base_currency
        ) ON CONFLICT (tenant_id, company_id, account_code) DO NOTHING;
    END IF;

    RAISE NOTICE '✅ حسابات المجاميع (SUM) تم إنشاؤها للشركة %', p_company_id;
END;
$$;


--
-- Name: create_super_admin_policy(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_super_admin_policy(p_table_name text, p_policy_name text DEFAULT 'super_admin_access'::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_sql TEXT;
BEGIN
    -- حذف Policy القديم إن وجد
    v_sql := format('DROP POLICY IF EXISTS %I ON %I', p_policy_name, p_table_name);
    EXECUTE v_sql;
    
    -- إنشاء Policy جديد
    v_sql := format('
        CREATE POLICY %I ON %I
        FOR ALL
        USING (
            is_super_admin(auth.uid())
            OR (
                tenant_id = get_user_tenant_id(auth.uid())
                AND company_id = get_user_company_id(auth.uid())
            )
        )
    ', p_policy_name, p_table_name);
    
    EXECUTE v_sql;
END;
$$;


--
-- Name: create_supplier_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_supplier_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_parent_id UUID;
    v_account_type_id UUID;
    v_new_code VARCHAR(50);
    v_new_account_id UUID;
    v_full_code VARCHAR(200);
BEGIN
    -- الحصول على حساب الموردين الأب (2110)
    SELECT id INTO v_parent_id 
    FROM chart_of_accounts 
    WHERE company_id = NEW.company_id 
      AND account_code = '2110';
    
    IF v_parent_id IS NULL THEN
        -- لا توجد شجرة حسابات، تخطي
        RAISE NOTICE 'لا توجد شجرة حسابات للشركة، تخطي إنشاء حساب المورد';
        RETURN NEW;
    END IF;
    
    -- الحصول على نوع الحساب
    SELECT id INTO v_account_type_id FROM account_types WHERE code = 'CURRENT_LIABILITY';
    
    -- توليد رقم الحساب الجديد
    v_new_code := generate_next_account_code(NEW.tenant_id, NEW.company_id, '2110');
    v_full_code := '2000.2100.2110.' || v_new_code;
    
    -- إنشاء الحساب الفرعي للمورد
    INSERT INTO chart_of_accounts (
        tenant_id, company_id, account_code, 
        name_ar, name_en, 
        account_type_id, parent_id, 
        is_group, is_detail, level, full_code, 
        currency, is_active, is_payable
    )
    VALUES (
        NEW.tenant_id, NEW.company_id, v_new_code,
        NEW.name_ar, COALESCE(NEW.name_en, NEW.name_ar),
        v_account_type_id, v_parent_id,
        false, true, 4, v_full_code,
        COALESCE(NEW.currency, 'SAR'), true, true
    )
    RETURNING id INTO v_new_account_id;
    
    -- تحديث المورد بربط الحساب
    NEW.payable_account_id := v_new_account_id;
    
    RAISE NOTICE 'تم إنشاء حساب للمورد: % - رقم الحساب: %', NEW.name_ar, v_new_code;
    
    RETURN NEW;
END;
$$;


--
-- Name: create_tenant(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_tenant(p_name character varying, p_owner_email character varying, p_owner_name character varying, p_product_code character varying, p_plan_code character varying, p_country character varying DEFAULT NULL::character varying, p_timezone character varying DEFAULT 'UTC'::character varying, p_language character varying DEFAULT 'ar'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_tenant_code VARCHAR(50);
    v_product RECORD;
    v_plan RECORD;
    v_subscription_id UUID;
    v_trial_ends TIMESTAMPTZ;
    v_module TEXT;
BEGIN
    -- التحقق من المنتج
    SELECT * INTO v_product FROM saas_products WHERE code = p_product_code AND is_active = true;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'المنتج غير موجود');
    END IF;
    
    -- التحقق من الباقة
    SELECT * INTO v_plan FROM subscription_plans 
    WHERE product_id = v_product.id AND code = p_plan_code AND is_active = true;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'الباقة غير موجودة');
    END IF;
    
    -- التحقق من عدم تكرار الإيميل
    IF EXISTS (SELECT 1 FROM tenants WHERE owner_email = p_owner_email) THEN
        RETURN jsonb_build_object('success', false, 'error', 'البريد الإلكتروني مسجل مسبقاً');
    END IF;
    
    -- توليد كود فريد
    v_tenant_code := 'T' || EXTRACT(EPOCH FROM NOW())::BIGINT || FLOOR(RANDOM() * 1000)::INT;
    
    -- حساب نهاية الفترة التجريبية
    v_trial_ends := NOW() + (v_plan.trial_days || ' days')::INTERVAL;
    
    -- إنشاء العميل مع product_id ✅
    INSERT INTO tenants (
        code, name, owner_email, owner_name,
        country, timezone, default_language,
        status, product_id
    ) VALUES (
        v_tenant_code, p_name, p_owner_email, p_owner_name,
        p_country, p_timezone, p_language,
        'active', v_product.id
    ) RETURNING id INTO v_tenant_id;
    
    -- إنشاء الاشتراك
    INSERT INTO subscriptions (
        tenant_id, product_id, plan_id,
        status, trial_started_at, trial_ends_at,
        billing_cycle, amount, currency
    ) VALUES (
        v_tenant_id, v_product.id, v_plan.id,
        'trial', NOW(), v_trial_ends,
        'monthly', v_plan.price_monthly, v_plan.currency
    ) RETURNING id INTO v_subscription_id;
    
    -- تفعيل الموديولات من الباقة
    IF v_plan.included_modules IS NOT NULL AND jsonb_array_length(v_plan.included_modules) > 0 THEN
        FOR v_module IN SELECT jsonb_array_elements_text(v_plan.included_modules)
        LOOP
            INSERT INTO tenant_modules (tenant_id, module_code, source)
            VALUES (v_tenant_id, v_module, 'plan')
            ON CONFLICT (tenant_id, module_code) DO NOTHING;
        END LOOP;
    END IF;
    
    -- تسجيل الحدث
    INSERT INTO saas_events (tenant_id, event_type, event_data, actor_type)
    VALUES (v_tenant_id, 'tenant_created', jsonb_build_object(
        'name', p_name,
        'product', p_product_code,
        'plan', p_plan_code,
        'trial_ends', v_trial_ends
    ), 'system');
    
    RETURN jsonb_build_object(
        'success', true,
        'tenant_id', v_tenant_id,
        'tenant_code', v_tenant_code,
        'subscription_id', v_subscription_id,
        'trial_ends_at', v_trial_ends
    );
END;
$$;


--
-- Name: create_tenant_isolation_policies(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.create_tenant_isolation_policies(p_table_name text, p_has_tenant_id boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_has_tenant_id BOOLEAN;
BEGIN
    -- التحقق الفعلي من وجود عمود tenant_id
    SELECT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = p_table_name
          AND column_name = 'tenant_id'
    ) INTO v_has_tenant_id;
    
    -- إذا لم يكن لديه tenant_id، تخطي
    IF NOT v_has_tenant_id THEN
        RAISE NOTICE '⚠️ الجدول % لا يحتوي على tenant_id - تم التخطي', p_table_name;
        RETURN;
    END IF;
    -- Policy: SELECT
    EXECUTE format(
        'CREATE POLICY tenant_isolation_select ON %I 
         FOR SELECT USING (
             %s OR is_super_admin()
         )',
        p_table_name,
        CASE WHEN p_has_tenant_id 
             THEN 'tenant_id = get_current_user_tenant_id()' 
             ELSE 'true' 
        END
    );
    
    -- Policy: INSERT
    EXECUTE format(
        'CREATE POLICY tenant_isolation_insert ON %I 
         FOR INSERT WITH CHECK (
             %s OR is_super_admin()
         )',
        p_table_name,
        CASE WHEN p_has_tenant_id 
             THEN 'tenant_id = get_current_user_tenant_id()' 
             ELSE 'true' 
        END
    );
    
    -- Policy: UPDATE
    EXECUTE format(
        'CREATE POLICY tenant_isolation_update ON %I 
         FOR UPDATE USING (
             %s OR is_super_admin()
         ) WITH CHECK (
             %s OR is_super_admin()
         )',
        p_table_name,
        CASE WHEN p_has_tenant_id 
             THEN 'tenant_id = get_current_user_tenant_id()' 
             ELSE 'true' 
        END,
        CASE WHEN p_has_tenant_id 
             THEN 'tenant_id = get_current_user_tenant_id()' 
             ELSE 'true' 
        END
    );
    
    -- Policy: DELETE
    EXECUTE format(
        'CREATE POLICY tenant_isolation_delete ON %I 
         FOR DELETE USING (
             %s OR is_super_admin()
         )',
        p_table_name,
        CASE WHEN p_has_tenant_id 
             THEN 'tenant_id = get_current_user_tenant_id()' 
             ELSE 'true' 
        END
    );
    
    RAISE NOTICE '✅ تم إنشاء Policies لجدول: %', p_table_name;
END;
$$;


