--
-- Name: deduct_inventory(uuid, uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.deduct_inventory(p_warehouse_id uuid, p_product_id uuid, p_quantity numeric, p_reference_type text, p_reference_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_company_id UUID;
  v_user_id UUID;
  v_movement_number VARCHAR(50);
BEGIN
  v_user_id := auth.uid();

  -- user_profiles.id = auth.uid(), tenant_id is in companies table
  SELECT c.tenant_id, up.company_id 
  INTO v_tenant_id, v_company_id
  FROM user_profiles up
  JOIN companies c ON c.id = up.company_id
  WHERE up.id = v_user_id
  LIMIT 1;

  v_movement_number := 'AUTO-' || TO_CHAR(NOW(), 'YYYYMMDD-HH24MISS') || '-' || SUBSTR(gen_random_uuid()::text, 1, 4);

  INSERT INTO inventory_movements (
    tenant_id, company_id, movement_number, movement_date,
    movement_type, product_id,
    from_warehouse_id, quantity,
    reference_type, reference_id,
    notes, created_by
  ) VALUES (
    v_tenant_id, v_company_id, v_movement_number, CURRENT_DATE,
    'out', p_product_id,
    p_warehouse_id, ABS(p_quantity),
    p_reference_type, p_reference_id,
    'Auto deduction: ' || p_reference_type, v_user_id
  );
END;
$$;


--
-- Name: deduct_inventory_on_sale(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.deduct_inventory_on_sale() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_item RECORD;
    v_movement_number VARCHAR(50);
    v_warehouse_id UUID;
BEGIN
    -- فقط عند تأكيد الفاتورة
    IF NEW.status != 'posted' THEN
        RETURN NEW;
    END IF;
    
    -- تخطي إذا تم معالجة المخزون مسبقاً
    IF OLD.status = 'posted' THEN
        RETURN NEW;
    END IF;
    
    -- الحصول على المستودع الافتراضي
    v_warehouse_id := NEW.warehouse_id;
    IF v_warehouse_id IS NULL THEN
        SELECT id INTO v_warehouse_id
        FROM warehouses
        WHERE company_id = NEW.company_id
          AND is_active = true
        ORDER BY created_at
        LIMIT 1;
    END IF;
    
    IF v_warehouse_id IS NULL THEN
        RAISE NOTICE 'لا يوجد مستودع، تخطي خصم المخزون';
        RETURN NEW;
    END IF;
    
    -- معالجة كل صنف في الفاتورة
    FOR v_item IN 
        SELECT * FROM sales_invoice_items 
        WHERE invoice_id = NEW.id 
          AND product_id IS NOT NULL
    LOOP
        -- توليد رقم الحركة
        v_movement_number := 'MV-SI-' || NEW.invoice_number || '-' || v_item.line_number;
        
        -- إنشاء حركة مخزون (صادر - بيع)
        INSERT INTO inventory_movements (
            tenant_id, company_id,
            movement_number, movement_date,
            movement_type,
            product_id, variant_id,
            from_warehouse_id,
            quantity, unit_id,
            unit_cost, total_cost,
            reference_type, reference_id, reference_number,
            notes,
            created_by
        )
        VALUES (
            NEW.tenant_id, NEW.company_id,
            v_movement_number, NEW.invoice_date,
            'sale',
            v_item.product_id, v_item.variant_id,
            COALESCE(v_item.warehouse_id, v_warehouse_id),
            v_item.quantity, v_item.unit_id,
            v_item.unit_cost, v_item.total_cost,
            'sales_invoice', NEW.id, NEW.invoice_number,
            'خصم مخزون - فاتورة مبيعات ' || NEW.invoice_number,
            NEW.created_by
        );
        
        RAISE NOTICE 'تم خصم المخزون للصنف: % - الكمية: %', v_item.product_id, v_item.quantity;
    END LOOP;
    
    RETURN NEW;
END;
$$;


--
-- Name: deduct_inventory_stock(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.deduct_inventory_stock(p_material_id uuid, p_warehouse_id uuid, p_company_id uuid, p_quantity numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    BEGIN
        -- Deduct actual quantity + release reservation
        UPDATE inventory_stock
        SET current_quantity = GREATEST(COALESCE(current_quantity, 0) - p_quantity, 0),
            quantity_on_hand = GREATEST(COALESCE(quantity_on_hand, 0) - p_quantity, 0),
            reserved_quantity = GREATEST(COALESCE(reserved_quantity, 0) - p_quantity, 0),
            updated_at = NOW()
        WHERE material_id = p_material_id
          AND warehouse_id = p_warehouse_id
          AND company_id = p_company_id;
    END;
    $$;


--
-- Name: delete_auth_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.delete_auth_user(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_caller        uuid := auth.uid();
  v_caller_tenant uuid;
  v_target_tenant uuid;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'delete_auth_user: target user id is required';
  END IF;

  -- مسار الخلفية: لا JWT (service_role/installer/scripts) → يُسمح
  IF v_caller IS NOT NULL THEN
    -- 1) المُتصل أدمن مستأجر (أو سوبر-أدمن)
    IF NOT (is_tenant_admin(v_caller) OR is_super_admin(v_caller)) THEN
      RAISE EXCEPTION 'delete_auth_user: not authorized';
    END IF;

    -- 2) لا حذف للذات
    IF p_user_id = v_caller THEN
      RAISE EXCEPTION 'delete_auth_user: cannot delete your own account';
    END IF;

    -- 3) الهدف ضمن مستأجر المُتصل (السوبر-أدمن يتخطّى) — يُفرَض فقط إن بقي ملف الهدف
    IF NOT is_super_admin(v_caller) THEN
      v_caller_tenant := get_user_tenant_id(v_caller);
      v_target_tenant := get_user_tenant_id(p_user_id);
      IF v_caller_tenant IS NULL THEN
        RAISE EXCEPTION 'delete_auth_user: caller has no tenant';
      END IF;
      IF v_target_tenant IS NOT NULL AND v_target_tenant <> v_caller_tenant THEN
        RAISE EXCEPTION 'delete_auth_user: target user is outside your tenant';
      END IF;
    END IF;

    -- 4) لا حذف لسوبر-أدمن (مالك منصّة)
    IF is_super_admin(p_user_id) THEN
      RAISE EXCEPTION 'delete_auth_user: cannot delete a platform super-admin';
    END IF;
  END IF;

  DELETE FROM auth.users WHERE id = p_user_id;
END;
$$;


--
-- Name: delete_tenant_complete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.delete_tenant_complete(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_tenant_name    TEXT;
    v_is_protected   BOOLEAN;
    v_user_tenant_id UUID;
    v_company_ids    UUID[];
    v_user_ids       UUID[];
    v_tenant_tables  TEXT[];
    v_company_tables TEXT[];
    v_cc_tbl         TEXT[];
    v_cc_stmt        TEXT[];
    v_act_tt         TEXT[] := '{}';
    v_act_ct         TEXT[] := '{}';
    v_act_ci         INT[]  := '{}';
    v_disabled       TEXT[] := '{}';
    v_failed         TEXT[];
    v_trig_set       TEXT[];
    v_scanned        BOOLEAN := false;
    v_escalated      BOOLEAN := false;
    v_tbl TEXT; v_pass INT; v_progress BOOLEAN; v_del INT; v_i INT; v_rec RECORD;
    v_uid UUID;
BEGIN
    IF NOT is_super_admin(auth.uid()) THEN
        RETURN jsonb_build_object('success', false, 'error', 'غير مصرح: Super Admin فقط');
    END IF;
    SELECT tenant_id INTO v_user_tenant_id FROM user_profiles WHERE id = auth.uid();
    IF v_user_tenant_id = p_tenant_id THEN
        RETURN jsonb_build_object('success', false, 'error', '⛔ لا يمكنك حذف حسابك الخاص!');
    END IF;
    SELECT name, is_protected INTO v_tenant_name, v_is_protected FROM tenants WHERE id = p_tenant_id;
    IF v_tenant_name IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'المشترك غير موجود');
    END IF;
    IF v_is_protected = true THEN
        RETURN jsonb_build_object('success', false, 'error', '🛡️ هذا حساب محمي! يجب إلغاء الحماية أولاً قبل الحذف');
    END IF;

    PERFORM set_config('app.is_registering', 'true', true);
    SELECT ARRAY_AGG(id) INTO v_company_ids FROM companies WHERE tenant_id = p_tenant_id;
    -- مُعرِّفات مستخدمي المستأجر (قبل التصفير) — لتحرير المصادقة لاحقاً
    SELECT ARRAY_AGG(DISTINCT id) INTO v_user_ids FROM user_profiles
    WHERE tenant_id = p_tenant_id OR (v_company_ids IS NOT NULL AND company_id = ANY(v_company_ids));

    SELECT ARRAY_AGG(DISTINCT c.table_name) INTO v_tenant_tables
    FROM information_schema.columns c
    JOIN information_schema.tables t ON t.table_schema=c.table_schema AND t.table_name=c.table_name AND t.table_type='BASE TABLE'
    WHERE c.table_schema='public' AND c.column_name='tenant_id' AND c.table_name NOT IN ('tenants','companies','user_profiles');

    SELECT ARRAY_AGG(DISTINCT c.table_name) INTO v_company_tables
    FROM information_schema.columns c
    JOIN information_schema.tables t ON t.table_schema=c.table_schema AND t.table_name=c.table_name AND t.table_type='BASE TABLE'
    WHERE c.table_schema='public' AND c.column_name='company_id' AND c.table_name<>'companies'
      AND c.table_name NOT IN (SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='tenant_id');

    SELECT ARRAY_AGG(cc.relname), ARRAY_AGG(
        format('DELETE FROM public.%I WHERE %I IN (SELECT %I FROM public.%I WHERE %s)',
            cc.relname, ca.attname, pa.attname, pc.relname,
            CASE WHEN EXISTS(SELECT 1 FROM information_schema.columns ic WHERE ic.table_schema='public' AND ic.table_name=pc.relname AND ic.column_name='tenant_id')
                 THEN 'tenant_id = '||quote_literal(p_tenant_id::text)||'::uuid'
                 ELSE 'company_id = ANY('||quote_literal(COALESCE(v_company_ids,ARRAY[]::uuid[])::text)||'::uuid[])' END))
    INTO v_cc_tbl, v_cc_stmt
    FROM pg_constraint con
    JOIN pg_class cc ON cc.oid=con.conrelid
    JOIN pg_namespace cn ON cn.oid=cc.relnamespace AND cn.nspname='public'
    JOIN pg_class pc ON pc.oid=con.confrelid
    JOIN pg_attribute ca ON ca.attrelid=con.conrelid AND ca.attnum=con.conkey[1]
    JOIN pg_attribute pa ON pa.attrelid=con.confrelid AND pa.attnum=con.confkey[1]
    WHERE con.contype='f' AND cc.relname<>pc.relname AND array_length(con.conkey,1)=1
      AND NOT EXISTS(SELECT 1 FROM information_schema.columns ic WHERE ic.table_schema='public' AND ic.table_name=cc.relname AND ic.column_name IN ('tenant_id','company_id'))
      AND EXISTS(SELECT 1 FROM information_schema.columns ic WHERE ic.table_schema='public' AND ic.table_name=pc.relname AND ic.column_name IN ('tenant_id','company_id'));

    SELECT ARRAY_AGG(DISTINCT cl.relname) INTO v_trig_set
    FROM pg_trigger tg JOIN pg_class cl ON cl.oid=tg.tgrelid JOIN pg_namespace ns ON ns.oid=cl.relnamespace AND ns.nspname='public'
    WHERE NOT tg.tgisinternal;

    -- تصفير user_profiles + مسح بيانات المصادقة (tenant_id/company_id) لمستخدمي المستأجر
    BEGIN UPDATE user_profiles SET tenant_id=NULL, company_id=NULL WHERE tenant_id=p_tenant_id; EXCEPTION WHEN OTHERS THEN NULL; END;
    IF v_user_ids IS NOT NULL THEN
        BEGIN
            UPDATE auth.users SET
                raw_user_meta_data = COALESCE(raw_user_meta_data,'{}'::jsonb) - 'tenant_id' - 'company_id',
                raw_app_meta_data  = COALESCE(raw_app_meta_data,'{}'::jsonb)  - 'tenant_id' - 'company_id'
            WHERE id = ANY(v_user_ids);
        EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;

    FOR v_pass IN 1..80 LOOP
        v_progress := false; v_failed := '{}';

        IF NOT v_scanned THEN
            IF v_cc_stmt IS NOT NULL THEN
                FOR v_i IN 1..array_length(v_cc_stmt,1) LOOP
                    BEGIN EXECUTE v_cc_stmt[v_i]; GET DIAGNOSTICS v_del=ROW_COUNT;
                        IF v_del>0 THEN v_progress:=true; v_act_ci:=array_append(v_act_ci,v_i); END IF;
                    EXCEPTION WHEN OTHERS THEN v_act_ci:=array_append(v_act_ci,v_i); v_failed:=array_append(v_failed,v_cc_tbl[v_i]); END;
                END LOOP;
            END IF;
            IF v_tenant_tables IS NOT NULL THEN
                FOREACH v_tbl IN ARRAY v_tenant_tables LOOP
                    BEGIN EXECUTE format('DELETE FROM public.%I WHERE tenant_id=$1',v_tbl) USING p_tenant_id; GET DIAGNOSTICS v_del=ROW_COUNT;
                        IF v_del>0 THEN v_progress:=true; v_act_tt:=array_append(v_act_tt,v_tbl); END IF;
                    EXCEPTION WHEN OTHERS THEN v_act_tt:=array_append(v_act_tt,v_tbl); v_failed:=array_append(v_failed,v_tbl); END;
                END LOOP;
            END IF;
            IF v_company_ids IS NOT NULL AND v_company_tables IS NOT NULL THEN
                FOREACH v_tbl IN ARRAY v_company_tables LOOP
                    BEGIN EXECUTE format('DELETE FROM public.%I WHERE company_id=ANY($1)',v_tbl) USING v_company_ids; GET DIAGNOSTICS v_del=ROW_COUNT;
                        IF v_del>0 THEN v_progress:=true; v_act_ct:=array_append(v_act_ct,v_tbl); END IF;
                    EXCEPTION WHEN OTHERS THEN v_act_ct:=array_append(v_act_ct,v_tbl); v_failed:=array_append(v_failed,v_tbl); END;
                END LOOP;
            END IF;
            v_scanned := true;
        ELSE
            IF array_length(v_act_ci,1) IS NOT NULL THEN
                FOREACH v_i IN ARRAY v_act_ci LOOP
                    BEGIN EXECUTE v_cc_stmt[v_i]; GET DIAGNOSTICS v_del=ROW_COUNT; IF v_del>0 THEN v_progress:=true; END IF;
                    EXCEPTION WHEN OTHERS THEN v_failed:=array_append(v_failed,v_cc_tbl[v_i]); END;
                END LOOP;
            END IF;
            IF array_length(v_act_tt,1) IS NOT NULL THEN
                FOREACH v_tbl IN ARRAY v_act_tt LOOP
                    BEGIN EXECUTE format('DELETE FROM public.%I WHERE tenant_id=$1',v_tbl) USING p_tenant_id; GET DIAGNOSTICS v_del=ROW_COUNT; IF v_del>0 THEN v_progress:=true; END IF;
                    EXCEPTION WHEN OTHERS THEN v_failed:=array_append(v_failed,v_tbl); END;
                END LOOP;
            END IF;
            IF array_length(v_act_ct,1) IS NOT NULL THEN
                FOREACH v_tbl IN ARRAY v_act_ct LOOP
                    BEGIN EXECUTE format('DELETE FROM public.%I WHERE company_id=ANY($1)',v_tbl) USING v_company_ids; GET DIAGNOSTICS v_del=ROW_COUNT; IF v_del>0 THEN v_progress:=true; END IF;
                    EXCEPTION WHEN OTHERS THEN v_failed:=array_append(v_failed,v_tbl); END;
                END LOOP;
            END IF;
        END IF;

        IF v_progress THEN CONTINUE; END IF;

        IF NOT v_escalated THEN
            v_escalated := true;
            IF array_length(v_failed,1) IS NOT NULL THEN
                FOREACH v_tbl IN ARRAY v_failed LOOP
                    IF v_tbl = ANY(v_trig_set) AND NOT (v_tbl = ANY(v_disabled)) THEN
                        BEGIN EXECUTE format('ALTER TABLE public.%I DISABLE TRIGGER USER',v_tbl); v_disabled:=array_append(v_disabled,v_tbl); EXCEPTION WHEN OTHERS THEN NULL; END;
                    END IF;
                END LOOP;
                FOREACH v_tbl IN ARRAY v_failed LOOP
                    FOR v_rec IN
                        SELECT cc.relname AS child, ca.attname AS ccol,
                               (EXISTS(SELECT 1 FROM information_schema.columns ic WHERE ic.table_schema='public' AND ic.table_name=v_tbl AND ic.column_name='tenant_id')) AS p_has_tenant
                        FROM pg_constraint con
                        JOIN pg_class cc ON cc.oid=con.conrelid
                        JOIN pg_namespace cn ON cn.oid=cc.relnamespace AND cn.nspname='public'
                        JOIN pg_attribute ca ON ca.attrelid=con.conrelid AND ca.attnum=con.conkey[1]
                        JOIN information_schema.columns col ON col.table_schema='public' AND col.table_name=cc.relname AND col.column_name=ca.attname AND col.is_nullable='YES'
                        WHERE con.contype='f' AND con.confrelid=(quote_ident(v_tbl))::regclass AND array_length(con.conkey,1)=1
                    LOOP
                        BEGIN
                            IF v_rec.p_has_tenant THEN
                                EXECUTE format('UPDATE public.%I SET %I=NULL WHERE %I IN (SELECT id FROM public.%I WHERE tenant_id=$1)',v_rec.child,v_rec.ccol,v_rec.ccol,v_tbl) USING p_tenant_id;
                            ELSIF v_company_ids IS NOT NULL THEN
                                EXECUTE format('UPDATE public.%I SET %I=NULL WHERE %I IN (SELECT id FROM public.%I WHERE company_id=ANY($1))',v_rec.child,v_rec.ccol,v_rec.ccol,v_tbl) USING v_company_ids;
                            END IF;
                        EXCEPTION WHEN OTHERS THEN
                            BEGIN
                                EXECUTE format('ALTER TABLE public.%I DISABLE TRIGGER USER',v_rec.child);
                                IF v_rec.p_has_tenant THEN
                                    EXECUTE format('UPDATE public.%I SET %I=NULL WHERE %I IN (SELECT id FROM public.%I WHERE tenant_id=$1)',v_rec.child,v_rec.ccol,v_rec.ccol,v_tbl) USING p_tenant_id;
                                ELSIF v_company_ids IS NOT NULL THEN
                                    EXECUTE format('UPDATE public.%I SET %I=NULL WHERE %I IN (SELECT id FROM public.%I WHERE company_id=ANY($1))',v_rec.child,v_rec.ccol,v_rec.ccol,v_tbl) USING v_company_ids;
                                END IF;
                                EXECUTE format('ALTER TABLE public.%I ENABLE TRIGGER USER',v_rec.child);
                            EXCEPTION WHEN OTHERS THEN NULL; END;
                        END;
                    END LOOP;
                END LOOP;
            END IF;
            CONTINUE;
        END IF;
        EXIT;
    END LOOP;

    IF array_length(v_disabled,1) IS NOT NULL THEN
        FOREACH v_tbl IN ARRAY v_disabled LOOP
            BEGIN EXECUTE format('ALTER TABLE public.%I ENABLE TRIGGER USER',v_tbl); EXCEPTION WHEN OTHERS THEN NULL; END;
        END LOOP;
    END IF;

    DELETE FROM companies WHERE tenant_id=p_tenant_id;
    DELETE FROM tenants   WHERE id=p_tenant_id;

    -- ═══ تحرير بريد المستخدمين المحذوفين (غير المحظورين) لإعادة التسجيل ═══
    -- محاولة حذف كامل لصف auth.users (يتشلّل على auth.identities/sessions/…)؛
    -- عند فشله بمرجع public عابر → Tombstone (وسم ميّت) فيتحرّر البريد دائماً.
    IF v_user_ids IS NOT NULL THEN
        FOREACH v_uid IN ARRAY v_user_ids LOOP
            -- المحظور: لا نحرّر بريده (banned_until مستقبلي) ⇒ يبقى مقفلاً
            IF EXISTS (SELECT 1 FROM auth.users u WHERE u.id = v_uid
                       AND u.banned_until IS NOT NULL AND u.banned_until > now()) THEN
                CONTINUE;
            END IF;
            -- إزالة صف الملف الشخصي اليتيم (محروس باستثناء)
            BEGIN DELETE FROM public.user_profiles WHERE id = v_uid; EXCEPTION WHEN OTHERS THEN NULL; END;
            -- محاولة الحذف الكامل، وإلا Tombstone
            BEGIN
                DELETE FROM auth.users WHERE id = v_uid;
            EXCEPTION WHEN OTHERS THEN
                BEGIN
                    UPDATE auth.users
                       SET email = 'deleted_' || v_uid::text || '@deleted.texacore.local',
                           raw_user_meta_data = '{}'::jsonb,
                           raw_app_meta_data  = COALESCE(raw_app_meta_data,'{}'::jsonb)  - 'tenant_id' - 'company_id'
                     WHERE id = v_uid;
                    -- منع إعادة التصاق OAuth (Google) بالحساب الميّت ⇒ إعادة التسجيل تُنشئ حساباً نظيفاً
                    DELETE FROM auth.identities WHERE user_id = v_uid;
                EXCEPTION WHEN OTHERS THEN NULL; END;
            END;
        END LOOP;
    END IF;

    RETURN jsonb_build_object('success', true, 'message', format('تم حذف المشترك "%s" وجميع بياناته بنجاح', v_tenant_name));

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'detail', SQLSTATE);
END;
$_$;


--
-- Name: direct_post_sale(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.direct_post_sale(p_invoice_id uuid, p_rolls jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_trx            sales_transactions%ROWTYPE;
    v_item           RECORD;
    v_roll           RECORD;
    v_wh             uuid;
    v_post           jsonb;
    v_idx            int := 0;
    v_movement_ids   uuid[] := '{}';
    v_mv_id          uuid;
    v_roll_ids       uuid[] := NULL;
    v_roll_materials uuid[] := NULL;
BEGIN
    -- قفل + فحوص
    SELECT * INTO v_trx FROM sales_transactions WHERE id = p_invoice_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'الفاتورة غير موجودة');
    END IF;
    PERFORM assert_can_access_company(v_trx.company_id);
    IF v_trx.is_posted = true THEN
        RETURN jsonb_build_object('success', false, 'error', 'الفاتورة مُرحَّلة مسبقاً');
    END IF;

    -- استخراج معرّفات الرولونات المختارة (إن وُجدت)
    IF p_rolls IS NOT NULL AND jsonb_typeof(p_rolls) = 'array' AND jsonb_array_length(p_rolls) > 0 THEN
        SELECT array_agg((e->>'id')::uuid) INTO v_roll_ids
        FROM jsonb_array_elements(p_rolls) e
        WHERE (e->>'id') IS NOT NULL;
    END IF;

    -- ═══ A) خصم الرولونات الكاملة (إن وُجدت) ═══
    IF v_roll_ids IS NOT NULL AND array_length(v_roll_ids, 1) > 0 THEN
        FOR v_roll IN
            SELECT id, material_id, warehouse_id,
                   COALESCE(current_length, 0) AS len,
                   COALESCE(cost_per_meter, 0) AS cpm
            FROM fabric_rolls
            WHERE id = ANY(v_roll_ids)
              AND COALESCE(status, '') NOT IN ('sold', 'delivered')
        LOOP
            v_idx := v_idx + 1;
            v_wh := COALESCE(v_roll.warehouse_id, v_trx.stock_warehouse_id, v_trx.warehouse_id);
            IF v_wh IS NULL THEN
                RAISE EXCEPTION 'لا يوجد مستودع للرول %', v_roll.id;
            END IF;

            INSERT INTO inventory_movements (
                tenant_id, company_id, movement_number, movement_date, movement_type,
                material_id, roll_id, from_warehouse_id, quantity, unit_cost, total_cost,
                reference_type, reference_id, reference_number, notes, created_by
            ) VALUES (
                v_trx.tenant_id, v_trx.company_id,
                'SOUT-' || LEFT(p_invoice_id::text, 8) || '-R' || v_idx,
                CURRENT_DATE, 'sale',
                v_roll.material_id, v_roll.id, v_wh, v_roll.len, v_roll.cpm, v_roll.cpm * v_roll.len,
                'sale_invoice', p_invoice_id, COALESCE(v_trx.invoice_no, v_trx.draft_no),
                'بيع مباشر — إخراج رول كامل', auth.uid()
            ) RETURNING id INTO v_mv_id;
            v_movement_ids := array_append(v_movement_ids, v_mv_id);
        END LOOP;

        -- إخراج الرولونات من المتاح
        UPDATE fabric_rolls
           SET status = 'sold', updated_at = NOW()
         WHERE id = ANY(v_roll_ids)
           AND COALESCE(status, '') NOT IN ('sold', 'delivered');

        -- المواد المغطّاة بالرولونات (لاستثنائها من خصم السائب)
        SELECT array_agg(DISTINCT material_id) INTO v_roll_materials
        FROM fabric_rolls WHERE id = ANY(v_roll_ids);
    END IF;

    -- ═══ B) خصم السائب/المادة للبنود غير المغطّاة برولونات ═══
    FOR v_item IN
        SELECT id, material_id, quantity,
               COALESCE(cost_price, 0) AS cost_price, warehouse_id
        FROM sales_transaction_items
        WHERE transaction_id = p_invoice_id
          AND material_id IS NOT NULL
          AND COALESCE(quantity, 0) > 0
          AND (v_roll_materials IS NULL OR NOT (material_id = ANY(v_roll_materials)))
    LOOP
        v_idx := v_idx + 1;
        v_wh := COALESCE(v_item.warehouse_id, v_trx.stock_warehouse_id, v_trx.warehouse_id);
        IF v_wh IS NULL THEN
            RAISE EXCEPTION 'لا يوجد مستودع للبند (مادة %)', v_item.material_id;
        END IF;

        INSERT INTO inventory_movements (
            tenant_id, company_id, movement_number, movement_date, movement_type,
            material_id, from_warehouse_id, quantity, unit_cost, total_cost,
            reference_type, reference_id, reference_number, notes, created_by
        ) VALUES (
            v_trx.tenant_id, v_trx.company_id,
            'SOUT-' || LEFT(p_invoice_id::text, 8) || '-' || v_idx,
            CURRENT_DATE, 'sales_delivery',
            v_item.material_id, v_wh, v_item.quantity, v_item.cost_price, v_item.cost_price * v_item.quantity,
            'sale_invoice', p_invoice_id, COALESCE(v_trx.invoice_no, v_trx.draft_no),
            'بيع مباشر — خصم سائب', auth.uid()
        ) RETURNING id INTO v_mv_id;
        v_movement_ids := array_append(v_movement_ids, v_mv_id);
    END LOOP;

    -- ═══ C) الترحيل المحاسبي (إيراد + ضريبة + COGS + ذمم) ═══
    v_post := post_sales_invoice(p_invoice_id);
    IF NOT COALESCE((v_post->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'فشل الترحيل المحاسبي: %', COALESCE(v_post->>'error', 'غير معروف');
    END IF;

    UPDATE sales_transactions
       SET delivered_at = NOW(),
           delivery_confirmed_at = NOW(),
           delivery_confirmed_by = auth.uid(),
           stock_movement_id = COALESCE(v_movement_ids[1], stock_movement_id)
     WHERE id = p_invoice_id;

    RETURN jsonb_build_object(
        'success', true,
        'invoice_id', p_invoice_id,
        'movement_ids', to_jsonb(v_movement_ids),
        'rolls_sold', COALESCE(array_length(v_roll_ids, 1), 0),
        'posting', v_post
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'detail', SQLSTATE);
END;
$$;


--
-- Name: FUNCTION direct_post_sale(p_invoice_id uuid, p_rolls jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.direct_post_sale(p_invoice_id uuid, p_rolls jsonb) IS 'بيع مباشر ذرّي واعٍ بالرولونات: رولونات كاملة (sale) + سائب (sales_delivery) + post_sales_invoice في معاملة واحدة';


--
-- Name: disable_addon_module(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.disable_addon_module(p_tenant_id uuid, p_module_code character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_module_rec RECORD;
BEGIN
    -- التحقق من الموديول
    SELECT * INTO v_module_rec FROM tenant_modules 
    WHERE tenant_id = p_tenant_id AND module_code = p_module_code;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'الموديول غير مفعل');
    END IF;
    
    -- لا يمكن إلغاء موديولات الباقة
    IF v_module_rec.source = 'plan' THEN
        RETURN jsonb_build_object('success', false, 'error', 'لا يمكن إلغاء موديول من الباقة');
    END IF;
    
    -- التحقق من عدم وجود موديولات تعتمد عليه
    IF EXISTS (
        SELECT 1 FROM tenant_modules tm
        JOIN system_modules sm ON tm.module_code = sm.code
        WHERE tm.tenant_id = p_tenant_id 
          AND tm.is_active = true
          AND p_module_code = ANY(sm.dependencies)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'يوجد موديولات تعتمد على هذا الموديول');
    END IF;
    
    -- إلغاء التفعيل
    UPDATE tenant_modules
    SET is_active = false
    WHERE tenant_id = p_tenant_id AND module_code = p_module_code;
    
    -- تسجيل الحدث
    INSERT INTO saas_events (tenant_id, event_type, event_data, actor_type)
    VALUES (p_tenant_id, 'module_disabled', jsonb_build_object('module', p_module_code), 'admin');
    
    RETURN jsonb_build_object('success', true, 'module', p_module_code);
END;
$$;


--
-- Name: disable_tenant_language(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.disable_tenant_language(p_tenant_id uuid, p_language_code character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_user_id UUID;
    v_is_primary BOOLEAN;
    v_enabled_count INT;
BEGIN
    v_current_user_id := auth.uid();
    
    -- التحقق من أن اللغة مفعلة
    SELECT is_primary INTO v_is_primary
    FROM tenant_languages
    WHERE tenant_id = p_tenant_id
    AND language_code = p_language_code
    AND is_enabled = true;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Language not enabled or not found'
        );
    END IF;
    
    -- التحقق من أنها ليست آخر لغة
    SELECT COUNT(*) INTO v_enabled_count
    FROM tenant_languages
    WHERE tenant_id = p_tenant_id
    AND is_enabled = true;
    
    IF v_enabled_count <= 1 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Cannot disable last language'
        );
    END IF;
    
    -- تعطيل اللغة
    UPDATE tenant_languages
    SET 
        is_enabled = false,
        disabled_at = NOW(),
        disabled_by = v_current_user_id
    WHERE tenant_id = p_tenant_id
    AND language_code = p_language_code;
    
    -- إذا كانت primary، تعيين لغة أخرى كـ primary
    IF v_is_primary THEN
        UPDATE tenant_languages
        SET is_primary = true
        WHERE id = (
            SELECT id
            FROM tenant_languages
            WHERE tenant_id = p_tenant_id
            AND is_enabled = true
            ORDER BY display_order
            LIMIT 1
        );
    END IF;
    
    -- تسجيل في audit log
    PERFORM log_audit(
        'disable_language',
        'tenant_languages',
        p_tenant_id,
        p_language_code,
        NULL,
        jsonb_build_object('language_code', p_language_code)
    );
    
    RETURN jsonb_build_object(
        'success', true,
        'tenant_id', p_tenant_id,
        'language_code', p_language_code
    );
END;
$$;


--
-- Name: enable_addon_module(uuid, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.enable_addon_module(p_tenant_id uuid, p_module_code character varying, p_price_monthly numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_module RECORD;
    v_dep TEXT;
BEGIN
    -- التحقق من الموديول
    SELECT * INTO v_module FROM system_modules WHERE code = p_module_code AND is_active = true;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'الموديول غير موجود');
    END IF;
    
    -- التحقق من أنه غير مفعل
    IF EXISTS (SELECT 1 FROM tenant_modules WHERE tenant_id = p_tenant_id AND module_code = p_module_code AND is_active = true) THEN
        RETURN jsonb_build_object('success', false, 'error', 'الموديول مفعل مسبقاً');
    END IF;
    
    -- التحقق من التبعيات
    FOREACH v_dep IN ARRAY v_module.dependencies
    LOOP
        IF NOT EXISTS (SELECT 1 FROM tenant_modules WHERE tenant_id = p_tenant_id AND module_code = v_dep AND is_active = true) THEN
            RETURN jsonb_build_object('success', false, 'error', 'يجب تفعيل موديول ' || v_dep || ' أولاً');
        END IF;
    END LOOP;
    
    -- تفعيل الموديول
    INSERT INTO tenant_modules (tenant_id, module_code, source, price_monthly)
    VALUES (p_tenant_id, p_module_code, 'addon', COALESCE(p_price_monthly, v_module.price_monthly))
    ON CONFLICT (tenant_id, module_code) DO UPDATE SET
        is_active = true,
        enabled_at = NOW(),
        price_monthly = COALESCE(p_price_monthly, v_module.price_monthly);
    
    -- تسجيل الحدث
    INSERT INTO saas_events (tenant_id, event_type, event_data, actor_type)
    VALUES (p_tenant_id, 'module_enabled', jsonb_build_object(
        'module', p_module_code,
        'price', COALESCE(p_price_monthly, v_module.price_monthly)
    ), 'admin');
    
    RETURN jsonb_build_object(
        'success', true,
        'module', p_module_code
    );
END;
$$;


--
-- Name: enable_rls_with_tenant_isolation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.enable_rls_with_tenant_isolation(p_table_name text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_has_tenant_id BOOLEAN;
    v_policy_exists BOOLEAN;
    v_rls_enabled BOOLEAN;
BEGIN
    -- Check if table exists
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = p_table_name
    ) THEN
        RETURN '⚠️  Table ' || p_table_name || ' does not exist - SKIP';
    END IF;
    
    -- Check if table has tenant_id column
    SELECT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' 
            AND table_name = p_table_name
            AND column_name = 'tenant_id'
    ) INTO v_has_tenant_id;
    
    IF NOT v_has_tenant_id THEN
        RETURN '⚠️  Table ' || p_table_name || ' does not have tenant_id column - SKIP';
    END IF;
    
    -- Check if RLS already enabled
    SELECT rowsecurity INTO v_rls_enabled
    FROM pg_tables
    WHERE schemaname = 'public' AND tablename = p_table_name;
    
    IF NOT v_rls_enabled THEN
        -- Enable RLS
    END IF;
    
    -- Check if policy already exists
    SELECT EXISTS (
        SELECT 1 FROM pg_policies
        WHERE schemaname = 'public'
            AND tablename = p_table_name
            AND policyname = 'tenant_isolation'
    ) INTO v_policy_exists;
    
    IF NOT v_policy_exists THEN
        -- Create tenant isolation policy
        EXECUTE format('
            CREATE POLICY tenant_isolation ON %I
            FOR ALL 
            USING (tenant_id = current_setting(''app.current_tenant_id'', true)::uuid)
        ', p_table_name);
        RETURN '✅ Enabled RLS + Created policy on: ' || p_table_name;
    ELSE
        IF NOT v_rls_enabled THEN
            RETURN '✅ Enabled RLS on: ' || p_table_name || ' (policy existed)';
        ELSE
            RETURN '⏭️  RLS already enabled on: ' || p_table_name;
        END IF;
    END IF;
    
EXCEPTION WHEN OTHERS THEN
    RETURN '❌ Error on ' || p_table_name || ': ' || SQLERRM;
END;
$$;


--
-- Name: enable_tenant_language(uuid, character varying, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.enable_tenant_language(p_tenant_id uuid, p_language_code character varying, p_is_primary boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_limit_check JSONB;
    v_can_add BOOLEAN;
    v_current_user_id UUID;
BEGIN
    v_current_user_id := auth.uid();
    
    -- التحقق من وجود اللغة في النظام
    IF NOT EXISTS (SELECT 1 FROM system_languages WHERE code = p_language_code AND is_active = true) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Language not available in system'
        );
    END IF;
    
    -- التحقق من أن اللغة غير مفعلة مسبقاً
    IF EXISTS (SELECT 1 FROM tenant_languages WHERE tenant_id = p_tenant_id AND language_code = p_language_code AND is_enabled = true) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Language already enabled'
        );
    END IF;
    
    -- التحقق من الحد الأقصى
    v_limit_check := check_language_limit(p_tenant_id);
    v_can_add := (v_limit_check->>'can_add_more')::BOOLEAN;
    
    IF NOT v_can_add THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Language limit reached',
            'limit_info', v_limit_check
        );
    END IF;
    
    -- إذا كانت أول لغة، تصبح primary تلقائياً
    IF NOT EXISTS (SELECT 1 FROM tenant_languages WHERE tenant_id = p_tenant_id AND is_enabled = true) THEN
        p_is_primary := true;
    END IF;
    
    -- إذا كانت primary جديدة، إلغاء primary من اللغات الأخرى
    IF p_is_primary THEN
        UPDATE tenant_languages
        SET is_primary = false
        WHERE tenant_id = p_tenant_id;
    END IF;
    
    -- إدراج أو تحديث اللغة
    INSERT INTO tenant_languages (
        tenant_id,
        language_code,
        language_name_ar,
        language_name_en,
        is_primary,
        is_enabled,
        enabled_at,
        enabled_by
    )
    SELECT
        p_tenant_id,
        p_language_code,
        sl.name_ar,
        sl.name_en,
        p_is_primary,
        true,
        NOW(),
        v_current_user_id
    FROM system_languages sl
    WHERE sl.code = p_language_code
    ON CONFLICT (tenant_id, language_code)
    DO UPDATE SET
        is_enabled = true,
        is_primary = p_is_primary,
        enabled_at = NOW(),
        enabled_by = v_current_user_id,
        disabled_at = NULL,
        disabled_by = NULL;
    
    -- تسجيل في audit log
    PERFORM log_audit(
        'enable_language',
        'tenant_languages',
        p_tenant_id,
        p_language_code,
        NULL,
        jsonb_build_object('language_code', p_language_code, 'is_primary', p_is_primary)
    );
    
    RETURN jsonb_build_object(
        'success', true,
        'tenant_id', p_tenant_id,
        'language_code', p_language_code,
        'is_primary', p_is_primary
    );
END;
$$;


--
-- Name: end_login_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.end_login_session(p_session_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
