--
-- Name: enforce_brand_isolation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.enforce_brand_isolation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_user_id UUID := auth.uid();
    v_is_platform_admin BOOLEAN;
BEGIN
    IF v_current_user_id IS NULL THEN
        RETURN NEW;
    END IF;

    v_is_platform_admin := is_platform_admin(v_current_user_id);
    
    -- Platform Admin يتخطى التحقق
    IF v_is_platform_admin THEN
        RETURN NEW;
    END IF;

    -- التحقق من أن tenant_id ينتمي لنفس براند المستخدم
    IF NEW.tenant_id IS NOT NULL THEN
        IF NOT is_same_brand(NEW.tenant_id, v_current_user_id) THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكنك إضافة بيانات لتينانت خارج براندك / Not allowed: You cannot add data to a tenant outside your brand';
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: enforce_je_balanced_on_post(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.enforce_je_balanced_on_post() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_debit  numeric;
  v_credit numeric;
  v_lines  integer;
  v_becoming_posted boolean;
BEGIN
  -- نتحقق فقط عند الانتقال إلى «مُرحَّل» (لا أثناء بناء القيد)
  v_becoming_posted :=
       (COALESCE(NEW.is_posted, false) = true AND COALESCE(OLD.is_posted, false) = false)
    OR (lower(COALESCE(NEW.status, '')) = 'posted'
        AND lower(COALESCE(OLD.status, '')) IS DISTINCT FROM 'posted');

  IF v_becoming_posted THEN
    SELECT COALESCE(SUM(debit), 0), COALESCE(SUM(credit), 0), COUNT(*)
      INTO v_debit, v_credit, v_lines
      FROM public.journal_entry_lines
      WHERE entry_id = NEW.id;

    IF v_lines = 0 THEN
      RAISE EXCEPTION 'لا يمكن ترحيل قيد بلا سطور (القيد %)', COALESCE(NEW.entry_number, NEW.id::text)
        USING ERRCODE = 'check_violation';
    END IF;

    IF ABS(v_debit - v_credit) > 0.01 THEN
      RAISE EXCEPTION 'القيد غير متوازن: مدين % ≠ دائن % (القيد %)',
        v_debit, v_credit, COALESCE(NEW.entry_number, NEW.id::text)
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_plan_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.enforce_plan_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_type      text := TG_ARGV[0];
  v_plan_type text;
  v_max       int;
  r           jsonb;
BEGIN
  IF NEW.tenant_id IS NULL THEN RETURN NEW; END IF;

  -- Cheap pre-check: the active plan's type + its max for this limit (indexed join, no COUNT).
  SELECT sp.plan_type,
         CASE v_type
           WHEN 'products'         THEN sp.max_products
           WHEN 'users'            THEN sp.max_users
           WHEN 'customers'        THEN sp.max_customers
           WHEN 'invoices_monthly' THEN sp.max_invoices_monthly
           WHEN 'companies'        THEN sp.max_companies
           WHEN 'branches'         THEN sp.max_branches
           WHEN 'warehouses'       THEN sp.max_warehouses
         END
    INTO v_plan_type, v_max
  FROM public.tenant_subscriptions ts
  JOIN public.subscription_plans sp ON sp.id = ts.plan_id
  WHERE ts.tenant_id = NEW.tenant_id
    AND ts.status IN ('trial','active','grace')
  ORDER BY CASE ts.status WHEN 'active' THEN 1 WHEN 'trial' THEN 2 ELSE 3 END
  LIMIT 1;

  -- Enforce ONLY the free plan. Paid plans were never hard-enforced; do NOT
  -- retroactively block them (a paid tenant may already be over an old limit).
  IF v_plan_type IS DISTINCT FROM 'free' THEN RETURN NEW; END IF;
  -- No active subscription, unset, or unlimited (-1) → allow, no count.
  IF v_max IS NULL OR v_max < 0 THEN RETURN NEW; END IF;

  -- Finite limit → authoritative check (this is the only path that COUNTs).
  BEGIN
    r := public.check_plan_limits(NEW.tenant_id, v_type);
  EXCEPTION WHEN OTHERS THEN
    RETURN NEW;  -- fail-open
  END;

  IF r IS NOT NULL
     AND (r->>'allowed') = 'false'
     AND COALESCE(r->>'error','') NOT IN ('no_active_subscription','plan_not_found')
  THEN
    RAISE EXCEPTION 'PLAN_LIMIT_EXCEEDED: % (%/%)',
        v_type, COALESCE(r->>'current','?'), COALESCE(r->>'max','?')
      USING ERRCODE = 'check_violation',
            HINT = 'بلغت حدّ باقتك — يرجى الترقية / Plan limit reached — please upgrade';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: ensure_company_fiscal_year(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.ensure_company_fiscal_year(p_company_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id uuid;
  v_start_month int;
  v_year int;
  v_start date;
  v_end date;
  v_fy_id uuid;
  v_existing uuid;
  i int;
  v_p_start date;
  v_p_end date;
BEGIN
  SELECT tenant_id, COALESCE(fiscal_year_start_month, 1)
    INTO v_tenant_id, v_start_month
  FROM companies WHERE id = p_company_id;

  IF v_tenant_id IS NULL THEN
    RETURN NULL;  -- شركة غير موجودة
  END IF;

  -- السنة المالية الحالية بناءً على شهر البداية
  v_year := EXTRACT(YEAR FROM CURRENT_DATE)::int;
  v_start := make_date(v_year, v_start_month, 1);
  IF CURRENT_DATE < v_start THEN
    v_start := make_date(v_year - 1, v_start_month, 1);
  END IF;
  v_end := (v_start + interval '1 year' - interval '1 day')::date;

  -- موجودة سلفاً؟
  SELECT id INTO v_existing FROM fiscal_years
  WHERE company_id = p_company_id AND start_date = v_start;
  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  INSERT INTO fiscal_years (tenant_id, company_id, name, code, start_date, end_date, is_current, is_closed)
  VALUES (
    v_tenant_id, p_company_id,
    'السنة المالية ' || EXTRACT(YEAR FROM v_start)::text,
    'FY-' || EXTRACT(YEAR FROM v_start)::text,
    v_start, v_end, true, false
  )
  RETURNING id INTO v_fy_id;

  -- 12 فترة شهرية
  FOR i IN 0..11 LOOP
    v_p_start := (v_start + (i || ' months')::interval)::date;
    v_p_end := (v_p_start + interval '1 month' - interval '1 day')::date;
    INSERT INTO accounting_periods (tenant_id, company_id, fiscal_year_id, name, period_number, start_date, end_date, is_closed)
    VALUES (
      v_tenant_id, p_company_id, v_fy_id,
      to_char(v_p_start, 'YYYY-MM'), i + 1, v_p_start, v_p_end, false
    );
  END LOOP;

  RETURN v_fy_id;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'ensure_company_fiscal_year warning for %: %', p_company_id, SQLERRM;
  RETURN NULL;
END;
$$;


--
-- Name: ensure_extended_chart_improvements(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.ensure_extended_chart_improvements(p_company_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_base_currency VARCHAR(10);
    v_asset_type UUID;
    v_recv_grp UUID;
    v_inv_grp UUID;
    v_1134_id UUID;
BEGIN
    -- لا نُحسّن شركة بلا شجرة أصلاً
    SELECT tenant_id INTO v_tenant_id FROM chart_of_accounts WHERE company_id = p_company_id LIMIT 1;
    IF v_tenant_id IS NULL THEN RETURN; END IF;

    SELECT COALESCE(cas.base_currency, c.default_currency, 'USD') INTO v_base_currency
    FROM companies c LEFT JOIN company_accounting_settings cas ON cas.company_id = c.id
    WHERE c.id = p_company_id;
    IF v_base_currency IS NULL THEN v_base_currency := 'USD'; END IF;

    SELECT id INTO v_asset_type FROM account_types WHERE code = 'ASSET';
    SELECT id INTO v_recv_grp  FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '113' LIMIT 1;
    SELECT id INTO v_inv_grp   FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '114' LIMIT 1;

    -- 1134 زبائن الإنترنت (تحت 113)
    IF v_recv_grp IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '1134') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, is_receivable, is_system, currency)
        VALUES (v_tenant_id, p_company_id, '1134', 'زبائن الإنترنت', 'Online Customers', v_asset_type, v_recv_grp, false, true, true, true, v_base_currency);
    END IF;

    SELECT id INTO v_1134_id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '1134' LIMIT 1;

    -- 1134-SUM إجمالي ذمم زبائن الإنترنت (تحت 1134)
    IF v_1134_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '1134-SUM') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, is_summary_account, summary_party_type, is_system, currency)
        VALUES (v_tenant_id, p_company_id, '1134-SUM', 'إجمالي ذمم زبائن الإنترنت', 'Total Online Customers Receivables', v_asset_type, v_1134_id, true, true, true, 'customer', true, v_base_currency);
    END IF;

    -- 1145 مشتريات بالطريق (تحت 114 المخزون)
    IF v_inv_grp IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '1145') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, is_system, currency)
        VALUES (v_tenant_id, p_company_id, '1145', 'مشتريات بالطريق', 'Purchases in Transit', v_asset_type, v_inv_grp, true, true, true, v_base_currency);
    END IF;
END;
$$;


--
-- Name: execute_confirmation_item(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.execute_confirmation_item(p_item_type text, p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_company uuid;
    v_user uuid := auth.uid();
    v_n integer;
    v_tenant uuid;
    v_atype text;
    v_adata jsonb;
    v_party_id uuid;
    v_party_name text;
    v_amount numeric;
    v_fund uuid;
    v_num text;
    v_doc_id uuid;
    v_inv uuid;
    v_cont uuid;
    v_rem uuid;
    v_pinv uuid;
    v_assignee uuid;
    v_assignee_name text;
    v_cust uuid;
    v_wh uuid;
    v_title text;
    v_cat text;
    v_orig_tg bigint;
    v_orig_at timestamptz;
    v_orig_name text;
    v_orig_phone text;
BEGIN
    IF p_item_type = 'payment_receipt' THEN
        SELECT company_id INTO v_company FROM payment_receipts WHERE id = p_item_id;
        IF v_company IS NULL THEN RAISE EXCEPTION 'سند القبض غير موجود'; END IF;
        PERFORM assert_can_access_company(v_company);
        UPDATE payment_receipts SET status='confirmed', updated_at=now() WHERE id=p_item_id AND status='draft';
        GET DIAGNOSTICS v_n = ROW_COUNT;
        IF v_n = 0 THEN RETURN jsonb_build_object('ok', false, 'message', 'السند ليس بحالة مسودة'); END IF;
        RETURN jsonb_build_object('ok', true, 'message', 'تم تأكيد سند القبض وترحيل القيد');

    ELSIF p_item_type = 'payment_voucher' THEN
        SELECT company_id INTO v_company FROM payment_vouchers WHERE id = p_item_id;
        IF v_company IS NULL THEN RAISE EXCEPTION 'سند الصرف غير موجود'; END IF;
        PERFORM assert_can_access_company(v_company);
        UPDATE payment_vouchers SET status='confirmed', updated_at=now() WHERE id=p_item_id AND status='draft';
        GET DIAGNOSTICS v_n = ROW_COUNT;
        IF v_n = 0 THEN RETURN jsonb_build_object('ok', false, 'message', 'السند ليس بحالة مسودة'); END IF;
        RETURN jsonb_build_object('ok', true, 'message', 'تم تأكيد سند الصرف وترحيل القيد');

    ELSIF p_item_type = 'journal_entry' THEN
        SELECT company_id INTO v_company FROM journal_entries WHERE id = p_item_id;
        IF v_company IS NULL THEN RAISE EXCEPTION 'القيد غير موجود'; END IF;
        PERFORM assert_can_access_company(v_company);
        PERFORM post_journal_entry(p_item_id, v_user);
        RETURN jsonb_build_object('ok', true, 'message', 'تم ترحيل القيد');

    ELSIF p_item_type = 'sales_invoice' THEN
        SELECT company_id INTO v_company FROM sales_transactions WHERE id = p_item_id;
        IF v_company IS NULL THEN RAISE EXCEPTION 'فاتورة المبيعات غير موجودة'; END IF;
        PERFORM assert_can_access_company(v_company);
        UPDATE sales_transactions SET stage='confirmed', confirmation_status='confirmed', updated_at=now()
          WHERE id=p_item_id AND stage='draft';
        GET DIAGNOSTICS v_n = ROW_COUNT;
        IF v_n = 0 THEN RETURN jsonb_build_object('ok', false, 'message', 'الفاتورة ليست بحالة مسودة'); END IF;
        RETURN jsonb_build_object('ok', true, 'message', 'تم تأكيد فاتورة المبيعات — جاهزة للتسليم عند أمين المستودع');

    ELSIF p_item_type = 'purchase_invoice' THEN
        SELECT company_id INTO v_company FROM purchase_transactions WHERE id = p_item_id;
        IF v_company IS NULL THEN RAISE EXCEPTION 'فاتورة المشتريات غير موجودة'; END IF;
        PERFORM assert_can_access_company(v_company);
        UPDATE purchase_transactions SET stage='confirmed', confirmation_status='confirmed', updated_at=now()
          WHERE id=p_item_id AND stage='draft';
        GET DIAGNOSTICS v_n = ROW_COUNT;
        IF v_n = 0 THEN RETURN jsonb_build_object('ok', false, 'message', 'الفاتورة ليست بحالة مسودة'); END IF;
        RETURN jsonb_build_object('ok', true, 'message', 'تم تأكيد فاتورة المشتريات');

    ELSIF p_item_type = 'stock_transfer' THEN
        SELECT company_id INTO v_company FROM stock_transfers WHERE id = p_item_id;
        IF v_company IS NULL THEN RAISE EXCEPTION 'المناقلة غير موجودة'; END IF;
        PERFORM assert_can_access_company(v_company);
        UPDATE stock_transfers SET status='confirmed', confirmed_by=v_user, confirmed_at=now(), updated_at=now()
          WHERE id=p_item_id AND status='pending';
        GET DIAGNOSTICS v_n = ROW_COUNT;
        IF v_n = 0 THEN RETURN jsonb_build_object('ok', false, 'message', 'المناقلة ليست بحالة معلّقة'); END IF;
        RETURN jsonb_build_object('ok', true, 'message', 'تم تأكيد المناقلة');

    ELSIF p_item_type = 'pending_action' THEN
        SELECT pa.company_id, pa.tenant_id, pa.action_type, pa.action_data,
               pa.created_by_telegram_id, pa.created_at, up.full_name, up.phone
          INTO v_company, v_tenant, v_atype, v_adata,
               v_orig_tg, v_orig_at, v_orig_name, v_orig_phone
          FROM pending_actions pa LEFT JOIN user_profiles up ON up.id = pa.created_by_user_id
         WHERE pa.id = p_item_id AND pa.status='pending';
        IF v_company IS NULL THEN RETURN jsonb_build_object('ok', false, 'message', 'المسودة غير موجودة أو ليست معلّقة'); END IF;
        PERFORM assert_can_access_company(v_company);
        v_amount := NULLIF(v_adata->>'amount','')::numeric;
        v_inv  := NULLIF(COALESCE(v_adata->>'sales_transaction_id', v_adata->>'invoice_id'),'')::uuid;
        v_cont := NULLIF(v_adata->>'container_id','')::uuid;
        v_rem  := NULLIF(v_adata->>'remittance_id','')::uuid;
        v_pinv := NULLIF(v_adata->>'purchase_transaction_id','')::uuid;

        IF v_atype = 'payment_received' THEN
            v_party_name := COALESCE(v_adata->>'from_name', v_adata->>'from_customer', v_adata->>'customer_name');
            v_party_id := NULLIF(v_adata->>'customer_id','')::uuid;
            IF v_party_id IS NULL AND v_party_name IS NOT NULL THEN
                SELECT id INTO v_party_id FROM customers
                  WHERE company_id=v_company AND (name_ar ILIKE '%'||v_party_name||'%' OR name_en ILIKE '%'||v_party_name||'%' OR company_name ILIKE '%'||v_party_name||'%')
                  ORDER BY length(COALESCE(name_en,name_ar)) LIMIT 1;
            END IF;
            IF v_party_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'message', 'تعذّر مطابقة العميل: '||COALESCE(v_party_name,'؟')||' — افتح المسودة وحدّد العميل يدوياً'); END IF;
            IF v_amount IS NULL OR v_amount <= 0 THEN RETURN jsonb_build_object('ok', false, 'message', 'مبلغ غير صالح بالمسودة'); END IF;
            v_fund := resolve_payment_fund(v_adata, v_company, v_user);
            IF v_fund IS NULL THEN RETURN jsonb_build_object('ok', false, 'message', 'لا صندوق متاح — حدّد الصندوق'); END IF;
            v_num := 'RCV-TG-'||to_char(now(),'YYMMDDHH24MISS');
            INSERT INTO payment_receipts(company_id, tenant_id, receipt_number, receipt_date, customer_id, amount, payment_method, status, treasury_account_id, sales_transaction_id, container_id, remittance_id, created_by, notes)
              VALUES(v_company, v_tenant, v_num, CURRENT_DATE, v_party_id, v_amount, 'cash', 'confirmed', v_fund, v_inv, v_cont, v_rem, v_user, 'من مسودة تلغرام')
              RETURNING id INTO v_doc_id;
            PERFORM relink_telegram_doc(p_item_id, 'payment_receipt', v_doc_id);
            BEGIN
              INSERT INTO document_activity(tenant_id, entity_type, entity_id, activity_type, event_code, content, is_pinned, created_by)
                VALUES(v_tenant, 'payment_receipt', v_doc_id, 'event', 'origin',
                       'أُنشئ من مسودة تلغرام بواسطة '||COALESCE(v_orig_name,'—')
                         ||CASE WHEN v_orig_phone IS NOT NULL THEN ' ('||v_orig_phone||')' ELSE '' END
                         ||CASE WHEN v_orig_tg IS NOT NULL THEN ' • TG:'||v_orig_tg::text ELSE '' END
                         ||' بتاريخ '||to_char(COALESCE(v_orig_at, now()),'YYYY-MM-DD HH24:MI'),
                       true, v_user);
            EXCEPTION WHEN OTHERS THEN NULL; END;
            UPDATE pending_actions SET status='confirmed', confirmed_at=now(), confirmed_via='web', confirmed_by=v_user WHERE id=p_item_id;
            RETURN jsonb_build_object('ok', true, 'message', 'تم إنشاء وترحيل سند قبض بمبلغ '||v_amount, 'document_id', v_doc_id);

        ELSIF v_atype = 'payment_made' THEN
            v_party_name := COALESCE(v_adata->>'to_name', v_adata->>'supplier_name');
            v_party_id := NULLIF(v_adata->>'supplier_id','')::uuid;
            IF v_party_id IS NULL AND v_party_name IS NOT NULL THEN
                SELECT id INTO v_party_id FROM suppliers
                  WHERE company_id=v_company AND (name_ar ILIKE '%'||v_party_name||'%' OR name_en ILIKE '%'||v_party_name||'%' OR company_name ILIKE '%'||v_party_name||'%')
                  ORDER BY length(COALESCE(name_en,name_ar)) LIMIT 1;
            END IF;
            IF v_party_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'message', 'تعذّر مطابقة المورد: '||COALESCE(v_party_name,'؟')||' — افتح المسودة وحدّد المورد يدوياً'); END IF;
            IF v_amount IS NULL OR v_amount <= 0 THEN RETURN jsonb_build_object('ok', false, 'message', 'مبلغ غير صالح بالمسودة'); END IF;
            v_fund := resolve_payment_fund(v_adata, v_company, v_user);
            IF v_fund IS NULL THEN RETURN jsonb_build_object('ok', false, 'message', 'لا صندوق متاح — حدّد الصندوق'); END IF;
            v_num := 'PAY-TG-'||to_char(now(),'YYMMDDHH24MISS');
            INSERT INTO payment_vouchers(company_id, tenant_id, voucher_number, voucher_date, supplier_id, amount, payment_method, status, treasury_account_id, purchase_transaction_id, container_id, remittance_id, created_by, notes)
              VALUES(v_company, v_tenant, v_num, CURRENT_DATE, v_party_id, v_amount, 'cash', 'confirmed', v_fund, v_pinv, v_cont, v_rem, v_user, 'من مسودة تلغرام')
              RETURNING id INTO v_doc_id;
            PERFORM relink_telegram_doc(p_item_id, 'payment_voucher', v_doc_id);
            BEGIN
              INSERT INTO document_activity(tenant_id, entity_type, entity_id, activity_type, event_code, content, is_pinned, created_by)
                VALUES(v_tenant, 'payment_voucher', v_doc_id, 'event', 'origin',
                       'أُنشئ من مسودة تلغرام بواسطة '||COALESCE(v_orig_name,'—')
                         ||CASE WHEN v_orig_phone IS NOT NULL THEN ' ('||v_orig_phone||')' ELSE '' END
                         ||CASE WHEN v_orig_tg IS NOT NULL THEN ' • TG:'||v_orig_tg::text ELSE '' END
                         ||' بتاريخ '||to_char(COALESCE(v_orig_at, now()),'YYYY-MM-DD HH24:MI'),
                       true, v_user);
            EXCEPTION WHEN OTHERS THEN NULL; END;
            UPDATE pending_actions SET status='confirmed', confirmed_at=now(), confirmed_via='web', confirmed_by=v_user WHERE id=p_item_id;
            RETURN jsonb_build_object('ok', true, 'message', 'تم إنشاء وترحيل سند صرف بمبلغ '||v_amount, 'document_id', v_doc_id);

        ELSIF v_atype = 'task' THEN
            v_title := COALESCE(NULLIF(v_adata->>'title',''), NULLIF(v_adata->>'description',''), 'مهمة');
            v_assignee := NULLIF(v_adata->>'assignee_id','')::uuid;
            v_assignee_name := v_adata->>'assignee_name';
            IF v_assignee IS NULL AND v_assignee_name IS NOT NULL THEN
                SELECT id INTO v_assignee FROM user_profiles
                  WHERE company_id=v_company AND (full_name ILIKE '%'||v_assignee_name||'%' OR display_name ILIKE '%'||v_assignee_name||'%') LIMIT 1;
            END IF;
            v_wh := NULLIF(v_adata->>'warehouse_id','')::uuid;
            IF v_wh IS NULL AND (v_adata->>'warehouse_name') IS NOT NULL THEN
                SELECT id INTO v_wh FROM warehouses
                  WHERE company_id=v_company AND (name ILIKE '%'||(v_adata->>'warehouse_name')||'%' OR name_ar ILIKE '%'||(v_adata->>'warehouse_name')||'%' OR name_en ILIKE '%'||(v_adata->>'warehouse_name')||'%') LIMIT 1;
            END IF;
            v_cust := NULLIF(v_adata->>'customer_id','')::uuid;
            IF v_wh IS NULL AND v_cust IS NULL AND (v_adata->>'customer_name') IS NOT NULL THEN
                SELECT id INTO v_cust FROM customers
                  WHERE company_id=v_company AND (name_ar ILIKE '%'||(v_adata->>'customer_name')||'%' OR name_en ILIKE '%'||(v_adata->>'customer_name')||'%' OR company_name ILIKE '%'||(v_adata->>'customer_name')||'%') LIMIT 1;
            END IF;
            v_cat := COALESCE(NULLIF(v_adata->>'category',''), CASE WHEN v_wh IS NOT NULL THEN 'stock_count' ELSE 'custom' END);
            INSERT INTO crm_tasks(company_id, tenant_id, title, description, task_category, priority, status,
                   assigned_to, assigned_by, due_date, related_entity_type, related_entity_id, created_by)
              VALUES(v_company, v_tenant, v_title, NULLIF(v_adata->>'description',''),
                   v_cat, COALESCE(NULLIF(v_adata->>'priority',''),'medium'), 'open',
                   v_assignee, v_user, NULLIF(v_adata->>'due_date','')::timestamptz,
                   CASE WHEN v_wh IS NOT NULL THEN 'warehouse' WHEN v_cust IS NOT NULL THEN 'customer' ELSE NULL END,
                   COALESCE(v_wh, v_cust), v_user)
              RETURNING id INTO v_doc_id;
            UPDATE pending_actions SET status='confirmed', confirmed_at=now(), confirmed_via='web', confirmed_by=v_user WHERE id=p_item_id;
            RETURN jsonb_build_object('ok', true,
                   'message', 'تم إنشاء المهمة'||CASE WHEN v_wh IS NOT NULL THEN ' (جرد مستودع — تُسنَد للأمين تلقائياً)' WHEN v_assignee IS NOT NULL THEN ' وإسنادها' ELSE '' END,
                   'document_id', v_doc_id);

        ELSE
            RETURN jsonb_build_object('ok', false, 'message', 'نوع المسودة غير مدعوم للتنفيذ التلقائي بعد: '||v_atype);
        END IF;

    ELSE
        RAISE EXCEPTION 'نوع تأكيد غير مدعوم: %', p_item_type;
    END IF;
END;
$$;


--
-- Name: execute_pos_delivery(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.execute_pos_delivery(p_invoice_id uuid, p_warehouse_id uuid, p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_delivery_id UUID;
  v_company_id UUID;
  v_user_id UUID;
  v_movement_number VARCHAR(50);
  v_note_number VARCHAR(50);
BEGIN
  v_user_id := auth.uid();
  
  SELECT up.company_id INTO v_company_id
  FROM user_profiles up WHERE up.id = v_user_id LIMIT 1;

  -- Generate delivery note number
  v_note_number := 'POS-DN-' || TO_CHAR(NOW(), 'YYYYMMDD-HH24MISS');

  -- 1. إنشاء إذن تسليم
  INSERT INTO delivery_notes (
    tenant_id, company_id, customer_id, warehouse_id,
    note_number, note_date, status, notes, created_by
  )
  SELECT 
    si.tenant_id, v_company_id, si.customer_id, p_warehouse_id,
    v_note_number, CURRENT_DATE, 'delivered',
    'POS Auto-Delivery for Invoice #' || si.invoice_number,
    v_user_id
  FROM sales_invoices si
  WHERE si.id = p_invoice_id
  RETURNING id INTO v_delivery_id;

  -- 2. نسخ بنود الفاتورة
  INSERT INTO delivery_note_items (
    tenant_id, delivery_note_id, product_id, 
    quantity_ordered, quantity_to_deliver, quantity_delivered
  )
  SELECT 
    p_tenant_id, v_delivery_id, sii.product_id,
    sii.quantity, sii.quantity, sii.quantity
  FROM sales_invoice_items sii
  WHERE sii.invoice_id = p_invoice_id;

  -- 3. تسجيل حركة مخزون (خصم)
  INSERT INTO inventory_movements (
    tenant_id, company_id, movement_number, movement_date,
    movement_type, product_id, from_warehouse_id,
    quantity, reference_type, reference_id,
    notes, created_by
  )
  SELECT 
    p_tenant_id, v_company_id,
    'POS-' || TO_CHAR(NOW(), 'YYYYMMDD-HH24MISS') || '-' || ROW_NUMBER() OVER (),
    CURRENT_DATE,
    'out', sii.product_id, p_warehouse_id,
    sii.quantity, 'pos_sale', p_invoice_id,
    'POS auto-deduction', v_user_id
  FROM sales_invoice_items sii
  WHERE sii.invoice_id = p_invoice_id;

  -- 4. تحديث حالة الفاتورة
  UPDATE sales_invoices SET status = 'posted' WHERE id = p_invoice_id;

  RETURN jsonb_build_object(
    'success', true,
    'invoice_id', p_invoice_id,
    'delivery_id', v_delivery_id,
    'message', 'POS sale completed'
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM,
    'invoice_id', p_invoice_id
  );
END;
$$;


--
-- Name: execute_readonly_query(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.execute_readonly_query(query_text text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET statement_timeout TO '5000'
    AS $$
DECLARE
  result JSON;
  clean_query TEXT;
BEGIN
  -- Security: Normalize and validate
  clean_query := LOWER(TRIM(query_text));
  
  -- Only allow SELECT and WITH (CTE) statements
  IF NOT (clean_query LIKE 'select%' OR clean_query LIKE 'with%') THEN
    RAISE EXCEPTION 'Only SELECT queries are allowed';
  END IF;
  
  -- Block any mutation keywords
  IF clean_query ~ '\b(insert|update|delete|drop|alter|create|truncate|grant|revoke|execute|copy|pg_)\b' THEN
    RAISE EXCEPTION 'Mutation or system queries are not allowed';
  END IF;
  
  -- Execute with row limit
  EXECUTE 'SELECT COALESCE(json_agg(t), ''[]''::json) FROM (' || query_text || ' LIMIT 500) t' INTO result;
  
  RETURN result;
END;
$$;


--
-- Name: execute_readonly_query(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.execute_readonly_query(query_text text, p_company_id uuid DEFAULT NULL::uuid, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET statement_timeout TO '10000'
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result JSON;
  clean_query TEXT;
  has_isolation BOOLEAN := FALSE;
BEGIN
  -- Normalize: remove ALL whitespace from start, lowercase
  clean_query := LOWER(REGEXP_REPLACE(TRIM(BOTH FROM query_text), '^\s+', '', 'g'));
  clean_query := REGEXP_REPLACE(clean_query, '\s+', ' ', 'g');
  
  IF NOT (clean_query LIKE 'select %' OR clean_query LIKE 'with %' OR clean_query = 'select' OR clean_query LIKE 'select*%') THEN
    RAISE EXCEPTION 'Only SELECT queries are allowed. Got: %', LEFT(clean_query, 50);
  END IF;
  
  IF clean_query ~ '\b(insert|update|delete|drop|alter|create|truncate|grant|revoke)\b' THEN
    RAISE EXCEPTION 'Mutation queries are not allowed';
  END IF;
  
  -- SECURITY: Query must contain company_id OR tenant_id
  IF p_company_id IS NOT NULL AND LOWER(query_text) LIKE '%' || p_company_id::text || '%' THEN
    has_isolation := TRUE;
  END IF;
  IF p_tenant_id IS NOT NULL AND LOWER(query_text) LIKE '%' || p_tenant_id::text || '%' THEN
    has_isolation := TRUE;
  END IF;
  IF LOWER(query_text) LIKE '%information_schema%' THEN
    has_isolation := TRUE;
  END IF;
  
  IF NOT has_isolation AND (p_company_id IS NOT NULL OR p_tenant_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Query must filter by company_id or tenant_id';
  END IF;
  
  EXECUTE 'SELECT COALESCE(json_agg(t), ''[]''::json) FROM (' || query_text || ' LIMIT 500) t' INTO result;
  RETURN result;
END;
$$;


--
-- Name: execute_recurring_entry(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.execute_recurring_entry(p_history_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_history RECORD;
    v_recurring RECORD;
    v_journal_entry_id UUID;
    v_line RECORD;
    v_total_debit NUMERIC := 0;
    v_total_credit NUMERIC := 0;
BEGIN
    -- جلب سجل التاريخ
    SELECT * INTO v_history FROM recurring_entry_history WHERE id = p_history_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'History record not found');
    END IF;
    
    -- التحقق من الحالة
    IF v_history.status != 'pending' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Entry already processed');
    END IF;
    
    IF v_history.approval_status NOT IN ('approved', 'auto_approved') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Entry not approved');
    END IF;
    
    -- جلب القيد المتكرر
    SELECT * INTO v_recurring FROM recurring_entries WHERE id = v_history.recurring_entry_id;
    
    -- إنشاء القيد المحاسبي الفعلي
    INSERT INTO journal_entries (
        tenant_id, company_id, branch_id,
        entry_date, description, description_ar,
        entry_type, reference_type, reference_id,
        currency, status, created_by
    ) VALUES (
        v_recurring.tenant_id, v_recurring.company_id, v_recurring.branch_id,
        v_history.scheduled_date, v_recurring.name_en, v_recurring.name_ar,
        'recurring', 'recurring_entry', v_recurring.id,
        v_recurring.currency, 'draft', p_user_id
    ) RETURNING id INTO v_journal_entry_id;
    
    -- إضافة بنود القيد
    FOR v_line IN
        SELECT * FROM recurring_entry_lines WHERE recurring_entry_id = v_recurring.id ORDER BY line_number
    LOOP
        INSERT INTO journal_entry_lines (
            tenant_id, entry_id, line_number, account_id,
            debit, credit, description, cost_center_id
        ) VALUES (
            v_recurring.tenant_id, v_journal_entry_id, v_line.line_number, v_line.account_id,
            v_line.debit, v_line.credit, v_line.description, v_line.cost_center_id
        );
        
        v_total_debit := v_total_debit + v_line.debit;
        v_total_credit := v_total_credit + v_line.credit;
    END LOOP;
    
    -- تحديث إجماليات القيد
    UPDATE journal_entries
    SET total_debit = v_total_debit, total_credit = v_total_credit
    WHERE id = v_journal_entry_id;
    
    -- ترحيل تلقائي إذا مفعّل
    IF v_recurring.auto_post THEN
        UPDATE journal_entries
        SET status = 'posted', is_posted = true, posted_at = NOW(), posted_by = p_user_id
        WHERE id = v_journal_entry_id;
    END IF;
    
    -- تحديث سجل التاريخ
    UPDATE recurring_entry_history
    SET 
        journal_entry_id = v_journal_entry_id,
        executed_at = NOW(),
        executed_by = p_user_id,
        status = 'executed'
    WHERE id = p_history_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'journal_entry_id', v_journal_entry_id,
        'total_debit', v_total_debit,
        'total_credit', v_total_credit,
        'auto_posted', v_recurring.auto_post
    );
    
EXCEPTION WHEN OTHERS THEN
    UPDATE recurring_entry_history
    SET status = 'failed', error_message = SQLERRM
    WHERE id = p_history_id;
    
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: execute_recurring_entry(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.execute_recurring_entry(p_history_id uuid, p_user_id uuid, p_force_post boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_history RECORD;
    v_recurring RECORD;
    v_line RECORD;
    v_journal_entry_id UUID;
    v_total_debit NUMERIC := 0;
    v_total_credit NUMERIC := 0;
    v_should_post BOOLEAN;
BEGIN
    SELECT * INTO v_history FROM recurring_entry_history WHERE id = p_history_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'History record not found');
    END IF;

    IF v_history.approval_status NOT IN ('approved', 'auto_approved') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Entry not approved');
    END IF;

    SELECT * INTO v_recurring FROM recurring_entries WHERE id = v_history.recurring_entry_id;
    v_should_post := v_recurring.auto_post OR p_force_post;

    -- 1. إنشاء القيد كمسودة أولاً (لتجنب chk_balanced_entry)
    INSERT INTO journal_entries (
        tenant_id, company_id, branch_id,
        entry_date, description, description_ar,
        entry_type, reference_type, reference_id,
        currency, status, created_by
    ) VALUES (
        v_recurring.tenant_id, v_recurring.company_id, v_recurring.branch_id,
        v_history.scheduled_date, v_recurring.name_en, v_recurring.name_ar,
        'recurring', 'recurring_entry', v_recurring.id,
        v_recurring.currency, 'draft', p_user_id
    ) RETURNING id INTO v_journal_entry_id;

    -- 2. إضافة البنود مع حساب الإجماليات
    FOR v_line IN
        SELECT * FROM recurring_entry_lines WHERE recurring_entry_id = v_recurring.id ORDER BY line_number
    LOOP
        INSERT INTO journal_entry_lines (
            tenant_id, entry_id, line_number, account_id,
            debit, credit, description, cost_center_id
        ) VALUES (
            v_recurring.tenant_id, v_journal_entry_id, v_line.line_number, v_line.account_id,
            v_line.debit, v_line.credit, v_line.description, v_line.cost_center_id
        );
        v_total_debit := v_total_debit + v_line.debit;
        v_total_credit := v_total_credit + v_line.credit;
    END LOOP;

    -- 3. تحديث الإجماليات + الترحيل إذا لزم (في خطوة واحدة)
    UPDATE journal_entries
    SET 
        total_debit = v_total_debit, 
        total_credit = v_total_credit,
        status = CASE WHEN v_should_post THEN 'posted' ELSE 'draft' END,
        is_posted = v_should_post,
        posted_at = CASE WHEN v_should_post THEN NOW() ELSE NULL END,
        posted_by = CASE WHEN v_should_post THEN p_user_id ELSE NULL END
    WHERE id = v_journal_entry_id;

    -- 4. تحديث سجل التاريخ
    UPDATE recurring_entry_history
    SET
        journal_entry_id = v_journal_entry_id,
        executed_at = NOW(),
        executed_by = p_user_id,
        status = 'executed'
    WHERE id = p_history_id;

    RETURN jsonb_build_object(
        'success', true,
        'journal_entry_id', v_journal_entry_id,
        'total_debit', v_total_debit,
        'total_credit', v_total_credit,
        'auto_posted', v_should_post
    );

EXCEPTION WHEN OTHERS THEN
    UPDATE recurring_entry_history
    SET status = 'failed', error_message = SQLERRM
    WHERE id = p_history_id;

    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: execute_report(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.execute_report(p_template_id uuid, p_parameters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_template RECORD;
    v_sql TEXT;
    v_result JSONB;
    v_count INTEGER;
BEGIN
    -- جلب القالب
    SELECT * INTO v_template FROM report_templates WHERE id = p_template_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Template not found');
    END IF;
    
    -- بناء الاستعلام
    v_sql := 'SELECT ';
    
    -- الأعمدة
    SELECT string_agg(
        (col->>'source') || ' AS ' || COALESCE(col->>'alias', 'col_' || ordinality::text),
        ', '
    ) INTO v_sql
    FROM jsonb_array_elements(v_template.columns) WITH ORDINALITY AS col(col, ordinality);
    
    v_sql := 'SELECT ' || v_sql || ' FROM ' || v_template.source_table;
    
    -- إضافة الـ joins
    IF v_template.joins IS NOT NULL AND jsonb_array_length(v_template.joins) > 0 THEN
        SELECT v_sql || ' ' || string_agg(
            COALESCE(j->>'type', 'LEFT') || ' JOIN ' || 
            (j->>'table') || 
            COALESCE(' AS ' || (j->>'alias'), '') || 
            ' ON ' || (j->>'on'),
            ' '
        )
        INTO v_sql
        FROM jsonb_array_elements(v_template.joins) AS j;
    END IF;
    
    -- تحديث عداد الاستخدام
    UPDATE report_templates
    SET use_count = use_count + 1, last_used_at = NOW()
    WHERE id = p_template_id;
    
    -- ملاحظة: التنفيذ الفعلي يحتاج أمان إضافي
    -- هذه نسخة مبسطة للتوضيح
    
    RETURN jsonb_build_object(
        'success', true,
        'template_name', v_template.name_ar,
        'sql_preview', v_sql,
        'message', 'Report execution requires frontend implementation'
    );
    
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: export_tenant_data(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.export_tenant_data(p_tenant_id uuid, p_tables text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_result JSONB := '{}';
    v_table TEXT;
    v_data JSONB;
    v_default_tables TEXT[] := ARRAY[
        'companies', 'branches', 'user_profiles', 'currencies'
    ];
BEGIN
    IF NOT is_super_admin() THEN
        RETURN jsonb_build_object('error', 'Unauthorized');
    END IF;
    
    IF p_tables IS NULL THEN
        p_tables := v_default_tables;
    END IF;
    
    FOREACH v_table IN ARRAY p_tables
    LOOP
        IF EXISTS (
            SELECT 1 FROM information_schema.tables 
            WHERE table_schema = 'public' AND table_name = v_table
        ) AND EXISTS (
            SELECT 1 FROM information_schema.columns 
            WHERE table_schema = 'public' 
              AND table_name = v_table 
              AND column_name = 'tenant_id'
        ) THEN
            EXECUTE format(
                'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) FROM %I t WHERE tenant_id = $1',
                v_table
            ) INTO v_data USING p_tenant_id;
            
            v_result := v_result || jsonb_build_object(v_table, v_data);
        END IF;
    END LOOP;
    
    RETURN v_result || jsonb_build_object(
        '_export_info', jsonb_build_object(
            'tenant_id', p_tenant_id,
            'exported_at', NOW(),
            'tables', p_tables
        )
    );
END;
$_$;


--
-- Name: fill_ecom_item_material_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fill_ecom_item_material_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.material_id IS NULL AND NEW.product_id IS NOT NULL THEN
    SELECT ep.material_id INTO NEW.material_id
    FROM ecommerce_products ep
    WHERE ep.id = NEW.product_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: finalize_container_costs(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.finalize_container_costs(p_container_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_container RECORD;
    v_allocation_result JSONB;
BEGIN
    -- جلب بيانات الكونتينر
    SELECT * INTO v_container
    FROM containers
    WHERE id = p_container_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Container not found',
            'error_ar', 'الكونتينر غير موجود'
        );
    END IF;
    
    -- التحقق من عدم التثبيت المسبق
    IF v_container.is_cost_finalized = true THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Container costs already finalized',
            'error_ar', 'تكاليف الكونتينر مثبتة بالفعل'
        );
    END IF;
    
    -- توزيع التكاليف أولاً
    v_allocation_result := allocate_container_costs(p_container_id, v_container.cost_allocation_method);
    
    IF NOT (v_allocation_result->>'success')::BOOLEAN THEN
        RETURN v_allocation_result;
    END IF;
    
    -- تثبيت الكونتينر
    UPDATE containers
    SET 
        is_cost_finalized = true,
        finalized_at = NOW(),
        finalized_by = p_user_id,
        final_goods_cost = (v_allocation_result->>'total_goods_value')::NUMERIC,
        updated_at = NOW()
    WHERE id = p_container_id;
    
    -- إرجاع النتيجة
    RETURN jsonb_build_object(
        'success', true,
        'container_id', p_container_id,
        'finalized_at', NOW(),
        'finalized_by', p_user_id,
        'allocation', v_allocation_result
    );
    
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM,
        'error_code', SQLSTATE
    );
END;
$$;


--
-- Name: fix_entry_type_from_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fix_entry_type_from_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- Sales entries
    IF NEW.reference_type IN ('sales_invoice', 'sales_cogs', 'sales_return') AND (NEW.entry_type IS NULL OR NEW.entry_type = 'manual') THEN
        NEW.entry_type := 'sales';
    END IF;
    -- Purchase entries
    IF NEW.reference_type IN ('purchase_invoice', 'purchase_return') AND (NEW.entry_type IS NULL OR NEW.entry_type = 'manual') THEN
        NEW.entry_type := 'purchase_invoice';
    END IF;
    -- Container entries
    IF NEW.reference_type IN ('container', 'container_tax', 'container_close', 'container_expense') AND (NEW.entry_type IS NULL OR NEW.entry_type = 'manual') THEN
        NEW.entry_type := 'purchase_invoice';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fix_identity_id_mismatch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fix_identity_id_mismatch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- Ensure identity.id matches the user_id for email provider
    -- This fixes an issue where inviteUserByEmail creates a random identity.id
    IF NEW.provider = 'email' AND NEW.id::text != NEW.user_id::text THEN
        NEW.id = NEW.user_id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_autoassign_warehouse_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_autoassign_warehouse_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_keeper uuid;
BEGIN
    IF NEW.assigned_to IS NULL AND NEW.related_entity_type = 'warehouse' AND NEW.related_entity_id IS NOT NULL THEN
        SELECT user_id INTO v_keeper FROM user_warehouse_permissions
          WHERE warehouse_id = NEW.related_entity_id AND COALESCE(is_keeper,false) = true
          ORDER BY assigned_at NULLS LAST LIMIT 1;
        IF v_keeper IS NULL THEN
            SELECT user_id INTO v_keeper FROM user_warehouse_permissions
              WHERE warehouse_id = NEW.related_entity_id AND COALESCE(can_count,false) = true LIMIT 1;
        END IF;
        IF v_keeper IS NOT NULL THEN NEW.assigned_to := v_keeper; END IF;
    END IF;
    RETURN NEW;
END $$;


--
-- Name: fn_container_status_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_container_status_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    rule JSONB;
    rule_user_id UUID;
    rule_trigger TEXT;
    rule_enabled BOOLEAN;
    rule_role TEXT;
    v_container_name TEXT;
    v_container_number TEXT;
    new_status_label_ar TEXT;
    new_status_label_en TEXT;
    notification_title_ar TEXT;
    notification_title_en TEXT;
    notification_body_ar TEXT;
    notification_body_en TEXT;
BEGIN
    IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
    IF NEW.notification_rules IS NULL OR NEW.notification_rules = '[]'::JSONB OR jsonb_array_length(NEW.notification_rules) = 0 THEN RETURN NEW; END IF;
    
    v_container_number := COALESCE(NEW.container_number, NEW.shipment_number, 'N/A');
    v_container_name := COALESCE(NEW.container_name, v_container_number);
    
    new_status_label_ar := CASE NEW.status
        WHEN 'draft' THEN 'مسودة' WHEN 'booked' THEN 'تم الحجز' WHEN 'loading' THEN 'جاري التحميل'
        WHEN 'in_transit' THEN 'بالبحر' WHEN 'at_port' THEN 'وصل الميناء' WHEN 'customs' THEN 'بالجمركة'
        WHEN 'cleared' THEN 'تم التخليص' WHEN 'delivered' THEN 'تم التسليم' WHEN 'received' THEN 'تم الاستلام'
        ELSE NEW.status END;
    
    new_status_label_en := CASE NEW.status
        WHEN 'draft' THEN 'Draft' WHEN 'booked' THEN 'Booked' WHEN 'loading' THEN 'Loading'
        WHEN 'in_transit' THEN 'In Transit' WHEN 'at_port' THEN 'At Port' WHEN 'customs' THEN 'At Customs'
        WHEN 'cleared' THEN 'Cleared' WHEN 'delivered' THEN 'Delivered' WHEN 'received' THEN 'Received'
        ELSE NEW.status END;
    
    FOR rule IN SELECT jsonb_array_elements(NEW.notification_rules)
    LOOP
        rule_enabled := COALESCE((rule ->> 'enabled')::BOOLEAN, false);
        rule_trigger := rule ->> 'trigger_status';
        rule_user_id := (rule ->> 'user_id')::UUID;
        rule_role := COALESCE(rule ->> 'role', 'unknown');
        
        IF NOT rule_enabled THEN CONTINUE; END IF;
        IF rule_trigger IS NULL OR rule_trigger != NEW.status THEN CONTINUE; END IF;
        IF rule_user_id IS NULL THEN CONTINUE; END IF;
        
        notification_title_ar := 'كونتينر ' || v_container_number || ' — ' || new_status_label_ar;
        notification_title_en := 'Container ' || v_container_number || ' — ' || new_status_label_en;
        
        IF rule_role = 'warehouse' THEN
            notification_body_ar := 'الكونتينر "' || v_container_name || '" أصبح جاهزاً للاستلام في المستودع';
            notification_body_en := 'Container "' || v_container_name || '" is ready for warehouse receiving';
        ELSIF rule_role = 'sales' THEN
            notification_body_ar := 'الكونتينر "' || v_container_name || '" وصل للحالة: ' || new_status_label_ar;
            notification_body_en := 'Container "' || v_container_name || '" reached status: ' || new_status_label_en;
        ELSE
            notification_body_ar := 'حالة الكونتينر تغيرت إلى: ' || new_status_label_ar;
            notification_body_en := 'Container status changed to: ' || new_status_label_en;
        END IF;
        
        INSERT INTO notifications (tenant_id, user_id, title, body, type, source_type, source_id, metadata)
        VALUES (
            NEW.company_id, rule_user_id,
            notification_title_ar || ' | ' || notification_title_en,
            notification_body_ar || ' | ' || notification_body_en,
            CASE WHEN NEW.status IN ('cleared','received','delivered') THEN 'success'
                 WHEN NEW.status = 'customs' THEN 'warning' ELSE 'info' END,
            'container', NEW.id,
            jsonb_build_object(
                'container_number', v_container_number, 'container_name', v_container_name,
                'old_status', OLD.status, 'new_status', NEW.status, 'role', rule_role,
                'status_label_ar', new_status_label_ar, 'status_label_en', new_status_label_en
            )
        );
    END LOOP;
    RETURN NEW;
END;
$$;


--
-- Name: fn_ensure_single_default_bank(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_ensure_single_default_bank() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF NEW.is_default = true THEN
        UPDATE company_bank_accounts
        SET is_default = false
        WHERE company_id = NEW.company_id
          AND id != NEW.id
          AND is_default = true;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_fix_payment_currency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_fix_payment_currency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_base text;
BEGIN
    IF NEW.currency IS NULL OR NEW.currency = 'SAR' THEN
        SELECT default_currency INTO v_base FROM companies WHERE id = NEW.company_id;
        IF v_base IS NOT NULL AND v_base <> 'SAR' THEN
            NEW.currency := v_base;
            IF NEW.exchange_rate IS NULL OR NEW.exchange_rate = 0 THEN NEW.exchange_rate := 1; END IF;
        END IF;
    END IF;
    RETURN NEW;
END $$;


--
-- Name: fn_mark_all_notifications_read(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_mark_all_notifications_read() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE affected INTEGER;
BEGIN
    UPDATE notifications SET is_read = true, read_at = now(), updated_at = now()
    WHERE user_id = auth.uid() AND is_read = false;
    GET DIAGNOSTICS affected = ROW_COUNT;
    RETURN affected;
END;
$$;


--
-- Name: fn_mark_notifications_read(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_mark_notifications_read(notification_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE affected INTEGER;
BEGIN
    UPDATE notifications SET is_read = true, read_at = now(), updated_at = now()
    WHERE id = ANY(notification_ids) AND user_id = auth.uid() AND is_read = false;
    GET DIAGNOSTICS affected = ROW_COUNT;
    RETURN affected;
END;
$$;


--
-- Name: fn_mark_overdue_installments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_mark_overdue_installments() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE payment_schedule_items
    SET status = 'overdue', updated_at = NOW()
    WHERE status = 'pending'
      AND due_date < CURRENT_DATE;
END;
$$;


--
-- Name: fn_notify_task_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_notify_task_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF NEW.assigned_to IS NOT NULL AND NEW.assigned_to IS DISTINCT FROM NEW.created_by THEN
        INSERT INTO notifications(user_id, tenant_id, title, body, type, source_type, source_id, metadata)
          VALUES(NEW.assigned_to, NEW.company_id, '📋 مهمة جديدة: '||NEW.title, NEW.description,
                 'info', 'task', NEW.id, jsonb_build_object('event','task_assigned','category',NEW.task_category));
        PERFORM fn_tg_notify_user(NEW.company_id, NEW.assigned_to,
            '📋 <b>مهمة جديدة</b>'||E'\n'||COALESCE(NEW.title,'')||
            CASE WHEN NEW.due_date IS NOT NULL THEN E'\n📅 الاستحقاق: '||to_char(NEW.due_date,'YYYY-MM-DD') ELSE '' END);
    END IF;
    RETURN NEW;
END $$;


--
-- Name: fn_notify_task_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_notify_task_completion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_mgr uuid;
BEGIN
    IF NEW.status = 'completed' AND OLD.status IS DISTINCT FROM 'completed' THEN
        v_mgr := COALESCE(NEW.assigned_by, NEW.created_by);
        IF v_mgr IS NOT NULL AND v_mgr IS DISTINCT FROM NEW.assigned_to THEN
            INSERT INTO notifications(user_id, tenant_id, title, body, type, source_type, source_id, metadata)
              VALUES(v_mgr, NEW.company_id, '✅ اكتملت مهمة: '||NEW.title, NEW.outcome,
                     'success', 'task', NEW.id, jsonb_build_object('event','task_completed','completed_by',NEW.assigned_to));
            PERFORM fn_tg_notify_user(NEW.company_id, v_mgr,
                '✅ <b>اكتملت مهمة</b>'||E'\n'||COALESCE(NEW.title,'')||
                CASE WHEN NEW.outcome IS NOT NULL THEN E'\n📝 '||NEW.outcome ELSE '' END);
        END IF;
    END IF;
    RETURN NEW;
END $$;


--
-- Name: fn_purchase_invoice_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_purchase_invoice_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    status_ar TEXT; status_en TEXT; notif_type TEXT; v_invoice_num TEXT;
BEGIN
    IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
    IF NEW.created_by IS NULL THEN RETURN NEW; END IF;
    v_invoice_num := COALESCE(NEW.invoice_number, 'N/A');
    
    status_ar := CASE NEW.status
        WHEN 'draft' THEN 'مسودة' WHEN 'pending' THEN 'بانتظار الموافقة'
        WHEN 'approved' THEN 'تمت الموافقة' WHEN 'confirmed' THEN 'مؤكدة'
        WHEN 'posted' THEN 'مرحّلة' WHEN 'paid' THEN 'مدفوعة'
        WHEN 'partial_paid' THEN 'مدفوعة جزئياً' WHEN 'cancelled' THEN 'ملغاة'
        WHEN 'rejected' THEN 'مرفوضة' ELSE NEW.status END;
    
    status_en := CASE NEW.status
        WHEN 'draft' THEN 'Draft' WHEN 'pending' THEN 'Pending Approval'
        WHEN 'approved' THEN 'Approved' WHEN 'confirmed' THEN 'Confirmed'
        WHEN 'posted' THEN 'Posted' WHEN 'paid' THEN 'Paid'
        WHEN 'partial_paid' THEN 'Partially Paid' WHEN 'cancelled' THEN 'Cancelled'
        WHEN 'rejected' THEN 'Rejected' ELSE NEW.status END;
    
    notif_type := CASE 
        WHEN NEW.status IN ('approved','posted','paid') THEN 'success'
        WHEN NEW.status IN ('cancelled','rejected') THEN 'error'
        WHEN NEW.status = 'pending' THEN 'warning' ELSE 'info' END;
    
    INSERT INTO notifications (tenant_id, user_id, title, body, type, source_type, source_id, metadata)
    VALUES (
        NEW.company_id, NEW.created_by,
        'فاتورة مشتريات ' || v_invoice_num || ' — ' || status_ar || ' | Purchase Invoice ' || v_invoice_num || ' — ' || status_en,
        'حالة فاتورة المشتريات تغيرت إلى: ' || status_ar || ' | Purchase invoice status changed to: ' || status_en,
        notif_type, 'purchase_invoice', NEW.id,
        jsonb_build_object('invoice_number', v_invoice_num, 'old_status', OLD.status, 'new_status', NEW.status, 'status_label_ar', status_ar, 'status_label_en', status_en)
    );
    RETURN NEW;
END;
$$;


