--
-- Name: fn_send_task_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_send_task_reminders() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE r record; v_n int := 0;
BEGIN
    FOR r IN
        SELECT * FROM crm_tasks
        WHERE reminder_at IS NOT NULL AND reminder_at <= now()
          AND status IN ('open','in_progress') AND assigned_to IS NOT NULL
        LIMIT 200
    LOOP
        INSERT INTO notifications(user_id, tenant_id, title, body, type, source_type, source_id, metadata)
          VALUES(r.assigned_to, r.company_id, '⏰ تذكير بمهمة: '||r.title, r.description,
                 'warning', 'task', r.id, jsonb_build_object('event','task_reminder'));
        PERFORM fn_tg_notify_user(r.company_id, r.assigned_to, '⏰ <b>تذكير بمهمة</b>'||E'\n'||COALESCE(r.title,''));
        UPDATE crm_tasks SET reminder_at = NULL WHERE id = r.id;  -- لا تكرّر التذكير
        v_n := v_n + 1;
    END LOOP;
    RETURN v_n;
END $$;


--
-- Name: fn_tg_notify_user(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_tg_notify_user(p_company uuid, p_user uuid, p_text text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_token text; v_chat bigint;
BEGIN
    IF p_user IS NULL OR p_company IS NULL THEN RETURN; END IF;
    SELECT integrations->'telegram'->>'bot_token' INTO v_token
      FROM companies WHERE id = p_company AND integrations->'telegram'->>'bot_token' IS NOT NULL LIMIT 1;
    IF v_token IS NULL THEN RETURN; END IF;
    SELECT telegram_chat_id::bigint INTO v_chat
      FROM telegram_connections WHERE user_id = p_user AND is_active = true AND telegram_chat_id IS NOT NULL LIMIT 1;
    IF v_chat IS NULL THEN RETURN; END IF;
    PERFORM net.http_post(
        url := 'https://api.telegram.org/bot' || v_token || '/sendMessage',
        headers := '{"Content-Type": "application/json"}'::jsonb,
        body := jsonb_build_object('chat_id', v_chat, 'text', p_text, 'parse_mode', 'HTML'),
        timeout_milliseconds := 20000
    );
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'fn_tg_notify_user failed: %', SQLERRM;
END $$;


--
-- Name: fn_transfer_status_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_transfer_status_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_transfer_number TEXT;
    v_from_wh_name TEXT;
    v_to_wh_name TEXT;
    v_creator UUID;
    v_title TEXT;
    v_body TEXT;
    v_driver_info TEXT;
    v_tracking TEXT;
    v_keeper RECORD;
BEGIN
    IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;

    v_transfer_number := COALESCE(NEW.transfer_number, NEW.id::TEXT);
    v_creator := NEW.created_by;

    SELECT COALESCE(name_ar, name_en, 'مستودع') INTO v_from_wh_name
    FROM warehouses WHERE id = NEW.from_warehouse_id;

    SELECT COALESCE(name_ar, name_en, 'مستودع') INTO v_to_wh_name
    FROM warehouses WHERE id = NEW.to_warehouse_id;

    -- Build shipping info
    v_driver_info := '';
    v_tracking := '';
    IF NEW.status = 'shipped' THEN
        IF NEW.shipping_method = 'company_driver' AND NEW.driver_name IS NOT NULL THEN
            v_driver_info := ' | السائق: ' || NEW.driver_name;
            IF NEW.vehicle_number IS NOT NULL THEN
                v_driver_info := v_driver_info || ' (' || NEW.vehicle_number || ')';
            END IF;
        ELSIF NEW.shipping_method = 'external_truck' AND NEW.driver_name IS NOT NULL THEN
            v_driver_info := ' | سائق خارجي: ' || NEW.driver_name;
        ELSIF NEW.shipping_method = 'shipping_company' AND NEW.shipping_carrier IS NOT NULL THEN
            v_driver_info := ' | شركة شحن: ' || NEW.shipping_carrier;
        END IF;
        IF NEW.tracking_number IS NOT NULL THEN
            v_tracking := ' | رقم التتبع: ' || NEW.tracking_number;
        END IF;
    END IF;

    -- ══════════════════════════════════════════════════
    -- 1. confirmed → إشعار لكل أمناء المستودع المصدر
    -- ══════════════════════════════════════════════════
    IF NEW.status = 'confirmed' THEN
        FOR v_keeper IN
            SELECT user_id FROM warehouse_keepers 
            WHERE warehouse_id = NEW.from_warehouse_id
        LOOP
            INSERT INTO notifications (tenant_id, user_id, title, body, type, source_type, source_id, metadata)
            VALUES (
                NEW.tenant_id, v_keeper.user_id,
                '📋 مناقلة جديدة — ' || v_transfer_number,
                'طلب مناقلة من ' || v_from_wh_name || ' إلى ' || v_to_wh_name || ' — الرجاء تجهيز البضاعة وبدء التحميل',
                'info', 'stock_transfer', NEW.id,
                jsonb_build_object(
                    'transfer_number', v_transfer_number,
                    'from_warehouse', v_from_wh_name,
                    'to_warehouse', v_to_wh_name,
                    'status', 'confirmed',
                    'action', 'prepare_and_load'
                )
            );
        END LOOP;
    END IF;

    -- ══════════════════════════════════════════════════
    -- 2. shipped → إشعار لكل أمناء المستودع الوجهة
    -- ══════════════════════════════════════════════════
    IF NEW.status = 'shipped' THEN
        FOR v_keeper IN
            SELECT user_id FROM warehouse_keepers 
            WHERE warehouse_id = NEW.to_warehouse_id
        LOOP
            INSERT INTO notifications (tenant_id, user_id, title, body, type, source_type, source_id, metadata)
            VALUES (
                NEW.tenant_id, v_keeper.user_id,
                '🚚 شحنة في الطريق — ' || v_transfer_number,
                'تم شحن بضاعة من ' || v_from_wh_name || ' إلى ' || v_to_wh_name 
                    || ' — الرجاء الاستعداد للاستلام' || v_driver_info || v_tracking,
                'warning', 'stock_transfer', NEW.id,
                jsonb_build_object(
                    'transfer_number', v_transfer_number,
                    'from_warehouse', v_from_wh_name,
                    'to_warehouse', v_to_wh_name,
                    'status', 'shipped',
                    'action', 'receive_goods',
                    'shipping_method', NEW.shipping_method,
                    'driver_name', NEW.driver_name,
                    'vehicle_number', NEW.vehicle_number,
                    'tracking_number', NEW.tracking_number,
                    'shipping_carrier', NEW.shipping_carrier
                )
            );
        END LOOP;
    END IF;

    -- ══════════════════════════════════════════════════
    -- 3. received/completed → إشعار لمُنشئ المناقلة
    -- ══════════════════════════════════════════════════
    IF NEW.status IN ('received', 'completed') AND v_creator IS NOT NULL THEN
        INSERT INTO notifications (tenant_id, user_id, title, body, type, source_type, source_id, metadata)
        VALUES (
            NEW.tenant_id, v_creator,
            '✅ مناقلة مكتملة — ' || v_transfer_number,
            'تم استلام المناقلة من ' || v_from_wh_name || ' في ' || v_to_wh_name || ' — المناقلة مكتملة بنجاح',
            'success', 'stock_transfer', NEW.id,
            jsonb_build_object(
                'transfer_number', v_transfer_number,
                'from_warehouse', v_from_wh_name,
                'to_warehouse', v_to_wh_name,
                'status', NEW.status,
                'action', 'completed'
            )
        );
    END IF;

    -- ══════════════════════════════════════════════════
    -- 4. cancelled → إشعار لمُنشئ المناقلة
    -- ══════════════════════════════════════════════════
    IF NEW.status = 'cancelled' AND v_creator IS NOT NULL THEN
        INSERT INTO notifications (tenant_id, user_id, title, body, type, source_type, source_id, metadata)
        VALUES (
            NEW.tenant_id, v_creator,
            '❌ مناقلة ملغاة — ' || v_transfer_number,
            'تم إلغاء المناقلة من ' || v_from_wh_name || ' إلى ' || v_to_wh_name,
            'error', 'stock_transfer', NEW.id,
            jsonb_build_object(
                'transfer_number', v_transfer_number,
                'from_warehouse', v_from_wh_name,
                'to_warehouse', v_to_wh_name,
                'status', 'cancelled',
                'action', 'cancelled'
            )
        );
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: fn_update_schedule_paid_amount(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_update_schedule_paid_amount() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE payment_schedule
    SET 
        paid_amount = (
            SELECT COALESCE(SUM(paid_amount), 0)
            FROM payment_schedule_items
            WHERE schedule_id = COALESCE(NEW.schedule_id, OLD.schedule_id)
        ),
        status = CASE
            WHEN (SELECT COALESCE(SUM(paid_amount), 0) FROM payment_schedule_items WHERE schedule_id = COALESCE(NEW.schedule_id, OLD.schedule_id)) >= total_amount THEN 'completed'
            WHEN (SELECT COUNT(*) FROM payment_schedule_items WHERE schedule_id = COALESCE(NEW.schedule_id, OLD.schedule_id) AND status = 'overdue') > 0 THEN 'overdue'
            ELSE 'active'
        END,
        updated_at = NOW()
    WHERE id = COALESCE(NEW.schedule_id, OLD.schedule_id);
    
    RETURN NEW;
END;
$$;


--
-- Name: fn_update_timestamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.fn_update_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$$;


--
-- Name: generate_customer_code(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_customer_code(p_tenant_id uuid) RETURNS character varying
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_count INT;
    v_code VARCHAR;
BEGIN
    -- عد العملاء الموجودين
    SELECT COUNT(*) INTO v_count 
    FROM customers 
    WHERE tenant_id = p_tenant_id;
    
    -- توليد الكود
    v_code := 'CUST-' || LPAD((v_count + 1)::TEXT, 5, '0');
    
    -- التأكد من عدم التكرار
    WHILE EXISTS (SELECT 1 FROM customers WHERE code = v_code AND tenant_id = p_tenant_id) LOOP
        v_code := 'CUST-' || LPAD(FLOOR(RANDOM() * 99999)::TEXT, 5, '0');
    END LOOP;
    
    RETURN v_code;
END;
$$;


--
-- Name: generate_delivery_note_number(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_delivery_note_number(p_tenant_id uuid, p_company_id uuid) RETURNS character varying
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_prefix VARCHAR(10) := 'DN';
    v_year VARCHAR(4) := TO_CHAR(CURRENT_DATE, 'YYYY');
    v_sequence INT;
    v_number VARCHAR(50);
BEGIN
    SELECT COALESCE(MAX(
        CAST(NULLIF(REGEXP_REPLACE(note_number, '[^0-9]', '', 'g'), '') AS INT)
    ), 0) + 1 INTO v_sequence
    FROM delivery_notes
    WHERE tenant_id = p_tenant_id
    AND EXTRACT(YEAR FROM note_date) = EXTRACT(YEAR FROM CURRENT_DATE);
    
    v_number := v_prefix || '-' || v_year || '-' || LPAD(v_sequence::TEXT, 6, '0');
    
    RETURN v_number;
END;
$$;


--
-- Name: generate_employee_number(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_employee_number(p_tenant_id uuid, p_company_id uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_prefix TEXT;
    v_counter INTEGER;
    v_number TEXT;
BEGIN
    SELECT employee_number_prefix, employee_number_counter
    INTO v_prefix, v_counter
    FROM hr_settings
    WHERE tenant_id = p_tenant_id 
    AND (company_id = p_company_id OR (company_id IS NULL AND p_company_id IS NULL))
    LIMIT 1;
    
    v_prefix := COALESCE(v_prefix, 'EMP');
    v_counter := COALESCE(v_counter, 1);
    
    v_number := v_prefix || '-' || LPAD(v_counter::TEXT, 4, '0');
    
    -- تحديث العداد
    UPDATE hr_settings SET employee_number_counter = v_counter + 1
    WHERE tenant_id = p_tenant_id 
    AND (company_id = p_company_id OR (company_id IS NULL AND p_company_id IS NULL));
    
    -- إذا لم يوجد سجل إعدادات، أنشئه
    IF NOT FOUND THEN
        INSERT INTO hr_settings (tenant_id, company_id, employee_number_counter)
        VALUES (p_tenant_id, p_company_id, 2);
    END IF;
    
    RETURN v_number;
END;
$$;


--
-- Name: generate_entry_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_entry_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_max_number INTEGER;
    v_year INTEGER;
    v_prefix VARCHAR(10);
BEGIN
    -- Skip if entry_number already provided
    IF NEW.entry_number IS NOT NULL THEN
        RETURN NEW;
    END IF;
    
    -- Get year from entry_date
    v_year := EXTRACT(YEAR FROM NEW.entry_date);
    
    -- Get max entry number for this company and year
    SELECT COALESCE(
        MAX(
            CASE 
                WHEN entry_number ~ '^\d+/\d{4}$' 
                THEN SPLIT_PART(entry_number, '/', 1)::INTEGER
                ELSE 0
            END
        ), 
        0
    ) INTO v_max_number
    FROM journal_entries
    WHERE company_id = NEW.company_id
      AND EXTRACT(YEAR FROM entry_date) = v_year;
    
    -- Generate new entry number
    NEW.entry_number := (v_max_number + 1)::TEXT || '/' || v_year::TEXT;
    
    RETURN NEW;
END;
$_$;


--
-- Name: generate_magic_link(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_magic_link(p_email text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_token TEXT;
    v_token_hash TEXT;
BEGIN
    -- Find the user
    SELECT id INTO v_user_id FROM auth.users WHERE email = p_email;
    IF v_user_id IS NULL THEN
        RETURN json_build_object('success', false, 'error', 'User not found');
    END IF;
    
    -- Generate a random token
    v_token := encode(gen_random_bytes(32), 'hex');
    v_token_hash := encode(digest(v_token, 'sha256'), 'hex');
    
    -- Update recovery token on the user
    UPDATE auth.users SET
        recovery_token = v_token_hash,
        recovery_sent_at = NOW()
    WHERE id = v_user_id;
    
    RETURN json_build_object(
        'success', true,
        'token', v_token,
        'token_hash', v_token_hash,
        'user_id', v_user_id,
        'type', 'recovery'
    );
END;
$$;


--
-- Name: generate_next_account_code(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_next_account_code(p_tenant_id uuid, p_company_id uuid, p_parent_code character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_max_code VARCHAR(50);
    v_next_number INT;
    v_parent_length INT;
    v_new_code VARCHAR(50);
BEGIN
    v_parent_length := LENGTH(p_parent_code);
    
    -- البحث عن آخر رقم حساب تحت هذا الأب
    SELECT MAX(account_code) INTO v_max_code
    FROM chart_of_accounts
    WHERE tenant_id = p_tenant_id
      AND company_id = p_company_id
      AND account_code LIKE p_parent_code || '%'
      AND LENGTH(account_code) = v_parent_length + 2;
    
    IF v_max_code IS NULL THEN
        -- أول حساب فرعي
        v_new_code := p_parent_code || '01';
    ELSE
        -- استخراج الرقم الأخير وزيادته
        v_next_number := CAST(RIGHT(v_max_code, 2) AS INT) + 1;
        IF v_next_number > 99 THEN
            RAISE EXCEPTION 'تم تجاوز الحد الأقصى للحسابات الفرعية تحت %', p_parent_code;
        END IF;
        v_new_code := p_parent_code || LPAD(v_next_number::TEXT, 2, '0');
    END IF;
    
    RETURN v_new_code;
END;
$$;


--
-- Name: FUNCTION generate_next_account_code(p_tenant_id uuid, p_company_id uuid, p_parent_code character varying); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_next_account_code(p_tenant_id uuid, p_company_id uuid, p_parent_code character varying) IS 'توليد رقم حساب جديد تلقائياً تحت حساب أب محدد';


--
-- Name: generate_order_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_order_number() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  new_num TEXT;
  seq_val INT;
BEGIN
  SELECT COALESCE(MAX(
    CAST(NULLIF(regexp_replace(order_number, '[^0-9]', '', 'g'), '') AS INT)
  ), 10000) + 1
  INTO seq_val
  FROM ecommerce_orders;
  
  new_num := 'TXO-' || seq_val;
  RETURN new_num;
END;
$$;


--
-- Name: generate_order_number(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_order_number(p_tenant_id uuid, p_company_id uuid DEFAULT NULL::uuid) RETURNS character varying
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_count INT;
    v_order_number VARCHAR;
    v_date_part VARCHAR;
BEGIN
    -- تنسيق التاريخ: YYYYMMDD
    v_date_part := TO_CHAR(NOW(), 'YYYYMMDD');
    
    -- عدد الطلبات اليوم
    SELECT COUNT(*) INTO v_count
    FROM orders
    WHERE tenant_id = p_tenant_id
      AND (p_company_id IS NULL OR company_id = p_company_id)
      AND DATE(created_at) = CURRENT_DATE;
    
    -- رقم الطلب: ORD-YYYYMMDD-XXXX
    v_order_number := 'ORD-' || v_date_part || '-' || LPAD((v_count + 1)::TEXT, 4, '0');
    
    RETURN v_order_number;
END;
$$;


--
-- Name: generate_payment_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_payment_number() RETURNS character varying
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_number VARCHAR;
    v_year VARCHAR;
    v_month VARCHAR;
BEGIN
    v_year := TO_CHAR(NOW(), 'YY');
    v_month := TO_CHAR(NOW(), 'MM');
    v_number := 'PAY-' || v_year || v_month || '-' || LPAD(nextval('saas_payment_number_seq')::TEXT, 5, '0');
    RETURN v_number;
END;
$$;


--
-- Name: generate_recurring_entries(uuid, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_recurring_entries(p_company_id uuid DEFAULT NULL::uuid, p_as_of_date date DEFAULT CURRENT_DATE, p_user_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_template RECORD;
    v_line RECORD;
    v_entry_id UUID;
    v_entry_number VARCHAR(50);
    v_execution_id UUID;
    v_entries_created INT := 0;
    v_fiscal_year_id UUID;
    v_line_number INT;
BEGIN
    -- معالجة كل قالب مستحق التنفيذ
    FOR v_template IN 
        SELECT * FROM recurring_entry_templates
        WHERE is_active = true
          AND (p_company_id IS NULL OR company_id = p_company_id)
          AND next_execution_date <= p_as_of_date
          AND (end_date IS NULL OR next_execution_date <= end_date)
          AND (max_executions IS NULL OR execution_count < max_executions)
        ORDER BY next_execution_date
    LOOP
        BEGIN
            -- الحصول على السنة المالية
            SELECT id INTO v_fiscal_year_id
            FROM fiscal_years
            WHERE company_id = v_template.company_id
              AND is_current = true
            LIMIT 1;
            
            -- توليد رقم القيد
            v_entry_number := 'JE-RC-' || v_template.template_code || '-' || TO_CHAR(v_template.next_execution_date, 'YYYYMMDD');
            
            -- إنشاء القيد اليومي
            INSERT INTO journal_entries (
                tenant_id, company_id,
                entry_number, entry_date,
                fiscal_year_id,
                entry_type,
                reference_type, reference_id, reference_number,
                description,
                currency,
                total_debit, total_credit,
                status, is_posted, posted_at,
                created_by, created_at
            )
            VALUES (
                v_template.tenant_id, v_template.company_id,
                v_entry_number, v_template.next_execution_date,
                v_fiscal_year_id,
                'recurring',
                'recurring_template', v_template.id, v_template.template_code,
                v_template.template_name || ' - ' || TO_CHAR(v_template.next_execution_date, 'YYYY-MM-DD'),
                v_template.currency,
                v_template.total_amount, v_template.total_amount,
                CASE WHEN v_template.auto_post THEN 'posted' ELSE 'draft' END,
                v_template.auto_post,
                CASE WHEN v_template.auto_post THEN NOW() ELSE NULL END,
                p_user_id, NOW()
            )
            RETURNING id INTO v_entry_id;
            
            -- إضافة بنود القيد
            v_line_number := 1;
            FOR v_line IN 
                SELECT * FROM recurring_entry_lines
                WHERE template_id = v_template.id
                ORDER BY line_number
            LOOP
                INSERT INTO journal_entry_lines (
                    tenant_id, entry_id, line_number,
                    account_id,
                    debit, credit,
                    description,
                    cost_center_id
                )
                VALUES (
                    v_template.tenant_id, v_entry_id, v_line_number,
                    v_line.account_id,
                    CASE 
                        WHEN v_line.is_percentage THEN v_template.total_amount * v_line.percentage / 100
                        ELSE v_line.debit 
                    END,
                    CASE 
                        WHEN v_line.is_percentage THEN v_template.total_amount * v_line.percentage / 100
                        ELSE v_line.credit 
                    END,
                    COALESCE(v_line.description, v_template.template_name),
                    v_line.cost_center_id
                );
                v_line_number := v_line_number + 1;
            END LOOP;
            
            -- تسجيل التنفيذ
            INSERT INTO recurring_entry_executions (
                tenant_id, template_id,
                journal_entry_id,
                execution_date, scheduled_date,
                status,
                executed_by, executed_at
            )
            VALUES (
                v_template.tenant_id, v_template.id,
                v_entry_id,
                p_as_of_date, v_template.next_execution_date,
                'success',
                p_user_id, NOW()
            );
            
            -- تحديث القالب
            UPDATE recurring_entry_templates
            SET last_execution_date = v_template.next_execution_date,
                next_execution_date = calculate_next_execution_date(
                    v_template.frequency,
                    v_template.next_execution_date,
                    v_template.day_of_week,
                    v_template.day_of_month,
                    v_template.month_of_year
                ),
                execution_count = execution_count + 1,
                updated_at = NOW()
            WHERE id = v_template.id;
            
            v_entries_created := v_entries_created + 1;
            
            RAISE NOTICE 'تم إنشاء قيد متكرر: % - التاريخ: %', v_template.template_name, v_template.next_execution_date;
            
        EXCEPTION WHEN OTHERS THEN
            -- تسجيل الخطأ
            INSERT INTO recurring_entry_executions (
                tenant_id, template_id,
                execution_date, scheduled_date,
                status, error_message,
                executed_at
            )
            VALUES (
                v_template.tenant_id, v_template.id,
                p_as_of_date, v_template.next_execution_date,
                'failed', SQLERRM,
                NOW()
            );
            
            RAISE NOTICE 'فشل إنشاء قيد متكرر: % - الخطأ: %', v_template.template_name, SQLERRM;
        END;
    END LOOP;
    
    RAISE NOTICE 'تم إنشاء % قيد متكرر', v_entries_created;
    
    RETURN v_entries_created;
END;
$$;


--
-- Name: FUNCTION generate_recurring_entries(p_company_id uuid, p_as_of_date date, p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_recurring_entries(p_company_id uuid, p_as_of_date date, p_user_id uuid) IS 'توليد القيود المتكررة المستحقة حتى تاريخ معين';


--
-- Name: generate_sample_request_number(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_sample_request_number(p_tenant_id uuid, p_prefix character varying DEFAULT 'SR'::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INT;
    v_number VARCHAR(50);
BEGIN
    SELECT COUNT(*) + 1 INTO v_count
    FROM sample_requests
    WHERE tenant_id = p_tenant_id
    AND EXTRACT(YEAR FROM created_at) = EXTRACT(YEAR FROM CURRENT_DATE);
    
    v_number := p_prefix || '-' || TO_CHAR(CURRENT_DATE, 'YYYY') || '-' || LPAD(v_count::TEXT, 5, '0');
    
    RETURN v_number;
END;
$$;


--
-- Name: generate_sequence_number(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_sequence_number(p_tenant_id uuid, p_company_id uuid, p_sequence_type character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_sequence RECORD;
    v_new_value BIGINT;
    v_result VARCHAR(50);
BEGIN
    SELECT * INTO v_sequence
    FROM sequences
    WHERE tenant_id = p_tenant_id 
      AND (company_id = p_company_id OR company_id IS NULL)
      AND sequence_type = p_sequence_type
    ORDER BY company_id NULLS LAST
    LIMIT 1;
    
    IF NOT FOUND THEN
        INSERT INTO sequences (tenant_id, company_id, sequence_type, current_value)
        VALUES (p_tenant_id, p_company_id, p_sequence_type, 1)
        RETURNING current_value INTO v_new_value;
    ELSE
        UPDATE sequences
        SET current_value = current_value + 1
        WHERE id = v_sequence.id
        RETURNING current_value INTO v_new_value;
        
        v_sequence.prefix := COALESCE(v_sequence.prefix, '');
        v_sequence.suffix := COALESCE(v_sequence.suffix, '');
        v_sequence.padding := COALESCE(v_sequence.padding, 5);
    END IF;
    
    v_result := COALESCE(v_sequence.prefix, '') || 
                LPAD(v_new_value::TEXT, COALESCE(v_sequence.padding, 5), '0') || 
                COALESCE(v_sequence.suffix, '');
    
    RETURN v_result;
END;
$$;


--
-- Name: generate_stage_number(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_stage_number(p_tenant_id uuid, p_company_id uuid, p_doc_type text, p_stage text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_prefix TEXT;
    v_year INTEGER := EXTRACT(YEAR FROM CURRENT_DATE);
    v_next INTEGER;
BEGIN
    v_prefix := CASE
        WHEN p_doc_type = 'purchase' AND p_stage = 'quotation' THEN 'PQ'
        WHEN p_doc_type = 'purchase' AND p_stage = 'order' THEN 'PO'
        WHEN p_doc_type = 'purchase' AND p_stage = 'receipt' THEN 'PR'
        WHEN p_doc_type = 'purchase' AND p_stage = 'invoice' THEN 'PI'
        WHEN p_doc_type = 'sale' AND p_stage = 'quotation' THEN 'SQ'
        WHEN p_doc_type = 'sale' AND p_stage = 'reservation' THEN 'SR'
        WHEN p_doc_type = 'sale' AND p_stage = 'order' THEN 'SO'
        WHEN p_doc_type = 'sale' AND p_stage = 'delivery' THEN 'SD'
        WHEN p_doc_type = 'sale' AND p_stage = 'invoice' THEN 'SI'
        ELSE 'DOC'
    END;

    INSERT INTO document_sequences (tenant_id, company_id, doc_type, stage, year, prefix, next_number)
    VALUES (p_tenant_id, p_company_id, p_doc_type, p_stage, v_year, v_prefix, 1)
    ON CONFLICT (tenant_id, company_id, doc_type, stage, year) DO NOTHING;

    UPDATE document_sequences
    SET next_number = next_number + 1, updated_at = NOW()
    WHERE tenant_id = p_tenant_id
      AND company_id = p_company_id
      AND doc_type = p_doc_type
      AND stage = p_stage
      AND year = v_year
    RETURNING prefix, next_number - 1 INTO v_prefix, v_next;

    RETURN v_prefix || '-' || v_year || '-' || LPAD(v_next::TEXT, 4, '0');
END;
$$;


--
-- Name: generate_stock_count_number(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.generate_stock_count_number(p_tenant_id uuid, p_prefix character varying DEFAULT 'SC'::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INT;
    v_number VARCHAR(50);
BEGIN
    SELECT COUNT(*) + 1 INTO v_count
    FROM stock_counts
    WHERE tenant_id = p_tenant_id
    AND EXTRACT(YEAR FROM created_at) = EXTRACT(YEAR FROM CURRENT_DATE);
    
    v_number := p_prefix || '-' || TO_CHAR(CURRENT_DATE, 'YYYY') || '-' || LPAD(v_count::TEXT, 5, '0');
    
    RETURN v_number;
END;
$$;


--
-- Name: get_account_balance(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_account_balance(p_account_id uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_balance DECIMAL(15, 2);
BEGIN
    SELECT COALESCE(SUM(jel.debit - jel.credit), 0) INTO v_balance
    FROM journal_entry_lines jel
    INNER JOIN journal_entries je ON jel.journal_entry_id = je.id
    WHERE jel.account_id = p_account_id
      AND je.entry_date <= p_as_of_date;
    
    RETURN v_balance;
END;
$$;


--
-- Name: get_account_balance_fc(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_account_balance_fc(p_account_id uuid, p_company_id uuid) RETURNS TABLE(total_debit numeric, total_credit numeric, balance numeric, currency text, transaction_count bigint, last_activity date)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
WITH 
-- Account's DB currency
account_info AS (
    SELECT 
        coa.id,
        COALESCE(coa.currency, c.default_currency, 'USD') AS account_currency
    FROM chart_of_accounts coa
    LEFT JOIN companies c ON c.id = coa.company_id
    WHERE coa.id = p_account_id
      AND coa.company_id = p_company_id
),
-- Detect if this account has entries in multiple currencies
currency_check AS (
    SELECT 
        COUNT(DISTINCT jel.currency) AS num_currencies
    FROM journal_entry_lines jel
    INNER JOIN journal_entries je
        ON je.id = jel.entry_id
       AND je.company_id = p_company_id
       AND je.is_posted = true
       AND je.status = 'posted'
    WHERE jel.account_id = p_account_id
      AND jel.currency IS NOT NULL
      AND jel.currency != ''
),
-- For mixed accounts: find the base currency (rate=1 when others have rate>1)
mixed_base AS (
    SELECT jel.currency AS base_currency
    FROM journal_entry_lines jel
    INNER JOIN journal_entries je
        ON je.id = jel.entry_id
       AND je.company_id = p_company_id
       AND je.is_posted = true
       AND je.status = 'posted'
    WHERE jel.account_id = p_account_id
      AND jel.currency IS NOT NULL
      AND jel.currency != ''
      AND COALESCE(jel.exchange_rate, 1) = 1
    GROUP BY jel.currency
    ORDER BY COUNT(*) DESC
    LIMIT 1
),
-- Calculate line-level amounts
posted_lines AS (
    SELECT 
        CASE
            WHEN jel.debit_fc IS NOT NULL AND jel.debit_fc > 0 THEN jel.debit_fc
            WHEN COALESCE(jel.exchange_rate, 1) > 1 THEN jel.debit / jel.exchange_rate
            ELSE jel.debit
        END AS fc_debit,
        CASE
            WHEN jel.credit_fc IS NOT NULL AND jel.credit_fc > 0 THEN jel.credit_fc
            WHEN COALESCE(jel.exchange_rate, 1) > 1 THEN jel.credit / jel.exchange_rate
            ELSE jel.credit
        END AS fc_credit,
        jel.debit AS base_debit,
        jel.credit AS base_credit,
        je.entry_date
    FROM journal_entry_lines jel
    INNER JOIN journal_entries je
        ON je.id = jel.entry_id
       AND je.company_id = p_company_id
       AND je.is_posted = true
       AND je.status = 'posted'
    WHERE jel.account_id = p_account_id
)
SELECT
    COALESCE(SUM(pl.fc_debit), 0)::NUMERIC AS total_debit,
    COALESCE(SUM(pl.fc_credit), 0)::NUMERIC AS total_credit,
    -- Mixed currencies: use balance_base (consistent)
    -- Single currency: use FC balance (native)
    CASE
        WHEN (SELECT num_currencies FROM currency_check) > 1 THEN
            (COALESCE(SUM(pl.base_debit), 0) - COALESCE(SUM(pl.base_credit), 0))::NUMERIC
        ELSE
            (COALESCE(SUM(pl.fc_debit), 0) - COALESCE(SUM(pl.fc_credit), 0))::NUMERIC
    END AS balance,
    -- Mixed currencies: use detected base currency
    -- Single currency: use account's DB currency
    CASE
        WHEN (SELECT num_currencies FROM currency_check) > 1 THEN
            COALESCE(
                (SELECT base_currency FROM mixed_base),
                (SELECT default_currency FROM companies WHERE id = p_company_id),
                'USD'
            )
        ELSE ai.account_currency
    END::TEXT AS currency,
    COUNT(*)::BIGINT AS transaction_count,
    MAX(pl.entry_date)::DATE AS last_activity
FROM account_info ai
LEFT JOIN posted_lines pl ON true
GROUP BY ai.account_currency;
$$;


--
-- Name: get_account_balances_bulk(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_account_balances_bulk(p_company_id uuid) RETURNS TABLE(account_id uuid, balance double precision, balance_fc double precision)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        jel.account_id,
        -- Base currency balance (debit - credit)
        ROUND(COALESCE(SUM(jel.debit - jel.credit), 0)::numeric, 2)::double precision AS balance,
        -- FC balance with Smart Recovery:
        -- If debit_fc > 0 or debit = 0 → use debit_fc
        -- Else if exchange_rate > 1 → use debit / exchange_rate
        -- Else → use debit as-is (same currency)
        ROUND(COALESCE(SUM(
            CASE
                WHEN COALESCE(jel.debit_fc, 0) > 0 OR COALESCE(jel.debit, 0) = 0
                    THEN COALESCE(jel.debit_fc, 0)
                WHEN COALESCE(jel.exchange_rate, 1) > 1
                    THEN jel.debit / jel.exchange_rate
                ELSE jel.debit
            END
            -
            CASE
                WHEN COALESCE(jel.credit_fc, 0) > 0 OR COALESCE(jel.credit, 0) = 0
                    THEN COALESCE(jel.credit_fc, 0)
                WHEN COALESCE(jel.exchange_rate, 1) > 1
                    THEN jel.credit / jel.exchange_rate
                ELSE jel.credit
            END
        ), 0)::numeric, 2)::double precision AS balance_fc
    FROM journal_entry_lines jel
    INNER JOIN journal_entries je ON jel.entry_id = je.id
    WHERE je.company_id = p_company_id
      AND je.is_posted = true
    GROUP BY jel.account_id;
END;
$$;


--
-- Name: get_account_balances_for_parent(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_account_balances_for_parent(p_company_id uuid, p_parent_id uuid) RETURNS TABLE(account_id uuid, total_debit numeric, total_credit numeric, balance numeric, balance_base numeric, currency text, transaction_count bigint, last_activity date)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
WITH target_accounts AS (
    SELECT coa.id, COALESCE(coa.currency, c.default_currency, 'USD') AS account_currency
    FROM chart_of_accounts coa
    LEFT JOIN companies c ON c.id = coa.company_id
    WHERE coa.company_id = p_company_id
      AND coa.parent_id = p_parent_id
      AND coa.is_group = false
),
posted_lines AS (
    SELECT
        jel.account_id,
        CASE
            WHEN jel.debit_fc IS NOT NULL AND (jel.debit_fc > 0 OR jel.debit = 0) THEN jel.debit_fc
            WHEN COALESCE(jel.exchange_rate, 1) > 1 THEN jel.debit / jel.exchange_rate
            ELSE jel.debit
        END AS fc_debit,
        CASE
            WHEN jel.credit_fc IS NOT NULL AND (jel.credit_fc > 0 OR jel.credit = 0) THEN jel.credit_fc
            WHEN COALESCE(jel.exchange_rate, 1) > 1 THEN jel.credit / jel.exchange_rate
            ELSE jel.credit
        END AS fc_credit,
        jel.debit AS base_debit,
        jel.credit AS base_credit,
        je.entry_date
    FROM journal_entry_lines jel
    INNER JOIN journal_entries je
        ON je.id = jel.entry_id
       AND je.company_id = p_company_id
       AND je.is_posted = true
       AND je.status = 'posted'
    WHERE jel.account_id IN (SELECT id FROM target_accounts)
)
SELECT
    ta.id::UUID AS account_id,
    COALESCE(SUM(pl.fc_debit), 0)::NUMERIC AS total_debit,
    COALESCE(SUM(pl.fc_credit), 0)::NUMERIC AS total_credit,
    (COALESCE(SUM(pl.fc_debit), 0) - COALESCE(SUM(pl.fc_credit), 0))::NUMERIC AS balance,
    (COALESCE(SUM(pl.base_debit), 0) - COALESCE(SUM(pl.base_credit), 0))::NUMERIC AS balance_base,
    ta.account_currency::TEXT AS currency,
    COUNT(pl.fc_debit)::BIGINT AS transaction_count,
    MAX(pl.entry_date)::DATE AS last_activity
FROM target_accounts ta
LEFT JOIN posted_lines pl ON pl.account_id = ta.id
GROUP BY ta.id, ta.account_currency;
$$;


--
-- Name: get_account_by_code(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_account_by_code(p_company_id uuid, p_account_code character varying) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_account_id UUID;
BEGIN
    SELECT id INTO v_account_id
    FROM chart_of_accounts
    WHERE company_id = p_company_id
      AND account_code = p_account_code
      AND is_active = true;
    
    RETURN v_account_id;
END;
$$;


--
-- Name: get_account_id(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_account_id(p_tenant_id uuid, p_company_id uuid, p_account_code character varying) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
