--
-- Name: get_account_ledger_fc(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_account_ledger_fc(p_account_id uuid, p_company_id uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS TABLE(line_id uuid, entry_id uuid, entry_number text, entry_date date, description text, debit numeric, credit numeric, running_balance numeric, currency text, original_currency text, exchange_rate numeric, entry_type text, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_running_balance NUMERIC := 0;
    v_record RECORD;
BEGIN
    FOR v_record IN
        SELECT
            jel.id AS line_id,
            je.id AS entry_id,
            je.entry_number,
            je.entry_date,
            COALESCE(jel.description, je.description, '') AS description,
            CASE
                WHEN jel.debit_fc IS NOT NULL AND (jel.debit_fc > 0 OR jel.debit = 0) THEN jel.debit_fc
                WHEN COALESCE(jel.exchange_rate, 1) > 1 THEN jel.debit / jel.exchange_rate
                ELSE jel.debit
            END AS fc_debit,
            CASE
                WHEN jel.credit_fc IS NOT NULL AND (jel.credit_fc > 0 OR jel.credit = 0) THEN jel.credit_fc
                WHEN COALESCE(jel.exchange_rate, 1) > 1 THEN jel.credit / jel.exchange_rate
                ELSE jel.credit
            END AS fc_credit,
            jel.currency AS original_currency,
            COALESCE(jel.exchange_rate, 1) AS exchange_rate,
            je.entry_type,
            je.status
        FROM journal_entry_lines jel
        INNER JOIN journal_entries je
            ON je.id = jel.entry_id
           AND je.company_id = p_company_id
           AND je.is_posted = true
           AND je.status = 'posted'
        WHERE jel.account_id = p_account_id
          AND (p_from_date IS NULL OR je.entry_date >= p_from_date)
          AND (p_to_date IS NULL OR je.entry_date <= p_to_date)
        ORDER BY je.entry_date ASC, je.entry_number ASC, jel.line_number ASC
    LOOP
        v_running_balance := v_running_balance + v_record.fc_debit - v_record.fc_credit;
        
        line_id := v_record.line_id;
        entry_id := v_record.entry_id;
        entry_number := v_record.entry_number;
        entry_date := v_record.entry_date;
        description := v_record.description;
        debit := ROUND(v_record.fc_debit, 2);
        credit := ROUND(v_record.fc_credit, 2);
        running_balance := ROUND(v_running_balance, 2);
        currency := v_record.original_currency;
        original_currency := v_record.original_currency;
        exchange_rate := v_record.exchange_rate;
        entry_type := v_record.entry_type;
        status := v_record.status;
        
        RETURN NEXT;
    END LOOP;
END;
$$;


--
-- Name: get_account_statement(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_account_statement(p_account_id uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS TABLE(entry_date date, entry_number character varying, reference_type character varying, reference_number character varying, description text, debit numeric, credit numeric, balance numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_from_date DATE;
    v_to_date DATE;
    v_opening_balance DECIMAL(15,2);
    v_normal_balance VARCHAR(10);
BEGIN
    -- تحديد التواريخ
    v_from_date := COALESCE(p_from_date, DATE_TRUNC('year', CURRENT_DATE)::DATE);
    v_to_date := COALESCE(p_to_date, CURRENT_DATE);
    
    -- الحصول على الطبيعة الطبيعية للحساب
    SELECT at.normal_balance INTO v_normal_balance
    FROM chart_of_accounts coa
    JOIN account_types at ON coa.account_type_id = at.id
    WHERE coa.id = p_account_id;
    
    -- حساب الرصيد الافتتاحي
    SELECT 
        COALESCE(coa.opening_balance, 0) +
        CASE 
            WHEN v_normal_balance = 'debit' THEN 
                COALESCE(SUM(jel.debit - jel.credit), 0)
            ELSE 
                COALESCE(SUM(jel.credit - jel.debit), 0)
        END
    INTO v_opening_balance
    FROM chart_of_accounts coa
    LEFT JOIN journal_entry_lines jel ON coa.id = jel.account_id
    LEFT JOIN journal_entries je ON jel.entry_id = je.id 
        AND je.is_posted = true
        AND je.entry_date < v_from_date
    WHERE coa.id = p_account_id
    GROUP BY coa.id, coa.opening_balance;
    
    v_opening_balance := COALESCE(v_opening_balance, 0);
    
    RETURN QUERY
    WITH movements AS (
        SELECT 
            je.entry_date,
            je.entry_number,
            je.reference_type,
            je.reference_number,
            COALESCE(jel.description, je.description) as description,
            jel.debit,
            jel.credit,
            ROW_NUMBER() OVER (ORDER BY je.entry_date, je.created_at) as rn
        FROM journal_entry_lines jel
        JOIN journal_entries je ON jel.entry_id = je.id
        WHERE jel.account_id = p_account_id
          AND je.is_posted = true
          AND je.entry_date BETWEEN v_from_date AND v_to_date
    )
    -- الرصيد الافتتاحي
    SELECT 
        v_from_date as entry_date,
        'OPENING'::VARCHAR(50) as entry_number,
        'opening_balance'::VARCHAR(50) as reference_type,
        ''::VARCHAR(100) as reference_number,
        'رصيد افتتاحي'::TEXT as description,
        CASE WHEN v_opening_balance > 0 AND v_normal_balance = 'debit' THEN v_opening_balance ELSE 0::DECIMAL(15,2) END as debit,
        CASE WHEN v_opening_balance > 0 AND v_normal_balance = 'credit' THEN v_opening_balance ELSE 0::DECIMAL(15,2) END as credit,
        v_opening_balance as balance
    
    UNION ALL
    
    -- الحركات
    SELECT 
        m.entry_date,
        m.entry_number,
        m.reference_type,
        m.reference_number,
        m.description,
        m.debit,
        m.credit,
        v_opening_balance + SUM(
            CASE WHEN v_normal_balance = 'debit' THEN m.debit - m.credit ELSE m.credit - m.debit END
        ) OVER (ORDER BY m.rn) as balance
    FROM movements m
    
    ORDER BY entry_date, entry_number;
END;
$$;


--
-- Name: FUNCTION get_account_statement(p_account_id uuid, p_from_date date, p_to_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_account_statement(p_account_id uuid, p_from_date date, p_to_date date) IS 'كشف حساب تفصيلي مع الرصيد الجاري';


--
-- Name: get_account_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_account_summary(p_account_id uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS TABLE(account_code character varying, account_name_ar character varying, opening_balance numeric, total_debit numeric, total_credit numeric, closing_balance numeric, transactions_count integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_from_date DATE;
    v_to_date DATE;
BEGIN
    v_from_date := COALESCE(p_from_date, DATE_TRUNC('year', CURRENT_DATE)::DATE);
    v_to_date := COALESCE(p_to_date, CURRENT_DATE);
    
    RETURN QUERY
    SELECT 
        coa.account_code,
        coa.name_ar as account_name_ar,
        COALESCE(coa.opening_balance, 0) + COALESCE(SUM(
            CASE WHEN je.entry_date < v_from_date THEN 
                CASE WHEN at.normal_balance = 'debit' THEN jel.debit - jel.credit ELSE jel.credit - jel.debit END
            ELSE 0 END
        ), 0) as opening_balance,
        COALESCE(SUM(CASE WHEN je.entry_date BETWEEN v_from_date AND v_to_date THEN jel.debit ELSE 0 END), 0) as total_debit,
        COALESCE(SUM(CASE WHEN je.entry_date BETWEEN v_from_date AND v_to_date THEN jel.credit ELSE 0 END), 0) as total_credit,
        COALESCE(coa.opening_balance, 0) + COALESCE(SUM(
            CASE WHEN at.normal_balance = 'debit' THEN jel.debit - jel.credit ELSE jel.credit - jel.debit END
        ), 0) as closing_balance,
        COUNT(DISTINCT CASE WHEN je.entry_date BETWEEN v_from_date AND v_to_date THEN je.id END)::INT as transactions_count
    FROM chart_of_accounts coa
    JOIN account_types at ON coa.account_type_id = at.id
    LEFT JOIN journal_entry_lines jel ON coa.id = jel.account_id
    LEFT JOIN journal_entries je ON jel.entry_id = je.id 
        AND je.is_posted = true
        AND je.entry_date <= v_to_date
    WHERE coa.id = p_account_id
    GROUP BY coa.id, coa.account_code, coa.name_ar, coa.opening_balance, at.normal_balance;
END;
$$;


--
-- Name: FUNCTION get_account_summary(p_account_id uuid, p_from_date date, p_to_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_account_summary(p_account_id uuid, p_from_date date, p_to_date date) IS 'ملخص حساب - الرصيد الافتتاحي والحركات والرصيد الختامي';


--
-- Name: get_account_type_id(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_account_type_id(p_account_type character varying) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_type_id UUID;
    v_classification VARCHAR(50);
    v_normal_balance VARCHAR(10);
BEGIN
    -- تحديد classification و normal_balance حسب account_type
    CASE p_account_type
        WHEN 'asset' THEN
            v_classification := 'assets';
            v_normal_balance := 'debit';
        WHEN 'liability' THEN
            v_classification := 'liabilities';
            v_normal_balance := 'credit';
        WHEN 'equity' THEN
            v_classification := 'equity';
            v_normal_balance := 'credit';
        WHEN 'revenue' THEN
            v_classification := 'income';
            v_normal_balance := 'credit';
        WHEN 'expense' THEN
            v_classification := 'expenses';
            v_normal_balance := 'debit';
        ELSE
            v_classification := 'assets';
            v_normal_balance := 'debit';
    END CASE;
    
    -- البحث عن account_type_id المناسب
    SELECT id INTO v_type_id
    FROM account_types
    WHERE classification = v_classification
      AND normal_balance = v_normal_balance
    ORDER BY display_order
    LIMIT 1;
    
    -- إذا لم يوجد، استخدم ASSET كافتراضي
    IF v_type_id IS NULL THEN
        SELECT id INTO v_type_id FROM account_types WHERE code = 'ASSET';
    END IF;
    
    RETURN v_type_id;
END;
$$;


--
-- Name: get_accounting_dashboard(uuid, text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_accounting_dashboard(p_company_id uuid, p_base_currency text, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_from date := COALESCE(p_from_date, date_trunc('month', CURRENT_DATE)::date);
  v_to date := COALESCE(p_to_date, CURRENT_DATE);
  v_result jsonb;
  v_trial_balance jsonb;
  v_top_accounts jsonb;
  v_alerts jsonb;
  v_kpis jsonb;
  v_monthly jsonb;
  v_total_debit numeric := 0;
  v_total_credit numeric := 0;
  v_journal_count int := 0;
  v_draft_count int := 0;
  v_posted_count int := 0;
BEGIN
  -- 1. KPIs
  WITH account_balances AS (
    SELECT
      at.classification,
      at.code as type_code,
      SUM(CASE WHEN at.normal_balance = 'debit' THEN jel.debit - jel.credit ELSE jel.credit - jel.debit END) as balance
    FROM journal_entry_lines jel
    JOIN journal_entries je ON je.id = jel.entry_id
    JOIN chart_of_accounts a ON a.id = jel.account_id
    JOIN account_types at ON at.id = a.account_type_id
    WHERE je.company_id = p_company_id
      AND je.is_posted = true
      AND je.entry_date >= v_from AND je.entry_date <= v_to
    GROUP BY at.classification, at.code
  )
  SELECT jsonb_build_object(
    'revenue', COALESCE((SELECT SUM(balance) FROM account_balances WHERE classification = 'income'), 0),
    'expenses', COALESCE((SELECT SUM(balance) FROM account_balances WHERE classification = 'expenses'), 0),
    'cashBalance', COALESCE((
      SELECT SUM(jel.debit - jel.credit)
      FROM journal_entry_lines jel
      JOIN journal_entries je ON je.id = jel.entry_id
      JOIN chart_of_accounts a ON a.id = jel.account_id
      WHERE je.company_id = p_company_id AND je.is_posted = true
        AND (a.account_code LIKE '111%' OR a.account_code LIKE '112%')
    ), 0),
    'receivables', COALESCE((
      SELECT SUM(jel.debit - jel.credit)
      FROM journal_entry_lines jel
      JOIN journal_entries je ON je.id = jel.entry_id
      JOIN chart_of_accounts a ON a.id = jel.account_id
      WHERE je.company_id = p_company_id AND je.is_posted = true
        AND a.account_code LIKE '113%'
    ), 0),
    'payables', COALESCE((
      SELECT SUM(jel.credit - jel.debit)
      FROM journal_entry_lines jel
      JOIN journal_entries je ON je.id = jel.entry_id
      JOIN chart_of_accounts a ON a.id = jel.account_id
      WHERE je.company_id = p_company_id AND je.is_posted = true
        AND a.account_code LIKE '2%'
    ), 0)
  ) INTO v_kpis;

  -- 2. Journal Stats
  SELECT COUNT(*), 
    COUNT(*) FILTER (WHERE status = 'draft'),
    COUNT(*) FILTER (WHERE status = 'posted')
  INTO v_journal_count, v_draft_count, v_posted_count
  FROM journal_entries
  WHERE company_id = p_company_id
    AND entry_date >= v_from AND entry_date <= v_to;

  -- 3. Trial Balance
  SELECT SUM(jel.debit), SUM(jel.credit)
  INTO v_total_debit, v_total_credit
  FROM journal_entry_lines jel
  JOIN journal_entries je ON je.id = jel.entry_id
  WHERE je.company_id = p_company_id AND je.is_posted = true;

  v_trial_balance := jsonb_build_object(
    'totalDebit', COALESCE(v_total_debit, 0),
    'totalCredit', COALESCE(v_total_credit, 0),
    'difference', COALESCE(v_total_debit - v_total_credit, 0),
    'isBalanced', COALESCE(v_total_debit = v_total_credit, true)
  );

  -- 4. Top 8 Accounts
  SELECT COALESCE(jsonb_agg(row_to_json(sub)::jsonb ORDER BY sub.activity DESC), '[]'::jsonb)
  INTO v_top_accounts
  FROM (
    SELECT
      a.account_code as "accountCode",
      a.name_ar as "accountName",
      at.name_ar as "typeName",
      at.classification,
      SUM(jel.debit + jel.credit) as activity,
      SUM(CASE WHEN at.normal_balance = 'debit' THEN jel.debit - jel.credit ELSE jel.credit - jel.debit END) as balance
    FROM journal_entry_lines jel
    JOIN journal_entries je ON je.id = jel.entry_id
    JOIN chart_of_accounts a ON a.id = jel.account_id AND a.is_detail = true
    JOIN account_types at ON at.id = a.account_type_id
    WHERE je.company_id = p_company_id AND je.is_posted = true
      AND je.entry_date >= v_from AND je.entry_date <= v_to
    GROUP BY a.account_code, a.name_ar, at.name_ar, at.classification
    ORDER BY activity DESC
    LIMIT 8
  ) sub;

  -- 5. Alerts
  SELECT jsonb_build_object(
    'draftEntries', v_draft_count,
    'isBalanced', COALESCE(v_total_debit = v_total_credit, true),
    'accountsCount', (SELECT COUNT(*) FROM chart_of_accounts WHERE company_id = p_company_id AND is_detail = true),
    'recurringPending', 0
  ) INTO v_alerts;

  -- 6. Monthly Revenue vs Expenses
  WITH months AS (
    SELECT generate_series(
      date_trunc('month', CURRENT_DATE - INTERVAL '5 months')::date,
      date_trunc('month', CURRENT_DATE)::date,
      '1 month'::interval
    )::date as month_start
  ),
  monthly_data AS (
    SELECT
      date_trunc('month', je.entry_date)::date as month_start,
      SUM(CASE WHEN at.classification = 'income' THEN jel.credit - jel.debit ELSE 0 END) as revenue,
      SUM(CASE WHEN at.classification = 'expenses' THEN jel.debit - jel.credit ELSE 0 END) as expenses
    FROM journal_entry_lines jel
    JOIN journal_entries je ON je.id = jel.entry_id
    JOIN chart_of_accounts a ON a.id = jel.account_id
    JOIN account_types at ON at.id = a.account_type_id
    WHERE je.company_id = p_company_id AND je.is_posted = true
      AND je.entry_date >= (CURRENT_DATE - INTERVAL '6 months')
      AND at.classification IN ('income', 'expenses')
    GROUP BY 1
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'month', to_char(m.month_start, 'YYYY-MM'),
      'label', to_char(m.month_start, 'Mon'),
      'revenue', ABS(COALESCE(md.revenue, 0)),
      'expenses', ABS(COALESCE(md.expenses, 0))
    ) ORDER BY m.month_start
  ), '[]'::jsonb)
  INTO v_monthly
  FROM months m
  LEFT JOIN monthly_data md ON md.month_start = m.month_start;

  -- Build result
  v_result := jsonb_build_object(
    'kpis', v_kpis,
    'journalStats', jsonb_build_object('total', v_journal_count, 'draft', v_draft_count, 'posted', v_posted_count),
    'trialBalance', v_trial_balance,
    'topAccounts', v_top_accounts,
    'alerts', v_alerts,
    'monthly', v_monthly
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_admin_statistics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_admin_statistics() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_stats JSONB;
BEGIN
    SELECT jsonb_build_object(
        'total_tenants', (SELECT COUNT(*) FROM tenants),
        'active_tenants', (SELECT COUNT(*) FROM tenants WHERE status = 'active'),
        'total_companies', (SELECT COUNT(*) FROM companies),
        'total_users', (SELECT COUNT(*) FROM user_profiles)
    ) INTO v_stats;
    
    RETURN v_stats;
END;
$$;


--
-- Name: get_aging_report(uuid, character varying, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_aging_report(p_company_id uuid, p_party_type character varying DEFAULT 'customer'::character varying, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS TABLE(party_id uuid, party_code character varying, party_name character varying, current_balance numeric, days_31_60 numeric, days_61_90 numeric, days_91_120 numeric, over_120_days numeric, total_balance numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_party_type = 'customer' THEN
        RETURN QUERY
        SELECT 
            c.id as party_id,
            c.code as party_code,
            c.name_ar as party_name,
            COALESCE(SUM(CASE WHEN p_as_of_date - si.invoice_date <= 30 THEN si.balance_due ELSE 0 END), 0) as current_balance,
            COALESCE(SUM(CASE WHEN p_as_of_date - si.invoice_date BETWEEN 31 AND 60 THEN si.balance_due ELSE 0 END), 0) as days_31_60,
            COALESCE(SUM(CASE WHEN p_as_of_date - si.invoice_date BETWEEN 61 AND 90 THEN si.balance_due ELSE 0 END), 0) as days_61_90,
            COALESCE(SUM(CASE WHEN p_as_of_date - si.invoice_date BETWEEN 91 AND 120 THEN si.balance_due ELSE 0 END), 0) as days_91_120,
            COALESCE(SUM(CASE WHEN p_as_of_date - si.invoice_date > 120 THEN si.balance_due ELSE 0 END), 0) as over_120_days,
            COALESCE(SUM(si.balance_due), 0) as total_balance
        FROM customers c
        LEFT JOIN sales_invoices si ON c.id = si.customer_id 
            AND si.company_id = p_company_id
            AND si.status = 'posted'
            AND si.balance_due > 0
            AND si.invoice_date <= p_as_of_date
        WHERE c.company_id = p_company_id
          AND c.status = 'active'
        GROUP BY c.id, c.code, c.name_ar
        HAVING COALESCE(SUM(si.balance_due), 0) > 0
        ORDER BY total_balance DESC;
    ELSE
        RETURN QUERY
        SELECT 
            s.id as party_id,
            s.code as party_code,
            s.name_ar as party_name,
            COALESCE(SUM(CASE WHEN p_as_of_date - pi.invoice_date <= 30 THEN pi.balance_due ELSE 0 END), 0) as current_balance,
            COALESCE(SUM(CASE WHEN p_as_of_date - pi.invoice_date BETWEEN 31 AND 60 THEN pi.balance_due ELSE 0 END), 0) as days_31_60,
            COALESCE(SUM(CASE WHEN p_as_of_date - pi.invoice_date BETWEEN 61 AND 90 THEN pi.balance_due ELSE 0 END), 0) as days_61_90,
            COALESCE(SUM(CASE WHEN p_as_of_date - pi.invoice_date BETWEEN 91 AND 120 THEN pi.balance_due ELSE 0 END), 0) as days_91_120,
            COALESCE(SUM(CASE WHEN p_as_of_date - pi.invoice_date > 120 THEN pi.balance_due ELSE 0 END), 0) as over_120_days,
            COALESCE(SUM(pi.balance_due), 0) as total_balance
        FROM suppliers s
        LEFT JOIN purchase_invoices pi ON s.id = pi.supplier_id 
            AND pi.company_id = p_company_id
            AND pi.status = 'posted'
            AND pi.balance_due > 0
            AND pi.invoice_date <= p_as_of_date
        WHERE s.company_id = p_company_id
          AND s.status = 'active'
        GROUP BY s.id, s.code, s.name_ar
        HAVING COALESCE(SUM(pi.balance_due), 0) > 0
        ORDER BY total_balance DESC;
    END IF;
END;
$$;


--
-- Name: FUNCTION get_aging_report(p_company_id uuid, p_party_type character varying, p_as_of_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_aging_report(p_company_id uuid, p_party_type character varying, p_as_of_date date) IS 'تقرير أعمار الديون - تصنيف المستحقات حسب العمر (0-30، 31-60، 61-90، 91-120، +120 يوم)';


--
-- Name: get_all_account_balances_fc(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_all_account_balances_fc(p_company_id uuid) RETURNS TABLE(account_id uuid, total_debit numeric, total_credit numeric, balance numeric, balance_base numeric, currency text, transaction_count bigint, last_activity date)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
WITH
-- Step 1: Get account currencies from chart_of_accounts
account_currencies_raw AS (
    SELECT
        coa.id AS account_id,
        coa.currency AS db_currency
    FROM chart_of_accounts coa
    WHERE coa.company_id = p_company_id
      AND coa.is_group = false
),
-- Step 2: Detect actual currency from journal lines (for NULL db_currency)
line_currencies AS (
    SELECT DISTINCT ON (jel.account_id)
        jel.account_id,
        jel.currency AS line_currency
    FROM journal_entry_lines jel
    INNER JOIN journal_entries je
        ON je.id = jel.entry_id
       AND je.company_id = p_company_id
       AND je.is_posted = true
       AND je.status = 'posted'
    WHERE jel.currency IS NOT NULL AND jel.currency != ''
    GROUP BY jel.account_id, jel.currency
    ORDER BY jel.account_id, COUNT(*) DESC
),
-- Step 3: Detect mixed-currency accounts
-- An account is "mixed" if journal lines have > 1 distinct currency
mixed_currency_accounts AS (
    SELECT jel.account_id,
           COUNT(DISTINCT jel.currency) AS num_currencies
    FROM journal_entry_lines jel
    INNER JOIN journal_entries je
        ON je.id = jel.entry_id
       AND je.company_id = p_company_id
       AND je.is_posted = true
       AND je.status = 'posted'
    WHERE jel.currency IS NOT NULL AND jel.currency != ''
    GROUP BY jel.account_id
    HAVING COUNT(DISTINCT jel.currency) > 1
),
-- Step 4: For mixed-currency accounts, find the BASE currency
-- The base currency = currency of entries with exchange_rate = 1
-- when other entries have exchange_rate > 1
-- (e.g., UAH entries with rate=1 + USD entries with rate=43.89 → base=UAH)
mixed_base_currency AS (
    SELECT DISTINCT ON (jel.account_id)
        jel.account_id,
        jel.currency AS base_currency
    FROM journal_entry_lines jel
    INNER JOIN journal_entries je
        ON je.id = jel.entry_id
       AND je.company_id = p_company_id
       AND je.is_posted = true
       AND je.status = 'posted'
    INNER JOIN mixed_currency_accounts mca ON mca.account_id = jel.account_id
    WHERE jel.currency IS NOT NULL
      AND jel.currency != ''
      AND COALESCE(jel.exchange_rate, 1) = 1
    GROUP BY jel.account_id, jel.currency
    ORDER BY jel.account_id, COUNT(*) DESC
),
-- Step 5: Merge currencies
account_currencies AS (
    SELECT
        acr.account_id,
        CASE
            -- Mixed currencies: use detected base currency
            WHEN mca.account_id IS NOT NULL
            THEN COALESCE(mbc.base_currency,
                         (SELECT default_currency FROM companies WHERE id = p_company_id),
                         'USD')
            -- Single currency: use DB or line currency
            ELSE COALESCE(
                NULLIF(acr.db_currency, ''),
                lc.line_currency,
                (SELECT default_currency FROM companies WHERE id = p_company_id),
                'USD'
            )
        END AS account_currency,
        (mca.account_id IS NOT NULL) AS is_mixed_currency
    FROM account_currencies_raw acr
    LEFT JOIN line_currencies lc ON lc.account_id = acr.account_id
    LEFT JOIN mixed_currency_accounts mca ON mca.account_id = acr.account_id
    LEFT JOIN mixed_base_currency mbc ON mbc.account_id = acr.account_id
),
-- Step 6: Calculate balances
posted_lines AS (
    SELECT
        jel.account_id,
        CASE
            WHEN jel.debit_fc IS NOT NULL AND jel.debit_fc > 0 THEN jel.debit_fc
            WHEN COALESCE(jel.exchange_rate, 1) > 1 THEN jel.debit / jel.exchange_rate
            ELSE jel.debit
        END AS fc_debit,
        CASE
            WHEN jel.credit_fc IS NOT NULL AND jel.credit_fc > 0 THEN jel.credit_fc
            WHEN COALESCE(jel.exchange_rate, 1) > 1 THEN jel.credit / jel.exchange_rate
            ELSE jel.credit
        END AS fc_credit,
        jel.debit AS base_debit,
        jel.credit AS base_credit,
        je.entry_date
    FROM journal_entry_lines jel
    INNER JOIN journal_entries je
        ON je.id = jel.entry_id
       AND je.company_id = p_company_id
       AND je.is_posted = true
       AND je.status = 'posted'
)
SELECT
    ac.account_id::UUID,
    COALESCE(SUM(pl.fc_debit), 0)::NUMERIC AS total_debit,
    COALESCE(SUM(pl.fc_credit), 0)::NUMERIC AS total_credit,
    -- For mixed-currency accounts: use balance_base (consistent currency)
    -- For single-currency accounts: use FC balance (native currency)
    CASE
        WHEN ac.is_mixed_currency THEN
            (COALESCE(SUM(pl.base_debit), 0) - COALESCE(SUM(pl.base_credit), 0))::NUMERIC
        ELSE
            (COALESCE(SUM(pl.fc_debit), 0) - COALESCE(SUM(pl.fc_credit), 0))::NUMERIC
    END AS balance,
    (COALESCE(SUM(pl.base_debit), 0) - COALESCE(SUM(pl.base_credit), 0))::NUMERIC AS balance_base,
    ac.account_currency::TEXT AS currency,
    COUNT(pl.fc_debit)::BIGINT AS transaction_count,
    MAX(pl.entry_date)::DATE AS last_activity
FROM account_currencies ac
LEFT JOIN posted_lines pl ON pl.account_id = ac.account_id
GROUP BY ac.account_id, ac.account_currency, ac.is_mixed_currency;
$$;


--
-- Name: get_all_import_entity_definitions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_all_import_entity_definitions() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_definitions JSONB;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            'entity_type', entity_type,
            'target_table', target_table,
            'display_name_ar', display_name_ar,
            'display_name_en', display_name_en,
            'icon', icon,
            'fields', fields,
            'required_fields', required_fields,
            'unique_fields', unique_fields,
            'lookup_fields', lookup_fields
        ) ORDER BY display_order
    ) INTO v_definitions
    FROM import_entity_definitions
    WHERE is_active = true;
    
    RETURN COALESCE(v_definitions, '[]'::JSONB);
END;
$$;


--
-- Name: get_all_plan_limits(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_all_plan_limits(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_plan RECORD;
    v_plan_id UUID;
    v_users_count INT := 0;
    v_companies_count INT := 0;
    v_branches_count INT := 0;
    v_warehouses_count INT := 0;
    v_products_count INT := 0;
    v_customers_count INT := 0;
    v_invoices_count INT := 0;
BEGIN
    -- جلب الباقة من tenant_subscriptions
    SELECT ts.plan_id INTO v_plan_id
    FROM tenant_subscriptions ts
    WHERE ts.tenant_id = p_tenant_id
      AND ts.status IN ('trial', 'active', 'grace')
    ORDER BY 
      CASE ts.status
        WHEN 'active' THEN 1 WHEN 'trial' THEN 2 WHEN 'grace' THEN 3
      END
    LIMIT 1;

    -- Fallback
    IF v_plan_id IS NULL THEN
        SELECT plan_id INTO v_plan_id
        FROM subscriptions
        WHERE tenant_id = p_tenant_id AND status IN ('trial', 'active')
        ORDER BY created_at DESC LIMIT 1;
    END IF;

    IF v_plan_id IS NULL THEN
        RETURN jsonb_build_object('error', 'no_active_subscription');
    END IF;

    SELECT * INTO v_plan FROM subscription_plans WHERE id = v_plan_id;

    -- عد الموارد الحالية
    SELECT COUNT(*) INTO v_users_count FROM user_profiles WHERE tenant_id = p_tenant_id;
    SELECT COUNT(*) INTO v_companies_count FROM companies WHERE tenant_id = p_tenant_id;
    
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'branches' AND table_schema = 'public') THEN
        SELECT COUNT(*) INTO v_branches_count FROM branches WHERE tenant_id = p_tenant_id;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'warehouses' AND table_schema = 'public') THEN
        SELECT COUNT(*) INTO v_warehouses_count FROM warehouses WHERE tenant_id = p_tenant_id;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'products' AND table_schema = 'public') THEN
        SELECT COUNT(*) INTO v_products_count FROM products WHERE tenant_id = p_tenant_id;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'customers' AND table_schema = 'public') THEN
        SELECT COUNT(*) INTO v_customers_count FROM customers WHERE tenant_id = p_tenant_id;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'sales_invoices' AND table_schema = 'public') THEN
        SELECT COUNT(*) INTO v_invoices_count FROM sales_invoices WHERE tenant_id = p_tenant_id AND created_at >= date_trunc('month', CURRENT_DATE);
    END IF;

    RETURN jsonb_build_object(
        'plan_code', v_plan.code,
        'plan_name_ar', v_plan.name_ar,
        'plan_name_en', v_plan.name_en,
        'plan_type', v_plan.plan_type,
        'limits', jsonb_build_object(
            'users',      jsonb_build_object('current', v_users_count, 'max', v_plan.max_users, 'unlimited', v_plan.max_users = -1, 'allowed', v_plan.max_users = -1 OR v_users_count < v_plan.max_users),
            'companies',  jsonb_build_object('current', v_companies_count, 'max', v_plan.max_companies, 'unlimited', v_plan.max_companies = -1, 'allowed', v_plan.max_companies = -1 OR v_companies_count < v_plan.max_companies),
            'branches',   jsonb_build_object('current', v_branches_count, 'max', v_plan.max_branches, 'unlimited', v_plan.max_branches = -1, 'allowed', v_plan.max_branches = -1 OR v_branches_count < v_plan.max_branches),
            'warehouses', jsonb_build_object('current', v_warehouses_count, 'max', v_plan.max_warehouses, 'unlimited', v_plan.max_warehouses = -1, 'allowed', v_plan.max_warehouses = -1 OR v_warehouses_count < v_plan.max_warehouses),
            'products',   jsonb_build_object('current', v_products_count, 'max', v_plan.max_products, 'unlimited', v_plan.max_products = -1, 'allowed', v_plan.max_products = -1 OR v_products_count < v_plan.max_products),
            'customers',  jsonb_build_object('current', v_customers_count, 'max', v_plan.max_customers, 'unlimited', v_plan.max_customers = -1, 'allowed', v_plan.max_customers = -1 OR v_customers_count < v_plan.max_customers),
            'invoices_monthly', jsonb_build_object('current', v_invoices_count, 'max', v_plan.max_invoices_monthly, 'unlimited', v_plan.max_invoices_monthly = -1, 'allowed', v_plan.max_invoices_monthly = -1 OR v_invoices_count < v_plan.max_invoices_monthly),
            'storage_gb', jsonb_build_object('current', 0, 'max', v_plan.storage_gb, 'unlimited', v_plan.storage_gb = -1)
        ),
        'modules', COALESCE(
            NULLIF((SELECT array_agg(tm.module_code ORDER BY tm.module_code)
                    FROM tenant_modules tm
                    WHERE tm.tenant_id = p_tenant_id AND tm.is_active), '{}'),
            v_plan.included_modules
        ),
        'features', v_plan.features
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('error', 'exception', 'message', SQLERRM);
END;
$$;


--
-- Name: get_allowed_tabs(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_allowed_tabs(p_tenant_id uuid, p_section_code character varying) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_plan_id UUID;
    v_plan_code VARCHAR(50);
    v_tabs JSONB;
BEGIN
    -- الحصول على plan_id و plan_code
    SELECT s.plan_id, sp.code INTO v_plan_id, v_plan_code
    FROM subscriptions s
    JOIN subscription_plans sp ON sp.id = s.plan_id
    WHERE s.tenant_id = p_tenant_id
    AND s.status = 'active'
    ORDER BY s.created_at DESC
    LIMIT 1;
    
    -- إرجاع التبويبات المتاحة
    SELECT jsonb_agg(
        jsonb_build_object(
            'code', tab_code,
            'name_ar', tab_name_ar,
            'name_en', tab_name_en,
            'icon', icon,
            'order', display_order,
            'is_core', is_core
        )
        ORDER BY display_order
    ) INTO v_tabs
    FROM ui_tabs
    WHERE section_code = p_section_code
    AND is_active = true
    AND (
        -- التبويبات الأساسية
        is_core = true
        OR
        -- التبويبات بدون شروط
        (required_feature_code IS NULL AND min_plan_level IS NULL)
        OR
        -- التبويبات بشرط الباقة فقط
        (
            required_feature_code IS NULL 
            AND min_plan_level IS NOT NULL
            AND CASE v_plan_code
                WHEN 'starter' THEN min_plan_level = 'starter'
                WHEN 'professional' THEN min_plan_level IN ('starter', 'professional')
                WHEN 'enterprise' THEN true
                ELSE false
            END
        )
        OR
        -- التبويبات بشرط الميزة
        (
            required_feature_code IS NOT NULL
            AND EXISTS (
                SELECT 1 FROM plan_module_features pmf
                WHERE pmf.plan_id = v_plan_id
                AND pmf.feature_code = required_feature_code
                AND pmf.is_enabled = true
            )
        )
    );
    
    RETURN COALESCE(v_tabs, '[]'::jsonb);
END;
$$;


--
-- Name: get_available_categories_for_customer(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_available_categories_for_customer(p_tenant_id uuid, p_customer_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, code character varying, name_ar character varying, name_en character varying, description text, image_url text, slug character varying, parent_id uuid, display_order integer, products_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- نسخة بسيطة - ترجع جميع الفئات (استعلام ديناميكي آمن)
    RETURN QUERY
    SELECT 
        pc.id,
        COALESCE(pc.code, '') as code,
        COALESCE(pc.name_en, '') as name_ar,
        COALESCE(pc.name_en, '') as name_en,
        ''::TEXT as description,
        NULL::TEXT as image_url,
        NULL::VARCHAR as slug,
        pc.parent_id,
        0 as display_order,
        0::BIGINT as products_count
    FROM product_categories pc
    ORDER BY pc.name_en;
END;
$$;


--
-- Name: get_available_mfa_methods(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_available_mfa_methods() RETURNS TABLE(method character varying, is_available boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_totp BOOLEAN;
    v_email BOOLEAN;
    v_sms BOOLEAN;
BEGIN
    SELECT allow_totp, allow_email_otp, allow_sms_otp 
    INTO v_totp, v_email, v_sms
    FROM mfa_system_settings LIMIT 1;
    
    method := 'totp'; is_available := COALESCE(v_totp, true); RETURN NEXT;
    method := 'email'; is_available := COALESCE(v_email, true); RETURN NEXT;
    method := 'sms'; is_available := COALESCE(v_sms, false); RETURN NEXT;
END;
$$;


--
-- Name: get_available_reports(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_available_reports(p_category character varying DEFAULT NULL::character varying) RETURNS TABLE(id uuid, code character varying, name_ar character varying, name_en character varying, category character varying, description text, is_system boolean, use_count integer, last_used_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        rt.id, rt.code, rt.name_ar, rt.name_en,
        rt.category, rt.description, rt.is_system,
        rt.use_count, rt.last_used_at
    FROM report_templates rt
    WHERE rt.is_active = true
      AND (p_category IS NULL OR rt.category = p_category)
    ORDER BY rt.is_system DESC, rt.use_count DESC, rt.name_ar;
END;
$$;


--
-- Name: get_balance_sheet(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_balance_sheet(p_company_id uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS TABLE(category character varying, category_ar character varying, account_id uuid, account_code character varying, account_name_ar character varying, account_name_en character varying, balance numeric, is_subtotal boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH balance_data AS (
        SELECT 
            coa.id as account_id,
            coa.account_code,
            coa.name_ar as account_name_ar,
            coa.name_en as account_name_en,
            at.classification,
            at.normal_balance,
            coa.opening_balance,
            COALESCE(SUM(jel.debit), 0) as total_debit,
            COALESCE(SUM(jel.credit), 0) as total_credit
        FROM chart_of_accounts coa
        JOIN account_types at ON coa.account_type_id = at.id
        LEFT JOIN journal_entry_lines jel ON coa.id = jel.account_id
        LEFT JOIN journal_entries je ON jel.entry_id = je.id 
            AND je.is_posted = true
            AND je.entry_date <= p_as_of_date
        WHERE coa.company_id = p_company_id
          AND coa.is_active = true
          AND coa.is_detail = true
          AND at.classification IN ('assets', 'liabilities', 'equity')
        GROUP BY coa.id, coa.account_code, coa.name_ar, coa.name_en, at.classification, at.normal_balance, coa.opening_balance
    ),
    calculated_balances AS (
        SELECT 
            bd.*,
            CASE 
                WHEN bd.normal_balance = 'debit' THEN 
                    COALESCE(bd.opening_balance, 0) + bd.total_debit - bd.total_credit
                ELSE 
                    COALESCE(bd.opening_balance, 0) + bd.total_credit - bd.total_debit
            END as balance
        FROM balance_data bd
    )
    -- الأصول
    SELECT 
        'assets'::VARCHAR(50) as category,
        'الأصول'::VARCHAR(100) as category_ar,
        cb.account_id,
        cb.account_code,
        cb.account_name_ar,
        cb.account_name_en,
        cb.balance,
        false as is_subtotal
    FROM calculated_balances cb
    WHERE cb.classification = 'assets' AND cb.balance != 0
    
    UNION ALL
    
    -- إجمالي الأصول
    SELECT 
        'assets_total'::VARCHAR(50),
        'إجمالي الأصول'::VARCHAR(100),
        NULL::UUID,
        ''::VARCHAR(50),
        'إجمالي الأصول'::VARCHAR(200),
        'Total Assets'::VARCHAR(200),
        COALESCE(SUM(balance), 0),
        true
    FROM calculated_balances
    WHERE classification = 'assets'
    
    UNION ALL
    
    -- الخصوم
    SELECT 
        'liabilities'::VARCHAR(50),
        'الخصوم'::VARCHAR(100),
        cb.account_id,
        cb.account_code,
        cb.account_name_ar,
        cb.account_name_en,
        cb.balance,
        false
    FROM calculated_balances cb
    WHERE cb.classification = 'liabilities' AND cb.balance != 0
    
    UNION ALL
    
    -- إجمالي الخصوم
    SELECT 
        'liabilities_total'::VARCHAR(50),
        'إجمالي الخصوم'::VARCHAR(100),
        NULL::UUID,
        ''::VARCHAR(50),
        'إجمالي الخصوم'::VARCHAR(200),
        'Total Liabilities'::VARCHAR(200),
        COALESCE(SUM(balance), 0),
        true
    FROM calculated_balances
    WHERE classification = 'liabilities'
    
    UNION ALL
    
    -- حقوق الملكية
    SELECT 
        'equity'::VARCHAR(50),
        'حقوق الملكية'::VARCHAR(100),
        cb.account_id,
        cb.account_code,
        cb.account_name_ar,
        cb.account_name_en,
        cb.balance,
        false
    FROM calculated_balances cb
    WHERE cb.classification = 'equity' AND cb.balance != 0
    
    UNION ALL
    
    -- إجمالي حقوق الملكية
    SELECT 
        'equity_total'::VARCHAR(50),
        'إجمالي حقوق الملكية'::VARCHAR(100),
        NULL::UUID,
        ''::VARCHAR(50),
        'إجمالي حقوق الملكية'::VARCHAR(200),
        'Total Equity'::VARCHAR(200),
        COALESCE(SUM(balance), 0),
        true
    FROM calculated_balances
    WHERE classification = 'equity'
    
    UNION ALL
    
    -- إجمالي الخصوم وحقوق الملكية
    SELECT 
        'liabilities_equity_total'::VARCHAR(50),
        'إجمالي الخصوم وحقوق الملكية'::VARCHAR(100),
        NULL::UUID,
        ''::VARCHAR(50),
        'إجمالي الخصوم وحقوق الملكية'::VARCHAR(200),
        'Total Liabilities & Equity'::VARCHAR(200),
        COALESCE(SUM(balance), 0),
        true
    FROM calculated_balances
    WHERE classification IN ('liabilities', 'equity')
    
    ORDER BY 
        CASE category 
            WHEN 'assets' THEN 1 
            WHEN 'assets_total' THEN 2
            WHEN 'liabilities' THEN 3 
            WHEN 'liabilities_total' THEN 4
            WHEN 'equity' THEN 5
            WHEN 'equity_total' THEN 6
            WHEN 'liabilities_equity_total' THEN 7
        END,
        account_code;
END;
$$;


--
-- Name: FUNCTION get_balance_sheet(p_company_id uuid, p_as_of_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_balance_sheet(p_company_id uuid, p_as_of_date date) IS 'الميزانية العمومية - الأصول والخصوم وحقوق الملكية';


--
-- Name: get_brand_tenant_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_brand_tenant_ids(p_product_id uuid) RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_ids UUID[];
BEGIN
    SELECT ARRAY_AGG(id)
    INTO v_tenant_ids
    FROM public.tenants
    WHERE product_id = p_product_id
      AND status = 'active';
    
    RETURN COALESCE(v_tenant_ids, ARRAY[]::UUID[]);
EXCEPTION WHEN OTHERS THEN
    RETURN ARRAY[]::UUID[];
END;
$$;


--
-- Name: get_budget_vs_actual_report(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_budget_vs_actual_report(p_budget_id uuid) RETURNS TABLE(account_code character varying, account_name character varying, period character varying, budgeted numeric, actual numeric, variance numeric, variance_percent numeric, status character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        coa.account_code,
        coa.name_ar as account_name,
        bl.period,
        bl.budgeted_amount as budgeted,
        bl.actual_amount as actual,
        bl.variance,
        bl.variance_percent,
        CASE 
            WHEN bl.actual_amount >= bl.budgeted_amount * 1.2 THEN 'critical'
            WHEN bl.actual_amount >= bl.budgeted_amount THEN 'exceeded'
            WHEN bl.actual_amount >= bl.budgeted_amount * 0.9 THEN 'warning'
            ELSE 'ok'
        END as status
    FROM budget_lines bl
    JOIN chart_of_accounts coa ON bl.account_id = coa.id
    WHERE bl.budget_id = p_budget_id
    ORDER BY coa.account_code, bl.period;
END;
$$;


--
-- Name: get_cart(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_cart(p_tenant_id uuid, p_customer_id uuid DEFAULT NULL::uuid, p_session_id character varying DEFAULT NULL::character varying) RETURNS TABLE(cart_id uuid, item_id uuid, product_id uuid, product_code character varying, product_name_ar character varying, product_name_en character varying, product_image text, variant_id uuid, quantity numeric, unit_price numeric, original_price numeric, discount_percent numeric, subtotal numeric, notes text, available_quantity numeric, in_stock boolean, price_changed boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_cart_id UUID;
BEGIN
    -- الحصول على السلة
    IF p_customer_id IS NOT NULL THEN
        SELECT id INTO v_cart_id
        FROM shopping_carts
        WHERE tenant_id = p_tenant_id
          AND customer_id = p_customer_id
          AND status = 'active'
        LIMIT 1;
    ELSIF p_session_id IS NOT NULL THEN
        SELECT id INTO v_cart_id
        FROM shopping_carts
        WHERE tenant_id = p_tenant_id
          AND session_id = p_session_id
          AND status = 'active'
        LIMIT 1;
    END IF;
    
    IF v_cart_id IS NULL THEN
        RETURN;
    END IF;
    
    -- إرجاع العناصر
    RETURN QUERY
    SELECT 
        sci.cart_id,
        sci.id,
        sci.product_id,
        p.sku,
        p.name_ar,
        p.name_en,
        get_product_primary_image(p.id),
        sci.product_variant_id,
        sci.quantity,
        sci.unit_price,
        sci.original_price,
        sci.discount_percent,
        sci.subtotal,
        sci.notes,
        COALESCE(
            (SELECT SUM(quantity_on_hand) 
             FROM inventory_stock 
             WHERE product_id = p.id),
            0
        ) as available_quantity,
        CASE 
            WHEN COALESCE(
                (SELECT SUM(quantity_on_hand) 
                 FROM inventory_stock 
                 WHERE product_id = p.id),
                0
            ) >= sci.quantity THEN true
            ELSE false
        END as in_stock,
        sci.price_changed
    FROM shopping_cart_items sci
    JOIN products p ON p.id = sci.product_id
    WHERE sci.cart_id = v_cart_id
    ORDER BY sci.created_at;
END;
$$;


--
-- Name: get_cart_summary(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_cart_summary(p_tenant_id uuid, p_customer_id uuid DEFAULT NULL::uuid, p_session_id character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_cart_id UUID;
    v_summary JSONB;
BEGIN
    -- الحصول على السلة
    IF p_customer_id IS NOT NULL THEN
        SELECT id INTO v_cart_id
        FROM shopping_carts
        WHERE tenant_id = p_tenant_id
          AND customer_id = p_customer_id
          AND status = 'active'
        LIMIT 1;
    ELSIF p_session_id IS NOT NULL THEN
        SELECT id INTO v_cart_id
        FROM shopping_carts
        WHERE tenant_id = p_tenant_id
          AND session_id = p_session_id
          AND status = 'active'
        LIMIT 1;
    END IF;
    
    IF v_cart_id IS NULL THEN
        RETURN jsonb_build_object(
            'cart_exists', false,
            'items_count', 0,
            'subtotal', 0,
            'total', 0
        );
    END IF;
    
    -- بناء الملخص
    SELECT jsonb_build_object(
        'cart_exists', true,
        'cart_id', sc.id,
        'items_count', (SELECT COUNT(*) FROM shopping_cart_items WHERE cart_id = sc.id),
        'total_quantity', (SELECT SUM(quantity) FROM shopping_cart_items WHERE cart_id = sc.id),
        'subtotal', sc.subtotal,
        'discount', sc.promo_discount,
        'total', sc.total_amount,
        'currency', sc.currency,
        'promo_code', sc.promo_code,
        'updated_at', sc.updated_at
    )
    INTO v_summary
    FROM shopping_carts sc
    WHERE sc.id = v_cart_id;
    
    RETURN v_summary;
END;
$$;


--
-- Name: get_collection_products(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_collection_products(p_store_id uuid, p_collection text, p_limit integer DEFAULT 12) RETURNS TABLE(id uuid, material_id uuid, product_id uuid, marketing_title jsonb, marketing_description jsonb, short_description jsonb, gallery_images text[], seo_slug text, tags text[], is_featured boolean, is_new boolean, is_bestseller boolean, is_on_sale boolean, sale_price numeric, sale_unit text, min_order_quantity numeric, view_count integer, order_count integer, published_at timestamp with time zone, material_code text, material_name_ar text, material_name_en text, unit_price numeric, selling_price numeric, material_image text, effective_price numeric, category_slugs text[], stock_status text, total_stock numeric, available_date timestamp with time zone, supplier_lead_time text, currency text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    WITH base AS (
        SELECT g.*, ep.created_at AS _created,
               ep.sale_start_date AS _sale_start, ep.sale_end_date AS _sale_end,
               ep.base_price AS _base_price
        FROM get_ecommerce_products(p_store_id, NULL, NULL, false, 500, 0) g
        JOIN ecommerce_products ep ON ep.id = g.id
    ),
    sales90 AS (
        SELECT oi.product_id AS pid, SUM(oi.quantity) AS qty
        FROM ecommerce_order_items oi
        JOIN ecommerce_orders o ON o.id = oi.order_id
        WHERE o.store_id = p_store_id
          AND o.status NOT IN ('cancelled', 'refunded', 'failed')
          AND o.created_at >= now() - INTERVAL '90 days'
        GROUP BY oi.product_id
    )
    SELECT b.id, b.material_id, b.product_id,
           b.marketing_title, b.marketing_description, b.short_description,
           b.gallery_images, b.seo_slug, b.tags,
           b.is_featured,
           (COALESCE(b.published_at, b._created) >= now() - INTERVAL '45 days') AS is_new,
           (COALESCE(s.qty, 0) > 0 OR b.order_count > 0) AS is_bestseller,
           (b.sale_price IS NOT NULL
            AND (b._sale_start IS NULL OR b._sale_start <= now())
            AND (b._sale_end IS NULL OR b._sale_end >= now())) AS is_on_sale,
           b.sale_price, b.sale_unit, b.min_order_quantity,
           b.view_count, b.order_count, b.published_at,
           b.material_code, b.material_name_ar, b.material_name_en,
           b.unit_price, b.selling_price, b.material_image,
           b.effective_price, b.category_slugs,
           b.stock_status, b.total_stock, b.available_date,
           b.supplier_lead_time, b.currency
    FROM base b
    LEFT JOIN sales90 s ON s.pid = b.id
    WHERE CASE
        WHEN p_collection = 'new' THEN
            COALESCE(b.published_at, b._created) >= now() - INTERVAL '45 days'
        WHEN p_collection = 'sale' THEN
            b.sale_price IS NOT NULL
            AND (b._sale_start IS NULL OR b._sale_start <= now())
            AND (b._sale_end IS NULL OR b._sale_end >= now())
        WHEN p_collection = 'bestsellers' THEN
            COALESCE(s.qty, 0) > 0 OR b.order_count > 0
        WHEN p_collection LIKE 'season:%' THEN
            p_collection = ANY(COALESCE(b.tags, '{}'))
        ELSE true
    END
    ORDER BY CASE
        WHEN p_collection = 'new' THEN extract(epoch FROM COALESCE(b.published_at, b._created))
        WHEN p_collection = 'sale' THEN
            CASE WHEN COALESCE(b._base_price, b.selling_price, 0) > 0
                 THEN (COALESCE(b._base_price, b.selling_price) - b.sale_price)
                      / COALESCE(b._base_price, b.selling_price)
                 ELSE 0 END
        WHEN p_collection = 'bestsellers' THEN COALESCE(s.qty, 0) + COALESCE(b.order_count, 0) * 0.1
        WHEN p_collection LIKE 'season:%' THEN
            -- داخل الموسم: الأكثر مبيعاً أولاً ثم الأحدث
            COALESCE(s.qty, 0) * 1000 + extract(epoch FROM COALESCE(b.published_at, b._created)) / 1e9
        ELSE b.view_count
    END DESC
    LIMIT GREATEST(p_limit, 1)
$$;


