--
-- Name: get_company_insights(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_company_insights(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'overview', COALESCE(overview, '{}'::jsonb),
        'sales_summary', COALESCE(sales_summary, '{}'::jsonb),
        'sales_by_material', COALESCE(sales_by_material, '[]'::jsonb),
        'purchases_summary', COALESCE(purchases_summary, '{}'::jsonb),
        'accounting_summary', COALESCE(accounting_summary, '{}'::jsonb),
        'inventory_status', COALESCE(inventory_status, '{}'::jsonb),
        'all_materials', COALESCE(all_materials, '[]'::jsonb),
        'rolls_by_material', COALESCE(rolls_by_material, '[]'::jsonb),
        'customers_list', COALESCE(customers_list, '[]'::jsonb),
        'suppliers_list', COALESCE(suppliers_list, '[]'::jsonb),
        'warehouses_list', COALESCE(warehouses_list, '[]'::jsonb),
        'containers_list', COALESCE(containers_list, '[]'::jsonb),
        'equity_info', COALESCE(equity_info, '{}'::jsonb),
        'chart_summary', COALESCE(chart_summary, '{}'::jsonb),
        'last_refreshed_at', last_refreshed_at,
        'refresh_duration_ms', refresh_duration_ms,
        'is_stale', is_stale
    ) INTO v_result
    FROM company_insights
    WHERE company_id = p_company_id;

    -- If no cache, build it
    IF v_result IS NULL THEN
        PERFORM refresh_company_insights(p_company_id);
        SELECT jsonb_build_object(
            'overview', COALESCE(overview, '{}'::jsonb),
            'sales_summary', COALESCE(sales_summary, '{}'::jsonb),
            'sales_by_material', COALESCE(sales_by_material, '[]'::jsonb),
            'purchases_summary', COALESCE(purchases_summary, '{}'::jsonb),
            'accounting_summary', COALESCE(accounting_summary, '{}'::jsonb),
            'inventory_status', COALESCE(inventory_status, '{}'::jsonb),
            'all_materials', COALESCE(all_materials, '[]'::jsonb),
            'rolls_by_material', COALESCE(rolls_by_material, '[]'::jsonb),
            'customers_list', COALESCE(customers_list, '[]'::jsonb),
            'suppliers_list', COALESCE(suppliers_list, '[]'::jsonb),
            'warehouses_list', COALESCE(warehouses_list, '[]'::jsonb),
            'containers_list', COALESCE(containers_list, '[]'::jsonb),
            'equity_info', COALESCE(equity_info, '{}'::jsonb),
            'chart_summary', COALESCE(chart_summary, '{}'::jsonb),
            'last_refreshed_at', last_refreshed_at,
            'refresh_duration_ms', refresh_duration_ms,
            'is_stale', is_stale
        ) INTO v_result
        FROM company_insights
        WHERE company_id = p_company_id;
    END IF;

    RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


--
-- Name: get_company_rounding_settings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_company_rounding_settings(p_company_id uuid) RETURNS TABLE(rounding_method character varying, tax_rounding integer, amount_rounding integer, unit_price_rounding integer, total_rounding integer)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COALESCE(
            CASE WHEN c.inherit_country_rounding THEN co.rounding_method ELSE c.rounding_method END,
            'half_up'
        )::VARCHAR(10),
        COALESCE(
            CASE WHEN c.inherit_country_rounding THEN co.tax_rounding ELSE c.tax_rounding END,
            2
        )::INT,
        COALESCE(
            CASE WHEN c.inherit_country_rounding THEN co.amount_rounding ELSE c.amount_rounding END,
            2
        )::INT,
        COALESCE(
            CASE WHEN c.inherit_country_rounding THEN co.unit_price_rounding ELSE c.unit_price_rounding END,
            2
        )::INT,
        COALESCE(
            CASE WHEN c.inherit_country_rounding THEN co.total_rounding ELSE c.total_rounding END,
            2
        )::INT
    FROM companies c
    LEFT JOIN company_countries cc ON cc.company_id = c.id AND cc.is_primary = true
    LEFT JOIN countries co ON co.code = cc.country_code
    WHERE c.id = p_company_id;
END;
$$;


--
-- Name: get_confirmation_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_confirmation_counts(p_company_id uuid) RETURNS TABLE(item_type text, cnt bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM assert_can_access_company(p_company_id);
    RETURN QUERY
    SELECT i.item_type, count(*)::bigint
    FROM get_confirmation_inbox(p_company_id, NULL, NULL) i
    GROUP BY i.item_type;
END;
$$;


--
-- Name: get_confirmation_inbox(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_confirmation_inbox(p_company_id uuid, p_status text DEFAULT NULL::text, p_type text DEFAULT NULL::text) RETURNS TABLE(item_type text, item_id uuid, ref_number text, party_name text, amount numeric, status text, source text, title text, created_at timestamp with time zone, creator_name text, creator_phone text, creator_telegram text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM assert_can_access_company(p_company_id);

    RETURN QUERY
    SELECT 'payment_receipt'::text, pr.id, pr.receipt_number::text,
           COALESCE(NULLIF(pr.customer_name,''), c.name_ar, c.name_en, c.company_name, '—')::text,
           pr.amount, pr.status::text, 'app'::text,
           COALESCE(NULLIF(pr.notes,''),'سند قبض')::text, pr.created_at,
           COALESCE(up.full_name, up.display_name)::text, up.phone::text,
           COALESCE(up.telegram_username, up.telegram_chat_id::text)::text
    FROM payment_receipts pr LEFT JOIN customers c ON c.id = pr.customer_id
         LEFT JOIN user_profiles up ON up.id = pr.created_by
    WHERE pr.company_id = p_company_id
      AND (p_type IS NULL OR p_type='payment_receipt')
      AND (CASE WHEN p_status IS NULL THEN pr.status='draft' ELSE pr.status=p_status END)

    UNION ALL
    SELECT 'payment_voucher'::text, pv.id, pv.voucher_number::text,
           COALESCE(NULLIF(pv.supplier_name,''), s.name_ar, s.name_en, '—')::text,
           pv.amount, pv.status::text, 'app'::text,
           COALESCE(NULLIF(pv.notes,''),'سند صرف')::text, pv.created_at,
           COALESCE(up.full_name, up.display_name)::text, up.phone::text,
           COALESCE(up.telegram_username, up.telegram_chat_id::text)::text
    FROM payment_vouchers pv LEFT JOIN suppliers s ON s.id = pv.supplier_id
         LEFT JOIN user_profiles up ON up.id = pv.created_by
    WHERE pv.company_id = p_company_id
      AND (p_type IS NULL OR p_type='payment_voucher')
      AND (CASE WHEN p_status IS NULL THEN pv.status='draft' ELSE pv.status=p_status END)

    UNION ALL
    SELECT 'journal_entry'::text, je.id, je.entry_number::text, '—'::text,
           je.total_debit, je.status::text, 'app'::text,
           COALESCE(NULLIF(je.description,''),'قيد يومية')::text, je.created_at,
           COALESCE(up.full_name, up.display_name)::text, up.phone::text,
           COALESCE(up.telegram_username, up.telegram_chat_id::text)::text
    FROM journal_entries je LEFT JOIN user_profiles up ON up.id = je.created_by
    WHERE je.company_id = p_company_id
      AND (p_type IS NULL OR p_type='journal_entry')
      AND (CASE WHEN p_status IS NULL THEN je.status='draft' ELSE je.status=p_status END)

    UNION ALL
    SELECT 'sales_invoice'::text, st.id,
           COALESCE(NULLIF(st.tracking_number,''),'ST-'||upper(substr(st.id::text,1,8)))::text,
           COALESCE(c.name_ar, c.name_en, c.company_name, '—')::text,
           st.total_amount, st.stage::text, COALESCE(st.source_type,'app')::text,
           'فاتورة مبيعات'::text, st.created_at,
           COALESCE(up.full_name, up.display_name, st.created_by_name)::text, up.phone::text,
           COALESCE(up.telegram_username, up.telegram_chat_id::text)::text
    FROM sales_transactions st LEFT JOIN customers c ON c.id = st.customer_id
         LEFT JOIN user_profiles up ON up.id = st.created_by
    WHERE st.company_id = p_company_id
      AND (p_type IS NULL OR p_type='sales_invoice')
      AND (CASE WHEN p_status IS NULL
                THEN (st.stage IN ('draft','confirmed') AND COALESCE(st.is_posted,false)=false)
                ELSE st.stage=p_status END)

    UNION ALL
    SELECT 'purchase_invoice'::text, pt.id,
           COALESCE(NULLIF(pt.supplier_invoice_number,''),'PT-'||upper(substr(pt.id::text,1,8)))::text,
           COALESCE(s.name_ar, s.name_en, '—')::text,
           pt.total_amount, pt.stage::text, 'app'::text,
           'فاتورة مشتريات'::text, pt.created_at,
           COALESCE(up.full_name, up.display_name, pt.created_by_name)::text, up.phone::text,
           COALESCE(up.telegram_username, up.telegram_chat_id::text)::text
    FROM purchase_transactions pt LEFT JOIN suppliers s ON s.id = pt.supplier_id
         LEFT JOIN user_profiles up ON up.id = pt.created_by
    WHERE pt.company_id = p_company_id
      AND (p_type IS NULL OR p_type='purchase_invoice')
      AND (CASE WHEN p_status IS NULL
                THEN (pt.stage IN ('draft','confirmed') AND COALESCE(pt.is_posted,false)=false)
                ELSE pt.stage=p_status END)

    UNION ALL
    SELECT 'stock_transfer'::text, tr.id, tr.transfer_number::text, '—'::text,
           tr.total_meters, tr.status::text, 'app'::text,
           'مناقلة مخزون'::text, tr.created_at,
           COALESCE(up.full_name, up.display_name)::text, up.phone::text,
           COALESCE(up.telegram_username, up.telegram_chat_id::text)::text
    FROM stock_transfers tr LEFT JOIN user_profiles up ON up.id = tr.created_by
    WHERE tr.company_id = p_company_id
      AND (p_type IS NULL OR p_type='stock_transfer')
      AND (CASE WHEN p_status IS NULL THEN tr.status='pending' ELSE tr.status=p_status END)

    UNION ALL
    -- 🤖/📋 مسودات البوت: اسم المُنشئ من user_profiles، ومعرّف تلغرام من المسودة نفسها fallback
    SELECT
        (CASE WHEN pa.action_type='task' THEN 'task' ELSE 'pending_action' END)::text,
        pa.id,
        (CASE WHEN pa.action_type='task'
              THEN COALESCE(pa.action_data->>'category','مهمة')
              ELSE pa.action_type END)::text,
        (CASE WHEN pa.action_type='task'
              THEN COALESCE(pa.action_data->>'assignee_name', pa.action_data->>'warehouse_name',
                            pa.action_data->>'customer_name', '—')
              ELSE COALESCE(pa.action_data->>'from_customer', pa.action_data->>'from_name',
                            pa.action_data->>'to_name', pa.action_data->>'party', '—') END)::text,
        COALESCE((pa.action_data->>'amount')::numeric, 0),
        pa.status::text,
        COALESCE(pa.confirmed_via,'telegram')::text,
        (CASE WHEN pa.action_type='task'
              THEN COALESCE(pa.action_data->>'title', NULLIF(pa.original_message,''), 'مهمة')
              ELSE COALESCE(NULLIF(pa.original_message,''), pa.action_type) END)::text,
        pa.created_at,
        COALESCE(up.full_name, up.display_name)::text, up.phone::text,
        COALESCE(up.telegram_username, pa.created_by_telegram_id::text)::text
    FROM pending_actions pa LEFT JOIN user_profiles up ON up.id = pa.created_by_user_id
    WHERE pa.company_id = p_company_id
      AND (p_type IS NULL OR p_type = (CASE WHEN pa.action_type='task' THEN 'task' ELSE 'pending_action' END))
      AND (CASE WHEN p_status IS NULL THEN pa.status='pending' ELSE pa.status=p_status END)

    ORDER BY 9 DESC;
END;
$$;


--
-- Name: get_cost_center_expenses(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_cost_center_expenses(p_cost_center_id uuid, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date) RETURNS TABLE(entry_date date, entry_number character varying, account_name character varying, description text, debit numeric, credit numeric, running_total numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        je.entry_date,
        je.entry_number,
        coa.name_ar as account_name,
        jel.description,
        jel.debit,
        jel.credit,
        SUM(jel.debit - jel.credit) OVER (ORDER BY je.entry_date, je.entry_number) as running_total
    FROM journal_entry_lines jel
    JOIN journal_entries je ON jel.entry_id = je.id
    JOIN chart_of_accounts coa ON jel.account_id = coa.id
    WHERE jel.cost_center_id = p_cost_center_id
      AND je.is_posted = true
      AND (p_start_date IS NULL OR je.entry_date >= p_start_date)
      AND (p_end_date IS NULL OR je.entry_date <= p_end_date)
    ORDER BY je.entry_date, je.entry_number, jel.line_number;
END;
$$;


--
-- Name: get_cost_centers_comparison(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_cost_centers_comparison(p_company_id uuid, p_period character varying DEFAULT 'current_year'::character varying) RETURNS TABLE(cost_center_id uuid, code character varying, name character varying, parent_name character varying, total_expenses numeric, budget_limit numeric, variance numeric, utilization_percent numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_start_date DATE;
    v_end_date DATE;
BEGIN
    -- تحديد الفترة
    CASE p_period
        WHEN 'current_month' THEN
            v_start_date := DATE_TRUNC('month', CURRENT_DATE);
            v_end_date := (DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month - 1 day')::DATE;
        WHEN 'current_quarter' THEN
            v_start_date := DATE_TRUNC('quarter', CURRENT_DATE);
            v_end_date := (DATE_TRUNC('quarter', CURRENT_DATE) + INTERVAL '3 months - 1 day')::DATE;
        ELSE -- current_year
            v_start_date := DATE_TRUNC('year', CURRENT_DATE);
            v_end_date := (DATE_TRUNC('year', CURRENT_DATE) + INTERVAL '1 year - 1 day')::DATE;
    END CASE;
    
    RETURN QUERY
    SELECT 
        cc.id as cost_center_id,
        cc.code,
        cc.name_ar as name,
        p.name_ar as parent_name,
        COALESCE(SUM(jel.debit), 0) as total_expenses,
        cc.budget_limit,
        cc.budget_limit - COALESCE(SUM(jel.debit), 0) as variance,
        CASE 
            WHEN cc.budget_limit > 0 THEN 
                ROUND((COALESCE(SUM(jel.debit), 0) / cc.budget_limit) * 100, 2)
            ELSE 0
        END as utilization_percent
    FROM cost_centers cc
    LEFT JOIN cost_centers p ON cc.parent_id = p.id
    LEFT JOIN journal_entry_lines jel ON jel.cost_center_id = cc.id
    LEFT JOIN journal_entries je ON jel.entry_id = je.id 
        AND je.is_posted = true
        AND je.entry_date BETWEEN v_start_date AND v_end_date
    WHERE cc.company_id = p_company_id
      AND cc.is_active = true
      AND cc.is_group = false
    GROUP BY cc.id, cc.code, cc.name_ar, p.name_ar, cc.budget_limit
    ORDER BY total_expenses DESC;
END;
$$;


