--
-- Name: get_current_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_current_tenant() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
    v_result JSONB;
BEGIN
    v_tenant_id := get_current_tenant_id();
    
    IF v_tenant_id IS NULL THEN
        RETURN NULL;
    END IF;
    
    SELECT jsonb_build_object(
        'id', t.id,
        'code', t.code,
        'name', t.name,
        'status', t.status,
        'default_language', t.default_language,
        'settings', t.settings
    ) INTO v_result
    FROM tenants t
    WHERE t.id = v_tenant_id;
    
    RETURN v_result;
END;
$$;


--
-- Name: get_current_tenant_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_current_tenant_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
    v_user_id UUID;
BEGIN
    -- المحاولة 1: من JWT metadata مباشرة
    v_tenant_id := NULLIF(
        COALESCE(
            auth.jwt() -> 'user_metadata' ->> 'tenant_id',
            auth.jwt() -> 'app_metadata' ->> 'tenant_id'
        ),
        ''
    )::UUID;
    
    IF v_tenant_id IS NOT NULL THEN
        RETURN v_tenant_id;
    END IF;
    
    -- المحاولة 2: من user_profiles
    v_user_id := auth.uid();
    IF v_user_id IS NOT NULL THEN
        SELECT tenant_id INTO v_tenant_id
        FROM user_profiles
        WHERE id = v_user_id
        LIMIT 1;
        
        IF v_tenant_id IS NOT NULL THEN
            RETURN v_tenant_id;
        END IF;
    END IF;
    
    -- المحاولة 3: من companies عبر user_profiles
    IF v_user_id IS NOT NULL THEN
        SELECT c.tenant_id INTO v_tenant_id
        FROM companies c
        JOIN user_profiles up ON up.company_id = c.id
        WHERE up.id = v_user_id
        LIMIT 1;
    END IF;
    
    RETURN v_tenant_id;
EXCEPTION
    WHEN OTHERS THEN
        RETURN NULL;
END;
$$;


