--
-- Name: get_current_user_tenant_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_current_user_tenant_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    cached text;
BEGIN
    -- Try transaction-local cache first
    BEGIN
      cached := current_setting('app.current_tenant_id', true);
      IF cached IS NOT NULL AND cached <> '' THEN
        RETURN cached::UUID;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;

    -- البحث عن tenant_id من user_profiles
    SELECT tenant_id INTO v_tenant_id
    FROM user_profiles
    WHERE id = auth.uid()
    LIMIT 1;
    
    -- إذا لم يوجد، تحقق من user_metadata
    IF v_tenant_id IS NULL THEN
        SELECT (raw_user_meta_data->>'tenant_id')::UUID INTO v_tenant_id
        FROM auth.users
        WHERE id = auth.uid();
    END IF;
    
    -- Cache the result
    IF v_tenant_id IS NOT NULL THEN
      PERFORM set_config('app.current_tenant_id', v_tenant_id::text, true);
    END IF;
    
    RETURN v_tenant_id;
END;
$$;


