--
-- Name: get_customer_price(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_customer_price(p_product_id uuid, p_qty numeric DEFAULT 1, p_customer_id uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_store uuid; v_base numeric := 0;
  v_qty_disc numeric := 0; v_cust_disc numeric := 0;
BEGIN
  SELECT ep.store_id,
         COALESCE(ep.base_price, fm.selling_price, 0)
    INTO v_store, v_base
  FROM ecommerce_products ep
  LEFT JOIN fabric_materials fm ON fm.id = ep.material_id
  WHERE ep.id = p_product_id;

  IF v_base IS NULL OR v_base = 0 THEN RETURN 0; END IF;

  SELECT COALESCE(MAX(discount_percent), 0) INTO v_qty_disc
  FROM ecommerce_quantity_tiers
  WHERE store_id = v_store AND is_active
    AND p_qty >= min_qty AND (max_qty IS NULL OR p_qty <= max_qty);

  IF p_customer_id IS NOT NULL THEN
    SELECT COALESCE(discount_percent, 0) INTO v_cust_disc
    FROM ecommerce_customers WHERE id = p_customer_id;
  END IF;

  RETURN round(v_base * (1 - v_qty_disc/100.0) * (1 - COALESCE(v_cust_disc,0)/100.0), 2);
END $$;


