--
-- Name: get_customer_statement(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_customer_statement(p_customer_id uuid, p_limit integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_company uuid; v_name text; v_balance numeric; v_currency text; v_lines jsonb;
BEGIN
    SELECT company_id, COALESCE(NULLIF(name_ar,''), NULLIF(company_name,''), name_en)
      INTO v_company, v_name FROM customers WHERE id = p_customer_id;
    IF v_company IS NULL THEN RETURN jsonb_build_object('ok', false, 'message', 'العميل غير موجود'); END IF;
    IF auth.uid() IS NOT NULL THEN PERFORM assert_can_access_company(v_company); END IF;

    -- الرصيد الحقيقي من الأستاذ (مدين-دائن) بالعملة الأساس — لا customers.balance
    SELECT COALESCE(SUM(jel.debit - jel.credit), 0) INTO v_balance
      FROM journal_entry_lines jel
      JOIN journal_entries je ON je.id = jel.entry_id
      WHERE jel.party_id = p_customer_id AND jel.party_type = 'customer'
        AND COALESCE(je.is_posted, false) = true;

    BEGIN SELECT default_currency INTO v_currency FROM companies WHERE id = v_company; EXCEPTION WHEN OTHERS THEN v_currency := ''; END;

    SELECT jsonb_agg(row_to_json(t)) INTO v_lines FROM (
        SELECT je.entry_date::date AS date,
               COALESCE(je.entry_number, '') AS ref,
               COALESCE(NULLIF(jel.description,''), NULLIF(je.description,''), '') AS descr,
               COALESCE(jel.debit, 0)  AS debit,
               COALESCE(jel.credit, 0) AS credit
        FROM journal_entry_lines jel
        JOIN journal_entries je ON je.id = jel.entry_id
        WHERE jel.party_id = p_customer_id AND jel.party_type = 'customer'
          AND COALESCE(je.is_posted, false) = true
        ORDER BY je.entry_date DESC, je.created_at DESC
        LIMIT GREATEST(p_limit, 1)
    ) t;

    RETURN jsonb_build_object(
        'ok', true, 'name', v_name, 'balance', round(v_balance, 2),
        'currency', COALESCE(v_currency, ''), 'lines', COALESCE(v_lines, '[]'::jsonb)
    );
END $$;


--
-- Name: get_daily_stats(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_daily_stats(p_tenant_id uuid DEFAULT NULL::uuid, target_date date DEFAULT CURRENT_DATE) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result json;
  v_tenant_id UUID;
BEGIN
  -- Resolve tenant_id: parameter > official helper > NULL
  v_tenant_id := COALESCE(p_tenant_id, get_user_tenant_id());

  SELECT json_build_object(
    'total_entries', COUNT(*),
    'posted_entries', COUNT(CASE WHEN status = 'posted' THEN 1 END),
    'draft_entries', COUNT(CASE WHEN status = 'draft' THEN 1 END),
    'total_debit', COALESCE(SUM(total_debit), 0),
    'total_credit', COALESCE(SUM(total_credit), 0),
    'journal_count', COUNT(CASE WHEN entry_type = 'journal' THEN 1 END),
    'receipt_count', COUNT(CASE WHEN entry_type = 'receipt' THEN 1 END),
    'payment_count', COUNT(CASE WHEN entry_type = 'payment' THEN 1 END),
    'cash_count', COUNT(CASE WHEN entry_type = 'cash' THEN 1 END),
    'total_receipts', COALESCE(SUM(CASE WHEN entry_type = 'receipt' THEN total_credit END), 0),
    'total_payments', COALESCE(SUM(CASE WHEN entry_type = 'payment' THEN total_debit END), 0),
    'report_date', target_date,
    'tenant_id', v_tenant_id
  ) INTO result
  FROM journal_entries
  WHERE entry_date = target_date
    AND deleted_at IS NULL
    AND (v_tenant_id IS NULL OR tenant_id = v_tenant_id);
  
  RETURN result;
END;
$$;


--
-- Name: get_dashboard_attention_items(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_dashboard_attention_items(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(item), '[]'::jsonb) INTO v_result
  FROM (
      SELECT jsonb_build_object(
        'id', 'unposted_' || id,
        'title', 'قيد لم يرحل: ' || reference_number,
        'description', 'أنشئ بتاريخ ' || to_char(created_at, 'YYYY/MM/DD'),
        'type', 'warning',
        'badge', 'مراجعة',
        'action', '/accounting/journal-entries/' || id
      ) as item
      FROM journal_entries
      WHERE company_id = p_company_id AND is_posted = false
      ORDER BY created_at DESC
      LIMIT 4
  ) sub;
  
  RETURN v_result;
END;
$$;


--
-- Name: get_dashboard_cash_flow(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_dashboard_cash_flow(p_company_id uuid, p_base_currency text, p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH dates AS (
    SELECT generate_series(CURRENT_DATE - (p_days - 1) * INTERVAL '1 day', CURRENT_DATE, '1 day'::interval)::date as d
  ),
  daily_flow AS (
    SELECT 
      je.entry_date,
      SUM(CASE WHEN jel.debit > 0 THEN jel.debit ELSE 0 END) as inflow,
      SUM(CASE WHEN jel.credit > 0 THEN jel.credit ELSE 0 END) as outflow
    FROM journal_entries je
    JOIN journal_entry_lines jel ON jel.entry_id = je.id
    JOIN chart_of_accounts a ON a.id = jel.account_id AND a.tenant_id = je.tenant_id
    WHERE je.company_id = p_company_id 
      AND je.is_posted = true 
      AND je.entry_date >= CURRENT_DATE - (p_days - 1) * INTERVAL '1 day'
      AND a.account_code LIKE '11%' -- cash and banks
    GROUP BY je.entry_date
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'date', to_char(d.d, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'income', COALESCE(df.inflow, 0),
      'expense', COALESCE(df.outflow, 0)
    ) ORDER BY d.d
  ), '[]'::jsonb)
  INTO v_result
  FROM dates d
  LEFT JOIN daily_flow df ON df.entry_date = d.d;

  RETURN v_result;
END;
$$;


--
-- Name: get_dashboard_currency_exposure(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_dashboard_currency_exposure(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result jsonb;
  v_base_currency text;
  v_cash_parent_code text;
BEGIN
  SELECT base_currency INTO v_base_currency
  FROM company_accounting_settings
  WHERE company_id = p_company_id;

  -- Find the parent account for cash & banks dynamically
  SELECT account_code INTO v_cash_parent_code
  FROM chart_of_accounts
  WHERE company_id = p_company_id
    AND is_detail = false
    AND (
      name_ar LIKE '%أموال جاهزة%'
      OR name_ar LIKE '%الأموال الجاهزة%'
      OR name_ar LIKE '%النقد%'
      OR name_ar LIKE '%صندوق%'
      OR account_code IN ('18', '11')
    )
    AND LENGTH(account_code) <= 2
  ORDER BY
    CASE
      WHEN name_ar LIKE '%أموال جاهزة%' THEN 1
      WHEN name_ar LIKE '%النقد%' THEN 2
      WHEN account_code = '18' THEN 3
      WHEN account_code = '11' THEN 4
      ELSE 5
    END
  LIMIT 1;

  IF v_cash_parent_code IS NULL THEN
    v_cash_parent_code := '18';
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'accountCode', a.account_code,
      'accountName', a.name_ar,
      'currency', COALESCE(a.currency, v_base_currency),
      'balance', COALESCE(bal.balance, 0)
    ) ORDER BY a.account_code
  ), '[]'::jsonb)
  INTO v_result
  FROM chart_of_accounts a
  LEFT JOIN (
    SELECT
      jel.account_id,
      SUM(jel.debit - jel.credit) as balance
    FROM journal_entry_lines jel
    JOIN journal_entries je ON je.id = jel.entry_id
    WHERE je.company_id = p_company_id
      AND je.is_posted = true
    GROUP BY jel.account_id
  ) bal ON bal.account_id = a.id
  WHERE a.company_id = p_company_id
    AND a.account_code LIKE v_cash_parent_code || '%'
    AND a.is_detail = true;

  RETURN v_result;
END;
$$;


--
-- Name: get_dashboard_kpis(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_dashboard_kpis(p_company_id uuid, p_base_currency text DEFAULT 'USD'::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_result JSONB;
  v_live_inventory_val NUMERIC := 0;
BEGIN
    -- Query the physical live inventory safely honoring RLS and Live Deductions automatically
    SELECT COALESCE(SUM(s.quantity_on_hand * COALESCE(NULLIF(s.average_cost, 0), m.purchase_price)), 0)
    INTO v_live_inventory_val
    FROM inventory_stock s
    JOIN fabric_materials m ON s.material_id = m.id
    WHERE s.company_id = p_company_id;

    WITH categories(category, label) AS (
        VALUES 
            ('cash', 'النقد والبنوك'), 
            ('receivables', 'الذمم المدينة'), 
            ('payables', 'الذمم الدائنة'), 
            ('inventory', 'قيمة المخزون')
    ),
    calendar AS (
        SELECT 
            dt::DATE as dt, 
            cat.category 
        FROM generate_series(CURRENT_DATE - INTERVAL '6 days', CURRENT_DATE, '1 day'::interval) dt
        CROSS JOIN categories cat
    ),
    category_daily_movements AS (
        SELECT 
            CASE
                WHEN a.account_code LIKE '111%' OR a.account_code LIKE '112%' THEN 'cash'
                WHEN a.account_code LIKE '113%' THEN 'receivables'
                WHEN a.account_code LIKE '211%' OR a.account_code LIKE '21%' THEN 'payables'
                WHEN a.account_code LIKE '114%' THEN 'inventory'
            END AS category,
            je.entry_date::DATE as entry_date,
            SUM(
                CASE 
                    WHEN a.account_code LIKE '211%' OR a.account_code LIKE '21%' THEN jel.credit - jel.debit
                    ELSE jel.debit - jel.credit
                END
            ) AS net_movement
        FROM journal_entry_lines jel
        JOIN journal_entries je ON je.id = jel.entry_id
        JOIN chart_of_accounts a ON a.id = jel.account_id
        WHERE je.company_id = p_company_id
          AND je.is_posted = true
          AND (a.account_code LIKE '111%' OR a.account_code LIKE '112%' OR a.account_code LIKE '113%' OR a.account_code LIKE '21%' OR a.account_code LIKE '114%')
        GROUP BY 1, 2
    ),
    sparkline_data AS (
        SELECT 
            c.category,
            c.dt,
            COALESCE((
                SELECT SUM(net_movement) 
                FROM category_daily_movements m 
                WHERE m.category = c.category AND m.entry_date <= c.dt
            ), 0) AS balance
        FROM calendar c
    ),
    sparklines_agg AS (
        SELECT 
            category,
            jsonb_agg(balance ORDER BY dt ASC) AS sparkline,
            MAX(CASE WHEN dt = CURRENT_DATE THEN balance ELSE 0 END) AS current_balance,
            MAX(CASE WHEN dt = CURRENT_DATE - INTERVAL '6 days' THEN balance ELSE 0 END) AS past_balance
        FROM sparkline_data
        GROUP BY category
    ),
    currency_balances AS (
        SELECT 
            CASE
                WHEN a.account_code LIKE '111%' OR a.account_code LIKE '112%' THEN 'cash'
                WHEN a.account_code LIKE '113%' THEN 'receivables'
                WHEN a.account_code LIKE '211%' OR a.account_code LIKE '21%' THEN 'payables'
                WHEN a.account_code LIKE '114%' THEN 'inventory'
            END AS category,
            COALESCE(a.currency, p_base_currency) AS currency_code,
            SUM(
                CASE 
                    WHEN a.account_code LIKE '211%' OR a.account_code LIKE '21%' THEN jel.credit - jel.debit
                    ELSE jel.debit - jel.credit
                END
            ) AS balance
        FROM journal_entry_lines jel
        JOIN journal_entries je ON je.id = jel.entry_id
        JOIN chart_of_accounts a ON a.id = jel.account_id
        WHERE je.company_id = p_company_id
          AND je.is_posted = true
          AND je.entry_date <= CURRENT_DATE
          AND (a.account_code LIKE '111%' OR a.account_code LIKE '112%' OR a.account_code LIKE '113%' OR a.account_code LIKE '21%' OR a.account_code LIKE '114%')
        GROUP BY 1, 2
    ),
    category_totals AS (
        SELECT category, SUM(balance) as total_balance
        FROM currency_balances
        GROUP BY category
    ),
    breakdown_agg AS (
        SELECT 
            cb.category,
            jsonb_agg(
                jsonb_build_object(
                    'key', cb.currency_code,
                    'label', cb.currency_code,
                    'pct', CASE WHEN ct.total_balance > 0 THEN ROUND((cb.balance / ct.total_balance * 100)::numeric, 1) ELSE 0 END
                ) ORDER BY cb.balance DESC
            ) AS breakdown
        FROM currency_balances cb
        JOIN category_totals ct ON cb.category = ct.category
        WHERE cb.balance > 0
        GROUP BY cb.category
    ),
    final_output AS (
        SELECT 
            s.category,
            jsonb_build_object(
                'id', s.category,
                'label', c.label,
                -- Override Inventory strictly with live physical value mapping
                'value', CASE WHEN s.category = 'inventory' THEN v_live_inventory_val ELSE COALESCE(s.current_balance, 0) END,
                'currency', p_base_currency,
                'deltaPct7d', 
                    CASE 
                        WHEN COALESCE(s.past_balance, 0) = 0 THEN 0
                        ELSE ROUND((( (CASE WHEN s.category = 'inventory' THEN v_live_inventory_val ELSE COALESCE(s.current_balance, 0) END) - s.past_balance) / NULLIF(ABS(s.past_balance), 0) * 100)::numeric, 1)
                    END,
                'sparkline', COALESCE(s.sparkline, '[]'::jsonb),
                'breakdown', COALESCE(b.breakdown, '[]'::jsonb)
            ) AS kpi_json
        FROM sparklines_agg s
        JOIN categories c ON c.category = s.category
        LEFT JOIN breakdown_agg b ON s.category = b.category
        ORDER BY 
            CASE s.category 
                WHEN 'cash' THEN 1 
                WHEN 'receivables' THEN 2 
                WHEN 'payables' THEN 3 
                WHEN 'inventory' THEN 4 
            END
    )
    SELECT jsonb_agg(kpi_json) INTO v_result FROM final_output;
    
    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


--
-- Name: get_dashboard_net_position(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_dashboard_net_position(p_company_id uuid, p_base_currency text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  -- We calculate Assets (1) and Liabilities (2) for the last 7 days cumulatively
  WITH dates AS (
    SELECT generate_series(CURRENT_DATE - INTERVAL '6 days', CURRENT_DATE, '1 day'::interval)::date as d
  ),
  daily_movements AS (
    SELECT 
      d.d as activity_date,
      a.account_code,
      jel.debit - jel.credit as net_amount_base
    FROM dates d
    LEFT JOIN journal_entries je ON je.company_id = p_company_id AND je.is_posted = true AND je.entry_date <= d.d
    LEFT JOIN journal_entry_lines jel ON jel.entry_id = je.id
    LEFT JOIN chart_of_accounts a ON a.id = jel.account_id AND a.tenant_id = je.tenant_id
    WHERE a.account_code LIKE '1%' OR a.account_code LIKE '2%'
  ),
  daily_totals AS (
    SELECT 
      activity_date,
      SUM(CASE WHEN account_code LIKE '1%' THEN net_amount_base ELSE 0 END) as total_assets,
      SUM(CASE WHEN account_code LIKE '2%' THEN -net_amount_base ELSE 0 END) as total_liabilities
    FROM daily_movements
    GROUP BY activity_date
  ),
  net_positions AS (
    SELECT 
      activity_date,
      COALESCE(total_assets - total_liabilities, 0) as net_position
    FROM daily_totals
    ORDER BY activity_date
  )
  SELECT jsonb_build_object(
    'valueBase', COALESCE((SELECT net_position FROM net_positions WHERE activity_date = CURRENT_DATE), 0),
    'baseCurrency', p_base_currency,
    'deltaPct7d', CASE 
      WHEN (SELECT net_position FROM net_positions WHERE activity_date = CURRENT_DATE - INTERVAL '6 days') = 0 THEN 0
      ELSE ROUND((((SELECT net_position FROM net_positions WHERE activity_date = CURRENT_DATE) - (SELECT net_position FROM net_positions WHERE activity_date = CURRENT_DATE - INTERVAL '6 days')) / ABS(NULLIF((SELECT net_position FROM net_positions WHERE activity_date = CURRENT_DATE - INTERVAL '6 days'), 0)) * 100)::numeric, 1)
    END,
    'deltaAbs7d', COALESCE((SELECT net_position FROM net_positions WHERE activity_date = CURRENT_DATE), 0) - COALESCE((SELECT net_position FROM net_positions WHERE activity_date = CURRENT_DATE - INTERVAL '6 days'), 0),
    'sparkline', COALESCE((SELECT jsonb_agg(net_position ORDER BY activity_date) FROM net_positions), '[]'::jsonb),
    'todayMovement', COALESCE((SELECT net_position FROM net_positions WHERE activity_date = CURRENT_DATE), 0) - COALESCE((SELECT net_position FROM net_positions WHERE activity_date = CURRENT_DATE - INTERVAL '1 day'), 0),
    'todayTxCount', COALESCE((SELECT COUNT(*) FROM journal_entries WHERE company_id = p_company_id AND is_posted = true AND entry_date = CURRENT_DATE), 0)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_dashboard_recent_activity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_dashboard_recent_activity(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', je.id,
      'title', 'قيد محاسبي: ' || je.reference_number,
      'user', COALESCE(u.full_name, 'النظام'),
      'timestamp', to_char(je.created_at, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'type', 'journal',
      'amount', je.total_debit
    ) ORDER BY je.created_at DESC
  ), '[]'::jsonb)
  INTO v_result
  FROM journal_entries je
  LEFT JOIN user_profiles u ON u.id = je.created_by
  WHERE je.company_id = p_company_id
  LIMIT 6;

  RETURN v_result;
END;
$$;


--
-- Name: get_dashboard_top_customers(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_dashboard_top_customers(p_company_id uuid, p_base_currency text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH cust_balances AS (
    SELECT 
      c.id,
      c.name_ar,
      SUM(jel.debit - jel.credit) as outstanding
    FROM customers c
    JOIN journal_entry_lines jel ON jel.account_id = c.receivable_account_id
    JOIN journal_entries je ON je.id = jel.entry_id
    WHERE je.company_id = p_company_id 
      AND je.is_posted = true
      AND je.status = 'posted'
    GROUP BY c.id, c.name_ar
    HAVING SUM(jel.debit - jel.credit) > 0
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', id,
      'name', name_ar,
      'outstanding', outstanding,
      'currency', p_base_currency,
      'daysOverdue', 0
    ) ORDER BY outstanding DESC
  ), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT * FROM cust_balances ORDER BY outstanding DESC LIMIT 5
  ) sub;

  RETURN v_result;
END;
$$;


--
-- Name: get_dashboard_top_suppliers(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_dashboard_top_suppliers(p_company_id uuid, p_base_currency text DEFAULT 'USD'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', sub.id,
      'name', sub.name,
      'outstanding', sub.outstanding,
      'currency', p_base_currency
    ) ORDER BY sub.outstanding DESC
  ), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      s.id,
      COALESCE(s.name_ar, s.name_en, 'مورد') as name,
      COALESCE(
        (SELECT SUM(jel.debit - jel.credit)
         FROM journal_entry_lines jel
         JOIN journal_entries je ON je.id = jel.entry_id
         WHERE jel.account_id = s.payable_account_id
           AND je.company_id = p_company_id
           AND je.is_posted = true),
        0
      ) as outstanding
    FROM suppliers s
    WHERE s.company_id = p_company_id
    ORDER BY outstanding DESC
    LIMIT 10
  ) sub
  WHERE sub.outstanding <> 0;

  RETURN v_result;
END;
$$;


--
-- Name: get_ecommerce_fx(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_ecommerce_fx(p_store_id uuid) RETURNS TABLE(base_currency text, quote_currency text, buy_rate numeric, margin_percent numeric, uah_per_usd numeric, rate_effective_from timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    WITH st AS (
        SELECT COALESCE(fx_margin_percent, 2) AS margin FROM ecommerce_stores WHERE id = p_store_id
    ),
    r AS (
        -- store's own active USD↔UAH rate (either direction)
        SELECT er.buy_rate, er.sell_rate, er.margin_percent, er.effective_from
        FROM ecommerce_currency_rates er
        WHERE er.store_id = p_store_id
          AND ((er.from_currency='USD' AND er.to_currency='UAH')
            OR (er.from_currency='UAH' AND er.to_currency='USD'))
          AND COALESCE(er.is_active, true)
          AND er.buy_rate > 0
          AND (er.effective_to IS NULL OR er.effective_to > now())
        ORDER BY er.effective_from DESC
        LIMIT 1
    ),
    n AS (
        -- Retail UAH per USD from the BUY leg. The sheet bakes the margin so the
        -- buy leg (lower USD-per-UAH) inverts to a HIGHER UAH-per-USD = market +
        -- margin. Normalized: a value < 1 is technical (USD-per-UAH) → invert.
        SELECT CASE WHEN r.buy_rate < 1 THEN 1.0 / r.buy_rate ELSE r.buy_rate END AS uah_per_usd_base,
               CASE WHEN r.buy_rate < 1 THEN 1.0 / r.buy_rate ELSE r.buy_rate END AS buy_disp,
               r.margin_percent, r.effective_from
        FROM r
    )
    SELECT 'USD'::text, 'UAH'::text,
           n.buy_disp,
           COALESCE(n.margin_percent, st.margin),
           n.uah_per_usd_base,                 -- NULL when no manual rate → storefront uses live source
           COALESCE(n.effective_from, now())
    FROM st LEFT JOIN n ON true;
$$;


--
-- Name: get_ecommerce_products(uuid, text, text, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_ecommerce_products(p_store_id uuid, p_category_slug text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_featured_only boolean DEFAULT false, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, material_id uuid, marketing_title jsonb, marketing_description jsonb, short_description jsonb, gallery_images text[], seo_slug text, tags text[], is_featured boolean, is_new boolean, is_bestseller boolean, is_on_sale boolean, sale_price numeric, sale_unit text, min_order_quantity numeric, view_count integer, order_count integer, published_at timestamp with time zone, material_code text, material_name_ar text, material_name_en text, unit_price numeric, material_image text, effective_price numeric, category_slugs text[])
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ep.id,
        ep.material_id,
        ep.marketing_title,
        ep.marketing_description,
        ep.short_description,
        ep.gallery_images,
        ep.seo_slug,
        ep.tags,
        ep.is_featured,
        ep.is_new,
        ep.is_bestseller,
        ep.is_on_sale,
        ep.sale_price,
        ep.sale_unit,
        ep.min_order_quantity,
        ep.view_count,
        ep.order_count,
        ep.published_at,
        -- Live from fabric_materials
        fm.code AS material_code,
        fm.name_ar AS material_name_ar,
        fm.name_en AS material_name_en,
        fm.unit_price,
        fm.image_url AS material_image,
        -- Effective price: sale_price if on sale, otherwise unit_price
        COALESCE(
            CASE WHEN ep.is_on_sale AND ep.sale_price IS NOT NULL 
                 AND (ep.sale_start_date IS NULL OR ep.sale_start_date <= now())
                 AND (ep.sale_end_date IS NULL OR ep.sale_end_date >= now())
            THEN ep.sale_price 
            ELSE NULL END,
            fm.unit_price
        ) AS effective_price,
        -- Category slugs
        ARRAY(
            SELECT ec.slug FROM ecommerce_product_categories epc
            JOIN ecommerce_categories ec ON ec.id = epc.category_id
            WHERE epc.product_id = ep.id
        ) AS category_slugs
    FROM ecommerce_products ep
    JOIN fabric_materials fm ON fm.id = ep.material_id
    WHERE ep.store_id = p_store_id
      AND ep.is_published = true
      AND (p_featured_only = false OR ep.is_featured = true)
      AND (p_search IS NULL OR (
          fm.name_ar ILIKE '%' || p_search || '%' OR
          fm.name_en ILIKE '%' || p_search || '%' OR
          fm.code ILIKE '%' || p_search || '%' OR
          ep.marketing_title::text ILIKE '%' || p_search || '%' OR
          p_search = ANY(ep.tags)
      ))
      AND (p_category_slug IS NULL OR EXISTS (
          SELECT 1 FROM ecommerce_product_categories epc
          JOIN ecommerce_categories ec ON ec.id = epc.category_id
          WHERE epc.product_id = ep.id AND ec.slug = p_category_slug
      ))
    ORDER BY ep.display_order ASC, ep.published_at DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: get_employee_commission_report(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_employee_commission_report(p_company_id uuid, p_from_date date, p_to_date date, p_employee_id uuid DEFAULT NULL::uuid) RETURNS TABLE(employee_id uuid, employee_name character varying, total_sales numeric, total_commission numeric, total_bonus numeric, net_commission numeric, invoice_count integer, avg_commission_rate numeric, status_summary jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ec.employee_id,
        'موظف'::VARCHAR as employee_name, -- يمكن ربطه بجدول الموظفين
        COALESCE(SUM(ec.base_amount), 0)::DECIMAL(15,2) as total_sales,
        COALESCE(SUM(ec.commission_amount), 0)::DECIMAL(15,2) as total_commission,
        COALESCE(SUM(ec.bonus_amount), 0)::DECIMAL(15,2) as total_bonus,
        COALESCE(SUM(ec.net_amount), 0)::DECIMAL(15,2) as net_commission,
        COUNT(DISTINCT ec.source_id)::INT as invoice_count,
        CASE 
            WHEN SUM(ec.base_amount) > 0 
            THEN (SUM(ec.commission_amount) / SUM(ec.base_amount) * 100)::DECIMAL(10,4)
            ELSE 0 
        END as avg_commission_rate,
        jsonb_build_object(
            'calculated', COUNT(*) FILTER (WHERE ec.status = 'calculated'),
            'approved', COUNT(*) FILTER (WHERE ec.status = 'approved'),
            'paid', COUNT(*) FILTER (WHERE ec.status = 'paid'),
            'cancelled', COUNT(*) FILTER (WHERE ec.status = 'cancelled')
        ) as status_summary
    FROM employee_commissions ec
    WHERE ec.company_id = p_company_id
      AND ec.period_start >= p_from_date
      AND ec.period_end <= p_to_date
      AND (p_employee_id IS NULL OR ec.employee_id = p_employee_id)
    GROUP BY ec.employee_id
    ORDER BY net_commission DESC;
END;
$$;


