--
-- Name: get_fund_balances(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_fund_balances(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result json;
  v_tenant_id UUID;
BEGIN
  v_tenant_id := COALESCE(p_tenant_id, get_user_tenant_id());

  SELECT COALESCE(json_agg(row_data), '[]'::json) INTO result
  FROM (
    SELECT json_build_object(
      'code', a.code,
      'name', COALESCE(a.name_ar, a.name_en),
      'balance', COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0)
    ) as row_data
    FROM accounts a
    JOIN journal_entry_lines jl ON jl.account_id = a.id
    JOIN journal_entries je ON je.id = jl.journal_entry_id
    WHERE a.account_type IN ('cash', 'bank')
      AND je.status = 'posted'
      AND je.deleted_at IS NULL
      AND (v_tenant_id IS NULL OR je.tenant_id = v_tenant_id)
      AND (v_tenant_id IS NULL OR a.tenant_id = v_tenant_id)
    GROUP BY a.id, a.code, a.name_ar, a.name_en
    HAVING COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0) != 0
    ORDER BY COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0) DESC
    LIMIT 10
  ) sub;
  
  RETURN result;
END;
$$;


--
-- Name: get_guest_orders(uuid, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_guest_orders(p_tenant_id uuid, p_email character varying, p_session_id character varying DEFAULT NULL::character varying) RETURNS TABLE(order_id uuid, order_number character varying, total_amount numeric, currency character varying, status character varying, payment_status character varying, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        o.id as order_id,
        o.order_number,
        o.total_amount,
        o.currency,
        o.status,
        o.payment_status,
        o.created_at
    FROM orders o
    INNER JOIN guest_checkouts gc ON gc.id = o.guest_checkout_id
    WHERE o.tenant_id = p_tenant_id
      AND gc.email = p_email
      AND (p_session_id IS NULL OR gc.session_id = p_session_id)
    ORDER BY o.created_at DESC;
END;
$$;


--
-- Name: get_import_entity_definition(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_import_entity_definition(p_entity_type character varying) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_definition JSONB;
BEGIN
    SELECT jsonb_build_object(
        'entity_type', entity_type,
        'target_table', target_table,
        'display_name_ar', display_name_ar,
        'display_name_en', display_name_en,
        'icon', icon,
        'fields', fields,
        'required_fields', required_fields,
        'unique_fields', unique_fields,
        'lookup_fields', lookup_fields
    ) INTO v_definition
    FROM import_entity_definitions
    WHERE entity_type = p_entity_type AND is_active = true;
    
    RETURN v_definition;
END;
$$;


--
-- Name: get_income_statement(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_income_statement(p_company_id uuid, p_from_date date, p_to_date date) RETURNS TABLE(category character varying, category_ar character varying, account_id uuid, account_code character varying, account_name_ar character varying, account_name_en character varying, amount numeric, is_subtotal boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH income_data AS (
        SELECT 
            coa.id as account_id,
            coa.account_code,
            coa.name_ar as account_name_ar,
            coa.name_en as account_name_en,
            at.classification,
            at.code as type_code,
            COALESCE(SUM(jel.credit - jel.debit), 0) as net_amount
        FROM chart_of_accounts coa
        JOIN account_types at ON coa.account_type_id = at.id
        LEFT JOIN journal_entry_lines jel ON coa.id = jel.account_id
        LEFT JOIN journal_entries je ON jel.entry_id = je.id 
            AND je.is_posted = true
            AND je.entry_date BETWEEN p_from_date AND p_to_date
        WHERE coa.company_id = p_company_id
          AND coa.is_active = true
          AND coa.is_detail = true
          AND at.classification IN ('income', 'expenses')
        GROUP BY coa.id, coa.account_code, coa.name_ar, coa.name_en, at.classification, at.code
        HAVING COALESCE(SUM(jel.credit - jel.debit), 0) != 0
    )
    -- الإيرادات
    SELECT 
        'revenue'::VARCHAR(50) as category,
        'الإيرادات'::VARCHAR(100) as category_ar,
        id.account_id,
        id.account_code,
        id.account_name_ar,
        id.account_name_en,
        id.net_amount as amount,
        false as is_subtotal
    FROM income_data id
    WHERE id.classification = 'income'
    
    UNION ALL
    
    -- إجمالي الإيرادات
    SELECT 
        'revenue_total'::VARCHAR(50),
        'إجمالي الإيرادات'::VARCHAR(100),
        NULL::UUID,
        ''::VARCHAR(50),
        'إجمالي الإيرادات'::VARCHAR(200),
        'Total Revenue'::VARCHAR(200),
        COALESCE(SUM(net_amount), 0),
        true
    FROM income_data
    WHERE classification = 'income'
    
    UNION ALL
    
    -- المصروفات
    SELECT 
        'expenses'::VARCHAR(50),
        'المصروفات'::VARCHAR(100),
        id.account_id,
        id.account_code,
        id.account_name_ar,
        id.account_name_en,
        ABS(id.net_amount),
        false
    FROM income_data id
    WHERE id.classification = 'expenses'
    
    UNION ALL
    
    -- إجمالي المصروفات
    SELECT 
        'expenses_total'::VARCHAR(50),
        'إجمالي المصروفات'::VARCHAR(100),
        NULL::UUID,
        ''::VARCHAR(50),
        'إجمالي المصروفات'::VARCHAR(200),
        'Total Expenses'::VARCHAR(200),
        COALESCE(ABS(SUM(net_amount)), 0),
        true
    FROM income_data
    WHERE classification = 'expenses'
    
    UNION ALL
    
    -- صافي الربح/الخسارة
    SELECT 
        'net_income'::VARCHAR(50),
        'صافي الربح/الخسارة'::VARCHAR(100),
        NULL::UUID,
        ''::VARCHAR(50),
        CASE 
            WHEN COALESCE(SUM(CASE WHEN classification = 'income' THEN net_amount ELSE -net_amount END), 0) >= 0 
            THEN 'صافي الربح'::VARCHAR(200)
            ELSE 'صافي الخسارة'::VARCHAR(200)
        END,
        CASE 
            WHEN COALESCE(SUM(CASE WHEN classification = 'income' THEN net_amount ELSE -net_amount END), 0) >= 0 
            THEN 'Net Profit'::VARCHAR(200)
            ELSE 'Net Loss'::VARCHAR(200)
        END,
        COALESCE(SUM(CASE WHEN classification = 'income' THEN net_amount ELSE -net_amount END), 0),
        true
    FROM income_data
    
    ORDER BY 
        CASE category 
            WHEN 'revenue' THEN 1 
            WHEN 'revenue_total' THEN 2
            WHEN 'expenses' THEN 3 
            WHEN 'expenses_total' THEN 4
            WHEN 'net_income' THEN 5
        END,
        account_code;
END;
$$;


