-- Name: FUNCTION get_income_statement(p_company_id uuid, p_from_date date, p_to_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_income_statement(p_company_id uuid, p_from_date date, p_to_date date) IS 'قائمة الدخل - الإيرادات والمصروفات وصافي الربح/الخسارة';


--
-- Name: get_low_stock_materials(uuid, uuid[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_low_stock_materials(p_company uuid, p_warehouse_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 15) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_rows jsonb;
BEGIN
    IF auth.uid() IS NOT NULL THEN PERFORM assert_can_access_company(p_company); END IF;
    SELECT jsonb_agg(row_to_json(t)) INTO v_rows FROM (
        SELECT x.name, x.unit, x.reorder, x.qty FROM (
            SELECT COALESCE(NULLIF(m.name_ar,''), NULLIF(m.name_en,''), m.code) AS name,
                   COALESCE(m.unit,'') AS unit,
                   COALESCE(m.reorder_point, m.min_stock_level, m.min_stock, 0) AS reorder,
                   COALESCE((SELECT SUM(COALESCE(s.quantity_on_hand, 0)) FROM inventory_stock s
                             WHERE s.material_id = m.id
                               AND (p_warehouse_ids IS NULL OR s.warehouse_id = ANY(p_warehouse_ids))), 0) AS qty
            FROM fabric_materials m
            WHERE m.company_id = p_company
              AND COALESCE(m.reorder_point, m.min_stock_level, m.min_stock, 0) > 0
        ) x
        WHERE x.qty < x.reorder
        ORDER BY (x.reorder - x.qty) DESC
        LIMIT GREATEST(p_limit, 1)
    ) t;
    RETURN jsonb_build_object('ok', true, 'items', COALESCE(v_rows, '[]'::jsonb));
END $$;


--
-- Name: get_manager_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_manager_dashboard(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_cash numeric; v_recv numeric; v_pay numeric; v_today numeric; v_low int; v_pending int; v_cur text;
BEGIN
    IF auth.uid() IS NOT NULL THEN PERFORM assert_can_access_company(p_company); END IF;

    SELECT round(COALESCE(SUM(jel.debit - jel.credit), 0), 2) INTO v_cash
      FROM journal_entry_lines jel
      JOIN journal_entries je ON je.id = jel.entry_id
      JOIN chart_of_accounts coa ON coa.id = jel.account_id
      WHERE je.company_id = p_company AND COALESCE(je.is_posted, false)
        AND (COALESCE(coa.is_cash_account,false) OR COALESCE(coa.is_bank_account,false));

    SELECT round(COALESCE(SUM(balance), 0), 2) INTO v_recv FROM customers WHERE company_id = p_company AND balance > 0;
    SELECT round(COALESCE(SUM(balance), 0), 2) INTO v_pay  FROM suppliers WHERE company_id = p_company AND balance > 0;

    SELECT round(COALESCE(SUM(total_amount), 0), 2) INTO v_today FROM sales_transactions
      WHERE company_id = p_company AND created_at::date = CURRENT_DATE
        AND COALESCE(stage,'') NOT IN ('draft','quotation','cancelled');

    SELECT count(*) INTO v_pending FROM pending_actions WHERE company_id = p_company AND status = 'pending';

    SELECT count(*) INTO v_low FROM fabric_materials m
      WHERE m.company_id = p_company
        AND COALESCE(m.reorder_point, m.min_stock_level, m.min_stock, 0) > 0
        AND COALESCE((SELECT SUM(quantity_on_hand) FROM inventory_stock s WHERE s.material_id = m.id), 0)
            < COALESCE(m.reorder_point, m.min_stock_level, m.min_stock, 0);

    BEGIN SELECT default_currency INTO v_cur FROM companies WHERE id = p_company; EXCEPTION WHEN OTHERS THEN v_cur := ''; END;

    RETURN jsonb_build_object('ok', true, 'cash', v_cash, 'receivables', v_recv, 'payables', v_pay,
        'today_sales', v_today, 'pending', v_pending, 'low_stock', v_low, 'currency', COALESCE(v_cur,''));
END $$;


--
-- Name: get_material_inventory_stats_batch(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_material_inventory_stats_batch(material_ids uuid[]) RETURNS TABLE(material_id uuid, rolls_count bigint, rolls_total_length numeric, reserved_length numeric, available_length numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        fr.material_id,
        COUNT(fr.id)::BIGINT as rolls_count,
        COALESCE(SUM(fr.current_length), 0)::DECIMAL(15,3) as rolls_total_length,
        COALESCE(SUM(fr.reserved_length), 0)::DECIMAL(15,3) as reserved_length,
        COALESCE(SUM(fr.available_length), 0)::DECIMAL(15,3) as available_length
    FROM 
        fabric_rolls fr
    WHERE 
        fr.material_id = ANY(material_ids)
        AND fr.status != 'consumed'
        AND fr.current_length > 0
    GROUP BY 
        fr.material_id;
END;
$$;


--
-- Name: get_material_specs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_material_specs(p_material_id uuid) RETURNS TABLE(composition text, weight_per_meter numeric, default_width numeric, season text, usage_type text, origin_country text, category text)
