  SELECT composition, weight_per_meter, default_width, season, usage_type, origin_country, category
  FROM fabric_materials
  WHERE id = p_material_id;
$$;


--
-- Name: get_material_stock(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_material_stock(p_material_id uuid, p_warehouse_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_company uuid; v_name text; v_unit text; v_total numeric; v_roll boolean;
    v_cost numeric; v_price numeric; v_cur text; v_reorder numeric; v_wh jsonb; v_rolls int;
BEGIN
    SELECT company_id, COALESCE(NULLIF(name_ar,''), NULLIF(name_en,''), code), COALESCE(unit,''),
           COALESCE(is_roll_tracked, false),
           COALESCE(avg_cost_per_unit, 0), COALESCE(selling_price, 0), COALESCE(currency,''),
           COALESCE(reorder_point, min_stock_level, min_stock, 0)
      INTO v_company, v_name, v_unit, v_roll, v_cost, v_price, v_cur, v_reorder
      FROM fabric_materials WHERE id = p_material_id;
    IF v_company IS NULL THEN RETURN jsonb_build_object('ok', false, 'message', 'المادة غير موجودة'); END IF;
    IF auth.uid() IS NOT NULL THEN PERFORM assert_can_access_company(v_company); END IF;

    -- Authoritative on-hand total from inventory_stock (the fabric_materials.total_stock
    -- field is stale for some rows), scoped to the accessible warehouses.
    SELECT COALESCE(SUM(COALESCE(s.quantity_on_hand, 0)), 0) INTO v_total
      FROM inventory_stock s
      WHERE s.material_id = p_material_id
        AND (p_warehouse_ids IS NULL OR s.warehouse_id = ANY(p_warehouse_ids));

    SELECT jsonb_agg(row_to_json(t)) INTO v_wh FROM (
        SELECT COALESCE(w.name, '—') AS warehouse, SUM(COALESCE(s.quantity_on_hand, 0)) AS qty
        FROM inventory_stock s
        LEFT JOIN warehouses w ON w.id = s.warehouse_id
        WHERE s.material_id = p_material_id
          AND (p_warehouse_ids IS NULL OR s.warehouse_id = ANY(p_warehouse_ids))
        GROUP BY w.name
        HAVING SUM(COALESCE(s.quantity_on_hand, 0)) <> 0
        ORDER BY 2 DESC
    ) t;

    SELECT count(*) INTO v_rolls FROM fabric_rolls r
      WHERE r.material_id = p_material_id
        AND COALESCE(r.available_length, r.current_length, 0) > 0
        AND (p_warehouse_ids IS NULL OR r.warehouse_id = ANY(p_warehouse_ids));

    RETURN jsonb_build_object(
        'ok', true, 'name', v_name, 'unit', v_unit, 'total', v_total, 'is_roll', v_roll,
        'cost', v_cost, 'price', v_price, 'currency', v_cur, 'reorder', v_reorder,
        'warehouses', COALESCE(v_wh, '[]'::jsonb), 'roll_count', v_rolls
    );
END $$;


--
-- Name: get_material_unit_conversions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_material_unit_conversions(p_material_id uuid) RETURNS TABLE(id uuid, from_unit_id uuid, from_unit_code character varying, from_unit_name_ar character varying, from_unit_name_en character varying, from_unit_symbol character varying, to_unit_id uuid, to_unit_code character varying, to_unit_name_ar character varying, to_unit_name_en character varying, to_unit_symbol character varying, conversion_factor numeric, weight_per_unit numeric, contains_quantity numeric, volume_cbm numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        muc.id,
        muc.from_unit_id,
        fu.code AS from_unit_code,
        fu.name_ar AS from_unit_name_ar,
        fu.name_en AS from_unit_name_en,
        fu.symbol AS from_unit_symbol,
        muc.to_unit_id,
        tu.code AS to_unit_code,
        tu.name_ar AS to_unit_name_ar,
        tu.name_en AS to_unit_name_en,
        tu.symbol AS to_unit_symbol,
        muc.conversion_factor,
        muc.weight_per_unit,
        muc.contains_quantity,
        muc.volume_cbm
    FROM public.material_unit_conversions muc
    JOIN public.units_of_measure fu ON fu.id = muc.from_unit_id
    JOIN public.units_of_measure tu ON tu.id = muc.to_unit_id
    WHERE muc.material_id = p_material_id
    AND muc.is_active = true
    ORDER BY muc.created_at;
END;
$$;


--
-- Name: get_mfa_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_mfa_status(p_user_id uuid DEFAULT auth.uid()) RETURNS TABLE(service_enabled boolean, is_required boolean, user_enabled boolean, can_enable boolean, preferred_method text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COALESCE(ss.is_enabled, false),
        is_mfa_required(p_user_id),
        COALESCE(us.is_enabled, false),
        COALESCE(ss.is_enabled, false),
        COALESCE(us.preferred_method, 'totp')::TEXT
    FROM mfa_system_settings ss
    LEFT JOIN mfa_user_settings us ON us.user_id = p_user_id
    LIMIT 1;
EXCEPTION
    WHEN OTHERS THEN
        -- Return default values if error
        RETURN QUERY SELECT false, false, false, false, 'totp'::TEXT;
END;
$$;


--
-- Name: get_modules_by_product(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_modules_by_product(p_product_code character varying) RETURNS TABLE(code character varying, name_en character varying, name_ar character varying, category character varying, price_monthly numeric, is_core boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        sm.code,
        sm.name_en,
        sm.name_ar,
        sm.category,
        sm.price_monthly,
        sm.is_core
    FROM system_modules sm
    WHERE sm.is_active = true
    AND (
        '*' = ANY(sm.available_in_products)
        OR p_product_code = ANY(sm.available_in_products)
    )
    ORDER BY sm.display_order;
END;
$$;


--
-- Name: get_monthly_expenses(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_monthly_expenses(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result json;
  v_tenant_id UUID;
BEGIN
  v_tenant_id := COALESCE(p_tenant_id, get_user_tenant_id());

  SELECT json_build_object(
    'count', COUNT(*),
    'total', COALESCE(SUM(total_debit), 0)
  ) INTO result
  FROM journal_entries
  WHERE entry_type = 'payment'
    AND entry_date >= date_trunc('month', CURRENT_DATE)
    AND deleted_at IS NULL 
    AND status = 'posted'
    AND (v_tenant_id IS NULL OR tenant_id = v_tenant_id);
  
  RETURN result;
END;
$$;


--
-- Name: get_monthly_revenue(integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_monthly_revenue(p_months integer DEFAULT 12, p_currency character varying DEFAULT 'USD'::character varying) RETURNS TABLE(month character varying, revenue numeric, payment_count integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        TO_CHAR(collection_date, 'YYYY-MM') as month,
        SUM(amount) as revenue,
        COUNT(*)::INT as payment_count
    FROM saas_payments
    WHERE status = 'completed'
    AND currency = p_currency
    AND collection_date >= NOW() - (p_months || ' months')::INTERVAL
    GROUP BY TO_CHAR(collection_date, 'YYYY-MM')
    ORDER BY month;
END;
$$;


--
-- Name: get_monthly_sales(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_monthly_sales(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result json;
  v_tenant_id UUID;
BEGIN
  v_tenant_id := COALESCE(p_tenant_id, get_user_tenant_id());

  SELECT json_build_object(
    'count', COUNT(*),
    'total', COALESCE(SUM(total_credit), 0)
  ) INTO result
  FROM journal_entries
  WHERE entry_type = 'receipt'
    AND entry_date >= date_trunc('month', CURRENT_DATE)
    AND deleted_at IS NULL 
    AND status = 'posted'
    AND (v_tenant_id IS NULL OR tenant_id = v_tenant_id);
  
  RETURN result;
END;
$$;


--
-- Name: get_monthly_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_monthly_summary(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result json;
  v_tenant_id UUID;
BEGIN
  v_tenant_id := COALESCE(p_tenant_id, get_user_tenant_id());

  SELECT json_build_object(
    'total_entries', COUNT(*),
    'posted', COUNT(CASE WHEN status = 'posted' THEN 1 END),
    'draft', COUNT(CASE WHEN status = 'draft' THEN 1 END),
    'total_debit', COALESCE(SUM(total_debit), 0),
    'total_credit', COALESCE(SUM(total_credit), 0),
    'month_start', date_trunc('month', CURRENT_DATE)::date,
    'tenant_id', v_tenant_id
  ) INTO result
  FROM journal_entries
  WHERE entry_date >= date_trunc('month', CURRENT_DATE)
    AND deleted_at IS NULL
    AND (v_tenant_id IS NULL OR tenant_id = v_tenant_id);
  
  RETURN result;
END;
$$;


--
-- Name: get_multi_currency_balances(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_multi_currency_balances(p_company_id uuid) RETURNS TABLE(account_id uuid, currency character varying, net_balance numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    -- إرجاع أرصدة مُقسّمة بالعملة لأي حساب يستقبل قيود بأكثر من عملة
    SELECT jel.account_id, 
           COALESCE(je.currency, 'USD')::VARCHAR as currency,
           SUM(COALESCE(jel.debit, 0) - COALESCE(jel.credit, 0)) as net_balance
    FROM journal_entry_lines jel
    JOIN journal_entries je ON je.id = jel.entry_id
    JOIN chart_of_accounts coa ON coa.id = jel.account_id
    WHERE coa.company_id = p_company_id
      AND je.status = 'posted'
      -- كشف تلقائي: الحسابات التي لها قيود بأكثر من عملة
      AND jel.account_id IN (
          SELECT jel2.account_id 
          FROM journal_entry_lines jel2
          JOIN journal_entries je2 ON je2.id = jel2.entry_id
          JOIN chart_of_accounts coa2 ON coa2.id = jel2.account_id
          WHERE coa2.company_id = p_company_id
            AND je2.status = 'posted'
          GROUP BY jel2.account_id
          HAVING COUNT(DISTINCT COALESCE(je2.currency, 'USD')) > 1
      )
    GROUP BY jel.account_id, COALESCE(je.currency, 'USD');
$$;


--
-- Name: get_my_active_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_my_active_sessions() RETURNS TABLE(session_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone, ip text, user_agent text, aal text, factor_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- تنظيف الجلسات المنتهية (أكثر من 7 أيام)
    DELETE FROM auth.sessions s2
    WHERE s2.user_id = auth.uid() 
    AND s2.updated_at < NOW() - INTERVAL '7 days';

    RETURN QUERY
    SELECT 
        s.id,
        s.created_at,
        s.updated_at,
        s.ip::text,
        s.user_agent,
        s.aal::text,
        s.factor_id
    FROM auth.sessions s
    WHERE s.user_id = auth.uid()
    AND s.updated_at > NOW() - INTERVAL '24 hours'
    ORDER BY s.updated_at DESC;
END;
$$;


