--
-- Name: get_my_hr(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_my_hr(p_user uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_emp uuid; v_name text; v_company uuid; v_leave numeric; v_pay jsonb;
BEGIN
    p_user := COALESCE(auth.uid(), p_user);   -- المستخدم لا يستعلم عن غيره
    SELECT id, COALESCE(NULLIF(full_name_ar,''), NULLIF(full_name_en,''), employee_number), company_id
      INTO v_emp, v_name, v_company FROM employees WHERE user_profile_id = p_user LIMIT 1;
    IF v_emp IS NULL THEN RETURN jsonb_build_object('ok', true, 'is_employee', false); END IF;
    IF auth.uid() IS NOT NULL THEN PERFORM assert_can_access_company(v_company); END IF;
    SELECT COALESCE(SUM(remaining_days), 0) INTO v_leave FROM leave_balances
      WHERE employee_id = v_emp AND year = EXTRACT(YEAR FROM CURRENT_DATE)::int;
    SELECT to_jsonb(p) INTO v_pay FROM (
        SELECT net_salary, currency, status, paid_at FROM payroll_entries WHERE employee_id = v_emp ORDER BY created_at DESC LIMIT 1
    ) p;
    RETURN jsonb_build_object('ok', true, 'is_employee', true, 'name', v_name, 'leave_remaining', v_leave, 'last_payslip', v_pay);
END $$;


--
-- Name: get_my_login_history(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_my_login_history(p_limit integer DEFAULT 20) RETURNS TABLE(session_id uuid, login_at timestamp with time zone, last_active timestamp with time zone, ip text, user_agent text, aal text, is_mfa boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    SELECT 
        s.id as session_id,
        s.created_at as login_at,
        s.updated_at as last_active,
        s.ip::text,
        s.user_agent,
        s.aal::text,
        (s.aal::text = 'aal2') as is_mfa
    FROM auth.sessions s
    WHERE s.user_id = auth.uid()
    ORDER BY s.created_at DESC
    LIMIT p_limit;
$$;


--
-- Name: get_my_trusted_devices(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_my_trusted_devices() RETURNS TABLE(device_id uuid, device_name text, ip_address text, trusted_until timestamp with time zone, created_at timestamp with time zone, last_used_at timestamp with time zone, last_ip text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    SELECT id, device_name, 
           COALESCE(last_ip, ip_address) as ip_address,
           trusted_until, created_at, last_used_at, last_ip
    FROM trusted_devices
    WHERE user_id = auth.uid()
    AND trusted_until > NOW()
    ORDER BY last_used_at DESC NULLS LAST;
$$;


--
-- Name: get_or_create_cart(uuid, uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_or_create_cart(p_tenant_id uuid, p_company_id uuid, p_customer_id uuid DEFAULT NULL::uuid, p_session_id character varying DEFAULT NULL::character varying) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_cart_id UUID;
BEGIN
    -- البحث عن سلة نشطة موجودة
    IF p_customer_id IS NOT NULL THEN
        SELECT id INTO v_cart_id
        FROM shopping_carts
        WHERE tenant_id = p_tenant_id
          AND customer_id = p_customer_id
          AND status = 'active'
        LIMIT 1;
    ELSIF p_session_id IS NOT NULL THEN
        SELECT id INTO v_cart_id
        FROM shopping_carts
        WHERE tenant_id = p_tenant_id
          AND session_id = p_session_id
          AND status = 'active'
        LIMIT 1;
    END IF;
    
    -- إنشاء سلة جديدة إذا لم توجد
    IF v_cart_id IS NULL THEN
        INSERT INTO shopping_carts (
            tenant_id,
            company_id,
            customer_id,
            session_id,
            status,
            expires_at
        )
        VALUES (
            p_tenant_id,
            p_company_id,
            p_customer_id,
            p_session_id,
            'active',
            NOW() + INTERVAL '30 days'
        )
        RETURNING id INTO v_cart_id;
    END IF;
    
    RETURN v_cart_id;
END;
$$;


--
-- Name: get_order_details(uuid, uuid, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_order_details(p_tenant_id uuid, p_order_id uuid, p_guest_email character varying DEFAULT NULL::character varying, p_session_id character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_order RECORD;
    v_items JSONB;
    v_customer JSONB;
    v_guest JSONB;
    v_result JSONB;
    v_uid  uuid := auth.uid();
    v_role text := auth.role();
    v_authorized boolean := false;
BEGIN
    -- الحصول على الطلب (مقصور على المستأجر)
    SELECT * INTO v_order
    FROM orders
    WHERE id = p_order_id
      AND tenant_id = p_tenant_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'الطلب غير موجود');
    END IF;

    -- ── بوّابة الملكية (قبل إرجاع أي PII) ──
    IF v_role = 'service_role' OR v_role IS NULL THEN
        -- 1) خلفية موثوقة (لا anon)
        v_authorized := true;
    ELSIF v_uid IS NOT NULL AND (
            is_super_admin(v_uid)
            OR is_tenant_admin(v_uid)
            OR is_company_admin(v_uid, v_order.company_id)
         ) THEN
        -- 2) موظّف/أدمن المستأجر
        v_authorized := true;
    ELSIF v_order.customer_id IS NOT NULL AND v_uid IS NOT NULL AND (
            EXISTS (SELECT 1 FROM ecommerce_customers ec
                    WHERE ec.user_id = v_uid AND ec.customer_id = v_order.customer_id)
            OR get_customer_id_from_auth(v_uid) = v_order.customer_id
         ) THEN
        -- 3) عميل مُسجَّل يملك الطلب
        v_authorized := true;
    ELSIF v_order.guest_checkout_id IS NOT NULL
          AND NULLIF(btrim(p_guest_email), '') IS NOT NULL THEN
        -- 4) زائر يُثبت الملكية ببريده (+ الجلسة اختيارياً)
        IF EXISTS (
            SELECT 1 FROM guest_checkouts gc
            WHERE gc.id = v_order.guest_checkout_id
              AND lower(gc.email) = lower(btrim(p_guest_email))
              AND (p_session_id IS NULL OR gc.session_id = p_session_id)
        ) THEN
            v_authorized := true;
        END IF;
    END IF;

    IF NOT v_authorized THEN
        -- رفض دون تسريب وجود الطلب أو أي PII
        RETURN jsonb_build_object('success', false, 'error', 'الطلب غير موجود');
    END IF;

    -- ── (من هنا: المنطق الأصلي بلا تغيير) ──
    -- عناصر الطلب
    SELECT jsonb_agg(
        jsonb_build_object(
            'product_id', oi.product_id,
            'product_name', oi.product_name,
            'product_sku', oi.product_sku,
            'product_image_url', oi.product_image_url,
            'quantity', oi.quantity,
            'unit_price', oi.unit_price,
            'total_price', oi.total_price
        )
    ) INTO v_items
    FROM order_items oi
    WHERE oi.order_id = p_order_id;

    -- معلومات العميل أو الزائر
    IF v_order.customer_id IS NOT NULL THEN
        SELECT jsonb_build_object(
            'type', 'customer',
            'id', c.id,
            'code', c.code,
            'full_name', c.full_name,
            'email', c.email,
            'phone', c.phone
        ) INTO v_customer
        FROM customers c
        WHERE c.id = v_order.customer_id;
    ELSIF v_order.guest_checkout_id IS NOT NULL THEN
        SELECT jsonb_build_object(
            'type', 'guest',
            'email', gc.email,
            'full_name', gc.full_name,
            'phone', gc.phone,
            'shipping_address', gc.shipping_address,
            'billing_address', gc.billing_address
        ) INTO v_guest
        FROM guest_checkouts gc
        WHERE gc.id = v_order.guest_checkout_id;
    END IF;

    v_result := jsonb_build_object(
        'success', true,
        'order', jsonb_build_object(
            'id', v_order.id,
            'order_number', v_order.order_number,
            'subtotal', v_order.subtotal,
            'discount_amount', v_order.discount_amount,
            'tax_amount', v_order.tax_amount,
            'shipping_amount', v_order.shipping_amount,
            'total_amount', v_order.total_amount,
            'currency', v_order.currency,
            'status', v_order.status,
            'payment_status', v_order.payment_status,
            'payment_method', v_order.payment_method,
            'shipping_method', v_order.shipping_method,
            'tracking_number', v_order.tracking_number,
            'customer_notes', v_order.customer_notes,
            'created_at', v_order.created_at,
            'items', COALESCE(v_items, '[]'::jsonb),
            'customer', COALESCE(v_customer, v_guest, '{}'::jsonb)
        )
    );

    RETURN v_result;
END;
$$;


--
-- Name: get_partner_allowed_brand_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_partner_allowed_brand_ids(p_user_id uuid DEFAULT auth.uid()) RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_partner_id UUID;
    v_brand_ids UUID[];
BEGIN
    -- Platform Owner يرى كل البراندات
    IF is_platform_owner(p_user_id) THEN
        SELECT ARRAY_AGG(id)
        INTO v_brand_ids
        FROM public.saas_products
        WHERE is_active = true;
        RETURN COALESCE(v_brand_ids, ARRAY[]::UUID[]);
    END IF;
    
    -- الحصول على partner_id
    SELECT p.id INTO v_partner_id
    FROM public.partners p
    JOIN public.user_profiles up ON up.email = p.email
    WHERE up.id = p_user_id
      AND p.is_active = true;
    
    IF v_partner_id IS NULL THEN
        -- ليس وكيلاً، إرجاع البراند الخاص به فقط
        RETURN ARRAY[get_user_brand_id(p_user_id)]::UUID[];
    END IF;
    
    -- الحصول على البراندات المسموح للوكيل بيعها
    SELECT ARRAY_AGG(pap.product_id)
    INTO v_brand_ids
    FROM public.partner_allowed_products pap
    WHERE pap.partner_id = v_partner_id
      AND pap.can_sell = true;
    
    -- إذا لم يكن هناك تحديد (backwards compatibility)، إرجاع كل البراندات
    IF v_brand_ids IS NULL OR array_length(v_brand_ids, 1) IS NULL THEN
        SELECT ARRAY_AGG(id)
        INTO v_brand_ids
        FROM public.saas_products
        WHERE is_active = true;
    END IF;
    
    RETURN COALESCE(v_brand_ids, ARRAY[]::UUID[]);
EXCEPTION WHEN OTHERS THEN
    RETURN ARRAY[]::UUID[];
END;
$$;


--
-- Name: get_partner_tenant_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_partner_tenant_ids(p_user_id uuid DEFAULT auth.uid()) RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_partner_id UUID;
    v_allowed_brands UUID[];
    v_tenant_ids UUID[];
BEGIN
    -- الحصول على partner_id
    SELECT p.id INTO v_partner_id
    FROM public.partners p
    JOIN public.user_profiles up ON up.email = p.email
    WHERE up.id = p_user_id
      AND p.is_active = true;
    
    IF v_partner_id IS NULL THEN
        RETURN ARRAY[]::UUID[];
    END IF;
    
    -- الحصول على البراندات المسموح للوكيل بيعها
    v_allowed_brands := get_partner_allowed_brand_ids(p_user_id);
    
    -- الحصول على جميع التينانتات التي أنشأها الوكيل ضمن البراندات المسموح بها
    SELECT ARRAY_AGG(t.id)
    INTO v_tenant_ids
    FROM public.tenants t
    WHERE t.partner_id = v_partner_id
      AND t.status = 'active'
      AND (t.product_id = ANY(v_allowed_brands) OR t.product_id IS NULL);
    
    RETURN COALESCE(v_tenant_ids, ARRAY[]::UUID[]);
EXCEPTION WHEN OTHERS THEN
    RETURN ARRAY[]::UUID[];
END;
$$;


--
-- Name: get_party_balance(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_party_balance(p_company_id uuid, p_party_type text, p_party_id uuid) RETURNS TABLE(party_id uuid, total_debit numeric, total_credit numeric, balance numeric, transaction_count bigint, last_transaction_date date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
WITH party_account AS (
    SELECT payable_account_id AS account_id
    FROM suppliers
    WHERE id = p_party_id AND company_id = p_company_id AND p_party_type = 'supplier'
    UNION ALL
    SELECT receivable_account_id AS account_id
    FROM customers
    WHERE id = p_party_id AND company_id = p_company_id AND p_party_type = 'customer'
    LIMIT 1
),
posted_lines AS (
    SELECT jel.debit, jel.credit, je.entry_date
    FROM journal_entry_lines jel
    INNER JOIN journal_entries je
        ON je.id        = jel.entry_id
       AND je.company_id = p_company_id
       AND je.is_posted  = true
       AND je.status     = 'posted'
    WHERE jel.account_id = (SELECT account_id FROM party_account)
)
SELECT
    p_party_id::UUID,
    COALESCE(SUM(debit),  0)::NUMERIC  AS total_debit,
    COALESCE(SUM(credit), 0)::NUMERIC  AS total_credit,
    CASE
        WHEN p_party_type = 'supplier'
            THEN (COALESCE(SUM(credit), 0) - COALESCE(SUM(debit), 0))::NUMERIC
        ELSE
            (COALESCE(SUM(debit), 0) - COALESCE(SUM(credit), 0))::NUMERIC
    END AS balance,
    COUNT(*)::BIGINT     AS transaction_count,
    MAX(entry_date)::DATE AS last_transaction_date
FROM posted_lines;
$$;


--
-- Name: get_party_balance(character varying, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_party_balance(p_party_type character varying, p_party_id uuid, p_company_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_total_debit  NUMERIC(15,4) := 0;
    v_total_credit NUMERIC(15,4) := 0;
    v_balance      NUMERIC(15,4);
BEGIN
    SELECT 
        COALESCE(SUM(jel.debit), 0),
        COALESCE(SUM(jel.credit), 0)
    INTO v_total_debit, v_total_credit
    FROM journal_entry_lines jel
    JOIN journal_entries je ON je.id = jel.entry_id
    WHERE jel.party_type = p_party_type
      AND jel.party_id = p_party_id
      AND je.is_posted = true
      AND (p_company_id IS NULL OR je.company_id = p_company_id);
    
    v_balance := v_total_debit - v_total_credit;
    
    RETURN jsonb_build_object(
        'party_type', p_party_type,
        'party_id', p_party_id,
        'total_debit', v_total_debit,
        'total_credit', v_total_credit,
        'balance', v_balance,
        'balance_label', CASE 
            WHEN p_party_type = 'supplier' THEN 
                CASE WHEN v_balance < 0 THEN 'مستحق للمورد' ELSE 'رصيد لصالحنا' END
            ELSE
                CASE WHEN v_balance > 0 THEN 'مستحق لنا' ELSE 'رصيد لصالح العميل' END
        END
    );
END;
$$;


--
-- Name: get_party_balances_bulk(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_party_balances_bulk(p_company_id uuid, p_party_type text) RETURNS TABLE(party_id uuid, total_debit numeric, total_credit numeric, balance numeric, total_debit_fc numeric, total_credit_fc numeric, balance_fc numeric, transaction_count bigint, last_transaction_date date)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
WITH party_accounts AS (
    SELECT id AS party_id, payable_account_id AS account_id
    FROM suppliers
    WHERE company_id = p_company_id AND p_party_type = 'supplier' AND payable_account_id IS NOT NULL
    UNION ALL
    SELECT id AS party_id, receivable_account_id AS account_id
    FROM customers
    WHERE company_id = p_company_id AND p_party_type = 'customer' AND receivable_account_id IS NOT NULL
),
posted_lines AS (
    SELECT jel.account_id,
           jel.debit AS raw_debit, jel.credit AS raw_credit,
           CASE
               WHEN jel.debit_fc IS NOT NULL AND (jel.debit_fc > 0 OR jel.debit = 0) THEN jel.debit_fc
               WHEN COALESCE(jel.exchange_rate, 1) > 1 THEN jel.debit / jel.exchange_rate
               ELSE jel.debit
           END AS fc_debit,
           CASE
               WHEN jel.credit_fc IS NOT NULL AND (jel.credit_fc > 0 OR jel.credit = 0) THEN jel.credit_fc
               WHEN COALESCE(jel.exchange_rate, 1) > 1 THEN jel.credit / jel.exchange_rate
               ELSE jel.credit
           END AS fc_credit,
           je.entry_date
    FROM journal_entry_lines jel
    INNER JOIN journal_entries je ON je.id = jel.entry_id
       AND je.company_id = p_company_id AND je.is_posted = true AND je.status = 'posted'
)
SELECT
    pa.party_id::UUID,
    COALESCE(SUM(pl.raw_debit), 0)::NUMERIC AS total_debit,
    COALESCE(SUM(pl.raw_credit), 0)::NUMERIC AS total_credit,
    CASE WHEN p_party_type = 'supplier'
        THEN (COALESCE(SUM(pl.raw_credit), 0) - COALESCE(SUM(pl.raw_debit), 0))::NUMERIC
        ELSE (COALESCE(SUM(pl.raw_debit), 0) - COALESCE(SUM(pl.raw_credit), 0))::NUMERIC
    END AS balance,
    COALESCE(SUM(pl.fc_debit), 0)::NUMERIC AS total_debit_fc,
    COALESCE(SUM(pl.fc_credit), 0)::NUMERIC AS total_credit_fc,
    CASE WHEN p_party_type = 'supplier'
        THEN (COALESCE(SUM(pl.fc_credit), 0) - COALESCE(SUM(pl.fc_debit), 0))::NUMERIC
        ELSE (COALESCE(SUM(pl.fc_debit), 0) - COALESCE(SUM(pl.fc_credit), 0))::NUMERIC
    END AS balance_fc,
    COUNT(pl.raw_debit)::BIGINT AS transaction_count,
    MAX(pl.entry_date)::DATE AS last_transaction_date
FROM party_accounts pa
LEFT JOIN posted_lines pl ON pl.account_id = pa.account_id
GROUP BY pa.party_id;
$$;


--
-- Name: get_pending_action_fund(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_pending_action_fund(p_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_company uuid; v_fund uuid;
BEGIN
    SELECT company_id, NULLIF(action_data->>'fund_account_id','')::uuid
      INTO v_company, v_fund FROM pending_actions WHERE id = p_id;
    IF v_company IS NULL THEN RETURN NULL; END IF;
    IF auth.uid() IS NOT NULL THEN PERFORM assert_can_access_company(v_company); END IF;
    IF v_fund IS NOT NULL THEN
        PERFORM 1 FROM chart_of_accounts
          WHERE id = v_fund AND company_id = v_company
            AND (COALESCE(is_cash_account,false) OR COALESCE(is_bank_account,false));
        IF NOT FOUND THEN
            v_fund := NULL;
        ELSIF auth.uid() IS NOT NULL AND NOT public.can_access_fund(v_fund, auth.uid()) THEN
            v_fund := NULL;   -- 🔒 المُؤكِّد لا يملك الصندوق → الواجهة تختار صندوقه
        END IF;
    END IF;
    RETURN v_fund;
END $$;


--
-- Name: get_pending_recurring_entries(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_pending_recurring_entries(p_company_id uuid DEFAULT NULL::uuid) RETURNS TABLE(history_id uuid, recurring_entry_id uuid, entry_name character varying, scheduled_date date, amount numeric, approval_status character varying, days_pending integer, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        reh.id as history_id,
        reh.recurring_entry_id,
        re.name_ar as entry_name,
        reh.scheduled_date,
        reh.amount,
        reh.approval_status,
        (CURRENT_DATE - reh.scheduled_date)::INTEGER as days_pending,
        reh.created_at
    FROM recurring_entry_history reh
    JOIN recurring_entries re ON reh.recurring_entry_id = re.id
    WHERE reh.approval_status = 'pending'
      AND reh.status = 'pending'
      AND (p_company_id IS NULL OR re.company_id = p_company_id)
    ORDER BY reh.scheduled_date ASC;
END;
$$;


--
-- Name: get_plan_modules(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_plan_modules(p_plan_id uuid) RETURNS TABLE(module_id uuid, module_code character varying, module_name_en character varying, module_name_ar character varying, module_icon character varying, is_enabled boolean, is_core boolean, is_active boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        pm.module_id,
        sm.code,
        sm.name_en,
        sm.name_ar,
        sm.icon,
        pm.is_enabled,
        pm.is_core,
        sm.is_active
    FROM plan_modules pm
    JOIN system_modules sm ON pm.module_id = sm.id
    WHERE pm.plan_id = p_plan_id
    ORDER BY pm.display_order, sm.display_order;
END;
$$;


--
-- Name: get_plan_pricing(character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_plan_pricing(p_plan_code character varying, p_billing_cycle character varying DEFAULT 'monthly'::character varying, p_free_months integer DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_plan RECORD;
    v_discount RECORD;
    v_original_price DECIMAL(10,2);
    v_monthly_after_promo DECIMAL(10,2);
    v_final_price DECIMAL(10,2);
    v_yearly_months_paid INT;
    v_promo_discount INT := 0;
BEGIN
    -- 1. الحصول على الباقة
    SELECT * INTO v_plan
    FROM subscription_plans
    WHERE code = p_plan_code AND is_active = true;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'plan_not_found',
            'message', 'الباقة غير موجودة'
        );
    END IF;
    
    -- 2. الحصول على الخصم الموسمي النشط
    SELECT * INTO v_discount
    FROM promotional_discounts
    WHERE is_active = true
      AND auto_apply = true
      AND NOW() BETWEEN valid_from AND valid_to
      AND (
          applies_to = 'both'
          OR applies_to = p_billing_cycle
      )
      AND (
          applicable_plans = '[]'::jsonb
          OR applicable_plans @> to_jsonb(ARRAY[p_plan_code])
      )
    ORDER BY priority DESC, discount_percentage DESC
    LIMIT 1;
    
    -- 3. حساب السعر حسب نوع الاشتراك
    IF p_billing_cycle = 'monthly' THEN
        -- ═══ شهري ═══
        v_original_price := v_plan.price_monthly;
        
        -- تطبيق الخصم الموسمي
        IF v_discount IS NOT NULL THEN
            v_promo_discount := v_discount.discount_percentage;
            v_monthly_after_promo := v_original_price * (1 - v_promo_discount::DECIMAL / 100);
        ELSE
            v_monthly_after_promo := v_original_price;
        END IF;
        
        v_final_price := v_monthly_after_promo;
        
    ELSE
        -- ═══ سنوي ═══
        v_original_price := v_plan.price_yearly; -- شهري × 12
        
        -- تطبيق الخصم الموسمي على الشهري أولاً
        IF v_discount IS NOT NULL THEN
            v_promo_discount := v_discount.discount_percentage;
            v_monthly_after_promo := v_plan.price_monthly * (1 - v_promo_discount::DECIMAL / 100);
        ELSE
            v_monthly_after_promo := v_plan.price_monthly;
        END IF;
        
        -- حساب السنوي مع بونص الأشهر المجانية
        -- مثال: 12 شهر - 2 شهر مجاني = 10 أشهر مدفوعة
        v_yearly_months_paid := 12 - p_free_months;
        v_final_price := v_monthly_after_promo * v_yearly_months_paid;
    END IF;
    
    -- 4. إرجاع النتيجة
    RETURN jsonb_build_object(
        'success', true,
        'plan_code', v_plan.code,
        'plan_name_ar', v_plan.name_ar,
        'plan_name_en', v_plan.name_en,
        'billing_cycle', p_billing_cycle,
        'currency', v_plan.currency,
        
        -- الأسعار
        'original_price', v_original_price,
        'monthly_after_promo', v_monthly_after_promo,
        'final_price', ROUND(v_final_price, 2),
        
        -- التفاصيل
        'promo_discount', v_promo_discount,
        'promo_name_ar', COALESCE(v_discount.name_ar, NULL),
        'promo_name_en', COALESCE(v_discount.name_en, NULL),
        'free_months', CASE WHEN p_billing_cycle = 'yearly' THEN p_free_months ELSE 0 END,
        'months_paid', CASE WHEN p_billing_cycle = 'yearly' THEN v_yearly_months_paid ELSE 1 END,
        
        -- التوفير
        'total_savings', ROUND(v_original_price - v_final_price, 2),
        'savings_percentage', ROUND((v_original_price - v_final_price) / v_original_price * 100, 2)
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'exception',
            'message', SQLERRM
        );
END;
$$;


--
-- Name: get_plans_by_product(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_plans_by_product(p_product_code character varying) RETURNS TABLE(id uuid, code character varying, name_en character varying, name_ar character varying, price_monthly numeric, price_yearly numeric, currency character varying, max_users integer, max_companies integer, is_popular boolean, is_active boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        sp.id,
        sp.code,
        sp.name_en,
        sp.name_ar,
        sp.price_monthly,
        sp.price_yearly,
        sp.currency,
        sp.max_users,
        sp.max_companies,
        sp.is_popular,
        sp.is_active
    FROM subscription_plans sp
    JOIN saas_products prod ON sp.product_id = prod.id
    WHERE prod.code = p_product_code
    AND sp.is_active = true
    ORDER BY sp.display_order;
END;
$$;


--
-- Name: get_product_attributes(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_product_attributes(p_product_ids uuid[]) RETURNS TABLE(product_id uuid, attributes jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        pa.product_id,
        jsonb_object_agg(pa.attribute_key, 
            jsonb_build_object(
                'value', pa.attribute_value,
                'value_num', pa.attribute_value_num
            )
        ) AS attributes
    FROM ecommerce_product_attributes pa
    WHERE pa.product_id = ANY(p_product_ids)
    GROUP BY pa.product_id;
END;
$$;


--
-- Name: get_product_name(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_product_name(p_product_id uuid, p_language character varying DEFAULT 'en'::character varying) RETURNS character varying
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_name VARCHAR;
BEGIN
    EXECUTE format(
        'SELECT COALESCE(name_%s, name_en, name_ar) FROM products WHERE id = $1',
        p_language
    ) INTO v_name USING p_product_id;
    
    RETURN v_name;
EXCEPTION
    WHEN OTHERS THEN
        -- إذا فشل، نرجع name_en أو name_ar
        SELECT COALESCE(name_en, name_ar) INTO v_name FROM products WHERE id = p_product_id;
        RETURN v_name;
END;
$_$;


--
-- Name: get_product_primary_image(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_product_primary_image(p_product_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_primary_image TEXT;
BEGIN
    SELECT img->>'url'
    INTO v_primary_image
    FROM products p,
         jsonb_array_elements(p.images) AS img
    WHERE p.id = p_product_id
      AND (img->>'is_primary')::boolean = true
    LIMIT 1;
    
    -- إذا لم توجد صورة primary، أرجع أول صورة
    IF v_primary_image IS NULL THEN
        SELECT img->>'url'
        INTO v_primary_image
        FROM products p,
             jsonb_array_elements(p.images) AS img
        WHERE p.id = p_product_id
        ORDER BY (img->>'display_order')::int
        LIMIT 1;
    END IF;
    
    RETURN v_primary_image;
END;
$$;


--
-- Name: get_product_review_statistics(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_product_review_statistics(p_tenant_id uuid, p_product_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_stats RECORD;
    v_result JSONB;
BEGIN
    SELECT * INTO v_stats
    FROM product_review_stats
    WHERE tenant_id = p_tenant_id
      AND product_id = p_product_id;
    
    IF NOT FOUND THEN
        -- إذا لم توجد إحصائيات، حسابها الآن
        PERFORM update_product_review_stats(p_tenant_id, p_product_id);
        
        SELECT * INTO v_stats
        FROM product_review_stats
        WHERE tenant_id = p_tenant_id AND product_id = p_product_id;
    END IF;
    
    v_result := jsonb_build_object(
        'total_reviews', COALESCE(v_stats.total_reviews, 0),
        'average_rating', COALESCE(v_stats.average_rating, 0),
        'rating_distribution', jsonb_build_object(
            '5', COALESCE(v_stats.rating_5_count, 0),
            '4', COALESCE(v_stats.rating_4_count, 0),
            '3', COALESCE(v_stats.rating_3_count, 0),
            '2', COALESCE(v_stats.rating_2_count, 0),
            '1', COALESCE(v_stats.rating_1_count, 0)
        ),
        'verified_reviews', jsonb_build_object(
            'count', COALESCE(v_stats.verified_reviews_count, 0),
            'average_rating', COALESCE(v_stats.verified_average_rating, 0)
        )
    );
    
    RETURN v_result;
END;
$$;


--
-- Name: get_product_reviews(uuid, uuid, integer, integer, integer, boolean, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_product_reviews(p_tenant_id uuid, p_product_id uuid, p_limit integer DEFAULT 10, p_offset integer DEFAULT 0, p_rating_filter integer DEFAULT NULL::integer, p_verified_only boolean DEFAULT false, p_sort_by character varying DEFAULT 'recent'::character varying) RETURNS TABLE(review_id uuid, customer_name character varying, rating integer, title character varying, review_text text, images jsonb, is_verified_purchase boolean, helpful_count integer, not_helpful_count integer, seller_response text, seller_response_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        pr.id as review_id,
        COALESCE(c.full_name, 'عميل') as customer_name,
        pr.rating,
        pr.title,
        pr.review_text,
        pr.images,
        pr.is_verified_purchase,
        pr.helpful_count,
        pr.not_helpful_count,
        pr.seller_response,
        pr.seller_response_at,
        pr.created_at
    FROM product_reviews pr
    LEFT JOIN customers c ON c.id = pr.customer_id
    WHERE pr.tenant_id = p_tenant_id
      AND pr.product_id = p_product_id
      AND pr.status = 'approved'
      AND (p_rating_filter IS NULL OR pr.rating = p_rating_filter)
      AND (p_verified_only = false OR pr.is_verified_purchase = true)
    ORDER BY
        CASE WHEN p_sort_by = 'recent' THEN pr.created_at END DESC,
        CASE WHEN p_sort_by = 'helpful' THEN pr.helpful_count END DESC,
        CASE WHEN p_sort_by = 'rating_high' THEN pr.rating END DESC,
        CASE WHEN p_sort_by = 'rating_low' THEN pr.rating END ASC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;


--
-- Name: get_product_stats(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_product_stats(p_product_code character varying) RETURNS TABLE(product_name character varying, total_plans integer, active_plans integer, total_tenants bigint, active_tenants bigint, available_modules bigint)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        prod.name,
        COUNT(DISTINCT sp.id)::INT as total_plans,
        COUNT(DISTINCT CASE WHEN sp.is_active THEN sp.id END)::INT as active_plans,
        COUNT(DISTINCT t.id) as total_tenants,
        COUNT(DISTINCT CASE WHEN t.status = 'active' THEN t.id END) as active_tenants,
        COUNT(DISTINCT sm.code) as available_modules
    FROM saas_products prod
    LEFT JOIN subscription_plans sp ON prod.id = sp.product_id
    LEFT JOIN tenants t ON prod.id = t.product_id
    LEFT JOIN system_modules sm ON (
        '*' = ANY(sm.available_in_products)
        OR prod.code = ANY(sm.available_in_products)
    ) AND sm.is_active = true
    WHERE prod.code = p_product_code
    GROUP BY prod.name;
END;
$$;


--
-- Name: get_products_for_store(uuid, uuid, uuid, uuid, numeric, numeric, boolean, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_products_for_store(p_tenant_id uuid, p_company_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_category_id uuid DEFAULT NULL::uuid, p_min_price numeric DEFAULT NULL::numeric, p_max_price numeric DEFAULT NULL::numeric, p_is_featured boolean DEFAULT NULL::boolean, p_search_term character varying DEFAULT NULL::character varying, p_sort_by character varying DEFAULT 'created_at'::character varying, p_sort_order character varying DEFAULT 'DESC'::character varying, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, sku character varying, barcode character varying, name_ar character varying, name_en character varying, description text, category_id uuid, category_name_ar character varying, brand_id uuid, brand_name character varying, images jsonb, slug character varying, base_price numeric, customer_price numeric, discount_percent numeric, discount_amount numeric, price_source character varying, is_on_sale boolean, stock_status character varying, available_quantity numeric, is_featured boolean, rating numeric, reviews_count integer, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- نسخة بسيطة جداً - ترجع كل المنتجات بدون فلاتر
    RETURN QUERY
    SELECT 
        p.id,
        COALESCE(p.sku, '') as sku,
        COALESCE(p.barcode, '') as barcode,
        COALESCE(p.name_ar, '') as name_ar,
        COALESCE(p.name_en, '') as name_en,
        COALESCE(p.description, '') as description,
        p.category_id,
        NULL::VARCHAR as category_name_ar,
        NULL::UUID as brand_id,
        NULL::VARCHAR as brand_name,
        COALESCE(p.images, '[]'::jsonb) as images,
        COALESCE(p.slug, '') as slug,
        COALESCE(p.default_price, 0) as base_price,
        COALESCE(p.default_price, 0) as customer_price,
        0::DECIMAL as discount_percent,
        0::DECIMAL as discount_amount,
        'base_price'::VARCHAR as price_source,
        false as is_on_sale,
        'in_stock'::VARCHAR as stock_status,
        999999::DECIMAL as available_quantity,
        COALESCE(p.is_featured, false) as is_featured,
        0.0 as rating,
        0 as reviews_count,
        COALESCE(p.created_at, NOW()) as created_at
    FROM products p
    ORDER BY p.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;


--
-- Name: get_promotional_discounts(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_promotional_discounts(p_active_only boolean DEFAULT false) RETURNS TABLE(id uuid, code character varying, name_ar character varying, name_en character varying, discount_percentage integer, valid_from timestamp with time zone, valid_to timestamp with time zone, applicable_plans jsonb, applies_to character varying, is_active boolean, auto_apply boolean, priority integer, is_current boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        pd.id,
        pd.code,
        pd.name_ar,
        pd.name_en,
        pd.discount_percentage,
        pd.valid_from,
        pd.valid_to,
        pd.applicable_plans,
        pd.applies_to,
        pd.is_active,
        pd.auto_apply,
        pd.priority,
        (NOW() BETWEEN pd.valid_from AND pd.valid_to)::BOOLEAN as is_current
    FROM promotional_discounts pd
    WHERE (NOT p_active_only OR pd.is_active = true)
    ORDER BY pd.priority DESC, pd.created_at DESC;
END;
$$;


--
-- Name: get_qr_scan_analytics(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_qr_scan_analytics(p_company_id uuid, p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_from timestamptz := now() - (p_days || ' days')::interval; v_res jsonb;
BEGIN
    IF auth.uid() IS NOT NULL THEN PERFORM assert_can_access_company(p_company_id); END IF;

    SELECT jsonb_build_object(
        'totals', (SELECT jsonb_build_object(
            'scans', count(*),
            'unique_scanners', count(DISTINCT scanner_chat_id),
            'staff', count(*) FILTER (WHERE is_staff),
            'public', count(*) FILTER (WHERE NOT is_staff),
            'mat', count(*) FILTER (WHERE kind='mat'),
            'roll', count(*) FILTER (WHERE kind='roll')
          ) FROM qr_telegram_scans WHERE company_id = p_company_id AND created_at >= v_from),
        'leads', (SELECT count(*) FROM contacts
                  WHERE company_id = p_company_id AND source = 'telegram' AND created_at >= v_from),
        'top_materials', (SELECT COALESCE(jsonb_agg(
            jsonb_build_object('material_id', m.material_id, 'name', m.name, 'scans', m.scans) ORDER BY m.scans DESC
          ), '[]'::jsonb) FROM (
            SELECT s.material_id, COALESCE(fm.name_ar, fm.name_en, '—') AS name, count(*) AS scans
            FROM qr_telegram_scans s LEFT JOIN fabric_materials fm ON fm.id = s.material_id
            WHERE s.company_id = p_company_id AND s.created_at >= v_from
            GROUP BY s.material_id, fm.name_ar, fm.name_en
            ORDER BY count(*) DESC LIMIT 10) m),
        'recent', (SELECT COALESCE(jsonb_agg(
            jsonb_build_object('kind', r.kind, 'material', r.material, 'scanner', r.scanner,
                               'is_staff', r.is_staff, 'at', r.created_at) ORDER BY r.created_at DESC
          ), '[]'::jsonb) FROM (
            SELECT s.kind, COALESCE(fm.name_ar, fm.name_en, '—') AS material,
                   COALESCE(NULLIF(s.scanner_name,''),'—') AS scanner, s.is_staff, s.created_at
            FROM qr_telegram_scans s LEFT JOIN fabric_materials fm ON fm.id = s.material_id
            WHERE s.company_id = p_company_id AND s.created_at >= v_from
            ORDER BY s.created_at DESC LIMIT 40) r),
        'by_day', (SELECT COALESCE(jsonb_agg(
            jsonb_build_object('day', d.day, 'scans', d.scans) ORDER BY d.day
          ), '[]'::jsonb) FROM (
            SELECT to_char(date_trunc('day', created_at), 'YYYY-MM-DD') AS day, count(*) AS scans
            FROM qr_telegram_scans WHERE company_id = p_company_id AND created_at >= v_from
            GROUP BY date_trunc('day', created_at)) d)
    ) INTO v_res;

    RETURN COALESCE(v_res, '{}'::jsonb);
END $$;


--
-- Name: get_remaining_days(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_remaining_days(p_tenant_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_end_date DATE;
    v_days_remaining INT;
BEGIN
    SELECT end_date INTO v_end_date
    FROM tenant_subscriptions
    WHERE tenant_id = p_tenant_id
        AND status = 'active'
    ORDER BY end_date DESC
    LIMIT 1;
    
    IF v_end_date IS NULL THEN
        RETURN 0;
    END IF;
    
    v_days_remaining := v_end_date - CURRENT_DATE;
    RETURN GREATEST(v_days_remaining, 0);
END;
$$;


--
-- Name: get_schema_info(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_schema_info() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  result JSON;
BEGIN
  SELECT json_agg(json_build_object(
    'table', t.table_name,
    'columns', (
      SELECT json_agg(json_build_object(
        'name', c.column_name,
        'type', c.data_type,
        'nullable', c.is_nullable
      ) ORDER BY c.ordinal_position)
      FROM information_schema.columns c
      WHERE c.table_schema = 'public' AND c.table_name = t.table_name
    )
  ) ORDER BY t.table_name)
  INTO result
  FROM information_schema.tables t
  WHERE t.table_schema = 'public' 
    AND t.table_type = 'BASE TABLE'
    AND t.table_name NOT LIKE 'pg_%'
    AND t.table_name NOT LIKE '_%;';
  
  RETURN result;
END;
$$;


--
-- Name: get_sector_attributes(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_sector_attributes(p_sector text, p_store_id uuid DEFAULT NULL::uuid) RETURNS TABLE(attribute_key text, label jsonb, attribute_type text, options jsonb, unit text, is_filterable boolean, display_in_card boolean, display_in_detail boolean, display_order integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ad.attribute_key,
        ad.label,
        ad.attribute_type::TEXT,
        ad.options,
        ad.unit,
        ad.is_filterable,
        ad.display_in_card,
        ad.display_in_detail,
        ad.display_order
    FROM ecommerce_attribute_definitions ad
    WHERE ad.sector = p_sector
      AND (ad.store_id IS NULL OR ad.store_id = p_store_id)
    ORDER BY ad.display_order ASC;
END;
$$;


--
-- Name: get_sector_units(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_sector_units(p_sector text) RETURNS TABLE(unit_key text, label jsonb, short_label jsonb, is_default boolean, conversion_factor numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        su.unit_key,
        su.label,
        su.short_label,
        su.is_default,
        su.conversion_factor
    FROM ecommerce_sale_units su
    WHERE su.sector = p_sector
    ORDER BY su.display_order ASC;
END;
$$;


--
-- Name: get_shipment_items_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_shipment_items_summary(p_shipment_id uuid) RETURNS TABLE(total_items bigint, total_expected_quantity numeric, total_received_quantity numeric, total_reserved_quantity numeric, total_available_quantity numeric, total_goods_value numeric, total_provisional_cost numeric, total_final_cost numeric, unique_suppliers bigint, unique_invoices bigint, unique_materials bigint)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(*)::BIGINT AS total_items,
        COALESCE(SUM(si.expected_quantity), 0)::DECIMAL(15,3) AS total_expected_quantity,
        COALESCE(SUM(si.received_quantity), 0)::DECIMAL(15,3) AS total_received_quantity,
        COALESCE(SUM(si.reserved_quantity), 0)::DECIMAL(15,3) AS total_reserved_quantity,
        COALESCE(SUM(
            COALESCE(si.expected_quantity, 0) - COALESCE(si.reserved_quantity, 0) - COALESCE(si.sold_quantity, 0)
        ), 0)::DECIMAL(15,3) AS total_available_quantity,
        COALESCE(SUM(si.total_price), 0)::DECIMAL(15,2) AS total_goods_value,
        COALESCE(SUM(si.total_provisional_cost), 0)::DECIMAL(15,2) AS total_provisional_cost,
        COALESCE(SUM(si.total_final_cost), 0)::DECIMAL(15,2) AS total_final_cost,
        COUNT(DISTINCT si.supplier_id)::BIGINT AS unique_suppliers,
        COUNT(DISTINCT si.purchase_invoice_id)::BIGINT AS unique_invoices,
        COUNT(DISTINCT si.material_id)::BIGINT AS unique_materials
    FROM shipment_items si
    WHERE si.shipment_id = p_shipment_id;
END;
$$;


--
-- Name: get_softphone_contacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_softphone_contacts() RETURNS TABLE(id text, name_ar text, name_en text, phone text, mobile text, type text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_uid        uuid    := auth.uid();
  v_is_backend boolean := (auth.role() = 'service_role') OR (auth.uid() IS NULL);
  v_company    uuid;
BEGIN
  -- Identity is always derived from auth.uid(); no client-supplied caller is trusted.
  -- Trusted backend calls (service_role / no JWT) bypass the per-user company scope.
  IF NOT v_is_backend THEN
    v_company := public.get_user_company_id(v_uid);
    IF v_company IS NULL THEN
      -- No company context => no private CRM directory access.
      RAISE EXCEPTION 'No company context for caller' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH combined AS (
    SELECT
      'c-' || cu.id::text       AS id,
      cu.name_ar::text          AS name_ar,
      cu.name_en::text          AS name_en,
      COALESCE(cu.phone, '')::text  AS phone,
      COALESCE(cu.mobile, '')::text AS mobile,
      'عميل'::text              AS type
    FROM customers cu
    WHERE v_is_backend OR cu.company_id = v_company

    UNION ALL

    SELECT
      's-' || su.id::text       AS id,
      su.name_ar::text          AS name_ar,
      su.name_en::text          AS name_en,
      COALESCE(su.phone, '')::text  AS phone,
      COALESCE(su.mobile, '')::text AS mobile,
      'مورد'::text              AS type
    FROM suppliers su
    WHERE v_is_backend OR su.company_id = v_company
  )
  SELECT DISTINCT ON (COALESCE(c.name_ar, c.name_en, ''))
    c.id,
    c.name_ar,
    c.name_en,
    c.phone,
    c.mobile,
    c.type
  FROM combined c
  ORDER BY COALESCE(c.name_ar, c.name_en, ''), c.id;
END;
$$;


--
-- Name: get_status_color_class(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_status_color_class(color character varying) RETURNS character varying
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  RETURN CASE color
    WHEN 'gray' THEN 'bg-gray-100 text-gray-700'
    WHEN 'blue' THEN 'bg-blue-100 text-blue-700'
    WHEN 'green' THEN 'bg-green-100 text-green-700'
    WHEN 'red' THEN 'bg-red-100 text-red-700'
    WHEN 'yellow' THEN 'bg-yellow-100 text-yellow-700'
    WHEN 'orange' THEN 'bg-orange-100 text-orange-700'
    WHEN 'purple' THEN 'bg-purple-100 text-purple-700'
    WHEN 'pink' THEN 'bg-pink-100 text-pink-700'
    WHEN 'indigo' THEN 'bg-indigo-100 text-indigo-700'
    WHEN 'teal' THEN 'bg-teal-100 text-teal-700'
    ELSE 'bg-gray-100 text-gray-700'
  END;
END;
$$;


--
-- Name: get_subscription_plans(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_subscription_plans(p_active_only boolean DEFAULT true) RETURNS TABLE(id uuid, product_id uuid, code character varying, name_ar character varying, name_en character varying, description text, max_users integer, max_companies integer, max_branches integer, max_warehouses integer, max_products integer, storage_gb integer, included_modules jsonb, features jsonb, price_monthly numeric, price_yearly numeric, currency character varying, trial_days integer, is_popular boolean, display_order integer, is_active boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        sp.id,
        sp.product_id,
        sp.code,
        sp.name_ar,
        sp.name_en,
        sp.description,
        sp.max_users,
        sp.max_companies,
        sp.max_branches,
        sp.max_warehouses,
        sp.max_products,
        sp.storage_gb,
        sp.included_modules,
        sp.features,
        sp.price_monthly,
        sp.price_yearly,
        sp.currency,
        sp.trial_days,
        sp.is_popular,
        sp.display_order,
