END;
$$;


--
-- Name: get_subscription_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_subscription_stats(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_subscription RECORD;
    v_stats JSONB;
BEGIN
    SELECT 
        ts.id,
        ts.status,
        ts.start_date,
        ts.end_date,
        ts.total_days_purchased,
        ts.remaining_balance,
        sp.name_en,
        sp.name_ar,
        sp.price_monthly,
        sp.price_daily,
        sp.currency,
        -- إصلاح: استخدام طرح التواريخ مباشرة بدلاً من EXTRACT
        (ts.end_date - CURRENT_DATE) as days_remaining,
        (CURRENT_DATE - ts.start_date) as days_used,
        CASE 
            WHEN ts.end_date < CURRENT_DATE THEN 'expired'
            WHEN (ts.end_date - CURRENT_DATE) <= 7 THEN 'expiring_soon'
            ELSE 'active'
        END as health_status
    INTO v_subscription
    FROM tenant_subscriptions ts
    JOIN subscription_plans sp ON ts.plan_id = sp.id
    WHERE ts.tenant_id = p_tenant_id
        AND ts.status IN ('active', 'trial', 'expired')
    ORDER BY ts.end_date DESC
    LIMIT 1;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('found', false);
    END IF;
    
    v_stats := jsonb_build_object(
        'found', true,
        'subscription_id', v_subscription.id,
        'status', v_subscription.status,
        'health_status', v_subscription.health_status,
        'start_date', v_subscription.start_date,
        'end_date', v_subscription.end_date,
        'days_remaining', GREATEST(v_subscription.days_remaining, 0),
        'days_used', v_subscription.days_used,
        'total_days_purchased', v_subscription.total_days_purchased,
        'remaining_balance', v_subscription.remaining_balance,
        'plan', jsonb_build_object(
            'name_en', v_subscription.name_en,
            'name_ar', v_subscription.name_ar,
            'price_monthly', v_subscription.price_monthly,
            'price_daily', v_subscription.price_daily,
            'currency', v_subscription.currency
        )
    );
    
    RETURN v_stats;
END;
$$;


--
-- Name: get_subscription_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_subscription_status(p_tenant_id uuid) RETURNS TABLE(subscription_id uuid, plan_name character varying, status character varying, days_remaining integer, is_expired boolean, is_locked boolean, is_in_grace_period boolean, grace_days_remaining integer, access_level character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_sub RECORD;
    v_days_remaining INT;
    v_grace_days_remaining INT;
    v_access_level VARCHAR;
BEGIN
    SELECT s.*, sp.name_ar as plan_name_ar, sp.name_en as plan_name_en
    INTO v_sub
    FROM subscriptions s
    LEFT JOIN subscription_plans sp ON s.plan_id = sp.id
    WHERE s.tenant_id = p_tenant_id
    AND s.status != 'cancelled'
    ORDER BY s.created_at DESC
    LIMIT 1;
    
    IF NOT FOUND THEN
        RETURN QUERY SELECT 
            NULL::UUID,
            'No Plan'::VARCHAR,
            'none'::VARCHAR,
            0,
            true,
            true,
            false,
            0,
            'locked'::VARCHAR;
        RETURN;
    END IF;
    
    -- حساب الأيام المتبقية
    v_days_remaining := EXTRACT(DAY FROM (v_sub.current_period_end - NOW()));
    
    -- حساب أيام فترة السماح المتبقية
    IF v_sub.current_period_end < NOW() THEN
        v_grace_days_remaining := COALESCE(v_sub.grace_period_days, 7) - 
            EXTRACT(DAY FROM (NOW() - v_sub.current_period_end))::INT;
    ELSE
        v_grace_days_remaining := COALESCE(v_sub.grace_period_days, 7);
    END IF;
    
    -- تحديد مستوى الوصول
    IF v_sub.locked_at IS NOT NULL THEN
        v_access_level := 'locked';
    ELSIF v_sub.current_period_end < NOW() AND v_grace_days_remaining <= 0 THEN
        v_access_level := 'locked';
    ELSIF v_sub.current_period_end < NOW() THEN
        v_access_level := 'read_only';
    ELSIF v_days_remaining <= 3 THEN
        v_access_level := 'warning';
    ELSE
        v_access_level := 'full';
    END IF;
    
    RETURN QUERY SELECT 
        v_sub.id,
        COALESCE(v_sub.plan_name_ar, v_sub.plan_name_en, 'Unknown')::VARCHAR,
        v_sub.status,
        GREATEST(0, v_days_remaining),
        v_sub.current_period_end < NOW(),
        v_sub.locked_at IS NOT NULL OR (v_sub.current_period_end < NOW() AND v_grace_days_remaining <= 0),
        v_sub.current_period_end < NOW() AND v_grace_days_remaining > 0,
        GREATEST(0, v_grace_days_remaining),
        v_access_level;
END;
$$;


--
-- Name: get_target_achievement_report(uuid, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_target_achievement_report(p_company_id uuid, p_period_year integer, p_period_month integer DEFAULT NULL::integer, p_employee_id uuid DEFAULT NULL::uuid) RETURNS TABLE(employee_id uuid, target_type character varying, target_amount numeric, achieved_amount numeric, achievement_percentage numeric, remaining_amount numeric, bonus_earned numeric, status character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        et.employee_id,
        et.target_type,
        et.target_amount,
        et.achieved_amount,
        et.achievement_percentage,
        GREATEST(et.target_amount - et.achieved_amount, 0)::DECIMAL(15,2) as remaining_amount,
        CASE 
            WHEN et.achievement_percentage >= 100 THEN et.bonus_on_achievement
            ELSE 0
        END + 
        CASE 
            WHEN et.achievement_percentage > 100 
            THEN (et.achieved_amount - et.target_amount) * et.bonus_on_exceed / 100
            ELSE 0
        END as bonus_earned,
        et.status
    FROM employee_targets et
    WHERE et.company_id = p_company_id
      AND et.period_year = p_period_year
      AND (p_period_month IS NULL OR et.period_month = p_period_month)
      AND (p_employee_id IS NULL OR et.employee_id = p_employee_id)
    ORDER BY et.employee_id, et.target_type;
END;
$$;


