--
-- Name: get_telegram_scan_card(text, uuid, bigint, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_telegram_scan_card(p_kind text, p_id uuid, p_scanner_chat_id bigint DEFAULT NULL::bigint, p_scanner_name text DEFAULT NULL::text, p_log boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_tenant uuid; v_company uuid; v_material uuid; v_staff boolean := false;
    v_name text; v_img text; v_price numeric; v_cur text; v_slug text; v_instock boolean; v_origin text;
    v_card jsonb; v_contact uuid; v_roll record;
BEGIN
    IF p_kind = 'roll' THEN
        SELECT fr.tenant_id, fr.company_id, fr.material_id INTO v_tenant, v_company, v_material
          FROM fabric_rolls fr WHERE fr.id = p_id;
    ELSE
        SELECT fm.tenant_id, fm.company_id, fm.id INTO v_tenant, v_company, v_material
          FROM fabric_materials fm WHERE fm.id = p_id;
    END IF;
    IF v_tenant IS NULL OR v_material IS NULL THEN
        RETURN jsonb_build_object('ok', false, 'message', 'العنصر غير موجود');
    END IF;

    -- staff verified SERVER-SIDE: scanner must be an ACTIVE telegram connection of THIS tenant
    v_staff := (p_scanner_chat_id IS NOT NULL) AND EXISTS(
        SELECT 1 FROM telegram_connections tc
        WHERE tc.is_active AND tc.tenant_id = v_tenant AND tc.telegram_chat_id = p_scanner_chat_id);

    -- PUBLIC card built from the material (for a roll → its material), mirroring storefront public scope
    SELECT COALESCE(fm.name_ar, fm.name_en),
           (SELECT mi.url FROM material_images mi
              WHERE mi.material_id = fm.id AND COALESCE(mi.is_published, true)
              ORDER BY mi.is_primary DESC NULLS LAST, mi.sort_order NULLS LAST LIMIT 1),
           COALESCE(ep.base_price, fm.selling_price),
           COALESCE(ep.currency, fm.currency),
           ep.seo_slug,
           (COALESCE(ep.stock_status,'tracked') NOT IN ('coming_soon','out_of_stock')
              AND (COALESCE(ep.stock_status,'tracked') <> 'tracked' OR COALESCE(fm.current_stock,0) > 0)),
           fm.origin_country
      INTO v_name, v_img, v_price, v_cur, v_slug, v_instock, v_origin
      FROM fabric_materials fm
      LEFT JOIN ecommerce_products ep ON ep.material_id = fm.id AND COALESCE(ep.is_published, false)
     WHERE fm.id = v_material;

    v_card := jsonb_build_object(
        'ok', true, 'kind', p_kind, 'material_id', v_material,
        'name', v_name, 'image', v_img, 'price', v_price, 'currency', v_cur,
        'in_stock', v_instock, 'origin', v_origin,
        'storefront_url', CASE WHEN NULLIF(v_slug,'') IS NOT NULL THEN 'https://tkanex.com/product/'||v_slug ELSE NULL END,
        'is_staff', v_staff
    );

    -- staff-only internal detail (never leaked to a public scanner)
    IF v_staff AND p_kind = 'roll' THEN
        SELECT fr.roll_number, fr.available_length, fr.width, fr.status, fr.color_name, w.name AS wh_name
          INTO v_roll
          FROM fabric_rolls fr LEFT JOIN warehouses w ON w.id = fr.warehouse_id
         WHERE fr.id = p_id;
        v_card := v_card || jsonb_build_object('roll', jsonb_build_object(
            'roll_number', v_roll.roll_number, 'length', v_roll.available_length, 'width', v_roll.width,
            'status', v_roll.status, 'warehouse', v_roll.wh_name, 'color', v_roll.color_name));
    ELSIF v_staff AND p_kind = 'mat' THEN
        v_card := v_card || jsonb_build_object('exact_stock', (SELECT current_stock FROM fabric_materials WHERE id = v_material));
    END IF;

    -- telemetry + CRM lead (only when a scanner identity is present)
    IF p_log AND p_scanner_chat_id IS NOT NULL THEN
        INSERT INTO qr_telegram_scans(tenant_id, company_id, kind, entity_id, material_id, scanner_chat_id, scanner_name, is_staff)
          VALUES(v_tenant, v_company, p_kind, p_id, v_material, p_scanner_chat_id, p_scanner_name, v_staff);

        IF NOT v_staff THEN   -- promote walk-in scanners to a CRM lead; staff are internal
            SELECT id INTO v_contact FROM contacts
              WHERE tenant_id = v_tenant AND telegram_chat_id = p_scanner_chat_id LIMIT 1;
            IF v_contact IS NULL THEN
                INSERT INTO contacts(tenant_id, company_id, display_name, telegram_chat_id, source, source_details,
                                     contact_type, lifecycle_stage, last_interaction_at, last_interaction_type)
                  VALUES(v_tenant, v_company, COALESCE(NULLIF(p_scanner_name,''),'زائر تلغرام'), p_scanner_chat_id,
                         'telegram', jsonb_build_object('channel', 'qr_scan', 'first_material', v_material, 'first_seen', now()),
                         'lead', 'new', now(), 'qr_scan')
                  RETURNING id INTO v_contact;
            ELSE
                UPDATE contacts SET last_interaction_at = now(), last_interaction_type = 'qr_scan',
                       display_name = COALESCE(NULLIF(display_name,''), NULLIF(p_scanner_name,''))
                 WHERE id = v_contact;
            END IF;
            INSERT INTO contact_interactions(tenant_id, contact_id, interaction_type, direction, subject, content, metadata)
              VALUES(v_tenant, v_contact, 'telegram', 'inbound', 'مسح QR',
                     'مسح '||CASE WHEN p_kind='roll' THEN 'رولون' ELSE 'عيّنة مادة' END||': '||COALESCE(v_name,'—'),
                     jsonb_build_object('event', 'qr_scan', 'kind', p_kind, 'entity_id', p_id, 'material_id', v_material));
        END IF;
    END IF;

    RETURN v_card;
EXCEPTION WHEN OTHERS THEN
    -- never fail the scan over logging/CRM; still return the card if it was built
    RETURN COALESCE(v_card, jsonb_build_object('ok', false, 'message', 'تعذّر التحميل'));
END $$;


--
-- Name: get_tenant_active_languages(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_tenant_active_languages(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(language_code character varying, language_name_ar character varying, language_name_en character varying, is_primary boolean, display_order integer, direction character varying, flag_emoji character varying)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
BEGIN
    v_tenant_id := COALESCE(p_tenant_id, get_current_tenant_id());
    
    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION 'Tenant not found';
    END IF;
    
    RETURN QUERY
    SELECT 
        tl.language_code,
        sl.name_ar,
        sl.name_en,
        tl.is_primary,
        tl.display_order,
        sl.direction,
        sl.flag_emoji
    FROM tenant_languages tl
    JOIN system_languages sl ON sl.code = tl.language_code
    WHERE tl.tenant_id = v_tenant_id
    AND tl.is_enabled = true
    ORDER BY tl.is_primary DESC, tl.display_order, sl.name_en;
END;
$$;


--
-- Name: get_tenant_available_modules(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_tenant_available_modules(p_tenant_id uuid) RETURNS TABLE(module_code character varying, name_ar character varying, name_en character varying, icon character varying, display_order integer, is_enabled boolean, requires_upgrade boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        m.code AS module_code,
        m.name_ar,
        m.name_en,
        m.icon,
        m.display_order,
        COALESCE(tm.is_enabled, FALSE) AS is_enabled,
        (
            (tm.is_enabled IS NULL OR tm.is_enabled = FALSE) 
            AND 
            (m.code = ANY(sp.included_modules))
        ) AS requires_upgrade
    FROM system_modules m
    LEFT JOIN tenant_modules tm 
        ON tm.module_code = m.code 
        AND tm.tenant_id = p_tenant_id
    LEFT JOIN tenants t 
        ON t.id = p_tenant_id
    LEFT JOIN subscriptions sub 
        ON sub.tenant_id = t.id 
        AND sub.status = 'active'
    LEFT JOIN subscription_plans sp 
        ON sp.id = sub.plan_id
    WHERE m.is_active = true
    ORDER BY m.display_order;
END;
$$;


--
-- Name: get_tenant_company_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_tenant_company_ids(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_company_ids UUID[];
BEGIN
    -- إذا لم يتم تحديد tenant_id، استخدم tenant_id للمستخدم الحالي
    v_tenant_id := COALESCE(p_tenant_id, get_user_tenant_id());
    
    IF v_tenant_id IS NULL THEN
        RETURN ARRAY[]::UUID[];
    END IF;
    
    SELECT ARRAY_AGG(id)
    INTO v_company_ids
    FROM public.companies
    WHERE tenant_id = v_tenant_id
      AND is_active = true;
    
    RETURN COALESCE(v_company_ids, ARRAY[]::UUID[]);
EXCEPTION WHEN OTHERS THEN
    RETURN ARRAY[]::UUID[];
END;
$$;


--
-- Name: get_tenant_limits(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_tenant_limits(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_plan RECORD;
BEGIN
    SELECT sp.* INTO v_plan
    FROM subscriptions s
    JOIN subscription_plans sp ON s.plan_id = sp.id
    WHERE s.tenant_id = p_tenant_id AND s.status IN ('active', 'trial')
    LIMIT 1;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'لا يوجد اشتراك');
    END IF;
    
    RETURN jsonb_build_object(
        'max_users', v_plan.max_users,
        'max_companies', v_plan.max_companies,
        'max_branches', v_plan.max_branches,
        'max_warehouses', v_plan.max_warehouses,
        'max_products', v_plan.max_products,
        'max_invoices_monthly', v_plan.max_invoices_monthly,
        'storage_gb', v_plan.storage_gb,
        'features', v_plan.features
    );
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: tenant_login_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.tenant_login_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    user_id uuid,
    user_email character varying(200),
    session_start timestamp with time zone DEFAULT now() NOT NULL,
    last_heartbeat timestamp with time zone DEFAULT now() NOT NULL,
    session_end timestamp with time zone,
    duration_seconds integer GENERATED ALWAYS AS (
CASE
    WHEN (session_end IS NOT NULL) THEN (EXTRACT(epoch FROM (session_end - session_start)))::integer
    ELSE (EXTRACT(epoch FROM (last_heartbeat - session_start)))::integer
END) STORED,
    is_active boolean DEFAULT true,
    ip character varying(50),
    country character varying(100),
    city character varying(100),
    user_agent text,
    browser character varying(100),
    os character varying(100),
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: get_tenant_login_sessions(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_tenant_login_sessions(p_tenant_id uuid, p_limit integer DEFAULT 50) RETURNS SETOF public.tenant_login_sessions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- Only allow super admins
    IF NOT EXISTS (
        SELECT 1 FROM auth.users u 
        WHERE u.id = auth.uid() 
        AND (u.raw_user_meta_data->>'is_super_admin')::boolean = true
    ) THEN
        RAISE EXCEPTION 'Access denied';
    END IF;

    RETURN QUERY
    SELECT *
    FROM tenant_login_sessions
    WHERE tenant_id = p_tenant_id
    ORDER BY session_start DESC
    LIMIT p_limit;
END;
$$;


--
-- Name: get_tenant_sidebar_structure(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_tenant_sidebar_structure(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_result JSONB;
BEGIN
    v_tenant_id := COALESCE(p_tenant_id, get_current_tenant_id());
    
    SELECT jsonb_build_object(
        'categories', jsonb_agg(
            jsonb_build_object(
                'category', category,
                'modules', modules
            )
        )
    ) INTO v_result
    FROM (
        SELECT 
            COALESCE(sm.category, 'basic') as category,
            jsonb_agg(
                jsonb_build_object(
                    'code', sm.code,
                    'name_ar', sm.name_ar,
                    'name_en', sm.name_en,
                    'icon', sm.icon,
                    'path', '/' || sm.code,
                    'is_enabled', COALESCE(tm.is_active, sm.is_core),
                    'is_core', sm.is_core,
                    'badge', CASE 
                        WHEN NOT COALESCE(tm.is_active, sm.is_core) THEN 'locked'
                        ELSE NULL
                    END
                )
                ORDER BY sm.display_order
            ) as modules
        FROM system_modules sm
        LEFT JOIN tenant_modules tm ON tm.module_code = sm.code 
            AND tm.tenant_id = v_tenant_id
        WHERE sm.is_active = true
        GROUP BY sm.category
    ) categories;
    
    RETURN v_result;
END;
$$;


--
-- Name: get_tenant_statistics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_tenant_statistics(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
    v_result JSONB;
BEGIN
    v_tenant_id := COALESCE(p_tenant_id, get_current_tenant_id());
    
    SELECT jsonb_build_object(
        'companies', (SELECT COUNT(*) FROM companies WHERE tenant_id = v_tenant_id),
        'users', (SELECT COUNT(*) FROM user_profiles WHERE tenant_id = v_tenant_id),
        'customers', (SELECT COUNT(*) FROM customers WHERE tenant_id = v_tenant_id),
        'suppliers', (SELECT COUNT(*) FROM suppliers WHERE tenant_id = v_tenant_id),
        'products', (SELECT COUNT(*) FROM products WHERE tenant_id = v_tenant_id),
        'journal_entries', (SELECT COUNT(*) FROM journal_entries WHERE tenant_id = v_tenant_id),
        'sales_invoices', (SELECT COUNT(*) FROM sales_invoices WHERE tenant_id = v_tenant_id),
        'documents', (SELECT COUNT(*) FROM documents WHERE tenant_id = v_tenant_id),
        'storage_used', (
            SELECT COALESCE(SUM(file_size), 0)
            FROM documents
            WHERE tenant_id = v_tenant_id
        )
    ) INTO v_result;
    
    RETURN v_result;
END;
$$;


--
-- Name: get_tenants_by_product(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_tenants_by_product(p_product_code character varying) RETURNS TABLE(id uuid, code character varying, name character varying, email character varying, status character varying, created_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        t.id,
        t.code,
        t.name,
        t.email,
        t.status,
        t.created_at
    FROM tenants t
    JOIN saas_products prod ON t.product_id = prod.id
    WHERE prod.code = p_product_code
    ORDER BY t.created_at DESC;
END;
$$;


--
-- Name: get_ticker_kpis(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_ticker_kpis(p_tenant_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  result JSON;
  today_start TIMESTAMPTZ := date_trunc('day', NOW());
  month_start TIMESTAMPTZ := date_trunc('month', NOW());
BEGIN
  SELECT json_build_object(
    'pending_sales_orders', COALESCE((
      SELECT COUNT(*) FROM sales_orders 
      WHERE tenant_id = p_tenant_id AND status IN ('draft', 'pending', 'confirmed')
    ), 0),
    'today_sales_count', COALESCE((
      SELECT COUNT(*) FROM sales_invoices 
      WHERE tenant_id = p_tenant_id AND created_at >= today_start
    ), 0),
    'month_sales_total', COALESCE((
      SELECT ROUND(COALESCE(SUM(total_amount), 0)::numeric, 2) FROM sales_invoices 
      WHERE tenant_id = p_tenant_id AND created_at >= month_start
    ), 0),
    'unpaid_invoices', COALESCE((
      SELECT COUNT(*) FROM sales_invoices 
      WHERE tenant_id = p_tenant_id AND status IN ('draft', 'pending', 'sent')
    ), 0),
    'pending_purchases', COALESCE((
      SELECT COUNT(*) FROM purchase_orders 
      WHERE tenant_id = p_tenant_id AND status IN ('draft', 'pending', 'approved')
    ), 0),
    'total_materials', COALESCE((
      SELECT COUNT(*) FROM fabric_materials 
      WHERE tenant_id = p_tenant_id AND is_active = true
    ), 0),
    'total_rolls', COALESCE((
      SELECT COUNT(*) FROM fabric_rolls 
      WHERE tenant_id = p_tenant_id AND status = 'available'
    ), 0),
    'total_customers', COALESCE((
      SELECT COUNT(*) FROM customers WHERE tenant_id = p_tenant_id
    ), 0),
    'total_suppliers', COALESCE((
      SELECT COUNT(*) FROM suppliers WHERE tenant_id = p_tenant_id
    ), 0)
  ) INTO result;
  
  RETURN result;
END;
$$;


--
-- Name: get_total_revenue(character varying, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_total_revenue(p_currency character varying DEFAULT 'USD'::character varying, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_total DECIMAL(12,2);
BEGIN
    SELECT COALESCE(SUM(amount), 0)
    INTO v_total
    FROM saas_payments
    WHERE status = 'completed'
    AND currency = p_currency
    AND (p_start_date IS NULL OR collection_date >= p_start_date)
    AND (p_end_date IS NULL OR collection_date <= p_end_date);
    
    RETURN v_total;
END;
$$;


--
-- Name: get_transfer_history(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_transfer_history(p_account_id uuid, p_limit integer DEFAULT 50) RETURNS TABLE(transfer_id uuid, transfer_date timestamp with time zone, transfer_type character varying, source_account_code character varying, source_account_name character varying, target_account_code character varying, target_account_name character varying, amount numeric, notes text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        t.id,
        t.created_at,
        t.transfer_type,
        sa.account_code,
        sa.name_ar,
        ta.account_code,
        ta.name_ar,
        t.amount,
        t.notes
    FROM account_transfers t
    INNER JOIN chart_of_accounts sa ON t.source_account_id = sa.id
    INNER JOIN chart_of_accounts ta ON t.target_account_id = ta.id
    WHERE t.source_account_id = p_account_id 
       OR t.target_account_id = p_account_id
    ORDER BY t.created_at DESC
    LIMIT p_limit;
END;
$$;


