--
-- Name: get_trial_balance(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_trial_balance(p_company_id uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS TABLE(account_id uuid, account_code character varying, account_name_ar character varying, account_name_en character varying, account_type character varying, parent_code character varying, level integer, is_group boolean, opening_debit numeric, opening_credit numeric, period_debit numeric, period_credit numeric, closing_debit numeric, closing_credit numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_from_date DATE;
    v_to_date DATE;
BEGIN
    -- تحديد التواريخ الافتراضية
    v_from_date := COALESCE(p_from_date, DATE_TRUNC('year', CURRENT_DATE)::DATE);
    v_to_date := COALESCE(p_to_date, CURRENT_DATE);
    
    RETURN QUERY
    WITH account_movements AS (
        -- حركات قبل الفترة (الرصيد الافتتاحي)
        SELECT 
            jel.account_id,
            SUM(CASE WHEN je.entry_date < v_from_date THEN jel.debit ELSE 0 END) as opening_debit,
            SUM(CASE WHEN je.entry_date < v_from_date THEN jel.credit ELSE 0 END) as opening_credit,
            -- حركات الفترة
            SUM(CASE WHEN je.entry_date BETWEEN v_from_date AND v_to_date THEN jel.debit ELSE 0 END) as period_debit,
            SUM(CASE WHEN je.entry_date BETWEEN v_from_date AND v_to_date THEN jel.credit ELSE 0 END) as period_credit
        FROM journal_entry_lines jel
        JOIN journal_entries je ON jel.entry_id = je.id
        WHERE je.company_id = p_company_id
          AND je.is_posted = true
          AND je.entry_date <= v_to_date
        GROUP BY jel.account_id
    ),
    account_balances AS (
        SELECT 
            coa.id as account_id,
            coa.account_code,
            coa.name_ar as account_name_ar,
            coa.name_en as account_name_en,
            at.code as account_type,
            parent.account_code as parent_code,
            coa.level,
            coa.is_group,
            COALESCE(coa.opening_balance, 0) as initial_balance,
            COALESCE(am.opening_debit, 0) as mov_opening_debit,
            COALESCE(am.opening_credit, 0) as mov_opening_credit,
            COALESCE(am.period_debit, 0) as period_debit,
            COALESCE(am.period_credit, 0) as period_credit,
            at.normal_balance
        FROM chart_of_accounts coa
        LEFT JOIN account_types at ON coa.account_type_id = at.id
        LEFT JOIN chart_of_accounts parent ON coa.parent_id = parent.id
        LEFT JOIN account_movements am ON coa.id = am.account_id
        WHERE coa.company_id = p_company_id
          AND coa.is_active = true
    )
    SELECT 
        ab.account_id,
        ab.account_code,
        ab.account_name_ar,
        ab.account_name_en,
        ab.account_type,
        ab.parent_code,
        ab.level,
        ab.is_group,
        -- الرصيد الافتتاحي
        CASE 
            WHEN ab.normal_balance = 'debit' THEN 
                GREATEST(ab.initial_balance + ab.mov_opening_debit - ab.mov_opening_credit, 0)
            ELSE 0::DECIMAL(15,2)
        END as opening_debit,
        CASE 
            WHEN ab.normal_balance = 'credit' THEN 
                GREATEST(ab.initial_balance + ab.mov_opening_credit - ab.mov_opening_debit, 0)
            ELSE 0::DECIMAL(15,2)
        END as opening_credit,
        -- حركات الفترة
        ab.period_debit,
        ab.period_credit,
        -- الرصيد الختامي
        CASE 
            WHEN ab.normal_balance = 'debit' THEN 
                GREATEST(ab.initial_balance + ab.mov_opening_debit - ab.mov_opening_credit + ab.period_debit - ab.period_credit, 0)
            ELSE 0::DECIMAL(15,2)
        END as closing_debit,
        CASE 
            WHEN ab.normal_balance = 'credit' THEN 
                GREATEST(ab.initial_balance + ab.mov_opening_credit - ab.mov_opening_debit + ab.period_credit - ab.period_debit, 0)
            ELSE 0::DECIMAL(15,2)
        END as closing_credit
    FROM account_balances ab
    ORDER BY ab.account_code;
END;
$$;


--
-- Name: FUNCTION get_trial_balance(p_company_id uuid, p_from_date date, p_to_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_trial_balance(p_company_id uuid, p_from_date date, p_to_date date) IS 'ميزان المراجعة - يعرض أرصدة جميع الحسابات (افتتاحي، حركات الفترة، ختامي)';


--
-- Name: get_trial_balance_base(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_trial_balance_base(p_company_id uuid) RETURNS TABLE(total_debit numeric, total_credit numeric, balance_diff numeric, is_balanced boolean, base_currency text, accounts_count bigint, entries_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
SELECT
    COALESCE(SUM(jel.debit), 0)::NUMERIC AS total_debit,
    COALESCE(SUM(jel.credit), 0)::NUMERIC AS total_credit,
    ABS(COALESCE(SUM(jel.debit), 0) - COALESCE(SUM(jel.credit), 0))::NUMERIC AS balance_diff,
    (ABS(COALESCE(SUM(jel.debit), 0) - COALESCE(SUM(jel.credit), 0)) < 0.01)::BOOLEAN AS is_balanced,
    COALESCE(c.default_currency, 'USD')::TEXT AS base_currency,
    COUNT(DISTINCT jel.account_id)::BIGINT AS accounts_count,
    COUNT(DISTINCT jel.entry_id)::BIGINT AS entries_count
FROM journal_entry_lines jel
INNER JOIN journal_entries je
    ON je.id = jel.entry_id
   AND je.company_id = p_company_id
   AND je.is_posted = true
   AND je.status = 'posted'
CROSS JOIN (SELECT default_currency FROM companies WHERE id = p_company_id) c
GROUP BY c.default_currency;
$$;


--
-- Name: get_user_accessible_company_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_accessible_company_ids(p_user_id uuid DEFAULT auth.uid()) RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_user_tenant_id UUID;
    v_user_company_id UUID;
    v_company_ids UUID[];
BEGIN
    -- Platform Owner يرى كل الشركات في كل البراندات
    IF is_platform_owner(p_user_id) THEN
        SELECT ARRAY_AGG(id)
        INTO v_company_ids
        FROM public.companies
        WHERE is_active = true;
        RETURN COALESCE(v_company_ids, ARRAY[]::UUID[]);
    END IF;
    
    -- Partner/Reseller: شركات التينانتات التابعة له ضمن البراندات المسموح بها
    IF is_partner_or_reseller(p_user_id) THEN
        SELECT ARRAY_AGG(c.id)
        INTO v_company_ids
        FROM public.companies c
        WHERE c.tenant_id = ANY(get_partner_tenant_ids(p_user_id))
          AND c.is_active = true;
        RETURN COALESCE(v_company_ids, ARRAY[]::UUID[]);
    END IF;
    
    -- الحصول على بيانات المستخدم
    SELECT tenant_id, company_id 
    INTO v_user_tenant_id, v_user_company_id
    FROM public.user_profiles
    WHERE id = p_user_id;
    
    IF v_user_tenant_id IS NULL THEN
        RETURN ARRAY[]::UUID[];
    END IF;
    
    -- Tenant Owner يرى كل شركات التينانت
    IF is_tenant_owner(p_user_id) THEN
        RETURN get_tenant_company_ids(v_user_tenant_id);
    END IF;
    
    -- المستخدم العادي: الشركة الافتراضية + الشركات المُعينة عبر user_roles
    SELECT ARRAY_AGG(DISTINCT company_id)
    INTO v_company_ids
    FROM (
        -- الشركة الافتراضية
        SELECT v_user_company_id AS company_id
        WHERE v_user_company_id IS NOT NULL
        UNION
        -- الشركات من user_roles
        SELECT ur.company_id
        FROM public.user_roles ur
        WHERE ur.user_id = p_user_id
          AND ur.is_active = true
          AND ur.company_id IS NOT NULL
    ) AS accessible;
    
    RETURN COALESCE(v_company_ids, ARRAY[]::UUID[]);
EXCEPTION WHEN OTHERS THEN
    RETURN ARRAY[]::UUID[];
END;
$$;


--
-- Name: get_user_accessible_funds(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_accessible_funds(p_user_id uuid DEFAULT auth.uid()) RETURNS TABLE(fund_account_id uuid, can_deposit boolean, can_withdraw boolean, can_transfer boolean, is_primary boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    -- Platform/Tenant/Company admins see all
    IF is_super_admin(p_user_id) OR is_tenant_admin(p_user_id) OR is_company_admin(p_user_id) THEN
        RETURN QUERY
        SELECT coa.id, true, true, true, false
        FROM chart_of_accounts coa
        WHERE coa.account_type IN ('cash', 'bank')
          AND coa.is_active = true
          AND coa.tenant_id = get_current_tenant_id();
        RETURN;
    END IF;
    
    -- Regular users - assigned funds only
    RETURN QUERY
    SELECT 
        ufp.fund_account_id,
        ufp.can_deposit,
        ufp.can_withdraw,
        ufp.can_transfer,
        ufp.is_primary
    FROM user_fund_permissions ufp
    WHERE ufp.user_id = p_user_id
      AND ufp.can_view = true;
END;
$$;


--
-- Name: get_user_accessible_warehouses(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_accessible_warehouses(p_user_id uuid DEFAULT auth.uid()) RETURNS TABLE(warehouse_id uuid, can_receive boolean, can_issue boolean, can_transfer boolean, can_count boolean, is_keeper boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    IF is_super_admin(p_user_id) OR is_tenant_admin(p_user_id) OR is_company_admin(p_user_id) THEN
        RETURN QUERY
        SELECT w.id, true, true, true, true, false
        FROM warehouses w
        WHERE w.is_active = true
          AND w.tenant_id = get_current_tenant_id();
        RETURN;
    END IF;
    
    RETURN QUERY
    SELECT 
        uwp.warehouse_id,
        uwp.can_receive,
        uwp.can_issue,
        uwp.can_transfer,
        uwp.can_count,
        uwp.is_keeper
    FROM user_warehouse_permissions uwp
    WHERE uwp.user_id = p_user_id
      AND uwp.can_view = true;
END;
$$;


--
-- Name: get_user_allowed_modules(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_allowed_modules(p_user_id uuid) RETURNS TABLE(module_code character varying, name_ar character varying, name_en character varying, name_de character varying, name_tr character varying, name_ru character varying, name_uk character varying, name_it character varying, name_pl character varying, name_ro character varying, description_ar text, description_en text, icon character varying, color character varying, category character varying, display_order integer, is_core boolean, is_beta boolean, requires_setup boolean, is_enabled boolean, requires_upgrade boolean, can_view boolean, can_create boolean, can_edit boolean, can_delete boolean, can_export boolean, can_import boolean, can_approve boolean, can_manage_settings boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_company_id UUID;
BEGIN
    -- الحصول على tenant_id و company_id للمستخدم
    SELECT up.tenant_id, up.company_id
    INTO v_tenant_id, v_company_id
    FROM user_profiles up
    WHERE up.id = p_user_id;
    
    -- إذا لم يوجد user_profile، إرجاع فارغ
    IF v_tenant_id IS NULL THEN
        RETURN;
    END IF;
    
    -- إرجاع الموديولات مع الصلاحيات
    RETURN QUERY
    SELECT 
        m.module_code,
        m.name_ar,
        m.name_en,
        m.name_de,
        m.name_tr,
        m.name_ru,
        m.name_uk,
        m.name_it,
        m.name_pl,
        m.name_ro,
        m.description_ar,
        m.description_en,
        m.icon,
        m.color,
        m.category,
        m.display_order,
        m.is_core,
        m.is_beta,
        m.requires_setup,
        
        -- التحقق من تفعيل الموديول للـ tenant
        COALESCE(tm.is_active, false) as is_enabled,
        
        -- التحقق من الحاجة للترقية
        CASE 
            WHEN tm.is_active = false THEN true
            ELSE false
        END as requires_upgrade,
        
        -- الصلاحيات من user_module_permissions (أو افتراضي true إذا لم توجد)
        COALESCE(ump.can_view, true) as can_view,
        COALESCE(ump.can_create, false) as can_create,
        COALESCE(ump.can_edit, false) as can_edit,
        COALESCE(ump.can_delete, false) as can_delete,
        COALESCE(ump.can_export, false) as can_export,
        COALESCE(ump.can_import, false) as can_import,
        COALESCE(ump.can_approve, false) as can_approve,
        COALESCE(ump.can_manage_settings, false) as can_manage_settings
        
    FROM modules m
    LEFT JOIN tenant_modules tm 
        ON m.module_code = tm.module_code 
        AND tm.tenant_id = v_tenant_id
    LEFT JOIN user_module_permissions ump
        ON m.module_code = ump.module_code
        AND ump.user_id = p_user_id
        AND ump.tenant_id = v_tenant_id
        AND ump.company_id = v_company_id
    WHERE m.is_active = true
    ORDER BY m.display_order;
    
END;
$$;


--
-- Name: get_user_brand_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_brand_id(p_user_id uuid DEFAULT auth.uid()) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_product_id UUID;
    v_tenant_id UUID;
BEGIN
    -- الحصول على tenant_id للمستخدم
    SELECT tenant_id INTO v_tenant_id
    FROM public.user_profiles
    WHERE id = p_user_id;
    
    IF v_tenant_id IS NULL THEN
        RETURN NULL;
    END IF;
    
    -- الحصول على product_id من tenant
    SELECT product_id INTO v_product_id
    FROM public.tenants
    WHERE id = v_tenant_id;
    
    RETURN v_product_id;
EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
END;
$$;


