--
-- Name: get_user_companies(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_companies(p_user_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.companies
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
              SELECT c.* FROM companies c
              JOIN user_profiles up ON up.company_id = c.id
              WHERE up.id = COALESCE(p_user_id, auth.uid())
              UNION
              SELECT c.* FROM companies c
              JOIN super_admins sa ON sa.user_id = COALESCE(p_user_id, auth.uid()) AND sa.is_active = true;
            $$;


