--
-- Name: get_user_full_permissions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_full_permissions(p_user_id uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_roles JSONB;
    v_funds JSONB;
    v_warehouses JSONB;
    v_branches JSONB;
    v_level TEXT;
BEGIN
    -- Get role level
    v_level := get_user_role_level(p_user_id);
    
    -- Get roles
    SELECT jsonb_agg(jsonb_build_object(
        'role_code', r.code,
        'role_name', r.name_ar,
        'level', COALESCE(r.permissions->>'level', 'operations'),
        'permissions', r.permissions
    ))
    INTO v_roles
    FROM user_roles ur
    JOIN roles r ON ur.role_id = r.id
    WHERE ur.user_id = p_user_id
      AND ur.is_active = true;
    
    -- Get funds (only for non-admins)
    IF v_level NOT IN ('platform', 'tenant', 'company') THEN
        SELECT jsonb_agg(jsonb_build_object(
            'fund_id', ufp.fund_account_id,
            'can_deposit', ufp.can_deposit,
            'can_withdraw', ufp.can_withdraw,
            'is_primary', ufp.is_primary
        ))
        INTO v_funds
        FROM user_fund_permissions ufp
        WHERE ufp.user_id = p_user_id AND ufp.can_view = true;
    ELSE
        v_funds := '"all"'::jsonb;
    END IF;
    
    -- Get warehouses
    IF v_level NOT IN ('platform', 'tenant', 'company') THEN
        SELECT jsonb_agg(jsonb_build_object(
            'warehouse_id', uwp.warehouse_id,
            'is_keeper', uwp.is_keeper,
            'can_receive', uwp.can_receive,
            'can_issue', uwp.can_issue
        ))
        INTO v_warehouses
        FROM user_warehouse_permissions uwp
        WHERE uwp.user_id = p_user_id AND uwp.can_view = true;
    ELSE
        v_warehouses := '"all"'::jsonb;
    END IF;
    
    -- Get branches
    IF v_level NOT IN ('platform', 'tenant', 'company') THEN
        SELECT jsonb_agg(jsonb_build_object(
            'branch_id', ubp.branch_id,
            'is_primary', ubp.is_primary,
            'can_manage', ubp.can_manage
        ))
        INTO v_branches
        FROM user_branch_permissions ubp
        WHERE ubp.user_id = p_user_id AND ubp.can_access = true;
    ELSE
        v_branches := '"all"'::jsonb;
    END IF;
    
    -- Build result
    v_result := jsonb_build_object(
        'user_id', p_user_id,
        'is_super_admin', is_super_admin(p_user_id),
        'is_tenant_admin', is_tenant_admin(p_user_id),
        'is_company_admin', is_company_admin(p_user_id),
        'level', v_level,
        'roles', COALESCE(v_roles, '[]'::jsonb),
        'funds', COALESCE(v_funds, '[]'::jsonb),
        'warehouses', COALESCE(v_warehouses, '[]'::jsonb),
        'branches', COALESCE(v_branches, '[]'::jsonb)
    );
    
    RETURN v_result;
END;
$$;


--
-- Name: get_user_mfa_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_mfa_status(p_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(user_id uuid, full_name text, email text, native_mfa_verified boolean, profile_two_factor boolean, custom_mfa_enabled boolean, is_synced boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    BEGIN
      RETURN QUERY
      SELECT 
        up.id AS user_id,
        up.full_name,
        up.email,
        EXISTS(
          SELECT 1 FROM auth.mfa_factors mf 
          WHERE mf.user_id = up.id 
          AND mf.factor_type = 'totp' 
          AND mf.status = 'verified'
        ) AS native_mfa_verified,
        COALESCE(up.two_factor_enabled, false) AS profile_two_factor,
        COALESCE(mus.is_enabled, false) AS custom_mfa_enabled,
        -- Check if all sources agree
        (
          EXISTS(
            SELECT 1 FROM auth.mfa_factors mf 
            WHERE mf.user_id = up.id 
            AND mf.factor_type = 'totp' 
            AND mf.status = 'verified'
          ) = COALESCE(up.two_factor_enabled, false)
          AND
          EXISTS(
            SELECT 1 FROM auth.mfa_factors mf 
            WHERE mf.user_id = up.id 
            AND mf.factor_type = 'totp' 
            AND mf.status = 'verified'
          ) = COALESCE(mus.is_enabled, false)
        ) AS is_synced
      FROM user_profiles up
      LEFT JOIN mfa_user_settings mus ON mus.user_id = up.id
      WHERE (p_user_id IS NULL OR up.id = p_user_id);
    END;
    $$;


--
-- Name: get_user_module_permissions(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_module_permissions(p_user_id uuid, p_module_code character varying) RETURNS TABLE(can_view boolean, can_create boolean, can_edit boolean, can_delete boolean, can_export boolean, can_import boolean, can_approve boolean, can_manage_settings boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_company_id UUID;
    v_is_admin BOOLEAN;
BEGIN
    SELECT up.tenant_id, up.company_id, up.is_admin
    INTO v_tenant_id, v_company_id, v_is_admin
    FROM user_profiles up
    WHERE up.id = p_user_id;
    
    IF v_is_admin THEN
        RETURN QUERY SELECT true, true, true, true, true, true, true, true;
        RETURN;
    END IF;
    
    RETURN QUERY
    SELECT 
        ump.can_view,
        ump.can_create,
        ump.can_edit,
        ump.can_delete,
        ump.can_export,
        ump.can_import,
        ump.can_approve,
        ump.can_manage_settings
    FROM user_module_permissions ump
    WHERE ump.user_id = p_user_id
      AND ump.tenant_id = v_tenant_id
      AND ump.company_id = v_company_id
      AND ump.module_code = p_module_code
      AND ump.is_active = true
      AND (ump.expires_at IS NULL OR ump.expires_at > NOW());
    
    IF NOT FOUND THEN
        RETURN QUERY SELECT false, false, false, false, false, false, false, false;
    END IF;
END;
$$;


--
-- Name: get_user_permissions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_permissions(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_permissions JSONB := '{}'::jsonb;
    v_role_perms JSONB;
BEGIN
    FOR v_role_perms IN
        SELECT r.permissions
        FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE ur.user_id = p_user_id
          AND ur.is_active = true
          AND (ur.expires_at IS NULL OR ur.expires_at > NOW())
    LOOP
        -- Merge permissions (later ones override)
        v_permissions := v_permissions || v_role_perms;
    END LOOP;
    
    RETURN v_permissions;
END;
$$;


--
-- Name: get_user_product_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_product_id(p_user_id uuid DEFAULT auth.uid()) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN get_user_brand_id(p_user_id);
END;
$$;


--
-- Name: get_user_ptt_channel_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_ptt_channel_ids(p_user_id uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  -- HARDENED: identity is the authenticated caller (auth.uid()); the
  -- client-supplied p_user_id is IGNORED for real users so this cannot be
  -- steered to read another subscriber's PTT memberships. This function is
  -- SECURITY DEFINER and underpins RLS on nexa_ptt_members and
  -- nexa_ptt_channels (ptt_*_select/update/delete reference
  -- get_user_ptt_channel_ids(auth.uid())), so it MUST return ONLY the
  -- caller's own channel memberships. A trusted backend (service_role, where
  -- auth.uid() IS NULL) may still pass an explicit p_user_id.
  SELECT channel_id
  FROM public.nexa_ptt_members
  WHERE user_id = COALESCE(auth.uid(), p_user_id);
$$;


--
-- Name: get_user_role_level(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_role_level(p_user_id uuid DEFAULT auth.uid()) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_level TEXT;
BEGIN
    -- التحقق من super_admin أولاً
    IF is_super_admin(p_user_id) THEN
        RETURN 'platform';
    END IF;
    
    -- الحصول على أعلى مستوى
    SELECT COALESCE(
        (r.permissions->>'level')::TEXT,
        'operations'
    ) INTO v_level
    FROM user_roles ur
    JOIN roles r ON ur.role_id = r.id
    WHERE ur.user_id = p_user_id
      AND ur.is_active = true
    ORDER BY 
        CASE (r.permissions->>'level')::TEXT
            WHEN 'tenant' THEN 1
            WHEN 'company' THEN 2
            WHEN 'branch' THEN 3
            WHEN 'operations' THEN 4
            ELSE 5
        END
    LIMIT 1;
    
    RETURN COALESCE(v_level, 'none');
END;
$$;


--
-- Name: get_user_roles(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_roles(p_user_id uuid) RETURNS TABLE(role_id uuid, role_code text, role_name_ar text, role_name_en text, role_level text, is_active boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.id AS role_id,
        r.code AS role_code,
        r.name_ar AS role_name_ar,
        r.name_en AS role_name_en,
        r.level AS role_level,
        ur.is_active
    FROM user_roles ur
    JOIN roles r ON ur.role_id = r.id
    WHERE ur.user_id = p_user_id
      AND ur.is_active = true;
EXCEPTION
    WHEN OTHERS THEN
        -- Return empty on error
        RETURN;
END;
$$;


--
-- Name: get_user_special_permissions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_special_permissions(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_permissions JSONB := '{}'::jsonb;
    v_role_sp JSONB;
    v_is_super BOOLEAN := false;
BEGIN
    -- Check if user is super_admin / tenant_owner / company_owner
    SELECT EXISTS (
        SELECT 1 FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE ur.user_id = p_user_id
          AND ur.is_active = true
          AND r.code IN ('super_admin', 'tenant_owner', 'company_owner')
    ) INTO v_is_super;
    
    -- If super_admin / tenant_owner / company_owner, return all permissions as true
    IF v_is_super THEN
        RETURN '{
            "can_edit_posted_purchase": true,
            "can_edit_posted_sale": true,
            "can_edit_posted_journal": true,
            "can_delete_posted": true,
            "can_unpost": true,
            "can_edit_closed_period": true,
            "can_view_audit_log": true,
            "can_view_all_branches": true,
            "can_manage_roles": true,
            "can_approve_transactions": true,
            "can_view_cost_prices": true,
            "can_view_profit_margins": true,
            "can_export_data": true,
            "can_manage_containers": true
        }'::jsonb;
    END IF;
    
    -- Merge special_permissions from all active roles
    FOR v_role_sp IN
        SELECT COALESCE(r.special_permissions, '{}'::jsonb)
        FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE ur.user_id = p_user_id
          AND ur.is_active = true
          AND (ur.expires_at IS NULL OR ur.expires_at > NOW())
          AND r.special_permissions IS NOT NULL
    LOOP
        -- Merge: true overrides false (permissive merge)
        v_permissions := v_permissions || v_role_sp;
    END LOOP;
    
    RETURN v_permissions;
END;
$$;


--
-- Name: get_user_tenant_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_tenant_id(p_user_id uuid DEFAULT auth.uid()) RETURNS uuid
