--
-- Name: get_user_visible_modules(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_user_visible_modules(p_user_id uuid) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    result TEXT[];
BEGIN
    SELECT COALESCE(
        array_agg(DISTINCT unnest_module),
        ARRAY['dashboard']::TEXT[]
    ) INTO result
    FROM (
        SELECT unnest(r.visible_modules) as unnest_module
        FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE ur.user_id = p_user_id
          AND ur.is_active = true
    ) sub;
    
    RETURN COALESCE(result, ARRAY['dashboard']::TEXT[]);
END;
$$;


--
-- Name: get_warehouse_settings(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_warehouse_settings(p_tenant_id uuid, p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_settings RECORD;
BEGIN
    SELECT * INTO v_settings
    FROM warehouse_settings
    WHERE tenant_id = p_tenant_id
    AND company_id = p_company_id
    LIMIT 1;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'costing_method', 'fifo',
            'require_dispatch_approval', true,
            'default_reservation_hours', 48,
            'allow_negative_stock', false,
            'warn_dye_lot_mismatch', true
        );
    END IF;
    
    RETURN to_jsonb(v_settings);
END;
$$;


--
-- Name: get_workflow_settings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.get_workflow_settings(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_settings JSONB;
BEGIN
    SELECT to_jsonb(cws.*) INTO v_settings
    FROM company_workflow_settings cws
    WHERE cws.company_id = p_company_id
    LIMIT 1;

    -- Return defaults if no settings exist
    IF v_settings IS NULL THEN
        v_settings := jsonb_build_object(
            'require_manager_approval_quotation', false,
            'require_manager_approval_order', false,
            'require_manager_approval_invoice', false,
            'require_manager_approval_reservation', false,
            'approval_amount_threshold', 0,
            'auto_create_delivery_on_confirm', true,
            'allow_edit_after_confirm', false,
            'edit_after_confirm_roles', ARRAY['company_admin', 'tenant_owner'],
            'notify_warehouse_on_confirm', true,
            'notify_manager_on_save', false,
            'notify_channel', 'internal',
            'require_payment_for_confirmation', false,
            'min_payment_percent', 0,
            -- Posting settings
            'auto_post_invoice', false,
            'auto_post_delivery', false,
            'auto_post_receipt', false,
            'auto_post_return', false,
            'require_post_confirmation', true
        );
    END IF;

    RETURN v_settings;
END;
$$;


--
-- Name: handle_new_company(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.handle_new_company() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- الشجرة المحاسبية يتم إنشاؤها عبر apply_chart_template_to_company
    -- من register_new_subscriber — لا حاجة للإنشاء التلقائي هنا
    RAISE NOTICE 'Company created: % — chart will be set via registration wizard', NEW.id;
    RETURN NEW;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.user_profiles (id, email, full_name, role, company_id, tenant_id, phone)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', ''),
    'user',
    (NEW.raw_user_meta_data->>'company_id')::uuid,
    (NEW.raw_user_meta_data->>'tenant_id')::uuid,
    COALESCE(NEW.raw_user_meta_data->>'phone', '')
  )
  ON CONFLICT (id) DO UPDATE SET
    company_id = COALESCE(EXCLUDED.company_id, user_profiles.company_id),
    tenant_id = COALESCE(EXCLUDED.tenant_id, user_profiles.tenant_id),
    full_name = COALESCE(NULLIF(EXCLUDED.full_name, ''), user_profiles.full_name),
    phone = COALESCE(NULLIF(EXCLUDED.phone, ''), user_profiles.phone);
  RETURN NEW;
END;
$$;


--
-- Name: heartbeat_login_session(uuid, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.heartbeat_login_session(p_session_id uuid, p_country character varying DEFAULT NULL::character varying, p_city character varying DEFAULT NULL::character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    UPDATE tenant_login_sessions
    SET last_heartbeat = NOW(),
        country = COALESCE(p_country, country),
        city = COALESCE(p_city, city)
    WHERE id = p_session_id
      AND is_active = true;
END;
$$;


--
-- Name: increment_reserved_quantity(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.increment_reserved_quantity(p_item_id uuid, p_quantity numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    UPDATE shipment_items
    SET reserved_quantity = COALESCE(reserved_quantity, 0) + p_quantity,
        updated_at = NOW()
    WHERE id = p_item_id;
END;
$$;


--
-- Name: increment_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.increment_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.version := COALESCE(OLD.version, 0) + 1;
    RETURN NEW;
END;
$$;


--
-- Name: invite_user_by_email(text, text, uuid, uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.invite_user_by_email(p_email text, p_full_name text DEFAULT NULL::text, p_company_id uuid DEFAULT NULL::uuid, p_tenant_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid, p_role_ids uuid[] DEFAULT NULL::uuid[]) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_existing_profile RECORD;
    v_result JSON;
BEGIN
    -- 1. Check if user already exists in user_profiles
    SELECT id INTO v_existing_profile FROM user_profiles WHERE email = p_email LIMIT 1;
    
    IF v_existing_profile.id IS NOT NULL THEN
        v_user_id := v_existing_profile.id;
        
        -- Update profile fields if provided
        UPDATE user_profiles SET
            full_name = COALESCE(p_full_name, full_name),
            company_id = COALESCE(p_company_id, company_id),
            tenant_id = COALESCE(p_tenant_id, tenant_id),
            branch_id = COALESCE(p_branch_id, branch_id),
            updated_at = NOW()
        WHERE id = v_user_id;
    ELSE
        -- 2. Check if user exists in auth.users but no profile
        SELECT id INTO v_user_id FROM auth.users WHERE email = p_email LIMIT 1;
        
        IF v_user_id IS NOT NULL THEN
            -- Create profile for existing auth user
            INSERT INTO user_profiles (id, email, full_name, company_id, tenant_id, branch_id, is_active)
            VALUES (v_user_id, p_email, p_full_name, p_company_id, p_tenant_id, p_branch_id, true)
            ON CONFLICT (id) DO UPDATE SET
                full_name = COALESCE(p_full_name, user_profiles.full_name),
                company_id = COALESCE(p_company_id, user_profiles.company_id),
                tenant_id = COALESCE(p_tenant_id, user_profiles.tenant_id);
        ELSE
            -- 3. Create new auth user with generated password
            v_user_id := gen_random_uuid();
            
            INSERT INTO auth.users (
                id, instance_id, email, 
                encrypted_password, email_confirmed_at,
                raw_app_meta_data, raw_user_meta_data,
                aud, role, created_at, updated_at,
                confirmation_token
            ) VALUES (
                v_user_id,
                '00000000-0000-0000-0000-000000000000',
                p_email,
                crypt(gen_random_uuid()::text, gen_salt('bf')),
                NOW(),
                jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
                jsonb_build_object('full_name', COALESCE(p_full_name, ''), 'invited', true),
                'authenticated',
                'authenticated',
                NOW(),
                NOW(),
                encode(gen_random_bytes(32), 'hex')
            );
            
            -- Create user_profile
            INSERT INTO user_profiles (id, email, full_name, company_id, tenant_id, branch_id, is_active)
            VALUES (v_user_id, p_email, p_full_name, p_company_id, p_tenant_id, p_branch_id, true)
            ON CONFLICT (id) DO NOTHING;
            
            -- Create identity for email provider
            INSERT INTO auth.identities (
                id, user_id, provider_id, provider, identity_data, last_sign_in_at, created_at, updated_at
            ) VALUES (
                gen_random_uuid(), v_user_id, p_email, 'email',
                jsonb_build_object('email', p_email, 'sub', v_user_id::text),
                NOW(), NOW(), NOW()
            );
        END IF;
    END IF;
    
    -- 4. Assign roles
    IF p_role_ids IS NOT NULL AND array_length(p_role_ids, 1) > 0 THEN
        -- Remove old roles
        DELETE FROM user_roles WHERE user_id = v_user_id;
        
        -- Insert new roles
        INSERT INTO user_roles (user_id, role_id, tenant_id, company_id, is_active)
        SELECT v_user_id, unnest(p_role_ids), p_tenant_id, p_company_id, true
        ON CONFLICT (user_id, role_id) DO UPDATE SET is_active = true;
    END IF;
    
    v_result := json_build_object(
        'success', true,
        'user_id', v_user_id,
        'email', p_email,
        'is_new', v_existing_profile.id IS NULL
    );
    
    RETURN v_result;
END;
$$;


--
-- Name: invite_user_by_email(text, text, uuid, uuid, uuid, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.invite_user_by_email(p_email text, p_full_name text DEFAULT NULL::text, p_company_id uuid DEFAULT NULL::uuid, p_tenant_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid, p_role_ids uuid[] DEFAULT NULL::uuid[], p_phone text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_existing_profile RECORD;
    v_result JSON;
BEGIN
    -- 1. Check if user already exists in user_profiles
    SELECT id INTO v_existing_profile FROM user_profiles WHERE email = p_email LIMIT 1;
    
    IF v_existing_profile.id IS NOT NULL THEN
        v_user_id := v_existing_profile.id;
        
        -- Update profile fields if provided
        UPDATE user_profiles SET
            full_name = COALESCE(p_full_name, full_name),
            company_id = COALESCE(p_company_id, company_id),
            tenant_id = COALESCE(p_tenant_id, tenant_id),
            branch_id = COALESCE(p_branch_id, branch_id),
            phone = COALESCE(p_phone, phone),
            updated_at = NOW()
        WHERE id = v_user_id;
    ELSE
        -- 2. Check if user exists in auth.users but no profile
        SELECT id INTO v_user_id FROM auth.users WHERE email = p_email LIMIT 1;
        
        IF v_user_id IS NOT NULL THEN
            INSERT INTO user_profiles (id, email, full_name, company_id, tenant_id, branch_id, phone, is_active)
            VALUES (v_user_id, p_email, p_full_name, p_company_id, p_tenant_id, p_branch_id, p_phone, true)
            ON CONFLICT (id) DO UPDATE SET
                full_name = COALESCE(p_full_name, user_profiles.full_name),
                company_id = COALESCE(p_company_id, user_profiles.company_id),
                tenant_id = COALESCE(p_tenant_id, user_profiles.tenant_id),
                phone = COALESCE(p_phone, user_profiles.phone);
        ELSE
            -- 3. Create new auth user
            v_user_id := gen_random_uuid();
            
            INSERT INTO auth.users (
                id, instance_id, email, 
                encrypted_password, email_confirmed_at,
                raw_app_meta_data, raw_user_meta_data,
                aud, role, created_at, updated_at,
                confirmation_token, phone
            ) VALUES (
                v_user_id,
                '00000000-0000-0000-0000-000000000000',
                p_email,
                crypt(gen_random_uuid()::text, gen_salt('bf')),
                NOW(),
                jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
                jsonb_build_object('full_name', COALESCE(p_full_name, ''), 'invited', true, 'phone', COALESCE(p_phone, '')),
                'authenticated',
                'authenticated',
                NOW(),
                NOW(),
                encode(gen_random_bytes(32), 'hex'),
                COALESCE(p_phone, '')
            );
            
            INSERT INTO user_profiles (id, email, full_name, company_id, tenant_id, branch_id, phone, is_active)
            VALUES (v_user_id, p_email, p_full_name, p_company_id, p_tenant_id, p_branch_id, p_phone, true)
            ON CONFLICT (id) DO NOTHING;
            
            INSERT INTO auth.identities (
                id, user_id, provider_id, provider, identity_data, last_sign_in_at, created_at, updated_at
            ) VALUES (
                gen_random_uuid(), v_user_id, p_email, 'email',
                jsonb_build_object('email', p_email, 'sub', v_user_id::text),
                NOW(), NOW(), NOW()
            );
        END IF;
    END IF;
    
    -- 4. Assign roles
    IF p_role_ids IS NOT NULL AND array_length(p_role_ids, 1) > 0 THEN
        DELETE FROM user_roles WHERE user_id = v_user_id;
        INSERT INTO user_roles (user_id, role_id, tenant_id, company_id, is_active)
        SELECT v_user_id, unnest(p_role_ids), p_tenant_id, p_company_id, true
        ON CONFLICT (user_id, role_id) DO UPDATE SET is_active = true;
    END IF;
    
    v_result := json_build_object(
        'success', true,
        'user_id', v_user_id,
        'email', p_email,
        'is_new', v_existing_profile.id IS NULL
    );
    
    RETURN v_result;
END;
$$;


--
-- Name: is_admin_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_admin_user(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE ur.user_id = p_user_id
          AND ur.is_active = true
          AND r.code IN ('super_admin', 'tenant_owner', 'company_admin')
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN false;
END;
$$;


--
-- Name: is_company_admin(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_company_admin(p_user_id uuid DEFAULT auth.uid(), p_company_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    IF is_super_admin(p_user_id) OR is_tenant_admin(p_user_id) THEN
        RETURN true;
    END IF;
    
    RETURN EXISTS (
        SELECT 1 FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE ur.user_id = p_user_id
          AND r.code IN ('company_owner', 'company_admin')
          AND ur.is_active = true
    );
END;
$$;


