--
-- Name: is_mfa_required(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_mfa_required(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_system_enforce_all BOOLEAN;
    v_system_enforce_admins BOOLEAN;
    v_enforced_roles TEXT[];
    v_user_roles TEXT[];
BEGIN
    -- Get system settings
    SELECT enforce_for_all, enforce_for_admins, enforced_roles 
    INTO v_system_enforce_all, v_system_enforce_admins, v_enforced_roles
    FROM mfa_system_settings LIMIT 1;
    
    -- If enforced for all
    IF COALESCE(v_system_enforce_all, false) THEN
        RETURN true;
    END IF;
    
    -- Get user roles from the new schema
    SELECT array_agg(r.code::TEXT) INTO v_user_roles
    FROM user_roles ur
    JOIN roles r ON ur.role_id = r.id
    WHERE ur.user_id = p_user_id
      AND ur.is_active = true;
    
    -- Check if user has an enforced role
    IF v_user_roles IS NOT NULL AND v_enforced_roles IS NOT NULL THEN
        IF v_user_roles && v_enforced_roles THEN
            RETURN true;
        END IF;
    END IF;
    
    -- If enforced for admins
    IF COALESCE(v_system_enforce_admins, false) AND v_user_roles IS NOT NULL THEN
        IF v_user_roles && ARRAY['super_admin', 'tenant_owner', 'company_admin']::TEXT[] THEN
            RETURN true;
        END IF;
    END IF;
    
    RETURN false;
EXCEPTION
    WHEN OTHERS THEN
        -- If any error, return false (don't block user)
        RETURN false;
END;
$$;


--
-- Name: is_partner_or_reseller(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_partner_or_reseller(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM public.partners p
        JOIN public.user_profiles up ON up.email = p.email
        WHERE up.id = p_user_id
          AND p.is_active = true
    );
EXCEPTION WHEN OTHERS THEN
    RETURN false;
END;
$$;


--
-- Name: is_platform_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_platform_admin(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  cache_key text;
  cached text;
  result boolean;
BEGIN
  -- Build per-user cache key
  cache_key := 'app.ipa_' || COALESCE(replace(p_user_id::text, '-', ''), 'anon');

  -- Try reading from transaction-local cache
  BEGIN
    cached := current_setting(cache_key, true);
    IF cached IS NOT NULL AND cached <> '' THEN
      RETURN cached = 't';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- Platform Owner check (itself cached)
  IF is_platform_owner(p_user_id) THEN
    PERFORM set_config(cache_key, 't', true);
    RETURN true;
  END IF;

  -- Role check
  result := EXISTS (
    SELECT 1 FROM public.user_roles ur
    JOIN public.roles r ON ur.role_id = r.id
    WHERE ur.user_id = p_user_id
      AND r.code IN ('platform_admin', 'support_senior')
      AND ur.is_active = true
  );

  PERFORM set_config(cache_key, CASE WHEN result THEN 't' ELSE 'f' END, true);
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$$;


--
-- Name: is_platform_owner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_platform_owner(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  cache_key text;
  cached text;
  result boolean;
BEGIN
  -- Build per-user cache key
  cache_key := 'app.ipo_' || COALESCE(replace(p_user_id::text, '-', ''), 'anon');

  -- Try reading from transaction-local cache
  BEGIN
    cached := current_setting(cache_key, true);
    IF cached IS NOT NULL AND cached <> '' THEN
      RETURN cached = 't';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Setting doesn't exist yet — that's fine
    NULL;
  END;

  -- Real check
  result := EXISTS (
    SELECT 1 FROM public.super_admins
    WHERE user_id = p_user_id
      AND is_active = true
  );

  -- Cache for remainder of this transaction
  PERFORM set_config(cache_key, CASE WHEN result THEN 't' ELSE 'f' END, true);

  RETURN result;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$$;


--
-- Name: is_reseller(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_reseller(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
