--
-- Name: is_same_brand(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_same_brand(p_tenant_id uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
      DECLARE
          v_user_brand_id UUID;
          v_tenant_brand_id UUID;
          v_user_tenant_id UUID;
      BEGIN
          -- Platform Owner sees all brands
          IF is_platform_owner(p_user_id) THEN
              RETURN true;
          END IF;
          
          -- If user belongs to this tenant, always allow (self-access)
          SELECT tenant_id INTO v_user_tenant_id
          FROM public.user_profiles
          WHERE id = p_user_id;
          
          IF v_user_tenant_id = p_tenant_id THEN
              RETURN true;
          END IF;
          
          -- Get user's brand
          v_user_brand_id := get_user_brand_id(p_user_id);
          
          -- Get tenant's brand (product_id)
          SELECT product_id INTO v_tenant_brand_id
          FROM public.tenants
          WHERE id = p_tenant_id;
          
          -- If tenant has no brand (new/unassigned), allow own-tenant access
          -- This handles new registrations before brand assignment
          IF v_tenant_brand_id IS NULL THEN
              RETURN v_user_tenant_id = p_tenant_id;
          END IF;
          
          -- Partner/Reseller: check allowed brands
          IF is_partner_or_reseller(p_user_id) THEN
              RETURN v_tenant_brand_id = ANY(get_partner_allowed_brand_ids(p_user_id));
          END IF;
          
          -- Normal user: brand must match
          RETURN v_user_brand_id IS NOT NULL 
             AND v_tenant_brand_id IS NOT NULL 
             AND v_user_brand_id = v_tenant_brand_id;
      EXCEPTION WHEN OTHERS THEN
          RETURN false;
      END;
      $$;


--
-- Name: is_store_tenant_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_store_tenant_member(p_store_id uuid) RETURNS boolean
