--
-- Name: is_super_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_super_admin(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE ur.user_id = p_user_id
          AND ur.is_active = true
          AND r.code = 'super_admin'
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN false;
END;
$$;


--
-- Name: is_tenant_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_tenant_admin(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    IF is_super_admin(p_user_id) THEN
        RETURN true;
    END IF;
    
    RETURN EXISTS (
        SELECT 1 FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE ur.user_id = p_user_id
          AND r.code = 'tenant_admin'
          AND ur.is_active = true
    );
END;
$$;


--
-- Name: is_tenant_owner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_tenant_owner(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_user_email TEXT;
    v_tenant_id UUID;
    v_owner_email TEXT;
BEGIN
    -- Super Admin يرى كل شيء
    IF is_super_admin(p_user_id) THEN
        RETURN true;
    END IF;
    
    -- Get user's email and tenant_id
    SELECT up.email, c.tenant_id INTO v_user_email, v_tenant_id
    FROM user_profiles up
    LEFT JOIN companies c ON up.company_id = c.id
    WHERE up.id = p_user_id;
    
    IF v_tenant_id IS NULL THEN
        RETURN false;
    END IF;
    
    -- Check if user is the tenant owner
    SELECT owner_email INTO v_owner_email
    FROM tenants
    WHERE id = v_tenant_id;
    
    RETURN v_user_email = v_owner_email;
EXCEPTION WHEN OTHERS THEN
    RETURN false;
END;
$$;


--
-- Name: is_valid_stage_transition(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_valid_stage_transition(p_type text, p_from text, p_to text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    IF p_type = 'purchase' THEN
        RETURN (p_from, p_to) IN (
            ('draft', 'quotation'),
            ('draft', 'order'),
            ('draft', 'invoice'),
            ('quotation', 'order'),
            ('quotation', 'invoice'),
            ('order', 'approved'),
            ('approved', 'receipt'),
            ('approved', 'invoice'),
            ('receipt', 'invoice'),
            ('invoice', 'posted'),
            ('posted', 'partial_paid'),
            ('posted', 'paid'),
            ('partial_paid', 'paid'),
            ('draft', 'cancelled'),
            ('quotation', 'cancelled'),
            ('order', 'cancelled'),
            ('approved', 'cancelled'),
            ('receipt', 'cancelled'),
            ('invoice', 'cancelled'),
            ('cancelled', 'draft')
        );
    END IF;

    IF p_type = 'sale' THEN
        RETURN (p_from, p_to) IN (
            ('draft', 'quotation'),
            ('draft', 'order'),
            ('draft', 'invoice'),
            ('quotation', 'reservation'),
            ('quotation', 'order'),
            ('reservation', 'order'),
            ('order', 'delivery'),
            ('order', 'invoice'),
            ('delivery', 'invoice'),
            ('invoice', 'posted'),
            ('posted', 'partial_paid'),
            ('posted', 'paid'),
            ('partial_paid', 'paid'),
            ('draft', 'cancelled'),
            ('quotation', 'cancelled'),
            ('reservation', 'cancelled'),
            ('order', 'cancelled'),
            ('delivery', 'cancelled'),
            ('invoice', 'cancelled'),
            ('cancelled', 'draft')
        );
    END IF;

    RETURN false;
END;
$$;


--
-- Name: is_whitelabel_partner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.is_whitelabel_partner(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM public.partners p
        JOIN public.user_profiles up ON up.email = p.email
        WHERE up.id = p_user_id
          AND p.partner_type = 'whitelabel'
          AND p.is_active = true
    );
EXCEPTION WHEN OTHERS THEN
    RETURN false;
END;
$$;


--
-- Name: licensing_activate(uuid, text, text, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.licensing_activate(p_license_id uuid, p_hardware_id text, p_signature text, p_is_transfer boolean DEFAULT false, p_activated_at timestamp with time zone DEFAULT now()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  UPDATE licensing.licenses SET
    status = 'active',
    hardware_id = p_hardware_id,
    activated_at = CASE WHEN activated_at IS NULL THEN p_activated_at ELSE activated_at END,
    last_heartbeat_at = NOW(),
    signature = p_signature,
    transfer_count = CASE WHEN p_is_transfer THEN transfer_count + 1 ELSE transfer_count END
  WHERE id = p_license_id;

  RETURN FOUND;
END;
$$;


