--
-- Name: licensing_create_license(uuid, text, integer, integer, integer, integer, text[], boolean, boolean, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.licensing_create_license(p_customer_id uuid, p_tier text DEFAULT 'pro'::text, p_max_users integer DEFAULT 15, p_max_companies integer DEFAULT 5, p_max_warehouses integer DEFAULT 10, p_max_storage_gb integer DEFAULT 50, p_enabled_modules text[] DEFAULT ARRAY['sales'::text, 'purchases'::text, 'warehouse'::text, 'accounting'::text], p_custom_branding boolean DEFAULT true, p_cloud_backup boolean DEFAULT true, p_api_access boolean DEFAULT true, p_duration_days integer DEFAULT 365, p_max_transfers integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_license licensing.licenses;
  v_key TEXT;
  v_chars TEXT := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  v_part1 TEXT := '';
  v_part2 TEXT := '';
  v_i INT;
BEGIN
  -- Generate license key
  FOR v_i IN 1..5 LOOP
    v_part1 := v_part1 || substr(v_chars, floor(random() * length(v_chars) + 1)::int, 1);
    v_part2 := v_part2 || substr(v_chars, floor(random() * length(v_chars) + 1)::int, 1);
  END LOOP;
  v_key := 'LIC-' || EXTRACT(YEAR FROM NOW())::TEXT || '-' || v_part1 || '-' || v_part2;

  INSERT INTO licensing.licenses (
    license_key, customer_id, tier, status,
    max_users, max_companies, max_warehouses, max_storage_gb,
    enabled_modules, custom_branding, cloud_backup, api_access,
    expires_at, max_transfers
  ) VALUES (
    v_key, p_customer_id, p_tier, 'pending',
    p_max_users, p_max_companies, p_max_warehouses, p_max_storage_gb,
    p_enabled_modules, p_custom_branding, p_cloud_backup, p_api_access,
    NOW() + (p_duration_days || ' days')::INTERVAL, p_max_transfers
  )
  RETURNING * INTO v_license;

  -- Log in audit
  INSERT INTO licensing.audit_log (license_id, action, details, performed_by)
  VALUES (v_license.id, 'license_created', jsonb_build_object('tier', p_tier, 'key', v_key), 'saas_admin');

  RETURN row_to_json(v_license)::jsonb;
END;
$$;


--
-- Name: licensing_extend(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.licensing_extend(p_license_id uuid, p_days integer DEFAULT 365) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_license licensing.licenses;
  v_new_expiry TIMESTAMPTZ;
BEGIN
  SELECT * INTO v_license FROM licensing.licenses WHERE id = p_license_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'License not found');
  END IF;

  -- If expired, extend from now; if active, extend from current expiry
  IF v_license.expires_at < NOW() THEN
    v_new_expiry := NOW() + (p_days || ' days')::INTERVAL;
  ELSE
    v_new_expiry := v_license.expires_at + (p_days || ' days')::INTERVAL;
  END IF;

  UPDATE licensing.licenses SET
    expires_at = v_new_expiry,
    status = 'active',
    updated_at = NOW()
  WHERE id = p_license_id;

  INSERT INTO licensing.audit_log (action, entity_type, entity_id, old_values, new_values, notes)
  VALUES ('extend', 'license', p_license_id,
    jsonb_build_object('expires_at', v_license.expires_at),
    jsonb_build_object('expires_at', v_new_expiry, 'days_added', p_days),
    'Extended by ' || p_days || ' days'
  );

  RETURN jsonb_build_object(
    'success', true,
    'new_expiry', v_new_expiry,
    'days_added', p_days
  );
END;
$$;


--
-- Name: licensing_find_by_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.licensing_find_by_key(p_license_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'id', l.id,
    'license_key', l.license_key,
    'customer_id', l.customer_id,
    'tier', l.tier,
    'max_users', l.max_users,
    'max_companies', l.max_companies,
    'max_warehouses', l.max_warehouses,
    'max_storage_gb', l.max_storage_gb,
    'enabled_modules', l.enabled_modules,
    'custom_branding', l.custom_branding,
    'cloud_backup', l.cloud_backup,
    'api_access', l.api_access,
    'binding_type', l.binding_type,
    'max_transfers', l.max_transfers,
    'transfer_count', l.transfer_count,
    'status', l.status,
    'hardware_id', l.hardware_id,
    'activated_at', l.activated_at,
    'expires_at', l.expires_at,
    'grace_period_days', l.grace_period_days,
    'last_heartbeat_at', l.last_heartbeat_at,
    'app_version', l.app_version,
    'signature', l.signature,
    'customer', jsonb_build_object(
      'id', c.id,
      'name', c.name,
      'email', c.email,
      'company_name', c.company_name
    )
  ) INTO result
  FROM licensing.licenses l
  LEFT JOIN licensing.customers c ON c.id = l.customer_id
  WHERE l.license_key = p_license_key;

  RETURN result;
END;
$$;


