    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN (
    SELECT COALESCE(jsonb_agg(
      row_to_json(a)::jsonb || jsonb_build_object(
        'license_key', l.license_key,
        'customer_name', c.company_name
      )
      ORDER BY a.created_at DESC
    ), '[]'::jsonb)
    FROM (SELECT * FROM licensing.license_activations ORDER BY created_at DESC LIMIT p_limit) a
    LEFT JOIN licensing.licenses l ON l.id = a.license_id
    LEFT JOIN licensing.customers c ON c.id = l.customer_id
  );
END;
$$;


