--
-- Name: licensing_heartbeat(text, text, text, text, integer, integer, integer, numeric, numeric, numeric, numeric, numeric, numeric, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.licensing_heartbeat(p_license_key text, p_hardware_id text, p_app_version text DEFAULT NULL::text, p_ip_address text DEFAULT NULL::text, p_users_active integer DEFAULT 0, p_companies_count integer DEFAULT 0, p_invoices_count integer DEFAULT 0, p_db_size_mb numeric DEFAULT 0, p_storage_used_mb numeric DEFAULT 0, p_cpu_percent numeric DEFAULT NULL::numeric, p_ram_used_gb numeric DEFAULT NULL::numeric, p_ram_total_gb numeric DEFAULT NULL::numeric, p_disk_used_percent numeric DEFAULT NULL::numeric, p_services_status jsonb DEFAULT '{}'::jsonb, p_errors jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_license licensing.licenses%ROWTYPE;
  v_days_remaining INT;
  v_is_grace BOOLEAN;
  v_command TEXT := 'OK';
  v_warning TEXT := NULL;
  v_latest_version RECORD;
  v_update_available JSONB := NULL;
  v_fingerprint TEXT;
BEGIN
  -- Find license
  SELECT * INTO v_license FROM licensing.licenses WHERE license_key = p_license_key;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('accepted', false, 'code', 'NOT_FOUND');
  END IF;

  -- Build stable fingerprint for comparison
  IF p_hardware_id ~ '^CPU-[a-f0-9]+-MAC-[a-f0-9]+-DISK-[a-f0-9]+$' THEN
    v_fingerprint := regexp_replace(p_hardware_id, '-MAC-[a-f0-9]+', '');
  ELSE
    v_fingerprint := p_hardware_id;
  END IF;

  -- Verify hardware (use stable fingerprint matching)
  IF v_license.hardware_id IS NOT NULL 
     AND v_license.hardware_id != p_hardware_id 
     AND (v_license.stable_fingerprint IS NULL OR v_license.stable_fingerprint != v_fingerprint)
  THEN
    RETURN jsonb_build_object('accepted', false, 'code', 'HARDWARE_MISMATCH');
  END IF;

  -- Check status
  IF v_license.status IN ('revoked', 'suspended') THEN
    RETURN jsonb_build_object('accepted', false, 'code', upper(v_license.status), 'command', 'STOP');
  END IF;

  -- Save heartbeat
  INSERT INTO licensing.license_heartbeats (
    license_id, license_key, hardware_id, app_version, ip_address,
    users_active, companies_count, invoices_count, db_size_mb, storage_used_mb,
    cpu_percent, ram_used_gb, ram_total_gb, disk_used_percent, services_status, errors
  ) VALUES (
    v_license.id, p_license_key, p_hardware_id, p_app_version, p_ip_address,
    p_users_active, p_companies_count, p_invoices_count, p_db_size_mb, p_storage_used_mb,
    p_cpu_percent, p_ram_used_gb, p_ram_total_gb, p_disk_used_percent, p_services_status, p_errors
  );

  -- Update last heartbeat + hardware_id (keep fresh)
  UPDATE licensing.licenses SET 
    last_heartbeat_at = NOW(),
    hardware_id = p_hardware_id,
    stable_fingerprint = COALESCE(stable_fingerprint, v_fingerprint),
    app_version = COALESCE(p_app_version, app_version)
  WHERE id = v_license.id;

  -- Calculate days
  v_days_remaining := CEIL(EXTRACT(EPOCH FROM (v_license.expires_at - NOW())) / 86400);
  v_is_grace := NOW() > v_license.expires_at;

  IF v_days_remaining <= 0 THEN
    DECLARE grace_left INT := v_license.grace_period_days - ABS(v_days_remaining);
    BEGIN
      IF grace_left <= 0 THEN v_command := 'STOP';
      ELSE v_command := 'WARN'; v_warning := 'الترخيص منتهي — متبقي ' || grace_left || ' يوم فترة سماح';
      END IF;
    END;
  ELSIF v_days_remaining <= 14 THEN
    v_command := 'WARN';
    v_warning := 'الترخيص ينتهي خلال ' || v_days_remaining || ' يوم';
  END IF;

  -- Check for updates
  IF p_app_version IS NOT NULL THEN
    SELECT version, is_required, docker_tag, changelog_ar
    INTO v_latest_version
    FROM licensing.app_versions
    WHERE release_type = 'stable'
    ORDER BY released_at DESC LIMIT 1;

    IF FOUND AND v_latest_version.version != p_app_version THEN
      v_update_available := jsonb_build_object(
        'version', v_latest_version.version,
        'is_required', v_latest_version.is_required,
        'docker_tag', v_latest_version.docker_tag,
        'changelog', v_latest_version.changelog_ar
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'accepted', true,
    'command', v_command,
    'warning', v_warning,
    'days_remaining', v_days_remaining,
    'grace_period', v_is_grace,
    'update_available', v_update_available,
    'server_time', NOW()
  );
END;
$_$;


