--
-- Name: licensing_upgrade_tier(uuid, text, integer, integer, integer, integer, jsonb, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.licensing_upgrade_tier(p_license_id uuid, p_new_tier text, p_max_users integer DEFAULT NULL::integer, p_max_companies integer DEFAULT NULL::integer, p_max_warehouses integer DEFAULT NULL::integer, p_max_storage_gb integer DEFAULT NULL::integer, p_enabled_modules jsonb DEFAULT NULL::jsonb, p_custom_branding boolean DEFAULT NULL::boolean, p_cloud_backup boolean DEFAULT NULL::boolean, p_api_access boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_license licensing.licenses;
  v_old_tier TEXT;
BEGIN
  SELECT * INTO v_license FROM licensing.licenses WHERE id = p_license_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'License not found');
  END IF;

  v_old_tier := v_license.tier;

  UPDATE licensing.licenses SET
    tier = p_new_tier,
    max_users = COALESCE(p_max_users, max_users),
    max_companies = COALESCE(p_max_companies, max_companies),
    max_warehouses = COALESCE(p_max_warehouses, max_warehouses),
    max_storage_gb = COALESCE(p_max_storage_gb, max_storage_gb),
    enabled_modules = COALESCE(p_enabled_modules, enabled_modules),
    custom_branding = COALESCE(p_custom_branding, custom_branding),
    cloud_backup = COALESCE(p_cloud_backup, cloud_backup),
    api_access = COALESCE(p_api_access, api_access),
    updated_at = NOW()
  WHERE id = p_license_id;

  -- Log in audit
  INSERT INTO licensing.audit_log (action, entity_type, entity_id, old_values, new_values, notes)
  VALUES ('upgrade', 'license', p_license_id, 
    jsonb_build_object('tier', v_old_tier),
    jsonb_build_object('tier', p_new_tier),
    'Tier upgraded from ' || v_old_tier || ' to ' || p_new_tier
  );

  RETURN jsonb_build_object(
    'success', true,
    'old_tier', v_old_tier,
    'new_tier', p_new_tier
  );
END;
$$;


--
-- Name: licensing_validate(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.licensing_validate(p_license_key text, p_hardware_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_license licensing.licenses%ROWTYPE;
  v_days_remaining INT;
  v_is_grace BOOLEAN;
  v_is_expired BOOLEAN;
BEGIN
  SELECT * INTO v_license FROM licensing.licenses WHERE license_key = p_license_key;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'code', 'NOT_FOUND');
  END IF;

  IF v_license.status IN ('revoked', 'suspended') THEN
    RETURN jsonb_build_object('valid', false, 'status', v_license.status, 'code', upper(v_license.status));
  END IF;

  IF v_license.hardware_id IS NOT NULL AND v_license.hardware_id != p_hardware_id THEN
    RETURN jsonb_build_object('valid', false, 'code', 'HARDWARE_MISMATCH');
  END IF;

  v_days_remaining := CEIL(EXTRACT(EPOCH FROM (v_license.expires_at - NOW())) / 86400);
  v_is_grace := NOW() > v_license.expires_at;
  v_is_expired := EXTRACT(EPOCH FROM (NOW() - v_license.expires_at)) > (v_license.grace_period_days * 86400);

  IF v_is_expired THEN
    RETURN jsonb_build_object('valid', false, 'code', 'EXPIRED', 'days_remaining', v_days_remaining);
  END IF;

  RETURN jsonb_build_object(
    'valid', true,
    'status', CASE WHEN v_is_grace THEN 'grace_period' ELSE 'active' END,
    'tier', v_license.tier,
    'days_remaining', v_days_remaining,
    'expires_at', v_license.expires_at,
    'grace_period', v_is_grace,
    'limits', jsonb_build_object(
      'max_users', v_license.max_users,
      'max_companies', v_license.max_companies,
      'max_warehouses', v_license.max_warehouses,
      'max_storage_gb', v_license.max_storage_gb,
      'enabled_modules', v_license.enabled_modules,
      'custom_branding', v_license.custom_branding,
      'cloud_backup', v_license.cloud_backup,
      'api_access', v_license.api_access
    )
  );
END;
$$;


--
-- Name: link_existing_customer_to_auth(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.link_existing_customer_to_auth(p_customer_id uuid, p_auth_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_customer_email VARCHAR;
    v_tenant_id UUID;
    v_company_id UUID;
    v_uid  uuid := auth.uid();
    v_role text := auth.role();
    v_caller_email text;
BEGIN
    SELECT email, tenant_id, company_id
      INTO v_customer_email, v_tenant_id, v_company_id
    FROM customers WHERE id = p_customer_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Customer not found'; END IF;

    -- بوّابة ملكية (تتجاوز للخلفية)
    IF NOT (v_role = 'service_role' OR v_role IS NULL) THEN
        IF v_uid IS NULL OR v_uid <> p_auth_user_id THEN
            RAISE EXCEPTION 'link_existing_customer_to_auth: may only link your own account';
        END IF;
        SELECT email INTO v_caller_email FROM auth.users WHERE id = v_uid;
        IF v_caller_email IS NULL OR v_customer_email IS NULL
           OR lower(v_caller_email) <> lower(v_customer_email) THEN
            RAISE EXCEPTION 'link_existing_customer_to_auth: email mismatch';
        END IF;
    END IF;

    UPDATE customers SET auth_user_id = p_auth_user_id WHERE id = p_customer_id;
    INSERT INTO user_profiles (id, email, role, tenant_id, company_id, customer_id)
    VALUES (p_auth_user_id, v_customer_email, 'customer', v_tenant_id, v_company_id, p_customer_id)
    ON CONFLICT (id) DO UPDATE SET customer_id = EXCLUDED.customer_id, role = 'customer';
    RETURN TRUE;
END;
$$;


--
-- Name: link_user_to_tenant(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.link_user_to_tenant(p_tenant_id uuid, p_user_id uuid, p_role character varying DEFAULT 'member'::character varying) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_link_id UUID;
BEGIN
    INSERT INTO tenant_users (tenant_id, user_id, role)
    VALUES (p_tenant_id, p_user_id, p_role)
    ON CONFLICT (tenant_id, user_id) 
    DO UPDATE SET 
        role = EXCLUDED.role,
        is_active = true,
        updated_at = NOW()
    RETURNING id INTO v_link_id;
    
    RETURN v_link_id;
END;
$$;


--
-- Name: lock_subscription(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.lock_subscription(p_subscription_id uuid, p_reason text DEFAULT 'Payment overdue'::text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE subscriptions
    SET 
        status = 'locked',
        locked_at = NOW(),
        lock_reason = p_reason,
        updated_at = NOW()
    WHERE id = p_subscription_id
    AND locked_at IS NULL;
    
    RETURN FOUND;
END;
$$;


--
-- Name: log_audit(character varying, character varying, uuid, character varying, jsonb, jsonb, jsonb, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.log_audit(p_action character varying, p_entity_type character varying, p_entity_id uuid DEFAULT NULL::uuid, p_entity_name character varying DEFAULT NULL::character varying, p_old_values jsonb DEFAULT NULL::jsonb, p_new_values jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb, p_severity character varying DEFAULT 'info'::character varying) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_audit_id UUID;
    v_changes JSONB;
BEGIN
    -- حساب التغييرات
    IF p_old_values IS NOT NULL AND p_new_values IS NOT NULL THEN
        SELECT jsonb_object_agg(key, value)
        INTO v_changes
        FROM jsonb_each(p_new_values)
        WHERE p_old_values -> key IS DISTINCT FROM value;
    END IF;
    
    INSERT INTO audit_logs (
        tenant_id,
        user_id,
        action,
        entity_type,
        entity_id,
        entity_name,
        old_values,
        new_values,
        changes,
        metadata,
        severity
    ) VALUES (
        get_current_tenant_id(),
        auth.uid(),
        p_action,
        p_entity_type,
        p_entity_id,
        p_entity_name,
        p_old_values,
        p_new_values,
        v_changes,
        p_metadata,
        p_severity
    )
    RETURNING id INTO v_audit_id;
    
    RETURN v_audit_id;
END;
$$;


--
-- Name: log_sensitive_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.log_sensitive_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_changes JSONB;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        v_changes := jsonb_build_object('old', to_jsonb(OLD), 'new', to_jsonb(NEW));
    ELSIF TG_OP = 'DELETE' THEN
        v_changes := to_jsonb(OLD);
    ELSIF TG_OP = 'INSERT' THEN
        v_changes := to_jsonb(NEW);
    END IF;

    BEGIN
        INSERT INTO public.audit_logs (
            user_id, action, entity_type, entity_id, changes, created_at
        ) VALUES (
            v_user_id, TG_OP, TG_TABLE_NAME, COALESCE(NEW.id, OLD.id)::text, v_changes, NOW()
        );
    EXCEPTION WHEN OTHERS THEN
        -- Silently ignore audit log errors to not block operations
        NULL;
    END;

    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: log_subscription_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.log_subscription_status_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO subscription_status_history (
            subscription_id,
            tenant_id,
            old_status,
            new_status,
            reason
        ) VALUES (
            NEW.id,
            NEW.tenant_id,
            OLD.status,
            NEW.status,
            NEW.lock_reason
        );
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: mark_insights_stale(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.mark_insights_stale() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_company_id UUID;
BEGIN
    -- Get company_id from the affected row
    v_company_id := COALESCE(NEW.company_id, OLD.company_id);
    
    IF v_company_id IS NOT NULL THEN
        UPDATE company_insights 
        SET is_stale = TRUE, updated_at = NOW()
        WHERE company_id = v_company_id;
    END IF;
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: mark_overdue_tasks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.mark_overdue_tasks() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE ai_tasks
    SET status = 'overdue'
    WHERE status IN ('pending', 'in_progress')
    AND due_date < CURRENT_DATE;
END;
$$;


--
-- Name: market_apply_analysis(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.market_apply_analysis(p_id uuid, p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE refined text := p->>'refined_role';
BEGIN
  UPDATE market_companies SET
    is_relevant = CASE WHEN p ? 'is_relevant' THEN (p->>'is_relevant')::boolean ELSE is_relevant END,
    relevance_reason = COALESCE(p->>'relevance_reason', relevance_reason),
    entity_class = COALESCE(p->>'entity_class', entity_class),
    digital_presence = COALESCE(p->>'digital_presence', digital_presence),
    interested_fabrics = ARRAY(SELECT jsonb_array_elements_text(COALESCE(p->'interested_fabrics','[]'::jsonb))),
    accessories = ARRAY(SELECT jsonb_array_elements_text(COALESCE(p->'accessories','[]'::jsonb))),
    colors = ARRAY(SELECT jsonb_array_elements_text(COALESCE(p->'colors','[]'::jsonb))),
    product_types = ARRAY(SELECT jsonb_array_elements_text(COALESCE(p->'product_types','[]'::jsonb))),
    business_size_note = COALESCE(p->>'business_size_note', business_size_note),
    analysis_summary = COALESCE(p->>'analysis_summary', analysis_summary),
    targeting_suggestions = ARRAY(SELECT jsonb_array_elements_text(COALESCE(p->'targeting_suggestions','[]'::jsonb))),
    analysis_i18n = COALESCE(p->'analysis_i18n', analysis_i18n),
    market_role = CASE WHEN refined IN ('supplier','manufacturer','buyer') THEN refined ELSE market_role END,
    analyzed_at = now()
  WHERE id = p_id;
END $$;


--
-- Name: market_apply_enrich(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.market_apply_enrich(p_id uuid, p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  UPDATE market_companies SET
    phones        = ARRAY(
      SELECT DISTINCT ph FROM unnest(
        phones || ARRAY(SELECT jsonb_array_elements_text(COALESCE(p->'phones','[]'::jsonb)))
      ) AS ph
      WHERE regexp_replace(ph,'\D','','g') ~ '^(380[0-9]{9}|0[0-9]{9})$'
    ),
    emails        = ARRAY(SELECT DISTINCT unnest(emails || ARRAY(SELECT jsonb_array_elements_text(COALESCE(p->'emails','[]'::jsonb))))),
    social        = social || COALESCE(p->'social','{}'::jsonb),
    facebook_url  = COALESCE(p->>'facebook_url',  facebook_url),
    instagram_url = COALESCE(p->>'instagram_url', instagram_url),
    contact_person= COALESCE(p->>'contact_person', contact_person),
    web_branches  = CASE WHEN jsonb_array_length(COALESCE(p->'web_branches','[]'::jsonb)) > 0
                         THEN p->'web_branches' ELSE web_branches END,
    working_hours = COALESCE(p->>'working_hours', working_hours),
    sources       = ARRAY(SELECT DISTINCT unnest(sources || ARRAY['website'])),
    enrich_status = 'ok',
    enrich_version= 2,
    enriched_at   = now()
  WHERE id = p_id;
END $_$;


--
-- Name: market_apply_i18n(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.market_apply_i18n(p_id uuid, p jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE market_companies SET analysis_i18n = p WHERE id = p_id;
$$;


--
-- Name: market_classify_local(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.market_classify_local(p_platform text DEFAULT 'tkanex'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_excl text := '(ta-?da|та-?да|сільпо|сильпо|rozetka|розетк|епіцентр|comfy|foxtrot|фокстрот|аврора|ашан|auchan|novus|новус|варус|гіпермаркет|гипермаркет|супермаркет|товари для дому|товары для дома|все для дому|господарськ|канцтовар|іграшк|игрушк|електрон|электрон|побутова техніка|книжк|зоомагазин|будматеріал|аптек|pharmacy|restaurant|\mcafe\M|кафе|ресторан|піцерія|пекарн|морозиво|їжа|\mfood\M|salon|салон краси|перукарн|готель|\mhotel\M|marketplace|маркетплейс)';
  v_fab  text := '(тканин|ткани|текстиль|textile|fabric|kumaş|трикотаж|поліестер|полиэстер|бязь|фліс|fleece|віскоз|вискоз|сатин|габардин|плащівк|підкладк|фурнітур|furnitura|швейн|пошив|ательє|atelier|фабрика одягу|виробництв|ткацьк|мода|moda)';
  v_glob text := '(zara|nike|adidas|h&m|reserved|mango|bershka|pull&bear|puma|levi)';
  n_excl int; n_rel int; n_glob int;
BEGIN
  -- 1) استبعاد الأسواق العامة/غير النسيجية
  UPDATE market_companies SET is_relevant=false, entity_class='irrelevant',
    relevance_reason=COALESCE(relevance_reason,'تصنيف محلي: نشاط غير نسيجي/سوق عام')
  WHERE target_platform=p_platform AND is_relevant IS NULL AND name ~* v_excl;
  GET DIAGNOSTICS n_excl = ROW_COUNT;

  -- 2) ذات صلة: إشارة أقمشة/خياطة في الاسم أو الكلمات المطابِقة (وليست مستبعدة)
  UPDATE market_companies SET is_relevant=true, entity_class=COALESCE(entity_class,'local')
  WHERE target_platform=p_platform AND is_relevant IS NULL
    AND (name ~* v_fab OR array_to_string(matched_keywords,' ') ~* v_fab OR category IN ('fabric_supplier','wholesaler','clothing_factory'));
  GET DIAGNOSTICS n_rel = ROW_COUNT;

  -- 3) برندات عالمية (تُبقى موسومة)
  UPDATE market_companies SET entity_class='global_brand'
  WHERE target_platform=p_platform AND name ~* v_glob AND COALESCE(entity_class,'') <> 'global_brand';
  GET DIAGNOSTICS n_glob = ROW_COUNT;

  RETURN jsonb_build_object('excluded', n_excl, 'relevant', n_rel, 'global', n_glob);
END $$;


--
-- Name: market_dedupe(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.market_dedupe(p_platform text DEFAULT 'tkanex'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE n_primary int; n_groups int;
BEGIN
  -- مفتاح الدمج
  UPDATE market_companies SET dedupe_key = lower(trim(name))
  WHERE target_platform = p_platform AND name IS NOT NULL;

  -- عدد الفروع لكل مجموعة (اسم × دور)
  WITH g AS (
    SELECT dedupe_key, market_role, count(*) c
    FROM market_companies WHERE target_platform = p_platform AND dedupe_key IS NOT NULL
    GROUP BY 1,2
  )
  UPDATE market_companies m SET branches_count = g.c
  FROM g WHERE m.target_platform = p_platform AND m.dedupe_key = g.dedupe_key AND m.market_role = g.market_role;

  -- اختيار الممثّل (الأعلى مراجعات ثم ERP) لكل مجموعة
  WITH ranked AS (
    SELECT id, row_number() OVER (
      PARTITION BY dedupe_key, market_role
      ORDER BY COALESCE(google_reviews_count,0) DESC, COALESCE(erp_prospect_score,0) DESC, id
    ) rn
    FROM market_companies WHERE target_platform = p_platform AND dedupe_key IS NOT NULL
  )
  UPDATE market_companies m SET is_primary = (r.rn = 1) FROM ranked r WHERE m.id = r.id;

  SELECT count(*) INTO n_primary FROM market_companies WHERE target_platform = p_platform AND is_primary = true;
  SELECT count(DISTINCT dedupe_key) INTO n_groups FROM market_companies WHERE target_platform = p_platform AND dedupe_key IS NOT NULL;
  RETURN jsonb_build_object('primary', n_primary, 'groups', n_groups);
END $$;


--
-- Name: market_companies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.market_companies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
