    email_public text,
    google_place_id text,
    google_rating numeric,
    google_reviews_count integer,
    facebook_url text,
    instagram_url text,
    facebook_followers integer,
    size_estimate text,
    source text DEFAULT 'google_places'::text NOT NULL,
    platform_tags jsonb DEFAULT '[]'::jsonb NOT NULL,
    priority_score numeric DEFAULT 0,
    erp_prospect_score numeric DEFAULT 0,
    legal_basis text,
    retention_until date,
    refreshed_at timestamp with time zone,
    collected_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tenant_id uuid,
    product_gender text,
    phone_secondary text,
    google_maps_url text,
    lat numeric,
    lng numeric,
    business_status text,
    matched_keywords text[] DEFAULT '{}'::text[],
    is_advertiser boolean DEFAULT false,
    last_ad_seen timestamp with time zone,
    ad_count integer DEFAULT 0,
    phones text[] DEFAULT '{}'::text[],
    emails text[] DEFAULT '{}'::text[],
    social jsonb DEFAULT '{}'::jsonb,
    enriched_at timestamp with time zone,
    enrich_status text,
    internal_rating integer,
    internal_status text,
    internal_activity text,
    internal_notes text,
    internal_updated_at timestamp with time zone,
    registration_no text,
    legal_name text,
    founded_year integer,
    employee_count text,
    registry_source text,
    interested_fabrics text[] DEFAULT '{}'::text[],
    accessories text[] DEFAULT '{}'::text[],
    product_types text[] DEFAULT '{}'::text[],
    colors text[] DEFAULT '{}'::text[],
    analysis_summary text,
    business_size_note text,
    targeting_suggestions text[] DEFAULT '{}'::text[],
    analyzed_at timestamp with time zone,
    is_relevant boolean,
    relevance_reason text,
    digital_presence text,
    branches_count integer,
    created_at timestamp with time zone DEFAULT now(),
    sources text[] DEFAULT '{}'::text[],
    social_followers integer,
    social_category text,
    social_enriched_at timestamp with time zone,
    entity_class text,
    google_primary_type text,
    dedupe_key text,
    is_primary boolean,
    contact_person text,
    web_branches jsonb DEFAULT '[]'::jsonb,
    working_hours text,
    enrich_version integer DEFAULT 0,
    analysis_i18n jsonb,
    claude_score numeric,
    claude_priority text,
    claude_verdict text,
    follows_competitors text[],
    consensus_score numeric,
    claude_fabrics text[],
    CONSTRAINT market_companies_category_check CHECK ((category = ANY (ARRAY['fabric_supplier'::text, 'importer'::text, 'wholesaler'::text, 'clothing_factory'::text, 'tailor'::text, 'designer'::text, 'retailer'::text, 'shoe_supplier'::text, 'construction_supplier'::text, 'contractor'::text, 'engineer'::text]))),
    CONSTRAINT market_companies_market_role_check CHECK ((market_role = ANY (ARRAY['supplier'::text, 'buyer'::text, 'manufacturer'::text]))),
    CONSTRAINT market_companies_size_estimate_check CHECK ((size_estimate = ANY (ARRAY['small'::text, 'medium'::text, 'large'::text]))),
    CONSTRAINT market_companies_source_check CHECK ((source = ANY (ARRAY['google_places'::text, 'meta_ads'::text, 'directory'::text, 'manual'::text, 'prom_ua'::text, 'olx'::text, 'instagram'::text, 'telegram'::text]))),
    CONSTRAINT market_companies_target_market_check CHECK ((target_market = ANY (ARRAY['ukraine'::text, 'turkey'::text, 'moldova'::text, 'syria'::text]))),
    CONSTRAINT market_companies_target_platform_check CHECK ((target_platform = ANY (ARRAY['tkanex'::text, 'obuvix'::text, 'warsha'::text])))
);


--
-- Name: market_score(public.market_companies); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.market_score(c public.market_companies) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT LEAST(100, GREATEST(0,
      (CASE WHEN c.website IS NOT NULL THEN 20 ELSE 0 END)
    + (CASE WHEN c.phone_public IS NOT NULL THEN 10 ELSE 0 END)
    + (CASE WHEN COALESCE(c.business_status,'OPERATIONAL') = 'OPERATIONAL' THEN 15 ELSE 0 END)
    + (CASE c.size_estimate WHEN 'large' THEN 25 WHEN 'medium' THEN 15 WHEN 'small' THEN 5 ELSE 0 END)
    + LEAST(20, COALESCE(c.google_reviews_count,0) / 10.0)
    + (CASE WHEN COALESCE(c.google_rating,0) >= 4.0 THEN 10 ELSE 0 END)
  ))::numeric;
$$;


--
-- Name: market_set_score(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.market_set_score() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.erp_prospect_score := market_score(NEW);
  RETURN NEW;
END $$;


--
-- Name: market_upsert_company(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.market_upsert_company(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_pid text := p->>'google_place_id';
  v_kw  text := NULLIF(p->>'matched_keyword', '');
  v_src text := COALESCE(p->>'source','google_places');
  v_rel boolean := CASE WHEN p ? 'is_relevant' THEN (p->>'is_relevant')::boolean ELSE NULL END;
BEGIN
  INSERT INTO market_companies (
    name, country, city, target_platform, target_market, market_role,
    category, product_gender, phone_public, phone_secondary, address, website,
    google_place_id, google_rating, google_reviews_count, google_maps_url,
    lat, lng, business_status, size_estimate, source, sources, platform_tags,
    legal_basis, matched_keywords, phones, is_relevant, google_primary_type, refreshed_at, updated_at
  ) VALUES (
    p->>'name', p->>'country', p->>'city', p->>'target_platform', p->>'target_market', p->>'market_role',
    p->>'category', p->>'product_gender', p->>'phone_public', p->>'phone_secondary', p->>'address', p->>'website',
    v_pid, (p->>'google_rating')::numeric, (p->>'google_reviews_count')::int, p->>'google_maps_url',
    (p->>'lat')::numeric, (p->>'lng')::numeric, p->>'business_status', p->>'size_estimate',
    v_src, ARRAY[v_src], COALESCE(p->'platform_tags', '[]'::jsonb),
    COALESCE(p->>'legal_basis','public_business_data'),
    CASE WHEN v_kw IS NULL THEN '{}'::text[] ELSE ARRAY[v_kw] END,
    ARRAY(SELECT DISTINCT x FROM unnest(ARRAY[p->>'phone_public', p->>'phone_secondary']) x WHERE x IS NOT NULL),
    v_rel, p->>'google_primary_type', now(), now()
  )
  ON CONFLICT (google_place_id) DO UPDATE SET
    name = EXCLUDED.name,
    address = COALESCE(EXCLUDED.address, market_companies.address),
    phone_public = COALESCE(EXCLUDED.phone_public, market_companies.phone_public),
    phone_secondary = COALESCE(EXCLUDED.phone_secondary, market_companies.phone_secondary),
    website = COALESCE(EXCLUDED.website, market_companies.website),
    google_rating = EXCLUDED.google_rating, google_reviews_count = EXCLUDED.google_reviews_count,
    google_maps_url = COALESCE(EXCLUDED.google_maps_url, market_companies.google_maps_url),
    lat = COALESCE(EXCLUDED.lat, market_companies.lat), lng = COALESCE(EXCLUDED.lng, market_companies.lng),
    business_status = COALESCE(EXCLUDED.business_status, market_companies.business_status),
    product_gender = COALESCE(EXCLUDED.product_gender, market_companies.product_gender),
    category = COALESCE(market_companies.category, EXCLUDED.category),
    google_primary_type = COALESCE(EXCLUDED.google_primary_type, market_companies.google_primary_type),
    is_relevant = COALESCE(market_companies.is_relevant, EXCLUDED.is_relevant),  -- لا نلغي قرار Gemini
    size_estimate = EXCLUDED.size_estimate,
    sources = ARRAY(SELECT DISTINCT unnest(market_companies.sources || EXCLUDED.sources)),
    matched_keywords = ARRAY(SELECT DISTINCT unnest(market_companies.matched_keywords || EXCLUDED.matched_keywords)),
    phones = ARRAY(SELECT DISTINCT unnest(market_companies.phones || EXCLUDED.phones)),
    refreshed_at = now(), updated_at = now()
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;


--
-- Name: match_pending_ptt_invites(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.match_pending_ptt_invites() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  user_phone_norm TEXT;
  inv RECORD;
BEGIN
  user_phone_norm := public.normalize_phone(NEW.phone);
  IF user_phone_norm IS NULL THEN RETURN NEW; END IF;
  FOR inv IN
    SELECT id, channel_id
    FROM public.nexa_ptt_pending_invites
    WHERE phone_normalized = user_phone_norm
      AND status = 'pending'
      AND (expires_at IS NULL OR expires_at > now())
  LOOP
    INSERT INTO public.nexa_ptt_members (channel_id, user_id, role, is_muted, is_confirmed, added_by)
    VALUES (inv.channel_id, NEW.id, 'member', true, false, NULL)
    ON CONFLICT DO NOTHING;
    UPDATE public.nexa_ptt_pending_invites
    SET status = 'matched', matched_user_id = NEW.id, matched_at = now()
    WHERE id = inv.id;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: merge_carts(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.merge_carts(p_tenant_id uuid, p_customer_id uuid, p_session_id character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_guest_cart_id UUID;
    v_customer_cart_id UUID;
    v_merged_count INT := 0;
BEGIN
    -- الحصول على سلة الزائر
    SELECT id INTO v_guest_cart_id
    FROM shopping_carts
    WHERE tenant_id = p_tenant_id
      AND session_id = p_session_id
      AND status = 'active'
    LIMIT 1;
    
    IF v_guest_cart_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'سلة الزائر غير موجودة'
        );
    END IF;
    
    -- الحصول على أو إنشاء سلة العميل
    v_customer_cart_id := get_or_create_cart(
        p_tenant_id,
        (SELECT company_id FROM shopping_carts WHERE id = v_guest_cart_id),
        p_customer_id,
        NULL
    );
    
    -- دمج العناصر
    WITH moved_items AS (
        INSERT INTO shopping_cart_items (
            cart_id,
            product_id,
            product_variant_id,
            quantity,
            unit_price,
            original_price,
            discount_percent,
            notes
        )
        SELECT 
            v_customer_cart_id,
            product_id,
            product_variant_id,
            quantity,
            unit_price,
            original_price,
            discount_percent,
            notes
        FROM shopping_cart_items
        WHERE cart_id = v_guest_cart_id
        ON CONFLICT (cart_id, product_id) 
        DO UPDATE SET
            quantity = shopping_cart_items.quantity + EXCLUDED.quantity
        RETURNING id
    )
    SELECT COUNT(*) INTO v_merged_count FROM moved_items;
    
    -- حذف سلة الزائر
    DELETE FROM shopping_carts WHERE id = v_guest_cart_id;
    
    -- تحديث المجاميع
    PERFORM update_cart_totals(v_customer_cart_id);
    
    RETURN jsonb_build_object(
        'success', true,
        'customer_cart_id', v_customer_cart_id,
        'merged_items', v_merged_count,
        'message', 'تم دمج السلة بنجاح'
    );
END;
$$;


--
-- Name: move_account_to_parent(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.move_account_to_parent(p_account_id uuid, p_new_parent_id uuid, p_notes text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_account RECORD;
    v_new_parent RECORD;
    v_old_parent_id UUID;
    v_tenant_id UUID;
    v_company_id UUID;
BEGIN
    -- Get account details
    SELECT * INTO v_account
    FROM chart_of_accounts
    WHERE id = p_account_id;
    
    IF v_account IS NULL THEN
        RAISE EXCEPTION 'Account not found';
    END IF;
    
    -- Get new parent details
    SELECT * INTO v_new_parent
    FROM chart_of_accounts
    WHERE id = p_new_parent_id;
    
    IF v_new_parent IS NULL THEN
        RAISE EXCEPTION 'New parent account not found';
    END IF;
    
    -- Validate same company
    IF v_account.company_id != v_new_parent.company_id THEN
        RAISE EXCEPTION 'Account and new parent must belong to the same company';
    END IF;
    
    -- Validate new parent is a group
    IF NOT v_new_parent.is_group THEN
        RAISE EXCEPTION 'New parent must be a group account';
    END IF;
    
    -- Prevent moving to self or descendant
    IF p_account_id = p_new_parent_id THEN
        RAISE EXCEPTION 'Cannot move account to itself';
    END IF;
    
    -- Check if new parent is a descendant of the account
    IF EXISTS (
        WITH RECURSIVE descendants AS (
            SELECT id, parent_id
            FROM chart_of_accounts
            WHERE parent_id = p_account_id
            
            UNION ALL
            
            SELECT c.id, c.parent_id
            FROM chart_of_accounts c
            INNER JOIN descendants d ON c.parent_id = d.id
        )
        SELECT 1 FROM descendants WHERE id = p_new_parent_id
    ) THEN
        RAISE EXCEPTION 'Cannot move account to its own descendant';
    END IF;
    
    v_tenant_id := v_account.tenant_id;
    v_company_id := v_account.company_id;
    v_old_parent_id := v_account.parent_id;
    
    -- Update account parent
    UPDATE chart_of_accounts
    SET parent_id = p_new_parent_id,
        updated_at = NOW()
    WHERE id = p_account_id;
    
    -- Record the move
    INSERT INTO account_transfers (
        tenant_id,
        company_id,
        source_account_id,
        target_account_id,
        transfer_type,
        notes,
        created_by
    ) VALUES (
        v_tenant_id,
        v_company_id,
        v_old_parent_id,
        p_new_parent_id,
        'move_account',
        COALESCE(p_notes, format('Moved account %s from parent %s to %s',
            v_account.account_code,
            (SELECT account_code FROM chart_of_accounts WHERE id = v_old_parent_id),
            v_new_parent.account_code
        )),
        p_user_id
    );
    
    RAISE NOTICE 'Account % moved from parent % to %', 
        v_account.account_code,
        (SELECT account_code FROM chart_of_accounts WHERE id = v_old_parent_id),
        v_new_parent.account_code;
    
    RETURN TRUE;
END;
$$;


--
-- Name: nexa_can_join_room(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.nexa_can_join_room(p_room text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_parts text[];
BEGIN
  IF p_room IS NULL OR length(p_room) = 0 THEN RETURN false; END IF;
  IF auth.role() = 'service_role' THEN RETURN true; END IF;
  IF v_uid IS NULL THEN RETURN false; END IF;
  -- admin bypass (monitoring/support/call-on-behalf)
  IF is_super_admin(v_uid) OR is_tenant_admin(v_uid) THEN RETURN true; END IF;
  IF p_room LIKE 'call\_%' THEN
    v_parts := string_to_array(p_room, '_');
    RETURN EXISTS (SELECT 1 FROM pbx_extension_users eu JOIN pbx_extensions e ON e.id = eu.extension_id
      WHERE eu.user_id = v_uid AND eu.is_active = true AND e.is_active = true AND e.extension_number IN (v_parts[2], v_parts[3]));
  END IF;
  RETURN EXISTS (SELECT 1 FROM nexa_ptt_channels c WHERE c.conference_room = p_room
    AND (c.is_public = true
      OR EXISTS (SELECT 1 FROM nexa_ptt_members m WHERE m.channel_id = c.id AND m.user_id = v_uid)
      OR EXISTS (SELECT 1 FROM nexa_ptt_invitations i WHERE i.channel_id = c.id AND i.to_user_id = v_uid)));
END;
$$;


--
-- Name: nexa_cleanup_expired_ptt_messages(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.nexa_cleanup_expired_ptt_messages() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  expired_record RECORD;
BEGIN
  FOR expired_record IN
    SELECT id, audio_url FROM nexa_ptt_messages WHERE expires_at < now()
  LOOP
    DELETE FROM nexa_ptt_messages WHERE id = expired_record.id;
  END LOOP;
END;
$$;


--
-- Name: nexa_create_ptt_channel(text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.nexa_create_ptt_channel(p_name text, p_type text, p_created_by uuid, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_channel_id UUID;
  v_room TEXT;
  v_creator UUID;
  v_tenant UUID;
BEGIN
  -- IDENTITY: the creator is ALWAYS the authenticated user. Never trust the
  -- client-supplied p_created_by. Trusted backend calls (service_role or no JWT)
  -- may act on behalf of an explicit p_created_by.
  IF auth.role() = 'service_role' OR auth.uid() IS NULL THEN
    v_creator := COALESCE(p_created_by, auth.uid());
  ELSE
    v_creator := auth.uid();
  END IF;

  IF v_creator IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  -- PROVENANCE: stamp the channel with the creator's own tenant. Ignore any
  -- client-supplied p_tenant_id for a real (non-backend) caller.
  IF auth.role() = 'service_role' OR auth.uid() IS NULL THEN
    v_tenant := COALESCE(p_tenant_id, get_user_tenant_id(v_creator));
  ELSE
    v_tenant := get_user_tenant_id(v_creator);
  END IF;

  v_room := 'ptt_' || encode(gen_random_bytes(8), 'hex');

  -- is_public is intentionally NOT a parameter on this signature, so new
  -- channels are created PRIVATE (column default false) and opened later via
  -- the dedicated flow. Cross-subscriber visibility stays gated by is_public +
  -- membership + invitation, which this function does not bypass.
  INSERT INTO nexa_ptt_channels (name, type, conference_room, created_by, tenant_id)
  VALUES (p_name, p_type, v_room, v_creator, v_tenant)
  RETURNING id INTO v_channel_id;

  -- Creator is admin (and a confirmed member by the same insert shape as before).
  INSERT INTO nexa_ptt_members (channel_id, user_id, role)
  VALUES (v_channel_id, v_creator, 'admin');

  RETURN v_channel_id;
END;
$$;


--
-- Name: nexa_get_ptt_channels(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.nexa_get_ptt_channels(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  -- IDENTITY: never trust client-supplied p_user_id; always act as auth.uid().
  -- Trusted backend (service_role / no auth context) may impersonate p_user_id.
  IF auth.role() = 'service_role' OR v_uid IS NULL THEN
    v_uid := COALESCE(p_user_id, v_uid);
  END IF;

  IF v_uid IS NULL THEN
    RETURN '[]'::json;
  END IF;

  RETURN (
    SELECT json_agg(row_to_json(ch))
    FROM (
      SELECT
        c.id, c.name, c.type, c.conference_room, c.avatar_url, c.is_active,
        c.created_at,
        (SELECT count(*) FROM nexa_ptt_members WHERE channel_id = c.id) AS member_count,
        (SELECT count(*) FROM nexa_ptt_members WHERE channel_id = c.id AND is_online = true) AS online_count,
        (SELECT json_agg(json_build_object(
          'user_id', m2.user_id, 'is_online', m2.is_online, 'is_talking', m2.is_talking
        )) FROM nexa_ptt_members m2 WHERE m2.channel_id = c.id AND m2.is_talking = true) AS talking_members,
        m.availability, m.role
      FROM nexa_ptt_channels c
      LEFT JOIN nexa_ptt_members m ON m.channel_id = c.id AND m.user_id = v_uid
      WHERE c.is_active = true
        AND (m.user_id IS NOT NULL OR c.is_public = true)
      ORDER BY c.updated_at DESC
    ) ch
  );
END;
$$;


--
-- Name: nexa_get_ptt_invitations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.nexa_get_ptt_invitations(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  -- Trusted backend (service_role / no JWT): no acting identity -> nothing addressed.
  IF v_uid IS NULL THEN
    RETURN '[]'::json;
  END IF;

  RETURN (
    SELECT COALESCE(json_agg(row_to_json(i)), '[]'::json)
    FROM (
      SELECT inv.id, inv.type, inv.from_user_name, inv.channel_name,
             inv.message, inv.created_at,
        (SELECT count(*) FROM nexa_ptt_members m
          WHERE m.channel_id = inv.channel_id) AS member_count
      FROM nexa_ptt_invitations inv
      WHERE inv.status = 'pending'
        AND inv.expires_at > now()
        AND (
          -- direct invitations addressed to the caller
          inv.to_user_id = v_uid
          OR
          -- broadcast invitations (to_user_id IS NULL): only for channels the
          -- caller can actually access (public OR already a member). Never global.
          (
            inv.to_user_id IS NULL
            AND EXISTS (
              SELECT 1 FROM nexa_ptt_channels c
              WHERE c.id = inv.channel_id
                AND (
                  c.is_public = true
                  OR EXISTS (
                    SELECT 1 FROM nexa_ptt_members mm
                    WHERE mm.channel_id = c.id
                      AND mm.user_id = v_uid
                  )
                )
            )
          )
        )
      ORDER BY inv.created_at DESC
    ) i
  );
END;
$$;


--
-- Name: nexa_respond_ptt_invitation(uuid, uuid, boolean, text, time without time zone, time without time zone, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.nexa_respond_ptt_invitation(p_invitation_id uuid, p_user_id uuid, p_accept boolean, p_availability text DEFAULT 'always'::text, p_schedule_start time without time zone DEFAULT NULL::time without time zone, p_schedule_end time without time zone DEFAULT NULL::time without time zone, p_schedule_days text[] DEFAULT NULL::text[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_invite     RECORD;
  v_uid        uuid := auth.uid();
  v_trusted    boolean := (auth.role() = 'service_role' OR auth.uid() IS NULL);
  v_actor      uuid;
  v_my_phone   text;
BEGIN
  SELECT * INTO v_invite FROM nexa_ptt_invitations WHERE id = p_invitation_id;
  IF NOT FOUND THEN RETURN false; END IF;

  -- Identity is auth.uid(); the client-supplied p_user_id is NEVER trusted
  -- for a real caller. The invitation must be addressed to the acting user.
  IF v_trusted THEN
    -- Trusted backend (service_role / no JWT): resolve actor from the
    -- invitation's own target first, then fall back to p_user_id for automation.
    v_actor := COALESCE(v_invite.to_user_id, p_user_id);
    IF v_actor IS NULL THEN RETURN false; END IF;
  ELSE
    v_actor := v_uid;
    IF v_invite.to_user_id IS NOT NULL THEN
      -- (a) Direct invite: only the addressed user may respond.
      IF v_invite.to_user_id <> v_uid THEN RETURN false; END IF;
    ELSIF v_invite.to_phone IS NOT NULL THEN
      -- (b) Phone invite: the caller's own phone must match the invite target.
      SELECT phone INTO v_my_phone FROM auth.users WHERE id = v_uid;
      IF v_my_phone IS NULL
         OR normalize_phone(v_my_phone) IS NULL
         OR normalize_phone(v_my_phone) <> normalize_phone(v_invite.to_phone) THEN
        RETURN false;
      END IF;
    ELSE
      -- Untargeted invitation: not claimable by an arbitrary caller.
      RETURN false;
    END IF;
  END IF;

  IF p_accept THEN
    -- Update invitation (bind to the verified actor, not the raw client value)
    UPDATE nexa_ptt_invitations
    SET status = 'accepted', responded_at = now(),
        to_user_id = v_actor,
        availability = p_availability,
        schedule_start = p_schedule_start,
        schedule_end = p_schedule_end,
        schedule_days = p_schedule_days
    WHERE id = p_invitation_id;

    -- Add the verified actor to the channel
    INSERT INTO nexa_ptt_members (channel_id, user_id, availability, schedule_start, schedule_end, schedule_days)
    VALUES (v_invite.channel_id, v_actor, p_availability, p_schedule_start, p_schedule_end, p_schedule_days)
    ON CONFLICT (channel_id, user_id) DO NOTHING;
  ELSE
    UPDATE nexa_ptt_invitations
    SET status = 'rejected', responded_at = now(), to_user_id = v_actor
    WHERE id = p_invitation_id;
  END IF;

  RETURN true;
END;
$$;


--
-- Name: nexa_send_ptt_invitation(text, uuid, text, uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.nexa_send_ptt_invitation(p_type text, p_from_user_id uuid, p_from_user_name text, p_to_user_id uuid DEFAULT NULL::uuid, p_to_phone text DEFAULT NULL::text, p_channel_id uuid DEFAULT NULL::uuid, p_channel_name text DEFAULT NULL::text, p_message text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_invite_id  UUID;
  v_channel_id UUID := p_channel_id;
  v_from       UUID := auth.uid();           -- identity = caller, never trust client
  v_trusted    BOOLEAN := (auth.role() = 'service_role' OR auth.uid() IS NULL);
BEGIN
  -- Trusted backend (service_role / no JWT): honour the supplied sender id.
  IF v_trusted THEN
    v_from := p_from_user_id;
  END IF;

  IF v_from IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  -- Access gate (skipped for trusted backend calls):
  -- You may only invite people INTO a channel you already belong to (member or owner).
  -- This supports cross-subscriber PUBLIC *and* PRIVATE groups without a same-tenant
  -- requirement, while blocking invites into channels the caller has no access to.
  -- The 'buddy' auto-create branch below is exempt: it makes a brand-new channel that
  -- the caller owns (created_by = v_from).
  IF NOT v_trusted
     AND NOT (p_type = 'buddy' AND v_channel_id IS NULL)
  THEN
    IF v_channel_id IS NULL THEN
      RAISE EXCEPTION 'channel required to send invitation';
    END IF;

    IF NOT EXISTS (
           SELECT 1 FROM nexa_ptt_channels c
            WHERE c.id = v_channel_id
              AND c.created_by = v_from
         )
       AND NOT EXISTS (
           SELECT 1 FROM nexa_ptt_members m
            WHERE m.channel_id = v_channel_id
              AND m.user_id = v_from
         )
       AND NOT is_super_admin(v_from)
    THEN
      RAISE EXCEPTION 'not a member of channel %, cannot invite', v_channel_id
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  -- For buddy type, create channel automatically (caller becomes owner).
  IF p_type = 'buddy' AND v_channel_id IS NULL THEN
    v_channel_id := nexa_create_ptt_channel(
      COALESCE(p_channel_name, p_from_user_name || ' ↔ PTT'),
      'buddy',
      v_from
    );
  END IF;

  INSERT INTO nexa_ptt_invitations (
    type, from_user_id, from_user_name,
    to_user_id, to_phone,
    channel_id, channel_name, message
  ) VALUES (
    p_type, v_from, p_from_user_name,
    p_to_user_id, p_to_phone,
    v_channel_id, p_channel_name, p_message
  ) RETURNING id INTO v_invite_id;

  RETURN v_invite_id;
END;
$$;


--
-- Name: nexa_update_ptt_availability(uuid, uuid, text, time without time zone, time without time zone, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.nexa_update_ptt_availability(p_channel_id uuid, p_user_id uuid, p_availability text, p_schedule_start time without time zone DEFAULT NULL::time without time zone, p_schedule_end time without time zone DEFAULT NULL::time without time zone, p_schedule_days text[] DEFAULT NULL::text[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_backend boolean := (auth.role() = 'service_role' OR auth.uid() IS NULL);
  v_target_user uuid;
BEGIN
  -- IDENTITY: never trust client-supplied p_user_id. The acting user is auth.uid().
  -- A trusted backend call (service_role / no JWT) may act on the supplied user.
  IF v_is_backend THEN
    v_target_user := COALESCE(p_user_id, v_uid);
  ELSE
    v_target_user := v_uid;
  END IF;

  IF v_target_user IS NULL THEN
    RETURN false;
  END IF;

  -- Self-scoped: can only mutate one's own membership row. If the caller is not
  -- a member of this channel, no row matches and FOUND is false (unchanged semantics).
  UPDATE nexa_ptt_members
  SET availability = p_availability,
      schedule_start = p_schedule_start,
      schedule_end = p_schedule_end,
      schedule_days = p_schedule_days
  WHERE channel_id = p_channel_id AND user_id = v_target_user;
  RETURN FOUND;
END;
$$;


--
-- Name: normalize_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.normalize_phone(phone text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  digits TEXT;
BEGIN
  IF phone IS NULL OR phone = '' THEN RETURN NULL; END IF;
  digits := regexp_replace(phone, '[^0-9]', '', 'g');
  IF length(digits) < 7 THEN RETURN digits; END IF;
  RETURN right(digits, 9);
END;
$$;


--
-- Name: notify_n8n_webhook(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.notify_n8n_webhook() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  payload jsonb;
  webhook_url text;
BEGIN
  -- ⚠️ IMPORTANT: Replace with your actual n8n webhook URL
  -- When running locally: http://localhost:5678/webhook/texacore-erp-events
  -- When on server: https://your-n8n-domain.com/webhook/texacore-erp-events
  webhook_url := 'http://localhost:5678/webhook/texacore-erp-events';
  
  -- Build the payload with tenant isolation data
  payload := jsonb_build_object(
    'type', TG_OP,
    'table', TG_TABLE_NAME,
    'schema', TG_TABLE_SCHEMA,
    'timestamp', now()::text,
    'tenant_id', CASE 
      WHEN TG_OP = 'DELETE' THEN OLD.tenant_id::text
      ELSE NEW.tenant_id::text
    END,
    'record', CASE 
      WHEN TG_OP = 'DELETE' THEN row_to_json(OLD)::jsonb
      ELSE row_to_json(NEW)::jsonb
    END,
    'old_record', CASE 
      WHEN TG_OP = 'UPDATE' THEN row_to_json(OLD)::jsonb
      ELSE NULL
    END
  );

  -- Send HTTP request to n8n (using pg_net extension)
  -- Note: pg_net must be enabled in Supabase Dashboard → Database → Extensions
  BEGIN
    PERFORM net.http_post(
      url := webhook_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'X-Webhook-Secret', 'texacore-n8n-secret-2026'
      ),
      body := payload
    );
  EXCEPTION WHEN OTHERS THEN
    -- Don't fail the transaction if webhook fails
    RAISE WARNING 'n8n webhook failed: %', SQLERRM;
  END;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: notify_new_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.notify_new_tenant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_is_registering BOOLEAN;
BEGIN
    -- 🛑 إذا كان التسجيل جارٍ (من register_new_subscriber)، لا ترسل إشعار
    -- سيتم إرسال الإشعار من register_new_subscriber بعد اكتمال كل البيانات
    BEGIN
        v_is_registering := current_setting('app.is_registering', true)::boolean;
    EXCEPTION WHEN OTHERS THEN
        v_is_registering := false;
    END;

    IF v_is_registering THEN
        RETURN NEW;
    END IF;

    -- إذا أُنشئ tenant يدوياً (ليس من الويزارد)، أرسل إشعار بسيط
    PERFORM send_new_subscriber_notification(NEW.id);

    RETURN NEW;
END;
$$;


--
-- Name: notify_pending_recurring_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.notify_pending_recurring_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_entry RECORD;
    v_admin_users RECORD;
    v_amount_text TEXT;
    v_company_id UUID;
BEGIN
    -- فقط عند INSERT بحالة pending
    IF NEW.status != 'pending' OR NEW.approval_status != 'pending' THEN
        RETURN NEW;
    END IF;

    -- جلب معلومات القيد المتكرر
    SELECT name_ar, name_en, amount, currency, company_id, tenant_id
    INTO v_entry
    FROM recurring_entries
    WHERE id = NEW.recurring_entry_id;

    v_company_id := v_entry.company_id;

    -- تنسيق المبلغ
    v_amount_text := COALESCE(v_entry.currency, '') || ' ' || TO_CHAR(COALESCE(v_entry.amount, NEW.amount), 'FM999,999,990.00');

    -- إرسال إشعار لكل المستخدمين الذين لهم صلاحيات محاسبة
    FOR v_admin_users IN
        SELECT DISTINCT u.id as user_id
        FROM auth.users u
        JOIN user_role_assignments ura ON u.id = ura.user_id
        JOIN roles r ON ura.role_id = r.id
        WHERE ura.tenant_id = v_entry.tenant_id
          AND ura.is_active = true
          AND (
            r.code IN ('super_admin', 'accountant', 'chief_accountant', 'financial_manager')
            OR r.visible_modules::text LIKE '%all%'
            OR r.visible_modules::text LIKE '%accounting%'
          )
    LOOP
        INSERT INTO notifications (
            tenant_id, user_id, title, body, type,
            source_type, source_id, metadata
        ) VALUES (
            v_company_id,  -- ← company_id لأن notifications FK يشير لـ companies
            v_admin_users.user_id,
            'قيد متكرر بانتظار الموافقة | Recurring entry awaiting approval',
            COALESCE(v_entry.name_ar, '') || ' — ' || v_amount_text || 
            ' | ' || COALESCE(v_entry.name_en, v_entry.name_ar, '') || ' — ' || v_amount_text,
            'warning',
            'recurring_entry',
            NEW.recurring_entry_id,
            jsonb_build_object(
                'history_id', NEW.id,
                'recurring_entry_id', NEW.recurring_entry_id,
                'scheduled_date', NEW.scheduled_date,
                'amount', COALESCE(NEW.amount, v_entry.amount),
                'currency', v_entry.currency,
                'action_url', '/accounting/recurring-entries'
            )
        );
    END LOOP;

    RETURN NEW;
END;
$$;


--
-- Name: notify_recurring_approval_result(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.notify_recurring_approval_result() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_entry RECORD;
    v_created_by UUID;
    v_company_id UUID;
    v_title_text TEXT;
    v_body_text TEXT;
    v_notif_type TEXT;
BEGIN
    IF OLD.approval_status = NEW.approval_status THEN
        RETURN NEW;
    END IF;

    IF NEW.approval_status NOT IN ('approved', 'rejected') THEN
        RETURN NEW;
    END IF;

    SELECT name_ar, name_en, created_by, currency, amount, company_id
    INTO v_entry
    FROM recurring_entries
    WHERE id = NEW.recurring_entry_id;

    v_created_by := v_entry.created_by;
    v_company_id := v_entry.company_id;

    IF NEW.approval_status = 'approved' THEN
        v_title_text := 'تمت الموافقة على القيد المتكرر ✅ | Recurring entry approved ✅';
        v_body_text := COALESCE(v_entry.name_ar, '') || ' تمت الموافقة والتنفيذ'
                       || ' | ' || COALESCE(v_entry.name_en, '') || ' has been approved and executed';
        v_notif_type := 'success';
    ELSE
        v_title_text := 'تم رفض القيد المتكرر ❌ | Recurring entry rejected ❌';
        v_body_text := COALESCE(v_entry.name_ar, '') || ' — ' || COALESCE(NEW.rejection_reason, '')
                       || ' | ' || COALESCE(v_entry.name_en, '') || ' — ' || COALESCE(NEW.rejection_reason, '');
        v_notif_type := 'error';
    END IF;

    IF v_created_by IS NOT NULL THEN
        INSERT INTO notifications (
            tenant_id, user_id, title, body, type,
            source_type, source_id, metadata
        ) VALUES (
            v_company_id,  -- ← company_id
            v_created_by,
            v_title_text,
            v_body_text,
            v_notif_type,
            'recurring_entry',
            NEW.recurring_entry_id,
            jsonb_build_object(
                'history_id', NEW.id,
                'recurring_entry_id', NEW.recurring_entry_id,
                'approval_status', NEW.approval_status,
                'action_url', '/accounting/recurring-entries'
            )
        );
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: np_status_to_shipment(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.np_status_to_shipment(p_code text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_code IN ('9','11','106') THEN 'delivered'
    WHEN p_code IN ('102','103','108') THEN 'returned'
    WHEN p_code IN ('7','8','10') THEN 'at_branch'
    WHEN p_code IN ('4','41','5','6','101','12','104','105') THEN 'in_transit'
    WHEN p_code IN ('1') THEN 'created'
    ELSE NULL  -- 2/3/غير معروف: لا نغيّر الحالة
  END;
$$;


--
-- Name: np_tracking_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.np_tracking_sync() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_req RECORD;
  v_doc jsonb;
  v_code int;          -- np_status_code عمود رقمي
  v_text text;
  v_new_status text;
  v_ship RECORD;
  v_enq RECORD;
  v_request_id bigint;
  v_sent int := 0;
BEGIN
  -- ═══ أ) معالجة الردود الجاهزة ═══
  FOR v_req IN
    SELECT q.id AS queue_id, q.shipment_id, r.status_code, r.content, r.timed_out
    FROM np_tracking_requests q
    JOIN net._http_response r ON r.id = q.request_id
  LOOP
    BEGIN
      IF COALESCE(v_req.timed_out, false) = false
         AND v_req.status_code = 200
         AND (v_req.content::jsonb)->'data'->0 IS NOT NULL THEN

        v_doc  := (v_req.content::jsonb)->'data'->0;
        v_code := NULLIF(v_doc->>'StatusCode', '')::int;
        v_text := v_doc->>'Status';
        v_new_status := np_status_to_shipment(v_code::text);

        SELECT id, status, np_status_code INTO v_ship
        FROM ecommerce_shipments WHERE id = v_req.shipment_id;

        IF v_ship.id IS NOT NULL THEN
          UPDATE ecommerce_shipments SET
            np_status_code  = v_code,
            np_status_text  = v_text,
            np_last_checked = now(),
            status          = COALESCE(v_new_status, status),
            shipped_at      = CASE WHEN v_new_status IN ('in_transit','at_branch','delivered')
                                   THEN COALESCE(shipped_at, now()) ELSE shipped_at END,
            delivered_at    = CASE WHEN v_new_status = 'delivered'
                                   THEN COALESCE(delivered_at,
                                        NULLIF(v_doc->>'ActualDeliveryDate','')::timestamptz, now())
                                   ELSE delivered_at END,
            updated_at      = now()
          WHERE id = v_ship.id;

          -- سجل التاريخ عند تغيّر كود الحالة فقط
          IF v_code IS DISTINCT FROM v_ship.np_status_code THEN
            INSERT INTO ecommerce_shipment_status_history
              (shipment_id, from_status, to_status, np_status_code, np_status_text, notes)
            VALUES
              (v_ship.id, v_ship.status, COALESCE(v_new_status, v_ship.status),
               v_code, v_text, 'np_tracking_sync (auto)');
          END IF;
        END IF;
      ELSE
        -- رد فاشل/منتهي المهلة: حدّث وقت الفحص ليُعاد لاحقاً دون إغراق
        UPDATE ecommerce_shipments
        SET np_last_checked = now(), updated_at = now()
        WHERE id = v_req.shipment_id;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'np_tracking_sync response error (queue %): %', v_req.queue_id, SQLERRM;
    END;

    DELETE FROM np_tracking_requests WHERE id = v_req.queue_id;
  END LOOP;

  -- تنظيف طلبات يتيمة قديمة (رد لم يصل خلال ساعة — pg_net يحذف ردوده دورياً)
  DELETE FROM np_tracking_requests WHERE created_at < now() - interval '1 hour';

  -- ═══ ب) إرسال طلبات تتبع جديدة (حد 50 لكل دورة) ═══
  FOR v_enq IN
    SELECT s.id, s.tracking_number,
           (c.integrations->'nova_poshta'->>'api_key') AS api_key
    FROM ecommerce_shipments s
    JOIN companies c ON c.tenant_id = s.tenant_id
      AND (c.integrations->'nova_poshta'->>'api_key') IS NOT NULL
      AND COALESCE((c.integrations->'nova_poshta'->>'enabled')::boolean, true)
    WHERE s.carrier = 'nova_poshta'
      AND s.tracking_number IS NOT NULL
      AND s.status NOT IN ('delivered','returned','failed')
      AND (s.np_last_checked IS NULL OR s.np_last_checked < now() - interval '20 minutes')
      AND NOT EXISTS (SELECT 1 FROM np_tracking_requests q WHERE q.shipment_id = s.id)
    LIMIT 50
  LOOP
    BEGIN
      SELECT net.http_post(
        url     := 'https://api.novaposhta.ua/v2.0/json/',
        body    := jsonb_build_object(
          'apiKey', v_enq.api_key,
          'modelName', 'TrackingDocument',
          'calledMethod', 'getStatusDocuments',
          'methodProperties', jsonb_build_object(
            'Documents', jsonb_build_array(
              jsonb_build_object('DocumentNumber', v_enq.tracking_number, 'Phone', '')
            )
          )
        ),
        headers := '{"Content-Type": "application/json"}'::jsonb,
        timeout_milliseconds := 8000
      ) INTO v_request_id;

      INSERT INTO np_tracking_requests (shipment_id, request_id)
      VALUES (v_enq.id, v_request_id);
      v_sent := v_sent + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'np_tracking_sync enqueue error (shipment %): %', v_enq.id, SQLERRM;
    END;
  END LOOP;

  IF v_sent > 0 THEN
    RAISE NOTICE 'np_tracking_sync: % tracking request(s) sent', v_sent;
  END IF;
END;
$$;


