--
-- Name: pbx_create_conversation(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.pbx_create_conversation(p_company_id uuid, p_creator_id uuid, p_other_user_id uuid, p_name text, p_type text DEFAULT 'direct'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  conv_id uuid;
  result json;
  v_caller uuid := auth.uid();
  v_trusted boolean := (auth.role() = 'service_role' OR auth.uid() IS NULL);
  v_creator uuid;
  v_company uuid;
  v_other_company uuid;
BEGIN
  -- ── IDENTITY: the creator is always the authenticated caller (never trust client) ──
  IF v_trusted THEN
    v_creator := COALESCE(p_creator_id, v_caller);
  ELSE
    v_creator := v_caller;
    IF v_creator IS NULL THEN
      RAISE EXCEPTION 'Not authenticated';
    END IF;
  END IF;

  -- ── COMPANY: internal PBX/CRM is STRICT per-company; derive from the creator ──
  v_company := public.get_user_company_id(v_creator);
  IF NOT v_trusted THEN
    IF v_company IS NULL THEN
      RAISE EXCEPTION 'Caller has no company';
    END IF;
    -- if a client passed a company, it must match the caller's own company
    IF p_company_id IS NOT NULL AND p_company_id <> v_company THEN
      RAISE EXCEPTION 'Forbidden: cross-company conversation';
    END IF;
  ELSE
    v_company := COALESCE(p_company_id, v_company);
  END IF;

  -- ── PARTICIPANT must belong to the SAME company (no cross-company internal chat) ──
  IF p_other_user_id IS NOT NULL AND NOT v_trusted THEN
    v_other_company := public.get_user_company_id(p_other_user_id);
    IF v_other_company IS DISTINCT FROM v_company THEN
      RAISE EXCEPTION 'Forbidden: other user is not in your company';
    END IF;
  END IF;

  -- Check for existing direct conversation
  IF p_type = 'direct' THEN
    SELECT cm1.conversation_id INTO conv_id
    FROM nexa_conversation_members cm1
    JOIN nexa_conversation_members cm2 ON cm1.conversation_id = cm2.conversation_id
    JOIN nexa_conversations c ON c.id = cm1.conversation_id
    WHERE cm1.user_id = v_creator
      AND cm2.user_id = p_other_user_id
      AND c.type = 'direct'
    LIMIT 1;

    IF conv_id IS NOT NULL THEN
      SELECT row_to_json(c.*) INTO result FROM nexa_conversations c WHERE c.id = conv_id;
      RETURN result;
    END IF;
  END IF;

  -- Create new
  INSERT INTO nexa_conversations (company_id, type, name, created_by)
  VALUES (v_company, p_type, p_name, v_creator)
  RETURNING id INTO conv_id;

  -- creator role: valid per nexa_conversation_members_role_check (admin|member)
  INSERT INTO nexa_conversation_members (conversation_id, user_id, role)
  VALUES (conv_id, v_creator, 'admin');

  IF p_other_user_id IS NOT NULL AND p_other_user_id <> v_creator THEN
    INSERT INTO nexa_conversation_members (conversation_id, user_id, role)
    VALUES (conv_id, p_other_user_id, 'member');
  END IF;

  SELECT row_to_json(c.*) INTO result FROM nexa_conversations c WHERE c.id = conv_id;
  RETURN result;
END;
$$;


--
-- Name: pbx_customer_agent_bindings(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.pbx_customer_agent_bindings(p_company_id uuid, p_limit integer DEFAULT 200) RETURNS TABLE(phone text, extension text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT ON (ph) ph AS phone, e.extension_number AS extension
  FROM (
    SELECT sales_agent_id, regexp_replace(phone,  '\D', '', 'g') AS ph FROM public.customers
      WHERE company_id = p_company_id AND sales_agent_id IS NOT NULL AND phone  IS NOT NULL
    UNION
    SELECT sales_agent_id, regexp_replace(mobile, '\D', '', 'g') AS ph FROM public.customers
      WHERE company_id = p_company_id AND sales_agent_id IS NOT NULL AND mobile IS NOT NULL
  ) c
  JOIN public.pbx_extensions e
    ON e.assigned_user_id = c.sales_agent_id AND e.company_id = p_company_id AND e.is_active
  WHERE length(c.ph) >= 4
  ORDER BY ph
  LIMIT p_limit
$$;


--
-- Name: pbx_get_contacts(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.pbx_get_contacts(p_tenant_id uuid, p_company_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result json;
  v_is_backend boolean := (auth.role() = 'service_role' OR auth.uid() IS NULL);
  v_tenant_id uuid;
  v_company_id uuid;
BEGIN
  -- Internal PBX + CRM = STRICT PER-COMPANY/TENANT private business data.
  -- A subscriber must NEVER read another company's CRM contacts or extensions.
  IF v_is_backend THEN
    -- Trusted backend call (service_role / no auth uid): honor the supplied scope.
    v_tenant_id  := p_tenant_id;
    v_company_id := p_company_id;
  ELSE
    -- End-user call: identity is ALWAYS auth.uid(); ignore client-supplied params.
    v_tenant_id  := get_user_tenant_id();
    v_company_id := get_user_company_id();
  END IF;

  -- Unresolvable caller leaks nothing.
  IF v_tenant_id IS NULL AND v_company_id IS NULL THEN
    RETURN json_build_object('customers', '[]'::json, 'suppliers', '[]'::json, 'extensions', '[]'::json);
  END IF;

  SELECT json_build_object(
    'customers', COALESCE((
      SELECT json_agg(json_build_object(
        'id', c.id,
        'name_ar', c.name_ar,
        'name_en', c.name_en,
        'phone', c.phone,
        'mobile', c.mobile,
        'company_name', c.company_name,
        'email', c.email
      ))
      FROM customers c
      WHERE c.tenant_id = v_tenant_id
        AND c.status = 'active'
        AND (c.phone IS NOT NULL AND c.phone != '' OR c.mobile IS NOT NULL AND c.mobile != '')
    ), '[]'::json),
    'suppliers', COALESCE((
      SELECT json_agg(json_build_object(
        'id', s.id,
        'name_ar', s.name_ar,
        'name_en', s.name_en,
        'phone', s.phone,
        'mobile', s.mobile,
        'company_name', s.company_name,
        'email', s.email
      ))
      FROM suppliers s
      WHERE s.tenant_id = v_tenant_id
        AND s.status = 'active'
        AND (s.phone IS NOT NULL AND s.phone != '' OR s.mobile IS NOT NULL AND s.mobile != '')
    ), '[]'::json),
    'extensions', COALESCE((
      SELECT json_agg(json_build_object(
        'id', e.id,
        'extension_number', e.extension_number,
        'display_name', e.display_name
      ))
      FROM pbx_extensions e
      WHERE e.company_id = v_company_id
    ), '[]'::json)
  ) INTO result;

  RETURN result;
END;
$$;


--
-- Name: pbx_get_conversations(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.pbx_get_conversations(p_user_id uuid, p_company_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_is_backend boolean := (auth.role() = 'service_role' OR auth.uid() IS NULL);
  v_user_id    uuid;
  v_company_id uuid;
BEGIN
  -- IDENTITY: the acting user is ALWAYS auth.uid() for end-user calls.
  -- Trusted backend calls (service_role / no JWT) may act for the passed user.
  IF v_is_backend THEN
    v_user_id := p_user_id;
  ELSE
    v_user_id := auth.uid();
  END IF;

  IF v_user_id IS NULL THEN
    RETURN '[]'::json;
  END IF;

  -- Internal PBX = strict per-company: company is derived from the acting user.
  -- Backend may pass an explicit company; otherwise derive from the user.
  IF v_is_backend AND p_company_id IS NOT NULL THEN
    v_company_id := p_company_id;
  ELSE
    v_company_id := public.get_user_company_id(v_user_id);
  END IF;

  RETURN COALESCE((
    SELECT json_agg(row_to_json(conv_data) ORDER BY conv_data.updated_at DESC)
    FROM (
      SELECT
        c.id,
        c.type,
        c.name,
        c.avatar_url,
        c.updated_at,
        m.is_pinned,
        m.is_muted,
        m.last_read_at,
        (SELECT content FROM nexa_messages msg WHERE msg.conversation_id = c.id ORDER BY msg.created_at DESC LIMIT 1) as last_message,
        (SELECT sender_id FROM nexa_messages msg WHERE msg.conversation_id = c.id ORDER BY msg.created_at DESC LIMIT 1) as last_sender_id,
        (SELECT created_at FROM nexa_messages msg WHERE msg.conversation_id = c.id ORDER BY msg.created_at DESC LIMIT 1) as last_message_at,
        (SELECT count(*) FROM nexa_messages msg
          WHERE msg.conversation_id = c.id
          AND msg.sender_id != v_user_id
          AND msg.created_at > COALESCE(m.last_read_at, '1970-01-01'::timestamptz)
        )::int as unread_count
      FROM nexa_conversations c
      JOIN nexa_conversation_members m ON m.conversation_id = c.id AND m.user_id = v_user_id
      WHERE c.company_id = v_company_id
    ) conv_data
  ), '[]'::json);
END;
$$;


--
-- Name: pbx_get_messages(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.pbx_get_messages(p_conversation_id uuid, p_limit integer DEFAULT 100) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_uid          uuid := auth.uid();
  v_is_backend   boolean := (auth.role() = 'service_role' OR auth.uid() IS NULL);
  v_conv_company uuid;
  v_allowed      boolean := false;
BEGIN
  IF p_conversation_id IS NULL THEN
    RETURN '[]'::json;
  END IF;

  IF v_is_backend THEN
    v_allowed := true;
  ELSE
    -- Access := caller is a member of the conversation
    --        OR the conversation belongs to the caller's own company.
    SELECT company_id INTO v_conv_company
    FROM nexa_conversations
    WHERE id = p_conversation_id;

    IF v_conv_company IS NULL THEN
      RETURN '[]'::json;   -- unknown conversation: no existence oracle
    END IF;

    v_allowed := EXISTS (
      SELECT 1 FROM nexa_conversation_members m
      WHERE m.conversation_id = p_conversation_id
        AND m.user_id = v_uid
    ) OR can_access_company(v_conv_company, v_uid);
  END IF;

  IF NOT v_allowed THEN
    RETURN '[]'::json;
  END IF;

  RETURN COALESCE((
    SELECT json_agg(row_to_json(msg_data) ORDER BY msg_data.created_at ASC)
    FROM (
      SELECT id, conversation_id, sender_id, content, type,
             media_url, media_metadata, reply_to_id,
             is_edited, is_deleted, created_at, updated_at
      FROM nexa_messages
      WHERE conversation_id = p_conversation_id
      ORDER BY created_at DESC
      LIMIT p_limit
    ) msg_data
  ), '[]'::json);
END;
$$;


