--
-- Name: pbx_provision_company(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.pbx_provision_company(p_company_id uuid, p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_ext_id uuid; v_num int; v_name text; v_tries int := 0;
BEGIN
  IF p_company_id IS NULL OR p_user_id IS NULL THEN RETURN NULL; END IF;

  INSERT INTO pbx_company_settings (company_id) VALUES (p_company_id)
    ON CONFLICT (company_id) DO NOTHING;

  SELECT eu.extension_id INTO v_ext_id
    FROM pbx_extension_users eu JOIN pbx_extensions e ON e.id = eu.extension_id
    WHERE eu.user_id = p_user_id AND e.company_id = p_company_id LIMIT 1;
  IF v_ext_id IS NOT NULL THEN
    -- ضمان تناسق الإسناد المباشر للعرض
    UPDATE pbx_extensions SET assigned_user_id = p_user_id
      WHERE id = v_ext_id AND assigned_user_id IS NULL;
    RETURN v_ext_id;
  END IF;

  v_name := COALESCE(
    (SELECT NULLIF(btrim(full_name), '') FROM user_profiles WHERE id = p_user_id),
    (SELECT email FROM user_profiles WHERE id = p_user_id), 'Extension');

  LOOP
    v_tries := v_tries + 1;
    SELECT COALESCE(max(extension_number::int), 99) + 1 INTO v_num
      FROM pbx_extensions WHERE company_id = p_company_id AND extension_number ~ '^[0-9]+$';
    BEGIN
      INSERT INTO pbx_extensions (company_id, extension_number, display_name, sip_password, is_active, assigned_user_id)
        VALUES (p_company_id, v_num::text, v_name, encode(gen_random_bytes(16), 'hex'), true, p_user_id)
        RETURNING id INTO v_ext_id;
      EXIT;
    EXCEPTION WHEN unique_violation THEN
      IF v_tries >= 5 THEN RAISE; END IF;
    END;
  END LOOP;

  INSERT INTO pbx_extension_users (extension_id, user_id, is_primary, is_active)
    VALUES (v_ext_id, p_user_id, true, true)
    ON CONFLICT (extension_id, user_id) DO NOTHING;

  RETURN v_ext_id;
END;
$_$;


--
-- Name: pbx_seed_company_telephony(uuid, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.pbx_seed_company_telephony(p_company_id uuid, p_ext_start integer DEFAULT 100, p_ext_end integer DEFAULT 199, p_access_number text DEFAULT '700'::text, p_company_name text DEFAULT 'شركتنا'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_ivr uuid;
BEGIN
  IF p_company_id IS NULL THEN RETURN NULL; END IF;

  -- نطاق التحويلات (لا يطمس قيمة موجودة)
  INSERT INTO pbx_company_settings (company_id, ext_range_start, ext_range_end)
    VALUES (p_company_id, p_ext_start, p_ext_end)
    ON CONFLICT (company_id) DO UPDATE
      SET ext_range_start = EXCLUDED.ext_range_start, ext_range_end = EXCLUDED.ext_range_end
      WHERE pbx_company_settings.ext_range_start IS NULL;

  -- IVR رئيسي (idempotent بالاسم)
  SELECT id INTO v_ivr FROM pbx_ivr_menus WHERE company_id = p_company_id AND name = 'IVR الرئيسي' LIMIT 1;
  IF v_ivr IS NULL THEN
    INSERT INTO pbx_ivr_menus (company_id, name, type, text_content, voice_id, is_active)
    VALUES (p_company_id, 'IVR الرئيسي', 'greeting',
      'مرحباً بكم في ' || p_company_name || '. للمبيعات اضغط 1، للدعم الفني اضغط 2، أو ابقَ على الخط للتحدث مع موظف.',
      'pNInz6obpgDQGcFmaJcg', true)
    RETURNING id INTO v_ivr;
  END IF;

  -- توجيه وارد: الرقم العام → IVR (idempotent)
  IF NOT EXISTS (
    SELECT 1 FROM pbx_call_routing
    WHERE company_id = p_company_id AND action = 'ivr' AND action_target::text = v_ivr::text
  ) THEN
    INSERT INTO pbx_call_routing (company_id, name, priority, direction, condition_type, condition_value, action, action_target)
    VALUES (p_company_id, 'توجيه الرقم العام → IVR', 1, 'inbound', 'all',
            jsonb_build_object('value', p_access_number), 'ivr', v_ivr::text);
  END IF;

  RETURN v_ivr;
END;
$$;


--
-- Name: pbx_send_message(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.pbx_send_message(p_conversation_id uuid, p_sender_id uuid, p_content text, p_type text DEFAULT 'text'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_backend boolean := (auth.role() = 'service_role' OR auth.uid() IS NULL);
  v_sender uuid;
  new_msg json;
BEGIN
  IF v_is_backend THEN
    -- trusted backend: may set sender explicitly, fall back to caller
    v_sender := COALESCE(p_sender_id, v_uid);
    IF v_sender IS NULL THEN
      RAISE EXCEPTION 'sender required';
    END IF;
  ELSE
    -- identity is always auth.uid(); ignore client-supplied p_sender_id (no impersonation)
    v_sender := v_uid;
    -- access = membership of the conversation
    IF NOT EXISTS (
      SELECT 1 FROM nexa_conversation_members m
      WHERE m.conversation_id = p_conversation_id
        AND m.user_id = v_uid
    ) THEN
      RAISE EXCEPTION 'not authorized to send to this conversation';
    END IF;
  END IF;

  INSERT INTO nexa_messages (conversation_id, sender_id, content, type)
  VALUES (p_conversation_id, v_sender, p_content, p_type)
  RETURNING row_to_json(nexa_messages.*) INTO new_msg;

  UPDATE nexa_conversations SET updated_at = now() WHERE id = p_conversation_id;

  RETURN new_msg;
END;
$$;


--
-- Name: pbx_send_message(uuid, uuid, text, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.pbx_send_message(p_conversation_id uuid, p_sender_id uuid, p_content text, p_type text DEFAULT 'text'::text, p_media_url text DEFAULT NULL::text, p_media_metadata jsonb DEFAULT NULL::jsonb, p_reply_to_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_backend boolean := (auth.role() = 'service_role' OR auth.uid() IS NULL);
  v_sender uuid;
  new_msg json;
BEGIN
  IF v_is_backend THEN
    v_sender := COALESCE(p_sender_id, v_uid);
    IF v_sender IS NULL THEN
      RAISE EXCEPTION 'sender required';
    END IF;
  ELSE
    v_sender := v_uid;
    IF NOT EXISTS (
      SELECT 1 FROM nexa_conversation_members m
      WHERE m.conversation_id = p_conversation_id
        AND m.user_id = v_uid
    ) THEN
      RAISE EXCEPTION 'not authorized to send to this conversation';
    END IF;
  END IF;

  INSERT INTO nexa_messages (conversation_id, sender_id, content, type, media_url, media_metadata, reply_to_id)
  VALUES (p_conversation_id, v_sender, p_content, p_type, p_media_url, p_media_metadata, p_reply_to_id)
  RETURNING row_to_json(nexa_messages.*) INTO new_msg;

  UPDATE nexa_conversations SET updated_at = now() WHERE id = p_conversation_id;

  RETURN new_msg;
END;
$$;


