--
-- Name: pbx_sticky_bindings(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.pbx_sticky_bindings(p_company_id uuid, p_limit integer DEFAULT 200) RETURNS TABLE(caller text, extension text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT ON (regexp_replace(caller, '\D', '', 'g'))
    regexp_replace(caller, '\D', '', 'g') AS caller, handled_extension AS extension
  FROM public.pbx_call_logs
  WHERE company_id = p_company_id AND handled_extension IS NOT NULL AND caller IS NOT NULL
    AND length(regexp_replace(caller, '\D', '', 'g')) >= 4
  ORDER BY regexp_replace(caller, '\D', '', 'g'), created_at DESC
  LIMIT p_limit
$$;


--
-- Name: post_journal_entry(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.post_journal_entry(p_entry_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_entry RECORD;
    v_line RECORD;
BEGIN
    IF p_entry_id IS NULL THEN
        RAISE EXCEPTION 'رقم القيد مطلوب';
    END IF;

    SELECT * INTO v_entry FROM journal_entries WHERE id = p_entry_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'القيد غير موجود: %', p_entry_id;
    END IF;

    IF v_entry.is_posted THEN
        RAISE EXCEPTION 'القيد مرحّل مسبقاً: %', v_entry.entry_number;
    END IF;

    -- [4I] منع الترحيل في فترة/سنة مالية مغلقة
    IF EXISTS (
        SELECT 1 FROM accounting_periods ap
        WHERE ap.company_id = v_entry.company_id AND COALESCE(ap.is_closed, false) = true
          AND v_entry.entry_date BETWEEN ap.start_date AND ap.end_date
    ) OR EXISTS (
        SELECT 1 FROM fiscal_years fy
        WHERE fy.company_id = v_entry.company_id AND COALESCE(fy.is_closed, false) = true
          AND v_entry.entry_date BETWEEN fy.start_date AND fy.end_date
    ) THEN
        RAISE EXCEPTION 'لا يمكن الترحيل في فترة/سنة مالية مغلقة (التاريخ %)', v_entry.entry_date
            USING ERRCODE = 'check_violation';
    END IF;

    -- Strict Balance Check
    IF ABS(v_entry.total_debit - v_entry.total_credit) > 0.01 THEN
        RAISE EXCEPTION 'القيد غير متوازن! الفرق: % (مدين: %, دائن: %)',
            ABS(v_entry.total_debit - v_entry.total_credit), v_entry.total_debit, v_entry.total_credit;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM journal_entry_lines WHERE entry_id = p_entry_id) THEN
        RAISE EXCEPTION 'القيد لا يحتوي على أسطر';
    END IF;

    FOR v_line IN SELECT * FROM journal_entry_lines WHERE entry_id = p_entry_id
    LOOP
        UPDATE chart_of_accounts
        SET current_balance = COALESCE(current_balance, 0) + (v_line.debit - v_line.credit),
            current_balance_fc = COALESCE(current_balance_fc, 0) + (COALESCE(v_line.debit_fc, 0) - COALESCE(v_line.credit_fc, 0)),
            updated_at = NOW()
        WHERE id = v_line.account_id;
    END LOOP;

    UPDATE journal_entries
    SET is_posted = true, posted_at = NOW(), posted_by = p_user_id, status = 'posted'
    WHERE id = p_entry_id;

    RETURN true;
END;
$$;


--
-- Name: post_purchase_invoice(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.post_purchase_invoice(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_invoice    purchase_invoices%ROWTYPE;
    v_je_id      UUID;
    v_user_id    UUID;
    v_account_purchases UUID;
    v_account_ap        UUID;
    v_account_tax       UUID;
    v_net_amount NUMERIC(15,4);
    v_tax_amount NUMERIC(15,4);
    v_total      NUMERIC(15,4);
    v_purch_debit NUMERIC(15,4);
    v_line_num   INT := 0;
BEGIN
    v_user_id := auth.uid();

    SELECT * INTO v_invoice FROM purchase_invoices WHERE id = p_invoice_id FOR UPDATE;   -- [4E] قفل
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'الفاتورة غير موجودة');
    END IF;

    PERFORM assert_can_access_company(v_invoice.company_id);   -- [4E] عزل المستأجر

    IF v_invoice.is_posted = true THEN
        RETURN jsonb_build_object('success', false, 'error', 'الفاتورة مُرحَّلة مسبقاً');
    END IF;

    v_total := COALESCE(v_invoice.total_amount, 0);
    v_tax_amount := COALESCE(v_invoice.tax_amount, 0);
    v_net_amount := v_total - v_tax_amount;

    IF v_total <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'مبلغ الفاتورة صفر');
    END IF;

    -- الحسابات (مقيّدة بالمستأجر/الشركة — أكواد موسّعة لتعدّد المخطّطات: 521 عربي / 5100 رقمي)
    -- المشتريات (يفضّل الورقة 521/5100 على الملخّص 52)
    SELECT id INTO v_account_purchases FROM chart_of_accounts
    WHERE company_id = v_invoice.company_id
      AND account_code IN ('521', '5100', '5000', '52', '1400')
      AND COALESCE(is_group, false) = false
    ORDER BY CASE account_code WHEN '521' THEN 0 WHEN '5100' THEN 1 WHEN '5000' THEN 2 ELSE 3 END LIMIT 1;
    IF v_account_purchases IS NULL THEN
        SELECT id INTO v_account_purchases FROM chart_of_accounts
        WHERE company_id = v_invoice.company_id AND account_code IN ('521','5100','5000','52','1400')
        ORDER BY CASE account_code WHEN '521' THEN 0 WHEN '5100' THEN 1 WHEN '5000' THEN 2 ELSE 3 END LIMIT 1;
    END IF;

    -- الذمم الدائنة: حساب المورد الفرعي أولاً، ثم العام (2111/211/2100)
    IF v_invoice.supplier_id IS NOT NULL THEN
        SELECT id INTO v_account_ap FROM chart_of_accounts
        WHERE company_id = v_invoice.company_id AND is_party_account = true
          AND party_type = 'supplier' AND party_id = v_invoice.supplier_id LIMIT 1;
    END IF;
    -- تحديد دوري (GL-6 الصحيح): أي حساب دائن قابل للترحيل
    IF v_account_ap IS NULL THEN
        SELECT id INTO v_account_ap FROM chart_of_accounts
        WHERE company_id = v_invoice.company_id
          AND COALESCE(is_payable, false) = true
          AND COALESCE(is_group, false) = false
        ORDER BY account_code LIMIT 1;
    END IF;
    -- fallback أخير بالأكواد (تُرحَّل لحساب ورقة فقط)
    IF v_account_ap IS NULL THEN
        SELECT id INTO v_account_ap FROM chart_of_accounts
        WHERE company_id = v_invoice.company_id
          AND account_code IN ('2112', '2111', '211', '2100', '2000')
          AND COALESCE(is_group, false) = false
        ORDER BY CASE account_code WHEN '2112' THEN 0 WHEN '2100' THEN 1 ELSE 2 END LIMIT 1;
    END IF;

    -- ضريبة المدخلات (موسّعة): 1190/1180 عربي / 1510/1500 رقمي
    IF v_tax_amount > 0 THEN
        SELECT id INTO v_account_tax FROM chart_of_accounts
        WHERE company_id = v_invoice.company_id
          AND account_code IN ('1190', '1180', '1510', '1500', '119')
          AND COALESCE(is_group, false) = false
        ORDER BY CASE account_code WHEN '1190' THEN 0 WHEN '1180' THEN 1 WHEN '1510' THEN 2 ELSE 3 END LIMIT 1;
    END IF;

    IF v_account_purchases IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'لم يُعثر على حساب المشتريات (5100/5000/1400)', 'invoice_id', p_invoice_id);
    END IF;
    IF v_account_ap IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'لم يُعثر على حساب الذمم الدائنة (2100/2000)', 'invoice_id', p_invoice_id);
    END IF;

    -- مبلغ المشتريات المدين (الضريبة منفصلة إن وُجد حسابها، وإلا مدمجة)
    v_purch_debit := CASE WHEN v_tax_amount > 0 AND v_account_tax IS NOT NULL THEN v_net_amount ELSE v_total END;

    UPDATE purchase_invoices
    SET status = 'posted', is_posted = true, posted_at = NOW(), updated_at = NOW()
    WHERE id = p_invoice_id;

    -- القيد (مسودة) — total_debit/total_credit للحارس
    INSERT INTO journal_entries (
        tenant_id, company_id, branch_id, entry_date, entry_type, description,
        reference_type, reference_id, reference_number, currency, exchange_rate,
        total_debit, total_credit, status, is_posted, created_by
    ) VALUES (
        v_invoice.tenant_id, v_invoice.company_id, v_invoice.branch_id,
        COALESCE(v_invoice.invoice_date, CURRENT_DATE), 'auto',
        'فاتورة مشتريات — ' || COALESCE(v_invoice.invoice_number, ''),
        'purchase_invoice', p_invoice_id, v_invoice.invoice_number,
        COALESCE(v_invoice.currency, 'SAR'), COALESCE(v_invoice.exchange_rate, 1),
        v_total, v_total, 'draft', false, v_user_id
    ) RETURNING id INTO v_je_id;

    -- مدين: المشتريات
    v_line_num := v_line_num + 1;
    INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, description, debit, credit, debit_fc, credit_fc)
    VALUES (v_invoice.tenant_id, v_je_id, v_line_num, v_account_purchases,
            'مشتريات — ' || COALESCE(v_invoice.invoice_number, ''), v_purch_debit, 0, v_purch_debit, 0);

    -- مدين: ضريبة المدخلات
    IF v_tax_amount > 0 AND v_account_tax IS NOT NULL THEN
        v_line_num := v_line_num + 1;
        INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, description, debit, credit, debit_fc, credit_fc)
        VALUES (v_invoice.tenant_id, v_je_id, v_line_num, v_account_tax,
                'ضريبة مدخلات — ' || COALESCE(v_invoice.invoice_number, ''), v_tax_amount, 0, v_tax_amount, 0);
    END IF;

    -- دائن: الذمم الدائنة
    v_line_num := v_line_num + 1;
    INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, description, debit, credit, debit_fc, credit_fc, party_type, party_id)
    VALUES (v_invoice.tenant_id, v_je_id, v_line_num, v_account_ap,
            'ذمم دائنة — ' || COALESCE(v_invoice.supplier_name, '') || ' — ' || COALESCE(v_invoice.invoice_number, ''),
            0, v_total, 0, v_total, 'supplier', v_invoice.supplier_id);

    -- الترحيل عبر post_journal_entry (تحديث الأرصدة + فحص التوازن)
    PERFORM post_journal_entry(v_je_id, v_user_id);

    UPDATE purchase_invoices SET journal_entry_id = v_je_id WHERE id = p_invoice_id;

    RETURN jsonb_build_object(
        'success', true, 'invoice_id', p_invoice_id, 'invoice_number', v_invoice.invoice_number,
        'journal_entry_id', v_je_id, 'total_amount', v_total, 'tax_amount', v_tax_amount,
        'message', 'تم ترحيل فاتورة المشتريات بنجاح'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'detail', SQLSTATE, 'invoice_id', p_invoice_id);
END;
$$;


--
-- Name: post_purchase_receipt(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.post_purchase_receipt(p_receipt_id uuid, p_warehouse_id uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_receipt      RECORD;
    v_item         JSONB;
    v_movement_count INT := 0;
    v_total_amount NUMERIC(15,4) := 0;
    v_je_id        UUID;
    v_movement_number VARCHAR(50);
    v_user_id      UUID;
    v_account_inventory UUID;
    v_account_ap   UUID;
    v_item_qty     NUMERIC(15,3);
    v_item_price   NUMERIC(15,4);
    v_item_total   NUMERIC(15,4);
BEGIN
    v_user_id := auth.uid();
    
    -- ════════════════════════════════════════════════════════
    -- الخطوة ٠: التحقق من سند الاستلام
    -- ════════════════════════════════════════════════════════
    SELECT * INTO v_receipt
    FROM purchase_receipts
    WHERE id = p_receipt_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'سند الاستلام غير موجود');
    END IF;
    
    IF v_receipt.status = 'completed' THEN
        RETURN jsonb_build_object('success', false, 'error', 'سند الاستلام مُرحَّل مسبقاً');
    END IF;
    
    -- ════════════════════════════════════════════════════════
    -- الخطوة ١: تحديث حالة سند الاستلام
    -- ════════════════════════════════════════════════════════
    UPDATE purchase_receipts
    SET status = 'completed',
        warehouse_id = COALESCE(p_warehouse_id, warehouse_id),
        updated_at = NOW()
    WHERE id = p_receipt_id;
    
    -- ════════════════════════════════════════════════════════
    -- الخطوة ٢: إنشاء حركات المخزون (واحدة لكل صنف)
    -- trigger: update_inventory_stock يحدّث inventory_stock تلقائياً
    -- ════════════════════════════════════════════════════════
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_item_qty   := COALESCE((v_item->>'quantity')::NUMERIC, 0);
        v_item_price := COALESCE((v_item->>'unit_price')::NUMERIC, 0);
        v_item_total := v_item_qty * v_item_price;
        v_total_amount := v_total_amount + v_item_total;
        v_movement_count := v_movement_count + 1;
        
        v_movement_number := 'GRN-' || COALESCE(v_receipt.receipt_number, '') || '-' || v_movement_count;
        
        INSERT INTO inventory_movements (
            tenant_id, company_id,
            movement_number, movement_date,
            movement_type,
            product_id, material_id, variant_id,
            to_warehouse_id,
            quantity, unit_cost, total_cost,
            reference_type, reference_id, reference_number,
            notes, created_by
        ) VALUES (
            v_receipt.tenant_id, v_receipt.company_id,
            v_movement_number, CURRENT_DATE,
            'receipt',
            (v_item->>'product_id')::UUID,
            (v_item->>'material_id')::UUID,
            (v_item->>'variant_id')::UUID,
            COALESCE(p_warehouse_id, v_receipt.warehouse_id),
            v_item_qty, v_item_price, v_item_total,
            'purchase_receipt', p_receipt_id, v_receipt.receipt_number,
            COALESCE(v_item->>'description', 'استلام مشتريات'),
            v_user_id
        );
    END LOOP;
    
    -- ════════════════════════════════════════════════════════
    -- الخطوة ٣: إنشاء قيد محاسبي
    -- مدين: المخزون (1400)  /  دائن: الموردون (2100)
    -- 
    -- ملاحظة: entry_number يتولّد تلقائياً بواسطة generate_entry_number trigger
    -- ملاحظة: total_debit/total_credit تتحسب بواسطة update_journal_entry_totals trigger
    -- ════════════════════════════════════════════════════════
    
    -- البحث عن حساب المخزون (خاص بالشركة أولاً، ثم عام)
    SELECT id INTO v_account_inventory
    FROM chart_of_accounts
    WHERE tenant_id = v_receipt.tenant_id
      AND (company_id = v_receipt.company_id OR company_id IS NULL)
      AND account_code = '1400'
    ORDER BY CASE WHEN company_id = v_receipt.company_id THEN 0 ELSE 1 END
    LIMIT 1;
    
    -- البحث عن حساب الموردين / الذمم الدائنة
    SELECT id INTO v_account_ap
    FROM chart_of_accounts
    WHERE tenant_id = v_receipt.tenant_id
      AND (company_id = v_receipt.company_id OR company_id IS NULL)
      AND account_code IN ('2100', '2108')
    ORDER BY CASE WHEN account_code = '2100' THEN 0 ELSE 1 END,
             CASE WHEN company_id = v_receipt.company_id THEN 0 ELSE 1 END
    LIMIT 1;
    
    IF v_account_inventory IS NOT NULL AND v_account_ap IS NOT NULL AND v_total_amount > 0 THEN
        -- إنشاء رأس القيد (entry_number يتولّد تلقائياً)
        INSERT INTO journal_entries (
            tenant_id, company_id, branch_id,
            entry_date, entry_type,
            description,
            reference_type, reference_id, reference_number,
            status, is_posted, posted_at, posted_by,
            created_by
        ) VALUES (
            v_receipt.tenant_id, v_receipt.company_id, v_receipt.branch_id,
            CURRENT_DATE, 'auto',
            'قيد استلام مشتريات — ' || COALESCE(v_receipt.receipt_number, ''),
            'purchase_receipt', p_receipt_id, v_receipt.receipt_number,
            'posted', true, NOW(), v_user_id,
            v_user_id
        ) RETURNING id INTO v_je_id;
        
        -- سطر مدين: المخزون
        INSERT INTO journal_entry_lines (
            tenant_id, entry_id, line_number,
            account_id, description,
            debit, credit,
            party_type, party_id
        ) VALUES (
            v_receipt.tenant_id, v_je_id, 1,
            v_account_inventory,
            'استلام مخزني — ' || COALESCE(v_receipt.receipt_number, ''),
            v_total_amount, 0,
            NULL, NULL
        );
        
        -- سطر دائن: الموردون
        INSERT INTO journal_entry_lines (
            tenant_id, entry_id, line_number,
            account_id, description,
            debit, credit,
            party_type, party_id
        ) VALUES (
            v_receipt.tenant_id, v_je_id, 2,
            v_account_ap,
            'تسوية استلام — ' || COALESCE(v_receipt.receipt_number, ''),
            0, v_total_amount,
            'supplier', v_receipt.supplier_id
        );
        
        -- ربط القيد بسند الاستلام
        UPDATE purchase_receipts
        SET journal_entry_id = v_je_id
        WHERE id = p_receipt_id;
    END IF;
    
    -- ════════════════════════════════════════════════════════
    -- الخطوة ٤: تحديث حالة المستند المصدر
    -- ════════════════════════════════════════════════════════
    IF v_receipt.invoice_id IS NOT NULL THEN
        UPDATE purchase_invoices
        SET receiving_status = 'received', updated_at = NOW()
        WHERE id = v_receipt.invoice_id;
    END IF;
    
    IF v_receipt.order_id IS NOT NULL THEN
        UPDATE purchase_orders
        SET updated_at = NOW()
        WHERE id = v_receipt.order_id;
    END IF;
    
    RETURN jsonb_build_object(
        'success', true,
        'receipt_id', p_receipt_id,
        'receipt_number', v_receipt.receipt_number,
        'movements_created', v_movement_count,
        'total_amount', v_total_amount,
        'journal_entry_id', v_je_id,
        'message', 'تم ترحيل سند الاستلام بنجاح'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM,
        'detail', SQLSTATE,
        'receipt_id', p_receipt_id
    );
END;
$$;


--
-- Name: post_purchase_return(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.post_purchase_return(p_return_id uuid, p_warehouse_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_return       RECORD;
    v_item         RECORD;
    v_je_id        UUID;
    v_user_id      UUID;
    v_total        NUMERIC(15,4) := 0;
    v_movement_count INT := 0;
    v_account_inventory UUID;
    v_account_ap   UUID;
    v_movement_number VARCHAR(50);
    v_wh_id        UUID;
BEGIN
    v_user_id := auth.uid();
    
    SELECT * INTO v_return FROM purchase_returns WHERE id = p_return_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'مرتجع المشتريات غير موجود');
    END IF;
    
    IF v_return.status = 'posted' THEN
        RETURN jsonb_build_object('success', false, 'error', 'المرتجع مُرحَّل مسبقاً');
    END IF;
    
    v_wh_id := COALESCE(p_warehouse_id, v_return.warehouse_id);
    
    -- تحديث الحالة
    UPDATE purchase_returns SET status = 'posted', updated_at = NOW() WHERE id = p_return_id;
    
    -- معالجة البنود → حركات مخزون (خروج)
    FOR v_item IN SELECT * FROM purchase_return_items WHERE return_id = p_return_id
    LOOP
        v_movement_count := v_movement_count + 1;
        v_total := v_total + COALESCE(v_item.total, v_item.quantity_returned * COALESCE(v_item.unit_price, 0));
        
        v_movement_number := 'PR-' || COALESCE(v_return.return_number, '') || '-' || v_movement_count;
        
        INSERT INTO inventory_movements (
            tenant_id, company_id,
            movement_number, movement_date,
            movement_type,
            product_id, material_id, variant_id,
            from_warehouse_id,
            quantity, unit_cost, total_cost,
            reference_type, reference_id, reference_number,
            notes, created_by
        ) VALUES (
            v_return.tenant_id, v_return.company_id,
            v_movement_number, CURRENT_DATE,
            'return_out',
            v_item.product_id, v_item.material_id, v_item.variant_id,
            v_wh_id,
            v_item.quantity_returned, COALESCE(v_item.unit_price, 0),
            COALESCE(v_item.total, v_item.quantity_returned * COALESCE(v_item.unit_price, 0)),
            'purchase_return', p_return_id, v_return.return_number,
            'مرتجع مشتريات', v_user_id
        );
    END LOOP;
    
    -- القيد: مدين ذمم دائنة / دائن مخزون
    SELECT id INTO v_account_inventory FROM chart_of_accounts
    WHERE tenant_id = v_return.tenant_id
      AND (company_id = v_return.company_id OR company_id IS NULL)
      AND account_code = '1400'
    ORDER BY CASE WHEN company_id = v_return.company_id THEN 0 ELSE 1 END LIMIT 1;
    
    SELECT id INTO v_account_ap FROM chart_of_accounts
    WHERE tenant_id = v_return.tenant_id
      AND (company_id = v_return.company_id OR company_id IS NULL)
      AND account_code = '2100'
    ORDER BY CASE WHEN company_id = v_return.company_id THEN 0 ELSE 1 END LIMIT 1;
    
    IF v_account_inventory IS NOT NULL AND v_account_ap IS NOT NULL AND v_total > 0 THEN
        INSERT INTO journal_entries (
            tenant_id, company_id, branch_id,
            entry_date, entry_type,
            description,
            reference_type, reference_id, reference_number,
            status, is_posted, posted_at, posted_by,
            created_by
        ) VALUES (
            v_return.tenant_id, v_return.company_id, v_return.branch_id,
            CURRENT_DATE, 'auto',
            'مرتجع مشتريات — ' || COALESCE(v_return.return_number, ''),
            'purchase_return', p_return_id, v_return.return_number,
            'posted', true, NOW(), v_user_id,
            v_user_id
        ) RETURNING id INTO v_je_id;
        
        -- مدين: تخفيض ذمم دائنة
        INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, description, debit, credit, party_type, party_id)
        VALUES (v_return.tenant_id, v_je_id, 1, v_account_ap, 'تخفيض ذمم دائنة — مرتجع', v_total, 0, 'supplier', v_return.supplier_id);
        
        -- دائن: إرجاع مخزون
        INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, description, debit, credit)
        VALUES (v_return.tenant_id, v_je_id, 2, v_account_inventory, 'إرجاع مخزون — مرتجع مشتريات', 0, v_total);
    END IF;
    
    RETURN jsonb_build_object(
        'success', true,
        'return_id', p_return_id,
        'movements_created', v_movement_count,
        'total_amount', v_total,
        'journal_entry_id', v_je_id,
        'message', 'تم ترحيل مرتجع المشتريات بنجاح'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'detail', SQLSTATE);
END;
$$;


--
-- Name: post_sales_invoice(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.post_sales_invoice(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_trx         sales_transactions%ROWTYPE;
    v_account_ar  UUID;
    v_account_rev UUID;
    v_account_tax UUID;
    v_account_cogs UUID;
    v_account_inv UUID;
    v_je_id       UUID;
    v_user_id     UUID;
    v_total       NUMERIC(15,4) := 0;
    v_net_amount  NUMERIC(15,4) := 0;
    v_tax_amount  NUMERIC(15,4) := 0;
    v_delivered_subtotal NUMERIC(15,4) := 0;
    v_delivered_discount NUMERIC(15,4) := 0;
    v_cost_amount NUMERIC(15,4) := 0;
    v_line_num    INT := 0;
    v_entry_no    TEXT;
    v_inv_label   TEXT;
    v_item_count  INT := 0;
    v_has_delivered BOOLEAN := false;
    v_cogs_recorded BOOLEAN := false;   -- [P1] هل تُسجَّل أسطر COGS؟
    v_total_debit  NUMERIC(15,4) := 0;  -- [P1] توازن الرأس
    v_total_credit NUMERIC(15,4) := 0;  -- [P1] توازن الرأس
    v_shipping     NUMERIC(15,4) := 0;  -- [4K] مبلغ الشحن المحمَّل على العميل
    v_account_shipping UUID;            -- [4K] حساب إيراد الشحن
BEGIN
    v_user_id := auth.uid();

    -- 1. جلب بيانات الفاتورة (مع قفل الصف ضد الترحيل المزدوج) [P1]
    SELECT * INTO v_trx FROM sales_transactions WHERE id = p_invoice_id FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'الفاتورة غير موجودة');
    END IF;

    -- [P1] عزل المستأجر: يتجاوز service_role/الأدمن، ويحظر العمليات العابرة للشركات
    PERFORM assert_can_access_company(v_trx.company_id);

    IF v_trx.is_posted = true THEN
        RETURN jsonb_build_object('success', false, 'error', 'الفاتورة مُرحَّلة مسبقاً');
    END IF;

    v_inv_label := COALESCE(v_trx.invoice_no, v_trx.draft_no, LEFT(p_invoice_id::text, 8));

    -- 2. حساب المبالغ من البنود المسلّمة فعلياً
    SELECT COUNT(*) INTO v_item_count
    FROM sales_transaction_items sti
    WHERE sti.transaction_id = p_invoice_id
      AND COALESCE(sti.delivered_qty, 0) > 0;

    v_has_delivered := v_item_count > 0;

    -- [P1] الخصم يحترم discount_amount حين discount_percent=0 (مُقاساً بالكمية المسلّمة)،
    --      والضريبة تُحسب على الصافي بعد هذا الخصم (اتّساق إيراد/ضريبة).
    SELECT
        COALESCE(SUM(line_sub), 0),
        COALESCE(SUM(line_disc), 0),
        COALESCE(SUM((line_sub - line_disc) * line_tax_rate / 100), 0),
        COALESCE(SUM(line_cost), 0)
    INTO v_delivered_subtotal, v_delivered_discount, v_tax_amount, v_cost_amount
    FROM (
        SELECT
            COALESCE(sti.delivered_qty, 0) * COALESCE(sti.unit_price, 0) AS line_sub,
            CASE WHEN COALESCE(sti.discount_percent, 0) > 0
                 THEN COALESCE(sti.delivered_qty, 0) * COALESCE(sti.unit_price, 0) * sti.discount_percent / 100
                 ELSE COALESCE(sti.discount_amount, 0) * (COALESCE(sti.delivered_qty, 0) / NULLIF(sti.quantity, 0))
            END AS line_disc,
            COALESCE(sti.tax_rate, 0) AS line_tax_rate,
            COALESCE(sti.cost_price, 0) * COALESCE(sti.delivered_qty, 0) AS line_cost
        FROM sales_transaction_items sti
        WHERE sti.transaction_id = p_invoice_id
    ) t;

    v_net_amount := v_delivered_subtotal - v_delivered_discount;
    v_total := v_net_amount + v_tax_amount;

    -- Fallback: لا كميات مسلّمة ⇒ استخدم الفاتورة الأصلية
    IF NOT v_has_delivered THEN
        v_total := COALESCE(v_trx.total_amount, 0);
        v_tax_amount := COALESCE(v_trx.tax_amount, 0);
        v_net_amount := v_total - v_tax_amount;

        SELECT COALESCE(SUM(COALESCE(sti.cost_price, 0) * COALESCE(sti.quantity, 0)), 0)
        INTO v_cost_amount
        FROM sales_transaction_items sti
        WHERE sti.transaction_id = p_invoice_id;
    END IF;

    -- [4K] مبلغ الشحن المحمَّل على العميل
    v_shipping := GREATEST(COALESCE(v_trx.shipping_amount, 0), 0);

    IF v_total <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error',
            'مبلغ الفاتورة صفر أو سالب — تحقق من الكميات المسلّمة');
    END IF;

    -- 3. البحث عن الحسابات
    IF v_trx.customer_id IS NOT NULL THEN
        SELECT c.receivable_account_id INTO v_account_ar
        FROM customers c
        WHERE c.id = v_trx.customer_id AND c.receivable_account_id IS NOT NULL;

        IF v_account_ar IS NULL THEN
            SELECT id INTO v_account_ar
            FROM chart_of_accounts
            WHERE is_party_account = true AND party_type = 'customer' AND party_id = v_trx.customer_id
            LIMIT 1;
        END IF;
    END IF;

    IF v_account_ar IS NULL THEN
        SELECT id INTO v_account_ar
        FROM chart_of_accounts
        WHERE tenant_id = v_trx.tenant_id
          AND (company_id = v_trx.company_id OR company_id IS NULL)
          AND account_code IN ('1131', '1130', '113')
        ORDER BY CASE WHEN account_code = '1131' THEN 0 WHEN account_code = '1130' THEN 1 ELSE 2 END,
                 CASE WHEN company_id = v_trx.company_id THEN 0 ELSE 1 END
        LIMIT 1;
    END IF;

    SELECT id INTO v_account_rev
    FROM chart_of_accounts
    WHERE tenant_id = v_trx.tenant_id
      AND (company_id = v_trx.company_id OR company_id IS NULL)
      AND account_code IN ('4110', '4100', '411', '41')
    ORDER BY CASE WHEN account_code = '4110' THEN 0 WHEN account_code = '4100' THEN 1 WHEN account_code = '411' THEN 2 ELSE 3 END,
             CASE WHEN company_id = v_trx.company_id THEN 0 ELSE 1 END
    LIMIT 1;

    IF v_tax_amount > 0 THEN
        SELECT id INTO v_account_tax
        FROM chart_of_accounts
        WHERE tenant_id = v_trx.tenant_id
          AND (company_id = v_trx.company_id OR company_id IS NULL)
          AND account_code IN ('2130', '2141', '2150')
        ORDER BY CASE WHEN account_code = '2130' THEN 0 WHEN account_code = '2141' THEN 1 ELSE 2 END,
                 CASE WHEN company_id = v_trx.company_id THEN 0 ELSE 1 END
        LIMIT 1;
    END IF;

    SELECT id INTO v_account_cogs
    FROM chart_of_accounts
    WHERE tenant_id = v_trx.tenant_id
      AND (company_id = v_trx.company_id OR company_id IS NULL)
      AND account_code IN ('5100', '5110', '511', '51')
    ORDER BY CASE WHEN account_code = '5100' THEN 0 WHEN account_code = '5110' THEN 1 WHEN account_code = '511' THEN 2 ELSE 3 END,
             CASE WHEN company_id = v_trx.company_id THEN 0 ELSE 1 END
    LIMIT 1;

    SELECT id INTO v_account_inv
    FROM chart_of_accounts
    WHERE tenant_id = v_trx.tenant_id
      AND (company_id = v_trx.company_id OR company_id IS NULL)
      AND account_code IN ('1140', '1141', '114')
    ORDER BY CASE WHEN account_code = '1140' THEN 0 WHEN account_code = '1141' THEN 1 ELSE 2 END,
             CASE WHEN company_id = v_trx.company_id THEN 0 ELSE 1 END
    LIMIT 1;

    -- [4K] حساب إيراد الشحن (412 مبيعات خدمات ← 421 ← 411)
    IF v_shipping > 0 THEN
        SELECT id INTO v_account_shipping FROM chart_of_accounts
        WHERE company_id = v_trx.company_id
          AND account_code IN ('412', '4120', '421', '411')
          AND COALESCE(is_group, false) = false
        ORDER BY CASE account_code WHEN '412' THEN 0 WHEN '4120' THEN 1 WHEN '421' THEN 2 ELSE 3 END LIMIT 1;
        IF v_account_shipping IS NULL THEN v_account_shipping := v_account_rev; END IF;
    END IF;

    IF v_account_ar IS NULL OR v_account_rev IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error',
            'حسابات المبيعات غير مكتملة — تحقق من الذمم المدينة (1130/113) وحساب الإيرادات (411/4100)');
    END IF;

    -- [P1] حارس: ضريبة موجبة بلا حساب ضريبة ⇒ قيد غير متوازن. امنعها بوضوح.
    IF v_tax_amount > 0 AND v_account_tax IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error',
            'حساب ضريبة المخرجات (2130/2141/2150) غير موجود رغم وجود ضريبة — أضِفه قبل الترحيل');
    END IF;

    v_cogs_recorded := (v_cost_amount > 0 AND v_account_cogs IS NOT NULL AND v_account_inv IS NOT NULL);

    -- 4. تحديث الفاتورة بالمبالغ الفعلية + الحالة
    UPDATE sales_transactions
    SET stage = 'posted',
        is_posted = true,
        posted_at = NOW(),
        posted_by = v_user_id,
        subtotal = v_delivered_subtotal,
        discount_amount = v_delivered_discount,
        tax_amount = v_tax_amount,
        total_amount = v_total + v_shipping,
        updated_at = NOW()
    WHERE id = p_invoice_id;

    IF v_has_delivered THEN
        -- [P1] الخصم على مستوى البند يحترم discount_amount حين discount_percent=0
        UPDATE sales_transaction_items
        SET quantity = delivered_qty,
            subtotal = delivered_qty * unit_price,
            discount_amount = CASE WHEN COALESCE(discount_percent, 0) > 0
                                   THEN (delivered_qty * unit_price) * (discount_percent / 100)
                                   ELSE COALESCE(discount_amount, 0) * (delivered_qty / NULLIF(quantity, 0))
                              END,
            tax_amount = ((delivered_qty * unit_price)
                          - CASE WHEN COALESCE(discount_percent, 0) > 0
                                 THEN (delivered_qty * unit_price) * (discount_percent / 100)
                                 ELSE COALESCE(discount_amount, 0) * (delivered_qty / NULLIF(quantity, 0))
                            END
                         ) * (COALESCE(tax_rate, 0) / 100),
            total = ((delivered_qty * unit_price)
                     - CASE WHEN COALESCE(discount_percent, 0) > 0
                            THEN (delivered_qty * unit_price) * (discount_percent / 100)
                            ELSE COALESCE(discount_amount, 0) * (delivered_qty / NULLIF(quantity, 0))
                       END
                    ) * (1 + COALESCE(tax_rate, 0) / 100)
        WHERE transaction_id = p_invoice_id
          AND COALESCE(delivered_qty, 0) > 0;
    END IF;

    -- 5. رقم القيد
    v_entry_no := 'JE-S-' || to_char(NOW(), 'YYMMDD') || '-' ||
                  LPAD(nextval('journal_entry_number_seq')::text, 4, '0');

    -- 6. توازن الرأس [P1]
    v_total_debit  := v_total + v_shipping + CASE WHEN v_cogs_recorded THEN v_cost_amount ELSE 0 END;
    v_total_credit := v_net_amount
                      + CASE WHEN v_tax_amount > 0 THEN v_tax_amount ELSE 0 END
                      + v_shipping
                      + CASE WHEN v_cogs_recorded THEN v_cost_amount ELSE 0 END;

    -- 7. إنشاء القيد (مسودة) — total_debit/total_credit مُعبّأة ليعمل حارس التوازن [P1]
    INSERT INTO journal_entries (
        tenant_id, company_id, entry_number, entry_date,
        description,
        reference_type, reference_id, reference_number,
        currency, exchange_rate,
        total_debit, total_credit,
        status, is_posted, created_by
    ) VALUES (
        v_trx.tenant_id, v_trx.company_id, v_entry_no, CURRENT_DATE,
        'فاتورة مبيعات — ' || v_inv_label || CASE WHEN v_has_delivered THEN ' (بناءً على المسلّم فعلياً)' ELSE '' END,
        'sales_invoice', p_invoice_id, v_inv_label,
        COALESCE(v_trx.currency, 'SAR'), COALESCE(v_trx.exchange_rate, 1),
        v_total_debit, v_total_credit,
        'draft', false, v_user_id
    ) RETURNING id INTO v_je_id;

    -- 8. سطور القيد (debit_fc/credit_fc = debit/credit حسب العُرف الحالي) [P1]
    -- ① مدين: الذمم المدينة (الكامل شامل الضريبة)
    v_line_num := v_line_num + 1;
    INSERT INTO journal_entry_lines (
        tenant_id, entry_id, line_number, account_id, description,
        debit, credit, debit_fc, credit_fc, party_type, party_id
    ) VALUES (
        v_trx.tenant_id, v_je_id, v_line_num, v_account_ar,
        'ذمم مدينة — ' || COALESCE(v_trx.customer_name, ''),
        v_total + v_shipping, 0, v_total + v_shipping, 0, 'customer', v_trx.customer_id
    );

    -- ② دائن: إيرادات المبيعات (الصافي)
    v_line_num := v_line_num + 1;
    INSERT INTO journal_entry_lines (
        tenant_id, entry_id, line_number, account_id, description,
        debit, credit, debit_fc, credit_fc
    ) VALUES (
        v_trx.tenant_id, v_je_id, v_line_num, v_account_rev,
        'إيرادات مبيعات — ' || v_inv_label,
        0, v_net_amount, 0, v_net_amount
    );

    -- ③ دائن: ضريبة المخرجات
    IF v_tax_amount > 0 AND v_account_tax IS NOT NULL THEN
        v_line_num := v_line_num + 1;
        INSERT INTO journal_entry_lines (
            tenant_id, entry_id, line_number, account_id, description,
            debit, credit, debit_fc, credit_fc
        ) VALUES (
            v_trx.tenant_id, v_je_id, v_line_num, v_account_tax,
            'ضريبة مخرجات — ' || v_inv_label,
            0, v_tax_amount, 0, v_tax_amount
        );
    END IF;

    -- [4K] دائن: إيراد الشحن
    IF v_shipping > 0 AND v_account_shipping IS NOT NULL THEN
        v_line_num := v_line_num + 1;
        INSERT INTO journal_entry_lines (
            tenant_id, entry_id, line_number, account_id, description,
            debit, credit, debit_fc, credit_fc
        ) VALUES (
            v_trx.tenant_id, v_je_id, v_line_num, v_account_shipping,
            'إيراد شحن — ' || v_inv_label,
            0, v_shipping, 0, v_shipping
        );
    END IF;

    -- ④⑤ تكلفة البضاعة المباعة COGS
    IF v_cogs_recorded THEN
        v_line_num := v_line_num + 1;
        INSERT INTO journal_entry_lines (
            tenant_id, entry_id, line_number, account_id, description,
            debit, credit, debit_fc, credit_fc
        ) VALUES (
            v_trx.tenant_id, v_je_id, v_line_num, v_account_cogs,
            'تكلفة مبيعات — ' || v_inv_label,
            v_cost_amount, 0, v_cost_amount, 0
        );

        v_line_num := v_line_num + 1;
        INSERT INTO journal_entry_lines (
            tenant_id, entry_id, line_number, account_id, description,
            debit, credit, debit_fc, credit_fc
        ) VALUES (
            v_trx.tenant_id, v_je_id, v_line_num, v_account_inv,
            'إخراج مخزون — ' || v_inv_label,
            0, v_cost_amount, 0, v_cost_amount
        );
    END IF;

    -- 9. ترحيل القيد عبر post_journal_entry (يحدّث current_balance + يفرض التوازن) [P1]
    PERFORM post_journal_entry(v_je_id, v_user_id);

    UPDATE sales_transactions SET journal_entry_id = v_je_id WHERE id = p_invoice_id;

    RETURN jsonb_build_object(
        'success', true,
        'invoice_id', p_invoice_id,
        'invoice_number', v_inv_label,
        'journal_entry_id', v_je_id,
        'customer_account_id', v_account_ar,
        'based_on_delivered', v_has_delivered,
        'delivered_subtotal', v_delivered_subtotal,
        'delivered_discount', v_delivered_discount,
        'net_amount', v_net_amount,
        'tax_amount', v_tax_amount,
        'shipping_amount', v_shipping,
        'total_amount', v_total + v_shipping,
        'cost_amount', v_cost_amount,
        'cogs_recorded', v_cogs_recorded,
        'gross_profit', v_net_amount - v_cost_amount,
        'message', CASE
            WHEN v_has_delivered THEN 'تم ترحيل فاتورة المبيعات بنجاح — بناءً على الكميات المسلّمة فعلياً'
            ELSE 'تم ترحيل فاتورة المبيعات بنجاح — بناءً على الفاتورة الأصلية (لا توجد كميات مسلّمة)'
        END
    );

EXCEPTION WHEN OTHERS THEN
    -- المعاملة تتراجع بالكامل تلقائياً؛ نُعيد رسالة الخطأ
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'detail', SQLSTATE);
END;
$$;


--
-- Name: post_sales_return(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.post_sales_return(p_return_id uuid, p_warehouse_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_return       sales_returns%ROWTYPE;
    v_item         RECORD;
    v_je_id        UUID;
    v_user_id      UUID;
    v_net          NUMERIC(15,4) := 0;
    v_tax          NUMERIC(15,4) := 0;
    v_total        NUMERIC(15,4) := 0;
    v_cost_total   NUMERIC(15,4) := 0;
    v_item_cost    NUMERIC(15,4) := 0;
    v_src_txn      UUID;          -- [4J] المعاملة المصدر (للفواتير المباشرة وللمتجر)
    v_movement_count INT := 0;
    v_line_num     INT := 0;
    v_account_ar   UUID;
    v_account_rev  UUID;
    v_account_tax  UUID;
    v_account_inv  UUID;
    v_account_cogs UUID;
    v_movement_number VARCHAR(50);
    v_wh_id        UUID;
    v_cogs_recorded BOOLEAN := false;
    v_total_debit  NUMERIC(15,4) := 0;
    v_total_credit NUMERIC(15,4) := 0;
BEGIN
    v_user_id := auth.uid();

    SELECT * INTO v_return FROM sales_returns WHERE id = p_return_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'مرتجع المبيعات غير موجود');
    END IF;

    PERFORM assert_can_access_company(v_return.company_id);

    IF v_return.status = 'posted' THEN
        RETURN jsonb_build_object('success', false, 'error', 'المرتجع مُرحَّل مسبقاً');
    END IF;

    v_wh_id := COALESCE(p_warehouse_id, v_return.warehouse_id);

    -- [4J] حلّ المعاملة المصدر للتكلفة: invoice_id مباشرةً، أو عبر طلب المتجر (source_id → sales_invoice_id)
    IF v_return.invoice_id IS NOT NULL THEN
        v_src_txn := v_return.invoice_id;
    ELSIF v_return.source_type = 'ecommerce' AND v_return.source_id IS NOT NULL THEN
        SELECT sales_invoice_id INTO v_src_txn FROM ecommerce_orders WHERE id = v_return.source_id;
    END IF;

    -- 1. حركات مخزون (دخول) بالتكلفة الأصلية من الفاتورة، وتجميع تكلفة الإرجاع
    FOR v_item IN SELECT * FROM sales_return_items WHERE return_id = p_return_id
    LOOP
        v_movement_count := v_movement_count + 1;

        -- التكلفة من بند الفاتورة الأصلية (مطابقة بالمادة/المنتج)
        v_item_cost := 0;
        IF v_src_txn IS NOT NULL THEN
            SELECT sti.cost_price INTO v_item_cost
            FROM sales_transaction_items sti
            WHERE sti.transaction_id = v_src_txn
              AND ( (v_item.material_id IS NOT NULL AND sti.material_id = v_item.material_id)
                 OR (v_item.product_id  IS NOT NULL AND sti.product_id  = v_item.product_id) )
            ORDER BY sti.cost_price DESC NULLS LAST
            LIMIT 1;
            v_item_cost := COALESCE(v_item_cost, 0);
        END IF;
        v_cost_total := v_cost_total + v_item.quantity_returned * v_item_cost;

        v_movement_number := 'SR-' || COALESCE(v_return.return_number, '') || '-' || v_movement_count;

        INSERT INTO inventory_movements (
            tenant_id, company_id,
            movement_number, movement_date,
            movement_type,
            product_id, material_id, variant_id,
            to_warehouse_id,
            quantity, unit_cost, total_cost,
            reference_type, reference_id, reference_number,
            notes, created_by
        ) VALUES (
            v_return.tenant_id, v_return.company_id,
            v_movement_number, CURRENT_DATE,
            'return_in',
            v_item.product_id, v_item.material_id, v_item.variant_id,
            v_wh_id,
            v_item.quantity_returned, v_item_cost,
            v_item.quantity_returned * v_item_cost,   -- بالتكلفة لا بسعر البيع
            'sales_return', p_return_id, v_return.return_number,
            'مرتجع مبيعات', v_user_id
        );
    END LOOP;

    -- 2. الصافي/الضريبة/الإجمالي من بنود المرتجع
    SELECT
        COALESCE(SUM(COALESCE(sri.subtotal, sri.total - COALESCE(sri.tax_amount, 0),
                              sri.quantity_returned * COALESCE(sri.unit_price, 0))), 0),
        COALESCE(SUM(COALESCE(sri.tax_amount, 0)), 0)
    INTO v_net, v_tax
    FROM sales_return_items sri
    WHERE sri.return_id = p_return_id;
    v_total := v_net + v_tax;

    IF v_total <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'قيمة المرتجع صفر أو سالبة');
    END IF;

    -- 3. الحسابات (مطابِقة لأكواد الفاتورة)
    IF v_return.customer_id IS NOT NULL THEN
        SELECT receivable_account_id INTO v_account_ar
        FROM customers WHERE id = v_return.customer_id AND receivable_account_id IS NOT NULL;
        IF v_account_ar IS NULL THEN
            SELECT id INTO v_account_ar FROM chart_of_accounts
            WHERE is_party_account = true AND party_type = 'customer' AND party_id = v_return.customer_id
            LIMIT 1;
        END IF;
    END IF;
    IF v_account_ar IS NULL THEN
        SELECT id INTO v_account_ar FROM chart_of_accounts
        WHERE tenant_id = v_return.tenant_id AND (company_id = v_return.company_id OR company_id IS NULL)
          AND account_code IN ('1131', '1130', '113')
        ORDER BY CASE account_code WHEN '1131' THEN 0 WHEN '1130' THEN 1 ELSE 2 END,
                 CASE WHEN company_id = v_return.company_id THEN 0 ELSE 1 END LIMIT 1;
    END IF;

    SELECT id INTO v_account_rev FROM chart_of_accounts
    WHERE tenant_id = v_return.tenant_id AND (company_id = v_return.company_id OR company_id IS NULL)
      AND account_code IN ('4110', '4100', '411', '41')
    ORDER BY CASE account_code WHEN '4110' THEN 0 WHEN '4100' THEN 1 WHEN '411' THEN 2 ELSE 3 END,
             CASE WHEN company_id = v_return.company_id THEN 0 ELSE 1 END LIMIT 1;

    IF v_tax > 0 THEN
        SELECT id INTO v_account_tax FROM chart_of_accounts
        WHERE tenant_id = v_return.tenant_id AND (company_id = v_return.company_id OR company_id IS NULL)
          AND account_code IN ('2130', '2141', '2150')
        ORDER BY CASE account_code WHEN '2130' THEN 0 WHEN '2141' THEN 1 ELSE 2 END,
                 CASE WHEN company_id = v_return.company_id THEN 0 ELSE 1 END LIMIT 1;
    END IF;

    SELECT id INTO v_account_inv FROM chart_of_accounts
    WHERE tenant_id = v_return.tenant_id AND (company_id = v_return.company_id OR company_id IS NULL)
      AND account_code IN ('1140', '1141', '114')
    ORDER BY CASE account_code WHEN '1140' THEN 0 WHEN '1141' THEN 1 ELSE 2 END,
             CASE WHEN company_id = v_return.company_id THEN 0 ELSE 1 END LIMIT 1;

    SELECT id INTO v_account_cogs FROM chart_of_accounts
    WHERE tenant_id = v_return.tenant_id AND (company_id = v_return.company_id OR company_id IS NULL)
      AND account_code IN ('5100', '5110', '511', '51')
    ORDER BY CASE account_code WHEN '5100' THEN 0 WHEN '5110' THEN 1 WHEN '511' THEN 2 ELSE 3 END,
             CASE WHEN company_id = v_return.company_id THEN 0 ELSE 1 END LIMIT 1;

    IF v_account_ar IS NULL OR v_account_rev IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error',
            'حسابات المرتجع غير مكتملة — تحقق من الذمم المدينة والإيرادات');
    END IF;
    IF v_tax > 0 AND v_account_tax IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error',
            'حساب ضريبة المخرجات غير موجود رغم وجود ضريبة في المرتجع');
    END IF;

    v_cogs_recorded := (v_cost_total > 0 AND v_account_inv IS NOT NULL AND v_account_cogs IS NOT NULL);

    -- 4. تحديث حالة المرتجع
    UPDATE sales_returns SET status = 'posted', updated_at = NOW() WHERE id = p_return_id;

    -- 5. القيد (مسودة) — عكس البيع: مدين إيراد/ضريبة، دائن ذمم؛ ومدين مخزون/دائن COGS
    v_total_debit  := v_net + v_tax + CASE WHEN v_cogs_recorded THEN v_cost_total ELSE 0 END;
    v_total_credit := v_total + CASE WHEN v_cogs_recorded THEN v_cost_total ELSE 0 END;

    INSERT INTO journal_entries (
        tenant_id, company_id, branch_id,
        entry_date, entry_type, description,
        reference_type, reference_id, reference_number,
        total_debit, total_credit,
        status, is_posted, created_by
    ) VALUES (
        v_return.tenant_id, v_return.company_id, v_return.branch_id,
        CURRENT_DATE, 'auto',
        'مرتجع مبيعات — ' || COALESCE(v_return.return_number, ''),
        'sales_return', p_return_id, v_return.return_number,
        v_total_debit, v_total_credit,
        'draft', false, v_user_id
    ) RETURNING id INTO v_je_id;

    -- ① مدين: تخفيض الإيراد (الصافي)
    v_line_num := v_line_num + 1;
    INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, description, debit, credit, debit_fc, credit_fc)
    VALUES (v_return.tenant_id, v_je_id, v_line_num, v_account_rev, 'تخفيض إيرادات — مرتجع', v_net, 0, v_net, 0);

    -- ② مدين: تخفيض ضريبة المخرجات (إن وجدت)
    IF v_tax > 0 AND v_account_tax IS NOT NULL THEN
        v_line_num := v_line_num + 1;
        INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, description, debit, credit, debit_fc, credit_fc)
        VALUES (v_return.tenant_id, v_je_id, v_line_num, v_account_tax, 'تخفيض ضريبة — مرتجع', v_tax, 0, v_tax, 0);
    END IF;

    -- ③ دائن: تخفيض الذمم المدينة (الإجمالي)
    v_line_num := v_line_num + 1;
    INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, description, debit, credit, debit_fc, credit_fc, party_type, party_id)
    VALUES (v_return.tenant_id, v_je_id, v_line_num, v_account_ar, 'تخفيض ذمم مدينة — مرتجع', 0, v_total, 0, v_total, 'customer', v_return.customer_id);

    -- ④⑤ عكس تكلفة البضاعة المباعة (بالتكلفة): مدين مخزون / دائن COGS
    IF v_cogs_recorded THEN
        v_line_num := v_line_num + 1;
        INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, description, debit, credit, debit_fc, credit_fc)
        VALUES (v_return.tenant_id, v_je_id, v_line_num, v_account_inv, 'إرجاع مخزون — مرتجع', v_cost_total, 0, v_cost_total, 0);

        v_line_num := v_line_num + 1;
        INSERT INTO journal_entry_lines (tenant_id, entry_id, line_number, account_id, description, debit, credit, debit_fc, credit_fc)
        VALUES (v_return.tenant_id, v_je_id, v_line_num, v_account_cogs, 'عكس تكلفة مبيعات — مرتجع', 0, v_cost_total, 0, v_cost_total);
    END IF;

    -- 6. الترحيل عبر post_journal_entry (تحديث الأرصدة + فحص التوازن)
    PERFORM post_journal_entry(v_je_id, v_user_id);

    RETURN jsonb_build_object(
        'success', true,
        'return_id', p_return_id,
        'movements_created', v_movement_count,
        'net_amount', v_net,
        'tax_amount', v_tax,
        'total_amount', v_total,
        'cost_reversed', v_cost_total,
        'cogs_reversed', v_cogs_recorded,
        'journal_entry_id', v_je_id,
        'message', 'تم ترحيل مرتجع المبيعات بنجاح'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'detail', SQLSTATE);
END;
$$;


--
-- Name: post_supplier_ledger(uuid, uuid, text, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.post_supplier_ledger(p_store_id uuid, p_supplier_link_id uuid, p_entry_type text, p_amount numeric, p_currency text DEFAULT 'UAH'::text, p_order_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_balance numeric;
BEGIN
  INSERT INTO marketplace_supplier_ledger(store_id, supplier_link_id, order_id, entry_type, amount, currency, note, created_by)
  VALUES (p_store_id, p_supplier_link_id, p_order_id, p_entry_type, p_amount, p_currency, p_note, auth.uid());

  SELECT COALESCE(SUM(amount), 0) INTO v_balance
  FROM marketplace_supplier_ledger
  WHERE supplier_link_id = p_supplier_link_id AND currency = p_currency;

  RETURN v_balance;
END $$;


--
-- Name: prepare_pending_action_draft(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.prepare_pending_action_draft(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_company uuid; v_tenant uuid; v_atype text; v_adata jsonb; v_user uuid := auth.uid();
    v_party uuid; v_party_name text; v_amount numeric; v_fund uuid; v_num text; v_doc uuid; v_inv uuid;
BEGIN
    SELECT company_id, tenant_id, action_type, action_data
      INTO v_company, v_tenant, v_atype, v_adata
      FROM pending_actions WHERE id=p_id AND status='pending';
    IF v_company IS NULL THEN RETURN jsonb_build_object('ok',false,'message','المسودة غير موجودة'); END IF;
    PERFORM assert_can_access_company(v_company);
    v_amount := NULLIF(v_adata->>'amount','')::numeric;
    v_inv := NULLIF(COALESCE(v_adata->>'sales_transaction_id', v_adata->>'invoice_id'),'')::uuid;
    SELECT fund_account_id INTO v_fund FROM get_user_accessible_funds(v_user) WHERE is_primary LIMIT 1;
    IF v_fund IS NULL THEN SELECT fund_account_id INTO v_fund FROM get_user_accessible_funds(v_user) LIMIT 1; END IF;

    IF v_atype = 'payment_received' THEN
        v_party_name := COALESCE(v_adata->>'from_name', v_adata->>'from_customer', v_adata->>'customer_name');
        v_party := NULLIF(v_adata->>'customer_id','')::uuid;
        IF v_party IS NULL AND v_party_name IS NOT NULL THEN
            SELECT id INTO v_party FROM customers WHERE company_id=v_company
              AND (name_ar ILIKE '%'||v_party_name||'%' OR name_en ILIKE '%'||v_party_name||'%' OR company_name ILIKE '%'||v_party_name||'%') LIMIT 1;
        END IF;
        v_num := 'RCV-TG-'||to_char(now(),'YYMMDDHH24MISS');
        INSERT INTO payment_receipts(company_id, tenant_id, receipt_number, receipt_date, customer_id, customer_name,
               amount, payment_method, status, treasury_account_id, sales_transaction_id, created_by, notes)
          VALUES(v_company, v_tenant, v_num, CURRENT_DATE, v_party, v_party_name,
               COALESCE(v_amount,0), 'cash', 'draft', v_fund, v_inv, v_user, 'مسودة من تلغرام — للمراجعة')
          RETURNING id INTO v_doc;
        UPDATE pending_actions SET status='confirmed', confirmed_at=now(), confirmed_via='web', confirmed_by=v_user WHERE id=p_id;
        RETURN jsonb_build_object('ok',true,'item_type','payment_receipt','item_id',v_doc);

    ELSIF v_atype = 'payment_made' THEN
        v_party_name := COALESCE(v_adata->>'to_name', v_adata->>'supplier_name');
        v_party := NULLIF(v_adata->>'supplier_id','')::uuid;
        IF v_party IS NULL AND v_party_name IS NOT NULL THEN
            SELECT id INTO v_party FROM suppliers WHERE company_id=v_company
              AND (name_ar ILIKE '%'||v_party_name||'%' OR name_en ILIKE '%'||v_party_name||'%' OR company_name ILIKE '%'||v_party_name||'%') LIMIT 1;
        END IF;
        v_num := 'PAY-TG-'||to_char(now(),'YYMMDDHH24MISS');
        INSERT INTO payment_vouchers(company_id, tenant_id, voucher_number, voucher_date, supplier_id, supplier_name,
               amount, payment_method, status, treasury_account_id, created_by, notes)
          VALUES(v_company, v_tenant, v_num, CURRENT_DATE, v_party, v_party_name,
               COALESCE(v_amount,0), 'cash', 'draft', v_fund, v_user, 'مسودة من تلغرام — للمراجعة')
          RETURNING id INTO v_doc;
        UPDATE pending_actions SET status='confirmed', confirmed_at=now(), confirmed_via='web', confirmed_by=v_user WHERE id=p_id;
        RETURN jsonb_build_object('ok',true,'item_type','payment_voucher','item_id',v_doc);

    ELSE
        RETURN jsonb_build_object('ok',false,'message','هذا النوع لا يُفتح كمستند — استخدم زر التأكيد');
    END IF;
END;
$$;


--
-- Name: prevent_base_currency_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.prevent_base_currency_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    has_entries BOOLEAN;
BEGIN
    -- فقط عند تغيير العملة الأساسية
    IF OLD.default_currency IS DISTINCT FROM NEW.default_currency THEN
        -- هل يوجد قيود محاسبية لهذه الشركة؟
        SELECT EXISTS (
            SELECT 1 FROM journal_entries 
            WHERE company_id = NEW.id
            LIMIT 1
        ) INTO has_entries;
        
        IF has_entries THEN
            RAISE EXCEPTION 'Cannot change base currency after journal entries exist. Current: %, Attempted: %',
                OLD.default_currency, NEW.default_currency;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: prevent_delete_if_referenced(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.prevent_delete_if_referenced() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- هذه الدالة ستُستخدم للجداول التي لا يجب حذف سجلاتها
    -- إذا كانت مرتبطة بسجلات أخرى
    RAISE EXCEPTION 'غير مسموح: لا يمكن حذف هذا السجل لارتباطه ببيانات أخرى / Not allowed: Cannot delete this record as it is referenced by other data';
END;
$$;


--
-- Name: prevent_delivered_invoice_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.prevent_delivered_invoice_deletion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_movement_count integer;
BEGIN
    IF OLD.stage IN ('in_delivery', 'delivered', 'posted', 'completed', 'partial_delivered', 'invoiced') THEN
        RAISE EXCEPTION 'Cannot delete sales invoice (%) in stage "%". Reverse delivery first.',
            COALESCE(OLD.invoice_no, OLD.draft_no, OLD.id::text), OLD.stage;
    END IF;

    SELECT COUNT(*) INTO v_movement_count
    FROM inventory_movements
    WHERE reference_id = OLD.id
      AND movement_type IN ('sale', 'issue', 'delivery');

    IF v_movement_count > 0 THEN
        RAISE EXCEPTION 'Cannot delete sales invoice (%) — % inventory movement(s) exist. Reverse delivery first.',
            COALESCE(OLD.invoice_no, OLD.draft_no, OLD.id::text), v_movement_count;
    END IF;

    IF OLD.journal_entry_id IS NOT NULL OR OLD.cogs_journal_entry_id IS NOT NULL THEN
        RAISE EXCEPTION 'Cannot delete sales invoice (%) — journal entries exist. Unpost first.',
            COALESCE(OLD.invoice_no, OLD.draft_no, OLD.id::text);
    END IF;

    RETURN OLD;
END;
$$;


--
-- Name: prevent_removing_used_currency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.prevent_removing_used_currency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_removed_currency TEXT;
    has_entries BOOLEAN;
BEGIN
    IF OLD.supported_currencies IS NOT DISTINCT FROM NEW.supported_currencies THEN
        RETURN NEW;
    END IF;

    FOREACH v_removed_currency IN ARRAY COALESCE(OLD.supported_currencies, ARRAY[]::TEXT[])
    LOOP
        IF NOT (v_removed_currency = ANY(COALESCE(NEW.supported_currencies, ARRAY[]::TEXT[]))) THEN
            SELECT EXISTS (
                SELECT 1 FROM journal_entries
                WHERE company_id = NEW.company_id AND currency = v_removed_currency
                LIMIT 1
            ) INTO has_entries;

            IF has_entries THEN
                RAISE EXCEPTION '❌ لا يمكن حذف العملة % — يوجد قيود محاسبية بها', v_removed_currency;
            END IF;
        END IF;
    END LOOP;

    RETURN NEW;
END;
$$;


--
-- Name: prevent_settings_base_currency_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.prevent_settings_base_currency_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    has_entries BOOLEAN;
BEGIN
    IF OLD.base_currency IS DISTINCT FROM NEW.base_currency THEN
        SELECT EXISTS (
            SELECT 1 FROM journal_entries 
            WHERE company_id = NEW.company_id
            LIMIT 1
        ) INTO has_entries;
        
        IF has_entries THEN
            RAISE EXCEPTION 'Cannot change base currency in accounting settings after journal entries exist. Current: %, Attempted: %',
                OLD.base_currency, NEW.base_currency;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: process_due_recurring_entries(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.process_due_recurring_entries(p_as_of_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_entry RECORD;
    v_history_id UUID;
    v_processed_count INTEGER := 0;
    v_results JSONB := '[]'::JSONB;
BEGIN
    -- البحث عن القيود المستحقة
    FOR v_entry IN
        SELECT *
        FROM recurring_entries
        WHERE is_active = true
          AND status = 'active'
          AND next_run_date <= p_as_of_date
          AND (end_date IS NULL OR end_date >= p_as_of_date)
          AND (max_executions IS NULL OR times_executed < max_executions)
    LOOP
        -- إنشاء سجل في التاريخ
        INSERT INTO recurring_entry_history (
            tenant_id, recurring_entry_id, scheduled_date, amount,
            approval_status, status
        ) VALUES (
            v_entry.tenant_id, v_entry.id, v_entry.next_run_date, v_entry.amount,
            CASE WHEN v_entry.requires_approval THEN 'pending' ELSE 'auto_approved' END,
            CASE WHEN v_entry.requires_approval THEN 'pending' ELSE 'pending' END
        ) RETURNING id INTO v_history_id;
        
        -- تحديث تاريخ التنفيذ التالي
        UPDATE recurring_entries
        SET 
            next_run_date = calculate_next_run_date(
                next_run_date, frequency, interval_value,
                day_of_month, day_of_week, month_of_year
            ),
            last_run_date = p_as_of_date,
            times_executed = times_executed + 1,
            updated_at = NOW()
        WHERE id = v_entry.id;
        
        -- إذا لا يحتاج موافقة، نفذ مباشرة
        IF NOT v_entry.requires_approval THEN
            PERFORM execute_recurring_entry(v_history_id, NULL);
        END IF;
        
        v_processed_count := v_processed_count + 1;
        v_results := v_results || jsonb_build_object(
            'entry_id', v_entry.id,
            'name', v_entry.name_ar,
            'history_id', v_history_id,
            'requires_approval', v_entry.requires_approval
        );
    END LOOP;
    
    RETURN jsonb_build_object(
        'success', true,
        'processed_count', v_processed_count,
        'entries', v_results
    );
END;
$$;


--
-- Name: process_payment_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.process_payment_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'confirmed' THEN
        UPDATE customers
        SET balance = balance - NEW.amount,
            total_payments = total_payments + NEW.amount
        WHERE id = NEW.customer_id;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: process_shipment_api_response(uuid, character varying, character varying, date, numeric, text, jsonb, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.process_shipment_api_response(p_shipment_doc_id uuid, p_tracking_number character varying, p_carrier_ref character varying, p_estimated_delivery date DEFAULT NULL::date, p_shipping_cost numeric DEFAULT NULL::numeric, p_label_url text DEFAULT NULL::text, p_api_response jsonb DEFAULT NULL::jsonb, p_success boolean DEFAULT true, p_error_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_doc RECORD;
BEGIN
    IF NOT p_success THEN
        UPDATE shipment_documents
        SET status = 'failed',
            status_description = p_error_message,
            api_response = p_api_response,
            updated_at = NOW()
        WHERE id = p_shipment_doc_id;
        
        RETURN jsonb_build_object('success', false, 'error', p_error_message);
    END IF;
    
    -- Update shipment document with API response
    UPDATE shipment_documents
    SET tracking_number = p_tracking_number,
        carrier_ref = p_carrier_ref,
        status = 'created',
        status_description = 'البوليصة تم إنشاؤها بنجاح',
        estimated_delivery_date = p_estimated_delivery,
        shipping_cost = COALESCE(p_shipping_cost, shipping_cost),
        label_url = p_label_url,
        barcode = p_tracking_number,
        api_response = p_api_response,
        status_history = status_history || jsonb_build_array(
            jsonb_build_object(
                'status', 'created',
                'date', to_char(NOW(), 'YYYY-MM-DD HH24:MI:SS'),
                'description', 'البوليصة تم إنشاؤها — TTN: ' || p_tracking_number
            )
        ),
        updated_at = NOW()
    WHERE id = p_shipment_doc_id
    RETURNING * INTO v_doc;
    
    -- Update the source trade document with tracking number
    IF v_doc.source_table = 'sales_orders' THEN
        UPDATE sales_orders 
        SET tracking_number = p_tracking_number,
            shipping_cost = COALESCE(p_shipping_cost, shipping_cost)
        WHERE id = v_doc.source_id;
    ELSIF v_doc.source_table = 'sales_deliveries' THEN
        UPDATE sales_deliveries
        SET tracking_number = p_tracking_number,
            shipping_cost = COALESCE(p_shipping_cost, shipping_cost)
        WHERE id = v_doc.source_id;
    ELSIF v_doc.source_table = 'transit_reservations' THEN
        UPDATE transit_reservations
        SET tracking_number = p_tracking_number,
            shipping_cost = COALESCE(p_shipping_cost, shipping_cost)
        WHERE id = v_doc.source_id;
    ELSIF v_doc.source_table = 'quotations' THEN
        UPDATE quotations
        SET tracking_number = p_tracking_number,
            shipping_cost = COALESCE(p_shipping_cost, shipping_cost)
        WHERE id = v_doc.source_id;
    ELSIF v_doc.source_table = 'sales_invoices' THEN
        UPDATE sales_invoices
        SET tracking_number = p_tracking_number,
            shipping_cost = COALESCE(p_shipping_cost, shipping_cost)
        WHERE id = v_doc.source_id;
    END IF;
    
    RETURN jsonb_build_object(
        'success', true,
        'tracking_number', p_tracking_number,
        'carrier_ref', p_carrier_ref,
        'shipment_document_id', p_shipment_doc_id,
        'label_url', p_label_url
    );
END;
$$;


--
-- Name: FUNCTION process_shipment_api_response(p_shipment_doc_id uuid, p_tracking_number character varying, p_carrier_ref character varying, p_estimated_delivery date, p_shipping_cost numeric, p_label_url text, p_api_response jsonb, p_success boolean, p_error_message text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.process_shipment_api_response(p_shipment_doc_id uuid, p_tracking_number character varying, p_carrier_ref character varying, p_estimated_delivery date, p_shipping_cost numeric, p_label_url text, p_api_response jsonb, p_success boolean, p_error_message text) IS 'معالجة رد API شركة الشحن — يُستدعى من n8n بعد تلقي رقم البوليصة (TTN)';


--
-- Name: propagate_templates_to_all_tenants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.propagate_templates_to_all_tenants() RETURNS TABLE(tenant_id uuid, tenant_name character varying, templates_created integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    rec RECORD;
    v_count INT;
BEGIN
    -- إعداد القوالب لكل تينانت موجود
    FOR rec IN SELECT id, name FROM tenants LOOP
        BEGIN
            PERFORM setup_chart_templates_for_tenant(rec.id);
            SELECT COUNT(*) INTO v_count FROM chart_templates WHERE tenant_id = rec.id;
            
            tenant_id := rec.id;
            tenant_name := rec.name;
            templates_created := v_count;
            RETURN NEXT;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE '⚠️ خطأ في إعداد القوالب للتينانت %: %', rec.id, SQLERRM;
            tenant_id := rec.id;
            tenant_name := rec.name;
            templates_created := 0;
            RETURN NEXT;
        END;
    END LOOP;
END;
$$;


--
-- Name: protect_companies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.protect_companies() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_user_id UUID := auth.uid();
    v_is_platform_admin BOOLEAN;
BEGIN
    IF v_current_user_id IS NULL THEN
        RETURN NEW;
    END IF;

    v_is_platform_admin := is_platform_admin(v_current_user_id);

    -- ════════ حماية tenant_id ════════
    IF OLD.tenant_id IS DISTINCT FROM NEW.tenant_id THEN
        IF NOT v_is_platform_admin THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكن نقل شركة من تينانت لآخر إلا من مدير المنصة / Not allowed: Only platform admin can move company between tenants';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: protect_company_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.protect_company_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- منع تغيير tenant_id
    IF TG_OP = 'UPDATE' THEN
        IF OLD.tenant_id IS DISTINCT FROM NEW.tenant_id THEN
            -- فقط Super Admin
            IF NOT COALESCE(
                (SELECT is_super_admin FROM user_profiles WHERE id = auth.uid()), 
                false
            ) THEN
                RAISE EXCEPTION 'غير مسموح بنقل الشركة لمستأجر آخر';
            END IF;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: protect_partners(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.protect_partners() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_user_id UUID := auth.uid();
    v_is_platform_admin BOOLEAN;
    v_current_user_email TEXT;
BEGIN
    IF v_current_user_id IS NULL THEN
        RETURN NEW;
    END IF;

    v_is_platform_admin := is_platform_admin(v_current_user_id);
    
    -- Platform Admin يمكنه كل شيء
    IF v_is_platform_admin THEN
        RETURN NEW;
    END IF;

    -- الحصول على بريد المستخدم الحالي
    SELECT email INTO v_current_user_email FROM public.user_profiles WHERE id = v_current_user_id;

    -- عند الإضافة: فقط Platform Admin
    IF TG_OP = 'INSERT' THEN
        RAISE EXCEPTION 'غير مسموح: فقط مدير المنصة يمكنه إنشاء وكلاء / Not allowed: Only platform admin can create partners';
    END IF;

    -- عند التعديل: الوكيل يعدّل بياناته الشخصية فقط
    IF TG_OP = 'UPDATE' THEN
        -- التحقق من أن المستخدم هو الوكيل نفسه
        IF LOWER(OLD.email) != LOWER(v_current_user_email) THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكنك تعديل بيانات وكيل آخر / Not allowed: You cannot modify another partner''s data';
        END IF;
        
        -- الحقول المسموح للوكيل بتعديلها
        -- الحقول غير المسموحة: email, partner_type, commission_rate, is_active
        IF OLD.email IS DISTINCT FROM NEW.email THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكنك تغيير البريد الإلكتروني / Not allowed: You cannot change email';
        END IF;
        IF OLD.partner_type IS DISTINCT FROM NEW.partner_type THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكنك تغيير نوع الوكالة / Not allowed: You cannot change partner type';
        END IF;
        IF OLD.commission_rate IS DISTINCT FROM NEW.commission_rate THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكنك تغيير نسبة العمولة / Not allowed: You cannot change commission rate';
        END IF;
        IF OLD.is_active IS DISTINCT FROM NEW.is_active THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكنك تغيير حالة التفعيل / Not allowed: You cannot change activation status';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: protect_role_assignments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.protect_role_assignments() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_is_super_admin BOOLEAN := false;
    v_is_tenant_admin BOOLEAN := false;
    v_current_user_id UUID;
BEGIN
    -- الحصول على المستخدم الحالي
    v_current_user_id := auth.uid();
    
    -- ═══════════════════════════════════════════════════════════
    -- السماح إذا كنا في SECURITY DEFINER context
    -- أو إذا لم يكن هناك مستخدم نشط (admin operations)
    -- ═══════════════════════════════════════════════════════════
    IF v_current_user_id IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;
    
    -- التحقق إذا المستخدم موجود في user_profiles
    SELECT 
        COALESCE(is_super_admin, false),
        COALESCE(is_tenant_admin, false)
    INTO v_is_super_admin, v_is_tenant_admin
    FROM user_profiles 
    WHERE id = v_current_user_id;
    
    -- ═══════════════════════════════════════════════════════════
    -- إذا لم يوجد سجل في user_profiles = مستخدم جديد = السماح
    -- (هذا يحدث أثناء عملية register_new_subscriber)
    -- ═══════════════════════════════════════════════════════════
    IF NOT FOUND THEN
        RETURN COALESCE(NEW, OLD);
    END IF;
    
    -- ═══════════════════════════════════════════════════════════
    -- السماح للمستخدم بإنشاء role assignment لنفسه للمرة الأولى
    -- (عند التسجيل الجديد، لا يوجد له أي أدوار بعد)
    -- ═══════════════════════════════════════════════════════════
    IF TG_OP = 'INSERT' AND NEW.user_id = v_current_user_id THEN
        -- هل لديه أي دور حالي؟
        IF NOT EXISTS (
            SELECT 1 FROM user_role_assignments 
            WHERE user_id = v_current_user_id
        ) THEN
            -- لا يوجد له دور = تسجيل جديد = السماح
            RETURN NEW;
        END IF;
    END IF;
    
    -- فقط Super Admin أو Tenant Admin يمكنهم تعديل الأدوار
    IF NOT (v_is_super_admin OR v_is_tenant_admin) THEN
        RAISE EXCEPTION 'غير مسموح بتعديل صلاحيات المستخدمين';
    END IF;
    
    -- منع المستخدم من تعديل صلاحياته الخاصة (إلا Super Admin)
    IF TG_OP = 'UPDATE' AND NEW.user_id = v_current_user_id AND NOT v_is_super_admin THEN
        RAISE EXCEPTION 'لا يمكنك تعديل صلاحياتك الخاصة';
    END IF;
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: protect_sensitive_user_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.protect_sensitive_user_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- 🛑 CRITICAL: Bypass during registration process
    IF current_setting('app.is_registering', true) = 'true' THEN
        RETURN NEW;
    END IF;

    IF NOT COALESCE(
        (SELECT is_super_admin FROM user_profiles WHERE id = auth.uid()),
        false
    ) THEN
        IF OLD.is_super_admin IS DISTINCT FROM NEW.is_super_admin THEN
            RAISE EXCEPTION 'غير مسموح بتغيير حقل is_super_admin';
        END IF;
        IF OLD.tenant_id IS NOT NULL AND OLD.tenant_id IS DISTINCT FROM NEW.tenant_id THEN
            RAISE EXCEPTION 'غير مسموح بتغيير حقل tenant_id';
        END IF;
        IF OLD.company_id IS NOT NULL AND OLD.company_id IS DISTINCT FROM NEW.company_id THEN
            RAISE EXCEPTION 'غير مسموح بتغيير حقل company_id';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: protect_super_admins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.protect_super_admins() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_user_id UUID := auth.uid();
    v_is_platform_owner BOOLEAN;
    v_super_admin_count INT;
BEGIN
    IF v_current_user_id IS NULL THEN
        -- السماح للعمليات النظامية بدون مستخدم (مثل الـ migrations)
        RETURN COALESCE(NEW, OLD);
    END IF;

    v_is_platform_owner := is_platform_owner(v_current_user_id);
    
    -- فقط Platform Owner يمكنه تعديل جدول super_admins
    IF NOT v_is_platform_owner THEN
        RAISE EXCEPTION 'غير مسموح: فقط مالك المنصة يمكنه إدارة مديري المنصة / Not allowed: Only platform owner can manage super admins';
    END IF;

    -- عند الحذف: منع حذف آخر Platform Owner
    IF TG_OP = 'DELETE' THEN
        SELECT COUNT(*) INTO v_super_admin_count
        FROM public.super_admins
        WHERE is_active = true;
        
        IF v_super_admin_count <= 1 THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكن حذف آخر مالك للمنصة / Not allowed: Cannot delete the last platform owner';
        END IF;
        
        RETURN OLD;
    END IF;

    -- عند إلغاء التفعيل: منع إلغاء تفعيل آخر Platform Owner
    IF TG_OP = 'UPDATE' AND OLD.is_active = true AND NEW.is_active = false THEN
        SELECT COUNT(*) INTO v_super_admin_count
        FROM public.super_admins
        WHERE is_active = true AND id != OLD.id;
        
        IF v_super_admin_count < 1 THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكن إلغاء تفعيل آخر مالك للمنصة / Not allowed: Cannot deactivate the last platform owner';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: protect_system_accounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.protect_system_accounts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- منع الحذف الفعلي
    IF TG_OP = 'DELETE' THEN
        IF OLD.is_system = true THEN
            RAISE EXCEPTION 'لا يمكن حذف حساب نظام محمي: % (%)', OLD.name_ar, OLD.account_code
                USING HINT = 'حسابات النظام محمية ولا يمكن حذفها';
        END IF;
        RETURN OLD;
    END IF;

    -- منع تعطيل حسابات النظام (soft delete)
    IF TG_OP = 'UPDATE' THEN
        IF OLD.is_system = true THEN
            -- منع تعطيل الحساب
            IF NEW.is_active = false AND OLD.is_active = true THEN
                RAISE EXCEPTION 'لا يمكن تعطيل حساب نظام محمي: % (%)', OLD.name_ar, OLD.account_code
                    USING HINT = 'حسابات النظام محمية ولا يمكن تعطيلها';
            END IF;
            -- منع إزالة علامة النظام
            IF NEW.is_system = false THEN
                RAISE EXCEPTION 'لا يمكن إزالة علامة النظام عن الحساب: % (%)', OLD.name_ar, OLD.account_code;
            END IF;
            -- منع تغيير is_summary_account
            IF OLD.is_summary_account = true AND NEW.is_summary_account = false THEN
                RAISE EXCEPTION 'لا يمكن إزالة علامة المجاميع عن الحساب: % (%)', OLD.name_ar, OLD.account_code;
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: protect_tenant_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.protect_tenant_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF NOT COALESCE(
        (SELECT is_super_admin FROM user_profiles WHERE id = auth.uid()),
        false
    ) THEN
        -- Only block if product_id is being CHANGED (not initial set)
        IF TG_OP = 'UPDATE' 
           AND OLD.product_id IS NOT NULL 
           AND OLD.product_id IS DISTINCT FROM NEW.product_id THEN
            RAISE EXCEPTION 'غير مسموح بتغيير المنصة للمستأجر';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: protect_tenants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.protect_tenants() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_user_id UUID := auth.uid();
    v_is_platform_owner BOOLEAN;
    v_is_platform_admin BOOLEAN;
    v_user_email TEXT;
BEGIN
    IF v_current_user_id IS NULL THEN
        RETURN NEW;
    END IF;

    v_is_platform_owner := is_platform_owner(v_current_user_id);
    v_is_platform_admin := is_platform_admin(v_current_user_id);

    SELECT email INTO v_user_email FROM public.user_profiles WHERE id = v_current_user_id;

    -- حماية product_id (البراند) — السماح بالتعيين الأولي (NULL -> value)
    IF OLD.product_id IS NOT NULL AND OLD.product_id IS DISTINCT FROM NEW.product_id THEN
        IF NOT v_is_platform_owner THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكن تغيير البراند إلا من مالك المنصة / Not allowed: Only platform owner can change brand (product_id)';
        END IF;
    END IF;

    -- حماية owner_email
    IF OLD.owner_email IS DISTINCT FROM NEW.owner_email THEN
        IF NOT (v_is_platform_admin OR LOWER(OLD.owner_email) = LOWER(v_user_email)) THEN
            RAISE EXCEPTION 'غير مسموح: فقط مدير المنصة أو صاحب الاشتراك يمكنه تغيير owner_email';
        END IF;
    END IF;

    -- حماية partner_id
    IF OLD.partner_id IS DISTINCT FROM NEW.partner_id THEN
        IF NOT v_is_platform_admin THEN
            RAISE EXCEPTION 'غير مسموح: فقط مدير المنصة يمكنه تغيير partner_id';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: protect_user_profile_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.protect_user_profile_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- 🛑 CRITICAL: Bypass during registration process
    IF current_setting('app.is_registering', true) = 'true' THEN
        RETURN NEW;
    END IF;

    IF NOT is_super_admin(auth.uid()) THEN
        IF OLD.role IS NOT NULL AND OLD.role IS DISTINCT FROM NEW.role THEN
            RAISE EXCEPTION 'Cannot change role field';
        END IF;
        IF OLD.tenant_id IS NOT NULL AND OLD.tenant_id IS DISTINCT FROM NEW.tenant_id THEN
            RAISE EXCEPTION 'Cannot change tenant_id field';
        END IF;
        IF OLD.company_id IS NOT NULL AND OLD.company_id IS DISTINCT FROM NEW.company_id THEN
            RAISE EXCEPTION 'Cannot change company_id field';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: protect_user_profiles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.protect_user_profiles() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_user_id UUID := auth.uid();
    v_is_platform_owner BOOLEAN;
    v_is_platform_admin BOOLEAN;
    v_is_tenant_owner BOOLEAN;
BEGIN
    -- Skip for system operations (no user context)
    IF v_current_user_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Get current user's permissions
    v_is_platform_owner := is_platform_owner(v_current_user_id);
    v_is_platform_admin := is_platform_admin(v_current_user_id);
    v_is_tenant_owner := is_tenant_owner(v_current_user_id);

    -- ════════ Protection: is_super_admin ════════
    IF OLD.is_super_admin IS DISTINCT FROM NEW.is_super_admin THEN
        IF NOT v_is_platform_owner THEN
            RAISE EXCEPTION 'غير مسموح: فقط مالك المنصة يمكنه تغيير is_super_admin / Not allowed: Only platform owner can change is_super_admin';
        END IF;
    END IF;

    -- ════════ Protection: is_platform_admin ════════
    IF OLD.is_platform_admin IS DISTINCT FROM NEW.is_platform_admin THEN
        IF NOT v_is_platform_owner THEN
            RAISE EXCEPTION 'غير مسموح: فقط مالك المنصة يمكنه تغيير is_platform_admin / Not allowed: Only platform owner can change is_platform_admin';
        END IF;
    END IF;

    -- ════════ CRITICAL FIX: Allow first-time tenant/company assignment ════════
    -- During registration, the user updates their own profile to set tenant_id,
    -- company_id, and role. OLD.tenant_id will be NULL (first time).
    IF OLD.id = v_current_user_id AND OLD.tenant_id IS NULL AND NEW.tenant_id IS NOT NULL THEN
        -- This is initial registration — allow all fields to be set
        RETURN NEW;
    END IF;

    -- ════════ Protection: tenant_id (after initial setup) ════════
    IF OLD.tenant_id IS DISTINCT FROM NEW.tenant_id THEN
        IF NOT v_is_platform_admin THEN
            RAISE EXCEPTION 'غير مسموح: فقط مدير المنصة يمكنه تغيير tenant_id / Not allowed: Only platform admin can change tenant_id';
        END IF;
    END IF;

    -- ════════ Protection: company_id ════════
    IF OLD.company_id IS DISTINCT FROM NEW.company_id THEN
        IF NOT (v_is_platform_admin OR v_is_tenant_owner) THEN
            RAISE EXCEPTION 'غير مسموح: فقط مدير المنصة أو صاحب الاشتراك يمكنه تغيير company_id / Not allowed: Only platform admin or tenant owner can change company_id';
        END IF;
    END IF;

    -- ════════ Regular user: only allowed fields ════════
    IF NOT (v_is_platform_admin OR v_is_tenant_owner) THEN
        IF OLD.id = v_current_user_id THEN
            IF OLD.email IS DISTINCT FROM NEW.email THEN
                RAISE EXCEPTION 'غير مسموح: لا يمكنك تغيير البريد الإلكتروني / Not allowed: You cannot change email';
            END IF;
            IF OLD.role IS DISTINCT FROM NEW.role THEN
                RAISE EXCEPTION 'غير مسموح: لا يمكنك تغيير دورك / Not allowed: You cannot change your role';
            END IF;
        ELSE
            RAISE EXCEPTION 'غير مسموح: لا يمكنك تعديل بيانات مستخدم آخر / Not allowed: You cannot modify another user''s data';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: protect_user_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.protect_user_roles() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_user_id UUID := auth.uid();
    v_is_platform_admin BOOLEAN;
    v_is_tenant_owner BOOLEAN;
    v_current_user_tenant_id UUID;
    v_target_user_tenant_id UUID;
    v_target_user_company_id UUID;
    v_target_role_level INT;
    v_current_user_max_role_level INT;
    v_is_company_admin BOOLEAN;
BEGIN
    -- Skip for system operations
    IF v_current_user_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- 🛑 CRITICAL: Bypass during registration process
    IF current_setting('app.is_registering', true) = 'true' THEN
        RETURN NEW;
    END IF;

    v_is_platform_admin := is_platform_admin(v_current_user_id);

    -- Platform Admin can do everything
    IF v_is_platform_admin THEN
        RETURN NEW;
    END IF;

    -- Prevent self-modification
    IF NEW.user_id = v_current_user_id THEN
        RAISE EXCEPTION 'غير مسموح: لا يمكنك تغيير صلاحياتك بنفسك / Not allowed: You cannot modify your own permissions';
    END IF;

    v_is_tenant_owner := is_tenant_owner(v_current_user_id);
    v_current_user_tenant_id := get_user_tenant_id(v_current_user_id);

    -- Get target user info
    SELECT tenant_id, company_id INTO v_target_user_tenant_id, v_target_user_company_id
    FROM public.user_profiles
    WHERE id = NEW.user_id;

    -- Tenant Owner: can modify roles of users in their tenant
    IF v_is_tenant_owner THEN
        IF v_target_user_tenant_id != v_current_user_tenant_id THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكنك تعديل صلاحيات مستخدم خارج تينانتك / Not allowed: You cannot modify permissions of users outside your tenant';
        END IF;
        RETURN NEW;
    END IF;

    -- Company Admin: can modify roles of users in their company
    v_is_company_admin := is_company_admin(v_current_user_id, v_target_user_company_id);
    
    IF v_is_company_admin THEN
        IF NOT can_access_company(v_target_user_company_id, v_current_user_id) THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكنك تعديل صلاحيات مستخدم خارج شركتك / Not allowed: You cannot modify permissions of users outside your company';
        END IF;
        
        -- Check role level
        SELECT COALESCE(r.level, 100) INTO v_target_role_level
        FROM public.roles r WHERE r.id = NEW.role_id;
        
        SELECT COALESCE(MIN(r.level), 100) INTO v_current_user_max_role_level
        FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.id
        WHERE ur.user_id = v_current_user_id AND ur.is_active = true;
        
        IF v_target_role_level < v_current_user_max_role_level THEN
            RAISE EXCEPTION 'غير مسموح: لا يمكنك منح صلاحيات أعلى من صلاحياتك / Not allowed: You cannot grant permissions higher than your own';
        END IF;
        
        RETURN NEW;
    END IF;

    -- Regular user cannot modify roles
    RAISE EXCEPTION 'غير مسموح: ليس لديك صلاحية تعديل أدوار المستخدمين / Not allowed: You do not have permission to modify user roles';
END;
$$;


--
-- Name: publish_material_to_store(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.publish_material_to_store(p_material_id uuid, p_store_id uuid DEFAULT 'a1b2c3d4-0001-4000-8000-000000000001'::uuid, p_category_ids uuid[] DEFAULT NULL::uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_product_id UUID;
  v_tenant_id UUID;
  v_cat_id UUID;
BEGIN
  -- Check if already published
  SELECT id INTO v_product_id 
  FROM ecommerce_products 
  WHERE source_id = p_material_id AND source_table = 'fabric_materials';
  
  IF v_product_id IS NOT NULL THEN
    RETURN v_product_id; -- Already published
  END IF;

  -- Get tenant
  SELECT tenant_id INTO v_tenant_id FROM ecommerce_stores WHERE id = p_store_id;

  -- Insert product
  INSERT INTO ecommerce_products (
    id, tenant_id, store_id, material_id,
    marketing_title, short_description,
    seo_slug, sku, base_price, currency, sale_unit,
    is_published, source_table, source_id, product_origin, sector, product_type,
    view_count, order_count, created_at, updated_at
  )
  SELECT 
    gen_random_uuid(), v_tenant_id, p_store_id, fm.id,
    jsonb_build_object('ar', COALESCE(fm.name_ar, fm.name_en), 'en', COALESCE(fm.name_en, fm.name_ar), 'ru', COALESCE(fm.name_ru, ''), 'uk', COALESCE(fm.name_uk, '')),
    jsonb_build_object('ar', COALESCE(fm.name_ar, ''), 'en', COALESCE(fm.name_en, '')),
    LOWER(REGEXP_REPLACE(REPLACE(COALESCE(fm.name_en, fm.code), ' ', '-'), '[^a-z0-9\-]', '', 'g')) || '-' || SUBSTRING(fm.id::text, 1, 8),
    fm.code, COALESCE(fm.selling_price, 0), COALESCE(fm.currency, 'USD'), 'meter',
    false, 'fabric_materials', fm.id, 'own', 'fabric', 'physical',
    0, 0, NOW(), NOW()
  FROM fabric_materials fm WHERE fm.id = p_material_id
  RETURNING id INTO v_product_id;

  -- Add categories if provided
  IF p_category_ids IS NOT NULL THEN
    FOREACH v_cat_id IN ARRAY p_category_ids LOOP
      INSERT INTO ecommerce_product_categories (product_id, category_id)
      VALUES (v_product_id, v_cat_id) ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;

  RETURN v_product_id;
END;
$$;


--
-- Name: publish_materials_bulk(uuid[], uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.publish_materials_bulk(p_material_ids uuid[], p_store_id uuid DEFAULT 'a1b2c3d4-0001-4000-8000-000000000001'::uuid, p_category_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count INT := 0;
  v_mid UUID;
  v_pid UUID;
BEGIN
  FOREACH v_mid IN ARRAY p_material_ids LOOP
    v_pid := publish_material_to_store(v_mid, p_store_id, 
      CASE WHEN p_category_id IS NOT NULL THEN ARRAY[p_category_id] ELSE NULL END);
    IF v_pid IS NOT NULL THEN v_count := v_count + 1; END IF;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: recalculate_account_balance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.recalculate_account_balance(p_account_id uuid) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ob DECIMAL(15,2);
    v_total_debit DECIMAL(15,2);
    v_total_credit DECIMAL(15,2);
    v_calculated DECIMAL(15,2);
    v_normal VARCHAR(50);
BEGIN
    SELECT COALESCE(coa.opening_balance, 0), at.normal_balance 
    INTO v_ob, v_normal
    FROM chart_of_accounts coa
    JOIN account_types at ON coa.account_type_id = at.id
    WHERE coa.id = p_account_id;

    SELECT COALESCE(SUM(jel.debit), 0), COALESCE(SUM(jel.credit), 0)
    INTO v_total_debit, v_total_credit
    FROM journal_entry_lines jel
    JOIN journal_entries je ON jel.entry_id = je.id
    WHERE jel.account_id = p_account_id 
      AND je.is_posted = true
      AND je.status != 'cancelled';
    
    IF v_normal = 'debit' THEN
        v_calculated := v_ob + (v_total_debit - v_total_credit);
    ELSE
        v_calculated := v_ob + (v_total_credit - v_total_debit);
    END IF;

    UPDATE chart_of_accounts 
    SET current_balance = v_calculated, updated_at = NOW()
    WHERE id = p_account_id;
    RETURN v_calculated;
END;
$$;


--
-- Name: recalculate_all_accounts_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.recalculate_all_accounts_balance() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    acc RECORD;
    v_count INTEGER := 0;
BEGIN
    FOR acc IN SELECT id FROM chart_of_accounts LOOP
        PERFORM recalculate_account_balance(acc.id);
        v_count := v_count + 1;
    END LOOP;
    RETURN v_count;
END;
$$;


--
-- Name: record_payment(uuid, uuid, numeric, character varying, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.record_payment(p_tenant_id uuid, p_invoice_id uuid, p_amount numeric, p_payment_method character varying, p_transaction_id character varying DEFAULT NULL::character varying, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_invoice RECORD;
    v_payment_id UUID;
    v_subscription RECORD;
BEGIN
    -- الحصول على الفاتورة
    SELECT * INTO v_invoice FROM billing_invoices 
    WHERE id = p_invoice_id AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'الفاتورة غير موجودة');
    END IF;
    
    -- تسجيل الدفعة
    INSERT INTO billing_payments (
        tenant_id, invoice_id, amount, currency,
        payment_method, transaction_id, notes, status
    ) VALUES (
        p_tenant_id, p_invoice_id, p_amount, v_invoice.currency,
        p_payment_method, p_transaction_id, p_notes, 'completed'
    ) RETURNING id INTO v_payment_id;
    
    -- تحديث الفاتورة
    UPDATE billing_invoices
    SET status = CASE WHEN p_amount >= total_amount THEN 'paid' ELSE 'partial' END,
        paid_at = NOW(),
        paid_amount = COALESCE(paid_amount, 0) + p_amount
    WHERE id = p_invoice_id;
    
    -- تفعيل الاشتراك إذا كان في الانتظار
    UPDATE subscriptions
    SET status = 'active',
        current_period_start = NOW(),
        current_period_end = NOW() + CASE WHEN billing_cycle = 'yearly' THEN INTERVAL '1 year' ELSE INTERVAL '1 month' END
    WHERE tenant_id = p_tenant_id AND status IN ('trial', 'past_due')
    RETURNING * INTO v_subscription;
    
    -- تسجيل الحدث
    INSERT INTO saas_events (tenant_id, event_type, event_data, actor_type)
    VALUES (p_tenant_id, 'payment_received', jsonb_build_object(
        'invoice_id', p_invoice_id,
        'amount', p_amount,
        'method', p_payment_method
    ), 'admin');
    
    RETURN jsonb_build_object(
        'success', true,
        'payment_id', v_payment_id,
        'subscription_status', v_subscription.status
    );
END;
$$;


