--
-- Name: register_customer(character varying, character varying, character varying, character varying, uuid, uuid, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.register_customer(p_email character varying, p_password character varying, p_full_name character varying, p_phone character varying, p_tenant_id uuid, p_company_id uuid, p_customer_group_code character varying DEFAULT 'RETAIL'::character varying, p_country character varying DEFAULT NULL::character varying, p_city character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_auth_user_id UUID;
    v_customer_id UUID;
    v_customer_code VARCHAR;
    v_customer_group_id UUID;
    v_name_parts TEXT[];
    v_first_name VARCHAR;
    v_last_name VARCHAR;
BEGIN
    -- ═══════════════════════════════════════════════════════════════
    -- 1. التحقق من عدم وجود Email مسبقاً
    -- ═══════════════════════════════════════════════════════════════
    
    IF EXISTS (SELECT 1 FROM customers WHERE email = p_email AND tenant_id = p_tenant_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'email_exists',
            'message', 'البريد الإلكتروني مسجل مسبقاً'
        );
    END IF;
    
    -- ═══════════════════════════════════════════════════════════════
    -- 2. إنشاء المستخدم في Supabase Auth
    -- ═══════════════════════════════════════════════════════════════
    
    -- ملاحظة: هذا يحتاج تنفيذ من خلال Supabase Auth API
    -- في الـ Frontend أو عبر Edge Function
    -- هنا نفترض أن auth_user_id سيُمرر من الخارج
    
    -- للاختبار فقط، يمكن استخدام gen_random_uuid()
    -- في الواقع، يجب استخدام Supabase Auth signup
    v_auth_user_id := gen_random_uuid();
    
    RAISE NOTICE 'ℹ️ تم توليد auth_user_id: %', v_auth_user_id;
    RAISE NOTICE 'ℹ️ في Production، استخدم Supabase Auth API لإنشاء المستخدم';
    
    -- ═══════════════════════════════════════════════════════════════
    -- 3. توليد customer_code
    -- ═══════════════════════════════════════════════════════════════
    
    v_customer_code := generate_customer_code(p_tenant_id);
    
    -- ═══════════════════════════════════════════════════════════════
    -- 4. الحصول على customer_group_id
    -- ═══════════════════════════════════════════════════════════════
    
    SELECT id INTO v_customer_group_id
    FROM customer_groups
    WHERE code = p_customer_group_code 
      AND tenant_id = p_tenant_id
    LIMIT 1;
    
    -- إذا لم توجد المجموعة، استخدم RETAIL الافتراضية
    IF v_customer_group_id IS NULL THEN
        SELECT id INTO v_customer_group_id
        FROM customer_groups
        WHERE code = 'RETAIL' 
          AND tenant_id = p_tenant_id
        LIMIT 1;
    END IF;
    
    -- ═══════════════════════════════════════════════════════════════
    -- 5. فصل الاسم الأول والأخير
    -- ═══════════════════════════════════════════════════════════════
    
    v_name_parts := string_to_array(p_full_name, ' ');
    v_first_name := v_name_parts[1];
    
    IF array_length(v_name_parts, 1) > 1 THEN
        v_last_name := array_to_string(v_name_parts[2:], ' ');
    ELSE
        v_last_name := '';
    END IF;
    
    -- ═══════════════════════════════════════════════════════════════
    -- 6. إنشاء customers record
    -- ═══════════════════════════════════════════════════════════════
    
    INSERT INTO customers (
        tenant_id,
        company_id,
        code,
        customer_type,
        name_ar,
        name_en,
        first_name,
        last_name,
        email,
        phone,
        mobile,
        country,
        city,
        group_id,
        auth_user_id,
        status,
        created_at
    )
    VALUES (
        p_tenant_id,
        p_company_id,
        v_customer_code,
        'individual',
        p_full_name,
        p_full_name,
        v_first_name,
        v_last_name,
        p_email,
        p_phone,
        p_phone,
        p_country,
        p_city,
        v_customer_group_id,
        v_auth_user_id,
        'active',
        NOW()
    )
    RETURNING id INTO v_customer_id;
    
    RAISE NOTICE '✅ تم إنشاء customer: % (%)', v_customer_code, v_customer_id;
    
    -- ═══════════════════════════════════════════════════════════════
    -- 7. إنشاء user_profiles record
    -- ═══════════════════════════════════════════════════════════════
    
    INSERT INTO user_profiles (
        id,
        email,
        full_name,
        role,
        tenant_id,
        company_id,
        customer_id,
        phone,
        created_at
    )
    VALUES (
        v_auth_user_id,
        p_email,
        p_full_name,
        'customer',
        p_tenant_id,
        p_company_id,
        v_customer_id,
        p_phone,
        NOW()
    )
    ON CONFLICT (id) DO UPDATE SET
        email = EXCLUDED.email,
        full_name = EXCLUDED.full_name,
        role = EXCLUDED.role,
        tenant_id = EXCLUDED.tenant_id,
        company_id = EXCLUDED.company_id,
        customer_id = EXCLUDED.customer_id,
        phone = EXCLUDED.phone;
    
    RAISE NOTICE '✅ تم إنشاء user_profile: role=customer';
    
    -- ═══════════════════════════════════════════════════════════════
    -- 8. إرجاع النتيجة
    -- ═══════════════════════════════════════════════════════════════
    
    RETURN jsonb_build_object(
        'success', true,
        'customer_id', v_customer_id,
        'customer_code', v_customer_code,
        'auth_user_id', v_auth_user_id,
        'message', 'تم التسجيل بنجاح'
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE '❌ خطأ في register_customer: %', SQLERRM;
        RETURN jsonb_build_object(
            'success', false,
            'error', 'registration_failed',
            'message', SQLERRM
        );
END;
$$;


--
-- Name: register_new_subscriber(uuid, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.register_new_subscriber(p_user_id uuid, p_user_email character varying, p_user_name character varying, p_company_name character varying DEFAULT NULL::character varying, p_phone character varying DEFAULT NULL::character varying, p_business_type character varying DEFAULT 'general'::character varying, p_currency character varying DEFAULT 'USD'::character varying, p_country_code character varying DEFAULT 'SA'::character varying, p_plan_code character varying DEFAULT 'texa-professional'::character varying, p_chart_template character varying DEFAULT 'extended'::character varying, p_local_currency character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
      DECLARE
          v_tenant_code VARCHAR(50);
          v_tenant_id UUID;
          v_company_id UUID;
          v_plan_id UUID;
          v_product_id UUID;
          v_subscription_id UUID;
          v_tenant_sub_id UUID;
          v_trial_days INT;
          v_plan_type VARCHAR;
          v_included_modules text[];
          v_result JSONB;
          v_currencies TEXT[];
          v_tenant_owner_role_id UUID;
          v_branch_id UUID;
          v_warehouse_id UUID;
          -- CORE: الأساسيات الوظيفية فقط (يُمنح لكل مستأجر فوق موديولات الباقة)
          -- موديولات الأعمال تأتي حصراً من included_modules للباقة (التزام بالباقة)
          v_core_modules text[] := ARRAY[
              'core', 'dashboard', 'settings', 'users',
              'companies', 'system_config', 'activity_log', 'workflows'
          ];
      BEGIN
          PERFORM set_config('app.is_registering', 'true', true);

          IF EXISTS (
              SELECT 1 FROM user_profiles WHERE id = p_user_id AND tenant_id IS NOT NULL
          ) THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'error_code', 'ALREADY_REGISTERED',
                  'message', 'This account is already registered'
              );
          END IF;

          v_tenant_code := 'T-' || UPPER(SUBSTRING(MD5(RANDOM()::TEXT || NOW()::TEXT), 1, 10));
          
          v_currencies := ARRAY[p_currency];
          IF p_local_currency IS NOT NULL AND p_local_currency != p_currency THEN
              v_currencies := array_append(v_currencies, p_local_currency);
          END IF;
          
          -- ═══ البحث عن الباقة المطلوبة ═══
          SELECT id, trial_days, ARRAY(SELECT jsonb_array_elements_text(to_jsonb(included_modules))), COALESCE(plan_type, 'paid'), product_id
          INTO v_plan_id, v_trial_days, v_included_modules, v_plan_type, v_product_id
          FROM subscription_plans
          WHERE code = p_plan_code AND is_active = true
          LIMIT 1;
          
          -- Fallback 1 → texa-professional
          IF v_plan_id IS NULL THEN
              SELECT id, trial_days, ARRAY(SELECT jsonb_array_elements_text(to_jsonb(included_modules))), COALESCE(plan_type, 'paid'), product_id
              INTO v_plan_id, v_trial_days, v_included_modules, v_plan_type, v_product_id
              FROM subscription_plans
              WHERE code = 'texa-professional' AND is_active = true
              LIMIT 1;
          END IF;
          
          -- Fallback 2 → texa-starter
          IF v_plan_id IS NULL THEN
              SELECT id, trial_days, ARRAY(SELECT jsonb_array_elements_text(to_jsonb(included_modules))), COALESCE(plan_type, 'paid'), product_id
              INTO v_plan_id, v_trial_days, v_included_modules, v_plan_type, v_product_id
              FROM subscription_plans
              WHERE code = 'texa-starter' AND is_active = true
              LIMIT 1;
          END IF;
          
          -- Fallback 3: free plan
          IF v_plan_id IS NULL THEN
              SELECT id, trial_days, ARRAY(SELECT jsonb_array_elements_text(to_jsonb(included_modules))), COALESCE(plan_type, 'free'), product_id
              INTO v_plan_id, v_trial_days, v_included_modules, v_plan_type, v_product_id
              FROM subscription_plans
              WHERE plan_type = 'free' AND is_active = true
              LIMIT 1;
          END IF;
          
          IF v_plan_id IS NULL THEN
              RAISE EXCEPTION 'No active plans found';
          END IF;
          
          IF v_product_id IS NULL THEN
              SELECT id INTO v_product_id FROM saas_products 
              WHERE code = 'texacore' AND is_active = true LIMIT 1;
          END IF;
          
          v_tenant_id := create_new_tenant(
              v_tenant_code,
              COALESCE(p_company_name, p_user_name),
              p_user_email,
              p_phone,
              p_country_code,
              'ar',
              p_business_type,
              v_product_id
          );
          
          IF v_tenant_id IS NULL THEN
              RAISE EXCEPTION 'Failed to create Tenant';
          END IF;

          -- ═══ تحديث بيانات المالك في التينانت ═══
          UPDATE tenants SET
              owner_name = COALESCE(p_company_name, p_user_name),
              owner_email = p_user_email,
              owner_phone = p_phone,
              country = p_country_code
          WHERE id = v_tenant_id;
          
          -- ═══ 1. subscriptions ═══
          INSERT INTO subscriptions (
              tenant_id, product_id, plan_id, status,
              trial_ends_at, current_period_start, current_period_end
          )
          SELECT
              v_tenant_id, sp.product_id, v_plan_id,
              CASE 
                  WHEN v_plan_type = 'free' THEN 'active'
                  WHEN v_trial_days > 0 THEN 'trial'
                  ELSE 'active'
              END,
              CASE WHEN v_trial_days > 0 AND v_plan_type != 'free' THEN NOW() + (v_trial_days || ' days')::INTERVAL ELSE NULL END,
              NOW(),
              CASE 
                  WHEN v_plan_type = 'free' THEN NULL
                  ELSE NOW() + (v_trial_days || ' days')::INTERVAL
              END
          FROM subscription_plans sp
          WHERE sp.id = v_plan_id
          RETURNING id INTO v_subscription_id;
          
          -- ═══ 2. tenant_subscriptions ═══
          INSERT INTO tenant_subscriptions (
              tenant_id, plan_id, status,
              start_date, end_date, trial_end_date,
              billing_cycle, created_by
          ) VALUES (
              v_tenant_id, v_plan_id,
              CASE 
                  WHEN v_plan_type = 'free' THEN 'active'
                  WHEN v_trial_days > 0 THEN 'trial'
                  ELSE 'active'
              END,
              CURRENT_DATE,
              CASE 
                  WHEN v_plan_type = 'free' THEN DATE '2099-12-31'
                  ELSE CURRENT_DATE + v_trial_days
              END,
              CASE 
                  WHEN v_trial_days > 0 AND v_plan_type != 'free' THEN CURRENT_DATE + v_trial_days
                  ELSE NULL
              END,
              'monthly',
              p_user_id
          ) RETURNING id INTO v_tenant_sub_id;
          
          v_company_id := create_default_company_for_tenant(
              v_tenant_id,
              COALESCE(p_company_name, p_user_name),
              p_business_type,
              'production',
              p_currency,
              p_country_code
          );
          
          IF v_company_id IS NULL THEN
              RAISE EXCEPTION 'Failed to create company';
          END IF;
          
          INSERT INTO company_accounting_settings (
              company_id, base_currency, supported_currencies,
              fiscal_year_start_month, fiscal_year_end_month,
              enable_vat, decimal_places
          )
          VALUES (
              v_company_id, p_currency, v_currencies,
              1, 12, true, 2
          )
          ON CONFLICT (company_id) DO UPDATE SET
              base_currency = EXCLUDED.base_currency,
              supported_currencies = EXCLUDED.supported_currencies,
              updated_at = NOW();
          
          INSERT INTO user_profiles (id, email, full_name, tenant_id, company_id, role)
          VALUES (p_user_id, p_user_email, p_user_name, v_tenant_id, v_company_id, 'admin')
          ON CONFLICT (id) DO UPDATE SET
              email = EXCLUDED.email,
              full_name = EXCLUDED.full_name,
              tenant_id = EXCLUDED.tenant_id,
              company_id = EXCLUDED.company_id,
              role = EXCLUDED.role;
          
          SELECT id INTO v_tenant_owner_role_id FROM roles WHERE code = 'tenant_owner' LIMIT 1;
          IF v_tenant_owner_role_id IS NOT NULL THEN
              INSERT INTO user_roles (user_id, role_id, tenant_id, company_id, assigned_by, is_active)
              VALUES (p_user_id, v_tenant_owner_role_id, v_tenant_id, v_company_id, p_user_id, true)
              ON CONFLICT DO NOTHING;
              
              INSERT INTO tenant_users (tenant_id, user_id, role, is_active)
              VALUES (v_tenant_id, p_user_id, 'owner', true)
              ON CONFLICT (tenant_id, user_id) DO NOTHING;

              INSERT INTO user_role_assignments (user_id, role_id, tenant_id, company_id, assigned_by)
              VALUES (p_user_id, v_tenant_owner_role_id, v_tenant_id, v_company_id, p_user_id)
              ON CONFLICT DO NOTHING;
          END IF;
          
          -- ═══ الموديولات ═══
          IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'system_modules') THEN
              INSERT INTO tenant_modules (tenant_id, module_code, is_active, source)
              SELECT v_tenant_id, sm.code, true, 'plan'
              FROM system_modules sm
              WHERE sm.code = ANY(v_included_modules)
              AND sm.is_active = true
              ON CONFLICT (tenant_id, module_code) DO UPDATE SET is_active = true;
              
              INSERT INTO tenant_modules (tenant_id, module_code, is_active, source)
              SELECT v_tenant_id, sm.code, true, 'core'
              FROM system_modules sm
              WHERE sm.code = ANY(v_core_modules)
              AND sm.is_active = true
              ON CONFLICT (tenant_id, module_code) DO UPDATE SET is_active = true;
          END IF;
          
          IF p_chart_template IS NOT NULL THEN
              BEGIN
                  PERFORM apply_chart_template_to_company(v_company_id, p_chart_template);
              EXCEPTION WHEN OTHERS THEN
                  RAISE NOTICE 'Chart template warning: %', SQLERRM;
              END;
          END IF;
          
          -- ═══ الفرع الرئيسي والمستودع ═══
          INSERT INTO branches (tenant_id, company_id, name, name_ar, name_en, code, is_main, is_active)
          VALUES (v_tenant_id, v_company_id, 'الفرع الرئيسي', 'الفرع الرئيسي', 'Main Branch', 'MAIN-001', true, true)
          RETURNING id INTO v_branch_id;
          
          INSERT INTO warehouses (tenant_id, company_id, code, name, name_ar, name_en, warehouse_type, branch_id, is_active)
          VALUES (v_tenant_id, v_company_id, 'WH-MAIN', 'المستودع الرئيسي', 'المستودع الرئيسي', 'Main Warehouse', 'regular', v_branch_id, true)
          RETURNING id INTO v_warehouse_id;

          -- ═══ 🔔 إرسال الإشعار الشامل (بعد اكتمال كل البيانات) ═══
          BEGIN
              PERFORM send_new_subscriber_notification(v_tenant_id);
          EXCEPTION WHEN OTHERS THEN
              RAISE NOTICE 'Notification warning: %', SQLERRM;
          END;

          v_result := jsonb_build_object(
              'success', true,
              'tenant_id', v_tenant_id,
              'tenant_code', v_tenant_code,
              'company_id', v_company_id,
              'product_id', v_product_id,
              'subscription_id', v_subscription_id,
              'tenant_subscription_id', v_tenant_sub_id,
              'plan_code', p_plan_code,
              'plan_type', v_plan_type,
              'trial_days', v_trial_days,
              'trial_ends_at', CASE WHEN v_trial_days > 0 AND v_plan_type != 'free' 
                               THEN NOW() + (v_trial_days || ' days')::INTERVAL 
                               ELSE NULL END,
              'currencies', v_currencies,
              'message', 'Registration successful'
          );
          
          RETURN v_result;
          
      EXCEPTION
          WHEN OTHERS THEN
              RAISE EXCEPTION 'Registration error: %', SQLERRM;
      END;
$$;


--
-- Name: register_session(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.register_session(p_license_key text, p_session_token text, p_hardware_id text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_ip_address text DEFAULT NULL::text, p_hostname text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_tier TEXT; v_max_sessions INT; v_current_sessions INT;
  v_max_devices INT; v_current_devices INT;
BEGIN
  PERFORM public.cleanup_stale_sessions();

  SELECT tier INTO v_tier FROM licensing.licenses
  WHERE license_key = p_license_key AND status = 'active';

  IF v_tier IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_license');
  END IF;

  SELECT max_concurrent_sessions, max_devices INTO v_max_sessions, v_max_devices
  FROM public.license_limits WHERE tier = v_tier;
  v_max_sessions := COALESCE(v_max_sessions, 1);
  v_max_devices := COALESCE(v_max_devices, 1);

  SELECT COUNT(*) INTO v_current_sessions FROM public.active_sessions
  WHERE license_key = p_license_key;

  SELECT COUNT(DISTINCT hardware_id) INTO v_current_devices FROM public.active_sessions
  WHERE license_key = p_license_key AND hardware_id IS NOT NULL;

  IF v_current_sessions >= v_max_sessions THEN
    RETURN jsonb_build_object('success', false, 'error', 'session_limit_reached',
      'max_sessions', v_max_sessions, 'current_sessions', v_current_sessions);
  END IF;

  IF p_hardware_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.active_sessions WHERE license_key = p_license_key AND hardware_id = p_hardware_id
  ) AND v_current_devices >= v_max_devices THEN
    RETURN jsonb_build_object('success', false, 'error', 'device_limit_reached',
      'max_devices', v_max_devices, 'current_devices', v_current_devices);
  END IF;

  INSERT INTO public.active_sessions (license_key, session_token, hardware_id, user_agent, ip_address, hostname)
  VALUES (p_license_key, p_session_token, p_hardware_id, p_user_agent, p_ip_address, p_hostname)
  ON CONFLICT (session_token) DO UPDATE SET last_heartbeat = NOW();

  RETURN jsonb_build_object('success', true,
    'sessions_used', v_current_sessions + 1, 'sessions_max', v_max_sessions,
    'devices_used', v_current_devices, 'devices_max', v_max_devices);
END;
$$;


--
-- Name: register_white_label_payment(uuid, numeric, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.register_white_label_payment(p_agent_id uuid, p_amount numeric, p_payment_method character varying, p_payment_reference character varying, p_period_months integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_agent RECORD;
    v_payment_id UUID;
    v_valid_from TIMESTAMPTZ;
    v_valid_to TIMESTAMPTZ;
BEGIN
    -- التحقق من الوكيل
    SELECT * INTO v_agent FROM agents WHERE id = p_agent_id AND status = 'active';
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'الوكيل غير موجود أو غير نشط');
    END IF;
    
    -- حساب الفترة
    v_valid_from := NOW();
    v_valid_to := v_valid_from + (p_period_months || ' months')::INTERVAL;
    
    -- إنشاء سجل الدفعة
    INSERT INTO white_label_payments (
        agent_id, amount, payment_method, payment_reference,
        period_months, valid_from, valid_to, status
    ) VALUES (
        p_agent_id, p_amount, p_payment_method, p_payment_reference,
        p_period_months, v_valid_from, v_valid_to, 'pending'
    ) RETURNING id INTO v_payment_id;
    
    -- تحديث حالة الوكيل
    UPDATE agents
    SET white_label_status = 'pending'
    WHERE id = p_agent_id;
    
    -- تسجيل الحدث
    INSERT INTO agent_events (agent_id, event_type, event_data)
    VALUES (p_agent_id, 'white_label_payment_registered', jsonb_build_object(
        'payment_id', v_payment_id,
        'amount', p_amount,
        'period_months', p_period_months
    ));
    
    RETURN jsonb_build_object(
        'success', true,
        'payment_id', v_payment_id,
        'valid_from', v_valid_from,
        'valid_to', v_valid_to,
        'message', 'تم تسجيل الدفعة بنجاح - في انتظار المعالجة'
    );
END;
$$;


--
-- Name: reject_recurring_entry(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.reject_recurring_entry(p_history_id uuid, p_user_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    UPDATE recurring_entry_history
    SET 
        approval_status = 'rejected',
        approved_by = p_user_id,
        approved_at = NOW(),
        rejection_reason = p_reason,
        status = 'cancelled'
    WHERE id = p_history_id
      AND approval_status = 'pending';
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Record not found or already processed');
    END IF;
    
    RETURN jsonb_build_object('success', true, 'message', 'Rejected successfully');
END;
$$;


--
-- Name: reject_review(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.reject_review(p_tenant_id uuid, p_review_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    UPDATE product_reviews
    SET status = 'rejected',
        report_reason = p_reason,
        updated_at = NOW()
    WHERE id = p_review_id
      AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'التقييم غير موجود');
    END IF;
    
    RETURN jsonb_build_object('success', true, 'message', 'تم رفض التقييم');
END;
$$;


--
-- Name: release_inventory_reservation(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.release_inventory_reservation(p_material_id uuid, p_warehouse_id uuid, p_company_id uuid, p_quantity numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    BEGIN
        -- Release reservation without deducting actual stock
        UPDATE inventory_stock
        SET reserved_quantity = GREATEST(COALESCE(reserved_quantity, 0) - p_quantity, 0),
            updated_at = NOW()
        WHERE material_id = p_material_id
          AND warehouse_id = p_warehouse_id
          AND company_id = p_company_id;
    END;
    $$;


--
-- Name: relink_telegram_doc(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.relink_telegram_doc(p_pa_id uuid, p_entity_type text, p_entity_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    UPDATE documents SET entity_type = p_entity_type, entity_id = p_entity_id, updated_at = now()
    WHERE entity_type = 'pending_action' AND entity_id = p_pa_id;
EXCEPTION WHEN OTHERS THEN NULL;
END $$;


--
-- Name: remove_from_cart(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.remove_from_cart(p_item_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_cart_id UUID;
BEGIN
    -- حذف العنصر
    DELETE FROM shopping_cart_items
    WHERE id = p_item_id
    RETURNING cart_id INTO v_cart_id;
    
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    
    -- تحديث المجاميع
    PERFORM update_cart_totals(v_cart_id);
    
    RETURN TRUE;
END;
$$;


--
-- Name: remove_module_from_plan(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.remove_module_from_plan(p_plan_id uuid, p_module_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_is_core BOOLEAN;
BEGIN
    -- التحقق من أن الموديول ليس أساسي
    SELECT is_core INTO v_is_core
    FROM plan_modules
    WHERE plan_id = p_plan_id AND module_id = p_module_id;
    
    IF v_is_core THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'core_module',
            'message', 'لا يمكن إزالة موديول أساسي'
        );
    END IF;
    
    -- حذف الموديول
    DELETE FROM plan_modules
    WHERE plan_id = p_plan_id AND module_id = p_module_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'message', 'تمت إزالة الموديول بنجاح'
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'exception',
            'message', SQLERRM
        );
END;
$$;


--
-- Name: remove_product_image(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.remove_product_image(p_tenant_id uuid, p_product_id uuid, p_image_url text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_images JSONB;
    v_updated_images JSONB;
BEGIN
    -- 1. الحصول على الصور الحالية
    SELECT COALESCE(images, '[]'::jsonb)
    INTO v_current_images
    FROM products
    WHERE id = p_product_id AND tenant_id = p_tenant_id;
    
    -- 2. حذف الصورة المحددة
    v_updated_images := (
        SELECT jsonb_agg(img)
        FROM jsonb_array_elements(v_current_images) AS img
        WHERE img->>'url' != p_image_url
    );
    
    -- 3. تحديث المنتج
    UPDATE products
    SET images = COALESCE(v_updated_images, '[]'::jsonb),
        updated_at = NOW()
    WHERE id = p_product_id AND tenant_id = p_tenant_id;
    
    RETURN FOUND;
END;
$$;


--
-- Name: renew_subscription(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.renew_subscription(p_subscription_id uuid, p_months integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_subscription RECORD;
    v_new_end DATE;
    v_result JSONB;
BEGIN
    -- الحصول على الاشتراك
    SELECT * INTO v_subscription
    FROM subscriptions
    WHERE id = p_subscription_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'subscription_not_found');
    END IF;
    
    -- حساب التاريخ الجديد
    IF v_subscription.current_period_end IS NULL OR 
       v_subscription.current_period_end < CURRENT_DATE THEN
        v_new_end := CURRENT_DATE + (p_months * INTERVAL '1 month');
    ELSE
        v_new_end := v_subscription.current_period_end + (p_months * INTERVAL '1 month');
    END IF;
    
    -- تحديث الاشتراك
    UPDATE subscriptions
    SET 
        status = 'active',
        current_period_end = v_new_end,
        locked_at = NULL,
        lock_reason = NULL,
        updated_at = NOW()
    WHERE id = p_subscription_id;
    
    -- تسجيل
    PERFORM log_audit(
        'renew',
        'subscriptions',
        p_subscription_id,
        NULL,
        NULL,
        jsonb_build_object('new_period_end', v_new_end, 'months', p_months)
    );
    
    RETURN jsonb_build_object(
        'success', true,
        'new_period_end', v_new_end,
        'months_added', p_months
    );
END;
$$;


--
-- Name: reorder_product_images(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.reorder_product_images(p_tenant_id uuid, p_product_id uuid, p_image_orders jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_images JSONB;
    v_updated_images JSONB;
    v_order_item JSONB;
BEGIN
    -- 1. الحصول على الصور الحالية
    SELECT COALESCE(images, '[]'::jsonb)
    INTO v_current_images
    FROM products
    WHERE id = p_product_id AND tenant_id = p_tenant_id;
    
    -- 2. تحديث display_order لكل صورة
    v_updated_images := (
        SELECT jsonb_agg(
            jsonb_set(
                img, 
                '{display_order}', 
                to_jsonb(
                    COALESCE(
                        (
                            SELECT (order_item->>'display_order')::int
                            FROM jsonb_array_elements(p_image_orders) AS order_item
                            WHERE order_item->>'url' = img->>'url'
                        ),
                        (img->>'display_order')::int
                    )
                )
            )
            ORDER BY 
                COALESCE(
                    (
                        SELECT (order_item->>'display_order')::int
                        FROM jsonb_array_elements(p_image_orders) AS order_item
                        WHERE order_item->>'url' = img->>'url'
                    ),
                    (img->>'display_order')::int
                )
        )
        FROM jsonb_array_elements(v_current_images) AS img
    );
    
    -- 3. تحديث المنتج
    UPDATE products
    SET images = v_updated_images,
        updated_at = NOW()
    WHERE id = p_product_id AND tenant_id = p_tenant_id;
    
    RETURN FOUND;
END;
$$;


