    || '<tr><td style="padding:20px 40px;text-align:center;"><p style="margin:0;font-size:12px;color:#9ca3af;">🔒 '||v_note||'</p></td></tr>'
    || '<tr><td style="background:#f9fafb;padding:20px 40px;text-align:center;border-top:1px solid #e5e7eb;"><p style="margin:0;font-size:12px;color:#9ca3af;">Texa<span style="color:#f59e0b;font-weight:800;">Core</span> ERP · <a href="https://texacore.ai" style="color:#047857;text-decoration:none;">texacore.ai</a></p></td></tr>'
