--
-- Name: reserve_inventory_stock(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.reserve_inventory_stock(p_material_id uuid, p_warehouse_id uuid, p_company_id uuid, p_quantity numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    BEGIN
        -- Increase reserved_quantity (meters level)
        UPDATE inventory_stock
        SET reserved_quantity = COALESCE(reserved_quantity, 0) + p_quantity,
            updated_at = NOW()
        WHERE material_id = p_material_id
          AND warehouse_id = p_warehouse_id
          AND company_id = p_company_id;
          
        -- If no row was updated, do nothing (material may not exist in this warehouse)
        -- This is non-blocking — the reservation is advisory
    END;
    $$;


--
-- Name: resolve_payment_fund(jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.resolve_payment_fund(p_adata jsonb, p_company uuid, p_user uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_fund uuid;
BEGIN
    -- 1) صندوق مختار (بوت/واجهة): نقدي/بنكي فعّال للشركة + متاح للمستخدم (عزل)
    v_fund := NULLIF(p_adata->>'fund_account_id','')::uuid;
    IF v_fund IS NOT NULL THEN
        PERFORM 1 FROM chart_of_accounts
          WHERE id = v_fund AND company_id = p_company
            AND (COALESCE(is_cash_account,false) OR COALESCE(is_bank_account,false))
            AND COALESCE(is_active,true) AND COALESCE(is_group,false) = false;
        IF NOT FOUND THEN
            v_fund := NULL;                                   -- ليس صندوقاً صالحاً
        ELSIF NOT public.can_access_fund(v_fund, p_user) THEN
            v_fund := NULL;                                   -- 🔒 غير متاح للمستخدم → تجاهُل
        END IF;
    END IF;
    -- 2) الأساسي للمستخدم، ثم أي صندوق متاح له
    IF v_fund IS NULL THEN
        SELECT fund_account_id INTO v_fund FROM get_user_accessible_funds(p_user) WHERE is_primary LIMIT 1;
    END IF;
    IF v_fund IS NULL THEN
        SELECT fund_account_id INTO v_fund FROM get_user_accessible_funds(p_user) LIMIT 1;
    END IF;
    RETURN v_fund;
END $$;


--
-- Name: review_listing_request(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.review_listing_request(p_request_id uuid, p_status text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_req marketplace_listing_requests%ROWTYPE;
BEGIN
    IF p_status NOT IN ('rejected', 'changes_requested', 'suspended') THEN
        RAISE EXCEPTION 'invalid review status %', p_status;
    END IF;

    SELECT * INTO v_req FROM marketplace_listing_requests WHERE id = p_request_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'listing request not found';
    END IF;
    IF NOT (is_platform_admin() OR v_req.tenant_id = get_user_tenant_id()) THEN
        RAISE EXCEPTION 'not authorized to review this request';
    END IF;

    -- إيقاف منتج منشور سابقاً
    IF p_status = 'suspended' AND v_req.ecommerce_product_id IS NOT NULL THEN
        UPDATE ecommerce_products SET is_published = false
        WHERE id = v_req.ecommerce_product_id;
    END IF;

    UPDATE marketplace_listing_requests
    SET status = p_status,
        review_note = COALESCE(p_note, review_note),
        reviewed_by = auth.uid(),
        reviewed_at = now()
    WHERE id = p_request_id;

    PERFORM update_supplier_link_stats(v_req.link_id);
END;
$$;


--
-- Name: revoke_all_other_sessions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.revoke_all_other_sessions(p_current_session_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    deleted_count int;
BEGIN
    -- Delete all sessions except the current one
    DELETE FROM auth.sessions 
    WHERE user_id = auth.uid() 
    AND id != p_current_session_id;
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;


--
-- Name: revoke_all_trusted_devices(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.revoke_all_trusted_devices() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE cnt int;
BEGIN
    DELETE FROM trusted_devices WHERE user_id = auth.uid();
    GET DIAGNOSTICS cnt = ROW_COUNT;
    RETURN cnt;
END;
$$;


--
-- Name: revoke_my_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.revoke_my_session(p_session_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid;
BEGIN
    -- تحقق أن الجلسة تخص المستخدم الحالي
    SELECT user_id INTO v_user_id 
    FROM auth.sessions 
    WHERE id = p_session_id AND user_id = auth.uid();
    
    IF v_user_id IS NULL THEN
        RETURN false;
    END IF;

    -- حذف refresh tokens أولاً
    DELETE FROM auth.refresh_tokens WHERE session_id = p_session_id;
    
    -- ثم حذف الجلسة
    DELETE FROM auth.sessions WHERE id = p_session_id AND user_id = auth.uid();
    
    RETURN true;
END;
$$;


--
-- Name: revoke_trusted_device(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.revoke_trusted_device(p_device_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    DELETE FROM trusted_devices WHERE id = p_device_id AND user_id = auth.uid();
    RETURN FOUND;
END;
$$;


--
-- Name: round_amount(numeric, integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.round_amount(p_amount numeric, p_decimal_places integer, p_rounding_method character varying DEFAULT 'half_up'::character varying) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_multiplier DECIMAL;
    v_result DECIMAL(18,6);
BEGIN
    -- حساب المضاعف
    v_multiplier := POWER(10, p_decimal_places);
    
    -- تطبيق طريقة التقريب
    CASE p_rounding_method
        -- التقريب الطبيعي (النصف للأعلى) - الطريقة الأكثر شيوعاً
        WHEN 'half_up' THEN
            v_result := ROUND(p_amount * v_multiplier) / v_multiplier;
        
        -- التقريب للأسفل دائماً
        WHEN 'down', 'floor' THEN
            v_result := FLOOR(p_amount * v_multiplier) / v_multiplier;
        
        -- التقريب للأعلى دائماً
        WHEN 'up', 'ceil' THEN
            v_result := CEIL(p_amount * v_multiplier) / v_multiplier;
        
        -- التقريب المصرفي (النصف للزوجي) - أكثر دقة إحصائياً
        WHEN 'half_even', 'banker' THEN
            -- PostgreSQL's ROUND uses half-even by default in some cases
            v_result := ROUND(p_amount::NUMERIC, p_decimal_places);
        
        -- التقريب للأسفل (النصف للأسفل)
        WHEN 'half_down' THEN
            v_result := CASE
                WHEN (p_amount * v_multiplier - FLOOR(p_amount * v_multiplier)) < 0.5
                THEN FLOOR(p_amount * v_multiplier) / v_multiplier
                ELSE CEIL(p_amount * v_multiplier) / v_multiplier
            END;
        
        -- افتراضي: half_up
        ELSE
            v_result := ROUND(p_amount * v_multiplier) / v_multiplier;
    END CASE;
    
    RETURN v_result;
END;
$$;


--
-- Name: round_amount_for_company(uuid, numeric, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.round_amount_for_company(p_company_id uuid, p_amount numeric, p_type character varying DEFAULT 'amount'::character varying) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_rounding_method VARCHAR(10);
    v_decimal_places INT;
    v_settings RECORD;
BEGIN
    -- الحصول على إعدادات التقريب
    SELECT * INTO v_settings FROM get_company_rounding_settings(p_company_id);
    
    v_rounding_method := v_settings.rounding_method;
    
    -- تحديد عدد المنازل العشرية حسب النوع
    v_decimal_places := CASE p_type
        WHEN 'tax' THEN v_settings.tax_rounding
        WHEN 'unit_price' THEN v_settings.unit_price_rounding
        WHEN 'total' THEN v_settings.total_rounding
        ELSE v_settings.amount_rounding
    END;
    
    -- تطبيق التقريب
    RETURN round_amount(p_amount, v_decimal_places, v_rounding_method);
END;
$$;


--
-- Name: run_isolation_tests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.run_isolation_tests() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_results JSONB := '[]'::JSONB;
    v_test RECORD;
    v_summary JSONB;
    v_pass INT := 0;
    v_fail INT := 0;
    v_warn INT := 0;
BEGIN
    FOR v_test IN SELECT * FROM test_tenant_isolation()
    LOOP
        v_results := v_results || jsonb_build_object(
            'name', v_test.test_name,
            'result', v_test.result,
            'details', v_test.details
        );
        
        IF v_test.result LIKE '%PASS%' THEN
            v_pass := v_pass + 1;
        ELSIF v_test.result LIKE '%FAIL%' THEN
            v_fail := v_fail + 1;
        ELSE
            v_warn := v_warn + 1;
        END IF;
    END LOOP;
    
    v_summary := jsonb_build_object(
        'total', v_pass + v_fail + v_warn,
        'passed', v_pass,
        'failed', v_fail,
        'warnings', v_warn,
        'status', CASE 
            WHEN v_fail > 0 THEN 'FAILED'
            WHEN v_warn > 0 THEN 'WARNING'
            ELSE 'PASSED'
        END
    );
    
    RETURN jsonb_build_object(
        'summary', v_summary,
        'tests', v_results,
        'timestamp', NOW()
    );
END;
$$;


--
-- Name: save_guest_checkout(uuid, uuid, character varying, character varying, character varying, character varying, jsonb, jsonb, boolean, text, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.save_guest_checkout(p_tenant_id uuid, p_company_id uuid, p_session_id character varying, p_email character varying, p_full_name character varying, p_phone character varying, p_shipping_address jsonb, p_billing_address jsonb DEFAULT NULL::jsonb, p_same_as_shipping boolean DEFAULT true, p_notes text DEFAULT NULL::text, p_ip_address character varying DEFAULT NULL::character varying, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_guest_checkout_id UUID;
    v_result JSONB;
BEGIN
    -- حفظ أو تحديث معلومات الزائر
    INSERT INTO guest_checkouts (
        tenant_id, company_id, session_id, email, full_name, phone,
        shipping_address, billing_address, same_as_shipping,
        notes, ip_address, user_agent
    )
    VALUES (
        p_tenant_id, p_company_id, p_session_id, p_email, p_full_name, p_phone,
        p_shipping_address, p_billing_address, p_same_as_shipping,
        p_notes, p_ip_address, p_user_agent
    )
    ON CONFLICT (tenant_id, session_id, email)
    DO UPDATE SET
        full_name = EXCLUDED.full_name,
        phone = EXCLUDED.phone,
        shipping_address = EXCLUDED.shipping_address,
        billing_address = EXCLUDED.billing_address,
        same_as_shipping = EXCLUDED.same_as_shipping,
        notes = EXCLUDED.notes,
        updated_at = NOW()
    RETURNING id INTO v_guest_checkout_id;
    
    -- إرجاع النتيجة
    v_result := jsonb_build_object(
        'success', true,
        'guest_checkout_id', v_guest_checkout_id,
        'message', 'تم حفظ معلومات الزائر بنجاح'
    );
    
    RETURN v_result;
END;
$$;


--
-- Name: save_report_result(uuid, jsonb, integer, jsonb, character varying, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.save_report_result(p_template_id uuid, p_parameters jsonb, p_result_count integer, p_result_summary jsonb, p_output_format character varying, p_file_path text, p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_saved_id UUID;
    v_tenant_id UUID;
BEGIN
    SELECT tenant_id INTO v_tenant_id FROM report_templates WHERE id = p_template_id;
    
    INSERT INTO saved_reports (
        tenant_id, template_id, parameters, result_count,
        result_summary, output_format, file_path, generated_by
    ) VALUES (
        v_tenant_id, p_template_id, p_parameters, p_result_count,
        p_result_summary, p_output_format, p_file_path, p_user_id
    ) RETURNING id INTO v_saved_id;
    
    RETURN v_saved_id;
END;
$$;


--
-- Name: schedule_expiry_notifications(uuid, uuid, date, text, numeric, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.schedule_expiry_notifications(p_tenant_id uuid, p_subscription_id uuid, p_end_date date, p_plan_name text DEFAULT 'الباقة'::text, p_amount_due numeric DEFAULT 0, p_currency character varying DEFAULT 'USD'::character varying) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant RECORD;
    v_settings RECORD;
    v_alert_day INT;
BEGIN
    -- جلب الإعدادات
    SELECT * INTO v_settings FROM saas_settings LIMIT 1;
    
    -- التحقق من تفعيل التنبيهات
    IF NOT COALESCE(v_settings.enable_alerts, true) THEN
        RAISE NOTICE '⚠️ Alerts disabled in settings';
        RETURN;
    END IF;
    
    -- جلب بيانات المستأجر
    SELECT name, email INTO v_tenant
    FROM tenants
    WHERE id = p_tenant_id;
    
    -- حذف التنبيهات القديمة غير المرسلة
    DELETE FROM subscription_alerts
    WHERE subscription_id = p_subscription_id
        AND status = 'pending';
    
    -- جدولة التنبيهات حسب الإعدادات
    FOR v_alert_day IN 
        SELECT jsonb_array_elements_text(
            COALESCE(v_settings.alert_days_before, '[7, 3, 1]'::JSONB)
        )::INT
    LOOP
        -- التحقق من أن التاريخ في المستقبل
        IF p_end_date - (v_alert_day || ' days')::INTERVAL > CURRENT_DATE THEN
            INSERT INTO subscription_alerts (
                tenant_id, subscription_id, alert_type, alert_date, days_remaining, amount_due,
                message_ar, message_en, sent_to
            ) VALUES (
                p_tenant_id, 
                p_subscription_id, 
                CASE WHEN v_alert_day = 0 THEN 'expired' ELSE 'expiry_warning' END,
                p_end_date - (v_alert_day || ' days')::INTERVAL, 
                v_alert_day,
                p_amount_due,
                CASE 
                    WHEN v_alert_day = 0 THEN '🔴 انتهى اشتراكك اليوم. يرجى التجديد فوراً لتجنب تعليق الخدمة'
                    WHEN v_alert_day <= 3 THEN format('⚠️ تنبيه عاجل: اشتراكك في %s سينتهي بعد %s أيام. المبلغ المطلوب: %s %s', 
                        p_plan_name, v_alert_day, p_amount_due, p_currency)
                    ELSE format('تنبيه: اشتراكك في %s سينتهي بعد %s أيام في تاريخ %s', 
                        p_plan_name, v_alert_day, p_end_date)
                END,
                CASE 
                    WHEN v_alert_day = 0 THEN '🔴 Your subscription expired today. Please renew immediately to avoid service suspension'
                    WHEN v_alert_day <= 3 THEN format('⚠️ Urgent: Your %s subscription expires in %s days. Amount due: %s %s',
                        p_plan_name, v_alert_day, p_amount_due, p_currency)
                    ELSE format('Notice: Your %s subscription will expire in %s days on %s',
                        p_plan_name, v_alert_day, p_end_date)
                END,
                v_tenant.email
            );
        END IF;
    END LOOP;
    
    RAISE NOTICE '📧 Scheduled notification alerts for tenant: %', v_tenant.name;
END;
$$;


--
-- Name: search_ecommerce_products(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.search_ecommerce_products(p_store_id uuid, p_query text, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, material_id uuid, product_id uuid, marketing_title jsonb, marketing_description jsonb, short_description jsonb, gallery_images text[], seo_slug text, tags text[], is_featured boolean, is_new boolean, is_bestseller boolean, is_on_sale boolean, sale_price numeric, sale_unit text, min_order_quantity numeric, view_count integer, order_count integer, published_at timestamp with time zone, material_code text, material_name_ar text, material_name_en text, unit_price numeric, selling_price numeric, material_image text, effective_price numeric, category_slugs text[], stock_status text, total_stock numeric, available_date timestamp with time zone, supplier_lead_time text, currency text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    WITH q AS (
        SELECT ar_normalize(p_query) AS nq,
               regexp_split_to_array(trim(ar_normalize(p_query)), '\s+') AS tokens
    ),
    base AS (
        SELECT g.*,
               -- Searchable corpus: serial + code + all-language names + every
               -- fabric attribute + localized marketing text + tags + categories
               ar_normalize(
                   concat_ws(' ',
                       g.display_no,
                       g.material_code, g.material_name_ar, g.material_name_en,
                       m.name_ru, m.name_uk, m.name_tr, m.name_pl, m.name_ro, m.name_it, m.name_de,
                       m.composition, m.season, m.usage_type, m.origin_country, m.category,
                       m.default_width, m.weight_per_meter,
                       g.marketing_title::text, g.marketing_description::text, g.short_description::text,
                       array_to_string(g.tags, ' '),
                       array_to_string(g.category_slugs, ' ')
                   )
               ) AS ntext,
               lower(coalesce(g.material_code, '')) AS lcode,
               lower(coalesce(g.display_no, '')) AS lserial
        FROM get_ecommerce_products(p_store_id, NULL, NULL, false, 1000, 0) g
        LEFT JOIN fabric_materials m ON m.id = g.material_id
    )
    SELECT
        s.id, s.material_id, s.product_id,
        s.marketing_title, s.marketing_description, s.short_description,
        s.gallery_images, s.seo_slug, s.tags,
        s.is_featured, s.is_new, s.is_bestseller, s.is_on_sale,
        s.sale_price, s.sale_unit, s.min_order_quantity,
        s.view_count, s.order_count, s.published_at,
        s.material_code, s.material_name_ar, s.material_name_en,
        s.unit_price, s.selling_price, s.material_image,
        s.effective_price, s.category_slugs,
        s.stock_status, s.total_stock, s.available_date,
        s.supplier_lead_time, s.currency
    FROM (
        SELECT b.*,
               (SELECT count(*) FROM unnest(q.tokens) tok
                  WHERE tok <> '' AND b.ntext LIKE '%' || tok || '%') AS hits,
               (SELECT count(*) FROM unnest(q.tokens) tok WHERE tok <> '') AS ntok
        FROM base b, q
        WHERE q.nq <> ''
    ) s
    WHERE s.hits > 0                                              -- at least one token matches
       OR s.lcode LIKE lower(trim(p_query)) || '%'                -- or code/barcode prefix
       OR s.lserial LIKE lower(trim(p_query)) || '%'              -- or serial (TX-…) prefix
    ORDER BY
        (s.lcode = lower(trim(p_query))) DESC,                    -- exact code first
        (s.lserial = lower(trim(p_query))) DESC,                  -- exact serial next
        (s.hits = s.ntok) DESC,                                   -- all tokens matched
        s.hits DESC,
        (s.ntext LIKE ('%' || (SELECT nq FROM q) || '%')) DESC,   -- contains full phrase
        s.order_count DESC, s.view_count DESC
    LIMIT GREATEST(p_limit, 1)
$$;


--
-- Name: select_marketplace_supplier(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.select_marketplace_supplier(p_material_id uuid, p_qty numeric DEFAULT 1) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT o.supplier_link_id
  FROM marketplace_supplier_offers o
  JOIN marketplace_supplier_links l ON l.id = o.supplier_link_id AND l.status = 'active'
  LEFT JOIN performance_scores ps
    ON ps.subject_type = 'supplier' AND ps.subject_id = o.supplier_link_id AND ps.dimension = 'overall'
  WHERE o.material_id = p_material_id
    AND o.is_active
    AND p_qty >= o.min_qty
    AND (o.available_qty IS NULL OR o.available_qty >= p_qty)
  ORDER BY o.price ASC, COALESCE(ps.avg_score, 0) DESC, COALESCE(o.lead_time_days, 9999) ASC
  LIMIT 1;
$$;


--
-- Name: send_new_subscriber_notification(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.send_new_subscriber_notification(p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_admin_tenant_id UUID := '681aa0e4-7692-4337-a3e8-2c127f80e573';
    v_admin_company_id UUID;
    v_admin_user_id UUID;
    v_tenant RECORD;
    v_product_name TEXT;
    v_product_code TEXT;
    v_plan_name TEXT;
    v_plan_price NUMERIC;
    v_plan_code TEXT;
    v_plan_type TEXT;
    v_trial_days INT;
    v_sub_status TEXT;
    v_sub_end_date DATE;
    v_modules_count INT;
    v_phone TEXT;
    v_users_count INT;
    v_companies_count INT;
    v_bot_token TEXT;
    v_tg_message TEXT;
    v_tg_url TEXT;
    v_conn RECORD;
    v_notif_body TEXT;
    v_notif_metadata JSONB;
    v_email TEXT; v_provider TEXT; v_lang TEXT; v_provider_label TEXT; v_lang_label TEXT;
    v_ip_country TEXT; v_ip TEXT; v_loc TEXT := ''; v_local_time TEXT;
    v_admin_url CONSTANT TEXT := 'https://app.texacore.ai/saas/subscribers';
BEGIN
    -- ═══ جلب company_id الإدارية ═══
    SELECT id INTO v_admin_company_id FROM companies 
    WHERE tenant_id = v_admin_tenant_id 
    ORDER BY created_at LIMIT 1;
    
    IF v_admin_company_id IS NULL THEN RETURN; END IF;

    -- ═══ 1. جلب بيانات المستأجر ═══
    SELECT * INTO v_tenant FROM tenants WHERE id = p_tenant_id;
    IF NOT FOUND THEN RETURN; END IF;

    -- ═══ 2. بيانات المنصة ═══
    SELECT sp.name, sp.code INTO v_product_name, v_product_code
    FROM saas_products sp WHERE sp.id = v_tenant.product_id;

    -- ═══ 3. بيانات الباقة والاشتراك ═══
    SELECT sp.name_ar, sp.price_monthly, sp.code, COALESCE(sp.plan_type, 'paid'), sp.trial_days,
           ts.status, ts.end_date
    INTO v_plan_name, v_plan_price, v_plan_code, v_plan_type, v_trial_days,
         v_sub_status, v_sub_end_date
    FROM tenant_subscriptions ts
    JOIN subscription_plans sp ON sp.id = ts.plan_id
    WHERE ts.tenant_id = p_tenant_id
    ORDER BY ts.created_at DESC
    LIMIT 1;

    -- ═══ 4. عدد الموديولات ═══
    SELECT count(*) INTO v_modules_count
    FROM tenant_modules WHERE tenant_id = p_tenant_id AND is_active = true;

    -- ═══ 5. رقم الهاتف ═══
    v_phone := COALESCE(v_tenant.phone, v_tenant.owner_phone, '');
    IF v_phone = '' THEN
        SELECT up.phone INTO v_phone FROM user_profiles up 
        WHERE up.tenant_id = p_tenant_id LIMIT 1;
    END IF;

    -- ═══ 6. عدد المستخدمين والشركات ═══
    SELECT count(*) INTO v_users_count FROM user_profiles WHERE tenant_id = p_tenant_id;
    SELECT count(*) INTO v_companies_count FROM companies WHERE tenant_id = p_tenant_id;

    -- ═══ 6b. البريد (حارس tombstone) + مزوّد التسجيل + اللغة ═══
    v_email := COALESCE(NULLIF(v_tenant.owner_email, ''), v_tenant.email, '');
    SELECT u.raw_app_meta_data->>'provider',
           lower(COALESCE(u.raw_user_meta_data->>'language', u.raw_user_meta_data->>'lang'))
      INTO v_provider, v_lang
      FROM auth.users u JOIN tenant_users tu ON tu.user_id = u.id
     WHERE tu.tenant_id = p_tenant_id AND tu.role = 'owner' LIMIT 1;
    IF v_email LIKE 'deleted\_%@deleted.texacore.local' OR v_email = '' THEN
        SELECT u.email INTO v_email FROM auth.users u JOIN tenant_users tu ON tu.user_id = u.id
         WHERE tu.tenant_id = p_tenant_id AND tu.role = 'owner' LIMIT 1;
        IF v_email IS NULL OR v_email LIKE 'deleted\_%@deleted.texacore.local' THEN v_email := '—'; END IF;
    END IF;
    v_provider_label := CASE lower(COALESCE(v_provider,''))
        WHEN 'google' THEN '🔵 Google' WHEN 'email' THEN '✉️ بريد وكلمة مرور'
        WHEN '' THEN NULL ELSE v_provider END;
    v_lang_label := CASE lower(COALESCE(v_lang,''))
        WHEN 'ar' THEN 'العربية' WHEN 'en' THEN 'English'
        WHEN 'ru' THEN 'Русский' WHEN 'uk' THEN 'Українська' ELSE NULL END;

    -- ═══ 6c. الموقع (حسب IP — قد يكون VPN) + الوقت المحلي ═══
    v_ip_country := COALESCE(NULLIF(v_tenant.registration_country_code,''), NULLIF(v_tenant.last_seen_country,''), '');
    v_ip := COALESCE(NULLIF(v_tenant.registration_ip::text,''), NULLIF(v_tenant.last_seen_ip::text,''), '');
    IF COALESCE(v_tenant.registration_city,'') <> '' OR COALESCE(v_tenant.last_seen_city,'') <> '' THEN
        v_loc := COALESCE(NULLIF(v_tenant.registration_city,''), v_tenant.last_seen_city);
    END IF;
    IF v_ip_country <> '' THEN
        v_loc := NULLIF(trim(both ' ·' FROM concat_ws(' · ', NULLIF(v_loc,''), v_ip_country)), '');
    END IF;
    v_local_time := to_char(now() AT TIME ZONE COALESCE(NULLIF(v_tenant.timezone,''),'UTC'), 'HH24:MI');

    -- ═══ بناء Metadata ═══
    v_notif_metadata := jsonb_build_object(
        'tenant_id', p_tenant_id,
        'tenant_code', v_tenant.code,
        'tenant_name', COALESCE(v_tenant.name, ''),
        'owner_name', COALESCE(v_tenant.owner_name, v_tenant.name, ''),
        'owner_email', v_email,
        'phone', COALESCE(v_phone, ''),
        'country', COALESCE(v_tenant.country, ''),
        'product_name', COALESCE(v_product_name, 'TexaCore'),
        'product_code', COALESCE(v_product_code, 'texacore'),
        'plan_name', COALESCE(v_plan_name, ''),
        'plan_code', COALESCE(v_plan_code, ''),
        'plan_price', COALESCE(v_plan_price, 0),
        'plan_type', COALESCE(v_plan_type, ''),
        'sub_status', COALESCE(v_sub_status, ''),
        'sub_end_date', v_sub_end_date,
        'trial_days', COALESCE(v_trial_days, 0),
        'modules_count', COALESCE(v_modules_count, 0),
        'users_count', COALESCE(v_users_count, 0),
        'companies_count', COALESCE(v_companies_count, 0),
        'registered_at', NOW(),
        'provider', COALESCE(v_provider, ''),
        'language', COALESCE(v_lang, ''),
        'ip_location', COALESCE(v_loc, ''),
        'ip', COALESCE(v_ip, ''),
        'timezone', COALESCE(v_tenant.timezone, '')
    );

    -- ═══ بناء نص الإشعار ═══
    v_notif_body := 
        '👤 ' || COALESCE(v_tenant.owner_name, v_tenant.name, 'غير محدد') || E'\n'
        || '📧 ' || v_email || E'\n'
        || CASE WHEN COALESCE(v_phone, '') != '' 
            THEN '📱 ' || v_phone || E'\n' ELSE '' END
        || CASE WHEN COALESCE(v_tenant.country, '') != '' 
            THEN '🌍 ' || v_tenant.country || E'\n' ELSE '' END
        || '📦 ' || COALESCE(v_plan_name, 'غير محدد')
            || CASE WHEN v_plan_price IS NOT NULL THEN ' ($' || v_plan_price || ')' ELSE '' END || E'\n'
        || '🏗️ ' || COALESCE(v_product_name, 'TexaCore') || E'\n'
        || '📊 ' || COALESCE(v_modules_count::TEXT, '0') || ' موديول';

    -- ═══ إرسال الإشعارات الداخلية ═══
    FOR v_admin_user_id IN 
        SELECT tu.user_id FROM tenant_users tu 
        WHERE tu.tenant_id = v_admin_tenant_id AND tu.role = 'owner'
    LOOP
        -- جدول notifications (يستخدم company_id كـ tenant_id)
        INSERT INTO notifications (
            tenant_id, user_id, title, body,
            type, source_type, source_id, metadata
        ) VALUES (
            v_admin_company_id,  -- ← company_id لأن FK يشير لـ companies
            v_admin_user_id,
            '🆕 مشترك جديد — ' || COALESCE(v_tenant.name, 'بدون اسم')
                || ' | 🆕 New Subscriber — ' || COALESCE(v_tenant.name, 'Unknown'),
            v_notif_body,
            'success',
            'new_subscriber',
            p_tenant_id,
            v_notif_metadata
        );

        -- جدول in_app_notifications
        INSERT INTO in_app_notifications (
            tenant_id, user_id, title, message,
            notification_type, priority, icon, color,
            action_url, action_text
        ) VALUES (
            v_admin_tenant_id,
            v_admin_user_id,
            '🆕 مشترك جديد — ' || COALESCE(v_tenant.name, 'بدون اسم'),
            v_notif_body,
            'new_subscriber',
            'high',
            'user-plus',
            'emerald',
            '/saas/subscribers',
            'عرض المشتركين'
        );
    END LOOP;

    -- ═══ إرسال إشعار تلغرام مفصّل ═══
    SELECT c.integrations->'telegram'->>'bot_token' INTO v_bot_token
    FROM companies c
    WHERE c.tenant_id = v_admin_tenant_id
    AND c.integrations->'telegram'->>'bot_token' IS NOT NULL
    LIMIT 1;

    IF v_bot_token IS NOT NULL THEN
        v_tg_message := E'🆕 <b>مشترك جديد في ' || COALESCE(v_product_name, 'المنصة') || E'</b>\n\n'
            || E'👤 <b>الاسم:</b> ' || COALESCE(v_tenant.owner_name, v_tenant.name, 'غير محدد') || E'\n'
            || E'📧 <b>البريد:</b> ' || v_email || E'\n'
            || CASE WHEN v_provider_label IS NOT NULL THEN E'🔑 <b>طريقة التسجيل:</b> ' || v_provider_label || E'\n' ELSE '' END
            || CASE WHEN v_lang_label IS NOT NULL THEN E'🗣️ <b>اللغة:</b> ' || v_lang_label || E'\n' ELSE '' END
            || CASE WHEN COALESCE(v_phone, '') != ''
                THEN E'📱 <b>الهاتف:</b> ' || v_phone || E'\n' ELSE '' END
            || CASE WHEN COALESCE(v_tenant.country, '') != ''
                THEN E'🌍 <b>الدولة:</b> ' || v_tenant.country || E'\n' ELSE '' END
            || CASE WHEN COALESCE(v_loc, '') <> ''
                THEN E'📍 <b>موقع الاتصال:</b> ' || v_loc || E' <i>(قد يكون VPN)</i>\n' ELSE '' END
            || CASE WHEN COALESCE(v_ip, '') <> ''
                THEN E'🌐 <b>IP:</b> <code>' || v_ip || E'</code>\n' ELSE '' END
            || E'🕐 <b>التوقيت المحلي:</b> ' || v_local_time || ' (' || COALESCE(NULLIF(v_tenant.timezone,''),'UTC') || E')\n'
            || E'🏢 <b>المنشأة:</b> ' || COALESCE(v_tenant.name, 'غير محدد') || E'\n'
            || E'\n'
            || E'━━━━━━━━━━━━━━━━━━━\n'
            || E'📦 <b>الباقة:</b> ' || COALESCE(v_plan_name, 'غير محدد')
                || CASE WHEN v_plan_price IS NOT NULL THEN ' ($' || v_plan_price || '/شهر)' ELSE '' END || E'\n'
            || E'🏗️ <b>المنصة:</b> ' || COALESCE(v_product_name, 'TexaCore') || E'\n'
            || E'💡 <b>النوع:</b> ' || CASE 
                WHEN v_sub_status = 'trial' THEN 'تجريبي (' || COALESCE(v_trial_days::TEXT, '30') || ' يوم) ⏳'
                WHEN v_sub_status = 'active' AND v_plan_type = 'free' THEN 'مجاني 🆓'
                WHEN v_sub_status = 'active' THEN 'مدفوع ✅'
                ELSE COALESCE(v_sub_status, 'غير محدد')
            END || E'\n'
            || CASE WHEN v_sub_end_date IS NOT NULL 
                THEN E'📅 <b>ينتهي:</b> ' || to_char(v_sub_end_date, 'YYYY-MM-DD') || E'\n' ELSE '' END
            || E'📊 <b>الموديولات:</b> ' || COALESCE(v_modules_count::TEXT, '0') || ' موديول' || E'\n'
            || E'👥 <b>المستخدمين:</b> ' || COALESCE(v_users_count::TEXT, '0') || E'\n'
            || E'🏢 <b>الشركات:</b> ' || COALESCE(v_companies_count::TEXT, '0') || E'\n'
            || E'\n'
            || E'━━━━━━━━━━━━━━━━━━━\n'
            || E'🔗 <b>الكود:</b> <code>' || COALESCE(v_tenant.code, '') || E'</code>\n'
            || E'📅 <b>التاريخ:</b> ' || to_char(NOW(), 'YYYY-MM-DD HH24:MI') || E'\n'
            || CASE WHEN regexp_replace(COALESCE(v_phone,''),'[^0-9]','','g') <> ''
                THEN E'💬 <a href="https://wa.me/' || regexp_replace(COALESCE(v_phone,''),'[^0-9]','','g') || E'">مراسلة عبر واتساب</a>\n' ELSE '' END
            || E'🔗 <a href="' || v_admin_url || E'">فتح لوحة المشتركين</a>\n\n'
            || E'🔔 <i>TexaCore SaaS Platform</i>';

        FOR v_conn IN
            SELECT tc.telegram_chat_id
            FROM telegram_connections tc
            WHERE tc.company_id IN (SELECT id FROM companies WHERE tenant_id = v_admin_tenant_id)
            AND tc.is_active = true
            AND (tc.notification_role = 'tenant_owner' OR tc.notification_role = 'owner')
        LOOP
            v_tg_url := 'https://api.telegram.org/bot' || v_bot_token || '/sendMessage';
            PERFORM net.http_post(
                url := v_tg_url,
                headers := '{"Content-Type": "application/json"}'::jsonb,
                body := jsonb_build_object(
                    'chat_id', v_conn.telegram_chat_id::bigint,
                    'text', v_tg_message,
                    'parse_mode', 'HTML'
                ),
                timeout_milliseconds := 20000
            );
        END LOOP;
    END IF;
END;
$_$;


--
-- Name: session_heartbeat(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.session_heartbeat(p_session_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.active_sessions SET last_heartbeat = NOW()
  WHERE session_token = p_session_token;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_expired'); END IF;
  RETURN jsonb_build_object('success', true);
END;
$$;


