--
-- Name: set_pending_action_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.set_pending_action_status(p_id uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_company uuid; v_n int;
BEGIN
    IF p_status NOT IN ('confirmed','rejected') THEN
        RETURN jsonb_build_object('ok', false, 'message', 'حالة غير مسموحة');
    END IF;
    SELECT company_id INTO v_company FROM pending_actions WHERE id = p_id;
    IF v_company IS NULL THEN RETURN jsonb_build_object('ok', false, 'message', 'المسودة غير موجودة'); END IF;
    PERFORM assert_can_access_company(v_company);
    UPDATE pending_actions
       SET status = p_status, confirmed_at = now(), confirmed_via = 'web', confirmed_by = auth.uid()
     WHERE id = p_id AND status = 'pending';
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN jsonb_build_object('ok', v_n > 0);
END $$;


--
-- Name: set_primary_language(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.set_primary_language(p_tenant_id uuid, p_language_code character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- التحقق من أن اللغة مفعلة
    IF NOT EXISTS (
        SELECT 1 FROM tenant_languages
        WHERE tenant_id = p_tenant_id
        AND language_code = p_language_code
        AND is_enabled = true
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Language not enabled'
        );
    END IF;
    
    -- إلغاء primary من كل اللغات
    UPDATE tenant_languages
    SET is_primary = false
    WHERE tenant_id = p_tenant_id;
    
    -- تعيين اللغة الجديدة كـ primary
    UPDATE tenant_languages
    SET is_primary = true
    WHERE tenant_id = p_tenant_id
    AND language_code = p_language_code;
    
    -- تسجيل في audit log
    PERFORM log_audit(
        'set_primary_language',
        'tenant_languages',
        p_tenant_id,
        p_language_code,
        NULL,
        jsonb_build_object('language_code', p_language_code)
    );
    
    RETURN jsonb_build_object(
        'success', true,
        'tenant_id', p_tenant_id,
        'primary_language', p_language_code
    );
END;
$$;


--
-- Name: set_primary_product_image(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.set_primary_product_image(p_tenant_id uuid, p_product_id uuid, p_image_url text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_images JSONB;
    v_updated_images JSONB;
BEGIN
    -- 1. الحصول على الصور الحالية
    SELECT COALESCE(images, '[]'::jsonb)
    INTO v_current_images
    FROM products
    WHERE id = p_product_id AND tenant_id = p_tenant_id;
    
    -- 2. تحديث جميع الصور
    v_updated_images := (
        SELECT jsonb_agg(
            CASE 
                WHEN img->>'url' = p_image_url THEN
                    jsonb_set(img, '{is_primary}', 'true'::jsonb)
                ELSE
                    jsonb_set(img, '{is_primary}', 'false'::jsonb)
            END
        )
        FROM jsonb_array_elements(v_current_images) AS img
    );
    
    -- 3. تحديث المنتج
    UPDATE products
    SET images = v_updated_images,
        updated_at = NOW()
    WHERE id = p_product_id AND tenant_id = p_tenant_id;
    
    RETURN FOUND;
END;
$$;


--
-- Name: set_published_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.set_published_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.is_published = true AND (OLD.is_published = false OR OLD.is_published IS NULL) THEN
        NEW.published_at = now();
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: set_roll_seq(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.set_roll_seq() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- 1. Auto-assign roll_seq if not provided
    IF NEW.roll_seq IS NULL THEN
        SELECT COALESCE(MAX(roll_seq), 0) + 1
        INTO NEW.roll_seq
        FROM fabric_rolls
        WHERE company_id = NEW.company_id;
    END IF;

    -- 2. Auto-generate smart roll_number from roll_code + roll_seq
    --    when roll_number is temporary (TEMP-xxx, JIT-xxx, ROLL-xxx)
    --    🔑 This handles offline-created rolls that sync later
    IF NEW.roll_code IS NOT NULL 
       AND NEW.roll_code != '' 
       AND (NEW.roll_number LIKE 'TEMP-%' 
            OR NEW.roll_number LIKE 'JIT-%' 
            OR NEW.roll_number LIKE 'ROLL-%') THEN
        NEW.roll_number := NEW.roll_code || '-' || LPAD(NEW.roll_seq::TEXT, 3, '0');
    END IF;

    RETURN NEW;
END;
$$;


