--
-- Name: set_user_ban(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.set_user_ban(p_user_id uuid, p_banned boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT is_super_admin(auth.uid()) THEN
        RETURN jsonb_build_object('success', false, 'error', 'غير مصرح: Super Admin فقط');
    END IF;
    -- لا تحظر نفسك
    IF p_user_id = auth.uid() THEN
        RETURN jsonb_build_object('success', false, 'error', '⛔ لا يمكنك حظر حسابك الخاص');
    END IF;
    UPDATE auth.users
       SET banned_until = CASE WHEN p_banned THEN (now() + interval '100 years') ELSE NULL END
     WHERE id = p_user_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'المستخدم غير موجود');
    END IF;
    RETURN jsonb_build_object('success', true, 'banned', p_banned);
END;
$$;


--
-- Name: setup_chart_templates_for_tenant(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.setup_chart_templates_for_tenant(p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    INSERT INTO chart_templates (tenant_id, template_code, template_name_ar, template_name_en, chart_type, include_demo_data, description_ar, description_en)
    VALUES (p_tenant_id, 'SIMPLE', 'الشجرة القياسية', 'Simple Chart', 'simple', false,
            'شجرة حسابات مبسطة (~52 حساب) بترقيم موحد', 'Simple chart with unified numbering (~52 accounts)')
    ON CONFLICT DO NOTHING;

    INSERT INTO chart_templates (tenant_id, template_code, template_name_ar, template_name_en, chart_type, include_demo_data, description_ar, description_en)
    VALUES (p_tenant_id, 'EXTENDED', 'الشجرة الموسعة', 'Extended Chart', 'extended', false,
            'شجرة حسابات كاملة (~82 حساب) للشركات التجارية', 'Full chart for commercial companies (~82 accounts)')
    ON CONFLICT DO NOTHING;

    RAISE NOTICE '✅ تم إعداد القوالب V5.1 (Simple + Extended) للمستأجر %', p_tenant_id;
END;
$$;


--
-- Name: setup_company_defaults(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.setup_company_defaults(p_company_id uuid, p_local_currency character varying DEFAULT NULL::character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_base_currency varchar;
    v_local_currency varchar;
    v_trading_currency varchar;
    v_country_code varchar;
    v_fiscal_start int := 1;
    v_branch_id uuid;
    v_warehouse_id uuid;
    v_user_id uuid;
    v_sg_id uuid;
BEGIN
    SELECT tenant_id, COALESCE(default_currency, 'USD'), COALESCE(country_code, 'SA')
    INTO v_tenant_id, v_base_currency, v_country_code
    FROM companies WHERE id = p_company_id;

    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION 'Company not found: %', p_company_id;
    END IF;

    v_local_currency := COALESCE(p_local_currency, v_base_currency);
    v_trading_currency := v_base_currency;

    IF v_country_code IN ('SA', 'AE', 'BH', 'KW', 'OM', 'QA') THEN v_fiscal_start := 1;
    ELSIF v_country_code IN ('GB', 'IN') THEN v_fiscal_start := 4;
    ELSE v_fiscal_start := 1;
    END IF;

    -- ═══════ 1. Accounting Settings ═══════
    INSERT INTO company_accounting_settings (company_id) VALUES (p_company_id)
    ON CONFLICT (company_id) DO NOTHING;

    UPDATE company_accounting_settings SET
        default_cash_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '101' LIMIT 1),
        default_bank_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '102' LIMIT 1),
        default_revenue_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '411' LIMIT 1),
        default_expense_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '511' LIMIT 1),
        default_inventory_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '141' LIMIT 1),
        default_cogs_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '511' LIMIT 1),
        default_receivable_account_id = NULL,
        default_payable_account_id = NULL,
        default_sales_discount_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '594' LIMIT 1),
        default_purchase_discount_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '412' LIMIT 1),
        default_customer_advance_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '215' LIMIT 1),
        default_supplier_advance_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '118' LIMIT 1),
        default_retained_earnings_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '32' LIMIT 1),
        default_depreciation_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '597' LIMIT 1),
        default_rounding_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '596' LIMIT 1),
        default_tax_input_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '117' LIMIT 1),
        default_tax_output_account_id = (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '214' LIMIT 1),
        base_currency = v_local_currency,
        supported_currencies = CASE
            WHEN v_local_currency != v_trading_currency THEN ARRAY[v_local_currency, v_trading_currency]
            ELSE ARRAY[v_local_currency]
        END,
        default_sales_currency = v_trading_currency,
        default_purchase_currency = v_trading_currency,
        updated_at = NOW()
    WHERE company_id = p_company_id;

    -- ═══════ 2. Exchange Settings ═══════
    INSERT INTO exchange_settings (company_id, tenant_id,
        currency_gain_account_id, currency_loss_account_id, commission_revenue_account_id,
        remittance_receivable_account_id, agent_payable_account_id, partner_payable_account_id,
        auto_post_transactions, auto_post_remittances)
    VALUES (p_company_id, v_tenant_id,
        (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '422' LIMIT 1),
        (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '591' LIMIT 1),
        (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '431' LIMIT 1),
        (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '131' LIMIT 1),
        (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '232' LIMIT 1),
        (SELECT id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '233' LIMIT 1),
        false, false)
    ON CONFLICT (tenant_id, company_id) DO NOTHING;

    -- ═══════ 3. Fiscal Year ═══════
    INSERT INTO fiscal_years (company_id, tenant_id, name, code, start_date, end_date, is_current, is_closed)
    VALUES (p_company_id, v_tenant_id,
        EXTRACT(YEAR FROM NOW())::text,
        'FY' || EXTRACT(YEAR FROM NOW())::text,
        MAKE_DATE(EXTRACT(YEAR FROM NOW())::int, v_fiscal_start, 1),
        MAKE_DATE(EXTRACT(YEAR FROM NOW())::int + 1, v_fiscal_start, 1) - INTERVAL '1 day',
        true, false)
    ON CONFLICT DO NOTHING;

    -- ═══════ 4. Default Branch ═══════
    IF NOT EXISTS (SELECT 1 FROM branches WHERE company_id = p_company_id) THEN
        INSERT INTO branches (company_id, tenant_id, code, name, name_ar, name_en, is_main, is_active, branch_type)
        VALUES (p_company_id, v_tenant_id, 'HQ', 'الفرع الرئيسي', 'الفرع الرئيسي', 'Main Branch', true, true, 'regular')
        RETURNING id INTO v_branch_id;
    ELSE
        SELECT id INTO v_branch_id FROM branches WHERE company_id = p_company_id AND is_main = true LIMIT 1;
    END IF;

    -- ═══════ 5. Default Warehouse ═══════
    IF NOT EXISTS (SELECT 1 FROM warehouses WHERE company_id = p_company_id) THEN
        INSERT INTO warehouses (company_id, tenant_id, branch_id, code, name, name_ar, name_en, warehouse_type, is_active)
        VALUES (p_company_id, v_tenant_id, v_branch_id, 'WH-01', 'المستودع الرئيسي', 'المستودع الرئيسي', 'Main Warehouse', 'regular', true)
        RETURNING id INTO v_warehouse_id;

        IF v_branch_id IS NOT NULL AND v_warehouse_id IS NOT NULL THEN
            UPDATE branches SET default_warehouse_id = v_warehouse_id WHERE id = v_branch_id;
        END IF;
    END IF;

    -- ═══════ 6. Link user to branch ═══════
    IF v_branch_id IS NOT NULL THEN
        UPDATE user_profiles SET branch_id = v_branch_id 
        WHERE company_id = p_company_id AND branch_id IS NULL;
    END IF;

    -- ═══════ 7. user_module_permissions ═══════
    SELECT up.id INTO v_user_id FROM user_profiles up 
    WHERE up.company_id = p_company_id AND up.tenant_id = v_tenant_id LIMIT 1;

    IF v_user_id IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM user_module_permissions WHERE user_id = v_user_id AND tenant_id = v_tenant_id) THEN
            INSERT INTO user_module_permissions (user_id, tenant_id, company_id, module_code,
                can_view, can_create, can_edit, can_delete, can_export, can_import, can_approve, can_manage_settings,
                granted_by, is_active)
            SELECT v_user_id, v_tenant_id, p_company_id, tm.module_code,
                true, true, true, true, true, true, true, true,
                v_user_id, true
            FROM tenant_modules tm
            WHERE tm.tenant_id = v_tenant_id AND tm.is_active = true AND tm.is_enabled = true
            ON CONFLICT DO NOTHING;
        END IF;
    END IF;

    -- ═══════ 8. Status Groups + Custom Statuses ═══════
    IF NOT EXISTS (SELECT 1 FROM status_groups WHERE tenant_id = v_tenant_id) THEN
        -- Sales Quotation
        INSERT INTO status_groups (tenant_id, doc_type, code, name_ar, name_en, sort_order, is_system)
        VALUES (v_tenant_id, 'sales_quotation', 'sales_quotation', 'عرض السعر', 'Sales Quotation', 1, false)
        RETURNING id INTO v_sg_id;
        INSERT INTO custom_statuses (tenant_id, group_id, doc_type, code, name_ar, name_en, color, sort_order, is_initial, is_final) VALUES
        (v_tenant_id, v_sg_id, 'sales_quotation', 'draft', 'مسودة', 'Draft', 'gray', 0, true, false),
        (v_tenant_id, v_sg_id, 'sales_quotation', 'sent', 'مُرسل', 'Sent', 'blue', 1, false, false),
        (v_tenant_id, v_sg_id, 'sales_quotation', 'approved', 'مقبول', 'Approved', 'green', 2, false, false),
        (v_tenant_id, v_sg_id, 'sales_quotation', 'rejected', 'مرفوض', 'Rejected', 'red', 3, false, true),
        (v_tenant_id, v_sg_id, 'sales_quotation', 'expired', 'منتهي الصلاحية', 'Expired', 'orange', 4, false, true);

        -- Sales Reservation
        INSERT INTO status_groups (tenant_id, doc_type, code, name_ar, name_en, sort_order, is_system)
        VALUES (v_tenant_id, 'sales_reservation', 'sales_reservation', 'حجز البضائع', 'Sales Reservation', 2, false)
        RETURNING id INTO v_sg_id;
        INSERT INTO custom_statuses (tenant_id, group_id, doc_type, code, name_ar, name_en, color, sort_order, is_initial, is_final) VALUES
        (v_tenant_id, v_sg_id, 'sales_reservation', 'draft', 'مسودة', 'Draft', 'gray', 0, true, false),
        (v_tenant_id, v_sg_id, 'sales_reservation', 'confirmed', 'مؤكد', 'Confirmed', 'blue', 1, false, false),
        (v_tenant_id, v_sg_id, 'sales_reservation', 'released', 'مُفرج عنه', 'Released', 'green', 2, false, false),
        (v_tenant_id, v_sg_id, 'sales_reservation', 'cancelled', 'ملغي', 'Cancelled', 'red', 3, false, true);

        -- Sales Invoice
        INSERT INTO status_groups (tenant_id, doc_type, code, name_ar, name_en, sort_order, is_system)
        VALUES (v_tenant_id, 'sales_invoice', 'sales_invoice', 'فاتورة المبيعات', 'Sales Invoice', 3, false)
        RETURNING id INTO v_sg_id;
        INSERT INTO custom_statuses (tenant_id, group_id, doc_type, code, name_ar, name_en, color, sort_order, is_initial, is_final) VALUES
        (v_tenant_id, v_sg_id, 'sales_invoice', 'draft', 'مسودة', 'Draft', 'gray', 0, true, false),
        (v_tenant_id, v_sg_id, 'sales_invoice', 'confirmed', 'مؤكدة', 'Confirmed', 'blue', 1, false, false),
        (v_tenant_id, v_sg_id, 'sales_invoice', 'paid', 'مدفوعة', 'Paid', 'green', 2, false, true),
        (v_tenant_id, v_sg_id, 'sales_invoice', 'cancelled', 'ملغاة', 'Cancelled', 'red', 3, false, true);

        -- Purchase Order
        INSERT INTO status_groups (tenant_id, doc_type, code, name_ar, name_en, sort_order, is_system)
        VALUES (v_tenant_id, 'purchase_order', 'purchase_order', 'أمر الشراء', 'Purchase Order', 4, false)
        RETURNING id INTO v_sg_id;
        INSERT INTO custom_statuses (tenant_id, group_id, doc_type, code, name_ar, name_en, color, sort_order, is_initial, is_final) VALUES
        (v_tenant_id, v_sg_id, 'purchase_order', 'draft', 'مسودة', 'Draft', 'gray', 0, true, false),
        (v_tenant_id, v_sg_id, 'purchase_order', 'sent', 'مُرسل', 'Sent', 'blue', 1, false, false),
        (v_tenant_id, v_sg_id, 'purchase_order', 'confirmed', 'مؤكد', 'Confirmed', 'indigo', 2, false, false),
        (v_tenant_id, v_sg_id, 'purchase_order', 'received', 'مستلم', 'Received', 'green', 3, false, true),
        (v_tenant_id, v_sg_id, 'purchase_order', 'cancelled', 'ملغي', 'Cancelled', 'red', 4, false, true);
    END IF;

END;
$$;


--
-- Name: setup_exchange_accounts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.setup_exchange_accounts(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
    v_base_currency VARCHAR(10);
    v_asset_type UUID;
    v_liability_type UUID;
    v_revenue_type UUID;
    v_expense_type UUID;
    v_assets_id UUID;
    v_liabilities_id UUID;
    v_revenue_id UUID;
    v_expenses_id UUID;
    v_parent_id UUID;
    v_created_count INT := 0;
    v_deleted_count INT := 0;
BEGIN
    SELECT tenant_id INTO v_tenant_id FROM companies WHERE id = p_company_id;
    IF v_tenant_id IS NULL THEN
        RETURN jsonb_build_object('error', 'Company not found');
    END IF;

    -- العملة الأساسية
    SELECT COALESCE(cas.base_currency, c.default_currency, 'USD')
    INTO v_base_currency
    FROM companies c LEFT JOIN company_accounting_settings cas ON cas.company_id = c.id
    WHERE c.id = p_company_id;
    IF v_base_currency IS NULL THEN v_base_currency := 'USD'; END IF;

    -- ═══ 1. حذف حسابات EX-xx القديمة ═══
    DELETE FROM chart_of_accounts
    WHERE company_id = p_company_id
      AND account_code LIKE 'EX-%';
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

    -- Account types
    SELECT id INTO v_asset_type FROM account_types WHERE code = 'CURRENT_ASSET';
    IF v_asset_type IS NULL THEN SELECT id INTO v_asset_type FROM account_types WHERE code = 'ASSET'; END IF;
    SELECT id INTO v_liability_type FROM account_types WHERE code = 'CURRENT_LIABILITY';
    IF v_liability_type IS NULL THEN SELECT id INTO v_liability_type FROM account_types WHERE code = 'LIABILITY'; END IF;
    SELECT id INTO v_revenue_type FROM account_types WHERE code = 'REVENUE';
    SELECT id INTO v_expense_type FROM account_types WHERE code = 'EXPENSE';

    -- الحسابات الجذرية
    SELECT id INTO v_assets_id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '1';
    SELECT id INTO v_liabilities_id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '2';
    SELECT id INTO v_revenue_id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '4';
    SELECT id INTO v_expenses_id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '5';

    -- ═══ 2. إنشاء 13 ذمم الصرافة (إذا لم تكن موجودة) ═══
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '13') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '13', 'ذمم الصرافة والحوالات', 'Exchange & Remittance Receivables', v_asset_type, v_assets_id, false, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;
    SELECT id INTO v_parent_id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '13';

    -- فروع 13
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '131') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '131', 'ذمم حوالات صادرة', 'Outgoing Remittance Receivables', v_asset_type, v_parent_id, true, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '132') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '132', 'ذمم حوالات واردة', 'Incoming Remittance Receivables', v_asset_type, v_parent_id, true, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '133') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '133', 'ذمم رصائد الصرافة', 'Exchange Balance Receivables', v_asset_type, v_parent_id, true, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;

    -- 134 مجموعة الوكلاء
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '134') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '134', 'حسابات الوكلاء الجارية', 'Agent Current Accounts', v_asset_type, v_parent_id, false, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;

    -- 135 مجموعة الشركاء
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '135') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '135', 'حسابات الشركاء الجارية', 'Partner Current Accounts', v_asset_type, v_parent_id, false, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;

    -- ═══ 3. إنشاء 23 التزامات الصرافة ═══
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '23') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '23', 'التزامات الصرافة والحوالات', 'Exchange & Remittance Liabilities', v_liability_type, v_liabilities_id, false, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;
    SELECT id INTO v_parent_id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '23';

    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '231') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '231', 'حوالات مستحقة للتسليم', 'Remittances Payable', v_liability_type, v_parent_id, true, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '232') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '232', 'ذمم الوكلاء الدائنة', 'Agent Payables', v_liability_type, v_parent_id, true, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '233') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '233', 'ذمم الشركاء الدائنة', 'Partner Payables', v_liability_type, v_parent_id, true, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;

    -- ═══ 4. إنشاء 43 إيرادات الصرافة ═══
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '43') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '43', 'إيرادات الصرافة والحوالات', 'Exchange & Remittance Revenue', v_revenue_type, v_revenue_id, false, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;
    SELECT id INTO v_parent_id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '43';

    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '431') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '431', 'إيرادات عمولات صرف', 'Exchange Commission Income', v_revenue_type, v_parent_id, true, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '432') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '432', 'إيرادات عمولات حوالات', 'Remittance Commission Income', v_revenue_type, v_parent_id, true, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '433') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '433', 'أرباح فروقات عملات - صرافة', 'FX Gains - Exchange', v_revenue_type, v_parent_id, true, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;

    -- ═══ 5. إنشاء 54 مصاريف الصرافة ═══
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '54') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '54', 'مصاريف الصرافة', 'Exchange Expenses', v_expense_type, v_expenses_id, false, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;
    SELECT id INTO v_parent_id FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '54';

    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '541') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '541', 'عمولات وكلاء', 'Agent Commissions', v_expense_type, v_parent_id, true, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '542') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '542', 'عمولات شركاء', 'Partner Commissions', v_expense_type, v_parent_id, true, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM chart_of_accounts WHERE company_id = p_company_id AND account_code = '543') THEN
        INSERT INTO chart_of_accounts (tenant_id, company_id, account_code, name_ar, name_en, account_type_id, parent_id, is_detail, is_active, currency)
        VALUES (v_tenant_id, p_company_id, '543', 'خسائر فروقات عملات', 'FX Losses - Exchange', v_expense_type, v_parent_id, true, true, v_base_currency);
        v_created_count := v_created_count + 1;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'created', v_created_count,
        'deleted_ex', v_deleted_count,
        'message', 'V7 exchange accounts setup complete'
    );
END;
$$;


--
-- Name: FUNCTION setup_exchange_accounts(p_company_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.setup_exchange_accounts(p_company_id uuid) IS 'V7 — إعداد حسابات الصرافة (13, 23, 43, 54) + حذف EX-xx القديمة + مجموعات الوكلاء (134) والشركاء (135)';


--
-- Name: setup_super_user_by_email(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.setup_super_user_by_email(p_user_email character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_role_id UUID;
    v_result JSONB;
BEGIN
    -- البحث عن المستخدم بالبريد الإلكتروني
    SELECT id INTO v_user_id
    FROM auth.users
    WHERE email = p_user_email
    LIMIT 1;
    
    IF v_user_id IS NULL THEN
        SELECT jsonb_build_object(
            'success', false,
            'error', 'المستخدم غير موجود في Auth. يرجى إنشاء المستخدم أولاً من Supabase Dashboard',
            'email', p_user_email
        ) INTO v_result;
        RETURN v_result;
    END IF;
    
    -- الحصول على Super Admin Role
    SELECT id INTO v_role_id
    FROM roles
    WHERE code = 'super_admin' AND tenant_id IS NULL
    LIMIT 1;
    
    IF v_role_id IS NULL THEN
        SELECT jsonb_build_object(
            'success', false,
            'error', 'Super Admin Role غير موجود. يرجى تطبيق STEP_12 أولاً'
        ) INTO v_result;
        RETURN v_result;
    END IF;
    
    -- ربط المستخدم بالـ Role (استخدام DO UPDATE بدلاً من ON CONFLICT)
    INSERT INTO user_roles (user_id, role_id, is_active)
    VALUES (v_user_id, v_role_id, true)
    ON CONFLICT (user_id, role_id) 
    DO UPDATE SET is_active = true;
    
    -- إرجاع النتيجة
    SELECT jsonb_build_object(
        'success', true,
        'user_id', v_user_id,
        'email', p_user_email,
        'role', 'super_admin',
        'message', 'تم تعيين Super Admin بنجاح'
    ) INTO v_result;
    
    RETURN v_result;
END;
$$;


--
-- Name: setup_support_user(character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.setup_support_user(p_user_email character varying, p_support_level character varying DEFAULT 'support'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_role_id UUID;
    v_role_code VARCHAR(50);
    v_result JSONB;
BEGIN
    -- تحديد Role Code
    IF p_support_level = 'senior' THEN
        v_role_code := 'support_senior';
    ELSE
        v_role_code := 'support';
    END IF;
    
    -- البحث عن المستخدم
    SELECT id INTO v_user_id
    FROM auth.users
    WHERE email = p_user_email
    LIMIT 1;
    
    IF v_user_id IS NULL THEN
        SELECT jsonb_build_object(
            'success', false,
            'error', 'المستخدم غير موجود في Auth',
            'email', p_user_email
        ) INTO v_result;
        RETURN v_result;
    END IF;
    
    -- الحصول على Support Role
    SELECT id INTO v_role_id
    FROM roles
    WHERE code = v_role_code AND tenant_id IS NULL
    LIMIT 1;
    
    IF v_role_id IS NULL THEN
        SELECT jsonb_build_object(
            'success', false,
            'error', 'Support Role غير موجود'
        ) INTO v_result;
        RETURN v_result;
    END IF;
    
    -- ربط المستخدم بالـ Role
    INSERT INTO user_roles (user_id, role_id, is_active)
    VALUES (v_user_id, v_role_id, true)
    ON CONFLICT (user_id, role_id) 
    DO UPDATE SET is_active = true;
    
    -- إرجاع النتيجة
    SELECT jsonb_build_object(
        'success', true,
        'user_id', v_user_id,
        'email', p_user_email,
        'role', v_role_code,
        'message', 'تم تعيين Support User بنجاح'
    ) INTO v_result;
    
    RETURN v_result;
END;
$$;


--
-- Name: start_login_session(uuid, uuid, character varying, character varying, character varying, character varying, text, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.start_login_session(p_tenant_id uuid, p_user_id uuid DEFAULT NULL::uuid, p_user_email character varying DEFAULT NULL::character varying, p_ip character varying DEFAULT NULL::character varying, p_country character varying DEFAULT NULL::character varying, p_city character varying DEFAULT NULL::character varying, p_user_agent text DEFAULT NULL::text, p_browser character varying DEFAULT NULL::character varying, p_os character varying DEFAULT NULL::character varying) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_session_id UUID;
    v_existing_id UUID;
BEGIN
    -- Close any stale active sessions for this tenant (older than 10 min without heartbeat)
    UPDATE tenant_login_sessions
    SET is_active = false,
        session_end = last_heartbeat
    WHERE tenant_id = p_tenant_id
      AND is_active = true
      AND last_heartbeat < NOW() - INTERVAL '10 minutes';

    -- Check if there's an active session from same IP + browser (same tab/session)
    SELECT id INTO v_existing_id
    FROM tenant_login_sessions
    WHERE tenant_id = p_tenant_id
      AND is_active = true
      AND ip = p_ip
      AND browser = p_browser
      AND last_heartbeat > NOW() - INTERVAL '5 minutes'
    ORDER BY session_start DESC
    LIMIT 1;

    IF v_existing_id IS NOT NULL THEN
        -- Resume existing session — just update heartbeat
        UPDATE tenant_login_sessions
        SET last_heartbeat = NOW(),
            country = COALESCE(p_country, country),
            city = COALESCE(p_city, city)
        WHERE id = v_existing_id;
        RETURN v_existing_id;
    END IF;

    -- Create new session
    INSERT INTO tenant_login_sessions (
        tenant_id, user_id, user_email,
        ip, country, city,
        user_agent, browser, os
    ) VALUES (
        p_tenant_id, p_user_id, p_user_email,
        p_ip, p_country, p_city,
        p_user_agent, p_browser, p_os
    ) RETURNING id INTO v_session_id;

    RETURN v_session_id;
END;
$$;


--
-- Name: suspend_tenant(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.suspend_tenant(p_tenant_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    UPDATE tenants
    SET status = 'suspended',
        suspended_at = NOW(),
        suspended_reason = p_reason
    WHERE id = p_tenant_id;
    
    -- تسجيل الحدث
    INSERT INTO saas_events (tenant_id, event_type, event_data, actor_type)
    VALUES (p_tenant_id, 'tenant_suspended', jsonb_build_object('reason', p_reason), 'admin');
    
    RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: switch_user_company(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.switch_user_company(p_user_id uuid, p_new_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_company_tenant_id UUID;
    v_company_name VARCHAR;
BEGIN
    -- التحقق من المستخدم
    IF p_user_id IS NULL OR p_user_id != auth.uid() THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'غير مصرح'
        );
    END IF;
    
    -- الحصول على tenant_id للمستخدم
    SELECT tenant_id INTO v_tenant_id
    FROM user_profiles
    WHERE id = p_user_id;
    
    IF v_tenant_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'المستخدم غير موجود'
        );
    END IF;
    
    -- التحقق من أن الشركة الجديدة تابعة لنفس الـ tenant
    SELECT tenant_id, name INTO v_company_tenant_id, v_company_name
    FROM companies
    WHERE id = p_new_company_id;
    
    IF v_company_tenant_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'الشركة غير موجودة'
        );
    END IF;
    
    IF v_company_tenant_id != v_tenant_id THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'الشركة غير تابعة لحسابك'
        );
    END IF;
    
    -- تحديث company_id في user_profiles
    UPDATE user_profiles
    SET 
        company_id = p_new_company_id,
        updated_at = NOW()
    WHERE id = p_user_id;
    
    RAISE NOTICE '✅ تم تبديل الشركة للمستخدم % إلى %', p_user_id, v_company_name;
    
    RETURN jsonb_build_object(
        'success', true,
        'company_id', p_new_company_id,
        'company_name', v_company_name,
        'message', 'تم تبديل الشركة بنجاح'
    );
    
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$$;


--
-- Name: sync_container_info_to_transaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_container_info_to_transaction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            -- عند تعيين أو تغيير container_id → أجلب container_number + status
            IF NEW.container_id IS NOT NULL AND (
                OLD.container_id IS DISTINCT FROM NEW.container_id
            ) THEN
                SELECT c.container_number, c.status
                INTO NEW.container_number, NEW.container_status
                FROM containers c
                WHERE c.id = NEW.container_id;
            END IF;

            -- عند إزالة container_id → أفرّغ الحقول
            IF NEW.container_id IS NULL AND OLD.container_id IS NOT NULL THEN
                NEW.container_number := NULL;
                NEW.container_status := NULL;
            END IF;

            RETURN NEW;
        END;
        $$;


--
-- Name: sync_container_status_to_transactions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_container_status_to_transactions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            -- عند تغيير status أو container_number في containers → حدّث كل الفواتير المربوطة
            IF OLD.status IS DISTINCT FROM NEW.status 
               OR OLD.container_number IS DISTINCT FROM NEW.container_number THEN
                UPDATE purchase_transactions
                SET container_status = NEW.status,
                    container_number = NEW.container_number
                WHERE container_id = NEW.id;
            END IF;
            RETURN NEW;
        END;
        $$;


--
-- Name: sync_ecom_fulfilled_from_delivery(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_ecom_fulfilled_from_delivery() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ecom_order_id uuid;
  v_ecom_item_id uuid;
  v_total_delivered numeric;
BEGIN
  -- فقط إذا تغيرت الكمية المسلّمة
  IF TG_OP = 'UPDATE' AND NEW.quantity_delivered = OLD.quantity_delivered THEN
    RETURN NEW;
  END IF;

  -- البحث عن الطلب الإلكتروني عبر: DN → SO → ecommerce_orders.sales_order_id
  SELECT eo.id INTO v_ecom_order_id
  FROM ecommerce_orders eo
  JOIN delivery_notes dn ON dn.sales_order_id = eo.sales_order_id
  WHERE dn.id = NEW.delivery_note_id
  LIMIT 1;

  IF v_ecom_order_id IS NULL THEN
    -- ليس مرتبطاً بطلب إلكتروني — لا نفعل شيئاً
    RETURN NEW;
  END IF;

  -- البحث عن بند الطلب الإلكتروني المطابق
  SELECT eoi.id INTO v_ecom_item_id
  FROM ecommerce_order_items eoi
  WHERE eoi.order_id = v_ecom_order_id
    AND (
      (NEW.material_id IS NOT NULL AND eoi.material_id = NEW.material_id)
      OR (NEW.product_id IS NOT NULL AND eoi.product_id = NEW.product_id)
    )
  LIMIT 1;

  IF v_ecom_item_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- تجميع الكمية المسلّمة من كل DN items لنفس المادة
  SELECT COALESCE(SUM(dni.quantity_delivered), 0) INTO v_total_delivered
  FROM delivery_note_items dni
  JOIN delivery_notes dn ON dn.id = dni.delivery_note_id
  WHERE dn.sales_order_id = (
    SELECT sales_order_id FROM ecommerce_orders WHERE id = v_ecom_order_id
  )
  AND (
    (NEW.material_id IS NOT NULL AND dni.material_id = NEW.material_id)
    OR (NEW.product_id IS NOT NULL AND dni.product_id = NEW.product_id)
  );

  -- تحديث الكمية الفعلية في بند الطلب الإلكتروني
  UPDATE ecommerce_order_items
  SET fulfilled_quantity = v_total_delivered
  WHERE id = v_ecom_item_id;

  -- فحص هل كل البنود مكتملة → تحديث حالة الطلب
  IF NOT EXISTS (
    SELECT 1 FROM ecommerce_order_items
    WHERE order_id = v_ecom_order_id
      AND (fulfilled_quantity IS NULL OR fulfilled_quantity = 0)
  ) THEN
    UPDATE ecommerce_orders
    SET fulfilled_quantity_entered = true,
        updated_at = NOW()
    WHERE id = v_ecom_order_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: sync_ecom_fulfilled_from_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_ecom_fulfilled_from_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ecom_order_id uuid;
  v_supplier_id uuid;
  v_ecom_supplier_id uuid;
  v_total_accepted numeric;
BEGIN
  -- فقط إذا تغيرت الكمية المقبولة
  IF TG_OP = 'UPDATE' AND NEW.quantity_accepted = OLD.quantity_accepted THEN
    RETURN NEW;
  END IF;

  -- جلب معلومات إذن الاستلام
  SELECT pr.supplier_id INTO v_supplier_id
  FROM purchase_receipts pr
  WHERE pr.id = NEW.receipt_id;

  IF v_supplier_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- البحث عن الطلب الإلكتروني عبر ecommerce_order_suppliers
  SELECT eos.id, eos.order_id INTO v_ecom_supplier_id, v_ecom_order_id
  FROM ecommerce_order_suppliers eos
  WHERE eos.supplier_id = v_supplier_id
    AND eos.purchase_order_id = (
      SELECT order_id FROM purchase_receipts WHERE id = NEW.receipt_id
    )
  LIMIT 1;

  IF v_ecom_supplier_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- تجميع الكمية المقبولة
  SELECT COALESCE(SUM(pri.quantity_accepted), 0) INTO v_total_accepted
  FROM purchase_receipt_items pri
  WHERE pri.receipt_id = NEW.receipt_id
    AND (
      (NEW.material_id IS NOT NULL AND pri.material_id = NEW.material_id)
      OR (NEW.product_id IS NOT NULL AND pri.product_id = NEW.product_id)
    );

  -- تحديث كمية المورد المنفّذة
  UPDATE ecommerce_order_suppliers
  SET fulfilled_quantity = v_total_accepted,
      status = CASE WHEN v_total_accepted > 0 THEN 'fulfilled' ELSE status END,
      updated_at = NOW()
  WHERE id = v_ecom_supplier_id;

  -- تحديث بند الطلب الإلكتروني أيضاً
  UPDATE ecommerce_order_items eoi
  SET fulfilled_quantity = v_total_accepted
  WHERE eoi.id = (
    SELECT order_item_id FROM ecommerce_order_suppliers WHERE id = v_ecom_supplier_id
  );

  -- فحص هل كل البنود مكتملة
  IF NOT EXISTS (
    SELECT 1 FROM ecommerce_order_items
    WHERE order_id = v_ecom_order_id
      AND (fulfilled_quantity IS NULL OR fulfilled_quantity = 0)
  ) THEN
    UPDATE ecommerce_orders
    SET fulfilled_quantity_entered = true,
        updated_at = NOW()
    WHERE id = v_ecom_order_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: sync_ecom_fulfilled_from_st_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_ecom_fulfilled_from_st_items() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order_id uuid;
  v_total numeric;
BEGIN
  -- الفاتورة الأم يجب أن تكون من المتجر الإلكتروني
  SELECT st.source_id INTO v_order_id
  FROM sales_transactions st
  WHERE st.id = NEW.transaction_id
    AND st.source_type = 'ecommerce'
    AND st.source_id IS NOT NULL;

  IF v_order_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- مجموع المسلَّم لنفس المادة عبر بنود الفاتورة
  SELECT COALESCE(SUM(sti.delivered_qty), 0) INTO v_total
  FROM sales_transaction_items sti
  WHERE sti.transaction_id = NEW.transaction_id
    AND (
      (NEW.material_id IS NOT NULL AND sti.material_id = NEW.material_id)
      OR (NEW.material_id IS NULL AND NEW.product_id IS NOT NULL AND sti.product_id = NEW.product_id)
    );

  UPDATE ecommerce_order_items eoi
  SET fulfilled_quantity = v_total
  WHERE eoi.order_id = v_order_id
    AND (
      (NEW.material_id IS NOT NULL AND eoi.material_id = NEW.material_id)
      OR (NEW.material_id IS NULL AND NEW.product_id IS NOT NULL AND eoi.product_id = NEW.product_id)
    );

  -- كل البنود استوفت كمياتها → علامة "الكميات أُدخلت"
  IF NOT EXISTS (
    SELECT 1 FROM ecommerce_order_items
    WHERE order_id = v_order_id
      AND (fulfilled_quantity IS NULL OR fulfilled_quantity = 0)
  ) THEN
    UPDATE ecommerce_orders
    SET fulfilled_quantity_entered = true, updated_at = now()
    WHERE id = v_order_id AND fulfilled_quantity_entered IS DISTINCT FROM true;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: sync_ecom_order_from_sales_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_ecom_order_from_sales_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  IF NEW.source_type IS DISTINCT FROM 'ecommerce' OR NEW.source_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.stage IS NOT DISTINCT FROM OLD.stage
     AND NEW.tracking_number IS NOT DISTINCT FROM OLD.tracking_number THEN
    RETURN NEW;
  END IF;

  SELECT id, status INTO v_order
  FROM ecommerce_orders WHERE id = NEW.source_id;

  IF v_order.id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.tracking_number IS NOT NULL
     AND NEW.tracking_number IS DISTINCT FROM OLD.tracking_number THEN
    UPDATE ecommerce_orders
    SET tracking_number = NEW.tracking_number, updated_at = now()
    WHERE id = v_order.id;
  END IF;

  -- خروج فعلي للشحن/الفرع → "تم الشحن"
  -- (in_delivery مستثناة: هي تجهيز الإذن، لا شحن)
  IF NEW.stage IN ('in_transit', 'at_branch', 'sent_to_branch')
     AND v_order.status IN ('confirmed', 'processing', 'supplier_preparing') THEN
    UPDATE ecommerce_orders
    SET status = 'shipped',
        shipped_at = COALESCE(shipped_at, now()),
        updated_at = now()
    WHERE id = v_order.id;

  -- تسليم فعلي → "تم التسليم"
  ELSIF NEW.stage IN ('delivered', 'posted', 'completed')
        AND v_order.status NOT IN ('delivered', 'cancelled', 'returned') THEN
    UPDATE ecommerce_orders
    SET status = 'delivered',
        delivered_at = COALESCE(delivered_at, now()),
        delivery_confirmed = true,
        updated_at = now()
    WHERE id = v_order.id;
  END IF;

  -- in_delivery: المستودع يجهّز الإذن — الطلبية تبقى كما هي (قيد التجهيز)

  IF NEW.stage = 'paid' THEN
    UPDATE ecommerce_orders
    SET payment_status = 'paid', updated_at = now()
    WHERE id = v_order.id AND payment_status IS DISTINCT FROM 'paid';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: sync_ecommerce_to_customers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_ecommerce_to_customers() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- لا ننشئ حساب ERP عند التسجيل — يتم إنشاؤه عند أول معاملة فعلية
    -- الزبون يبقى فقط في ecommerce_customers حتى يتعامل فعلياً
    RAISE NOTICE '✅ sync_ecommerce_to_customers: Customer registered in ecommerce_customers only (no ERP account created). Email: %', NEW.email;
    RETURN NEW;
END;
$$;


--
-- Name: sync_is_group_from_is_detail(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_is_group_from_is_detail() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.is_group := NOT NEW.is_detail;
    RETURN NEW;
END;
$$;


--
-- Name: sync_material_current_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_material_current_stock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_mat UUID;
BEGIN
    v_mat := COALESCE(NEW.material_id, OLD.material_id);
    IF v_mat IS NOT NULL THEN
        UPDATE fabric_materials fm
        SET current_stock = COALESCE((
                SELECT SUM(quantity_on_hand) FROM inventory_stock WHERE material_id = v_mat
            ), 0),
            avg_cost_per_unit = COALESCE((
                SELECT CASE WHEN SUM(quantity_on_hand) > 0
                            THEN SUM(quantity_on_hand * COALESCE(average_cost,0)) / SUM(quantity_on_hand)
                            ELSE 0 END
                FROM inventory_stock WHERE material_id = v_mat AND quantity_on_hand > 0
            ), fm.avg_cost_per_unit),
            updated_at = NOW()
        WHERE fm.id = v_mat;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: sync_material_price_to_ecommerce(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_material_price_to_ecommerce() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Only sync if selling_price actually changed
  IF NEW.selling_price IS DISTINCT FROM OLD.selling_price THEN
    UPDATE ecommerce_products 
    SET base_price = NEW.selling_price,
        updated_at = NOW()
    WHERE source_table = 'fabric_materials' 
      AND source_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_mfa_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_mfa_status() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    DECLARE
      r RECORD;
      has_verified_totp BOOLEAN;
    BEGIN
      -- Loop through all user_profiles
      FOR r IN SELECT id FROM user_profiles
      LOOP
        -- Check if this user has a verified TOTP factor in Supabase native MFA
        SELECT EXISTS(
          SELECT 1 FROM auth.mfa_factors 
          WHERE user_id = r.id 
          AND factor_type = 'totp' 
          AND status = 'verified'
        ) INTO has_verified_totp;

        -- Sync user_profiles.two_factor_enabled
        UPDATE user_profiles 
        SET two_factor_enabled = has_verified_totp
        WHERE id = r.id 
        AND two_factor_enabled IS DISTINCT FROM has_verified_totp;

        -- Sync mfa_user_settings
        INSERT INTO mfa_user_settings (user_id, is_enabled, totp_verified, preferred_method)
        VALUES (r.id, has_verified_totp, has_verified_totp, 'totp')
        ON CONFLICT (user_id) DO UPDATE SET
          is_enabled = has_verified_totp,
          totp_verified = has_verified_totp
        WHERE mfa_user_settings.is_enabled IS DISTINCT FROM has_verified_totp
           OR mfa_user_settings.totp_verified IS DISTINCT FROM has_verified_totp;
      END LOOP;
    END;
    $$;


--
-- Name: sync_purchase_invoice_item_to_transaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_purchase_invoice_item_to_transaction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_material_name text;
    v_material_code text;
    v_invoice_status text;
BEGIN
    -- Get material name for better description
    IF NEW.material_id IS NOT NULL THEN
        SELECT name_ar, code INTO v_material_name, v_material_code
        FROM fabric_materials WHERE id = NEW.material_id;
    END IF;

    -- Check if parent invoice is posted (= fully received)
    SELECT status INTO v_invoice_status
    FROM purchase_invoices WHERE id = NEW.invoice_id;

    INSERT INTO purchase_transaction_items (
        id, transaction_id, line_number, product_id, material_id,
        item_code, description, description_ar, quantity, received_qty, unit,
        unit_price, discount_amount, discount_percent,
        tax_rate, tax_amount, subtotal, total,
        color_id, color_name, warehouse_id,
        created_at, updated_at
    ) VALUES (
        NEW.id, NEW.invoice_id, NEW.line_number,
        NEW.product_id, NEW.material_id,
        COALESCE(v_material_code, NEW.description),
        COALESCE(v_material_name, NEW.description),
        COALESCE(v_material_name, NEW.description),
        NEW.quantity,
        -- الرشيد: posted = fully received
        CASE WHEN v_invoice_status IN ('posted','completed','paid') THEN NEW.quantity ELSE 0 END,
        'piece',
        NEW.unit_price,
        COALESCE(NEW.discount_amount, 0),
        COALESCE(NEW.discount_percentage, 0),
        COALESCE(NEW.tax_rate, COALESCE(NEW.tax_percentage, 0)),
        COALESCE(NEW.tax_amount, 0),
        COALESCE(NEW.subtotal, 0),
        COALESCE(NEW.total, 0),
        NEW.color_id, NEW.color_name, NEW.warehouse_id,
        NEW.created_at, NEW.updated_at
    )
    ON CONFLICT (id) DO UPDATE SET
        description = EXCLUDED.description,
        description_ar = EXCLUDED.description_ar,
        quantity = EXCLUDED.quantity,
        received_qty = EXCLUDED.received_qty,
        unit_price = EXCLUDED.unit_price,
        subtotal = EXCLUDED.subtotal,
        total = EXCLUDED.total,
        updated_at = now();
    
    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'sync_purchase_invoice_item failed: %', SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: sync_purchase_invoice_to_transaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_purchase_invoice_to_transaction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_supplier_name text;
    v_subtotal numeric;
BEGIN
    -- Get supplier name if missing
    IF NEW.supplier_name IS NULL OR NEW.supplier_name = '' THEN
        SELECT COALESCE(name_ar, name_en) INTO v_supplier_name
        FROM suppliers WHERE id = NEW.supplier_id;
    ELSE
        v_supplier_name := NEW.supplier_name;
    END IF;

    -- Calculate subtotal
    v_subtotal := COALESCE(NEW.subtotal, 0);
    IF v_subtotal = 0 AND COALESCE(NEW.total_amount, 0) > 0 THEN
        v_subtotal := COALESCE(NEW.total_amount, 0);
    END IF;

    INSERT INTO purchase_transactions (
        id, tenant_id, company_id, branch_id, stage, invoice_no,
        supplier_id, supplier_name, doc_date, invoice_date, due_date,
        warehouse_id, receipt_mode, shipment_id,
        currency, exchange_rate, 
        subtotal, discount_amount, tax_amount, expenses_total, total_amount,
        paid_amount, balance,
        is_posted, is_active, 
        journal_entry_id, notes, supplier_invoice_number, supplier_invoice_date,
        supplier_notes, confirmation_status,
        created_by, created_at, updated_at,
        expenses, attachments
    ) VALUES (
        NEW.id, NEW.tenant_id, NEW.company_id, NEW.branch_id,
        -- الرشيد: posted = مستلمة ومرحّلة مباشرة
        CASE 
            WHEN NEW.status IN ('posted','paid','completed') THEN 'received'
            WHEN NEW.document_stage IN ('request','quotation','draft','confirmed','received','posted','cancelled') THEN NEW.document_stage
            WHEN NEW.document_stage = 'invoice' THEN 'confirmed'
            ELSE 'draft'
        END,
        NEW.invoice_number,
        NEW.supplier_id, v_supplier_name,
        NEW.invoice_date, NEW.invoice_date, NEW.due_date,
        NEW.warehouse_id, NEW.receipt_mode, NEW.shipment_id,
        NEW.currency, COALESCE(NEW.exchange_rate, 1),
        v_subtotal, COALESCE(NEW.discount_amount, 0),
        COALESCE(NEW.tax_amount, 0), COALESCE(NEW.expenses_total, 0),
        COALESCE(NEW.total_amount, 0),
        0, COALESCE(NEW.total_amount, 0),
        CASE WHEN NEW.status IN ('posted','paid','completed') THEN true ELSE COALESCE(NEW.is_posted, false) END,
        true,
        NEW.journal_entry_id, NEW.notes, NEW.supplier_invoice_number, NEW.supplier_invoice_date,
        NEW.supplier_notes,
        CASE WHEN NEW.confirmation_status IN ('pending','confirmed','rejected') THEN NEW.confirmation_status ELSE 'pending' END,
        NEW.created_by, NEW.created_at, NEW.updated_at,
        COALESCE(NEW.expenses, '[]'::jsonb), COALESCE(NEW.attachments, '[]'::jsonb)
    )
    ON CONFLICT (id) DO UPDATE SET
        stage = EXCLUDED.stage,
        invoice_no = EXCLUDED.invoice_no,
        supplier_id = EXCLUDED.supplier_id,
        supplier_name = EXCLUDED.supplier_name,
        subtotal = EXCLUDED.subtotal,
        total_amount = EXCLUDED.total_amount,
        tax_amount = EXCLUDED.tax_amount,
        currency = EXCLUDED.currency,
        is_posted = EXCLUDED.is_posted,
        updated_at = now();
    
    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'sync_purchase_invoice_to_transaction failed: %', SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: sync_sales_invoice_item_to_transaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_sales_invoice_item_to_transaction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_material_name text;
    v_material_code text;
    v_invoice_status text;
BEGIN
    -- Get product/material name
    IF NEW.product_id IS NOT NULL THEN
        SELECT name_ar, code INTO v_material_name, v_material_code
        FROM fabric_materials WHERE id = NEW.product_id;
    END IF;

    -- Check parent invoice status
    SELECT status INTO v_invoice_status
    FROM sales_invoices WHERE id = NEW.invoice_id;

    INSERT INTO sales_transaction_items (
        id, transaction_id, line_number, product_id,
        item_code, description, description_ar, quantity, delivered_qty, unit,
        unit_price, discount_amount, discount_percent,
        tax_rate, tax_amount, subtotal, total,
        warehouse_id, cost_price,
        created_at, updated_at
    ) VALUES (
        NEW.id, NEW.invoice_id, NEW.line_number, NEW.product_id,
        COALESCE(v_material_code, NEW.description),
        COALESCE(v_material_name, NEW.description),
        COALESCE(v_material_name, NEW.description),
        NEW.quantity,
        CASE WHEN v_invoice_status IN ('posted','completed','paid') THEN NEW.quantity ELSE 0 END,
        'piece',
        NEW.unit_price,
        COALESCE(NEW.discount_amount, 0),
        COALESCE(NEW.discount_percent, 0),
        COALESCE(NEW.tax_rate, COALESCE(NEW.tax_percent, 0)),
        COALESCE(NEW.tax_amount, 0),
        COALESCE(NEW.subtotal, 0),
        COALESCE(NEW.total, 0),
        NEW.warehouse_id,
        NEW.unit_cost,
        NEW.created_at,
        NEW.updated_at
    )
    ON CONFLICT (id) DO UPDATE SET
        description = EXCLUDED.description,
        description_ar = EXCLUDED.description_ar,
        quantity = EXCLUDED.quantity,
        delivered_qty = EXCLUDED.delivered_qty,
        unit_price = EXCLUDED.unit_price,
        subtotal = EXCLUDED.subtotal,
        total = EXCLUDED.total,
        updated_at = now();
    
    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'sync_sales_invoice_item failed: %', SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: sync_sales_invoice_paid_from_receipts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_sales_invoice_paid_from_receipts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_inv   UUID;
    v_paid  NUMERIC(15,4);
    v_total NUMERIC(15,4);
BEGIN
    v_inv := COALESCE(NEW.sales_transaction_id, OLD.sales_transaction_id);
    IF v_inv IS NOT NULL THEN
        SELECT COALESCE(SUM(amount), 0) INTO v_paid
        FROM payment_receipts
        WHERE sales_transaction_id = v_inv AND status = 'confirmed';

        SELECT COALESCE(total_amount, 0) INTO v_total
        FROM sales_transactions WHERE id = v_inv;

        UPDATE sales_transactions
        SET paid_amount = v_paid,
            balance = GREATEST(v_total - v_paid, 0),
            updated_at = NOW()
        WHERE id = v_inv;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: sync_sales_invoice_to_transaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_sales_invoice_to_transaction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_customer_name text;
    v_subtotal numeric;
BEGIN
    -- Get customer name if missing
    IF NEW.customer_name IS NULL OR NEW.customer_name = '' THEN
        SELECT COALESCE(name_ar, name_en) INTO v_customer_name
        FROM customers WHERE id = NEW.customer_id;
    ELSE
        v_customer_name := NEW.customer_name;
    END IF;

    v_subtotal := COALESCE(NEW.subtotal, 0);
    IF v_subtotal = 0 AND COALESCE(NEW.total_amount, 0) > 0 THEN
        v_subtotal := COALESCE(NEW.total_amount, 0);
    END IF;

    INSERT INTO sales_transactions (
        id, tenant_id, company_id, branch_id, stage, invoice_no,
        customer_id, customer_name, salesperson_id,
        doc_date, invoice_date, due_date,
        warehouse_id,
        currency, exchange_rate, 
        subtotal, discount_amount, discount_percent, tax_amount, total_amount,
        paid_amount, balance,
        is_posted, is_active, 
        journal_entry_id, notes,
        created_by, created_at, updated_at
    ) VALUES (
        NEW.id, NEW.tenant_id, NEW.company_id, NEW.branch_id,
        CASE 
            WHEN NEW.status IN ('posted','paid','completed') THEN 'delivered'
            WHEN NEW.document_stage IN ('draft','quotation','reservation','confirmed','order','delivery','invoice','posted','cancelled','paid') THEN NEW.document_stage
            ELSE 'draft'
        END,
        NEW.invoice_number,
        NEW.customer_id, v_customer_name, NEW.salesperson_id,
        NEW.invoice_date, NEW.invoice_date, NEW.due_date,
        NEW.warehouse_id,
        NEW.currency, COALESCE(NEW.exchange_rate, 1),
        v_subtotal, COALESCE(NEW.discount_amount, 0),
        COALESCE(NEW.discount_percent, 0), COALESCE(NEW.tax_amount, 0),
        COALESCE(NEW.total_amount, 0),
        0, COALESCE(NEW.total_amount, 0),
        CASE WHEN NEW.status IN ('posted','paid','completed') THEN true ELSE COALESCE(NEW.is_posted, false) END,
        true,
        NEW.journal_entry_id, NEW.notes,
        NEW.created_by, NEW.created_at, NEW.updated_at
    )
    ON CONFLICT (id) DO UPDATE SET
        stage = EXCLUDED.stage,
        invoice_no = EXCLUDED.invoice_no,
        customer_id = EXCLUDED.customer_id,
        customer_name = EXCLUDED.customer_name,
        subtotal = EXCLUDED.subtotal,
        total_amount = EXCLUDED.total_amount,
        tax_amount = EXCLUDED.tax_amount,
        currency = EXCLUDED.currency,
        is_posted = EXCLUDED.is_posted,
        updated_at = now();
    
    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'sync_sales_invoice_to_transaction failed: %', SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: sync_single_user_mfa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_single_user_mfa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    DECLARE
      target_user_id UUID;
      has_verified_totp BOOLEAN;
    BEGIN
      -- Determine which user was affected
      target_user_id := COALESCE(NEW.user_id, OLD.user_id);
      
      -- Check current MFA status
      SELECT EXISTS(
        SELECT 1 FROM auth.mfa_factors 
        WHERE user_id = target_user_id 
        AND factor_type = 'totp' 
        AND status = 'verified'
      ) INTO has_verified_totp;

      -- Sync user_profiles
      UPDATE user_profiles 
      SET two_factor_enabled = has_verified_totp
      WHERE id = target_user_id;

      -- Sync mfa_user_settings (upsert)
      INSERT INTO mfa_user_settings (user_id, is_enabled, totp_verified, preferred_method)
      VALUES (target_user_id, has_verified_totp, has_verified_totp, 'totp')
      ON CONFLICT (user_id) DO UPDATE SET
        is_enabled = has_verified_totp,
        totp_verified = has_verified_totp;

      RETURN COALESCE(NEW, OLD);
    END;
    $$;


--
-- Name: sync_summary_account_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.sync_summary_account_balance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_sum_id UUID;
    v_new_total NUMERIC;
BEGIN
    -- فقط إذا تغير الرصيد
    IF OLD.current_balance = NEW.current_balance THEN
        RETURN NEW;
    END IF;

    -- فقط للحسابات التي لها أب (فرعية)
    IF NEW.parent_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- البحث عن حساب SUM أخ (نفس الأب و is_summary_account)
    SELECT id INTO v_sum_id
    FROM public.chart_of_accounts
    WHERE parent_id = NEW.parent_id
      AND is_summary_account = true
    LIMIT 1;

    IF v_sum_id IS NULL THEN
        RETURN NEW;  -- لا يوجد حساب مجاميع
    END IF;

    -- حساب المجموع الجديد من كل الأخوة (ما عدا SUM نفسه)
    SELECT COALESCE(SUM(current_balance), 0) INTO v_new_total
    FROM public.chart_of_accounts
    WHERE parent_id = NEW.parent_id
      AND is_summary_account IS NOT TRUE
      AND id != v_sum_id;

    -- تحديث رصيد SUM
    UPDATE public.chart_of_accounts
    SET current_balance = v_new_total,
        updated_at = NOW()
    WHERE id = v_sum_id
      AND current_balance != v_new_total;  -- تجنب التحديث الدوري

    RETURN NEW;
END;
$$;


--
-- Name: task_accept(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.task_accept(p_id uuid, p_user uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_company uuid; v_assignee uuid; v_status text;
BEGIN
    p_user := COALESCE(auth.uid(), p_user);   -- منع الانتحال
    SELECT company_id, assigned_to, status INTO v_company, v_assignee, v_status FROM crm_tasks WHERE id = p_id;
    IF v_company IS NULL THEN RETURN jsonb_build_object('ok',false,'message','المهمة غير موجودة'); END IF;
    IF auth.uid() IS NOT NULL THEN PERFORM assert_can_access_company(v_company); END IF;
    IF v_assignee IS DISTINCT FROM p_user THEN RETURN jsonb_build_object('ok',false,'message','ليست مهمتك'); END IF;
    IF v_status NOT IN ('open','overdue','in_progress') THEN RETURN jsonb_build_object('ok',false,'message','لا يمكن استلامها بحالتها الحالية'); END IF;
    UPDATE crm_tasks SET status='in_progress', accepted_at=COALESCE(accepted_at, now()), updated_at=now() WHERE id=p_id;
    RETURN jsonb_build_object('ok',true,'message','تم الاستلام');
END $$;


--
-- Name: task_complete(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.task_complete(p_id uuid, p_user uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_company uuid; v_assignee uuid; v_assigner uuid; v_status text;
BEGIN
    p_user := COALESCE(auth.uid(), p_user);
    SELECT company_id, assigned_to, assigned_by, status INTO v_company, v_assignee, v_assigner, v_status FROM crm_tasks WHERE id = p_id;
    IF v_company IS NULL THEN RETURN jsonb_build_object('ok',false,'message','المهمة غير موجودة'); END IF;
    IF auth.uid() IS NOT NULL THEN PERFORM assert_can_access_company(v_company); END IF;
    IF v_assignee IS DISTINCT FROM p_user THEN RETURN jsonb_build_object('ok',false,'message','ليست مهمتك'); END IF;
    IF v_status NOT IN ('open','overdue','in_progress') THEN RETURN jsonb_build_object('ok',false,'message','لا يمكن إنهاؤها بحالتها'); END IF;
    UPDATE crm_tasks SET status='completed', completed_at=now(), verification_status='pending_review', updated_at=now() WHERE id=p_id;
    RETURN jsonb_build_object('ok',true,'message','تم الإنجاز — بانتظار تحقّق المدير','assigner',v_assigner);
END $$;


--
-- Name: task_verify(uuid, boolean, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.task_verify(p_id uuid, p_approved boolean, p_rating integer DEFAULT NULL::integer, p_reason text DEFAULT NULL::text, p_user uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_company uuid; v_assignee uuid; v_assigner uuid; v_creator uuid; v_vstatus text;
BEGIN
    p_user := COALESCE(auth.uid(), p_user);
    IF p_rating IS NOT NULL THEN p_rating := GREATEST(1, LEAST(5, p_rating)); END IF;   -- حدّ التقييم
    SELECT company_id, assigned_to, assigned_by, created_by, verification_status
      INTO v_company, v_assignee, v_assigner, v_creator, v_vstatus FROM crm_tasks WHERE id = p_id;
    IF v_company IS NULL THEN RETURN jsonb_build_object('ok',false,'message','المهمة غير موجودة'); END IF;
    IF auth.uid() IS NOT NULL THEN PERFORM assert_can_access_company(v_company); END IF;
    IF p_user IS DISTINCT FROM v_assigner AND p_user IS DISTINCT FROM v_creator THEN
        RETURN jsonb_build_object('ok',false,'message','التحقّق للمدير المُسنِد فقط');
    END IF;
    IF COALESCE(v_vstatus,'') <> 'pending_review' THEN RETURN jsonb_build_object('ok',false,'message','ليست بانتظار التحقّق'); END IF;

    IF p_approved THEN
        UPDATE crm_tasks SET verification_status='approved', verified_by=p_user, verified_at=now(),
               completion_rating=p_rating, status='completed', updated_at=now() WHERE id=p_id;
        IF p_rating IS NOT NULL AND v_assignee IS NOT NULL THEN
            BEGIN
                INSERT INTO employee_points(company_id, user_id, points, period_type, period_date, category, reason)
                VALUES (v_company, v_assignee, p_rating, 'monthly', date_trunc('month', CURRENT_DATE)::date, 'task', 'تقييم إنجاز مهمة crm:'||p_id::text);
            EXCEPTION WHEN OTHERS THEN NULL; END;
        END IF;
        RETURN jsonb_build_object('ok',true,'message','تم التحقّق والتقييم','assignee',v_assignee);
    ELSE
        UPDATE crm_tasks SET verification_status='rejected', verified_by=p_user, verified_at=now(),
               rejection_reason=p_reason, status='in_progress', updated_at=now() WHERE id=p_id;
        RETURN jsonb_build_object('ok',true,'message','أُعيدت للموظف','assignee',v_assignee);
    END IF;
END $$;


--
-- Name: tenant_has_module(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.tenant_has_module(p_module_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM tenant_modules
    WHERE tenant_id = get_user_tenant_id()
      AND module_code = p_module_code
      AND is_active = true
  )
  -- Platform admin always has access
  OR is_platform_admin();
$$;


--
-- Name: tenant_has_module(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.tenant_has_module(p_tenant_id uuid, p_module_code character varying) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- التحقق من حالة العميل أولاً
    IF NOT EXISTS (SELECT 1 FROM tenants WHERE id = p_tenant_id AND status = 'active') THEN
        RETURN false;
    END IF;
    
    -- التحقق من الموديول
    RETURN EXISTS (
        SELECT 1 FROM tenant_modules 
        WHERE tenant_id = p_tenant_id 
          AND module_code = p_module_code 
          AND is_active = true
          AND (expires_at IS NULL OR expires_at > NOW())
    );
END;
$$;


--
-- Name: test_tenant_isolation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.test_tenant_isolation() RETURNS TABLE(test_name text, result text, details text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tenant1_id UUID;
    v_tenant2_id UUID;
    v_count1 INT;
    v_count2 INT;
    v_total INT;
BEGIN
    -- الحصول على IDs
    SELECT id INTO v_tenant1_id FROM tenants WHERE code = 'test-tenant-001';
    SELECT id INTO v_tenant2_id FROM tenants WHERE code = 'test-tenant-002';
    
    -- Test 1: التحقق من وجود الـ tenants
    test_name := 'Test Tenants Exist';
    IF v_tenant1_id IS NOT NULL AND v_tenant2_id IS NOT NULL THEN
        result := '✅ PASS';
        details := format('Tenant1: %s, Tenant2: %s', v_tenant1_id, v_tenant2_id);
    ELSE
        result := '❌ FAIL';
        details := 'Missing test tenants';
    END IF;
    RETURN NEXT;
    
    -- Test 2: عدد الشركات لكل tenant
    SELECT COUNT(*) INTO v_count1 FROM companies WHERE tenant_id = v_tenant1_id;
    SELECT COUNT(*) INTO v_count2 FROM companies WHERE tenant_id = v_tenant2_id;
    SELECT COUNT(*) INTO v_total FROM companies WHERE tenant_id IN (v_tenant1_id, v_tenant2_id);
    
    test_name := 'Companies Isolation';
    IF v_count1 > 0 AND v_count2 > 0 AND v_total = (v_count1 + v_count2) THEN
        result := '✅ PASS';
        details := format('T1: %s, T2: %s, Total: %s', v_count1, v_count2, v_total);
    ELSE
        result := '⚠️ WARN';
        details := format('Counts may indicate issues: T1=%s, T2=%s', v_count1, v_count2);
    END IF;
    RETURN NEXT;
    
    -- Test 3: عدد العملاء لكل tenant
    SELECT COUNT(*) INTO v_count1 FROM customers WHERE tenant_id = v_tenant1_id;
    SELECT COUNT(*) INTO v_count2 FROM customers WHERE tenant_id = v_tenant2_id;
    
    test_name := 'Customers Isolation';
    IF v_count1 >= 2 AND v_count2 >= 2 THEN
        result := '✅ PASS';
        details := format('T1: %s customers, T2: %s customers', v_count1, v_count2);
    ELSE
        result := '⚠️ WARN';
        details := format('Expected at least 2 each: T1=%s, T2=%s', v_count1, v_count2);
    END IF;
    RETURN NEXT;
    
    -- Test 4: التحقق من أن دالة get_current_tenant_id موجودة
    test_name := 'get_current_tenant_id Function';
    IF EXISTS (
        SELECT 1 FROM pg_proc p
        JOIN pg_namespace n ON p.pronamespace = n.oid
        WHERE n.nspname = 'public' AND p.proname = 'get_current_tenant_id'
    ) THEN
        result := '✅ PASS';
        details := 'Function exists and is callable';
    ELSE
        result := '❌ FAIL';
        details := 'Function does not exist - RLS will fail!';
    END IF;
    RETURN NEXT;
    
    -- Test 5: التحقق من RLS مفعل على الجداول الحرجة
    test_name := 'RLS Enabled on Critical Tables';
    DECLARE
        v_rls_count INT;
        v_critical_tables TEXT[] := ARRAY[
            'companies', 'customers', 'suppliers', 'products',
            'journal_entries', 'sales_invoices', 'documents'
        ];
        v_table TEXT;
        v_rls_enabled BOOLEAN;
        v_missing TEXT := '';
    BEGIN
        v_rls_count := 0;
        FOREACH v_table IN ARRAY v_critical_tables
        LOOP
            SELECT relrowsecurity INTO v_rls_enabled
            FROM pg_class
            WHERE relname = v_table AND relnamespace = 'public'::regnamespace;
            
            IF COALESCE(v_rls_enabled, false) THEN
                v_rls_count := v_rls_count + 1;
            ELSE
                v_missing := v_missing || v_table || ', ';
            END IF;
        END LOOP;
        
        IF v_rls_count = array_length(v_critical_tables, 1) THEN
            result := '✅ PASS';
            details := format('All %s critical tables have RLS enabled', v_rls_count);
        ELSIF v_rls_count > 0 THEN
            result := '⚠️ WARN';
            details := format('RLS enabled on %s/%s tables. Missing: %s', 
                v_rls_count, array_length(v_critical_tables, 1), 
                TRIM(TRAILING ', ' FROM v_missing));
        ELSE
            result := '❌ FAIL';
            details := 'No critical tables have RLS enabled!';
        END IF;
    END;
    RETURN NEXT;
    
    -- Test 6: التحقق من وجود RLS Policies
    test_name := 'RLS Policies Exist';
    SELECT COUNT(*) INTO v_count1
    FROM pg_policies
    WHERE schemaname = 'public' 
      AND (policyname LIKE '%tenant%' OR policyname LIKE '%isolation%');
    
    IF v_count1 >= 20 THEN
        result := '✅ PASS';
        details := format('%s tenant isolation policies found', v_count1);
    ELSIF v_count1 > 0 THEN
        result := '⚠️ WARN';
        details := format('Only %s policies found - may need more', v_count1);
    ELSE
        result := '❌ FAIL';
        details := 'No tenant isolation policies found!';
    END IF;
    RETURN NEXT;
    
    -- Test 7: التحقق من audit_logs
    test_name := 'Audit Logs Table';
    IF EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'audit_logs'
    ) THEN
        result := '✅ PASS';
        details := 'audit_logs table exists';
    ELSE
        result := '⚠️ WARN';
        details := 'audit_logs table not found';
    END IF;
    RETURN NEXT;
    
    -- Test 8: التحقق من documents table
    test_name := 'Documents Table';
    IF EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'documents'
    ) THEN
        SELECT COUNT(*) INTO v_count1
        FROM information_schema.columns
        WHERE table_name = 'documents' AND column_name = 'tenant_id';
        
        IF v_count1 > 0 THEN
            result := '✅ PASS';
            details := 'documents table exists with tenant_id';
        ELSE
            result := '⚠️ WARN';
            details := 'documents table missing tenant_id column';
        END IF;
    ELSE
        result := '❌ FAIL';
        details := 'documents table not found';
    END IF;
    RETURN NEXT;
    
    -- Test 9: التحقق من storage_quotas
    test_name := 'Storage Quotas Table';
    IF EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'storage_quotas'
    ) THEN
        result := '✅ PASS';
        details := 'storage_quotas table exists';
    ELSE
        result := '⚠️ WARN';
        details := 'storage_quotas table not found';
    END IF;
    RETURN NEXT;
    
    -- Test 10: التحقق من subscription_alerts
    test_name := 'Subscription Alerts Table';
    IF EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'subscription_alerts'
    ) THEN
        result := '✅ PASS';
        details := 'subscription_alerts table exists';
    ELSE
        result := '⚠️ WARN';
        details := 'subscription_alerts table not found';
    END IF;
    RETURN NEXT;
    
    RETURN;
END;
$$;


--
-- Name: toggle_plan_status(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.toggle_plan_status(p_plan_id uuid, p_is_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM subscription_plans WHERE id = p_plan_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'plan_not_found'
        );
    END IF;
    
    UPDATE subscription_plans
    SET is_active = p_is_active
    WHERE id = p_plan_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'plan_id', p_plan_id,
        'is_active', p_is_active
    );
END;
$$;


--
-- Name: toggle_tenant_module(uuid, character varying, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.toggle_tenant_module(p_tenant_id uuid, p_module_code character varying, p_enabled boolean, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_user_id UUID;
BEGIN
    v_current_user_id := auth.uid();
    
    -- ✅ استخدام is_super_admin() الآمنة
    IF NOT is_super_admin(v_current_user_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Unauthorized: Super Admin access required'
        );
    END IF;
    
    -- التحقق من وجود الموديول
    IF NOT EXISTS (SELECT 1 FROM system_modules WHERE code = p_module_code) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Module not found'
        );
    END IF;
    
    -- إدراج أو تحديث
    INSERT INTO tenant_modules (
        tenant_id,
        module_code,
        is_active,
        enabled_by,
        enabled_at
    ) VALUES (
        p_tenant_id,
        p_module_code,
        p_enabled,
        v_current_user_id,
        CASE WHEN p_enabled THEN NOW() ELSE NULL END
    )
    ON CONFLICT (tenant_id, module_code)
    DO UPDATE SET
        is_active = p_enabled,
        enabled_by = v_current_user_id,
        enabled_at = CASE WHEN p_enabled THEN NOW() ELSE tenant_modules.enabled_at END;
    
    RETURN jsonb_build_object(
        'success', true,
        'tenant_id', p_tenant_id,
        'module_code', p_module_code,
        'enabled', p_enabled
    );
END;
$$;


--
-- Name: transfer_account_balance(uuid, uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.transfer_account_balance(p_source_account_id uuid, p_target_account_id uuid, p_amount numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID; v_company_id UUID;
    v_source_account RECORD; v_target_account RECORD;
    v_transfer_amount DECIMAL(15, 2); v_source_balance DECIMAL(15, 2);
    v_journal_entry_id UUID; v_transfer_id UUID; v_description TEXT;
BEGIN
    SELECT * INTO v_source_account FROM chart_of_accounts WHERE id = p_source_account_id;
    IF v_source_account IS NULL THEN RAISE EXCEPTION 'Source account not found'; END IF;
    SELECT * INTO v_target_account FROM chart_of_accounts WHERE id = p_target_account_id;
    IF v_target_account IS NULL THEN RAISE EXCEPTION 'Target account not found'; END IF;
    IF v_source_account.company_id != v_target_account.company_id THEN
        RAISE EXCEPTION 'Accounts must belong to the same company';
    END IF;
    v_tenant_id := v_source_account.tenant_id;
    v_company_id := v_source_account.company_id;

    -- Security check (NEW)
    PERFORM assert_can_access_company(v_company_id);

    IF v_source_account.is_group OR v_target_account.is_group THEN
        RAISE EXCEPTION 'Cannot transfer balance from/to group accounts';
    END IF;
    SELECT COALESCE(SUM(debit - credit), 0) INTO v_source_balance
    FROM journal_entry_lines WHERE account_id = p_source_account_id;
    IF p_amount IS NULL THEN v_transfer_amount := ABS(v_source_balance);
    ELSE v_transfer_amount := p_amount; END IF;
    IF v_transfer_amount <= 0 THEN RAISE EXCEPTION 'Transfer amount must be positive'; END IF;
    IF v_transfer_amount > ABS(v_source_balance) THEN
        RAISE EXCEPTION 'Transfer amount (%) exceeds source balance (%)', v_transfer_amount, ABS(v_source_balance);
    END IF;
    v_description := format('Balance transfer from %s to %s', v_source_account.account_code, v_target_account.account_code);
    INSERT INTO journal_entries (tenant_id, company_id, entry_date, description, notes, created_by)
    VALUES (v_tenant_id, v_company_id, CURRENT_DATE, v_description, p_notes, p_user_id)
    RETURNING id INTO v_journal_entry_id;
    INSERT INTO journal_entry_lines (journal_entry_id, account_id, debit, credit, description)
    VALUES (v_journal_entry_id, p_target_account_id, v_transfer_amount, 0, v_description);
    INSERT INTO journal_entry_lines (journal_entry_id, account_id, debit, credit, description)
    VALUES (v_journal_entry_id, p_source_account_id, 0, v_transfer_amount, v_description);
    INSERT INTO account_transfers (tenant_id, company_id, source_account_id, target_account_id,
        transfer_type, amount, journal_entry_id, notes, created_by)
    VALUES (v_tenant_id, v_company_id, p_source_account_id, p_target_account_id,
        'balance', v_transfer_amount, v_journal_entry_id, p_notes, p_user_id)
    RETURNING id INTO v_transfer_id;
    RETURN v_transfer_id;
END;
$$;


