--
-- Name: trigger_nexa_intelligence(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.trigger_nexa_intelligence(p_report_type text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_company RECORD;
  v_url TEXT := 'https://wzkklenfsaepegymfxfz.supabase.co/functions/v1/nexa-intelligence';
  v_key TEXT;
BEGIN
  -- خادمي/أدمن فقط: لا يُطلق مستخدم عادي عملاً عابراً لكل الشركات
  IF auth.uid() IS NOT NULL
     AND NOT (is_super_admin(auth.uid()) OR is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'trigger_nexa_intelligence: not authorized (platform/service only)';
  END IF;

  -- المفتاح من Vault لا من الكود
  SELECT decrypted_secret INTO v_key
  FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1;
  IF v_key IS NULL OR length(v_key) = 0 THEN
    RAISE EXCEPTION 'trigger_nexa_intelligence: Vault secret "service_role_key" not set — run vault.create_secret(...)';
  END IF;

  FOR v_company IN
    SELECT c.id AS company_id, c.tenant_id FROM companies c WHERE c.is_active = true
  LOOP
    PERFORM net.http_post(
      url := v_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_key,
        'apikey', v_key
      ),
      body := jsonb_build_object('report_type', p_report_type, 'company_id', v_company.company_id, 'tenant_id', v_company.tenant_id)
    );
    RAISE LOG '[NexaIntelligence] Triggered % report for company %', p_report_type, v_company.company_id;
  END LOOP;
END;
$$;


--
-- Name: unlock_subscription(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.unlock_subscription(p_subscription_id uuid, p_new_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE subscriptions
    SET 
        status = 'active',
        locked_at = NULL,
        lock_reason = NULL,
        current_period_end = COALESCE(p_new_period_end, current_period_end + INTERVAL '30 days'),
        updated_at = NOW()
    WHERE id = p_subscription_id;
    
    RETURN FOUND;
END;
$$;


--
-- Name: unpost_journal_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.unpost_journal_entry(p_entry_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_entry RECORD;
    v_line RECORD;
BEGIN
    SELECT * INTO v_entry
    FROM journal_entries
    WHERE id = p_entry_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'القيد غير موجود';
    END IF;
    
    IF NOT v_entry.is_posted THEN
        RAISE EXCEPTION 'القيد غير مرحّل';
    END IF;
    
    -- Reverse: subtract Net (Dr-Cr) that was added during posting
    FOR v_line IN 
        SELECT * FROM journal_entry_lines WHERE entry_id = p_entry_id
    LOOP
        UPDATE chart_of_accounts
        SET current_balance = COALESCE(current_balance, 0) - (v_line.debit - v_line.credit),
            updated_at = NOW()
        WHERE id = v_line.account_id;
    END LOOP;
    
    UPDATE journal_entries
    SET is_posted = false,
        posted_at = NULL,
        posted_by = NULL,
        status = 'draft'
    WHERE id = p_entry_id;
    
    RETURN true;
END;
$$;


--
-- Name: unpost_journal_entry(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.unpost_journal_entry(p_entry_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_entry RECORD;
    v_line RECORD;
    v_movement DECIMAL(15,2);
BEGIN
    SELECT * INTO v_entry FROM journal_entries WHERE id = p_entry_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'القيد غير موجود'; END IF;
    IF NOT v_entry.is_posted THEN RETURN true; END IF;
    
    FOR v_line IN 
        SELECT jel.*, at.normal_balance
        FROM journal_entry_lines jel
        JOIN chart_of_accounts coa ON jel.account_id = coa.id
        JOIN account_types at ON coa.account_type_id = at.id
        WHERE jel.entry_id = p_entry_id
    LOOP
        IF v_line.normal_balance = 'debit' THEN
            v_movement := v_line.debit - v_line.credit;
        ELSE
            v_movement := v_line.credit - v_line.debit;
        END IF;
        UPDATE chart_of_accounts
        SET current_balance = current_balance - v_movement, updated_at = NOW()
        WHERE id = v_line.account_id;
    END LOOP;
    
    UPDATE journal_entries
    SET is_posted = false, posted_at = NULL, status = 'draft'
    WHERE id = p_entry_id;
    RETURN true;
END;
$$;


--
-- Name: update_account_balance_from_je_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.update_account_balance_from_je_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_entry_status TEXT;
    v_delta    NUMERIC;
    v_delta_fc NUMERIC;
BEGIN
    IF TG_OP = 'INSERT' THEN
        SELECT status INTO v_entry_status FROM public.journal_entries WHERE id = NEW.entry_id;
        IF v_entry_status = 'posted' THEN
            UPDATE public.chart_of_accounts
            SET current_balance = current_balance + COALESCE(NEW.debit,0) - COALESCE(NEW.credit,0),
                current_balance_fc = COALESCE(current_balance_fc,0) + COALESCE(NEW.debit_fc,0) - COALESCE(NEW.credit_fc,0),
                updated_at = NOW()
            WHERE id = NEW.account_id;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        SELECT status INTO v_entry_status FROM public.journal_entries WHERE id = NEW.entry_id;
        IF v_entry_status = 'posted' THEN
            v_delta    := (COALESCE(NEW.debit,0)-COALESCE(NEW.credit,0)) - (COALESCE(OLD.debit,0)-COALESCE(OLD.credit,0));
            v_delta_fc := (COALESCE(NEW.debit_fc,0)-COALESCE(NEW.credit_fc,0)) - (COALESCE(OLD.debit_fc,0)-COALESCE(OLD.credit_fc,0));
            IF v_delta <> 0 OR v_delta_fc <> 0 THEN
                UPDATE public.chart_of_accounts
                SET current_balance = current_balance + v_delta,
                    current_balance_fc = COALESCE(current_balance_fc,0) + v_delta_fc,
                    updated_at = NOW()
                WHERE id = NEW.account_id;
            END IF;
            IF OLD.account_id <> NEW.account_id THEN
                UPDATE public.chart_of_accounts
                SET current_balance = current_balance - (COALESCE(OLD.debit,0)-COALESCE(OLD.credit,0)),
                    current_balance_fc = COALESCE(current_balance_fc,0) - (COALESCE(OLD.debit_fc,0)-COALESCE(OLD.credit_fc,0)),
                    updated_at = NOW()
                WHERE id = OLD.account_id;
                UPDATE public.chart_of_accounts
                SET current_balance = current_balance + (COALESCE(NEW.debit,0)-COALESCE(NEW.credit,0)),
                    current_balance_fc = COALESCE(current_balance_fc,0) + (COALESCE(NEW.debit_fc,0)-COALESCE(NEW.credit_fc,0)),
                    updated_at = NOW()
                WHERE id = NEW.account_id;
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        SELECT status INTO v_entry_status FROM public.journal_entries WHERE id = OLD.entry_id;
        IF v_entry_status = 'posted' THEN
            UPDATE public.chart_of_accounts
            SET current_balance = current_balance - COALESCE(OLD.debit,0) + COALESCE(OLD.credit,0),
                current_balance_fc = COALESCE(current_balance_fc,0) - COALESCE(OLD.debit_fc,0) + COALESCE(OLD.credit_fc,0),
                updated_at = NOW()
            WHERE id = OLD.account_id;
        END IF;
        RETURN OLD;
    END IF;

    RETURN NULL;
END;
$$;


