--

CREATE OR REPLACE FUNCTION public.update_import_job_status(p_job_id uuid, p_status character varying, p_error_message text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    UPDATE import_jobs
    SET 
        status = p_status,
        error_message = COALESCE(p_error_message, error_message),
        updated_at = NOW(),
        completed_at = CASE WHEN p_status IN ('completed', 'failed', 'cancelled') THEN NOW() ELSE completed_at END
    WHERE id = p_job_id;
END;
$$;


--
-- Name: update_inventory_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.update_inventory_stock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_qty   DECIMAL(15,3);
    v_current_cost  DECIMAL(15,4);
    v_new_avg_cost  DECIMAL(15,4);
    v_warehouse_id  UUID;
    v_target_id     UUID;
    v_mt            TEXT;
    v_is_in         BOOLEAN;
    v_is_out        BOOLEAN;
    v_new_qty       DECIMAL(15,3);
    v_allow_negative BOOLEAN := false;
BEGIN
    v_mt := lower(COALESCE(NEW.movement_type, ''));
    -- [4A] مفردات موحّدة (تشمل الأنواع التي كانت تُهمَل)
    v_is_in  := v_mt IN ('receipt','purchase','return_in','adjustment_in','transfer_in','container_receipt','purchase_receipt');
    v_is_out := v_mt IN ('sale','issue','return_out','adjustment_out','transfer_out','sales_delivery','out');

    -- أنواع غير معروفة: سجل فقط، بلا أثر على الرصيد
    IF NOT (v_is_in OR v_is_out) THEN
        RETURN NEW;
    END IF;

    -- [4A] اتجاه المستودع حسب نوع الحركة
    IF v_is_out THEN
        v_warehouse_id := COALESCE(NEW.from_warehouse_id, NEW.to_warehouse_id);
    ELSE
        v_warehouse_id := COALESCE(NEW.to_warehouse_id, NEW.from_warehouse_id);
    END IF;

    v_target_id := COALESCE(NEW.material_id, NEW.product_id);

    -- الرصيد الحالي
    SELECT quantity_on_hand, average_cost
    INTO v_current_qty, v_current_cost
    FROM inventory_stock
    WHERE ((material_id IS NOT NULL AND material_id = v_target_id)
        OR (product_id  IS NOT NULL AND product_id  = v_target_id))
      AND warehouse_id = v_warehouse_id
    LIMIT 1;
    IF NOT FOUND THEN
        v_current_qty := 0;
        v_current_cost := 0;
    END IF;

    -- ═══ الإضافة (IN) — متوسط مرجّح ═══
    IF v_is_in THEN
        IF (v_current_qty + NEW.quantity) > 0 THEN
            v_new_avg_cost := ((v_current_qty * v_current_cost) + (NEW.quantity * COALESCE(NEW.unit_cost, v_current_cost, 0))) / (v_current_qty + NEW.quantity);
        ELSE
            v_new_avg_cost := COALESCE(NEW.unit_cost, v_current_cost, 0);
        END IF;

        UPDATE inventory_stock
        SET quantity_on_hand = quantity_on_hand + NEW.quantity,
            average_cost = v_new_avg_cost,
            last_cost = COALESCE(NEW.unit_cost, inventory_stock.last_cost),
            last_movement_date = NOW(),
            updated_at = NOW()
        WHERE ((material_id IS NOT NULL AND material_id = v_target_id)
            OR (product_id  IS NOT NULL AND product_id  = v_target_id))
          AND warehouse_id = v_warehouse_id;

        IF NOT FOUND THEN
            INSERT INTO inventory_stock (
                tenant_id, company_id, product_id, material_id, warehouse_id,
                quantity_on_hand, average_cost, last_cost, last_movement_date, batch_number
            ) VALUES (
                NEW.tenant_id, NEW.company_id, NEW.product_id, NEW.material_id, v_warehouse_id,
                NEW.quantity, v_new_avg_cost, COALESCE(NEW.unit_cost, 0), NOW(), 'N/A'
            );
        END IF;

        NEW.balance_before := v_current_qty;
        NEW.balance_after  := v_current_qty + NEW.quantity;

    -- ═══ الصرف (OUT) — مع حارس السالب ═══
    ELSE
        v_new_qty := v_current_qty - NEW.quantity;

        IF v_new_qty < 0 THEN
            -- هل تسمح المادة بالرصيد السالب؟
            IF NEW.material_id IS NOT NULL THEN
                SELECT COALESCE(allow_negative_stock, false) INTO v_allow_negative
                FROM fabric_materials WHERE id = NEW.material_id;
            END IF;
            IF NOT COALESCE(v_allow_negative, false) THEN
                RAISE EXCEPTION 'الكمية غير كافية في المستودع: المتاح %، المطلوب % (المادة/المنتج %، المستودع %)',
                    v_current_qty, NEW.quantity, v_target_id, v_warehouse_id
                    USING ERRCODE = 'check_violation';
            END IF;
        END IF;

        UPDATE inventory_stock
        SET quantity_on_hand = quantity_on_hand - NEW.quantity,
            last_movement_date = NOW(),
            updated_at = NOW()
        WHERE ((material_id IS NOT NULL AND material_id = v_target_id)
            OR (product_id  IS NOT NULL AND product_id  = v_target_id))
          AND warehouse_id = v_warehouse_id;

        -- لا صف؟ أنشئه (لئلا يُفقَد الخصم) — يبقى inventory_stock = Σ الحركات
        IF NOT FOUND THEN
            INSERT INTO inventory_stock (
                tenant_id, company_id, product_id, material_id, warehouse_id,
                quantity_on_hand, average_cost, last_cost, last_movement_date, batch_number
            ) VALUES (
                NEW.tenant_id, NEW.company_id, NEW.product_id, NEW.material_id, v_warehouse_id,
                -NEW.quantity, COALESCE(v_current_cost, 0), COALESCE(NEW.unit_cost, 0), NOW(), 'N/A'
            );
        END IF;

        NEW.balance_before := v_current_qty;
        NEW.balance_after  := v_new_qty;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: update_invoice_payment_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.update_invoice_payment_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_paid DECIMAL(15,2);
BEGIN
    SELECT COALESCE(SUM(amount), 0) INTO v_total_paid
    FROM payment_receipt_allocations
    WHERE invoice_id = COALESCE(NEW.invoice_id, OLD.invoice_id);
    
    UPDATE sales_invoices
    SET paid_amount = v_total_paid,
        payment_status = CASE
            WHEN v_total_paid >= total_amount THEN 'paid'
            WHEN v_total_paid > 0 THEN 'partial'
            ELSE 'unpaid'
        END
    WHERE id = COALESCE(NEW.invoice_id, OLD.invoice_id);
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


