--

CREATE OR REPLACE FUNCTION public.update_subscription_plan(p_plan_id uuid, p_name_ar character varying DEFAULT NULL::character varying, p_name_en character varying DEFAULT NULL::character varying, p_description text DEFAULT NULL::text, p_max_users integer DEFAULT NULL::integer, p_max_companies integer DEFAULT NULL::integer, p_max_branches integer DEFAULT NULL::integer, p_max_warehouses integer DEFAULT NULL::integer, p_max_products integer DEFAULT NULL::integer, p_storage_gb integer DEFAULT NULL::integer, p_included_modules jsonb DEFAULT NULL::jsonb, p_features jsonb DEFAULT NULL::jsonb, p_price_monthly numeric DEFAULT NULL::numeric, p_price_yearly numeric DEFAULT NULL::numeric, p_currency character varying DEFAULT NULL::character varying, p_trial_days integer DEFAULT NULL::integer, p_is_popular boolean DEFAULT NULL::boolean, p_display_order integer DEFAULT NULL::integer, p_is_active boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
