--
-- Name: update_summary_account_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.update_summary_account_balance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- تحديث رصيد الحساب الملخص = مجموع أرصدة الحسابات الفرعية
    UPDATE chart_of_accounts
    SET current_balance = COALESCE((
        SELECT SUM(current_balance)
        FROM chart_of_accounts sub
        WHERE sub.parent_id = NEW.parent_id
          AND sub.is_party_account = true
    ), 0),
    updated_at = now()
    WHERE parent_id = NEW.parent_id
      AND is_summary_account = true;

    RETURN NEW;
END;
$$;


--
-- Name: update_supplier_link_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.update_supplier_link_stats(p_link_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_products INTEGER;
    v_orders INTEGER;
    v_revenue DECIMAL(15,2);
BEGIN
    -- عدد المنتجات المنشورة
    SELECT COUNT(*) INTO v_products
    FROM ecommerce_products
    WHERE supplier_link_id = p_link_id AND is_published = true;
    
    -- عدد الطلبات والإيراد
    SELECT COALESCE(COUNT(DISTINCT eos.order_id), 0),
           COALESCE(SUM(eoi.total), 0)
    INTO v_orders, v_revenue
    FROM ecommerce_order_suppliers eos
    JOIN marketplace_supplier_links msl ON msl.supplier_id = eos.supplier_id AND msl.id = p_link_id
    JOIN ecommerce_order_items eoi ON eoi.order_id = eos.order_id;
    
    -- تحديث
    UPDATE marketplace_supplier_links
    SET total_products = v_products,
        total_orders = v_orders,
        total_revenue = COALESCE(v_revenue, 0),
        -- تفعيل تلقائي إذا approved + has products
        status = CASE 
            WHEN status = 'approved' AND v_products > 0 THEN 'active'
            WHEN status = 'active' AND v_products = 0 THEN 'approved'
            ELSE status
        END
    WHERE id = p_link_id;
END;
$$;


--
-- Name: update_telegram_draft(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.update_telegram_draft(p_id uuid, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_company uuid;
BEGIN
    SELECT company_id INTO v_company FROM pending_actions WHERE id = p_id AND status = 'pending';
    IF v_company IS NULL THEN RETURN jsonb_build_object('ok', false, 'message', 'المسودة غير موجودة أو مؤكَّدة'); END IF;
    IF auth.uid() IS NOT NULL THEN PERFORM assert_can_access_company(v_company); END IF;

    UPDATE pending_actions
       SET action_data = COALESCE(action_data, '{}'::jsonb) || COALESCE(p_patch, '{}'::jsonb)
     WHERE id = p_id AND status = 'pending';

    RETURN jsonb_build_object('ok', true);
END $$;


