--
-- Name: update_tenant_presence(uuid, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.update_tenant_presence(p_tenant_id uuid, p_ip character varying DEFAULT NULL::character varying, p_country character varying DEFAULT NULL::character varying, p_city character varying DEFAULT NULL::character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    UPDATE tenants SET
        last_seen_at = NOW(),
        last_seen_ip = COALESCE(p_ip, last_seen_ip),
        last_seen_country = COALESCE(p_country, last_seen_country),
        last_seen_city = COALESCE(p_city, last_seen_city)
    WHERE id = p_tenant_id;
END;
$$;


--
-- Name: update_tenant_registration_location(uuid, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.update_tenant_registration_location(p_tenant_id uuid, p_ip character varying DEFAULT NULL::character varying, p_country character varying DEFAULT NULL::character varying, p_country_code character varying DEFAULT NULL::character varying, p_city character varying DEFAULT NULL::character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    UPDATE tenants SET
        registration_ip = COALESCE(p_ip, registration_ip),
        country = COALESCE(p_country, country),
        registration_country_code = COALESCE(p_country_code, registration_country_code),
        registration_city = COALESCE(p_city, registration_city),
        -- Also update last_seen on registration
        last_seen_at = NOW(),
        last_seen_ip = p_ip,
        last_seen_country = p_country,
        last_seen_city = p_city
    WHERE id = p_tenant_id;
END;
$$;


