--
-- Name: update_user_profile_on_registration(uuid, character varying, character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION public.update_user_profile_on_registration(p_user_id uuid, p_email character varying, p_full_name character varying, p_role character varying, p_company_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_result JSON;
    v_uid  uuid := auth.uid();
    v_role text := auth.role();
    v_eff_role character varying := p_role;
BEGIN
    IF NOT (v_role = 'service_role' OR v_role IS NULL) THEN
        IF v_uid IS NOT NULL AND (is_super_admin(v_uid) OR is_tenant_admin(v_uid) OR is_company_admin(v_uid, p_company_id)) THEN
            NULL;  -- أدمن: يحترم p_role
        ELSE
            -- مستخدم عادي: ملفه فقط + منع تصعيد الدور
            IF v_uid IS NULL OR v_uid <> p_user_id THEN
                RAISE EXCEPTION 'update_user_profile_on_registration: may only update your own profile';
            END IF;
            v_eff_role := 'customer';
        END IF;
    END IF;

    INSERT INTO public.user_profiles (id, email, full_name, role, company_id)
    VALUES (p_user_id, p_email, p_full_name, v_eff_role, p_company_id)
    ON CONFLICT (id) DO UPDATE SET
        email = EXCLUDED.email, full_name = EXCLUDED.full_name,
        role = EXCLUDED.role, company_id = EXCLUDED.company_id, updated_at = NOW();

    SELECT row_to_json(t) INTO v_result FROM (
        SELECT id, email, full_name, role, company_id, created_at, updated_at
        FROM public.user_profiles WHERE id = p_user_id
    ) t;
    RETURN v_result;
END;
$$;


