    label_url text,
    barcode character varying(100),
    api_request jsonb,
    api_response jsonb,
    status_history jsonb DEFAULT '[]'::jsonb,
    description text,
    internal_notes text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


