    CONSTRAINT contact_interactions_interaction_type_check CHECK ((interaction_type = ANY (ARRAY[('call'::character varying)::text, ('email'::character varying)::text, ('meeting'::character varying)::text, ('note'::character varying)::text, ('sms'::character varying)::text, ('whatsapp'::character varying)::text, ('telegram'::character varying)::text, ('visit'::character varying)::text, ('task'::character varying)::text, ('status_change'::character varying)::text, ('assignment_change'::character varying)::text]))),
    CONSTRAINT contact_interactions_outcome_check CHECK (((outcome)::text = ANY (ARRAY[('answered'::character varying)::text, ('missed'::character varying)::text, ('voicemail'::character varying)::text, ('busy'::character varying)::text, ('callback_requested'::character varying)::text, ('successful'::character varying)::text, ('follow_up_needed'::character varying)::text, ('no_answer'::character varying)::text, ('completed'::character varying)::text, (NULL::character varying)::text])))
);


