    CONSTRAINT contacts_contact_type_check CHECK (((contact_type)::text = ANY (ARRAY[('lead'::character varying)::text, ('prospect'::character varying)::text, ('wholesale_lead'::character varying)::text, ('retail_lead'::character varying)::text, ('partner_lead'::character varying)::text, ('existing_contact'::character varying)::text]))),
    CONSTRAINT contacts_lead_score_check CHECK (((lead_score >= 0) AND (lead_score <= 100))),
    CONSTRAINT contacts_lifecycle_stage_check CHECK ((lifecycle_stage = ANY (ARRAY[('new'::character varying)::text, ('contacted'::character varying)::text, ('interested'::character varying)::text, ('qualified'::character varying)::text, ('negotiation'::character varying)::text, ('converted'::character varying)::text, ('lost'::character varying)::text, ('archived'::character varying)::text]))),
    CONSTRAINT contacts_priority_check CHECK (((priority)::text = ANY (ARRAY[('low'::character varying)::text, ('medium'::character varying)::text, ('high'::character varying)::text, ('urgent'::character varying)::text]))),
    CONSTRAINT contacts_source_check CHECK ((source = ANY (ARRAY[('phone_inbound'::character varying)::text, ('phone_outbound'::character varying)::text, ('google_ads'::character varying)::text, ('facebook_ads'::character varying)::text, ('instagram_ads'::character varying)::text, ('website'::character varying)::text, ('telegram'::character varying)::text, ('online_store'::character varying)::text, ('referral'::character varying)::text, ('walk_in'::character varying)::text, ('exhibition'::character varying)::text, ('whatsapp'::character varying)::text, ('email_campaign'::character varying)::text, ('manual'::character varying)::text]))),
    CONSTRAINT contacts_status_check CHECK ((status = ANY (ARRAY[('active'::character varying)::text, ('inactive'::character varying)::text, ('converted'::character varying)::text, ('archived'::character varying)::text, ('blacklisted'::character varying)::text])))
);

