--
-- Name: COLUMN fabric_materials.current_stock; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fabric_materials.current_stock IS 'الكمية الإجمالية بالمتر (سائب + مجرود). loose_stock = current_stock - SUM(rolls)';


