    line_number integer DEFAULT 1,
    account_id uuid NOT NULL,
    debit numeric(15,2) DEFAULT 0,
    credit numeric(15,2) DEFAULT 0,
    currency character varying(3),
    exchange_rate numeric(18,8) DEFAULT 1,
    debit_fc numeric(15,2) DEFAULT 0,
    credit_fc numeric(15,2) DEFAULT 0,
    description text,
    cost_center_id uuid,
    party_type character varying(20),
    party_id uuid,
    reference_type character varying(50),
    reference_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    marker_color character varying(20) DEFAULT NULL::character varying,
    marked_at timestamp with time zone,
    marked_by uuid,
    updated_at timestamp with time zone,
    is_fund_line boolean,
    CONSTRAINT chk_debit_or_credit CHECK ((((debit > (0)::numeric) AND (credit = (0)::numeric)) OR ((debit = (0)::numeric) AND (credit > (0)::numeric)) OR ((debit = (0)::numeric) AND (credit = (0)::numeric))))
);

ALTER TABLE ONLY public.journal_entry_lines REPLICA IDENTITY FULL;


