    coa.account_code,
    coa.name_ar,
    coa.name_en,
    at.code AS account_type_code,
    sum(jel.debit) AS total_debit,
    sum(jel.credit) AS total_credit,
    (sum(jel.debit) - sum(jel.credit)) AS balance,
    count(*) AS entry_count,
    max(je.entry_date) AS last_entry_date
   FROM (((public.journal_entry_lines jel
     JOIN public.journal_entries je ON ((jel.entry_id = je.id)))
     JOIN public.chart_of_accounts coa ON ((jel.account_id = coa.id)))
     LEFT JOIN public.account_types at ON ((coa.account_type_id = at.id)))
  WHERE ((je.status)::text = 'posted'::text)
  GROUP BY je.company_id, je.tenant_id, jel.account_id, coa.account_code, coa.name_ar, coa.name_en, at.code
  WITH NO DATA;


--
-- Name: mv_inventory_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_inventory_summary AS
 SELECT im.company_id,
    im.tenant_id,
    im.product_id,
    im.material_id,
    im.to_warehouse_id AS warehouse_id,
    sum(
        CASE
            WHEN ((im.movement_type)::text = ANY (ARRAY[('IN'::character varying)::text, ('PURCHASE'::character varying)::text, ('RETURN_IN'::character varying)::text, ('ADJUSTMENT_IN'::character varying)::text, ('TRANSFER_IN'::character varying)::text])) THEN im.quantity
            ELSE (0)::numeric
        END) AS total_in,
    sum(
        CASE
            WHEN ((im.movement_type)::text = ANY (ARRAY[('OUT'::character varying)::text, ('SALE'::character varying)::text, ('RETURN_OUT'::character varying)::text, ('ADJUSTMENT_OUT'::character varying)::text, ('TRANSFER_OUT'::character varying)::text])) THEN im.quantity
            ELSE (0)::numeric
        END) AS total_out,
    sum(
        CASE
            WHEN ((im.movement_type)::text = ANY (ARRAY[('IN'::character varying)::text, ('PURCHASE'::character varying)::text, ('RETURN_IN'::character varying)::text, ('ADJUSTMENT_IN'::character varying)::text, ('TRANSFER_IN'::character varying)::text])) THEN im.quantity
            ELSE (- im.quantity)
        END) AS balance,
    max(im.movement_date) AS last_movement
   FROM public.inventory_movements im
  GROUP BY im.company_id, im.tenant_id, im.product_id, im.material_id, im.to_warehouse_id
  WITH NO DATA;


--
-- Name: sales_invoices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.sales_invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    company_id uuid NOT NULL,
    branch_id uuid,
    invoice_number character varying(50) NOT NULL,
    invoice_date date DEFAULT CURRENT_DATE NOT NULL,
    invoice_type character varying(20) DEFAULT 'invoice'::character varying,
    order_id uuid,
    customer_id uuid NOT NULL,
    customer_name character varying(200),
    customer_tax_number character varying(100),
    billing_address text,
    shipping_address text,
    currency character varying(3) DEFAULT 'USD'::character varying,
    exchange_rate numeric(18,8) DEFAULT 1,
    subtotal numeric(15,2) DEFAULT 0,
    discount_type character varying(20) DEFAULT 'fixed'::character varying,
    discount_value numeric(15,2) DEFAULT 0,
    discount_amount numeric(15,2) DEFAULT 0,
    taxable_amount numeric(15,2) DEFAULT 0,
    tax_amount numeric(15,2) DEFAULT 0,
    shipping_amount numeric(15,2) DEFAULT 0,
    total_amount numeric(15,2) DEFAULT 0,
    paid_amount numeric(15,2) DEFAULT 0,
    balance_due numeric(15,2) GENERATED ALWAYS AS ((total_amount - paid_amount)) STORED,
    payment_terms_days integer DEFAULT 0,
    due_date date,
    status character varying(20) DEFAULT 'draft'::character varying,
    payment_status character varying(20) DEFAULT 'unpaid'::character varying,
    journal_entry_id uuid,
    is_posted boolean DEFAULT false,
    posted_at timestamp with time zone,
    terms text,
    notes text,
    internal_notes text,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    cancel_reason text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    expenses jsonb DEFAULT '[]'::jsonb,
    expenses_total numeric(18,2) DEFAULT 0,
    attachments jsonb DEFAULT '[]'::jsonb,
    salesperson_id uuid,
    discount_percent numeric(5,2) DEFAULT 0,
    price_list_id uuid,
    confirmation_status text DEFAULT 'draft'::text,
    confirmed_at timestamp with time zone,
    confirmed_by uuid,
    approval_status text DEFAULT 'none'::text,
    approved_by uuid,
    approved_at timestamp with time zone,
    approval_notes text,
    delivery_note_id uuid,
    delivery_method character varying(30) DEFAULT 'store_pickup'::character varying,
    shipping_address_id uuid,
    shipping_recipient character varying(200),
    shipping_phone character varying(50),
    shipping_carrier character varying(50),
    tracking_number character varying(100),
    shipping_cost numeric(12,2) DEFAULT 0,
    delivery_notes text,
    payment_required boolean DEFAULT false,
    payment_confirmed boolean DEFAULT false,
    payment_schedule_id uuid,
    document_stage character varying(20) DEFAULT 'invoice'::character varying,
    order_number character varying(50),
    order_date date,
    expected_delivery_date date,
    delivery_status character varying(20) DEFAULT 'pending'::character varying,
    warehouse_id uuid,
    CONSTRAINT sales_invoices_status_check CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('saved'::character varying)::text, ('pending'::character varying)::text, ('approved'::character varying)::text, ('confirmed'::character varying)::text, ('in_progress'::character varying)::text, ('completed'::character varying)::text, ('cancelled'::character varying)::text, ('rejected'::character varying)::text, ('posted'::character varying)::text, ('paid'::character varying)::text, ('partially_paid'::character varying)::text, ('overdue'::character varying)::text, ('closed'::character varying)::text])))
);


--
-- Name: TABLE sales_invoices; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sales_invoices IS '⛔ DEPRECATED [2026-02-15] — مُؤرشف. البديل: sales_transactions (stage=invoice/posted/paid). لا تستخدم في الكود الجديد.';


--
-- Name: COLUMN sales_invoices.salesperson_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_invoices.salesperson_id IS 'معرف المندوب / Sales person ID';


--
-- Name: COLUMN sales_invoices.discount_percent; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_invoices.discount_percent IS 'نسبة الخصم الموروثة من ملف العميل / Customer profile discount %';


--
-- Name: COLUMN sales_invoices.price_list_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_invoices.price_list_id IS 'قائمة الأسعار المستخدمة / Price list used for this document';


--
-- Name: COLUMN sales_invoices.document_stage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_invoices.document_stage IS 'مرحلة المستند: request=طلب, quotation=عرض سعر, order=أمر بيع, invoice=فاتورة';


--
-- Name: mv_monthly_sales; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_monthly_sales AS
 SELECT sales_invoices.company_id,
    sales_invoices.tenant_id,
    date_trunc('month'::text, (sales_invoices.invoice_date)::timestamp with time zone) AS month,
    sales_invoices.currency,
    count(*) AS invoice_count,
    sum(sales_invoices.total_amount) AS total_amount,
    sum(COALESCE(sales_invoices.tax_amount, (0)::numeric)) AS total_tax,
    (sum(sales_invoices.total_amount) - sum(COALESCE(sales_invoices.tax_amount, (0)::numeric))) AS total_net
   FROM public.sales_invoices
  WHERE ((sales_invoices.status)::text <> ALL (ARRAY[('cancelled'::character varying)::text, ('draft'::character varying)::text]))
  GROUP BY sales_invoices.company_id, sales_invoices.tenant_id, (date_trunc('month'::text, (sales_invoices.invoice_date)::timestamp with time zone)), sales_invoices.currency
  WITH NO DATA;


