    discount_percent numeric DEFAULT 0,
    sales_agent_id uuid
);

ALTER TABLE ONLY public.suppliers REPLICA IDENTITY FULL;


--
-- Name: parties; Type: VIEW; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.parties AS
 SELECT customers.id,
    customers.company_id,
    customers.tenant_id,
    customers.name_ar AS name,
    'customer'::text AS party_type
   FROM public.customers
UNION ALL
 SELECT suppliers.id,
    suppliers.company_id,
    suppliers.tenant_id,
    suppliers.name_ar AS name,
    'supplier'::text AS party_type
   FROM public.suppliers;


