    rated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT performance_ratings_dimension_check CHECK ((dimension = ANY (ARRAY['response_speed'::text, 'pricing'::text, 'commitment'::text, 'quality'::text, 'returns'::text, 'overall'::text]))),
    CONSTRAINT performance_ratings_score_check CHECK (((score >= (0)::numeric) AND (score <= (5)::numeric))),
    CONSTRAINT performance_ratings_source_check CHECK ((source = ANY (ARRAY['auto'::text, 'manual'::text, 'system'::text]))),
    CONSTRAINT performance_ratings_subject_type_check CHECK ((subject_type = ANY (ARRAY['supplier'::text, 'customer'::text])))
);


--
-- Name: performance_scores; Type: VIEW; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.performance_scores AS
 SELECT performance_ratings.subject_type,
    performance_ratings.subject_id,
    performance_ratings.dimension,
    round((sum((performance_ratings.score * performance_ratings.weight)) / NULLIF(sum(performance_ratings.weight), (0)::numeric)), 2) AS avg_score,
    count(*) AS samples
   FROM public.performance_ratings
  GROUP BY performance_ratings.subject_type, performance_ratings.subject_id, performance_ratings.dimension;


